/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2020_SEED = {"dse/writing/part-b/2020/Q2":[{"front":"more than a backdrop","meaning":"不只是背景","examples":[{"en":"Hong Kong’s public housing estates are more than a backdrop for photographs.","zh":"香港的公共屋邨不只是相片背景。"},{"en":"More than a backdrop means something has deeper meaning and is not only a background scene.","zh":"more than a backdrop 指某事物有更深意義，不只是背景景物。"},{"en":"A school is more than a backdrop for exam results; it is where students grow and make friends.","zh":"學校不只是考試成績的背景；它也是學生成長和交朋友的地方。"},{"en":"When visitors treat a neighbourhood only as scenery, they may forget it is more than a backdrop.","zh":"當訪客只把社區當成景物時，他們可能忘記它不只是背景。"},{"en":"Public housing estates are more than a backdrop because real families live, work, and rest there.","zh":"公共屋邨不只是背景，因為真實家庭在那裏生活、工作和休息。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"for better or worse","meaning":"不論好壞；無論利弊","examples":[{"en":"For better or worse, social media has changed the way public housing estates are seen.","zh":"不論好壞，社交媒體已改變公共屋邨被看待的方式。"},{"en":"For better or worse means whether the result is good, bad, or mixed.","zh":"for better or worse 指不論結果是好、壞，還是好壞參半。"},{"en":"For better or worse, online learning has become part of many students’ daily lives.","zh":"不論好壞，網上學習已成為許多學生日常生活的一部分。"},{"en":"People use this phrase when a change has benefits but also possible problems.","zh":"當一個改變有好處但也可能有問題時，人們會使用這個短語。"},{"en":"For better or worse, smartphones have changed how people communicate, shop, and remember events.","zh":"不論好壞，智能手機已改變人們溝通、購物和記錄事件的方式。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"social media","meaning":"社交媒體","examples":[{"en":"Social media has changed the way Hong Kong’s public housing estates are seen.","zh":"社交媒體已改變香港公共屋邨被看待的方式。"},{"en":"Social media refers to online platforms where people share posts, photos, videos, and opinions.","zh":"social media 指人們分享帖文、相片、影片和意見的網上平台。"},{"en":"Students may use social media to share school events or ask classmates for help.","zh":"學生可能使用社交媒體分享學校活動，或向同學求助。"},{"en":"Social media can make a place famous quickly because photos spread from person to person.","zh":"社交媒體可以令一個地方很快成名，因為相片會在人與人之間傳播。"},{"en":"Social media connects people, but it can also create pressure to perform for attention.","zh":"社交媒體能連繫人，但也可能製造為了吸引注意而表演的壓力。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"change the way something is seen","meaning":"改變……被看待的方式","examples":[{"en":"Instagram has changed the way public housing estates are seen.","zh":"Instagram 已改變公共屋邨被看待的方式。"},{"en":"To change the way something is seen means to change how people understand, judge, or imagine it.","zh":"change the way something is seen 指改變人們理解、判斷或想像某事物的方式。"},{"en":"A documentary can change the way homelessness is seen by showing real people’s stories.","zh":"紀錄片可以透過展示真實人物故事，改變無家者被看待的方式。"},{"en":"Photos online can change the way a neighbourhood is seen, even by people who have never visited it.","zh":"網上相片可以改變一個社區被看待的方式，即使觀看者從未到訪。"},{"en":"Changing the way something is seen can bring respect, but it can also create misunderstanding.","zh":"改變某事物被看待的方式可以帶來尊重，但也可能造成誤解。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"public housing estates","meaning":"公共屋邨","examples":[{"en":"Hong Kong’s public housing estates have become popular photo spots.","zh":"香港的公共屋邨已成為熱門拍照地點。"},{"en":"Public housing estates are large groups of homes provided or supported by the government for residents.","zh":"public housing estates 指由政府提供或資助、讓居民居住的大型住宅群。"},{"en":"Many families live in public housing estates because private housing is too expensive.","zh":"許多家庭住在公共屋邨，因為私人樓宇太昂貴。"},{"en":"Public housing estates include flats, playgrounds, shops, open spaces, and daily community life.","zh":"公共屋邨包括單位、遊樂場、商店、公共空間和日常社區生活。"},{"en":"A public housing estate should be respected as a home, not treated only as a tourist scene.","zh":"公共屋邨應被尊重為家，而不應只被當成旅遊景物。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"once simply homes for","meaning":"曾經只是……的家","examples":[{"en":"Public housing estates were once simply homes for ordinary families.","zh":"公共屋邨曾經只是普通家庭的家。"},{"en":"Once simply homes for means they used to be seen only as places where people lived.","zh":"once simply homes for 指它們過去只被視為人們居住的地方。"},{"en":"A quiet village was once simply home for farmers before tourists began visiting it.","zh":"一條安靜村莊在遊客到訪前，曾經只是農民的家。"},{"en":"When a place becomes famous online, what was once simply home for residents may become a public attraction.","zh":"當一個地方在網上成名，曾經只是居民的家，可能變成公共景點。"},{"en":"The phrase shows a change from ordinary daily life to wider public attention.","zh":"這個短語顯示由普通日常生活轉變為受到公眾關注。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"ordinary families","meaning":"普通家庭","examples":[{"en":"Public housing estates were built as homes for ordinary families.","zh":"公共屋邨是為普通家庭建造的住所。"},{"en":"Ordinary families are normal families who live everyday lives without special wealth or fame.","zh":"ordinary families 指過着日常生活、沒有特別財富或名氣的一般家庭。"},{"en":"Ordinary families may worry about school fees, rent, food prices, and work schedules.","zh":"普通家庭可能擔心學費、租金、食物價格和工作時間表。"},{"en":"Public services are important because ordinary families depend on them every day.","zh":"公共服務很重要，因為普通家庭每天都依賴它們。"},{"en":"Calling families ordinary does not make them unimportant; it shows they represent real community life.","zh":"稱家庭為普通並不代表他們不重要；而是顯示他們代表真實社區生活。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"colourful backdrops","meaning":"色彩繽紛的背景","examples":[{"en":"The estates have become colourful backdrops for online self-expression.","zh":"這些屋邨已成為網上自我表達的色彩繽紛背景。"},{"en":"Colourful backdrops are bright and attractive backgrounds used in photos or videos.","zh":"colourful backdrops 指相片或影片中明亮而吸引的背景。"},{"en":"A painted wall at school can become a colourful backdrop for graduation photos.","zh":"學校一幅彩繪牆可以成為畢業相的色彩繽紛背景。"},{"en":"Colourful backdrops attract attention online because they make ordinary pictures look lively.","zh":"色彩繽紛的背景能在網上吸引注意，因為它令普通相片變得生動。"},{"en":"A colourful backdrop may look beautiful, but people should remember what lies behind it.","zh":"色彩繽紛的背景可能很美，但人們應記得背後有甚麼。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"online self-expression","meaning":"網上自我表達","examples":[{"en":"Young people use Instagram for online self-expression.","zh":"年輕人使用 Instagram 進行網上自我表達。"},{"en":"Online self-expression means showing one’s identity, mood, taste, or ideas through the internet.","zh":"online self-expression 指透過互聯網展示自己的身份、心情、品味或想法。"},{"en":"A teenager may use clothes, captions, and photos for online self-expression.","zh":"青少年可能用衣着、文字說明和相片進行網上自我表達。"},{"en":"Online self-expression can build confidence, but it may also create pressure to look perfect.","zh":"網上自我表達可以建立信心，但也可能製造看起來完美的壓力。"},{"en":"Social media turns many public places into spaces for online self-expression.","zh":"社交媒體把許多公共地方變成網上自我表達的空間。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"class assignment","meaning":"課堂習作","examples":[{"en":"For his class assignment, the writer visited Choi Hung Estate.","zh":"為了他的課堂習作，作者到訪彩虹邨。"},{"en":"A class assignment is a piece of schoolwork given by a teacher.","zh":"class assignment 指老師安排給學生完成的課業。"},{"en":"A student may interview residents for a class assignment about community life.","zh":"學生可能為一份關於社區生活的課堂習作訪問居民。"},{"en":"Class assignments help students practise research, writing, and observation.","zh":"課堂習作幫助學生練習研究、寫作和觀察。"},{"en":"A good class assignment should teach students how to think, not only how to collect facts.","zh":"好的課堂習作應教學生如何思考，而不只是收集資料。"}],"source":"2020 Q2.pdf","sourcePage":1},{"front":"top ten photo spots","meaning":"十大打卡熱點","examples":[{"en":"Choi Hung Estate is often treated as one of Hong Kong’s top ten photo spots.","zh":"彩虹邨常被視為香港十大打卡熱點之一。"},{"en":"Top ten photo spots are places commonly ranked as especially popular for taking pictures.","zh":"top ten photo spots 指常被列為特別受歡迎拍照地點的地方。"},{"en":"Tourists may search for top ten photo spots before visiting a new city.","zh":"遊客到訪新城市前，可能會搜尋十大打卡熱點。"},{"en":"A place becomes a top photo spot when many people share similar attractive images of it.","zh":"當許多人分享某地相似而吸引的相片時，它就會成為熱門拍照地點。"},{"en":"Being a top ten photo spot can bring attention, but also crowds and disturbance.","zh":"成為十大打卡熱點可以帶來關注，但也可能帶來人群和滋擾。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"interviewed Instagrammers and residents","meaning":"訪問 Instagram 用戶和居民","examples":[{"en":"The writer interviewed Instagrammers and residents at Choi Hung Estate.","zh":"作者在彩虹邨訪問 Instagram 用戶和居民。"},{"en":"Interviewed Instagrammers and residents means asked both photo-taking visitors and people who live there for their views.","zh":"interviewed Instagrammers and residents 指詢問拍照訪客和當地居民的看法。"},{"en":"A student may interview shop owners and customers to understand a market more fully.","zh":"學生可以訪問店主和顧客，以更全面理解一個市場。"},{"en":"Interviewing different groups helps show that one place can mean different things to different people.","zh":"訪問不同群體有助顯示同一個地方對不同人有不同意義。"},{"en":"By interviewing Instagrammers and residents, the writer could compare excitement with daily inconvenience.","zh":"透過訪問 Instagram 用戶和居民，作者能比較興奮感與日常不便。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"what draws young people there","meaning":"是甚麼吸引年輕人到那裏","examples":[{"en":"The writer wanted to understand what draws young people there.","zh":"作者想了解是甚麼吸引年輕人到那裏。"},{"en":"What draws young people there means what attracts young people to that place.","zh":"what draws young people there 指甚麼吸引年輕人前往該地方。"},{"en":"A teacher may ask what draws students to a new reading club.","zh":"老師可能會問是甚麼吸引學生參加新的閱讀會。"},{"en":"Bright colours, easy transport, and online fame can draw young people to a photo spot.","zh":"鮮明色彩、方便交通和網上名氣都可以吸引年輕人到打卡地點。"},{"en":"Understanding what draws people somewhere helps explain their choices and behaviour.","zh":"了解是甚麼吸引人到某地，有助解釋他們的選擇和行為。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"what this attention means to","meaning":"這種關注對……有甚麼意義","examples":[{"en":"He wanted to know what this attention means to residents.","zh":"他想知道這種關注對居民有甚麼意義。"},{"en":"What this attention means to someone asks how public interest affects or feels to that person.","zh":"what this attention means to someone 是問公眾關注如何影響某人，或對某人有何感受。"},{"en":"A school may ask what media attention means to students after a competition win.","zh":"學校在比賽勝出後，可能會問媒體關注對學生有甚麼意義。"},{"en":"Attention can mean pride to some people but pressure to others.","zh":"關注對一些人可能代表自豪，但對另一些人可能代表壓力。"},{"en":"Asking what attention means to residents helps us see beyond the visitor’s point of view.","zh":"問這種關注對居民有甚麼意義，能幫助我們看見訪客角度以外的事情。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"visual beauty","meaning":"視覺美感","examples":[{"en":"Instagrammers are attracted by the visual beauty of the estate.","zh":"Instagram 用戶被屋邨的視覺美感吸引。"},{"en":"Visual beauty means beauty that can be seen through colour, shape, pattern, light, or space.","zh":"visual beauty 指透過色彩、形狀、圖案、光線或空間看見的美。"},{"en":"A garden has visual beauty when flowers, paths, and trees create a pleasing scene.","zh":"當花朵、小路和樹木形成悅目的景象時，花園就有視覺美感。"},{"en":"Visual beauty attracts photographers because it makes images clear and memorable.","zh":"視覺美感吸引攝影者，因為它令影像清楚而難忘。"},{"en":"Visual beauty can make people notice places they once ignored.","zh":"視覺美感可以令人注意到他們曾經忽略的地方。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"local identity","meaning":"本地身份；地方認同","examples":[{"en":"Public housing estates can express a strong sense of local identity.","zh":"公共屋邨可以表達強烈的本地身份感。"},{"en":"Local identity is the feeling, character, and culture that make a place recognisably itself.","zh":"local identity 指令一個地方清楚有自己特色的感覺、性格和文化。"},{"en":"Street food, dialects, festivals, and old buildings can all show local identity.","zh":"街頭小食、方言、節日和舊建築都可以展示本地身份。"},{"en":"Local identity becomes stronger when people understand the stories behind familiar places.","zh":"當人們理解熟悉地方背後的故事時，本地身份感會更強。"},{"en":"A place loses local identity when it looks and feels exactly like everywhere else.","zh":"當一個地方看起來和感覺都與其他地方完全一樣時，它就會失去本地身份。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"both pride and unease","meaning":"既自豪又不安","examples":[{"en":"Residents feel both pride and unease about Instagram tourism.","zh":"居民對 Instagram 打卡旅遊既自豪又不安。"},{"en":"Both pride and unease means people feel pleased but also worried or uncomfortable.","zh":"both pride and unease 指人們既感到高興自豪，也感到擔心或不舒服。"},{"en":"A student may feel both pride and unease after becoming suddenly famous online.","zh":"學生在網上突然成名後，可能既自豪又不安。"},{"en":"Residents may feel pride when their estate is admired, but unease when strangers disturb them.","zh":"當屋邨受到欣賞時，居民可能自豪；但陌生人造成滋擾時，他們會不安。"},{"en":"Mixed situations often create both pride and unease because benefits and problems arrive together.","zh":"複雜情況常令人既自豪又不安，因為好處和問題同時出現。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"the first attraction","meaning":"第一個吸引之處","examples":[{"en":"The first attraction is the striking appearance of the estates.","zh":"第一個吸引之處是屋邨醒目的外觀。"},{"en":"The first attraction means the first reason something catches people’s interest.","zh":"the first attraction 指某事物首先吸引人興趣的原因。"},{"en":"The first attraction of a library may be its quiet study space.","zh":"圖書館第一個吸引之處可能是安靜的自修空間。"},{"en":"For many visitors, the first attraction of Choi Hung Estate is its colour.","zh":"對許多訪客而言，彩虹邨第一個吸引之處是它的色彩。"},{"en":"The first attraction may bring people in, but deeper understanding comes later.","zh":"第一個吸引之處可能把人吸引過來，但更深入的理解會在之後出現。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"striking appearance","meaning":"醒目的外觀","examples":[{"en":"Choi Hung Estate is popular because of its striking appearance.","zh":"彩虹邨因其醒目的外觀而受歡迎。"},{"en":"A striking appearance is an appearance that is unusual, strong, or easy to notice.","zh":"striking appearance 指不尋常、強烈或容易被注意到的外觀。"},{"en":"A bright red bridge has a striking appearance against a grey sky.","zh":"一條鮮紅色橋在灰色天空下有醒目的外觀。"},{"en":"Buildings with striking appearances often become popular in photographs.","zh":"外觀醒目的建築常在相片中變得受歡迎。"},{"en":"A striking appearance can attract attention before people understand the place’s real purpose.","zh":"醒目的外觀可以在人們理解該地方真正用途前先吸引注意。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"not merely","meaning":"不僅僅是","examples":[{"en":"Choi Hung Estate is not merely a group of residential blocks.","zh":"彩虹邨不僅僅是一組住宅大廈。"},{"en":"Not merely means not only or not simply.","zh":"not merely 指不只是或不單單是。"},{"en":"A meal is not merely food; it can also carry family memory.","zh":"一頓飯不僅僅是食物；它也可以承載家庭記憶。"},{"en":"People use not merely when they want to show that something has extra importance.","zh":"當人們想顯示某事物有額外重要性時，會使用 not merely。"},{"en":"A housing estate is not merely concrete and walls; it is also a living community.","zh":"屋邨不僅僅是石屎和牆壁；它也是一個仍有人生活的社區。"}],"source":"2020 Q2.pdf","sourcePage":2},{"front":"residential blocks","meaning":"住宅大廈","examples":[{"en":"Choi Hung Estate is made up of several residential blocks.","zh":"彩虹邨由幾座住宅大廈組成。"},{"en":"Residential blocks are large buildings divided into homes or flats where people live.","zh":"residential blocks 指分成多個住所或單位、讓人居住的大型建築物。"},{"en":"Many residential blocks have lifts, staircases, corridors, and shared entrances.","zh":"許多住宅大廈有升降機、樓梯、走廊和共用入口。"},{"en":"Residential blocks create a sense of community when neighbours meet in common spaces.","zh":"當鄰居在公共空間相遇時，住宅大廈會形成社區感。"},{"en":"Visitors should remember that residential blocks are private living spaces, not only photo backgrounds.","zh":"訪客應記得住宅大廈是私人生活空間，不只是拍照背景。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"collectively","meaning":"整體來說","examples":[{"en":"Collectively, the buildings form a recognisable composition.","zh":"整體來說，這些建築形成一個容易辨認的構圖。"},{"en":"Collectively means when things are considered together as a group.","zh":"collectively 指把多個事物作為一個整體來看。"},{"en":"Collectively, the students’ small efforts made the charity event successful.","zh":"整體來說，學生們的小努力令慈善活動成功。"},{"en":"One building may look ordinary alone, but collectively the blocks create a strong pattern.","zh":"一座建築單獨看可能普通，但整體來說，這些大廈形成強烈圖案。"},{"en":"This word helps show that the whole group has an effect greater than each single part.","zh":"這個詞幫助顯示整體效果比每個單一部分更強。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"instantly recognisable","meaning":"一眼就能認出的","examples":[{"en":"The estate is instantly recognisable because of its colourful walls.","zh":"這個屋邨因其色彩繽紛的外牆而一眼就能認出。"},{"en":"Instantly recognisable means easy to identify immediately.","zh":"instantly recognisable 指可以立即被辨認出來。"},{"en":"A school uniform can make students instantly recognisable on a trip.","zh":"校服可以令學生在旅行時一眼就能被認出。"},{"en":"Famous buildings become instantly recognisable when their shapes or colours are very distinctive.","zh":"當著名建築的形狀或顏色很有特色時，它們會一眼就能被認出。"},{"en":"Choi Hung Estate is instantly recognisable because people remember its rainbow-like colours.","zh":"彩虹邨一眼就能被認出，因為人們記得它像彩虹一樣的顏色。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"composition of colour, lines and space","meaning":"色彩、線條與空間的構圖","examples":[{"en":"The estate forms a composition of colour, lines and space.","zh":"這個屋邨形成色彩、線條與空間的構圖。"},{"en":"A composition of colour, lines and space means a visual arrangement made from these elements.","zh":"composition of colour, lines and space 指由這些元素組成的視覺安排。"},{"en":"A painting uses a composition of colour, lines and space to guide the viewer’s eyes.","zh":"一幅畫會使用色彩、線條與空間的構圖來引導觀眾視線。"},{"en":"Photographers like clear compositions because they make pictures feel balanced.","zh":"攝影者喜歡清晰構圖，因為它令相片感覺平衡。"},{"en":"In Choi Hung Estate, walls, corridors, and open areas work together as one composition.","zh":"在彩虹邨，外牆、走廊和公共空間共同形成一個構圖。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"rainbow-painted walls","meaning":"彩虹色外牆","examples":[{"en":"The rainbow-painted walls are one reason Choi Hung Estate is popular.","zh":"彩虹色外牆是彩虹邨受歡迎的原因之一。"},{"en":"Rainbow-painted walls are walls painted in several bright colours like a rainbow.","zh":"rainbow-painted walls 指塗上多種像彩虹般鮮明顏色的牆身。"},{"en":"Children may enjoy rainbow-painted walls because the colours feel cheerful and playful.","zh":"孩子可能喜歡彩虹色外牆，因為顏色令人感到開朗和有趣。"},{"en":"Rainbow-painted walls make photos stand out because the background already looks lively.","zh":"彩虹色外牆令相片突出，因為背景本身已很生動。"},{"en":"These walls are attractive, but they are still part of people’s homes.","zh":"這些外牆很吸引，但它們仍是人們家園的一部分。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"basketball court","meaning":"籃球場","examples":[{"en":"The basketball court creates a strong visual focus.","zh":"籃球場形成強烈的視覺焦點。"},{"en":"A basketball court is a marked area where people play basketball.","zh":"basketball court 指劃有場地線、供人打籃球的地方。"},{"en":"A school basketball court may become a meeting place after lessons.","zh":"學校籃球場放學後可能成為學生聚集的地方。"},{"en":"In photos, the lines of a basketball court can guide the viewer’s eyes.","zh":"在相片中，籃球場的線條可以引導觀眾視線。"},{"en":"A basketball court is for exercise and play first, even if visitors use it for photos.","zh":"籃球場首先是運動和玩樂的地方，即使訪客也會用它拍照。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"long corridors","meaning":"長長的走廊","examples":[{"en":"The long corridors add lines and depth to the photographs.","zh":"長長的走廊為相片增加線條和深度。"},{"en":"Long corridors are extended passageways that connect rooms, flats, or parts of a building.","zh":"long corridors 指連接房間、單位或建築不同部分的長通道。"},{"en":"A hospital’s long corridors can make visitors feel the building is large and busy.","zh":"醫院長長的走廊會令訪客感到建築很大很繁忙。"},{"en":"Long corridors create depth in photos because the lines seem to stretch into the distance.","zh":"長長的走廊能在相片中創造深度，因為線條像延伸到遠方。"},{"en":"In housing estates, long corridors are daily routes for residents, not just visual patterns.","zh":"在屋邨中，長長的走廊是居民的日常路線，不只是視覺圖案。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"symmetrical background","meaning":"對稱的背景","examples":[{"en":"The buildings create a symmetrical background for photos.","zh":"這些建築為相片創造對稱的背景。"},{"en":"A symmetrical background has two sides that look balanced or similar.","zh":"symmetrical background 指兩邊看起來平衡或相似的背景。"},{"en":"A classroom wall with windows arranged evenly can create a symmetrical background.","zh":"課室牆上的窗戶排列整齊，可以形成對稱的背景。"},{"en":"Symmetrical backgrounds often make photos feel tidy, calm, and carefully arranged.","zh":"對稱的背景常令相片感覺整齊、平靜和經過細心安排。"},{"en":"A symmetrical background can be attractive because the viewer’s eyes understand it quickly.","zh":"對稱背景吸引人，因為觀眾的眼睛能很快理解它。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"work naturally on a phone screen","meaning":"在手機屏幕上自然好看","examples":[{"en":"The scene works naturally on a phone screen.","zh":"這個景象在手機屏幕上自然好看。"},{"en":"To work naturally on a phone screen means to look clear and attractive when viewed on a mobile phone.","zh":"work naturally on a phone screen 指在手機上觀看時清楚而吸引。"},{"en":"A simple poster works naturally on a phone screen because the words are easy to read.","zh":"簡潔海報在手機屏幕上自然好看，因為文字容易閱讀。"},{"en":"Bright colours and strong lines work naturally on a phone screen because small images still look clear.","zh":"鮮明色彩和強烈線條在手機屏幕上自然好看，因為小圖仍然清楚。"},{"en":"Many Instagram photos succeed because their scenes work naturally on a phone screen.","zh":"許多 Instagram 相片成功，是因為它們的場景在手機屏幕上自然好看。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"every corner already looks edited","meaning":"每個角落都像已修圖一樣","examples":[{"en":"One student said that every corner already looks edited.","zh":"一名學生說，每個角落都像已修圖一樣。"},{"en":"Every corner already looks edited means the place looks neat, colourful, or polished even before filters are added.","zh":"every corner already looks edited 指一個地方即使未加濾鏡，也已看起來整齊、繽紛或精緻。"},{"en":"A café with perfect lighting may make every corner already look edited.","zh":"一間光線完美的咖啡店，可能令每個角落都像已修圖一樣。"},{"en":"People say this when a real place looks as attractive as a finished photo.","zh":"當真實地方看起來像完成品相片一樣吸引時，人們會這樣說。"},{"en":"If every corner already looks edited, visitors need less effort to create eye-catching images.","zh":"如果每個角落都像已修圖一樣，訪客便較少需要努力去拍出吸睛相片。"}],"source":"2020 Q2.pdf","sourcePage":3},{"front":"little, if any, effort","meaning":"幾乎不需要任何努力","examples":[{"en":"Little, if any, effort is needed to make the photos attractive.","zh":"要令相片吸引，幾乎不需要任何努力。"},{"en":"Little, if any, effort means almost no effort, or possibly none at all.","zh":"little, if any, effort 指幾乎不用努力，甚至可能完全不用。"},{"en":"With clear instructions, little, if any, effort is needed to set up the app.","zh":"有清晰指示時，設定應用程式幾乎不需要任何努力。"},{"en":"A beautiful location may require little, if any, effort to photograph well.","zh":"漂亮地點可能幾乎不需要任何努力就能拍得好看。"},{"en":"This phrase emphasises that something is very easy to achieve.","zh":"這個短語強調某件事非常容易做到。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"make the photos attractive","meaning":"令相片吸引","examples":[{"en":"The colours and lines make the photos attractive.","zh":"色彩和線條令相片吸引。"},{"en":"To make the photos attractive means to help the pictures look interesting, pleasant, or eye-catching.","zh":"make the photos attractive 指令相片看起來有趣、悅目或吸引目光。"},{"en":"Good lighting can make the photos attractive even when the subject is simple.","zh":"良好光線即使在主題簡單時，也能令相片吸引。"},{"en":"Bright backgrounds make photos attractive because they stand out in a busy social media feed.","zh":"鮮明背景令相片吸引，因為它們能在繁忙的社交媒體版面中突出。"},{"en":"Making photos attractive should not come at the cost of disturbing other people.","zh":"令相片吸引不應以滋擾他人為代價。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"rooftop court","meaning":"天台球場","examples":[{"en":"The rooftop court is one of the most popular places for photos.","zh":"天台球場是最受歡迎的拍照地點之一。"},{"en":"A rooftop court is a sports court located on the roof of a building or structure.","zh":"rooftop court 指位於建築物或結構物天台上的運動場。"},{"en":"A rooftop court gives players open space in a crowded city.","zh":"天台球場在擁擠城市中為球員提供開放空間。"},{"en":"Rooftop courts attract photographers because they combine sport, height, buildings, and sky.","zh":"天台球場吸引攝影者，因為它結合運動、高度、建築和天空。"},{"en":"A rooftop court may be photogenic, but it is also a place where residents exercise.","zh":"天台球場可能很上鏡，但它也是居民運動的地方。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"standing in front of","meaning":"站在……前面","examples":[{"en":"A person standing in front of the pastel walls becomes the centre of the picture.","zh":"一個人站在淺色柔和的牆身前面，會成為相片的焦點。"},{"en":"Standing in front of something means being positioned before it, usually facing away from or toward it.","zh":"standing in front of 某物，指站在它前方，通常面向或背向它。"},{"en":"A child standing in front of a birthday cake becomes the focus of the photo.","zh":"孩子站在生日蛋糕前面，會成為相片焦點。"},{"en":"People stand in front of attractive walls because the background frames them clearly.","zh":"人們站在吸引的牆身前面，因為背景能清楚襯托他們。"},{"en":"When standing in front of someone’s home, visitors should be careful not to block the entrance.","zh":"站在別人家門前時，訪客應小心不要阻塞入口。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"pastel walls","meaning":"淺色柔和的牆身","examples":[{"en":"The pastel walls create a soft but colourful background.","zh":"淺色柔和的牆身創造柔和但繽紛的背景。"},{"en":"Pastel walls are walls painted in light, gentle colours.","zh":"pastel walls 指塗上淺淡柔和顏色的牆身。"},{"en":"A nursery may use pastel walls to make children feel calm.","zh":"幼兒中心可能使用淺色柔和的牆身，令孩子感到平靜。"},{"en":"Pastel walls photograph well because the colours are clear but not too harsh.","zh":"淺色柔和的牆身很適合拍照，因為顏色清楚但不刺眼。"},{"en":"In Choi Hung Estate, pastel walls help create a friendly and recognisable image.","zh":"在彩虹邨，淺色柔和的牆身幫助形成親切而容易辨認的形象。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"become the centre of a picture","meaning":"成為相片的焦點","examples":[{"en":"A visitor can become the centre of a picture without ruining the pattern.","zh":"訪客可以成為相片的焦點，而不破壞圖案。"},{"en":"To become the centre of a picture means to become the main focus that viewers notice first.","zh":"become the centre of a picture 指成為觀眾首先注意到的主要焦點。"},{"en":"A dancer in bright clothes may become the centre of a picture on a dark stage.","zh":"穿鮮色衣服的舞者在黑暗舞台上可能成為相片焦點。"},{"en":"Strong backgrounds can help a person become the centre of a picture more clearly.","zh":"強烈背景可以幫助人物更清楚成為相片的焦點。"},{"en":"A good photo balances the person and the background so neither feels confusing.","zh":"好相片會平衡人物和背景，讓兩者都不顯得混亂。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"the pattern behind","meaning":"背後的圖案","examples":[{"en":"The pattern behind the person remains clear in the photograph.","zh":"相片中人物背後的圖案仍然清晰。"},{"en":"The pattern behind means the repeated shapes, colours, or lines in the background.","zh":"the pattern behind 指背景中重複出現的形狀、顏色或線條。"},{"en":"In a class photo, the pattern behind the students may be a row of bookshelves.","zh":"在班相中，學生背後的圖案可能是一排書架。"},{"en":"A clear pattern behind a subject can make a photo look organised.","zh":"主體背後清晰的圖案可以令相片看起來有組織。"},{"en":"If the pattern behind is too busy, the main person may be harder to notice.","zh":"如果背後的圖案太複雜，主要人物可能較難被注意到。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"not only...but also","meaning":"不但……而且……","examples":[{"en":"The attraction is not only beauty in the traditional sense, but also visual clarity.","zh":"吸引之處不但在於傳統意義上的美，而且在於視覺清晰度。"},{"en":"Not only...but also is used to add a second important idea to the first one.","zh":"not only...but also 用來在第一個重要想法之外，再加入第二個重要想法。"},{"en":"Exercise is not only good for the body, but also helpful for mood.","zh":"運動不但對身體有益，而且有助改善心情。"},{"en":"This pattern shows that both points matter, not just the first one.","zh":"這個句式顯示兩點都重要，而不只是第一點。"},{"en":"Public housing estates attract visitors not only through colour, but also through local meaning.","zh":"公共屋邨不但透過色彩吸引訪客，而且透過地方意義吸引訪客。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"beauty in the traditional sense","meaning":"傳統意義上的美","examples":[{"en":"The estate offers more than beauty in the traditional sense.","zh":"這個屋邨提供的不只是傳統意義上的美。"},{"en":"Beauty in the traditional sense means the usual idea of beauty, such as elegance, harmony, or prettiness.","zh":"beauty in the traditional sense 指一般理解的美，例如優雅、和諧或漂亮。"},{"en":"A crowded market may not have beauty in the traditional sense, but it can feel full of life.","zh":"擁擠的市場未必有傳統意義上的美，但可以充滿生命力。"},{"en":"Some places attract people because of character, not beauty in the traditional sense.","zh":"有些地方吸引人，是因為有性格，而不是因為傳統意義上的美。"},{"en":"Choi Hung Estate shows that visual interest can go beyond traditional ideas of beauty.","zh":"彩虹邨顯示視覺吸引力可以超越傳統美感概念。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"visual clarity","meaning":"視覺清晰度","examples":[{"en":"The estate attracts Instagrammers because of its visual clarity.","zh":"這個屋邨因其視覺清晰度而吸引 Instagram 用戶。"},{"en":"Visual clarity means a scene is easy to see, understand, and frame in an image.","zh":"visual clarity 指一個場景容易被看見、理解和放進影像框架中。"},{"en":"A simple sign has visual clarity when people can read it quickly from far away.","zh":"當人們能從遠處很快讀懂一個簡單標誌時，它就有視覺清晰度。"},{"en":"Strong lines and clean colours create visual clarity in photographs.","zh":"強烈線條和乾淨色彩在相片中創造視覺清晰度。"},{"en":"Visual clarity matters online because viewers scroll quickly and notice clear images first.","zh":"視覺清晰度在網上很重要，因為觀眾快速滑動，會先注意清楚影像。"}],"source":"2020 Q2.pdf","sourcePage":4},{"front":"bold enough to catch attention","meaning":"夠鮮明去吸引注意","examples":[{"en":"The colours are bold enough to catch attention online.","zh":"這些顏色夠鮮明，能在網上吸引注意。"},{"en":"Bold enough to catch attention means strong or clear enough to make people notice.","zh":"bold enough to catch attention 指夠強烈或清楚，能令人注意到。"},{"en":"A headline must be bold enough to catch attention on a crowded noticeboard.","zh":"標題必須夠鮮明，才能在擁擠的告示板上吸引注意。"},{"en":"Bright colours catch attention because they stand out from dull surroundings.","zh":"鮮色能吸引注意，因為它們在暗淡環境中突出。"},{"en":"Something can be bold enough to catch attention without being messy or too loud.","zh":"某事物可以夠鮮明去吸引注意，而不必混亂或過於吵鬧。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"simple enough to fit","meaning":"夠簡潔去配合……","examples":[{"en":"The pattern is simple enough to fit the square frame of social media.","zh":"這個圖案夠簡潔，能配合社交媒體的方形畫面。"},{"en":"Simple enough to fit means not too complicated for a particular space, format, or purpose.","zh":"simple enough to fit 指不太複雜，能配合某個空間、格式或用途。"},{"en":"A logo should be simple enough to fit on a small phone icon.","zh":"標誌應夠簡潔，能配合小小的手機圖示。"},{"en":"Photos work better online when the main pattern is simple enough to fit the screen.","zh":"當主要圖案夠簡潔去配合屏幕時，相片在網上效果會更好。"},{"en":"If an image is too crowded, it may not be simple enough to fit social media formats.","zh":"如果影像太擁擠，它可能不夠簡潔去配合社交媒體格式。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"the square frame of social media","meaning":"社交媒體的方形畫面","examples":[{"en":"The estate fits the square frame of social media.","zh":"這個屋邨配合社交媒體的方形畫面。"},{"en":"The square frame of social media refers to the common square shape used for many online images.","zh":"the square frame of social media 指許多網上影像常用的方形格式。"},{"en":"A café table may look good in the square frame of social media if the objects are neatly arranged.","zh":"如果物件排列整齊，咖啡店桌面可能很適合社交媒體的方形畫面。"},{"en":"Photographers may choose scenes that fit the square frame of social media easily.","zh":"攝影者可能選擇容易配合社交媒體方形畫面的場景。"},{"en":"This frame can influence what people photograph and how they arrange the scene.","zh":"這種畫面會影響人們拍攝甚麼，以及如何安排場景。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"another reason is that","meaning":"另一個原因是","examples":[{"en":"Another reason is that these estates offer local identity.","zh":"另一個原因是這些屋邨提供本地身份感。"},{"en":"Another reason is that is used to introduce an additional explanation.","zh":"another reason is that 用來引入另一個解釋。"},{"en":"Another reason is that students learn better when examples feel familiar.","zh":"另一個原因是，當例子令人感到熟悉時，學生會學得更好。"},{"en":"This phrase helps organise writing by moving from one reason to the next.","zh":"這個短語透過由一個原因轉到下一個原因，幫助組織文章。"},{"en":"Another reason is that public places often carry memories that visitors cannot see at first.","zh":"另一個原因是，公共地方常承載訪客一開始看不見的記憶。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"something more meaningful than","meaning":"比……更有意義的東西","examples":[{"en":"The estates offer something more meaningful than an artificial tourist attraction.","zh":"這些屋邨提供比人工化旅遊景點更有意義的東西。"},{"en":"Something more meaningful than means something has deeper value than another thing being compared.","zh":"something more meaningful than 指某事物比另一個被比較的東西有更深價值。"},{"en":"A handwritten letter may offer something more meaningful than an expensive gift.","zh":"手寫信可能提供比昂貴禮物更有意義的東西。"},{"en":"Real community life can feel more meaningful than a place built only for photos.","zh":"真實社區生活可能比只為拍照而建的地方更有意義。"},{"en":"This phrase helps compare surface attraction with deeper human value.","zh":"這個短語幫助比較表面吸引力與更深層的人情價值。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"artificial tourist attraction","meaning":"人工化的旅遊景點","examples":[{"en":"The estate feels more authentic than an artificial tourist attraction.","zh":"這個屋邨感覺比人工化的旅遊景點更真實。"},{"en":"An artificial tourist attraction is a place created mainly to attract visitors, rather than growing naturally from local life.","zh":"artificial tourist attraction 指主要為吸引遊客而建，而不是自然從本地生活中形成的地方。"},{"en":"A fake old street in a theme park can be an artificial tourist attraction.","zh":"主題公園中的仿古街道可以是人工化的旅遊景點。"},{"en":"Artificial tourist attractions may look tidy, but they may not show real daily life.","zh":"人工化旅遊景點可能看起來整齊，但未必展示真實日常生活。"},{"en":"Some visitors prefer real neighbourhoods because they feel less like artificial tourist attractions.","zh":"有些訪客較喜歡真實社區，因為它們不像人工化旅遊景點。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"a sense of local identity","meaning":"本地身份感；地方認同感","examples":[{"en":"Older housing estates give visitors a sense of local identity.","zh":"較舊的屋邨給訪客一種本地身份感。"},{"en":"A sense of local identity means a feeling that a place has its own history, habits, and character.","zh":"a sense of local identity 指感覺到一個地方有自己的歷史、習慣和性格。"},{"en":"Old markets can give people a sense of local identity through food, voices, and familiar shops.","zh":"舊街市可以透過食物、聲音和熟悉店舖給人本地身份感。"},{"en":"Visitors may feel a sense of local identity when they see how residents really live.","zh":"當訪客看見居民真正如何生活時，可能感受到本地身份感。"},{"en":"This sense becomes stronger when a place shows everyday life, not only tourist design.","zh":"當一個地方展示日常生活，而不只是旅遊設計時，這種感覺會更強。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"unlike shopping malls","meaning":"不像商場","examples":[{"en":"Unlike shopping malls, older estates show Hong Kong’s everyday rhythm.","zh":"不像商場，較舊的屋邨展示香港的日常節奏。"},{"en":"Unlike shopping malls means different from shopping malls in an important way.","zh":"unlike shopping malls 指在重要方面與商場不同。"},{"en":"Unlike shopping malls, street markets often show more local voices and habits.","zh":"不像商場，街市常展示更多本地聲音和習慣。"},{"en":"This phrase introduces contrast between places that may look modern and places that feel lived-in.","zh":"這個短語引入對比，區分看似現代的地方和有生活感的地方。"},{"en":"Unlike shopping malls, housing estates are not mainly designed for buying and selling.","zh":"不像商場，屋邨主要不是為買賣而設計。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"look similar in any modern city","meaning":"在任何現代城市都看起來相似","examples":[{"en":"Many shopping malls look similar in any modern city.","zh":"許多商場在任何現代城市都看起來相似。"},{"en":"Look similar in any modern city means not having much local difference from place to place.","zh":"look similar in any modern city 指不同地方之間沒有太多本地差異。"},{"en":"Chain coffee shops may look similar in any modern city because they use the same design.","zh":"連鎖咖啡店可能在任何現代城市都看起來相似，因為它們使用同一設計。"},{"en":"Places that look similar everywhere may feel convenient but less memorable.","zh":"到處看起來相似的地方可能方便，但較不令人難忘。"},{"en":"Older neighbourhoods stand out because they do not simply look similar in any modern city.","zh":"較舊社區突出，因為它們不只是任何現代城市都看起來相似的地方。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"older housing estates","meaning":"較舊的屋邨","examples":[{"en":"Hong Kong’s older housing estates show the city’s history.","zh":"香港較舊的屋邨展示城市的歷史。"},{"en":"Older housing estates are public or residential estates built in earlier periods of a city’s development.","zh":"older housing estates 指在城市發展較早時期建成的公共或住宅屋邨。"},{"en":"Older housing estates may have older lifts, tiled walls, small shops, and familiar gathering spaces.","zh":"較舊的屋邨可能有舊式升降機、瓷磚牆、小商店和熟悉的聚集空間。"},{"en":"These estates show history because their design reflects how people lived in the past.","zh":"這些屋邨展示歷史，因為它們的設計反映過去人們如何生活。"},{"en":"Older housing estates may look ordinary, but they carry shared memory.","zh":"較舊的屋邨可能看似普通，但承載共同記憶。"}],"source":"2020 Q2.pdf","sourcePage":5},{"front":"density, history and everyday rhythm","meaning":"密度、歷史和日常節奏","examples":[{"en":"Public housing estates show Hong Kong’s density, history and everyday rhythm.","zh":"公共屋邨展示香港的密度、歷史和日常節奏。"},{"en":"Density, history and everyday rhythm means crowded living, past development, and ordinary daily activities.","zh":"density, history and everyday rhythm 指密集生活、過去發展和普通日常活動。"},{"en":"A street market can show density, history and everyday rhythm through stalls, old signs, and regular customers.","zh":"街市可以透過攤檔、舊招牌和熟客展示密度、歷史和日常節奏。"},{"en":"These elements make a place feel real because they show how people actually live.","zh":"這些元素令地方感覺真實，因為它們展示人們實際如何生活。"},{"en":"Public housing estates reveal more than buildings; they reveal density, history and everyday rhythm.","zh":"公共屋邨展現的不只是建築；它們展現密度、歷史和日常節奏。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"tightly packed flats","meaning":"密集的住宅單位","examples":[{"en":"The tightly packed flats form a dramatic concrete canyon.","zh":"密集的住宅單位形成震撼的石屎峽谷。"},{"en":"Tightly packed flats are homes built very close together with little space between them.","zh":"tightly packed flats 指彼此距離很近、空間有限的住宅單位。"},{"en":"In a crowded city, tightly packed flats may surround a narrow courtyard.","zh":"在擁擠城市中，密集的住宅單位可能圍繞狹窄天井。"},{"en":"Tightly packed flats show urban density because many people live in a small area.","zh":"密集的住宅單位展示城市密度，因為很多人住在小面積中。"},{"en":"They can look visually powerful, but they also remind us of limited living space.","zh":"它們可以看起來很有視覺震撼力，但也提醒我們居住空間有限。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"form a dramatic concrete canyon","meaning":"形成震撼的石屎峽谷","examples":[{"en":"At Yik Cheong Building, the flats form a dramatic concrete canyon.","zh":"在益昌大廈，住宅單位形成震撼的石屎峽谷。"},{"en":"To form a dramatic concrete canyon means tall buildings create a narrow, powerful space like a canyon made of concrete.","zh":"form a dramatic concrete canyon 指高樓形成像由石屎構成的峽谷般狹窄而有力量的空間。"},{"en":"High apartment blocks may form a dramatic concrete canyon around a small courtyard.","zh":"高層住宅可能圍繞小天井，形成震撼的石屎峽谷。"},{"en":"This effect attracts photographers because the buildings seem to rise sharply on both sides.","zh":"這種效果吸引攝影者，因為建築像在兩邊急速升起。"},{"en":"A dramatic concrete canyon can look impressive, but it is also someone’s living environment.","zh":"震撼的石屎峽谷可以很壯觀，但它也是某些人的生活環境。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"concrete canyon","meaning":"石屎峽谷","examples":[{"en":"Yik Cheong Building is often photographed as a concrete canyon.","zh":"益昌大廈常被拍成石屎峽谷。"},{"en":"A concrete canyon is a narrow urban space surrounded by tall concrete buildings.","zh":"concrete canyon 指被高大石屎建築包圍的狹窄城市空間。"},{"en":"Some city streets feel like concrete canyons when high towers stand on both sides.","zh":"當高樓立在兩旁時，一些城市街道感覺像石屎峽谷。"},{"en":"Concrete canyons can create powerful photos because they show scale and density.","zh":"石屎峽谷能創造有力量的相片，因為它展示規模和密度。"},{"en":"The phrase suggests both visual drama and the crowded feeling of city life.","zh":"這個短語同時暗示視覺震撼和城市生活的擁擠感。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"elderly neighbours exercising","meaning":"做運動的長者街坊","examples":[{"en":"Elderly neighbours exercising remind visitors that the estate is a living community.","zh":"做運動的長者街坊提醒訪客，屋邨是一個仍有人生活的社區。"},{"en":"Elderly neighbours exercising means older residents doing physical activity in shared spaces.","zh":"elderly neighbours exercising 指年長居民在共享空間做身體活動。"},{"en":"Elderly neighbours exercising in the morning can make a park feel friendly and active.","zh":"早上做運動的長者街坊可以令公園感覺親切而有活力。"},{"en":"Such scenes show that a place is used for daily life, not only for visitors.","zh":"這些場景顯示一個地方是供日常生活使用，而不只是給訪客觀看。"},{"en":"Seeing elderly neighbours exercising helps outsiders notice the human side of the estate.","zh":"看見做運動的長者街坊，能幫助外人注意到屋邨有人情的一面。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"children playing after school","meaning":"放學後玩耍的小朋友","examples":[{"en":"Children playing after school make the estate feel alive.","zh":"放學後玩耍的小朋友令屋邨感覺有生命力。"},{"en":"Children playing after school means young people using shared spaces for games after classes finish.","zh":"children playing after school 指孩子下課後在共享空間玩遊戲。"},{"en":"Children playing after school in a courtyard can show that neighbours trust the space.","zh":"放學後在庭院玩耍的小朋友可以顯示鄰里信任這個空間。"},{"en":"These scenes make a community feel alive because ordinary routines continue there.","zh":"這些場景令社區感覺有生命力，因為普通日常仍在那裏繼續。"},{"en":"A visitor should be careful not to disturb children playing after school.","zh":"訪客應小心不要滋擾放學後玩耍的小朋友。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"remind visitors that","meaning":"提醒訪客","examples":[{"en":"These everyday scenes remind visitors that the estate is not a museum set.","zh":"這些日常場景提醒訪客，屋邨不是博物館佈景。"},{"en":"Remind visitors that means make visitors remember or realise an important fact.","zh":"remind visitors that 指令訪客記起或意識到一個重要事實。"},{"en":"Signs in a temple remind visitors that they should speak quietly.","zh":"寺廟中的告示提醒訪客應保持安靜。"},{"en":"Residents’ daily activities remind visitors that a famous place may still be someone’s home.","zh":"居民的日常活動提醒訪客，著名地方仍可能是某人的家。"},{"en":"This phrase is useful when people may forget something important because they are excited.","zh":"當人們因興奮而可能忘記重要事情時，這個短語很有用。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"living community","meaning":"仍有人生活的社區","examples":[{"en":"Choi Hung Estate is a living community, not just a photo spot.","zh":"彩虹邨是一個仍有人生活的社區，不只是拍照地點。"},{"en":"A living community is a place where real people continue their daily lives and relationships.","zh":"living community 指真實的人仍在其中過日常生活並建立關係的地方。"},{"en":"A market is a living community when shopkeepers know customers and neighbours meet there.","zh":"當店主認識顧客、鄰居在那裏相遇時，街市就是一個仍有人生活的社區。"},{"en":"Treating a place as a living community encourages visitors to behave with respect.","zh":"把地方視為仍有人生活的社區，會鼓勵訪客尊重行為。"},{"en":"A living community changes, remembers, argues, celebrates, and cares for people.","zh":"仍有人生活的社區會改變、記憶、爭論、慶祝，也會照顧人。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"museum set","meaning":"博物館佈景；展覽佈景","examples":[{"en":"The estate is a real home, not a museum set.","zh":"這個屋邨是真實的家，不是博物館佈景。"},{"en":"A museum set is a display arranged for people to look at, not a place for normal living.","zh":"museum set 指為給人觀看而安排的展覽場景，不是正常生活的地方。"},{"en":"An old classroom in a museum may be a museum set showing past school life.","zh":"博物館中的舊課室可能是展示過去校園生活的博物館佈景。"},{"en":"Calling a home a museum set would ignore the people who actually live there.","zh":"把一個家稱作博物館佈景，會忽視真正住在那裏的人。"},{"en":"Public housing estates may be interesting to visitors, but they are not museum sets.","zh":"公共屋邨對訪客可能很有趣，但它們不是博物館佈景。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"several Instagrammers said","meaning":"幾位 Instagram 用戶表示","examples":[{"en":"Several Instagrammers said they preferred these places.","zh":"幾位 Instagram 用戶表示，他們較喜歡這些地方。"},{"en":"Several Instagrammers said means a number of Instagram users expressed the same or similar opinion.","zh":"several Instagrammers said 指幾名 Instagram 用戶表達相同或相近意見。"},{"en":"Several students said they preferred studying in the library because it was quieter.","zh":"幾名學生表示，他們較喜歡在圖書館溫習，因為那裏較安靜。"},{"en":"This phrase shows that the writer is reporting views from more than one person.","zh":"這個短語顯示作者正在報道不止一個人的看法。"},{"en":"Several Instagrammers said the estates felt more local than luxury hotels.","zh":"幾位 Instagram 用戶表示，這些屋邨比豪華酒店更有本地感。"}],"source":"2020 Q2.pdf","sourcePage":6},{"front":"feel more Hong Kong","meaning":"更有香港味","examples":[{"en":"They felt these estates were more Hong Kong than luxury hotels.","zh":"他們覺得這些屋邨比豪華酒店更有香港味。"},{"en":"Feel more Hong Kong means seem to show Hong Kong’s real character more strongly.","zh":"feel more Hong Kong 指看起來更強烈地展現香港的真實特色。"},{"en":"A crowded tram ride may feel more Hong Kong than a hotel lobby.","zh":"擁擠的電車旅程可能比酒店大堂更有香港味。"},{"en":"Places feel more Hong Kong when they show local habits, sounds, food, and history.","zh":"當地方展示本地習慣、聲音、食物和歷史時，就會更有香港味。"},{"en":"This phrase is informal but useful for describing a strong sense of local identity.","zh":"這個短語較口語，但很適合描述強烈的地方認同感。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"luxury hotels","meaning":"豪華酒店","examples":[{"en":"Some Instagrammers prefer housing estates to luxury hotels.","zh":"有些 Instagram 用戶較喜歡屋邨，而不是豪華酒店。"},{"en":"Luxury hotels are expensive hotels that offer high levels of comfort, service, and style.","zh":"luxury hotels 指提供高水平舒適、服務和風格的昂貴酒店。"},{"en":"Tourists may stay in luxury hotels for sea views, large rooms, and fine restaurants.","zh":"遊客可能入住豪華酒店，享受海景、大房間和高級餐廳。"},{"en":"Luxury hotels can be beautiful, but they may look similar in many global cities.","zh":"豪華酒店可以很美，但在許多國際城市可能看起來相似。"},{"en":"Some visitors prefer older estates because they feel more real than luxury hotels.","zh":"有些訪客較喜歡舊屋邨，因為它們比豪華酒店感覺更真實。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"harbour-view cafés","meaning":"海景咖啡店","examples":[{"en":"Housing estates can feel more local than harbour-view cafés.","zh":"屋邨可以比海景咖啡店更有本地感。"},{"en":"Harbour-view cafés are cafés where customers can see the harbour while eating or drinking.","zh":"harbour-view cafés 指顧客進食或飲品時能看見海港景色的咖啡店。"},{"en":"Harbour-view cafés may attract tourists who want beautiful city scenery.","zh":"海景咖啡店可能吸引想欣賞城市美景的遊客。"},{"en":"Although harbour-view cafés are pleasant, they may not show everyday local life.","zh":"雖然海景咖啡店令人愉快，但未必展示日常本地生活。"},{"en":"A small estate shop can sometimes feel more local than a stylish harbour-view café.","zh":"一間小小的屋邨店舖有時比時尚海景咖啡店更有本地感。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"the more..., the more...","meaning":"越……就越……","examples":[{"en":"The more global Instagram becomes, the more people search for real local images.","zh":"Instagram 越全球化，人們就越尋找真實本地影像。"},{"en":"The more..., the more... is used to show that one change increases together with another change.","zh":"the more..., the more... 用來顯示一個變化增加時，另一個變化也一起增加。"},{"en":"The more students read, the more vocabulary they learn.","zh":"學生讀得越多，就學到越多詞彙。"},{"en":"The more cities look alike, the more people value places with local character.","zh":"城市看起來越相似，人們就越重視有本地特色的地方。"},{"en":"This pattern helps explain a relationship between two growing effects.","zh":"這個句式有助解釋兩個不斷增強的效果之間的關係。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"rooted in a real place","meaning":"植根於真實地方","examples":[{"en":"People search for images rooted in a real place.","zh":"人們尋找植根於真實地方的影像。"},{"en":"Rooted in a real place means connected to an actual location, community, and lived experience.","zh":"rooted in a real place 指與實際地點、社區和生活經驗相連。"},{"en":"A story rooted in a real place often includes local names, voices, and habits.","zh":"植根於真實地方的故事，常包括本地名稱、聲音和習慣。"},{"en":"Images rooted in a real place feel more authentic than pictures taken in a studio set.","zh":"植根於真實地方的影像，比在影樓佈景中拍攝的相片更真實。"},{"en":"People may trust photos more when they seem rooted in a real place.","zh":"當相片看似植根於真實地方時，人們可能更信任它們。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"paradoxically","meaning":"矛盾的是","examples":[{"en":"Paradoxically, visitors are attracted by what residents consider ordinary.","zh":"矛盾的是，訪客被居民視為平常的東西吸引。"},{"en":"Paradoxically means in a way that seems surprising because two ideas appear to conflict.","zh":"paradoxically 指某種情況令人意外，因為兩個想法看似互相衝突。"},{"en":"Paradoxically, a quiet village may become crowded because people visit it for peace.","zh":"矛盾的是，一條安靜村莊可能因人們為尋求寧靜而到訪，結果變得擁擠。"},{"en":"This word is used when the result seems opposite to what we might expect.","zh":"當結果看似與預期相反時，人們會使用這個詞。"},{"en":"Paradoxically, ordinary estate details can become special when seen through outsiders’ eyes.","zh":"矛盾的是，普通屋邨細節在外人眼中可以變得特別。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"precisely what","meaning":"正正是","examples":[{"en":"What attracts visitors is precisely what residents consider ordinary.","zh":"吸引訪客的，正正是居民視為平常的東西。"},{"en":"Precisely what means exactly the thing that is being discussed.","zh":"precisely what 指正在討論的正是那件事物。"},{"en":"The quietness of the library is precisely what helps students concentrate.","zh":"圖書館的寧靜正正是幫助學生專注的原因。"},{"en":"Visitors may admire precisely what locals no longer notice.","zh":"訪客可能欣賞的，正正是本地人不再留意的東西。"},{"en":"This phrase gives emphasis by pointing directly to the main thing.","zh":"這個短語透過直接指出重點來加強語氣。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"consider ordinary","meaning":"視為平常","examples":[{"en":"Residents may consider laundry on rails and old lifts ordinary.","zh":"居民可能把欄杆上的衣物和舊式升降機視為平常。"},{"en":"To consider ordinary means to think something is normal, common, or not special.","zh":"consider ordinary 指認為某事物正常、常見或不特別。"},{"en":"City residents may consider crowded trains ordinary because they use them every day.","zh":"城市居民可能把擁擠列車視為平常，因為他們每天都使用。"},{"en":"People often consider ordinary the things they see too often to notice.","zh":"人們常把經常看見的東西視為平常，以致不再注意。"},{"en":"What locals consider ordinary may look interesting to visitors.","zh":"本地人視為平常的東西，訪客可能覺得有趣。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"laundry on rails","meaning":"晾在欄杆上的衣物","examples":[{"en":"Laundry on rails has become part of the visual identity of the estate.","zh":"晾在欄杆上的衣物已成為屋邨視覺身份的一部分。"},{"en":"Laundry on rails means clothes hung on railings to dry.","zh":"laundry on rails 指掛在欄杆上晾乾的衣物。"},{"en":"In many older buildings, laundry on rails shows how residents use limited space.","zh":"在許多舊建築中，晾在欄杆上的衣物展示居民如何使用有限空間。"},{"en":"Laundry on rails may look visually interesting, but it is also part of private daily life.","zh":"晾在欄杆上的衣物可能看起來有視覺趣味，但也是私人日常生活的一部分。"},{"en":"Visitors should not treat laundry on rails as decoration without considering residents’ privacy.","zh":"訪客不應只把晾在欄杆上的衣物當成裝飾，而不考慮居民私隱。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"old lifts","meaning":"舊式升降機","examples":[{"en":"Old lifts are part of the everyday rhythm of older estates.","zh":"舊式升降機是較舊屋邨日常節奏的一部分。"},{"en":"Old lifts are older elevator systems used to carry people between floors.","zh":"old lifts 指用來載人上下樓層的較舊升降機系統。"},{"en":"Residents may wait for old lifts every morning on the way to work or school.","zh":"居民每天早上上班或上學時，可能要等待舊式升降機。"},{"en":"Old lifts can show the age of a building and the routines of people who live there.","zh":"舊式升降機可以顯示建築物的年齡和居民的生活規律。"},{"en":"To visitors, old lifts may look nostalgic; to residents, they are daily transport.","zh":"對訪客而言，舊式升降機可能很懷舊；對居民而言，它們是日常交通。"}],"source":"2020 Q2.pdf","sourcePage":7},{"front":"tiled walls","meaning":"瓷磚牆","examples":[{"en":"Tiled walls are common in older Hong Kong housing estates.","zh":"瓷磚牆在香港較舊的屋邨很常見。"},{"en":"Tiled walls are walls covered with small flat pieces of ceramic or similar material.","zh":"tiled walls 指鋪上細小平面陶瓷或類似材料的牆身。"},{"en":"Bathrooms, kitchens, schools, and old corridors often have tiled walls because they are easy to clean.","zh":"浴室、廚房、學校和舊走廊常有瓷磚牆，因為它們容易清潔。"},{"en":"Tiled walls can show the design style of an earlier period.","zh":"瓷磚牆可以顯示較早時期的設計風格。"},{"en":"In photos, tiled walls may add texture and a strong sense of place.","zh":"在相片中，瓷磚牆可以增加質感和強烈地方感。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"open spaces between blocks","meaning":"大廈之間的公共空間","examples":[{"en":"Open spaces between blocks give residents room to gather.","zh":"大廈之間的公共空間讓居民有地方聚集。"},{"en":"Open spaces between blocks are shared outdoor areas located among residential buildings.","zh":"open spaces between blocks 指位於住宅大廈之間的共享戶外空間。"},{"en":"Children may play in open spaces between blocks after school.","zh":"小朋友放學後可能在大廈之間的公共空間玩耍。"},{"en":"These spaces help neighbours meet, rest, exercise, and watch community life.","zh":"這些空間幫助鄰居見面、休息、運動和觀看社區生活。"},{"en":"Open spaces between blocks are important because dense housing still needs breathing room.","zh":"大廈之間的公共空間很重要，因為密集住宅仍需要喘息空間。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"feelings are far from simple","meaning":"感受絕不簡單","examples":[{"en":"Residents’ feelings are far from simple.","zh":"居民的感受絕不簡單。"},{"en":"Feelings are far from simple means emotions are mixed, complicated, or difficult to explain in one way.","zh":"feelings are far from simple 指情緒混合、複雜，或難以用單一方式解釋。"},{"en":"A student’s feelings after graduation may be far from simple because they feel both excited and sad.","zh":"學生畢業後的感受可能絕不簡單，因為他們既興奮又傷感。"},{"en":"Residents may feel proud of attention but annoyed by noise, so their feelings are far from simple.","zh":"居民可能因關注而自豪，但又因噪音而不滿，所以感受絕不簡單。"},{"en":"This phrase helps show that a situation cannot be judged too quickly.","zh":"這個短語幫助顯示一個情況不能太快下判斷。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"be pleased that","meaning":"對……感到高興","examples":[{"en":"Some residents are pleased that their estate has become famous.","zh":"有些居民對自己的屋邨變得有名感到高興。"},{"en":"To be pleased that means to feel happy or satisfied because something has happened.","zh":"be pleased that 指因某事發生而感到高興或滿意。"},{"en":"Parents may be pleased that their child has made new friends at school.","zh":"父母可能對孩子在學校交到新朋友感到高興。"},{"en":"Residents may be pleased that outsiders finally notice their neighbourhood’s beauty.","zh":"居民可能對外人終於注意到自己社區的美感到高興。"},{"en":"Being pleased about attention does not mean accepting every behaviour from visitors.","zh":"對關注感到高興，不代表接受訪客的所有行為。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"become famous","meaning":"變得有名","examples":[{"en":"Choi Hung Estate has become famous as a photo spot.","zh":"彩虹邨已作為拍照地點變得有名。"},{"en":"To become famous means to become widely known by many people.","zh":"become famous 指變得被很多人廣泛認識。"},{"en":"A small restaurant may become famous after many customers share photos online.","zh":"一間小餐廳在許多顧客網上分享相片後，可能變得有名。"},{"en":"A place can become famous quickly when social media users repeat the same image.","zh":"當社交媒體用戶重複分享同一種影像時，一個地方可以很快變得有名。"},{"en":"Becoming famous can bring pride, crowds, business, and inconvenience at the same time.","zh":"變得有名可以同時帶來自豪、人群、生意和不便。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"retired resident","meaning":"退休居民","examples":[{"en":"A retired resident said she felt proud of the estate.","zh":"一位退休居民說，她為屋邨感到自豪。"},{"en":"A retired resident is someone who no longer works full-time and lives in a particular place.","zh":"retired resident 指不再全職工作，並住在某個地方的人。"},{"en":"A retired resident may spend mornings exercising in the estate courtyard.","zh":"退休居民可能早上在屋邨庭院做運動。"},{"en":"Retired residents often carry long memories of how a neighbourhood has changed.","zh":"退休居民常承載社區如何改變的長久記憶。"},{"en":"Listening to retired residents can help visitors understand a place beyond its appearance.","zh":"聆聽退休居民說話，能幫助訪客理解外觀以外的地方。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"live there for more than forty years","meaning":"在那裏住了四十多年","examples":[{"en":"Mrs Lau had lived there for more than forty years.","zh":"劉太在那裏住了四十多年。"},{"en":"To live there for more than forty years means to have made that place one’s home for over four decades.","zh":"live there for more than forty years 指把該地方作為自己的家超過四十年。"},{"en":"A person who has lived in the same building for forty years knows many neighbours and stories.","zh":"在同一座大廈住了四十年的人，認識許多鄰居和故事。"},{"en":"Long residence creates attachment because daily life, family memories, and community changes happen there.","zh":"長期居住會建立感情，因為日常生活、家庭記憶和社區變化都在那裏發生。"},{"en":"Someone who has lived there for more than forty years may see the estate very differently from a visitor.","zh":"在那裏住了四十多年的人，可能會以很不同於訪客的方式看待屋邨。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"feel proud when","meaning":"當……時感到自豪","examples":[{"en":"She felt proud when visitors praised the colours of the buildings.","zh":"當訪客讚賞建築物的顏色時，她感到自豪。"},{"en":"To feel proud when something happens means to feel pleased and honoured because of that event.","zh":"feel proud when 指因某事發生而感到高興和光榮。"},{"en":"Parents may feel proud when their child helps a classmate.","zh":"當孩子幫助同學時，父母可能感到自豪。"},{"en":"Residents may feel proud when outsiders recognise beauty in their neighbourhood.","zh":"當外人認可自己社區的美時，居民可能感到自豪。"},{"en":"Feeling proud when praised is natural, especially when the praise concerns one’s home.","zh":"當受到讚賞時感到自豪是自然的，尤其當讚賞與自己的家有關。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"praise the colours of","meaning":"讚賞……的顏色","examples":[{"en":"Visitors praised the colours of the buildings.","zh":"訪客讚賞建築物的顏色。"},{"en":"To praise the colours of something means to say its colours are beautiful, attractive, or well chosen.","zh":"praise the colours of 某物，指稱讚它的顏色美麗、吸引或選得好。"},{"en":"A teacher may praise the colours of a student’s poster because they make the message clear.","zh":"老師可能讚賞學生海報的顏色，因為它們令訊息清楚。"},{"en":"Visitors praise the colours of Choi Hung Estate because the walls look cheerful in photos.","zh":"訪客讚賞彩虹邨的顏色，因為牆身在相片中看起來開朗。"},{"en":"Praising colours can make residents feel their familiar environment is valued.","zh":"讚賞顏色可以令居民感到熟悉的環境受到重視。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"in her eyes","meaning":"在她眼中","examples":[{"en":"In her eyes, the attention proves that public housing is not dull.","zh":"在她眼中，這種關注證明公共房屋並不沉悶。"},{"en":"In her eyes means from her point of view or according to her feelings.","zh":"in her eyes 指從她的角度或按照她的感受來看。"},{"en":"In his mother’s eyes, the small prize was a big achievement.","zh":"在他母親眼中，小獎項也是重大成就。"},{"en":"This phrase shows that the writer is reporting one person’s personal perspective.","zh":"這個短語顯示作者正在報道某人的個人觀點。"},{"en":"In residents’ eyes, the estate may be home before it is a tourist spot.","zh":"在居民眼中，屋邨首先可能是家，然後才是旅遊景點。"}],"source":"2020 Q2.pdf","sourcePage":8},{"front":"attention proves that","meaning":"這種關注證明","examples":[{"en":"The attention proves that public housing can be part of visual culture.","zh":"這種關注證明公共房屋可以成為視覺文化的一部分。"},{"en":"Attention proves that means public interest shows or confirms a certain point.","zh":"attention proves that 指公眾興趣顯示或確認某個觀點。"},{"en":"The long queue proves that people still care about the old bakery.","zh":"長長的人龍證明人們仍關心那間老餅店。"},{"en":"Online attention may prove that ordinary places can carry strong visual meaning.","zh":"網上關注可能證明普通地方也能承載強烈視覺意義。"},{"en":"However, attention proves only that people notice something, not that they fully understand it.","zh":"然而，關注只能證明人們注意到某事，不代表他們完全理解它。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"public housing","meaning":"公共房屋","examples":[{"en":"Public housing is an important part of Hong Kong life.","zh":"公共房屋是香港生活的重要部分。"},{"en":"Public housing is housing provided or supported by the government for people who need affordable homes.","zh":"public housing 指由政府提供或資助、給需要可負擔住所的人居住的房屋。"},{"en":"Many families depend on public housing when private rent is too high.","zh":"當私人租金太高時，許多家庭依賴公共房屋。"},{"en":"Public housing shapes daily life because it affects where people live, study, shop, and meet neighbours.","zh":"公共房屋塑造日常生活，因為它影響人們住在哪裏、在哪裏讀書、購物和見鄰居。"},{"en":"Public housing should be discussed with respect because it is home to many people.","zh":"討論公共房屋時應保持尊重，因為它是許多人的家。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"not necessarily","meaning":"不一定","examples":[{"en":"Public housing is not necessarily dull or embarrassing.","zh":"公共房屋不一定沉悶或令人尷尬。"},{"en":"Not necessarily means something is not always true, even if some people think it is.","zh":"not necessarily 指某事不總是真的，即使有些人這樣認為。"},{"en":"A small flat is not necessarily uncomfortable if it is well designed.","zh":"小單位如果設計得好，不一定不舒服。"},{"en":"Online fame is not necessarily good because it may bring pressure and crowds.","zh":"網上成名不一定是好事，因為它可能帶來壓力和人群。"},{"en":"This phrase helps challenge simple assumptions.","zh":"這個短語有助挑戰簡單假設。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"dull or embarrassing","meaning":"沉悶或令人尷尬","examples":[{"en":"Public housing is not necessarily dull or embarrassing.","zh":"公共房屋不一定沉悶或令人尷尬。"},{"en":"Dull or embarrassing means boring, unattractive, or something people may feel ashamed of.","zh":"dull or embarrassing 指沉悶、不吸引，或令人可能感到羞愧的。"},{"en":"Old buildings are not automatically dull or embarrassing if people understand their history.","zh":"如果人們了解舊建築的歷史，它們不會自動變得沉悶或令人尷尬。"},{"en":"A place may seem dull to outsiders but meaningful to people who live there.","zh":"一個地方對外人可能看似沉悶，但對住在那裏的人很有意義。"},{"en":"Public housing can be ordinary without being dull or embarrassing.","zh":"公共房屋可以普通，而不等於沉悶或令人尷尬。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"visual culture","meaning":"視覺文化","examples":[{"en":"Public housing can be part of Hong Kong’s visual culture.","zh":"公共房屋可以成為香港視覺文化的一部分。"},{"en":"Visual culture means the images, designs, colours, symbols, and scenes through which people understand society.","zh":"visual culture 指人們用來理解社會的影像、設計、顏色、符號和場景。"},{"en":"Posters, films, street signs, and social media photos are all part of visual culture.","zh":"海報、電影、街道招牌和社交媒體相片都是視覺文化的一部分。"},{"en":"Public housing enters visual culture when people share and discuss its images widely.","zh":"當公共房屋的影像被廣泛分享和討論時，它就進入視覺文化。"},{"en":"Visual culture affects how people notice places and judge their value.","zh":"視覺文化會影響人們如何注意地方和判斷其價值。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"with popularity comes recognition","meaning":"受歡迎帶來認同","examples":[{"en":"With popularity comes recognition.","zh":"受歡迎帶來認同。"},{"en":"With popularity comes recognition means when something becomes popular, people begin to notice and value it.","zh":"with popularity comes recognition 指某事物變得受歡迎時，人們開始注意並重視它。"},{"en":"With popularity comes recognition for small cafés that were once ignored.","zh":"受歡迎可以為曾被忽略的小咖啡店帶來認同。"},{"en":"Recognition can bring pride because people feel their place or work has finally been seen.","zh":"認同可以帶來自豪，因為人們覺得自己的地方或工作終於被看見。"},{"en":"However, with popularity may also come pressure, crowds, and new problems.","zh":"然而，受歡迎也可能帶來壓力、人群和新問題。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"make a neighbourhood feel valued","meaning":"令社區感到受重視","examples":[{"en":"Recognition can make an ordinary neighbourhood feel valued.","zh":"認同可以令普通社區感到受重視。"},{"en":"To make a neighbourhood feel valued means to make residents feel their area is respected and appreciated.","zh":"make a neighbourhood feel valued 指令居民覺得自己的地區受到尊重和欣賞。"},{"en":"A community art project can make a neighbourhood feel valued by showing local stories.","zh":"社區藝術計劃可以透過展示本地故事，令社區感到受重視。"},{"en":"Praise from outsiders may make residents feel valued, especially if their area was once ignored.","zh":"外人的讚賞可能令居民感到受重視，尤其當該地區曾被忽略。"},{"en":"A neighbourhood feels valued when attention includes respect, not just photography.","zh":"當關注包括尊重，而不只是拍照時，社區才會感到受重視。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"ordinary neighbourhood","meaning":"普通社區","examples":[{"en":"Recognition can make an ordinary neighbourhood feel valued.","zh":"認同可以令普通社區感到受重視。"},{"en":"An ordinary neighbourhood is a normal local area where people live, shop, meet, and go about daily life.","zh":"ordinary neighbourhood 指人們居住、購物、見面和過日常生活的一般本地地區。"},{"en":"An ordinary neighbourhood may include small shops, schools, bus stops, and familiar faces.","zh":"普通社區可能包括小商店、學校、巴士站和熟悉面孔。"},{"en":"Ordinary neighbourhoods can become meaningful because of the memories people build there.","zh":"普通社區會因人們在那裏建立的記憶而變得有意義。"},{"en":"A place does not need luxury buildings to be an important ordinary neighbourhood.","zh":"一個地方不需要豪華建築，也可以是重要的普通社區。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"nevertheless","meaning":"然而","examples":[{"en":"Nevertheless, many residents are uncomfortable with the disturbance.","zh":"然而，許多居民對滋擾感到不舒服。"},{"en":"Nevertheless means however, or despite what has just been said.","zh":"nevertheless 指然而，或儘管剛才所說的情況如此。"},{"en":"The park is beautiful; nevertheless, nearby residents dislike the noise at night.","zh":"公園很美；然而，附近居民不喜歡晚上的噪音。"},{"en":"This word helps introduce a contrasting point after a positive idea.","zh":"這個詞幫助在正面想法後引入相反觀點。"},{"en":"Nevertheless is useful in essays because it shows balance and careful thinking.","zh":"nevertheless 在文章中很有用，因為它顯示平衡和仔細思考。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"be uncomfortable with","meaning":"對……感到不舒服","examples":[{"en":"Many residents are uncomfortable with the disturbance caused by visitors.","zh":"許多居民對訪客造成的滋擾感到不舒服。"},{"en":"To be uncomfortable with something means to feel uneasy, unhappy, or not relaxed about it.","zh":"be uncomfortable with 某事，指對它感到不自在、不高興或不放鬆。"},{"en":"Some students are uncomfortable with speaking in front of a large class.","zh":"有些學生對在大班面前說話感到不舒服。"},{"en":"Residents may be uncomfortable with strangers taking photos near their homes.","zh":"居民可能對陌生人在家附近拍照感到不舒服。"},{"en":"Being uncomfortable with something does not always mean rejecting it completely; it may mean wanting boundaries.","zh":"對某事感到不舒服不一定代表完全拒絕它；也可能代表想要界線。"}],"source":"2020 Q2.pdf","sourcePage":9},{"front":"disturbance created by","meaning":"由……造成的滋擾","examples":[{"en":"Residents dislike the disturbance created by Instagram tourism.","zh":"居民不喜歡由 Instagram 打卡旅遊造成的滋擾。"},{"en":"Disturbance created by something means noise, inconvenience, or disruption caused by that thing.","zh":"disturbance created by 某事，指由它造成的噪音、不便或打擾。"},{"en":"The disturbance created by roadworks can make it hard for students to concentrate.","zh":"由道路工程造成的滋擾，可能令學生難以專心。"},{"en":"Disturbance created by visitors may include shouting, blocking paths, and entering private spaces.","zh":"由訪客造成的滋擾可能包括大聲說話、阻塞通道和進入私人空間。"},{"en":"A problem feels worse when the disturbance is repeated every weekend.","zh":"當滋擾每個週末重複出現時，問題會感覺更嚴重。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"Instagram tourism","meaning":"Instagram 打卡旅遊","examples":[{"en":"Instagram tourism has brought both attention and disturbance.","zh":"Instagram 打卡旅遊帶來了關注，也帶來了滋擾。"},{"en":"Instagram tourism means visiting places mainly to take and share attractive photos on Instagram.","zh":"Instagram tourism 指主要為拍攝並分享吸引相片到 Instagram 而到訪地方。"},{"en":"A colourful staircase may become popular through Instagram tourism.","zh":"一條色彩繽紛的樓梯可能因 Instagram 打卡旅遊而受歡迎。"},{"en":"Instagram tourism can help people discover local places, but it may also disturb residents.","zh":"Instagram 打卡旅遊可以幫助人發現本地地方，但也可能滋擾居民。"},{"en":"Responsible Instagram tourism should respect the people who live near photo spots.","zh":"負責任的 Instagram 打卡旅遊應尊重住在拍照熱點附近的人。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"the complaint is not that..., but that...","meaning":"投訴的不是……而是……","examples":[{"en":"The complaint is not that visitors take photos, but that some forget people live there.","zh":"投訴的不是訪客拍照，而是有些人忘記那裏有人居住。"},{"en":"This pattern means the real problem is not the first thing mentioned, but the second thing.","zh":"這個句式指真正問題不是第一件提到的事，而是第二件事。"},{"en":"The complaint is not that students talk, but that they talk loudly during the lesson.","zh":"投訴的不是學生說話，而是他們在課堂中大聲說話。"},{"en":"This structure helps separate acceptable behaviour from the behaviour that causes harm.","zh":"這個結構有助區分可接受行為和造成傷害的行為。"},{"en":"Residents may accept photos, but not disrespectful behaviour around their homes.","zh":"居民可能接受拍照，但不接受在家附近不尊重他人的行為。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"first of all a home","meaning":"首先是一個家","examples":[{"en":"The estate is first of all a home.","zh":"這個屋邨首先是一個家。"},{"en":"First of all a home means the place’s most important identity is as a living space for residents.","zh":"first of all a home 指該地方最重要的身份是居民生活的空間。"},{"en":"A village may attract tourists, but it is first of all a home for local families.","zh":"一條村可能吸引遊客，但它首先是本地家庭的家。"},{"en":"Remembering that a place is first of all a home helps visitors behave more respectfully.","zh":"記得一個地方首先是一個家，能幫助訪客更尊重地行動。"},{"en":"A photo spot can still be first of all a home, not a public stage.","zh":"打卡地點仍然可以首先是一個家，而不是公共舞台。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"middle-aged resident","meaning":"中年居民","examples":[{"en":"A middle-aged resident described the problems caused by visitors.","zh":"一位中年居民描述訪客造成的問題。"},{"en":"A middle-aged resident is a person in the middle stage of adulthood who lives in a particular place.","zh":"middle-aged resident 指處於成年中期，並住在某個地方的人。"},{"en":"A middle-aged resident may worry about children, elderly parents, work, and neighbourhood safety.","zh":"中年居民可能要擔心孩子、年老父母、工作和社區安全。"},{"en":"Interviewing a middle-aged resident can reveal practical concerns about daily disturbance.","zh":"訪問中年居民可以揭示日常滋擾帶來的實際憂慮。"},{"en":"This perspective matters because middle-aged residents often manage family routines at home.","zh":"這個角度重要，因為中年居民常要管理家庭日常。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"block staircases","meaning":"阻塞樓梯","examples":[{"en":"Some visitors blocked staircases while taking photos.","zh":"有些訪客拍照時阻塞樓梯。"},{"en":"To block staircases means to stand or place things in stairways so people cannot pass easily.","zh":"block staircases 指站在或放東西在樓梯通道，使人難以通過。"},{"en":"Students block staircases when they sit on the steps during recess.","zh":"學生小息時坐在樓梯級上，就是阻塞樓梯。"},{"en":"Blocking staircases is dangerous because people may need to leave quickly in an emergency.","zh":"阻塞樓梯很危險，因為緊急情況下人們可能需要快速離開。"},{"en":"Visitors should never block staircases because residents use them for daily movement and safety.","zh":"訪客絕不應阻塞樓梯，因為居民日常通行和安全都需要使用樓梯。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"shout across","meaning":"隔着……大聲呼喊","examples":[{"en":"Some visitors shouted across the basketball court.","zh":"有些訪客隔着籃球場大聲呼喊。"},{"en":"To shout across a place means to speak very loudly from one side to another.","zh":"shout across 某地，指從一邊向另一邊大聲說話。"},{"en":"A student may shout across the playground to call a friend.","zh":"學生可能隔着操場大聲呼喊朋友。"},{"en":"Shouting across a shared space can disturb people who are resting, studying, or exercising.","zh":"隔着共享空間大聲呼喊，會滋擾正在休息、學習或運動的人。"},{"en":"Visitors should avoid shouting across housing estate spaces because sound travels easily between buildings.","zh":"訪客應避免隔着屋邨空間大聲呼喊，因為聲音很容易在樓宇之間傳開。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"take photos without permission","meaning":"未經同意拍照","examples":[{"en":"Some visitors took photos of residents without permission.","zh":"有些訪客未經同意拍攝居民。"},{"en":"To take photos without permission means to photograph people or private areas before asking if it is allowed.","zh":"take photos without permission 指在詢問是否可以之前，拍攝人物或私人地方。"},{"en":"A student should not take photos of classmates without permission.","zh":"學生不應未經同意拍攝同學。"},{"en":"Taking photos without permission can make people feel watched, exposed, or disrespected.","zh":"未經同意拍照會令人感到被注視、被暴露或不受尊重。"},{"en":"Asking first shows that the person in the photo has a choice.","zh":"先徵求同意顯示相中人有選擇權。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"harmless fun","meaning":"無傷大雅的玩樂","examples":[{"en":"What is harmless fun to one person may upset another person.","zh":"對一個人來說無傷大雅的玩樂，可能會令另一個人不快。"},{"en":"Harmless fun means enjoyable behaviour that seems to cause no damage or trouble.","zh":"harmless fun 指看似不造成傷害或麻煩的有趣行為。"},{"en":"Children may think ringing a doorbell and running away is harmless fun, but neighbours may feel annoyed.","zh":"孩子可能覺得按門鈴後跑走是無傷大雅的玩樂，但鄰居可能感到煩厭。"},{"en":"Something may look like harmless fun to visitors but feel intrusive to residents.","zh":"對訪客來說看似無傷大雅的玩樂，對居民可能感覺被打擾。"},{"en":"Before calling something harmless fun, people should ask who might be affected.","zh":"在稱某事為無傷大雅的玩樂前，人們應問誰可能受到影響。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"an invasion of privacy","meaning":"侵犯私隱","examples":[{"en":"Taking photos of residents without permission can be an invasion of privacy.","zh":"未經同意拍攝居民可能是侵犯私隱。"},{"en":"An invasion of privacy is an action that enters or exposes someone’s private life without proper respect or permission.","zh":"an invasion of privacy 指在沒有適當尊重或同意下進入或暴露某人的私人生活。"},{"en":"Reading someone’s messages without asking is an invasion of privacy.","zh":"未經詢問閱讀別人的訊息是侵犯私隱。"},{"en":"Photographing people at home can feel like an invasion of privacy because home should feel safe.","zh":"拍攝在家的人可能感覺像侵犯私隱，因為家應該令人感到安全。"},{"en":"Respecting privacy means knowing that not every visible moment is public property.","zh":"尊重私隱意味着明白不是每個可見時刻都是公共財產。"}],"source":"2020 Q2.pdf","sourcePage":10},{"front":"put it best","meaning":"說得最好；最能概括","examples":[{"en":"A young mother put it best when she asked visitors to remember people live there.","zh":"一位年輕母親說得最好，她請訪客記得有人住在那裏。"},{"en":"Put it best means expressed an idea most clearly or accurately.","zh":"put it best 指最清楚或最準確地表達一個想法。"},{"en":"The team captain put it best when she said winning matters less than learning together.","zh":"隊長說得最好，她說勝利不如一起學習重要。"},{"en":"Writers use this phrase when one person’s words summarise the whole issue well.","zh":"當某人的說話很好地總結整個問題時，作者會使用這個短語。"},{"en":"The young mother put it best because her sentence was simple, direct, and fair.","zh":"這位年輕母親說得最好，因為她的句子簡單、直接而公平。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"not mind visitors coming","meaning":"不介意訪客到來","examples":[{"en":"She did not mind visitors coming if they behaved respectfully.","zh":"如果訪客行為尊重，她不介意訪客到來。"},{"en":"Not mind visitors coming means not objecting to visitors arriving, as long as the situation is acceptable.","zh":"not mind visitors coming 指在情況可接受時，不反對訪客到來。"},{"en":"A shop owner may not mind students coming in if they keep the place tidy.","zh":"如果學生保持地方整潔，店主可能不介意學生進來。"},{"en":"Residents may not mind visitors coming when visitors stay quiet and avoid private areas.","zh":"當訪客保持安靜並避開私人範圍時，居民可能不介意訪客到來。"},{"en":"Not minding visitors does not mean accepting rude or careless behaviour.","zh":"不介意訪客到來，不代表接受無禮或粗心行為。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"provided that","meaning":"只要；假如","examples":[{"en":"She did not mind visitors coming, provided that they remembered people live there.","zh":"她不介意訪客到來，只要他們記得那裏有人居住。"},{"en":"Provided that means only if a certain condition is met.","zh":"provided that 指只有在某個條件達成時才可以。"},{"en":"Students may use the computer room, provided that they keep it clean.","zh":"學生可以使用電腦室，只要他們保持清潔。"},{"en":"Visitors may take photos, provided that they do not disturb residents.","zh":"訪客可以拍照，只要他們不滋擾居民。"},{"en":"This phrase is useful for setting clear limits while still allowing something.","zh":"這個短語有助在允許某事的同時設下清晰限制。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"remember people live here","meaning":"記得這裏有人居住","examples":[{"en":"Visitors should remember people live here.","zh":"訪客應記得這裏有人居住。"},{"en":"Remember people live here means keep in mind that this place is someone’s home, not only a public scene.","zh":"remember people live here 指記住這個地方是某人的家，不只是公共景象。"},{"en":"Tourists should remember people live here before taking photos near windows or doors.","zh":"遊客在窗戶或門口附近拍照前，應記得這裏有人居住。"},{"en":"When visitors remember people live here, they are more likely to lower their voices.","zh":"當訪客記得這裏有人居住時，他們較可能放低聲浪。"},{"en":"This simple reminder turns photo-taking into a more respectful act.","zh":"這個簡單提醒令拍照變成更尊重他人的行為。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"reveal the central tension","meaning":"揭示核心矛盾","examples":[{"en":"Her words reveal the central tension between visitors and residents.","zh":"她的說話揭示訪客與居民之間的核心矛盾。"},{"en":"To reveal the central tension means to show the main conflict or problem inside a situation.","zh":"reveal the central tension 指顯示一個情況中的主要衝突或問題。"},{"en":"A student’s complaint may reveal the central tension between exam pressure and creative learning.","zh":"學生的投訴可能揭示考試壓力與創意學習之間的核心矛盾。"},{"en":"The young mother’s words reveal the central tension between public attention and private life.","zh":"這位年輕母親的說話揭示公眾關注與私人生活之間的核心矛盾。"},{"en":"This phrase helps readers understand what the real issue is.","zh":"這個短語幫助讀者理解真正問題所在。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"central tension","meaning":"核心矛盾","examples":[{"en":"The central tension is between a photo backdrop and a private home.","zh":"核心矛盾在於拍照背景與私人家園之間。"},{"en":"Central tension means the main conflict that makes a situation difficult or complicated.","zh":"central tension 指令一個情況變得困難或複雜的主要衝突。"},{"en":"In many schools, the central tension is between high exam results and students’ wellbeing.","zh":"在許多學校，核心矛盾在於高考試成績與學生身心健康之間。"},{"en":"The central tension in Instagram tourism is that one place can be both public image and private home.","zh":"Instagram 打卡旅遊的核心矛盾是，同一個地方可以同時是公共影像和私人家園。"},{"en":"Understanding the central tension helps people look for fair solutions.","zh":"理解核心矛盾有助人們尋找公平解決方法。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"see a backdrop","meaning":"視為背景","examples":[{"en":"Instagrammers may see a backdrop, but residents see their homes.","zh":"Instagram 用戶可能視它為背景，但居民看見的是自己的家。"},{"en":"To see a backdrop means to view a place mainly as a background for photos.","zh":"see a backdrop 指主要把一個地方視為拍照背景。"},{"en":"Tourists may see a colourful street as a backdrop while shopkeepers see their workplace.","zh":"遊客可能把一條彩色街道視為背景，而店主看見的是自己的工作場所。"},{"en":"Seeing only a backdrop can make people ignore daily life and personal privacy.","zh":"只視為背景會令人忽視日常生活和個人私隱。"},{"en":"Visitors should look beyond the backdrop and notice the community around them.","zh":"訪客應看見背景以外的東西，注意身邊的社區。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"front door","meaning":"家門口","examples":[{"en":"Residents see their front door, their safety and their privacy.","zh":"居民看見的是自己的家門口、安全和私隱。"},{"en":"A front door is the main entrance to someone’s home.","zh":"front door 指某人住所的主要入口。"},{"en":"People usually feel protective of their front door because it marks the boundary between public and private life.","zh":"人們通常會保護自己的家門口，因為它標示公共生活與私人生活的界線。"},{"en":"Taking photos near someone’s front door may make them feel exposed.","zh":"在某人家門口附近拍照，可能令對方感到被暴露。"},{"en":"A front door is not just an object in a photo; it is part of someone’s private space.","zh":"家門口不只是相片中的物件；它是某人私人空間的一部分。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"right to live without being watched","meaning":"不被注視地生活的權利","examples":[{"en":"Residents have the right to live without being watched.","zh":"居民有不被注視地生活的權利。"},{"en":"The right to live without being watched means people should be able to live privately without constant attention from strangers.","zh":"right to live without being watched 指人們應能在沒有陌生人持續注視下私人地生活。"},{"en":"Children have the right to play near home without being photographed by unknown visitors.","zh":"孩子有權在家附近玩耍，而不被陌生訪客拍攝。"},{"en":"This right matters because home should feel safe, ordinary, and free from unwanted observation.","zh":"這項權利很重要，因為家應該令人感到安全、平常，並免受不想要的觀察。"},{"en":"Respectful visitors remember that residents’ privacy is more important than a perfect photo.","zh":"尊重他人的訪客會記得，居民私隱比完美相片更重要。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, Instagram popularity brings both benefits and risks.","zh":"總括而言，Instagram 的受歡迎程度帶來好處，也帶來風險。"},{"en":"All things considered means after thinking about all the important points.","zh":"all things considered 指在考慮所有重要因素之後。"},{"en":"All things considered, the school trip was successful despite the rain.","zh":"總括而言，雖然下雨，學校旅行仍算成功。"},{"en":"Writers use this phrase near a conclusion to give a balanced judgement.","zh":"作者常在結論附近使用這個短語，以作出平衡判斷。"},{"en":"All things considered, photo tourism should be welcomed only when it respects residents.","zh":"總括而言，只有在尊重居民時，打卡旅遊才應被歡迎。"}],"source":"2020 Q2.pdf","sourcePage":11},{"front":"the power and the danger of","meaning":"……的力量與危險","examples":[{"en":"The essay shows the power and the danger of visual culture.","zh":"這篇文章展示視覺文化的力量與危險。"},{"en":"The power and the danger of something means both its ability to do good and its ability to cause harm.","zh":"the power and the danger of 某事，指它做好事的能力和造成傷害的能力。"},{"en":"The internet shows the power and the danger of fast information.","zh":"互聯網展示快速資訊的力量與危險。"},{"en":"Visual culture has power because it can change opinions, but danger because it can simplify real lives.","zh":"視覺文化有力量，因為它能改變觀點；但也有危險，因為它能簡化真實生活。"},{"en":"This phrase is useful when one thing has both positive and negative effects.","zh":"當某事物同時有正面和負面影響時，這個短語很有用。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"visual culture","meaning":"視覺文化","examples":[{"en":"Instagram shows the power and danger of visual culture.","zh":"Instagram 展示視覺文化的力量與危險。"},{"en":"Visual culture means the way images, designs, colours, and screens shape how people see the world.","zh":"visual culture 指影像、設計、色彩和屏幕如何塑造人們看世界的方式。"},{"en":"Advertising is part of visual culture because it uses images to influence choices.","zh":"廣告是視覺文化的一部分，因為它使用影像影響選擇。"},{"en":"Visual culture can make ordinary places famous when people repeatedly share attractive photos.","zh":"當人們反覆分享吸引的相片時，視覺文化可以令普通地方成名。"},{"en":"Visual culture is powerful because people often believe what they see before asking deeper questions.","zh":"視覺文化很有力量，因為人們常在提出更深問題前先相信自己所見。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"combine colour, geometry and local character","meaning":"結合色彩、幾何感和本地特色","examples":[{"en":"The estates combine colour, geometry and local character.","zh":"這些屋邨結合色彩、幾何感和本地特色。"},{"en":"To combine colour, geometry and local character means to bring together bright design, shapes, and a sense of place.","zh":"combine colour, geometry and local character 指把鮮明設計、形狀和地方感結合起來。"},{"en":"A market mural may combine colour, geometry and local character by using patterns from nearby streets.","zh":"街市壁畫可以使用附近街道的圖案，結合色彩、幾何感和本地特色。"},{"en":"This combination makes photos attractive while still feeling connected to the neighbourhood.","zh":"這種結合令相片吸引，同時仍與社區相連。"},{"en":"Places with colour, geometry and local character often stand out online.","zh":"具有色彩、幾何感和本地特色的地方，常在網上突出。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"online appeal","meaning":"網上吸引力","examples":[{"en":"Housing estates have strong online appeal.","zh":"屋邨有很強的網上吸引力。"},{"en":"Online appeal means the ability to attract attention, likes, shares, or interest on the internet.","zh":"online appeal 指在互聯網上吸引注意、讚好、分享或興趣的能力。"},{"en":"A simple recipe video may have online appeal because it is easy to understand quickly.","zh":"簡單食譜影片可能有網上吸引力，因為它很容易快速理解。"},{"en":"Bright colours and clear patterns increase online appeal because they look good on small screens.","zh":"鮮明色彩和清晰圖案增加網上吸引力，因為它們在小屏幕上好看。"},{"en":"Online appeal can make a place famous, but it does not automatically make visitors respectful.","zh":"網上吸引力可以令一個地方成名，但不會自動令訪客變得尊重。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"purpose-built attractions","meaning":"特意建造的景點","examples":[{"en":"Few purpose-built attractions can match the appeal of older estates.","zh":"很少特意建造的景點能媲美較舊屋邨的吸引力。"},{"en":"Purpose-built attractions are places specially designed to attract visitors.","zh":"purpose-built attractions 指專門為吸引訪客而設計的地方。"},{"en":"A theme park ride is a purpose-built attraction because it is created for entertainment.","zh":"主題公園機動遊戲是特意建造的景點，因為它為娛樂而創造。"},{"en":"Purpose-built attractions may be impressive, but they can feel less authentic than real neighbourhoods.","zh":"特意建造的景點可能令人印象深刻，但可能不如真實社區那麼真實。"},{"en":"Older estates attract some visitors precisely because they were not purpose-built attractions.","zh":"較舊屋邨吸引一些訪客，正是因為它們不是特意建造的景點。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"respond with mixed feelings","meaning":"以複雜心情回應","examples":[{"en":"Residents respond with mixed feelings to Instagram tourism.","zh":"居民以複雜心情回應 Instagram 打卡旅遊。"},{"en":"To respond with mixed feelings means to react with both positive and negative emotions.","zh":"respond with mixed feelings 指以正面和負面情緒同時回應。"},{"en":"A student may respond with mixed feelings to moving schools because they feel excited but nervous.","zh":"學生轉校時可能以複雜心情回應，因為既興奮又緊張。"},{"en":"Residents respond with mixed feelings when fame brings recognition but also disturbance.","zh":"當名氣帶來認同但也帶來滋擾時，居民會以複雜心情回應。"},{"en":"This phrase helps show emotional balance rather than a simple yes or no reaction.","zh":"這個短語有助顯示情緒上的平衡，而不是簡單的接受或拒絕。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"mixed feelings","meaning":"複雜心情","examples":[{"en":"Residents have mixed feelings about their estate becoming famous.","zh":"居民對自己的屋邨變得有名有複雜心情。"},{"en":"Mixed feelings are different emotions felt at the same time, often both good and bad.","zh":"mixed feelings 指同時出現不同情緒，通常有好也有壞。"},{"en":"A person may have mixed feelings about leaving home for university.","zh":"一個人離家上大學時，可能有複雜心情。"},{"en":"Mixed feelings appear when one event brings both opportunity and worry.","zh":"當一件事同時帶來機會和憂慮時，就會出現複雜心情。"},{"en":"Residents’ mixed feelings make sense because fame can bring pride and inconvenience together.","zh":"居民有複雜心情是合理的，因為名氣可以同時帶來自豪和不便。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"neighbourhood is appreciated","meaning":"社區受到欣賞","examples":[{"en":"Residents feel pride when their neighbourhood is appreciated.","zh":"當社區受到欣賞時，居民會感到自豪。"},{"en":"When a neighbourhood is appreciated, people recognise its value, beauty, or importance.","zh":"neighbourhood is appreciated 指人們認可該社區的價值、美感或重要性。"},{"en":"A neighbourhood is appreciated when visitors praise its old shops and local stories.","zh":"當訪客讚賞舊店舖和本地故事時，社區就是受到欣賞。"},{"en":"Residents may feel respected when the neighbourhood they love is appreciated by outsiders.","zh":"當外人欣賞居民所愛的社區時，居民可能感到受尊重。"},{"en":"Appreciation should include good behaviour, not only compliments and photos.","zh":"欣賞應包括良好行為，而不只是稱讚和拍照。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"frustration","meaning":"挫敗感；不滿","examples":[{"en":"Residents feel frustration when visitors disturb their peace.","zh":"當訪客打擾居民安寧時，居民會感到不滿。"},{"en":"Frustration is the unhappy feeling people have when something blocks, annoys, or disappoints them.","zh":"frustration 指當某事阻礙、煩擾或令人失望時產生的不快感覺。"},{"en":"A student may feel frustration when the internet fails during an online test.","zh":"學生在網上測驗期間網絡失靈，可能會感到挫敗。"},{"en":"Repeated noise creates frustration because residents cannot rest properly at home.","zh":"重複的噪音會造成不滿，因為居民不能在家好好休息。"},{"en":"Frustration grows when people feel their concerns are ignored.","zh":"當人們覺得自己的憂慮被忽視時，挫敗感會增加。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"come at the cost of","meaning":"以犧牲……為代價","examples":[{"en":"Appreciation should not come at the cost of privacy and peace.","zh":"欣賞不應以犧牲私隱與安寧為代價。"},{"en":"To come at the cost of something means to bring one benefit while damaging or sacrificing another thing.","zh":"come at the cost of 某事，指得到一種好處時損害或犧牲另一件事。"},{"en":"Good exam results should not come at the cost of students’ health.","zh":"好考試成績不應以犧牲學生健康為代價。"},{"en":"Tourism becomes unfair when visitors’ enjoyment comes at the cost of residents’ daily life.","zh":"當訪客享樂以犧牲居民日常生活為代價時，旅遊就變得不公平。"},{"en":"This phrase warns that success is not always worth the price paid.","zh":"這個短語提醒我們，成功不一定值得付出那個代價。"}],"source":"2020 Q2.pdf","sourcePage":12},{"front":"privacy and peace","meaning":"私隱與安寧","examples":[{"en":"Residents want to protect their privacy and peace.","zh":"居民想保護自己的私隱與安寧。"},{"en":"Privacy and peace mean personal space, quiet, safety, and freedom from unwanted attention.","zh":"privacy and peace 指個人空間、寧靜、安全和免受不想要的關注。"},{"en":"Families need privacy and peace at home after a long day of work or school.","zh":"經過漫長工作或上學一天後，家庭在家中需要私隱與安寧。"},{"en":"Loud visitors and unwanted photos can damage residents’ privacy and peace.","zh":"喧鬧訪客和未經同意的相片會損害居民的私隱與安寧。"},{"en":"Respecting privacy and peace is basic when visiting any living community.","zh":"到訪任何仍有人生活的社區時，尊重私隱與安寧是基本要求。"}],"source":"2020 Q2.pdf","sourcePage":13},{"front":"the way forward","meaning":"未來方向；解決方法","examples":[{"en":"The way forward is to build a more respectful photo culture.","zh":"未來方向是建立更尊重他人的拍照文化。"},{"en":"The way forward means the best future solution or next direction.","zh":"the way forward 指最佳的未來解決方法或下一步方向。"},{"en":"If a class has many conflicts, the way forward may be clearer rules and better listening.","zh":"如果班上有很多衝突，解決方法可能是更清晰規則和更好聆聽。"},{"en":"The way forward should solve the problem without destroying what is valuable.","zh":"未來方向應解決問題，而不破壞有價值的東西。"},{"en":"For Instagram tourism, the way forward is respect, not a complete ban.","zh":"對 Instagram 打卡旅遊而言，未來方向是尊重，而不是完全禁止。"}],"source":"2020 Q2.pdf","sourcePage":13},{"front":"ban visitors","meaning":"禁止訪客","examples":[{"en":"The solution is not to ban visitors completely.","zh":"解決方法不是完全禁止訪客。"},{"en":"To ban visitors means to officially stop visitors from entering or using a place.","zh":"ban visitors 指正式禁止訪客進入或使用某地方。"},{"en":"A school may ban visitors from entering classrooms during lessons for safety reasons.","zh":"學校可能為安全理由禁止訪客在上課期間進入課室。"},{"en":"Banning visitors completely may reduce disturbance, but it can also close off public appreciation.","zh":"完全禁止訪客可能減少滋擾，但也可能關閉公眾欣賞的機會。"},{"en":"A better solution may be clear rules rather than a full ban.","zh":"較好的解決方法可能是清晰規則，而不是全面禁止。"}],"source":"2020 Q2.pdf","sourcePage":13},{"front":"build a more respectful photo culture","meaning":"建立更尊重他人的拍照文化","examples":[{"en":"Hong Kong needs to build a more respectful photo culture.","zh":"香港需要建立更尊重他人的拍照文化。"},{"en":"To build a more respectful photo culture means to create habits of taking photos that consider other people’s rights and feelings.","zh":"build a more respectful photo culture 指建立拍照時考慮他人權利和感受的習慣。"},{"en":"Schools can build a more respectful photo culture by teaching students to ask before photographing classmates.","zh":"學校可以透過教學生拍攝同學前先詢問，建立更尊重他人的拍照文化。"},{"en":"A respectful photo culture reduces conflict because visitors know how to behave.","zh":"尊重他人的拍照文化能減少衝突，因為訪客知道如何行事。"},{"en":"This culture values good photos, but values people’s dignity more.","zh":"這種文化重視好相片，但更重視人的尊嚴。"}],"source":"2020 Q2.pdf","sourcePage":13},{"front":"asking permission","meaning":"徵求同意","examples":[{"en":"Asking permission is important before taking photos of residents.","zh":"拍攝居民前，徵求同意很重要。"},{"en":"Asking permission means checking whether someone agrees before you do something involving them.","zh":"asking permission 指在做涉及某人的事情前，先詢問對方是否同意。"},{"en":"Students should ask permission before using a classmate’s photo in a project.","zh":"學生在專題中使用同學相片前，應徵求同意。"},{"en":"Asking permission protects privacy because people can say yes or no.","zh":"徵求同意能保護私隱，因為人們可以選擇同意或拒絕。"},{"en":"A simple question before taking a photo can show real respect.","zh":"拍照前簡單問一句，可以顯示真正尊重。"}],"source":"2020 Q2.pdf","sourcePage":13},{"front":"keeping voices down","meaning":"放低聲浪","examples":[{"en":"Visitors should respect residents by keeping voices down.","zh":"訪客應透過放低聲浪來尊重居民。"},{"en":"Keeping voices down means speaking more quietly so other people are not disturbed.","zh":"keeping voices down 指說話較小聲，以免滋擾他人。"},{"en":"Students keep their voices down in the library because others are studying.","zh":"學生在圖書館放低聲浪，因為其他人在學習。"},{"en":"Keeping voices down in housing estates helps residents rest, study, and care for family members.","zh":"在屋邨放低聲浪有助居民休息、學習和照顧家人。"},{"en":"This small action can make visitors much less disruptive.","zh":"這個小行動可以大大減少訪客造成的滋擾。"}],"source":"2020 Q2.pdf","sourcePage":13},{"front":"avoiding private areas","meaning":"避開私人範圍","examples":[{"en":"Visitors should avoid private areas when taking photos.","zh":"訪客拍照時應避開私人範圍。"},{"en":"Avoiding private areas means staying away from spaces that belong to residents or are not meant for public use.","zh":"avoiding private areas 指遠離屬於居民或不供公眾使用的空間。"},{"en":"Tourists should avoid private areas such as doorways, corridors near homes, and laundry spaces.","zh":"遊客應避開家門口、住宅附近走廊和晾衣空間等私人範圍。"},{"en":"Avoiding private areas prevents people from feeling watched or unsafe.","zh":"避開私人範圍能防止人們感到被注視或不安全。"},{"en":"A good photo is not worth entering a space where residents expect privacy.","zh":"好相片不值得令人進入居民期望有私隱的空間。"}],"source":"2020 Q2.pdf","sourcePage":13},{"front":"treat every estate as a community","meaning":"把每個屋邨視為社區","examples":[{"en":"Visitors should treat every estate as a community.","zh":"訪客應把每個屋邨視為社區。"},{"en":"To treat every estate as a community means to see it as a place where people live together, not just a scene.","zh":"treat every estate as a community 指把屋邨看作人們共同生活的地方，而不只是景象。"},{"en":"Students visiting an old neighbourhood should treat it as a community by speaking politely and observing respectfully.","zh":"學生到訪舊社區時，應透過禮貌說話和尊重觀察，把它視為社區。"},{"en":"When visitors treat an estate as a community, they are less likely to block paths or invade privacy.","zh":"當訪客把屋邨視為社區時，他們較不會阻塞通道或侵犯私隱。"},{"en":"This attitude helps balance appreciation with respect.","zh":"這種態度有助在欣賞與尊重之間取得平衡。"}],"source":"2020 Q2.pdf","sourcePage":13},{"front":"rather than simply a stage","meaning":"而不只是舞台","examples":[{"en":"Visitors should treat the estate as a community rather than simply a stage.","zh":"訪客應把屋邨視為社區，而不只是舞台。"},{"en":"Rather than simply a stage means not just as a place for performance, display, or posing.","zh":"rather than simply a stage 指不只是把它當成表演、展示或擺姿勢的地方。"},{"en":"A school hall should be treated as a learning space rather than simply a stage for photos.","zh":"學校禮堂應被視為學習空間，而不只是拍照舞台。"},{"en":"If visitors see a neighbourhood simply as a stage, they may forget the people who live there.","zh":"如果訪客只把社區視為舞台，他們可能忘記住在那裏的人。"},{"en":"Treating an estate as a community rather than simply a stage makes photography more respectful.","zh":"把屋邨視為社區，而不只是舞台，會令拍照更尊重他人。"}],"source":"2020 Q2.pdf","sourcePage":13}],"dse/writing/part-b/2020/Q3":[{"front":"independent stationery shops","meaning":"獨立文具店","examples":[{"en":"Independent stationery shops are fighting for survival as Hong Kong goes digital.","zh":"隨着香港數碼化，獨立文具店正為生存而掙扎。"},{"en":"Independent stationery shops are small stationery businesses that are not part of a large chain.","zh":"獨立文具店是不屬於大型連鎖集團的小型文具生意。"},{"en":"Students may visit independent stationery shops near school to buy pens, notebooks, and art paper.","zh":"學生可能會到學校附近的獨立文具店購買筆、筆記簿和美術紙。"},{"en":"Independent stationery shops can struggle when rent rises and customers buy supplies online.","zh":"當租金上升、顧客在網上購買用品時，獨立文具店可能會經營困難。"},{"en":"Independent stationery shops survive best when they offer service that big stores cannot copy.","zh":"獨立文具店如果能提供大型店舖無法複製的服務，就最有機會生存。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"fight for survival","meaning":"為生存而掙扎","examples":[{"en":"Independent stationery shops are fighting for survival.","zh":"獨立文具店正為生存而掙扎。"},{"en":"To fight for survival means to struggle hard to stay alive or continue operating.","zh":"fight for survival 指努力掙扎，以求生存或繼續經營。"},{"en":"A small café may fight for survival when a large chain opens nearby.","zh":"當大型連鎖店在附近開張，一間小咖啡店可能要為生存而掙扎。"},{"en":"If costs rise but sales fall, a shop has to fight for survival.","zh":"如果成本上升但銷售下降，店舖就要為生存而掙扎。"},{"en":"These stationery shops are not simply trying to grow; they are fighting for survival.","zh":"這些文具店不只是想發展；它們是在為生存而掙扎。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"go digital","meaning":"數碼化","examples":[{"en":"Hong Kong is going digital, and small shops are under pressure.","zh":"香港正在數碼化，小店因而承受壓力。"},{"en":"To go digital means to use more online tools, electronic systems, or digital services.","zh":"go digital 指更多使用網上工具、電子系統或數碼服務。"},{"en":"Schools go digital when teachers use tablets, e-notes, and online worksheets.","zh":"當老師使用平板電腦、電子筆記和網上工作紙時，學校就是在數碼化。"},{"en":"When customers go digital, they may buy fewer things from physical shops.","zh":"當顧客轉向數碼化，他們可能會較少到實體店購物。"},{"en":"Going digital can save time, but it can also hurt shops that depend on walk-in customers.","zh":"數碼化可以節省時間，但也可能傷害依賴路過顧客的店舖。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"in recent years","meaning":"近年","examples":[{"en":"In recent years, small stationery shops have become less common.","zh":"近年，小型文具店變得較少見。"},{"en":"In recent years means during the last few years, not long ago.","zh":"in recent years 指在過去幾年，即不久之前的一段時間。"},{"en":"In recent years, more students have used tablets for homework.","zh":"近年，更多學生使用平板電腦做功課。"},{"en":"In recent years, online shopping has changed how families buy daily goods.","zh":"近年，網上購物改變了家庭購買日用品的方式。"},{"en":"In recent years, many familiar neighbourhood shops have slowly disappeared.","zh":"近年，許多熟悉的社區小店慢慢消失。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"the sight of","meaning":"……的景象","examples":[{"en":"The sight of small stationery shops beside schools has become less common.","zh":"學校旁邊小型文具店的景象已變得較少見。"},{"en":"The sight of something means the scene or image of seeing it.","zh":"the sight of something 指看見某事物時的景象或畫面。"},{"en":"The sight of children buying stickers after school once made the street lively.","zh":"孩子放學後買貼紙的景象，曾令街道充滿生氣。"},{"en":"When shops close, the sight of empty shutters can make a neighbourhood feel colder.","zh":"當店舖結業，空置鐵閘的景象會令社區感覺更冷清。"},{"en":"The sight of a tiny stationery shop can remind people of school days.","zh":"一間小小文具店的景象，可以令人想起學生時代。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"tucked beside","meaning":"隱身於……旁邊","examples":[{"en":"Small stationery shops were often tucked beside schools and housing estates.","zh":"小型文具店常隱身於學校和屋邨旁邊。"},{"en":"Tucked beside means placed quietly or neatly next to something, often in a small space.","zh":"tucked beside 指安靜或整齊地位於某物旁邊，通常在小空間裏。"},{"en":"A tiny bakery was tucked beside the MTR exit.","zh":"一間小麵包店隱身於港鐵出口旁邊。"},{"en":"Shops tucked beside schools can catch students on their way home.","zh":"隱身於學校旁邊的店舖，可以吸引放學回家的學生。"},{"en":"A stationery shop tucked beside a housing estate feels close to daily life.","zh":"一間隱身於屋邨旁邊的文具店，感覺貼近日常生活。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"housing estates","meaning":"屋邨","examples":[{"en":"Independent stationery shops used to be common beside schools and housing estates.","zh":"獨立文具店過去常見於學校和屋邨旁邊。"},{"en":"Housing estates are groups of residential buildings where many families live.","zh":"housing estates 是許多家庭居住的一組住宅樓宇。"},{"en":"A housing estate may have shops, playgrounds, schools, and clinics nearby.","zh":"屋邨附近可能有商店、遊樂場、學校和診所。"},{"en":"Shops near housing estates can depend on regular customers from the neighbourhood.","zh":"屋邨附近的店舖可以依賴社區中的固定顧客。"},{"en":"When a housing estate loses small shops, daily life becomes less convenient.","zh":"當屋邨失去小店，日常生活會變得不太方便。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"become less common","meaning":"變得較少見","examples":[{"en":"The sight of these shops has become less common.","zh":"這些店舖的景象已變得較少見。"},{"en":"Become less common means appear or happen less often than before.","zh":"become less common 指比以前較少出現或較少發生。"},{"en":"Paying with coins has become less common as people use mobile payment.","zh":"隨着人們使用流動支付，用硬幣付款已變得較少見。"},{"en":"If students buy supplies online, visits to stationery shops become less common.","zh":"如果學生在網上購買用品，到文具店購物就會變得較少見。"},{"en":"Small shops become less common when rent and competition both increase.","zh":"當租金和競爭同時增加，小店會變得較少見。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"rising rents","meaning":"租金上升","examples":[{"en":"Rising rents have put pressure on small stationery shops.","zh":"租金上升令小型文具店承受壓力。"},{"en":"Rising rents mean shop owners must pay more money to use their premises.","zh":"rising rents 指店主要支付更多錢來使用店舖地方。"},{"en":"Rising rents can force a family restaurant to raise prices.","zh":"租金上升可能迫使家庭餐廳加價。"},{"en":"If sales stay low while rents rise, small shops may close.","zh":"如果銷售保持低迷而租金上升，小店可能會結業。"},{"en":"Rising rents hurt independent shops more because their profits are usually small.","zh":"租金上升對獨立小店傷害更大，因為它們的利潤通常較少。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"changing study habits","meaning":"學習習慣改變","examples":[{"en":"Changing study habits have affected the stationery business.","zh":"學習習慣改變影響了文具生意。"},{"en":"Changing study habits means students are learning and preparing schoolwork in new ways.","zh":"changing study habits 指學生以新的方式學習和準備功課。"},{"en":"Students use fewer notebooks when changing study habits include tablets and e-notes.","zh":"當學習習慣改變，包括使用平板電腦和電子筆記時，學生會較少使用筆記簿。"},{"en":"Changing study habits can reduce demand for pens, folders, and printed worksheets.","zh":"學習習慣改變可以減少對筆、文件夾和印刷工作紙的需求。"},{"en":"Stationery shops must understand changing study habits if they want to stay useful.","zh":"文具店如果想保持有用，就必須理解學習習慣改變。"}],"source":"2020 Q3.pdf","sourcePage":1},{"front":"online shopping","meaning":"網上購物","examples":[{"en":"Online shopping has changed how families buy stationery.","zh":"網上購物改變了家庭購買文具的方式。"},{"en":"Online shopping means buying goods through websites or apps instead of visiting a shop.","zh":"online shopping 指透過網站或應用程式購物，而不是親身到店舖。"},{"en":"Parents use online shopping to compare prices before buying school supplies.","zh":"家長使用網上購物，在購買學校用品前比較價格。"},{"en":"Online shopping can reduce foot traffic because customers no longer need to enter nearby shops.","zh":"網上購物可以減少客流，因為顧客不再需要走進附近店舖。"},{"en":"Online shopping is convenient, but it can make neighbourhood shops weaker.","zh":"網上購物很方便，但也可能令社區小店變弱。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"turn something into","meaning":"把……變成","examples":[{"en":"Online shopping has turned a stable business into a fragile trade.","zh":"網上購物把一門穩定的生意變成脆弱的行業。"},{"en":"To turn something into something else means to change it into a different form or condition.","zh":"turn something into something else 指把某物改變成另一種形式或狀態。"},{"en":"Good lighting can turn a small room into a comfortable study area.","zh":"良好的燈光可以把小房間變成舒適的溫習區。"},{"en":"Rising costs can turn a profitable shop into a struggling business.","zh":"成本上升可以把有利潤的店舖變成苦苦掙扎的生意。"},{"en":"Technology can turn old habits into new routines very quickly.","zh":"科技可以很快把舊習慣變成新常規。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"a once-stable neighbourhood business","meaning":"曾經穩定的社區生意","examples":[{"en":"Stationery shops were once a stable neighbourhood business.","zh":"文具店曾經是穩定的社區生意。"},{"en":"A once-stable neighbourhood business is a local business that used to be steady and reliable.","zh":"a once-stable neighbourhood business 指過去穩定可靠的本地社區生意。"},{"en":"A family bakery may be a once-stable neighbourhood business if fewer people now buy bread there.","zh":"如果現在較少人在家庭麵包店買麵包，它可能成為一門曾經穩定的社區生意。"},{"en":"When habits change, a once-stable neighbourhood business can suddenly face risk.","zh":"當習慣改變，曾經穩定的社區生意可能突然面對風險。"},{"en":"Stationery shops became vulnerable after this once-stable neighbourhood business lost daily customers.","zh":"這門曾經穩定的社區生意失去每日顧客後，文具店變得脆弱。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"a fragile trade","meaning":"脆弱的行業","examples":[{"en":"Stationery retail has become a fragile trade.","zh":"文具零售已變成一個脆弱的行業。"},{"en":"A fragile trade is a business area that can be easily damaged by small changes.","zh":"a fragile trade 指容易被小改變傷害的行業。"},{"en":"A flower shop can become a fragile trade if rent rises and customers order online.","zh":"如果租金上升、顧客在網上下單，花店也可能變成脆弱的行業。"},{"en":"A fragile trade may suffer when one school changes its buying system.","zh":"當一間學校改變採購制度，脆弱的行業可能會受影響。"},{"en":"Stationery is now a fragile trade because profits are thin and demand is changing.","zh":"文具現在是脆弱的行業，因為利潤微薄而需求正在改變。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"the decline","meaning":"衰落；下滑","examples":[{"en":"The decline has worried shop owners and community groups.","zh":"這種衰落令店主和社區團體擔心。"},{"en":"The decline means a fall or weakening in number, strength, or success.","zh":"the decline 指數量、力量或成功程度下降或變弱。"},{"en":"The decline of local markets worries older residents who use them daily.","zh":"本地街市的衰落令每天使用它們的長者居民擔心。"},{"en":"A decline in sales can make shop owners reduce opening hours.","zh":"銷售下滑可能令店主縮短營業時間。"},{"en":"The decline of stationery shops is not just economic; it also changes community life.","zh":"文具店的衰落不只是經濟問題，也改變社區生活。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"shop owners","meaning":"店主","examples":[{"en":"Shop owners are asking whether these stores still have a future.","zh":"店主正在問這些店舖是否仍有未來。"},{"en":"Shop owners are people who own and usually manage shops.","zh":"shop owners 指擁有並通常管理店舖的人。"},{"en":"Shop owners decide what products to sell and how to serve customers.","zh":"店主決定出售甚麼產品，以及如何服務顧客。"},{"en":"When rent rises, shop owners must decide whether they can continue.","zh":"當租金上升，店主必須決定是否能繼續經營。"},{"en":"Many shop owners know their regular customers by name.","zh":"許多店主都認得固定顧客的名字。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"community groups","meaning":"社區團體","examples":[{"en":"Community groups are concerned about the loss of local shops.","zh":"社區團體關注本地店舖流失。"},{"en":"Community groups are organisations formed by residents to support local needs.","zh":"community groups 是由居民組成、支援本地需要的組織。"},{"en":"Community groups may organise events to help small businesses.","zh":"社區團體可能舉辦活動來幫助小商戶。"},{"en":"If community groups speak up, landlords and schools may notice local concerns.","zh":"如果社區團體發聲，業主和學校可能會注意到本地憂慮。"},{"en":"Community groups care about stationery shops because they are part of neighbourhood life.","zh":"社區團體關心文具店，因為它們是社區生活的一部分。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"have a place in","meaning":"在……中佔一席位","examples":[{"en":"These stores may still have a place in Hong Kong’s retail landscape.","zh":"這些店舖可能仍在香港零售格局中佔一席位。"},{"en":"To have a place in something means to still be useful, accepted, or needed there.","zh":"have a place in something 指在某個環境中仍然有用、被接受或被需要。"},{"en":"Libraries still have a place in education, even when students use the internet.","zh":"即使學生使用互聯網，圖書館仍在教育中佔一席位。"},{"en":"Small shops have a place in a neighbourhood if they provide personal service.","zh":"如果小店提供個人化服務，它們仍能在社區中佔一席位。"},{"en":"Stationery shops can have a place in Hong Kong if they become more specialised.","zh":"如果文具店變得更專門化，它們仍能在香港佔一席位。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"retail landscape","meaning":"零售格局","examples":[{"en":"The stores are struggling within Hong Kong’s retail landscape.","zh":"這些店舖正在香港零售格局中掙扎。"},{"en":"The retail landscape means the overall situation of shops, customers, rents, and competition.","zh":"retail landscape 指店舖、顧客、租金和競爭的整體情況。"},{"en":"Online platforms have changed the retail landscape for bookstores.","zh":"網上平台改變了書店的零售格局。"},{"en":"When the retail landscape changes, small businesses must adjust quickly.","zh":"當零售格局改變，小商戶必須快速調整。"},{"en":"Hong Kong’s retail landscape is difficult for shops with thin profits.","zh":"香港的零售格局對利潤微薄的店舖來說十分困難。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"under serious pressure","meaning":"承受沉重壓力","examples":[{"en":"Independent stationery shops are under serious pressure.","zh":"獨立文具店正承受沉重壓力。"},{"en":"Under serious pressure means facing strong difficulty, stress, or threat.","zh":"under serious pressure 指面對很大的困難、壓力或威脅。"},{"en":"A student is under serious pressure when several exams happen in one week.","zh":"如果一星期內有幾場考試，學生就會承受沉重壓力。"},{"en":"Shops are under serious pressure when rent, wages, and competition all increase.","zh":"當租金、工資和競爭同時增加，店舖就會承受沉重壓力。"},{"en":"Under serious pressure, some owners may change their business or close.","zh":"在沉重壓力下，有些店主可能會轉型或結業。"}],"source":"2020 Q3.pdf","sourcePage":2},{"front":"competing as ordinary retailers","meaning":"以普通零售商身分競爭","examples":[{"en":"They cannot survive by competing as ordinary retailers.","zh":"它們不能靠以普通零售商身分競爭而生存。"},{"en":"Competing as ordinary retailers means trying to win customers only by selling common goods like normal shops.","zh":"competing as ordinary retailers 指像一般店舖一樣，只靠出售普通貨品來爭取顧客。"},{"en":"Small shops lose money when they compete as ordinary retailers against big chains.","zh":"小店與大型連鎖店以普通零售商身分競爭時，容易虧蝕。"},{"en":"If everyone sells the same pens, competing as ordinary retailers becomes very difficult.","zh":"如果所有人都賣相同的筆，以普通零售商身分競爭就會非常困難。"},{"en":"Stationery shops need special service instead of competing as ordinary retailers.","zh":"文具店需要特別服務，而不是只以普通零售商身分競爭。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"rebuild themselves as","meaning":"把自己重新定位為","examples":[{"en":"The shops need to rebuild themselves as specialist community shops.","zh":"這些店舖需要把自己重新定位為專門的社區小店。"},{"en":"To rebuild themselves as something means to change their identity and business model.","zh":"rebuild themselves as something 指改變自己的身份和經營模式。"},{"en":"A café may rebuild itself as a study space for students.","zh":"一間咖啡店可能把自己重新定位為學生溫習空間。"},{"en":"Shops rebuild themselves when old customers disappear and new needs appear.","zh":"當舊顧客消失而新需要出現，店舖就要重新定位。"},{"en":"Stationery shops can rebuild themselves as places for advice, workshops, and school support.","zh":"文具店可以把自己重新定位為提供建議、工作坊和學校支援的地方。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"specialist shops","meaning":"專門店","examples":[{"en":"Independent shops can survive as specialist shops.","zh":"獨立店舖可以作為專門店生存。"},{"en":"Specialist shops focus on particular products or services and know them well.","zh":"specialist shops 專注於特定產品或服務，並對它們十分熟悉。"},{"en":"A specialist shop for art materials can help students choose the right paper.","zh":"一間美術材料專門店可以幫助學生選擇合適的紙張。"},{"en":"Specialist shops can charge fairly because they offer knowledge, not just goods.","zh":"專門店可以合理收費，因為它們提供的不只是貨品，還有知識。"},{"en":"Stationery shops become stronger when customers see them as specialist shops.","zh":"當顧客把文具店視為專門店，它們會變得更強。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"service-driven community shops","meaning":"以服務為主導的社區小店","examples":[{"en":"They can become service-driven community shops.","zh":"它們可以成為以服務為主導的社區小店。"},{"en":"Service-driven community shops focus on helping local customers, not just selling products.","zh":"service-driven community shops 重視幫助本地顧客，而不只是出售產品。"},{"en":"A service-driven community shop remembers what nearby schools require.","zh":"以服務為主導的社區小店會記得附近學校需要甚麼。"},{"en":"Good service can bring customers back even when online prices are lower.","zh":"即使網上價格較低，良好服務也可以令顧客回來。"},{"en":"Stationery shops can survive as service-driven community shops with advice and trust.","zh":"文具店可以靠建議和信任，作為以服務為主導的社區小店生存。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"the first reason for the fall","meaning":"衰落的第一個原因","examples":[{"en":"The first reason for the fall is straightforward.","zh":"衰落的第一個原因很直接。"},{"en":"The first reason for the fall means the main first cause of a decline.","zh":"the first reason for the fall 指衰落的第一個主要原因。"},{"en":"The first reason for the fall in sales was fewer students visiting after school.","zh":"銷售下滑的第一個原因，是放學後到店的學生減少。"},{"en":"When explaining a problem, naming the first reason for the fall helps readers follow the argument.","zh":"解釋問題時，指出衰落的第一個原因能幫助讀者理解論點。"},{"en":"For stationery shops, the first reason for the fall is changing customer behaviour.","zh":"對文具店來說，衰落的第一個原因是顧客行為改變。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"the reason is straightforward","meaning":"原因很直接","examples":[{"en":"The reason is straightforward: the old business model no longer matches the way families shop.","zh":"原因很直接：舊有經營模式不再配合家庭購物的方式。"},{"en":"The reason is straightforward means the explanation is simple and easy to understand.","zh":"the reason is straightforward 指解釋簡單、容易理解。"},{"en":"The reason is straightforward: the shop closes early, so workers cannot visit after work.","zh":"原因很直接：店舖太早關門，所以上班族下班後不能光顧。"},{"en":"When prices online are much lower, the reason for fewer customers may be straightforward.","zh":"當網上價格低得多，顧客減少的原因可能很直接。"},{"en":"The reason is straightforward, but solving the problem is still difficult.","zh":"原因很直接，但解決問題仍然困難。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"old business model","meaning":"舊有經營模式","examples":[{"en":"The old business model no longer matches the way families shop.","zh":"舊有經營模式不再配合家庭購物的方式。"},{"en":"An old business model is a previous way of making money or serving customers.","zh":"old business model 指過去賺錢或服務顧客的方式。"},{"en":"A shop’s old business model may depend on students visiting every afternoon.","zh":"一間店的舊有經營模式可能依賴學生每天放學後光顧。"},{"en":"When customer habits change, an old business model may stop working.","zh":"當顧客習慣改變，舊有經營模式可能不再有效。"},{"en":"Stationery shops need to update the old business model instead of waiting for the past.","zh":"文具店需要更新舊有經營模式，而不是等待過去回來。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"no longer matches","meaning":"不再配合","examples":[{"en":"The old business model no longer matches the way families shop.","zh":"舊有經營模式不再配合家庭購物的方式。"},{"en":"No longer matches means does not fit or suit something anymore.","zh":"no longer matches 指不再適合或配合某事物。"},{"en":"My old timetable no longer matches my new school schedule.","zh":"我的舊時間表不再配合新的學校課程。"},{"en":"If a shop sells only basic items, it may no longer match customers’ needs.","zh":"如果一間店只賣基本用品，它可能不再配合顧客需要。"},{"en":"The business no longer matches modern habits, so it must change.","zh":"這門生意不再配合現代習慣，所以必須改變。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"the way families shop","meaning":"家庭購物的方式","examples":[{"en":"The business model does not match the way families shop today.","zh":"這個經營模式不配合今天家庭購物的方式。"},{"en":"The way families shop means how households choose, buy, and receive goods.","zh":"the way families shop 指家庭如何選擇、購買和接收貨品。"},{"en":"The way families shop changed when parents began ordering supplies online.","zh":"當家長開始在網上訂購用品，家庭購物的方式就改變了。"},{"en":"If the way families shop becomes faster and cheaper, small shops face pressure.","zh":"如果家庭購物的方式變得更快更便宜，小店就會面對壓力。"},{"en":"Stationery shops must understand the way families shop before planning new services.","zh":"文具店在規劃新服務前，必須理解家庭購物的方式。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"in the past","meaning":"過去","examples":[{"en":"In the past, pupils went to nearby shops for school supplies.","zh":"過去，學生會到附近店舖購買學校用品。"},{"en":"In the past means during an earlier time, not now.","zh":"in the past 指在較早的時間，不是現在。"},{"en":"In the past, children often bought sweets and pencils after school.","zh":"過去，孩子常在放學後買糖果和鉛筆。"},{"en":"In the past, small shops could survive because students visited them daily.","zh":"過去，小店能夠生存，因為學生每天都會光顧。"},{"en":"In the past, shopping was more local and less dependent on delivery.","zh":"過去，購物更本地化，較少依賴送貨。"}],"source":"2020 Q3.pdf","sourcePage":3},{"front":"pupils","meaning":"學生；小學生","examples":[{"en":"Pupils used to buy exercise books after school.","zh":"學生過去常在放學後買練習簿。"},{"en":"Pupils are children who study at school, especially younger students.","zh":"pupils 指在學校讀書的孩子，尤其是較年幼的學生。"},{"en":"Primary school pupils often need pencils, rulers, and coloured paper.","zh":"小學生常需要鉛筆、間尺和顏色紙。"},{"en":"When pupils stop visiting nearby shops, those shops lose daily sales.","zh":"當學生不再到附近店舖購物，這些店舖就失去每日銷售。"},{"en":"Pupils once made stationery shops lively after the school bell rang.","zh":"過去放學鐘響後，學生令文具店變得熱鬧。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"nearby shops","meaning":"附近店舖","examples":[{"en":"Pupils went to nearby shops for exercise books and project materials.","zh":"學生會到附近店舖購買練習簿和專題研習材料。"},{"en":"Nearby shops are shops close to where people live, study, or work.","zh":"nearby shops 是接近人們居住、學習或工作的店舖。"},{"en":"Students visit nearby shops when they need something quickly before class.","zh":"學生上課前急需物品時，會到附近店舖購買。"},{"en":"Nearby shops lose customers when families choose home delivery instead.","zh":"當家庭選擇送貨到家，附近店舖就會失去顧客。"},{"en":"A nearby shop is useful because people can get help immediately.","zh":"附近店舖很有用，因為人們可以立即得到幫助。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"exercise books","meaning":"練習簿","examples":[{"en":"Pupils bought exercise books from nearby stationery shops.","zh":"學生從附近文具店購買練習簿。"},{"en":"Exercise books are notebooks used by students for classwork and homework.","zh":"exercise books 是學生用來做課堂練習和功課的簿。"},{"en":"A maths teacher may ask pupils to bring two exercise books every term.","zh":"數學老師可能要求學生每學期帶兩本練習簿。"},{"en":"If schools use more online worksheets, students may need fewer exercise books.","zh":"如果學校更多使用網上工作紙，學生可能需要較少練習簿。"},{"en":"Exercise books were once one of the most common items in stationery shops.","zh":"練習簿曾是文具店最常見的貨品之一。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"coloured paper","meaning":"顏色紙","examples":[{"en":"Students bought coloured paper for school projects.","zh":"學生為學校專題研習購買顏色紙。"},{"en":"Coloured paper is paper in different colours, often used for art or displays.","zh":"coloured paper 是不同顏色的紙，常用於美術或展示。"},{"en":"Children use coloured paper to make cards for festivals.","zh":"孩子用顏色紙製作節日賀卡。"},{"en":"A project may look clearer when headings are placed on coloured paper.","zh":"如果標題放在顏色紙上，專題研習可能會看起來更清楚。"},{"en":"Coloured paper is easier to choose in person because students can see the exact shade.","zh":"顏色紙親身選擇較容易，因為學生可以看見準確色調。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"correction tape","meaning":"改錯帶","examples":[{"en":"Students often bought correction tape from stationery shops.","zh":"學生常從文具店購買改錯帶。"},{"en":"Correction tape is a tool used to cover written mistakes neatly.","zh":"correction tape 是用來整齊遮蓋書寫錯誤的工具。"},{"en":"A student uses correction tape when she writes the wrong word in pen.","zh":"學生用原子筆寫錯字時，會使用改錯帶。"},{"en":"Correction tape is useful during exams because it dries immediately.","zh":"改錯帶在考試時很有用，因為它不用等待變乾。"},{"en":"Small stationery shops once sold correction tape to students almost every day.","zh":"小型文具店過去幾乎每天都賣改錯帶給學生。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"last-minute project materials","meaning":"臨急需要的專題研習材料","examples":[{"en":"Pupils went to nearby shops for last-minute project materials.","zh":"學生會到附近店舖購買臨急需要的專題研習材料。"},{"en":"Last-minute project materials are supplies bought shortly before a project is due.","zh":"last-minute project materials 指在專題研習截止前不久才購買的用品。"},{"en":"A student may need cardboard, glue, and markers as last-minute project materials.","zh":"學生可能臨急需要卡紙、膠水和記號筆作專題研習材料。"},{"en":"Nearby shops help when last-minute project materials cannot arrive by delivery in time.","zh":"當送貨趕不及，附近店舖可以幫助學生買到臨急需要的材料。"},{"en":"Stationery shops were useful because they saved students with last-minute project needs.","zh":"文具店很有用，因為它們曾拯救臨急需要專題材料的學生。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"buy stationery in bulk","meaning":"大量購買文具","examples":[{"en":"Many parents now buy stationery in bulk.","zh":"許多家長現在大量購買文具。"},{"en":"To buy stationery in bulk means to buy many stationery items at once.","zh":"buy stationery in bulk 指一次過購買大量文具用品。"},{"en":"Parents buy stationery in bulk before the school year begins.","zh":"家長在學年開始前大量購買文具。"},{"en":"Buying stationery in bulk can be cheaper, but it reduces small daily purchases.","zh":"大量購買文具可能較便宜，但會減少日常小額購物。"},{"en":"When families buy stationery in bulk online, nearby shops lose regular visits.","zh":"當家庭在網上大量購買文具，附近店舖就失去固定客流。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"chain stores","meaning":"連鎖店","examples":[{"en":"Parents often buy stationery from chain stores.","zh":"家長常從連鎖店購買文具。"},{"en":"Chain stores are shops with many branches under the same brand.","zh":"chain stores 是同一品牌旗下有多間分店的店舖。"},{"en":"A chain store may sell the same notebooks in many districts.","zh":"連鎖店可能在許多地區出售相同的筆記簿。"},{"en":"Chain stores can offer lower prices because they buy large quantities.","zh":"連鎖店因為大量入貨，所以可以提供較低價格。"},{"en":"Small stationery shops struggle when customers choose chain stores for cheaper goods.","zh":"當顧客為了較便宜貨品而選擇連鎖店，小型文具店就會經營困難。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"online platforms","meaning":"網上平台","examples":[{"en":"Parents can buy stationery from online platforms.","zh":"家長可以從網上平台購買文具。"},{"en":"Online platforms are websites or apps where people can search for and buy products.","zh":"online platforms 是讓人搜尋和購買產品的網站或應用程式。"},{"en":"Online platforms let parents compare pens from different sellers.","zh":"網上平台讓家長比較不同賣家的筆。"},{"en":"If online platforms offer discounts and delivery, families may stop visiting local shops.","zh":"如果網上平台提供折扣和送貨，家庭可能會停止光顧本地店舖。"},{"en":"Online platforms are convenient, but they cannot always give personal advice.","zh":"網上平台很方便，但未必能提供個人建議。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"prices are lower","meaning":"價格較低","examples":[{"en":"Customers choose online platforms because prices are lower.","zh":"顧客選擇網上平台，因為價格較低。"},{"en":"Prices are lower means goods cost less money than in another place.","zh":"prices are lower 指貨品比另一個地方較便宜。"},{"en":"Parents may buy exercise books online if prices are lower there.","zh":"如果網上的價格較低，家長可能會在網上買練習簿。"},{"en":"When prices are lower online, small shops find it hard to compete.","zh":"當網上價格較低，小店很難競爭。"},{"en":"Lower prices attract customers, but service may be weaker.","zh":"較低價格能吸引顧客，但服務可能較弱。"}],"source":"2020 Q3.pdf","sourcePage":4},{"front":"delivery is convenient","meaning":"送貨方便","examples":[{"en":"Online shopping is attractive because delivery is convenient.","zh":"網上購物吸引人，因為送貨方便。"},{"en":"Delivery is convenient means goods can be sent to customers easily and quickly.","zh":"delivery is convenient 指貨品可以方便而快速地送到顧客手上。"},{"en":"Busy parents like online orders because delivery is convenient after work.","zh":"忙碌家長喜歡網上訂購，因為下班後送貨很方便。"},{"en":"If delivery is convenient, people may not walk to nearby shops.","zh":"如果送貨方便，人們可能不會走到附近店舖購物。"},{"en":"Convenient delivery saves time but reduces contact with local shopkeepers.","zh":"方便送貨節省時間，但減少了與本地店主的接觸。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"a pack of pens","meaning":"一包筆","examples":[{"en":"A pack of pens can be ordered online.","zh":"一包筆可以在網上訂購。"},{"en":"A pack of pens means several pens sold together in one package.","zh":"a pack of pens 指幾支筆作為一包出售。"},{"en":"A student may buy a pack of pens before exam season.","zh":"學生可能在考試季前買一包筆。"},{"en":"Buying a pack of pens online can be cheaper than buying one pen at a time.","zh":"在網上買一包筆，可能比一支一支買便宜。"},{"en":"When families order a pack of pens online, small shops lose small daily sales.","zh":"當家庭在網上訂購一包筆，小店就失去日常小額銷售。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"compared, ordered and delivered","meaning":"可比較、訂購並送貨","examples":[{"en":"A pack of pens can be compared, ordered and delivered online.","zh":"一包筆可以在網上比較、訂購並送貨。"},{"en":"Compared, ordered and delivered means customers can check choices, buy them, and receive them without going out.","zh":"compared, ordered and delivered 指顧客可以查看選擇、購買並收到貨品，無需外出。"},{"en":"School bags can be compared, ordered and delivered through one shopping app.","zh":"書包可以透過一個購物應用程式比較、訂購並送貨。"},{"en":"When products are compared, ordered and delivered online, physical shops lose some advantages.","zh":"當產品可以在網上比較、訂購並送貨，實體店就失去部分優勢。"},{"en":"This process is convenient because it turns shopping into a few clicks.","zh":"這個過程很方便，因為它把購物變成幾下點擊。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"without stepping into a shop","meaning":"無需走進店舖","examples":[{"en":"Stationery can be delivered without a child stepping into a shop.","zh":"文具可以送到家中，孩子無需走進店舖。"},{"en":"Without stepping into a shop means without physically entering a store.","zh":"without stepping into a shop 指不需要親身進入店舖。"},{"en":"Parents can buy school shoes online without stepping into a shop.","zh":"家長可以在網上買校鞋，無需走進店舖。"},{"en":"If customers buy everything without stepping into a shop, local retailers lose contact with them.","zh":"如果顧客所有東西都無需走進店舖就買到，本地零售商就會失去與他們的接觸。"},{"en":"The phrase shows how online shopping removes the old habit of visiting neighbourhood stores.","zh":"這個片語顯示網上購物如何消除到社區店舖購物的舊習慣。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"this saves time","meaning":"這樣節省時間","examples":[{"en":"For customers, this saves time.","zh":"對顧客來說，這樣節省時間。"},{"en":"This saves time means this makes a task quicker or reduces wasted time.","zh":"this saves time 指這樣令工作更快完成，或減少浪費時間。"},{"en":"Ordering school supplies online saves time for parents who work late.","zh":"對工作到很晚的家長來說，在網上訂購學校用品節省時間。"},{"en":"A service saves time when it removes travel, waiting, or searching.","zh":"如果一項服務減少交通、等待或搜尋，它就是在節省時間。"},{"en":"Online shopping saves time, but it also removes visits to local shops.","zh":"網上購物節省時間，但也減少了到本地店舖的次數。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"removes the daily foot traffic","meaning":"減少每日客流","examples":[{"en":"Online shopping removes the daily foot traffic that shops used to depend on.","zh":"網上購物減少了店舖過去依賴的每日客流。"},{"en":"Removes the daily foot traffic means takes away the regular flow of people walking into a shop.","zh":"removes the daily foot traffic 指帶走每天走進店舖的人流。"},{"en":"A new bus route may remove daily foot traffic from a small street.","zh":"新巴士路線可能會減少小街上的每日客流。"},{"en":"Without daily foot traffic, shops have fewer chances to make small sales.","zh":"沒有每日客流，店舖作出小額銷售的機會就會減少。"},{"en":"Online shopping hurts stationery shops because it removes the students who once visited every day.","zh":"網上購物傷害文具店，因為它減少了過去每天光顧的學生。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"used to depend on","meaning":"過去依賴","examples":[{"en":"Shop owners used to depend on students buying items after school.","zh":"店主過去依賴學生放學後購買物品。"},{"en":"Used to depend on means relied on something regularly in the past.","zh":"used to depend on 指過去經常依靠某事物。"},{"en":"The bakery used to depend on office workers buying breakfast.","zh":"麵包店過去依賴上班族購買早餐。"},{"en":"A business is at risk if the customers it used to depend on disappear.","zh":"如果一門生意過去依賴的顧客消失，它就會有風險。"},{"en":"Stationery shops used to depend on students, but students now buy less in person.","zh":"文具店過去依賴學生，但學生現在較少親身購買。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"run a stationery shop","meaning":"經營文具店","examples":[{"en":"Mr Wong runs a stationery shop in Sham Shui Po.","zh":"黃先生在深水埗經營一間文具店。"},{"en":"To run a stationery shop means to manage and operate a shop that sells stationery.","zh":"run a stationery shop 指管理和營運一間售賣文具的店舖。"},{"en":"My aunt runs a stationery shop near a primary school.","zh":"我姑姐在一間小學附近經營文具店。"},{"en":"People who run a stationery shop must choose stock, serve customers, and pay rent.","zh":"經營文具店的人必須選擇存貨、服務顧客和支付租金。"},{"en":"It is harder to run a stationery shop when fewer students visit after school.","zh":"當放學後光顧的學生減少，經營文具店就會更困難。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"no longer","meaning":"不再","examples":[{"en":"Students no longer buy pens one by one after school.","zh":"學生不再放學後一支一支地買筆。"},{"en":"No longer means something happened before but does not happen now.","zh":"no longer 指某事以前發生，但現在不再發生。"},{"en":"Many families no longer visit video rental shops.","zh":"許多家庭不再光顧影碟出租店。"},{"en":"Shops struggle when customers no longer follow old buying habits.","zh":"當顧客不再跟隨舊有購物習慣，店舖就會掙扎。"},{"en":"Students no longer need some stationery because schoolwork has moved online.","zh":"學生不再需要某些文具，因為功課已轉到網上。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"one by one","meaning":"一支一支地","examples":[{"en":"Students no longer buy pens one by one after school.","zh":"學生不再放學後一支一支地買筆。"},{"en":"One by one means separately, one item or person at a time.","zh":"one by one 指逐一地，一次一件物品或一個人。"},{"en":"The teacher checked the exercise books one by one.","zh":"老師一本一本地檢查練習簿。"},{"en":"Buying pens one by one brings small but regular sales to a shop.","zh":"一支一支地買筆，能為店舖帶來小額但固定的銷售。"},{"en":"When customers stop buying one by one, small daily income disappears.","zh":"當顧客停止逐件購買，小額日常收入就會消失。"}],"source":"2020 Q3.pdf","sourcePage":5},{"front":"rent is another burden","meaning":"租金是另一個負擔","examples":[{"en":"Rent is another burden for independent shops.","zh":"對獨立店舖來說，租金是另一個負擔。"},{"en":"Rent is another burden means rent is one more heavy cost or problem.","zh":"rent is another burden 指租金是另一項沉重成本或問題。"},{"en":"For a small café, rent is another burden after wages and food costs.","zh":"對小咖啡店來說，除了工資和食材成本，租金是另一個負擔。"},{"en":"If sales fall, rent becomes an even heavier burden.","zh":"如果銷售下降，租金會變成更沉重的負擔。"},{"en":"Independent shops suffer because rent is another burden they cannot avoid.","zh":"獨立店舖受苦，因為租金是它們無法避免的另一個負擔。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"unlike large retailers","meaning":"不像大型零售商","examples":[{"en":"Unlike large retailers, independent shops cannot easily absorb weak sales.","zh":"不像大型零售商，獨立店舖不容易承受數個月生意淡靜。"},{"en":"Unlike large retailers means different from big retail companies.","zh":"unlike large retailers 指與大型零售公司不同。"},{"en":"Unlike large retailers, small shops may not have extra money for long slow periods.","zh":"不像大型零售商，小店可能沒有額外資金應付長時間淡季。"},{"en":"This phrase shows a contrast between powerful companies and small businesses.","zh":"這個片語顯示大型公司與小商戶之間的對比。"},{"en":"Unlike large retailers, neighbourhood shops often depend on every week’s income.","zh":"不像大型零售商，社區小店常依賴每星期的收入。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"large retailers","meaning":"大型零售商","examples":[{"en":"Large retailers can survive weak sales more easily than small shops.","zh":"大型零售商比小店更容易捱過生意淡靜。"},{"en":"Large retailers are big companies that sell goods through many stores or platforms.","zh":"large retailers 是透過多間店舖或平台出售貨品的大公司。"},{"en":"Large retailers can buy products cheaply because they order in huge quantities.","zh":"大型零售商因為大量訂貨，所以可以便宜入貨。"},{"en":"When sales are weak, large retailers may use savings from other branches.","zh":"當生意淡靜，大型零售商可能使用其他分店的收入支撐。"},{"en":"Small shops cannot always compete with large retailers on price.","zh":"小店不一定能在價格上與大型零售商競爭。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"absorb months of weak sales","meaning":"承受數個月生意淡靜","examples":[{"en":"Independent shops cannot easily absorb months of weak sales.","zh":"獨立店舖不容易承受數個月生意淡靜。"},{"en":"To absorb months of weak sales means to survive a long period with low income.","zh":"absorb months of weak sales 指在長時間收入偏低下仍能支撐。"},{"en":"A restaurant needs savings to absorb months of weak sales after roadworks block the street.","zh":"道路工程阻塞街道後，餐廳需要儲備來承受數個月生意淡靜。"},{"en":"Without enough cash, shops cannot absorb months of weak sales and still pay bills.","zh":"沒有足夠現金，店舖無法承受數個月生意淡靜並繼續支付帳單。"},{"en":"This is why one slow season can be dangerous for independent shops.","zh":"這就是為甚麼一個淡季也可能對獨立店舖構成危險。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"weak sales","meaning":"生意淡靜","examples":[{"en":"Small shops struggle during periods of weak sales.","zh":"小店在生意淡靜期間會經營困難。"},{"en":"Weak sales mean customers are buying less than usual.","zh":"weak sales 指顧客購買量比平常少。"},{"en":"A rainy month can cause weak sales for outdoor market stalls.","zh":"多雨的一個月可能令戶外市場攤檔生意淡靜。"},{"en":"Weak sales reduce the money available for rent, wages, and new stock.","zh":"生意淡靜會減少支付租金、工資和新存貨的資金。"},{"en":"Stationery shops face weak sales when students buy supplies online or in bulk.","zh":"當學生在網上或大量購買用品，文具店就會面對生意淡靜。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"negotiate favourable leases","meaning":"商討有利租約","examples":[{"en":"Independent shops cannot easily negotiate favourable leases.","zh":"獨立店舖不容易商討有利租約。"},{"en":"To negotiate favourable leases means to discuss rental agreements with better terms.","zh":"negotiate favourable leases 指商討條件較好的租賃協議。"},{"en":"Big companies can negotiate favourable leases because landlords want famous tenants.","zh":"大公司可以商討有利租約，因為業主想吸引知名租戶。"},{"en":"If a shop cannot negotiate a favourable lease, high rent may force it out.","zh":"如果店舖無法商討有利租約，高租金可能迫使它搬走。"},{"en":"Small stationery shops often lack the bargaining power to get better rental terms.","zh":"小型文具店往往缺乏議價能力，難以取得較好的租約條件。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"favourable leases","meaning":"有利租約","examples":[{"en":"Large retailers are more likely to obtain favourable leases.","zh":"大型零售商較有可能取得有利租約。"},{"en":"Favourable leases are rental agreements with helpful conditions, such as lower rent or longer terms.","zh":"favourable leases 是條件較好的租約，例如較低租金或較長租期。"},{"en":"A favourable lease can give a shop time to build regular customers.","zh":"有利租約可以給店舖時間建立固定顧客。"},{"en":"Without favourable leases, small shops face higher risk when sales fall.","zh":"沒有有利租約，小店在銷售下降時會面對更高風險。"},{"en":"Favourable leases matter because rent is one of the largest costs.","zh":"有利租約很重要，因為租金是最大成本之一。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"cover rent, wages and electricity","meaning":"支付租金、工資和電費","examples":[{"en":"A small shop must sell many items to cover rent, wages and electricity.","zh":"一間小店必須賣出很多貨品，才能支付租金、工資和電費。"},{"en":"To cover rent, wages and electricity means to earn enough money to pay these basic costs.","zh":"cover rent, wages and electricity 指賺到足夠金錢支付這些基本成本。"},{"en":"A café must sell many cups of coffee to cover rent, wages and electricity.","zh":"咖啡店必須賣出很多杯咖啡，才能支付租金、工資和電費。"},{"en":"If daily sales are low, a shop may fail to cover rent, wages and electricity.","zh":"如果每日銷售低，店舖可能無法支付租金、工資和電費。"},{"en":"Thin profits make it hard for stationery shops to cover these regular expenses.","zh":"微薄利潤令文具店難以支付這些固定開支。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"unsold stock","meaning":"滯銷存貨","examples":[{"en":"Small shops also have to pay for unsold stock.","zh":"小店還要支付滯銷存貨的成本。"},{"en":"Unsold stock means products that remain in the shop because customers have not bought them.","zh":"unsold stock 指顧客沒有購買、仍留在店裏的貨品。"},{"en":"Old notebooks become unsold stock when students choose a newer design.","zh":"當學生選擇較新的設計，舊筆記簿就變成滯銷存貨。"},{"en":"Unsold stock ties up money that shop owners need for fresh products.","zh":"滯銷存貨佔用了店主用來購入新貨的資金。"},{"en":"Too much unsold stock can make a shop look old and unattractive.","zh":"太多滯銷存貨會令店舖看起來老舊而不吸引。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"not so much… as…","meaning":"與其說是……不如說是……","examples":[{"en":"The problem is not so much that people have stopped writing as that the profit is too thin.","zh":"問題與其說是人們已停止書寫，不如說是利潤太微薄。"},{"en":"Not so much A as B means B is the real or more important reason, not A.","zh":"not so much A as B 指真正或更重要的原因是 B，而不是 A。"},{"en":"The issue is not so much laziness as lack of sleep.","zh":"問題與其說是懶惰，不如說是睡眠不足。"},{"en":"A shop may fail not so much because nobody buys, as because costs are too high.","zh":"一間店倒閉，與其說是完全沒有人買，不如說是成本太高。"},{"en":"This phrase helps correct a simple explanation by pointing to the deeper reason.","zh":"這個片語有助修正簡單解釋，指出更深層原因。"}],"source":"2020 Q3.pdf","sourcePage":6},{"front":"profit on each item","meaning":"每件貨品的利潤","examples":[{"en":"The profit on each item is too thin.","zh":"每件貨品的利潤太微薄。"},{"en":"Profit on each item means the money a shop earns from selling one product after costs.","zh":"profit on each item 指扣除成本後，店舖從每件產品賺到的錢。"},{"en":"The profit on each pen may be only a few cents.","zh":"每支筆的利潤可能只有幾毫。"},{"en":"If the profit on each item is low, a shop must sell many items to survive.","zh":"如果每件貨品的利潤低，店舖就必須賣出很多貨品才能生存。"},{"en":"Stationery shops struggle because small goods often bring small profits.","zh":"文具店經營困難，因為小件貨品通常帶來小利潤。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"too thin","meaning":"太薄；太微薄","examples":[{"en":"The profit on each item is too thin.","zh":"每件貨品的利潤太微薄。"},{"en":"Too thin means too small or weak to be enough.","zh":"too thin 指太少、太弱或不足夠。"},{"en":"The soup tasted too thin because there was not enough flavour.","zh":"那碗湯味道太淡薄，因為不夠味。"},{"en":"A profit margin that is too thin cannot protect a shop during slow months.","zh":"如果利潤率太微薄，店舖在淡季就沒有保護。"},{"en":"In retail, thin profit leaves little room for mistakes.","zh":"在零售業中，微薄利潤令店舖沒有多少犯錯空間。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"regular student customers","meaning":"固定學生顧客","examples":[{"en":"Once a shop loses regular student customers, it enters a painful cycle.","zh":"一旦店舖失去固定學生顧客，就會進入痛苦循環。"},{"en":"Regular student customers are students who visit and buy from a shop often.","zh":"regular student customers 指經常到店購物的學生。"},{"en":"A stationery shop near a school depends on regular student customers after class.","zh":"學校附近的文具店依賴放學後光顧的固定學生顧客。"},{"en":"Losing regular student customers reduces both sales and neighbourhood energy.","zh":"失去固定學生顧客會減少銷售，也會削弱社區活力。"},{"en":"Shops need trust and convenience to keep regular student customers.","zh":"店舖需要信任和便利，才能留住固定學生顧客。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"caught in a painful cycle","meaning":"陷入痛苦循環","examples":[{"en":"A shop can become caught in a painful cycle.","zh":"一間店可能會陷入痛苦循環。"},{"en":"Caught in a painful cycle means trapped in a repeated problem that keeps getting worse.","zh":"caught in a painful cycle 指被困在不斷重複並惡化的問題中。"},{"en":"A student may be caught in a painful cycle of sleeping late and feeling tired.","zh":"學生可能陷入晚睡又疲倦的痛苦循環。"},{"en":"Shops become caught in a painful cycle when fewer sales lead to older stock and fewer customers.","zh":"當銷售減少導致存貨變舊，而舊存貨又令顧客更少，店舖就陷入痛苦循環。"},{"en":"Breaking a painful cycle requires changing the cause, not only waiting.","zh":"要打破痛苦循環，必須改變原因，而不只是等待。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"fewer sales mean less money","meaning":"銷售減少代表資金減少","examples":[{"en":"Fewer sales mean less money to refresh stock.","zh":"銷售減少代表用來更新存貨的資金減少。"},{"en":"Fewer sales mean less money shows that lower income leaves fewer resources for the business.","zh":"fewer sales mean less money 表示收入降低會令生意可用資源減少。"},{"en":"Fewer ticket sales mean less money for the school drama club.","zh":"門票銷售減少代表學校戲劇學會的資金減少。"},{"en":"When fewer sales mean less money, shops cannot buy attractive new products.","zh":"當銷售減少代表資金減少，店舖就無法購買吸引的新產品。"},{"en":"This simple cause-and-effect explains why decline can continue.","zh":"這個簡單因果關係解釋了為何衰落會持續。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"refresh stock","meaning":"更新存貨","examples":[{"en":"Shop owners need money to refresh stock.","zh":"店主需要資金來更新存貨。"},{"en":"To refresh stock means to replace old products with new or more attractive ones.","zh":"refresh stock 指用新的或更吸引的產品取代舊貨。"},{"en":"A clothes shop refreshes stock before summer begins.","zh":"服裝店在夏天開始前更新存貨。"},{"en":"If a stationery shop cannot refresh stock, customers may think it is outdated.","zh":"如果文具店不能更新存貨，顧客可能會覺得它過時。"},{"en":"Fresh stock can make a small shop look alive again.","zh":"新存貨可以令小店看起來重新有生氣。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"older stock","meaning":"舊存貨","examples":[{"en":"Older stock makes the shop look less attractive.","zh":"舊存貨令店舖看起來較不吸引。"},{"en":"Older stock means products that have stayed in the shop for a long time.","zh":"older stock 指留在店內很久的產品。"},{"en":"Older stock may include faded notebooks or unpopular pen designs.","zh":"舊存貨可能包括褪色的筆記簿或不受歡迎的筆款式。"},{"en":"When shelves are full of older stock, customers may leave without buying.","zh":"當貨架上滿是舊存貨，顧客可能不買就離開。"},{"en":"Older stock can signal that a shop is struggling to keep up.","zh":"舊存貨可能顯示店舖正難以跟上變化。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"look less attractive","meaning":"看起來較不吸引","examples":[{"en":"Older stock makes the shop look less attractive.","zh":"舊存貨令店舖看起來較不吸引。"},{"en":"Look less attractive means appear less pleasant, interesting, or worth visiting.","zh":"look less attractive 指看起來不太美觀、有趣或值得光顧。"},{"en":"A display looks less attractive when products are dusty and badly arranged.","zh":"當產品有灰塵又擺放混亂，陳列就看起來較不吸引。"},{"en":"If a shop looks less attractive, fewer customers may walk in.","zh":"如果店舖看起來較不吸引，走進來的顧客可能會更少。"},{"en":"Fresh displays can stop a small shop from looking less attractive.","zh":"新鮮的陳列可以避免小店看起來較不吸引。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"draws even fewer customers","meaning":"吸引更少顧客","examples":[{"en":"An unattractive shop draws even fewer customers.","zh":"不吸引的店舖會吸引更少顧客。"},{"en":"Draws even fewer customers means attracts an even smaller number of people.","zh":"draws even fewer customers 指吸引到的人數更少。"},{"en":"A dark entrance can draw even fewer customers to a restaurant.","zh":"黑暗的入口可能令餐廳吸引更少顧客。"},{"en":"When a shop looks old, it draws even fewer customers and earns less money.","zh":"當店舖看起來老舊，它會吸引更少顧客，收入也會減少。"},{"en":"This creates a cycle: fewer customers, less money, and weaker displays.","zh":"這會形成循環：顧客更少、資金更少、陳列更弱。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"digital transformation","meaning":"數碼轉型","examples":[{"en":"Schools’ digital transformation has added to the pressure.","zh":"學校的數碼轉型增加了壓力。"},{"en":"Digital transformation means changing systems and habits by using digital technology.","zh":"digital transformation 指透過數碼科技改變系統和習慣。"},{"en":"A school’s digital transformation may include e-books, online homework, and learning apps.","zh":"學校的數碼轉型可能包括電子書、網上功課和學習應用程式。"},{"en":"Digital transformation reduces paper use and changes what students buy.","zh":"數碼轉型減少紙張使用，並改變學生購買的物品。"},{"en":"Stationery shops feel the effect when education moves from paper to screens.","zh":"當教育由紙張轉向螢幕，文具店就會感受到影響。"}],"source":"2020 Q3.pdf","sourcePage":7},{"front":"added to the pressure","meaning":"增加壓力","examples":[{"en":"Digital learning has added to the pressure on stationery shops.","zh":"數碼學習增加了文具店的壓力。"},{"en":"Added to the pressure means made an already difficult situation more difficult.","zh":"added to the pressure 指令本來已困難的情況更加困難。"},{"en":"Extra homework added to the pressure before exams.","zh":"額外功課增加了考試前的壓力。"},{"en":"Rising wages added to the pressure created by weak sales.","zh":"工資上升增加了生意淡靜帶來的壓力。"},{"en":"Online learning added to the pressure by reducing demand for paper products.","zh":"網上學習因減少紙本產品需求而增加壓力。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"e-notes","meaning":"電子筆記","examples":[{"en":"More teachers are using e-notes.","zh":"更多老師正在使用電子筆記。"},{"en":"E-notes are electronic notes that students read on screens instead of paper.","zh":"e-notes 是學生在螢幕上閱讀、而非紙上閱讀的電子筆記。"},{"en":"Students can open e-notes on a tablet during class.","zh":"學生可以在課堂上用平板電腦打開電子筆記。"},{"en":"When teachers use e-notes, families may buy fewer notebooks and files.","zh":"當老師使用電子筆記，家庭可能會購買較少筆記簿和文件夾。"},{"en":"E-notes are convenient, but they reduce the need for printed materials.","zh":"電子筆記很方便，但會減少對印刷材料的需要。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"online worksheets","meaning":"網上工作紙","examples":[{"en":"Teachers increasingly use online worksheets.","zh":"老師越來越多使用網上工作紙。"},{"en":"Online worksheets are exercises completed or shared through the internet.","zh":"online worksheets 是透過互聯網完成或分享的練習。"},{"en":"A teacher may send online worksheets through a school learning platform.","zh":"老師可能透過學校學習平台發送網上工作紙。"},{"en":"Online worksheets reduce printing, so students need less paper.","zh":"網上工作紙減少列印，所以學生需要較少紙張。"},{"en":"Stationery shops lose sales when homework moves from paper to online worksheets.","zh":"當功課由紙本轉為網上工作紙，文具店就失去銷售。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"learning apps","meaning":"學習應用程式","examples":[{"en":"Learning apps have reduced demand for some stationery items.","zh":"學習應用程式減少了對某些文具用品的需求。"},{"en":"Learning apps are mobile or computer programs that help students study.","zh":"learning apps 是幫助學生學習的手機或電腦程式。"},{"en":"A vocabulary learning app can replace some flashcards.","zh":"詞彙學習應用程式可以取代部分生字卡。"},{"en":"If students practise on learning apps, they may use fewer workbooks.","zh":"如果學生在學習應用程式上練習，他們可能會較少使用練習冊。"},{"en":"Learning apps change study habits and reduce some traditional stationery needs.","zh":"學習應用程式改變學習習慣，並減少部分傳統文具需求。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"folders","meaning":"文件夾","examples":[{"en":"Some families now need fewer folders than before.","zh":"有些家庭現在需要的文件夾比以前少。"},{"en":"Folders are covers or files used to hold and organise papers.","zh":"folders 是用來存放和整理紙張的文件套或文件夾。"},{"en":"Students use folders to keep worksheets for different subjects apart.","zh":"學生使用文件夾，把不同科目的工作紙分開。"},{"en":"If schools send fewer printed worksheets, students need fewer folders.","zh":"如果學校發出較少印刷工作紙，學生就需要較少文件夾。"},{"en":"Folders are still useful when students must submit paper projects.","zh":"當學生必須提交紙本專題研習時，文件夾仍然有用。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"refill paper","meaning":"活頁紙","examples":[{"en":"Some families need less refill paper than before.","zh":"有些家庭需要的活頁紙比以前少。"},{"en":"Refill paper is loose paper used in ring files or binders.","zh":"refill paper 是放在活頁夾或文件夾中的散裝紙。"},{"en":"Secondary students often use refill paper for notes and exercises.","zh":"中學生常用活頁紙做筆記和練習。"},{"en":"Digital notes reduce the amount of refill paper students buy.","zh":"電子筆記減少了學生購買活頁紙的數量。"},{"en":"Refill paper still sells when teachers require handwritten homework.","zh":"當老師要求手寫功課時，活頁紙仍然有銷量。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"printed past papers","meaning":"印刷版歷屆試卷","examples":[{"en":"Families may need fewer printed past papers.","zh":"家庭可能需要較少印刷版歷屆試卷。"},{"en":"Printed past papers are old exam papers produced on paper for practice.","zh":"printed past papers 是印在紙上供練習的舊考試卷。"},{"en":"Students use printed past papers to prepare for public exams.","zh":"學生使用印刷版歷屆試卷準備公開考試。"},{"en":"If schools upload past papers online, families may print or buy fewer copies.","zh":"如果學校把歷屆試卷上載到網上，家庭可能會列印或購買較少副本。"},{"en":"Printed past papers remain useful for students who practise writing under exam conditions.","zh":"對需要在考試情況下練習書寫的學生來說，印刷版歷屆試卷仍然有用。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"even when","meaning":"即使","examples":[{"en":"Even when stationery is still required, schools may arrange group purchases.","zh":"即使仍然需要文具，學校也可能安排集體採購。"},{"en":"Even when means although a certain situation is true.","zh":"even when 指即使某種情況是真實的。"},{"en":"Even when students use tablets, they may still need pens for exams.","zh":"即使學生使用平板電腦，他們考試時仍可能需要筆。"},{"en":"Even when demand remains, small shops may lose business if schools buy directly.","zh":"即使需求仍然存在，如果學校直接購買，小店也可能失去生意。"},{"en":"This phrase shows that a problem can continue despite a helpful condition.","zh":"這個片語顯示，即使有有利條件，問題仍可能持續。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"arrange group purchases","meaning":"安排集體採購","examples":[{"en":"Schools may arrange group purchases directly through suppliers.","zh":"學校可能直接經供應商安排集體採購。"},{"en":"To arrange group purchases means to organise one large order for many people.","zh":"arrange group purchases 指為多人組織一個大型訂單。"},{"en":"A school may arrange group purchases of textbooks for all students.","zh":"學校可能為所有學生安排教科書集體採購。"},{"en":"Group purchases can lower prices but may bypass small local shops.","zh":"集體採購可以降低價格，但可能繞過本地小店。"},{"en":"When schools arrange group purchases, parents do not need to visit stationery shops.","zh":"當學校安排集體採購，家長就不需要到文具店。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"directly through suppliers","meaning":"直接經供應商","examples":[{"en":"Schools may buy stationery directly through suppliers.","zh":"學校可能直接經供應商購買文具。"},{"en":"Directly through suppliers means buying from the companies that provide goods, without using small shops.","zh":"directly through suppliers 指直接向供貨公司購買，而不經小店。"},{"en":"A restaurant may buy vegetables directly through suppliers instead of markets.","zh":"餐廳可能直接經供應商購買蔬菜，而不是到街市。"},{"en":"Buying directly through suppliers can be efficient but removes local retailers from the process.","zh":"直接經供應商購買可以有效率，但會把本地零售商排除在過程外。"},{"en":"Small stationery shops lose business when schools order directly through suppliers.","zh":"當學校直接經供應商訂貨，小型文具店就會失去生意。"}],"source":"2020 Q3.pdf","sourcePage":8},{"front":"efficient for parents","meaning":"對家長來說有效率","examples":[{"en":"Group purchasing is efficient for parents.","zh":"集體採購對家長來說有效率。"},{"en":"Efficient for parents means it saves parents time, effort, or money.","zh":"efficient for parents 指為家長節省時間、精力或金錢。"},{"en":"One online form is efficient for parents because they do not need to visit several shops.","zh":"一張網上表格對家長來說有效率，因為他們不用到幾間店購物。"},{"en":"A system can be efficient for parents but harmful to small businesses.","zh":"一個制度可以對家長有效率，但對小商戶有害。"},{"en":"School group orders are efficient for parents because supplies arrive in one package.","zh":"學校集體訂購對家長有效率，因為用品會一次過送到。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"quietly cuts out","meaning":"悄悄繞過","examples":[{"en":"Group purchasing quietly cuts out small stationery shops.","zh":"集體採購悄悄繞過小型文具店。"},{"en":"Quietly cuts out means removes someone from a process without much attention.","zh":"quietly cuts out 指在不太引人注意的情況下，把某人或某方排除在過程外。"},{"en":"Online booking quietly cuts out travel agents in many simple trips.","zh":"網上訂票在許多簡單旅程中悄悄繞過旅行社。"},{"en":"A new ordering system can quietly cut out local shops even if customers still need the goods.","zh":"新訂購制度即使在顧客仍需要貨品時，也可以悄悄繞過本地店舖。"},{"en":"Small shops suffer when they are quietly cut out of school supply chains.","zh":"當小店被悄悄排除在學校供應鏈之外，它們就會受苦。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"served as informal supply centres","meaning":"曾經充當非正式供應中心","examples":[{"en":"Small shops once served as informal supply centres.","zh":"小店曾經充當非正式供應中心。"},{"en":"Served as informal supply centres means acted as unofficial places where people could quickly get needed items.","zh":"served as informal supply centres 指充當非官方、讓人快速取得所需物品的地方。"},{"en":"A corner shop served as an informal supply centre during a rainy school picnic.","zh":"一間街角小店在下雨的學校旅行中，充當了非正式供應中心。"},{"en":"Stationery shops served as informal supply centres because students could buy urgent materials there.","zh":"文具店曾充當非正式供應中心，因為學生可以在那裏購買急需材料。"},{"en":"Losing these shops means losing small but useful support points in the community.","zh":"失去這些店舖，代表社區失去細小但有用的支援點。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"informal supply centres","meaning":"非正式供應中心","examples":[{"en":"Stationery shops acted as informal supply centres for students.","zh":"文具店曾是學生的非正式供應中心。"},{"en":"Informal supply centres are unofficial places where people can get everyday materials when needed.","zh":"informal supply centres 是非官方、讓人按需要取得日常材料的地方。"},{"en":"A school tuck shop may become an informal supply centre for pencils and rulers.","zh":"學校小食部可能成為鉛筆和間尺的非正式供應中心。"},{"en":"Informal supply centres help people solve small problems quickly.","zh":"非正式供應中心幫助人們快速解決小問題。"},{"en":"Stationery shops were informal supply centres because they filled gaps left by home and school.","zh":"文具店是非正式供應中心，因為它們填補了家庭和學校之間的空缺。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"as someone put it","meaning":"正如某人所說","examples":[{"en":"As Ms Chan put it, parents will use one online order form if the school provides it.","zh":"正如陳女士所說，如果學校提供一張網上訂購表格，家長就會使用。"},{"en":"As someone put it means as that person expressed or explained it.","zh":"as someone put it 指正如某人表達或解釋那樣。"},{"en":"As the teacher put it, practice matters more than luck.","zh":"正如老師所說，練習比運氣更重要。"},{"en":"Writers use this phrase to introduce a clear opinion from another person.","zh":"作者使用這個片語來引入另一個人的清楚看法。"},{"en":"As Ms Chan put it, convenience often decides how parents shop.","zh":"正如陳女士所說，便利往往決定家長如何購物。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"online order form","meaning":"網上訂購表格","examples":[{"en":"The school gives parents one online order form.","zh":"學校給家長一張網上訂購表格。"},{"en":"An online order form is a digital form used to choose and buy items.","zh":"online order form 是用來選擇和購買物品的數碼表格。"},{"en":"Parents fill in an online order form for school uniforms.","zh":"家長填寫網上訂購表格購買校服。"},{"en":"An online order form saves time but may reduce visits to nearby shops.","zh":"網上訂購表格節省時間，但可能減少到附近店舖的次數。"},{"en":"A single online order form can replace several small shopping trips.","zh":"一張網上訂購表格可以取代幾次小型購物行程。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"it would be wrong to say","meaning":"說……是錯的","examples":[{"en":"It would be wrong to say these shops have no future.","zh":"說這些店舖沒有未來是錯的。"},{"en":"It would be wrong to say means that statement is not accurate or fair.","zh":"it would be wrong to say 指某種說法並不準確或不公平。"},{"en":"It would be wrong to say books are useless just because many people read online.","zh":"只因很多人在網上閱讀，就說書本無用是錯的。"},{"en":"This phrase helps correct an overly negative view.","zh":"這個片語有助修正過度負面的看法。"},{"en":"It would be wrong to say stationery shops are finished if some can still adapt.","zh":"如果有些文具店仍能適應，就說它們已經完結是錯的。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"have no future","meaning":"沒有未來","examples":[{"en":"It would be wrong to say these shops have no future.","zh":"說這些店舖沒有未來是錯的。"},{"en":"Have no future means have no chance of continuing or succeeding later.","zh":"have no future 指沒有繼續存在或日後成功的機會。"},{"en":"People once said small cinemas had no future, but some survived by becoming special.","zh":"人們曾說小型戲院沒有未來，但有些透過變得特別而生存下來。"},{"en":"A business may seem to have no future if it refuses to change.","zh":"如果一門生意拒絕改變，它可能看似沒有未來。"},{"en":"Independent stationery shops do not have no future; they need a new role.","zh":"獨立文具店並非沒有未來；它們需要新的角色。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"lack in scale","meaning":"規模不足","examples":[{"en":"What they lack in scale, they can make up for in service.","zh":"它們規模不足的地方，可以用服務來彌補。"},{"en":"Lack in scale means being smaller and having fewer resources than bigger competitors.","zh":"lack in scale 指規模較小，資源比大型競爭者少。"},{"en":"A small bakery may lack in scale but know every customer’s favourite bread.","zh":"一間小麵包店可能規模不足，但知道每位顧客最喜歡的麵包。"},{"en":"Shops that lack in scale cannot always lower prices like chain stores.","zh":"規模不足的店舖不一定能像連鎖店那樣減價。"},{"en":"Independent shops can balance their lack in scale with care and expertise.","zh":"獨立店舖可以用關懷和專業知識彌補規模不足。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"make up for","meaning":"彌補","examples":[{"en":"Small shops can make up for their lack of scale with personality.","zh":"小店可以用特色彌補規模不足。"},{"en":"To make up for something means to compensate for a weakness or loss.","zh":"make up for 指補償某個弱點或損失。"},{"en":"A small classroom can make up for limited space with good organisation.","zh":"小課室可以透過良好整理來彌補空間有限。"},{"en":"Friendly service can make up for slightly higher prices.","zh":"友善服務可以彌補價格稍高。"},{"en":"Stationery shops can make up for small size by giving useful advice.","zh":"文具店可以用有用建議彌補規模小的不足。"}],"source":"2020 Q3.pdf","sourcePage":9},{"front":"personality, advice and immediacy","meaning":"特色、建議和即時性","examples":[{"en":"Small shops can offer personality, advice and immediacy.","zh":"小店可以提供特色、建議和即時性。"},{"en":"Personality, advice and immediacy mean character, helpful guidance, and quick local service.","zh":"personality, advice and immediacy 指個性、有用指導和快速本地服務。"},{"en":"A shop has personality when its owner remembers customers and chooses special products.","zh":"當店主記得顧客並選擇特別產品，店舖就有特色。"},{"en":"Advice and immediacy matter when a student needs the right material today.","zh":"當學生今天就需要合適材料，建議和即時性就很重要。"},{"en":"These qualities give small shops something online platforms cannot easily provide.","zh":"這些特質讓小店擁有網上平台難以提供的東西。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"chain store","meaning":"連鎖店","examples":[{"en":"A chain store can sell a pen.","zh":"連鎖店可以賣一支筆。"},{"en":"A chain store is one shop in a larger branded group of shops.","zh":"chain store 是大型品牌店舖群中的其中一間店。"},{"en":"A chain store often has the same products and layout in many districts.","zh":"連鎖店通常在許多地區有相同產品和佈局。"},{"en":"A chain store may be cheaper, but it may not know local school needs.","zh":"連鎖店可能較便宜，但未必知道本地學校需要。"},{"en":"A chain store sells goods; a good local shop can also give advice.","zh":"連鎖店出售貨品；好的本地小店還可以提供建議。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"independent shopkeeper","meaning":"獨立店主","examples":[{"en":"A good independent shopkeeper can give personal advice.","zh":"好的獨立店主可以給予個人建議。"},{"en":"An independent shopkeeper is a person who owns or manages a shop outside a chain.","zh":"independent shopkeeper 指擁有或管理非連鎖店舖的人。"},{"en":"An independent shopkeeper may know which pens local teachers allow.","zh":"獨立店主可能知道本地老師允許使用哪些筆。"},{"en":"Customers trust an independent shopkeeper when the advice is honest and practical.","zh":"當建議誠實而實用，顧客就會信任獨立店主。"},{"en":"A helpful independent shopkeeper can turn a small shop into a community resource.","zh":"樂於助人的獨立店主可以把小店變成社區資源。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"recommend the right ink","meaning":"推薦合適墨水","examples":[{"en":"A shopkeeper can recommend the right ink for left-handed students.","zh":"店主可以為左撇子學生推薦合適墨水。"},{"en":"To recommend the right ink means to suggest ink that suits a person’s writing needs.","zh":"recommend the right ink 指建議適合某人書寫需要的墨水。"},{"en":"A teacher may recommend the right ink for students taking exams.","zh":"老師可能為參加考試的學生推薦合適墨水。"},{"en":"The right ink matters because some ink smudges easily.","zh":"合適墨水很重要，因為有些墨水容易化開。"},{"en":"Personal advice helps customers choose ink better than a simple online photo.","zh":"個人建議比一張簡單網上圖片更能幫助顧客選擇墨水。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"left-handed students","meaning":"左撇子學生","examples":[{"en":"Some pens and inks are better for left-handed students.","zh":"有些筆和墨水較適合左撇子學生。"},{"en":"Left-handed students are students who mainly write with their left hand.","zh":"left-handed students 指主要用左手寫字的學生。"},{"en":"Left-handed students may need fast-drying ink to avoid smudges.","zh":"左撇子學生可能需要快乾墨水，以免弄污字跡。"},{"en":"If pens are not suitable, left-handed students may dirty their hands while writing.","zh":"如果筆不合適，左撇子學生寫字時可能會弄髒手。"},{"en":"A good shopkeeper can help left-handed students find comfortable writing tools.","zh":"好店主可以幫助左撇子學生找到舒適的書寫工具。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"affordable art materials","meaning":"負擔得起的美術材料","examples":[{"en":"A shopkeeper can suggest affordable art materials.","zh":"店主可以建議負擔得起的美術材料。"},{"en":"Affordable art materials are art supplies that students can pay for without spending too much.","zh":"affordable art materials 是學生不用花太多錢也能購買的美術用品。"},{"en":"A parent may ask for affordable art materials for a school display board.","zh":"家長可能為學校展板詢問負擔得起的美術材料。"},{"en":"Affordable art materials help students complete projects without wasting money.","zh":"負擔得起的美術材料幫助學生完成專題，而不浪費金錢。"},{"en":"Small shops can win trust by recommending good materials at fair prices.","zh":"小店可以透過推薦價錢合理的好材料來贏得信任。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"school project","meaning":"學校專題研習","examples":[{"en":"Students may need art materials for a school project.","zh":"學生可能需要美術材料來做學校專題研習。"},{"en":"A school project is a piece of work students complete for a subject or topic.","zh":"school project 是學生為某科目或題目完成的一項作品。"},{"en":"A science school project may need cardboard, markers, and glue.","zh":"科學學校專題研習可能需要卡紙、記號筆和膠水。"},{"en":"School projects can create sudden demand for materials near deadlines.","zh":"學校專題研習在截止日期前可能會突然帶來材料需求。"},{"en":"Stationery shops help when students need school project supplies quickly.","zh":"當學生急需學校專題研習用品，文具店可以幫上忙。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"assemble an exam kit","meaning":"組合考試用品套裝","examples":[{"en":"A shopkeeper can assemble an exam kit at short notice.","zh":"店主可以在短時間通知下組合考試用品套裝。"},{"en":"To assemble an exam kit means to put together the items a student needs for an exam.","zh":"assemble an exam kit 指把學生考試所需物品組合起來。"},{"en":"An exam kit may include pens, pencils, an eraser, a ruler, and correction tape.","zh":"考試用品套裝可能包括原子筆、鉛筆、擦膠、間尺和改錯帶。"},{"en":"Parents are relieved when a shop can assemble an exam kit quickly.","zh":"當店舖能快速組合考試用品套裝，家長會感到放心。"},{"en":"This service shows how small shops can offer practical help, not just products.","zh":"這項服務顯示小店能提供實際幫助，而不只是產品。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"at short notice","meaning":"在短時間通知下","examples":[{"en":"A shop can prepare an exam kit at short notice.","zh":"店舖可以在短時間通知下準備考試用品套裝。"},{"en":"At short notice means with very little time to prepare.","zh":"at short notice 指準備時間很少。"},{"en":"The teacher asked students to bring coloured paper at short notice.","zh":"老師在短時間通知下要求學生帶顏色紙。"},{"en":"Shops that can help at short notice are useful to busy families.","zh":"能在短時間通知下幫忙的店舖，對忙碌家庭很有用。"},{"en":"At short notice, local shops are often faster than online delivery.","zh":"在短時間通知下，本地店舖往往比網上送貨更快。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"moved in this direction","meaning":"朝這個方向發展","examples":[{"en":"Some shops have already moved in this direction.","zh":"有些店舖已經朝這個方向發展。"},{"en":"Moved in this direction means started to change towards a particular plan or style.","zh":"moved in this direction 指開始朝某個計劃或模式改變。"},{"en":"A café moved in this direction by offering study tables and quiet hours.","zh":"一間咖啡店透過提供溫習桌和安靜時段，朝這個方向發展。"},{"en":"Shops move in this direction when ordinary retail no longer works.","zh":"當普通零售不再有效，店舖就會朝這個方向發展。"},{"en":"Stationery shops move in this direction by becoming more specialised and service-based.","zh":"文具店透過變得更專門化和服務化，朝這個方向發展。"}],"source":"2020 Q3.pdf","sourcePage":10},{"front":"Japanese masking tape","meaning":"日本和紙膠帶","examples":[{"en":"Some shops sell Japanese masking tape.","zh":"有些店舖售賣日本和紙膠帶。"},{"en":"Japanese masking tape is decorative adhesive tape often used for crafts, notebooks, and cards.","zh":"Japanese masking tape 是常用於手工藝、筆記簿和賀卡的裝飾膠帶。"},{"en":"Students use Japanese masking tape to decorate project covers.","zh":"學生使用日本和紙膠帶裝飾專題封面。"},{"en":"Customers may prefer choosing Japanese masking tape in person because colours and patterns matter.","zh":"顧客可能較喜歡親身選擇日本和紙膠帶，因為顏色和圖案很重要。"},{"en":"Special items like Japanese masking tape can make a stationery shop feel unique.","zh":"日本和紙膠帶這類特色產品，可以令文具店感覺獨特。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"fountain-pen ink","meaning":"鋼筆墨水","examples":[{"en":"Specialist shops may sell fountain-pen ink.","zh":"專門店可能售賣鋼筆墨水。"},{"en":"Fountain-pen ink is liquid ink used in fountain pens.","zh":"fountain-pen ink 是鋼筆使用的液體墨水。"},{"en":"Writers choose fountain-pen ink by colour, flow, and drying speed.","zh":"寫作者會按顏色、流暢度和乾透速度選擇鋼筆墨水。"},{"en":"Fountain-pen ink is hard to choose online if customers want to test the shade.","zh":"如果顧客想測試色調，鋼筆墨水在網上很難選。"},{"en":"Selling fountain-pen ink can help a shop attract serious writing lovers.","zh":"售賣鋼筆墨水可以幫助店舖吸引認真的書寫愛好者。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"handmade notebooks","meaning":"手工筆記簿","examples":[{"en":"Some shops sell handmade notebooks.","zh":"有些店舖售賣手工筆記簿。"},{"en":"Handmade notebooks are notebooks made by hand or in small batches, often with special designs.","zh":"handmade notebooks 是手工或小批量製作、通常有特別設計的筆記簿。"},{"en":"A student may buy a handmade notebook as a gift for a friend.","zh":"學生可能買一本手工筆記簿作為朋友的禮物。"},{"en":"Handmade notebooks can attract customers who want something personal and different.","zh":"手工筆記簿可以吸引想要個人化和不同產品的顧客。"},{"en":"These notebooks help small shops compete through character rather than price.","zh":"這些筆記簿幫助小店透過特色而不是價格競爭。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"calligraphy brushes","meaning":"毛筆","examples":[{"en":"Some shops sell calligraphy brushes.","zh":"有些店舖售賣毛筆。"},{"en":"Calligraphy brushes are brushes used for artistic writing, especially Chinese calligraphy.","zh":"calligraphy brushes 是用來藝術書寫，特別是中國書法的筆。"},{"en":"Students use calligraphy brushes to practise writing Chinese characters beautifully.","zh":"學生使用毛筆練習把中文字寫得漂亮。"},{"en":"A good shopkeeper can help beginners choose the right calligraphy brush.","zh":"好店主可以幫助初學者選擇合適毛筆。"},{"en":"Calligraphy brushes are easier to choose in person because softness and size matter.","zh":"毛筆親身選擇較容易，因為軟硬度和大小很重要。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"craft supplies","meaning":"手工藝材料","examples":[{"en":"Specialist shops may sell craft supplies.","zh":"專門店可能售賣手工藝材料。"},{"en":"Craft supplies are materials used to make handmade objects or art projects.","zh":"craft supplies 是用來製作手工物品或美術作品的材料。"},{"en":"Craft supplies can include beads, glue, paper, fabric, and tape.","zh":"手工藝材料可以包括珠子、膠水、紙張、布料和膠帶。"},{"en":"Students need craft supplies when they make models or display boards.","zh":"學生製作模型或展示板時，需要手工藝材料。"},{"en":"Craft supplies can bring customers into shops because many people want to see them first.","zh":"手工藝材料可以吸引顧客進店，因為許多人想先親眼看看。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"difficult to choose without seeing them in person","meaning":"不親眼看就難以選擇","examples":[{"en":"Some craft supplies are difficult to choose without seeing them in person.","zh":"有些手工藝材料不親眼看就難以選擇。"},{"en":"Difficult to choose without seeing them in person means hard to select without looking at or touching the real items.","zh":"difficult to choose without seeing them in person 指沒有親眼看或觸摸實物就很難選。"},{"en":"Fabric colours are difficult to choose without seeing them in person.","zh":"布料顏色不親眼看就難以選擇。"},{"en":"If texture and size matter, products are difficult to choose online.","zh":"如果質感和大小很重要，產品在網上就難以選擇。"},{"en":"This gives physical stationery shops an advantage over online platforms.","zh":"這令實體文具店比網上平台更有優勢。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"in person","meaning":"親身；當面","examples":[{"en":"Customers may prefer to choose craft supplies in person.","zh":"顧客可能較喜歡親身選擇手工藝材料。"},{"en":"In person means physically present, not online or through another person.","zh":"in person 指親身在場，而不是在網上或透過別人。"},{"en":"Parents may visit a shop in person to check the quality of school bags.","zh":"家長可能親身到店查看書包質素。"},{"en":"Some products are easier to judge in person because colour and texture matter.","zh":"有些產品親身判斷較容易，因為顏色和質感很重要。"},{"en":"In person service can make customers feel more confident about what they buy.","zh":"親身服務可以令顧客對所買的東西更有信心。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"run simple workshops","meaning":"舉辦簡單工作坊","examples":[{"en":"Some stationery shops run simple workshops.","zh":"有些文具店舉辦簡單工作坊。"},{"en":"To run simple workshops means to organise easy practical classes for customers.","zh":"run simple workshops 指為顧客舉辦容易參與的實用課程。"},{"en":"A shop may run simple workshops on card making before Christmas.","zh":"店舖可能在聖誕節前舉辦製作賀卡的簡單工作坊。"},{"en":"Workshops bring people into the shop and help them use the products.","zh":"工作坊能吸引人進店，並幫助他們使用產品。"},{"en":"Simple workshops can turn a stationery shop into a small community space.","zh":"簡單工作坊可以把文具店變成小型社區空間。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"take WhatsApp orders","meaning":"接受 WhatsApp 訂單","examples":[{"en":"Some shops take WhatsApp orders from parents.","zh":"有些店舖接受家長的 WhatsApp 訂單。"},{"en":"To take WhatsApp orders means to accept customer orders through WhatsApp messages.","zh":"take WhatsApp orders 指透過 WhatsApp 訊息接受顧客訂單。"},{"en":"A parent can send a photo of a supply list and let the shop prepare everything.","zh":"家長可以傳送用品清單照片，讓店舖準備所有物品。"},{"en":"WhatsApp orders save time while keeping the connection with a local shop.","zh":"WhatsApp 訂單節省時間，同時保留與本地店舖的聯繫。"},{"en":"Taking WhatsApp orders helps small shops become more convenient without losing personal service.","zh":"接受 WhatsApp 訂單能幫助小店變得更方便，而不失去個人化服務。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"prepare customised school packs","meaning":"準備度身訂造的學校用品套裝","examples":[{"en":"Some shops prepare customised school packs before term begins.","zh":"有些店舖在開學前準備度身訂造的學校用品套裝。"},{"en":"To prepare customised school packs means to put together supply sets based on a student’s school needs.","zh":"prepare customised school packs 指根據學生的學校需要組合用品套裝。"},{"en":"A customised school pack may include notebooks, files, pens, and art paper.","zh":"度身訂造的學校用品套裝可能包括筆記簿、文件夾、筆和美術紙。"},{"en":"Parents save time when shops prepare customised school packs for each grade.","zh":"當店舖為每個級別準備度身訂造的學校用品套裝，家長就能節省時間。"},{"en":"This service lets small shops compete through convenience and local knowledge.","zh":"這項服務讓小店透過便利和本地知識競爭。"}],"source":"2020 Q3.pdf","sourcePage":11},{"front":"before the term begins","meaning":"開學前","examples":[{"en":"Shops prepare school packs before the term begins.","zh":"店舖在開學前準備學校用品套裝。"},{"en":"Before the term begins means before a new school period starts.","zh":"before the term begins 指新學期開始之前。"},{"en":"Parents buy uniforms before the term begins.","zh":"家長在開學前購買校服。"},{"en":"If shops prepare early before the term begins, students can start school smoothly.","zh":"如果店舖在開學前及早準備，學生就能順利開學。"},{"en":"The weeks before the term begins are important for stationery shops.","zh":"開學前幾星期對文具店很重要。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"by nostalgia alone","meaning":"單靠懷舊情懷","examples":[{"en":"Survival will not happen by nostalgia alone.","zh":"生存不會單靠懷舊情懷發生。"},{"en":"By nostalgia alone means only because people miss the past, without practical change.","zh":"by nostalgia alone 指只靠人們懷念過去，而沒有實際改變。"},{"en":"A cinema cannot survive by nostalgia alone if it offers poor seats and high prices.","zh":"如果座位差、價格高，戲院不能單靠懷舊情懷生存。"},{"en":"Nostalgia may bring attention, but service and usefulness keep customers.","zh":"懷舊情懷可能帶來注意，但服務和實用性才能留住顧客。"},{"en":"Stationery shops need more than warm memories to survive.","zh":"文具店需要的不只是溫暖回憶，才能生存。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"build online catalogues","meaning":"建立網上目錄","examples":[{"en":"Shop owners need to build online catalogues.","zh":"店主需要建立網上目錄。"},{"en":"To build online catalogues means to create digital lists or pages showing products for sale.","zh":"build online catalogues 指建立展示出售產品的數碼清單或頁面。"},{"en":"A small shop can build an online catalogue with photos and prices.","zh":"小店可以用照片和價格建立網上目錄。"},{"en":"Online catalogues help parents check products before sending orders.","zh":"網上目錄幫助家長在下單前查看產品。"},{"en":"Building online catalogues lets local shops join digital habits without becoming faceless.","zh":"建立網上目錄讓本地小店配合數碼習慣，同時不失去人情味。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"keep a sharper selection of products","meaning":"保持更精準的選品","examples":[{"en":"Shops need to keep a sharper selection of products.","zh":"店舖需要保持更精準的選品。"},{"en":"To keep a sharper selection of products means to choose goods more carefully and focus on what customers really need.","zh":"keep a sharper selection of products 指更仔細地選貨，集中在顧客真正需要的東西。"},{"en":"A small bookshop keeps a sharper selection by selling titles local readers ask for.","zh":"小書店透過出售本地讀者常問的書，保持更精準的選品。"},{"en":"A sharper selection reduces unsold stock and makes shelves more attractive.","zh":"更精準的選品可以減少滯銷存貨，令貨架更吸引。"},{"en":"Stationery shops should not sell everything; they should sell the right things.","zh":"文具店不應甚麼都賣；它們應該賣對的東西。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"work more closely with","meaning":"與……更緊密合作","examples":[{"en":"Shops should work more closely with schools and local artists.","zh":"店舖應與學校和本地藝術家更緊密合作。"},{"en":"To work more closely with someone means to cooperate more often and more directly.","zh":"work more closely with someone 指更經常、更直接地合作。"},{"en":"A library can work more closely with teachers to support reading lessons.","zh":"圖書館可以與老師更緊密合作，以支援閱讀課。"},{"en":"Shops that work more closely with schools can understand supply needs earlier.","zh":"與學校更緊密合作的店舖，可以更早了解用品需要。"},{"en":"Working more closely with local artists can bring special products and workshops.","zh":"與本地藝術家更緊密合作，可以帶來特色產品和工作坊。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"local artists","meaning":"本地藝術家","examples":[{"en":"Stationery shops can work with local artists.","zh":"文具店可以與本地藝術家合作。"},{"en":"Local artists are people in the community who create art, design, or craft work.","zh":"local artists 是在社區中創作藝術、設計或手工藝作品的人。"},{"en":"Local artists may design notebooks, postcards, or stickers for small shops.","zh":"本地藝術家可能為小店設計筆記簿、明信片或貼紙。"},{"en":"Working with local artists can give a shop products that chain stores do not have.","zh":"與本地藝術家合作，可以讓店舖擁有連鎖店沒有的產品。"},{"en":"Local artists help stationery shops build character and community identity.","zh":"本地藝術家幫助文具店建立特色和社區身份。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"bid for supply lists","meaning":"競投用品清單","examples":[{"en":"Schools can allow small shops to bid for supply lists.","zh":"學校可以讓小店競投用品清單。"},{"en":"To bid for supply lists means to compete for the chance to provide required school items.","zh":"bid for supply lists 指競爭提供學校所需用品的機會。"},{"en":"A local shop may bid for a school’s art supply list before term begins.","zh":"本地小店可能在開學前競投學校的美術用品清單。"},{"en":"If small shops can bid for supply lists, they gain fairer access to school business.","zh":"如果小店能競投用品清單，它們就能較公平地接觸學校生意。"},{"en":"This helps schools support the community instead of choosing only large distributors.","zh":"這幫助學校支援社區，而不是只選擇大型分銷商。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"supply lists","meaning":"用品清單","examples":[{"en":"Small shops should have a chance to bid for supply lists.","zh":"小店應有機會競投用品清單。"},{"en":"Supply lists are lists of items students or schools need for lessons.","zh":"supply lists 是列出學生或學校上課所需物品的清單。"},{"en":"A supply list may include files, pens, exercise books, and art materials.","zh":"用品清單可能包括文件夾、筆、練習簿和美術材料。"},{"en":"When schools give supply lists only to large sellers, small shops lose business.","zh":"當學校只把用品清單交給大型賣家，小店就會失去生意。"},{"en":"Sharing supply lists with local shops can keep neighbourhood retail alive.","zh":"與本地小店分享用品清單，可以令社區零售保持活力。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"relying only on","meaning":"只依賴","examples":[{"en":"Schools should avoid relying only on large distributors.","zh":"學校應避免只依賴大型分銷商。"},{"en":"Relying only on something means depending on that one thing and not using other choices.","zh":"relying only on something 指只依靠某一樣東西，而不使用其他選擇。"},{"en":"Students should avoid relying only on memorisation when learning English.","zh":"學生學英文時，應避免只依賴死記硬背。"},{"en":"Schools that rely only on large distributors may weaken nearby shops.","zh":"只依賴大型分銷商的學校，可能會削弱附近小店。"},{"en":"Using several suppliers can be fairer than relying only on one large company.","zh":"使用幾個供應來源，比只依賴一間大公司更公平。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"large distributors","meaning":"大型分銷商","examples":[{"en":"Schools often rely on large distributors.","zh":"學校常依賴大型分銷商。"},{"en":"Large distributors are big companies that supply goods to many shops, schools, or organisations.","zh":"large distributors 是向許多店舖、學校或機構供應貨品的大公司。"},{"en":"A large distributor can deliver thousands of notebooks to several schools.","zh":"大型分銷商可以向幾間學校運送數千本筆記簿。"},{"en":"Large distributors may be efficient, but they can reduce opportunities for small shops.","zh":"大型分銷商可能很有效率，但會減少小店的機會。"},{"en":"Schools should balance convenience with support for local businesses.","zh":"學校應在便利與支援本地商戶之間取得平衡。"}],"source":"2020 Q3.pdf","sourcePage":12},{"front":"landlords","meaning":"業主","examples":[{"en":"Landlords also have a role to play.","zh":"業主也有角色要發揮。"},{"en":"Landlords are people or companies that own property and rent it to others.","zh":"landlords 是擁有物業並出租給他人的人或公司。"},{"en":"A landlord may reduce rent to help a long-time neighbourhood shop survive.","zh":"業主可能減租，幫助一間經營多年的社區小店生存。"},{"en":"If landlords raise rents too quickly, small shops may disappear.","zh":"如果業主太快加租，小店可能會消失。"},{"en":"Landlords affect the retail mix of a street through their rental decisions.","zh":"業主透過租金決定影響一條街的零售組合。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"district organisations","meaning":"地區組織","examples":[{"en":"District organisations can help protect neighbourhood shops.","zh":"地區組織可以幫助保護社區店舖。"},{"en":"District organisations are local groups that work on community issues in an area.","zh":"district organisations 是在某區處理社區議題的本地團體。"},{"en":"District organisations may organise markets, publicity, or support schemes for small shops.","zh":"地區組織可能為小店舉辦市集、宣傳或支援計劃。"},{"en":"If district organisations promote local shopping, residents may return to neighbourhood stores.","zh":"如果地區組織推廣本地購物，居民可能會重新光顧社區店舖。"},{"en":"These organisations can connect schools, shopkeepers, artists, and residents.","zh":"這些組織可以連繫學校、店主、藝術家和居民。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"have a role to play","meaning":"有角色要發揮","examples":[{"en":"Residents also have a role to play.","zh":"居民也有角色要發揮。"},{"en":"Have a role to play means have responsibility or an important part in helping something happen.","zh":"have a role to play 指在幫助某事發生方面有責任或重要作用。"},{"en":"Parents have a role to play in teaching children to read.","zh":"家長在教孩子閱讀方面有角色要發揮。"},{"en":"Residents have a role to play because their shopping choices affect local shops.","zh":"居民有角色要發揮，因為他們的購物選擇影響本地店舖。"},{"en":"Everyone has a role to play if a community wants to keep useful small businesses.","zh":"如果社區想保留有用的小商戶，每個人都有角色要發揮。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"be replaced by","meaning":"被……取代","examples":[{"en":"Every neighbourhood shop could be replaced by the same chain stores.","zh":"每間社區小店都可能被相同的連鎖店取代。"},{"en":"Be replaced by means be taken away and have something else put in its place.","zh":"be replaced by 指被拿走，並由另一事物放在原來位置。"},{"en":"The old cinema was replaced by a supermarket.","zh":"舊戲院被一間超級市場取代。"},{"en":"If small shops are replaced by chain stores, streets may lose variety.","zh":"如果小店被連鎖店取代，街道可能會失去多樣性。"},{"en":"A city becomes less personal when unique shops are replaced by identical brands.","zh":"當獨特店舖被相同品牌取代，城市會變得不太有人情味。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"not just… but also…","meaning":"不只是……而且是……","examples":[{"en":"Hong Kong will lose not just variety but also everyday warmth.","zh":"香港失去的不只是多樣性，而且是日常人情味。"},{"en":"Not just A but also B means both things are true, and the second is important too.","zh":"not just A but also B 指兩件事都是真的，而且第二件事也很重要。"},{"en":"A library offers not just books but also a quiet place to study.","zh":"圖書館提供的不只是書，而且是安靜的溫習地方。"},{"en":"Losing small shops means losing not just products but also personal relationships.","zh":"失去小店意味着失去的不只是產品，而且是人與人之間的關係。"},{"en":"This phrase adds weight by showing that the loss is wider than it first seems.","zh":"這個片語透過顯示損失比表面更廣，令語氣更有力。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"everyday warmth","meaning":"日常人情味","examples":[{"en":"Small neighbourhood shops give Hong Kong a kind of everyday warmth.","zh":"小型社區店舖給香港一種日常人情味。"},{"en":"Everyday warmth means the friendly human feeling found in ordinary daily life.","zh":"everyday warmth 指普通日常生活中的友善人情感。"},{"en":"A shopkeeper greeting children by name creates everyday warmth.","zh":"店主叫得出孩子名字來打招呼，會創造日常人情味。"},{"en":"Cities lose everyday warmth when every street looks the same.","zh":"當每條街都看起來一樣，城市就會失去日常人情味。"},{"en":"Independent stationery shops add everyday warmth through familiar faces and small help.","zh":"獨立文具店透過熟悉面孔和細小幫助，增添日常人情味。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"for now","meaning":"目前","examples":[{"en":"For now, independent stationery shops are down, but not necessarily out.","zh":"目前，獨立文具店受挫，但未必出局。"},{"en":"For now means at the present time, although things may change later.","zh":"for now 指在目前這段時間，雖然之後可能改變。"},{"en":"For now, the shop closes early because there are not enough staff.","zh":"目前，店舖因人手不足而提早關門。"},{"en":"A situation may look difficult for now, but improvement is still possible.","zh":"情況目前可能看似困難，但仍有改善可能。"},{"en":"For now, stationery shops are struggling, but some can still adapt.","zh":"目前，文具店正在掙扎，但有些仍能適應。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"down, but not necessarily out","meaning":"受挫但未必出局","examples":[{"en":"Independent stationery shops are down, but not necessarily out.","zh":"獨立文具店受挫，但未必出局。"},{"en":"Down, but not necessarily out means badly hurt or weakened, but not finished.","zh":"down, but not necessarily out 指受到嚴重打擊或變弱，但尚未完結。"},{"en":"The football team was down, but not necessarily out, after losing the first match.","zh":"足球隊輸了第一場後受挫，但未必出局。"},{"en":"A shop may be down, but not out, if it still has loyal customers and new ideas.","zh":"如果店舖仍有忠實顧客和新想法，它可能受挫但未出局。"},{"en":"This phrase gives hope while still admitting the situation is serious.","zh":"這個片語在承認情況嚴重的同時，也帶出希望。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"not necessarily","meaning":"未必","examples":[{"en":"Independent shops are not necessarily finished.","zh":"獨立店舖未必已經完結。"},{"en":"Not necessarily means something may not be true in every case.","zh":"not necessarily 指某事未必在所有情況下都是真的。"},{"en":"Expensive products are not necessarily better than cheaper ones.","zh":"昂貴產品未必比便宜產品好。"},{"en":"A small shop is not necessarily weak if it offers special service.","zh":"如果小店提供特別服務，它未必脆弱。"},{"en":"Stationery shops are struggling, but they are not necessarily doomed.","zh":"文具店正在掙扎，但未必注定失敗。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"merely wait for","meaning":"只是等待","examples":[{"en":"Shops that merely wait for the old days to return are likely to disappear.","zh":"只是等待昔日光景重臨的店舖，很可能會消失。"},{"en":"Merely wait for means only wait passively without taking action.","zh":"merely wait for 指只是被動等待，而沒有採取行動。"},{"en":"A student cannot merely wait for good grades without studying.","zh":"學生不能只是等待好成績，而不溫習。"},{"en":"Shops that merely wait for customers may lose them to faster services.","zh":"只是等待顧客的店舖，可能會把顧客輸給更快的服務。"},{"en":"Survival requires action, not merely waiting for better times.","zh":"生存需要行動，而不是只是等待好日子。"}],"source":"2020 Q3.pdf","sourcePage":13},{"front":"the old days to return","meaning":"昔日光景重臨","examples":[{"en":"Some shops are waiting for the old days to return.","zh":"有些店舖正在等待昔日光景重臨。"},{"en":"The old days to return means past habits or better times coming back.","zh":"the old days to return 指過去的習慣或好時光再次回來。"},{"en":"A cinema owner may hope for the old days to return when people watched movies every weekend.","zh":"戲院老闆可能希望昔日光景重臨，人人每個週末都看電影。"},{"en":"Waiting for the old days to return can stop a business from adapting.","zh":"等待昔日光景重臨，可能會阻止生意適應變化。"},{"en":"Stationery shops cannot depend on the old days returning because students now study differently.","zh":"文具店不能依賴昔日光景重臨，因為學生現在的學習方式不同。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"likely to disappear","meaning":"很可能消失","examples":[{"en":"Shops that wait for the past to return are likely to disappear.","zh":"等待過去重臨的店舖很可能消失。"},{"en":"Likely to disappear means probably going to vanish, close, or stop existing.","zh":"likely to disappear 指很可能消失、結業或不再存在。"},{"en":"A small stall is likely to disappear if the owner cannot pay rent.","zh":"如果檔主無法支付租金，小攤檔很可能消失。"},{"en":"Businesses are likely to disappear when they ignore changing customer habits.","zh":"當生意忽視顧客習慣改變，它們很可能消失。"},{"en":"Stationery shops that refuse to change are more likely to disappear.","zh":"拒絕改變的文具店更可能消失。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"offer expertise","meaning":"提供專業知識","examples":[{"en":"The strongest shops offer expertise, character and convenience.","zh":"最強的店舖提供專業知識、特色和便利。"},{"en":"To offer expertise means to provide useful specialist knowledge.","zh":"offer expertise 指提供有用的專門知識。"},{"en":"A camera shop offers expertise when it explains which lens suits a beginner.","zh":"相機店解釋哪個鏡頭適合初學者時，就是在提供專業知識。"},{"en":"Stationery shops offer expertise by helping students choose suitable pens, paper, and ink.","zh":"文具店透過幫助學生選擇合適的筆、紙和墨水來提供專業知識。"},{"en":"Expertise gives small shops a reason to exist beyond low prices.","zh":"專業知識讓小店在低價以外有存在理由。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"character and convenience","meaning":"特色和便利","examples":[{"en":"Successful shops need character and convenience.","zh":"成功的店舖需要特色和便利。"},{"en":"Character and convenience mean a shop feels distinctive and is also easy to use.","zh":"character and convenience 指店舖有獨特感，同時也容易使用。"},{"en":"A café has character and convenience if it serves unique drinks near an MTR station.","zh":"如果咖啡店在港鐵站附近提供特色飲品，它就有特色和便利。"},{"en":"Character attracts customers, while convenience helps them return.","zh":"特色吸引顧客，而便利令他們回來。"},{"en":"Stationery shops need both personality and practical service to survive.","zh":"文具店需要個性和實用服務，才能生存。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"still be standing","meaning":"仍然屹立不倒","examples":[{"en":"Useful and personal shops may still be standing when the dust settles.","zh":"有用而有人情味的店舖在塵埃落定時可能仍然屹立不倒。"},{"en":"Still be standing means continue to exist after difficulty or competition.","zh":"still be standing 指經歷困難或競爭後仍然存在。"},{"en":"After many restaurants closed, the family noodle shop was still standing.","zh":"許多餐廳結業後，那間家庭麵店仍然屹立不倒。"},{"en":"Shops with loyal customers are more likely to still be standing after hard times.","zh":"有忠實顧客的店舖，在艱難時期後更可能仍然屹立不倒。"},{"en":"Stationery shops that adapt may still be standing in a digital retail world.","zh":"能適應的文具店，在數碼零售世界中可能仍然屹立不倒。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"when the dust settles","meaning":"塵埃落定時","examples":[{"en":"Some shops may still be standing when the dust settles.","zh":"有些店舖在塵埃落定時可能仍然屹立不倒。"},{"en":"When the dust settles means after confusion, change, or conflict has calmed down.","zh":"when the dust settles 指混亂、改變或衝突平息之後。"},{"en":"After the school merger, people will know what remains when the dust settles.","zh":"學校合併後，人們會在塵埃落定時知道還剩下甚麼。"},{"en":"Businesses must survive uncertainty before seeing where they stand when the dust settles.","zh":"生意必須先捱過不確定，才能在塵埃落定時看清自己的位置。"},{"en":"When the dust settles, the shops that changed early may be the strongest.","zh":"塵埃落定時，最早改變的店舖可能會最強。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"fast-changing retail scene","meaning":"變化急速的零售環境","examples":[{"en":"Hong Kong has a fast-changing retail scene.","zh":"香港有一個變化急速的零售環境。"},{"en":"A fast-changing retail scene is a shopping environment where customer habits and business conditions change quickly.","zh":"fast-changing retail scene 指顧客習慣和營商條件快速改變的購物環境。"},{"en":"Online payment, delivery apps, and high rent create a fast-changing retail scene.","zh":"電子支付、送貨應用程式和高租金創造了變化急速的零售環境。"},{"en":"Small shops must adjust quickly in a fast-changing retail scene.","zh":"在變化急速的零售環境中，小店必須快速調整。"},{"en":"Hong Kong’s fast-changing retail scene rewards shops that are useful and flexible.","zh":"香港變化急速的零售環境，會獎勵有用而靈活的店舖。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"not by being cheaper, but by being more useful","meaning":"不是靠更便宜，而是靠更有用","examples":[{"en":"The smallest shops may survive not by being cheaper, but by being more useful.","zh":"最小的店舖可能不是靠更便宜，而是靠更有用來生存。"},{"en":"Not by being cheaper, but by being more useful means usefulness, not low price, is the survival strategy.","zh":"not by being cheaper, but by being more useful 指生存策略不是低價，而是實用性。"},{"en":"A small repair shop survives not by being cheaper, but by being more reliable.","zh":"小型維修店不是靠更便宜，而是靠更可靠來生存。"},{"en":"Stationery shops cannot always beat online prices, so they must be more useful.","zh":"文具店不一定能擊敗網上價格，所以必須變得更有用。"},{"en":"This phrase shows a clear contrast between price competition and service value.","zh":"這個片語清楚對比價格競爭和服務價值。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"more personal","meaning":"更有人情味；更個人化","examples":[{"en":"Independent shops can survive by being more personal.","zh":"獨立店舖可以靠更有人情味來生存。"},{"en":"More personal means more connected to individual customers and their needs.","zh":"more personal 指更貼近個別顧客和他們的需要。"},{"en":"A tutor gives more personal help when she knows each student’s weakness.","zh":"補習老師了解每個學生的弱點時，會給予更個人化的幫助。"},{"en":"Shops become more personal when they remember regular customers and give tailored advice.","zh":"當店舖記得固定顧客並提供度身建議，就會變得更有人情味。"},{"en":"Being more personal helps small shops offer what large platforms cannot.","zh":"更有人情味能幫助小店提供大型平台無法提供的東西。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"deeply rooted in","meaning":"深深紮根於","examples":[{"en":"The shops can survive by being deeply rooted in their communities.","zh":"這些店舖可以靠深深紮根於社區而生存。"},{"en":"Deeply rooted in means strongly connected to a place, group, or tradition over time.","zh":"deeply rooted in 指長時間與某地方、群體或傳統有強烈連繫。"},{"en":"A family restaurant is deeply rooted in the neighbourhood after serving residents for decades.","zh":"一間家庭餐廳服務居民幾十年後，深深紮根於社區。"},{"en":"Shops deeply rooted in the community understand local habits and needs.","zh":"深深紮根於社區的店舖，了解本地習慣和需要。"},{"en":"Stationery shops survive better when residents see them as part of the community.","zh":"當居民把文具店視為社區的一部分，它們會更容易生存。"}],"source":"2020 Q3.pdf","sourcePage":14},{"front":"the communities they serve","meaning":"它們服務的社區","examples":[{"en":"The smallest shops may survive by serving their communities well.","zh":"最小的店舖可能透過好好服務它們的社區而生存。"},{"en":"The communities they serve means the local people and neighbourhoods that the shops help.","zh":"the communities they serve 指店舖幫助的本地居民和社區。"},{"en":"A clinic serves its community well when it understands elderly patients’ needs.","zh":"診所了解長者病人的需要時，就是好好服務它的社區。"},{"en":"Shops that serve their communities well provide goods, advice, and familiar human contact.","zh":"好好服務社區的店舖會提供貨品、建議和熟悉的人情接觸。"},{"en":"Stationery shops survive when the communities they serve still see them as useful.","zh":"當它們服務的社區仍然覺得文具店有用，文具店就能生存。"}],"source":"2020 Q3.pdf","sourcePage":15}],"dse/writing/part-b/2020/Q4":[{"front":"application for transfer","meaning":"調職申請","examples":[{"en":"Chris writes an application for transfer to the Shanghai branch.","zh":"Chris 寫了一封調職申請，希望調到上海分店。"},{"en":"An application for transfer is a formal request to move from one position, department, or branch to another.","zh":"調職申請是正式要求從一個職位、部門或分店轉到另一個地方工作的文件。"},{"en":"A nurse may write an application for transfer if she wants to move from a night-shift team to a daytime clinic.","zh":"如果護士想由夜班團隊轉到日間診所，可能會寫一封調職申請。"},{"en":"A clear application for transfer should explain the reason, the applicant’s experience, and how the move would help the organisation.","zh":"清楚的調職申請應解釋原因、申請人的經驗，以及這次調動如何幫助機構。"},{"en":"An application for transfer is stronger when it shows benefits for both the employee and the employer.","zh":"當調職申請能顯示對員工和僱主都有好處時，說服力會更強。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"transfer to","meaning":"調職到……","examples":[{"en":"I am writing to apply for a transfer to our Shanghai branch.","zh":"本人寫信申請調職到上海分店。"},{"en":"To transfer to a place means to move officially from one workplace, school, team, or branch to another.","zh":"「調職到……」指正式由一個工作地點、學校、團隊或分店轉到另一個。"},{"en":"My colleague hopes to transfer to the marketing department next year.","zh":"我的同事希望明年調職到市場部。"},{"en":"A staff member may transfer to another branch when their skills are needed there.","zh":"當另一間分店需要某位員工的技能時，該員工可能會調職到那裏。"},{"en":"Before asking to transfer to a new post, it is important to understand the duties and expectations.","zh":"在申請調職到新職位前，了解職責和期望很重要。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"Shanghai branch","meaning":"上海分店","examples":[{"en":"I am writing to apply for a transfer to our Shanghai branch.","zh":"本人寫信申請調職到上海分店。"},{"en":"The Shanghai branch is the part of the company that operates in Shanghai.","zh":"上海分店是公司在上海營運的部分。"},{"en":"The Shanghai branch handles guests, customers, or business connected with the Shanghai market.","zh":"上海分店處理與上海市場有關的住客、顧客或業務。"},{"en":"A company may send experienced staff to the Shanghai branch when it wants to improve service there.","zh":"當公司希望改善上海的服務時，可能會派有經驗的員工到上海分店。"},{"en":"Working at the Shanghai branch can help employees understand a different local market.","zh":"在上海分店工作可以幫助員工了解另一個本地市場。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"Dear Mr Wong","meaning":"黃先生鈞鑒","examples":[{"en":"Dear Mr Wong, I am writing to apply for a transfer.","zh":"黃先生鈞鑒：本人寫信申請調職。"},{"en":"“Dear Mr Wong” is a formal greeting used at the beginning of a letter or email to a man named Mr Wong.","zh":"“Dear Mr Wong” 是寫給黃先生的信件或電郵開首所用的正式稱呼。"},{"en":"Dear Mr Wong, thank you for considering my request for leave.","zh":"黃先生鈞鑒：感謝你考慮本人的請假申請。"},{"en":"In a formal workplace letter, using “Dear Mr Wong” shows respect and identifies the recipient clearly.","zh":"在正式職場信件中使用 “Dear Mr Wong”，可以表示尊重並清楚指出收件人。"},{"en":"“Dear Mr Wong” is more formal than beginning a work email with only the person’s first name.","zh":"“Dear Mr Wong” 比只用對方名字開首的工作電郵更正式。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"I am writing to apply for","meaning":"本人寫信申請……","examples":[{"en":"I am writing to apply for a transfer from Park Hotel Hong Kong.","zh":"本人寫信申請從香港百樂酒店調職。"},{"en":"“I am writing to apply for” is a formal way to state what position, opportunity, or request you are applying for.","zh":"“I am writing to apply for” 是正式說明自己申請某個職位、機會或請求的句式。"},{"en":"I am writing to apply for the position of receptionist advertised on your website.","zh":"本人寫信申請貴公司網站上刊登的接待員職位。"},{"en":"This phrase is useful in application letters because it tells the reader the purpose immediately.","zh":"這個句式適合用於申請信，因為它立即告訴讀者寫信目的。"},{"en":"After “I am writing to apply for,” you should clearly name the job, transfer, scholarship, or opportunity.","zh":"在 “I am writing to apply for” 之後，應清楚寫明職位、調職、獎學金或機會。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"should a suitable position become available","meaning":"如有合適職位空缺","examples":[{"en":"I would like to transfer should a suitable position become available.","zh":"如有合適職位空缺，本人希望能調職。"},{"en":"“Should a suitable position become available” means if an appropriate job opening appears in the future.","zh":"“Should a suitable position become available” 指如果將來出現合適的職位空缺。"},{"en":"I would be interested in joining the Tokyo office should a suitable position become available.","zh":"如東京辦公室有合適職位空缺，本人有意加入。"},{"en":"This phrase sounds formal because it places “should” before the subject instead of using “if.”","zh":"這個說法較正式，因為它把 “should” 放在主語之前，而不是直接使用 “if”。"},{"en":"It is useful when you want to show interest politely without assuming that a vacancy already exists.","zh":"當你想禮貌地表達興趣，而不假定已有空缺時，這個句式很有用。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"a suitable position","meaning":"合適職位","examples":[{"en":"I would like to apply if a suitable position becomes available.","zh":"如有合適職位空缺，本人希望申請。"},{"en":"A suitable position is a job that matches someone’s skills, experience, goals, or situation.","zh":"合適職位是與某人的技能、經驗、目標或情況相配的工作。"},{"en":"A suitable position for an experienced receptionist may involve guest service and team coordination.","zh":"對有經驗的接待員來說，合適職位可能包括賓客服務和團隊協調。"},{"en":"Finding a suitable position matters because a poor match can waste both the employee’s and the company’s time.","zh":"找到合適職位很重要，因為不合適的配對會浪費員工和公司的時間。"},{"en":"A position may be available, but it is suitable only if the duties and requirements fit the applicant.","zh":"一個職位可能有空缺，但只有在職責和要求配合申請人時，才算合適。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"become available","meaning":"有空缺；可供申請","examples":[{"en":"A suitable position may become available at the Shanghai branch.","zh":"上海分店可能會有合適職位空缺。"},{"en":"If a position becomes available, it means people can now apply for it because there is an opening.","zh":"如果一個職位 become available，表示現在有空缺，其他人可以申請。"},{"en":"A place in the training course may become available if another student withdraws.","zh":"如果有學生退出，培訓課程可能會有名額可供申請。"},{"en":"Jobs often become available when staff leave, teams expand, or new projects begin.","zh":"當員工離職、團隊擴展或新項目開始時，職位常會出現空缺。"},{"en":"When an opportunity becomes available, applicants should respond quickly and professionally.","zh":"當機會出現並可供申請時，申請人應迅速而專業地回應。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"having served","meaning":"在……服務了","examples":[{"en":"Having served the hotel for four years, I understand its service standards well.","zh":"在酒店服務了四年後，本人十分了解其服務標準。"},{"en":"“Having served” means after working for or supporting an organisation for a period of time.","zh":"“Having served” 指在某機構工作或服務了一段時間之後。"},{"en":"Having served the school as a prefect for two years, she understood how to guide younger students.","zh":"在學校擔任領袖生兩年後，她明白如何指導低年級學生。"},{"en":"Having served a company for many years can give an employee deep knowledge of its culture and systems.","zh":"在一間公司服務多年，可以令員工深入了解公司的文化和制度。"},{"en":"This phrase is often used before explaining what experience has taught someone.","zh":"這個說法常用於解釋經驗教會了某人甚麼之前。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"most recently as","meaning":"最近擔任","examples":[{"en":"I have served most recently as a Senior Guest Relations Officer.","zh":"本人最近擔任高級賓客服務主任。"},{"en":"“Most recently as” introduces the latest role or position someone has held.","zh":"“Most recently as” 用來介紹某人最近或最新擔任的職位。"},{"en":"She worked in several departments, most recently as an assistant manager in customer service.","zh":"她曾在多個部門工作，最近擔任客戶服務助理經理。"},{"en":"This phrase is useful in applications because it shows the reader the applicant’s current or latest experience.","zh":"這個說法適合用於申請信，因為它讓讀者知道申請人目前或最近的經驗。"},{"en":"When using “most recently as,” the position that follows should be the newest one, not the oldest.","zh":"使用 “most recently as” 時，後面應接最新職位，而不是最早的職位。"}],"source":"2020 Q4.pdf","sourcePage":1},{"front":"Senior Guest Relations Officer","meaning":"高級賓客服務主任","examples":[{"en":"I have worked most recently as a Senior Guest Relations Officer.","zh":"本人最近擔任高級賓客服務主任。"},{"en":"A Senior Guest Relations Officer is an experienced hotel staff member who handles guest needs, problems, and service communication.","zh":"高級賓客服務主任是有經驗的酒店職員，負責處理住客需要、問題和服務溝通。"},{"en":"A Senior Guest Relations Officer may welcome VIP guests and help solve complaints.","zh":"高級賓客服務主任可能負責接待貴賓和協助處理投訴。"},{"en":"This role requires patience, clear communication, and strong knowledge of hotel services.","zh":"這個職位需要耐性、清晰溝通能力，以及對酒店服務的充分了解。"},{"en":"A good Senior Guest Relations Officer protects the hotel’s image by making guests feel respected and supported.","zh":"優秀的高級賓客服務主任會令住客感到被尊重和支持，從而保護酒店形象。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"come to see","meaning":"逐漸明白","examples":[{"en":"I have come to see hospitality as earning trust at every point of a guest’s journey.","zh":"我逐漸明白，酒店款待服務是在住客旅程的每一個環節贏得信任。"},{"en":"To come to see something in a certain way means to gradually understand or believe it through experience.","zh":"“Come to see” 指透過經驗逐漸理解或相信某事。"},{"en":"After working with children, I came to see teaching as listening, not only explaining.","zh":"與孩子工作後，我逐漸明白教學不只是解釋，也包括聆聽。"},{"en":"People often come to see a job differently after facing real problems in that field.","zh":"人們在某個行業面對真實問題後，常會逐漸以不同方式理解那份工作。"},{"en":"This phrase shows a change in understanding that develops over time.","zh":"這個說法顯示一種隨時間形成的理解轉變。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"hospitality","meaning":"酒店款待服務","examples":[{"en":"I have come to see hospitality as earning trust throughout a guest’s stay.","zh":"我逐漸明白，酒店款待服務是在住客整個住宿期間贏得信任。"},{"en":"Hospitality is the service of welcoming, caring for, and helping guests, especially in hotels, restaurants, or travel.","zh":"酒店款待服務指歡迎、照顧和協助客人的服務，尤其出現在酒店、餐廳或旅遊行業。"},{"en":"Good hospitality includes greeting guests warmly, answering questions clearly, and solving problems quickly.","zh":"良好的款待服務包括熱情迎接客人、清楚回答問題和迅速解決困難。"},{"en":"Poor hospitality can make guests feel ignored even if the room or meal is expensive.","zh":"即使房間或餐飲昂貴，差劣的款待服務仍會令客人覺得被忽視。"},{"en":"Hospitality is not only about facilities; it is also about how people are treated.","zh":"酒店款待服務不只是設施，也包括人們如何被對待。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"not simply as…, but more importantly as…","meaning":"不只是……更重要是……","examples":[{"en":"I see hospitality not simply as providing rooms and meals, but more importantly as earning trust.","zh":"我認為酒店款待服務不只是提供房間和膳食，更重要是贏得信任。"},{"en":"“Not simply as…, but more importantly as…” contrasts a basic view with a deeper or more important view.","zh":"“Not simply as…, but more importantly as…” 用來對比基本看法和更深層或更重要的看法。"},{"en":"I see education not simply as passing exams, but more importantly as learning how to think.","zh":"我認為教育不只是通過考試，更重要是學會思考。"},{"en":"A library is not simply a place for books, but more importantly a space where people can learn freely.","zh":"圖書館不只是放書的地方，更重要是讓人自由學習的空間。"},{"en":"This structure helps show that the second idea is the speaker’s main point.","zh":"這個句式有助顯示第二個想法才是說話者的重點。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"earn trust","meaning":"贏得信任","examples":[{"en":"Good hospitality means earning trust at every point of a guest’s journey.","zh":"良好的酒店款待服務意味着在住客旅程的每一個環節贏得信任。"},{"en":"To earn trust means to make people believe you are reliable, honest, and able to help them.","zh":"「贏得信任」指令人相信你可靠、誠實，而且有能力提供幫助。"},{"en":"A doctor earns trust by listening carefully and explaining treatment clearly.","zh":"醫生透過細心聆聽和清楚解釋治療方法來贏得信任。"},{"en":"Hotels earn trust when they keep promises, handle mistakes well, and respect guests’ needs.","zh":"酒店在守承諾、妥善處理錯誤和尊重住客需要時，便能贏得信任。"},{"en":"Trust is not automatic; staff must earn trust through repeated responsible actions.","zh":"信任不是自動得到的；員工必須透過一次又一次負責任的行動來贏得信任。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"at every point of","meaning":"在……的每一個環節","examples":[{"en":"Hotels must earn trust at every point of a guest’s journey.","zh":"酒店必須在住客旅程的每一個環節贏得信任。"},{"en":"“At every point of” means during each stage or part of a process.","zh":"“At every point of” 指在一個過程的每個階段或部分。"},{"en":"A school should support students at every point of their learning journey, from admission to graduation.","zh":"學校應在學生學習旅程的每一個環節提供支援，由入學到畢業都包括在內。"},{"en":"A customer forms opinions at every point of contact, including phone calls, emails, and face-to-face service.","zh":"顧客會在每一個接觸點形成看法，包括電話、電郵和面對面服務。"},{"en":"This phrase is useful when a process has many stages and each one matters.","zh":"當一個過程有很多階段，而且每個階段都重要時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"a guest’s journey","meaning":"住客旅程","examples":[{"en":"Trust must be earned at every point of a guest’s journey.","zh":"信任必須在住客旅程的每一個環節中贏得。"},{"en":"A guest’s journey is the whole experience a guest has, from booking and arrival to staying and leaving.","zh":"住客旅程是住客的整體體驗，由預訂和抵達，到住宿和離開都包括在內。"},{"en":"A guest’s journey begins before check-in because online information and reservations already affect expectations.","zh":"住客旅程在入住前已經開始，因為網上資料和預訂已會影響期望。"},{"en":"If one stage of a guest’s journey goes badly, the whole stay may feel disappointing.","zh":"如果住客旅程其中一個階段出錯，整個住宿體驗都可能令人失望。"},{"en":"Understanding a guest’s journey helps hotel staff notice where service can improve.","zh":"了解住客旅程可以幫助酒店員工留意服務可改善之處。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"strengthen its presence in","meaning":"加強在……的地位","examples":[{"en":"Our organisation continues to strengthen its presence in the Mainland market.","zh":"本機構繼續加強在內地市場的地位。"},{"en":"To strengthen its presence in a market means to become more visible, active, and competitive there.","zh":"「加強在某市場的地位」指在該市場變得更顯眼、更活躍和更具競爭力。"},{"en":"A restaurant chain may strengthen its presence in a new city by opening more branches.","zh":"餐飲連鎖店可能透過開設更多分店，加強在新城市的地位。"},{"en":"Companies strengthen their presence in a market when they attract more customers and build a stronger reputation.","zh":"當公司吸引更多顧客並建立更強聲譽時，就是在加強其市場地位。"},{"en":"This phrase is often used in business to describe growth in a particular area.","zh":"這個說法常用於商業語境，描述在某個地區或市場的增長。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"the Mainland market","meaning":"內地市場","examples":[{"en":"The hotel group is strengthening its presence in the Mainland market.","zh":"酒店集團正在加強其在內地市場的地位。"},{"en":"The Mainland market refers to customers, business opportunities, and competition in Mainland China.","zh":"內地市場指中國內地的顧客、商業機會和競爭環境。"},{"en":"A fashion brand may enter the Mainland market by opening stores in major cities.","zh":"時裝品牌可能透過在主要城市開設店舖進入內地市場。"},{"en":"Understanding the Mainland market requires knowledge of local consumer habits, payment methods, and service expectations.","zh":"了解內地市場需要認識本地消費習慣、付款方式和服務期望。"},{"en":"The Mainland market can offer growth opportunities, but companies must adapt carefully.","zh":"內地市場可以提供增長機會，但公司必須謹慎適應。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"Putonghua-speaking guests","meaning":"說普通話的住客","examples":[{"en":"I understand both Hong Kong service culture and Putonghua-speaking guests.","zh":"本人了解香港服務文化，也了解說普通話的住客。"},{"en":"Putonghua-speaking guests are guests who communicate mainly or partly in Putonghua.","zh":"說普通話的住客是主要或部分使用普通話溝通的住客。"},{"en":"A hotel in Shanghai needs staff who can welcome Putonghua-speaking guests clearly and politely.","zh":"上海的酒店需要能清楚而有禮地接待說普通話住客的員工。"},{"en":"Understanding Putonghua-speaking guests can reduce misunderstandings during check-in, complaints, and special requests.","zh":"了解說普通話的住客，可以減少入住登記、投訴和特別要求中的誤會。"},{"en":"Language ability is useful, but serving Putonghua-speaking guests also requires cultural awareness.","zh":"語言能力有用，但服務說普通話的住客也需要文化意識。"}],"source":"2020 Q4.pdf","sourcePage":2},{"front":"smoother operations","meaning":"更順暢的運作","examples":[{"en":"I could help the Shanghai team achieve smoother operations.","zh":"本人可以幫助上海團隊達致更順暢的運作。"},{"en":"Smoother operations are work processes that run with fewer delays, mistakes, or misunderstandings.","zh":"更順暢的運作指工作流程較少延誤、錯誤或誤會。"},{"en":"Clearer shift notes helped the front desk achieve smoother operations during busy mornings.","zh":"更清楚的交更筆記幫助前台在繁忙早上達致更順暢的運作。"},{"en":"Smoother operations can improve guest satisfaction because staff respond faster and more consistently.","zh":"更順暢的運作可以提升住客滿意度，因為員工回應更快、更一致。"},{"en":"A team often needs good communication and clear procedures to maintain smoother operations.","zh":"團隊通常需要良好溝通和清晰程序，才能保持更順暢的運作。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"stronger guest loyalty","meaning":"更高的住客忠誠度","examples":[{"en":"I could help the team build stronger guest loyalty.","zh":"本人可以幫助團隊建立更高的住客忠誠度。"},{"en":"Stronger guest loyalty means guests are more likely to return, recommend the hotel, and trust the brand.","zh":"更高的住客忠誠度指住客更可能再次入住、推薦酒店並信任品牌。"},{"en":"Remembering a guest’s room preference can help build stronger guest loyalty.","zh":"記得住客的房間偏好可以幫助建立更高的住客忠誠度。"},{"en":"Stronger guest loyalty reduces the need to find new guests because satisfied guests come back.","zh":"更高的住客忠誠度可減少尋找新住客的需要，因為滿意的住客會回來。"},{"en":"Hotels build stronger guest loyalty by offering reliable service, personal attention, and careful problem-solving.","zh":"酒店透過可靠服務、個人化關注和細心解決問題來建立更高的住客忠誠度。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"closer cooperation","meaning":"更緊密的合作","examples":[{"en":"I could help achieve closer cooperation between the two branches.","zh":"本人可以幫助兩間分店達致更緊密的合作。"},{"en":"Closer cooperation means people or teams work together more frequently, clearly, and effectively.","zh":"更緊密的合作指個人或團隊更頻密、更清楚和更有效地一起工作。"},{"en":"Closer cooperation between teachers and parents can help students solve problems earlier.","zh":"老師和家長之間更緊密的合作，可以幫助學生更早解決問題。"},{"en":"Companies achieve closer cooperation when teams share information instead of working separately.","zh":"當團隊分享資訊，而不是各自工作時，公司便能達致更緊密的合作。"},{"en":"Closer cooperation is especially important when two branches serve similar customers.","zh":"當兩間分店服務相似顧客時，更緊密的合作尤其重要。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"between the two branches","meaning":"兩間分店之間","examples":[{"en":"Closer cooperation between the two branches would benefit the organisation.","zh":"兩間分店之間更緊密的合作會對機構有利。"},{"en":"“Between the two branches” refers to the relationship or activity connecting two company locations.","zh":"「兩間分店之間」指連接兩個公司地點的關係或活動。"},{"en":"Information sharing between the two branches helped staff recognise returning guests.","zh":"兩間分店之間的資訊共享，幫助員工識別回頭住客。"},{"en":"Problems can occur between the two branches if procedures are different and communication is slow.","zh":"如果程序不同而溝通緩慢，兩間分店之間可能會出現問題。"},{"en":"When work moves between the two branches smoothly, customers receive more consistent service.","zh":"當工作能在兩間分店之間順利流動時，顧客會得到更一致的服務。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"for these reasons","meaning":"基於以上原因","examples":[{"en":"For these reasons, I respectfully ask for your support.","zh":"基於以上原因，本人恭敬地請求你的支持。"},{"en":"“For these reasons” means because of the points already explained.","zh":"「基於以上原因」表示因為前面已解釋的各項理由。"},{"en":"The course is useful, affordable, and related to my career goals; for these reasons, I hope to join it.","zh":"這個課程有用、負擔得起，而且與我的事業目標相關；基於以上原因，我希望參加。"},{"en":"This phrase helps connect earlier arguments with a request or conclusion.","zh":"這個說法有助把前面的論點與請求或結論連接起來。"},{"en":"In a formal letter, “for these reasons” can make the final request feel logical and organised.","zh":"在正式信件中，「基於以上原因」可以令最後的請求顯得合邏輯和有條理。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"respectfully ask for","meaning":"恭敬地請求","examples":[{"en":"I respectfully ask for your support in considering my application.","zh":"本人恭敬地請求你支持考慮我的申請。"},{"en":"To respectfully ask for something means to request it politely and with proper respect for the other person.","zh":"「恭敬地請求」指以有禮並尊重對方的方式提出請求。"},{"en":"I respectfully ask for your advice on how to improve my proposal.","zh":"本人恭敬地請求你就如何改善我的建議書給予意見。"},{"en":"This phrase is useful when the reader has authority to approve, reject, or guide a request.","zh":"當讀者有權批准、拒絕或指導一項請求時，這個說法很有用。"},{"en":"A respectful request should sound polite without becoming unclear about what is being asked.","zh":"有禮的請求應該保持客氣，同時清楚說明所請求的事情。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"your support in considering","meaning":"支持考慮……","examples":[{"en":"I ask for your support in considering my application.","zh":"本人請求你支持考慮我的申請。"},{"en":"“Your support in considering” means the reader’s help, approval, or positive attention when reviewing a request.","zh":"“Your support in considering” 指讀者在審視請求時給予幫助、認可或正面關注。"},{"en":"I would appreciate your support in considering my proposal for staff training.","zh":"如你能支持考慮本人關於職員培訓的建議，本人將不勝感激。"},{"en":"Asking for someone’s support in considering an application is polite because it does not demand an immediate approval.","zh":"請求別人支持考慮申請是有禮的，因為它沒有要求對方立即批准。"},{"en":"The phrase is suitable when you want the person to give serious and fair attention to your request.","zh":"當你希望對方認真而公平地看待你的請求時，這個說法很合適。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"in terms of","meaning":"就……而言","examples":[{"en":"In terms of work experience, I have been involved in front-office operations.","zh":"就工作經驗而言，本人曾參與前堂運作。"},{"en":"“In terms of” means regarding or when considering a particular aspect of something.","zh":"“In terms of” 指就某一方面而言，或從某個角度考慮。"},{"en":"In terms of transport, the new flat is convenient because it is near a station.","zh":"就交通而言，這個新單位很方便，因為它靠近車站。"},{"en":"In terms of cost, eating at home is usually cheaper than eating out.","zh":"就成本而言，在家吃飯通常比外出用餐便宜。"},{"en":"This phrase helps organise writing by focusing on one topic at a time.","zh":"這個說法可以幫助文章按不同方面逐一組織內容。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"work experience","meaning":"工作經驗","examples":[{"en":"My work experience covers many areas of front-office operations.","zh":"本人的工作經驗涵蓋前堂運作的多個範疇。"},{"en":"Work experience is the knowledge and skills someone gains from doing jobs or workplace tasks.","zh":"工作經驗是人透過工作或職場任務所得的知識和技能。"},{"en":"Part-time work in a shop gave me useful work experience in customer service.","zh":"在商店兼職給了我有用的客戶服務工作經驗。"},{"en":"Work experience can make an application stronger because it shows what the applicant has already handled.","zh":"工作經驗可以令申請更有說服力，因為它顯示申請人已處理過哪些事情。"},{"en":"Good work experience is not only about time served, but also about what was learned.","zh":"良好的工作經驗不只是服務時間長短，也包括從中學到甚麼。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"be involved in","meaning":"參與","examples":[{"en":"I have been involved in many areas of front-office operations.","zh":"本人曾參與前堂運作的多個範疇。"},{"en":"To be involved in something means to take part in it or have a role in it.","zh":"「參與」某事指加入其中，或在當中擔任某個角色。"},{"en":"She was involved in planning the school charity fair.","zh":"她參與籌備學校慈善賣物會。"},{"en":"Staff who are involved in daily operations understand problems that outsiders may not see.","zh":"參與日常運作的員工會了解外人未必看見的問題。"},{"en":"Being involved in different tasks can help employees develop broader skills.","zh":"參與不同任務可以幫助員工培養更廣泛的技能。"}],"source":"2020 Q4.pdf","sourcePage":3},{"front":"many areas of","meaning":"多個範疇的……","examples":[{"en":"I have been involved in many areas of front-office operations.","zh":"本人曾參與多個範疇的前堂運作。"},{"en":"“Many areas of” means several different parts or aspects of a larger field.","zh":"“Many areas of” 指一個較大領域中的幾個不同部分或方面。"},{"en":"A school principal deals with many areas of school life, including teaching, discipline, and parent communication.","zh":"校長要處理學校生活的多個範疇，包括教學、紀律和家長溝通。"},{"en":"Working in many areas of a business can help someone understand how the whole organisation works.","zh":"參與企業多個範疇的工作，可以幫助人了解整個機構如何運作。"},{"en":"This phrase shows that the experience is broad, not limited to one small task.","zh":"這個說法顯示經驗廣泛，而不是只限於一項小任務。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"front-office operations","meaning":"前堂運作","examples":[{"en":"I have been involved in many areas of front-office operations.","zh":"本人曾參與前堂運作的多個範疇。"},{"en":"Front-office operations are the hotel tasks that deal directly with guests, such as reception, check-in, and enquiries.","zh":"前堂運作是酒店中直接面對住客的工作，例如接待、入住登記和查詢。"},{"en":"Front-office operations include answering calls, arranging rooms, and handling guest requests.","zh":"前堂運作包括接聽電話、安排房間和處理住客要求。"},{"en":"When front-office operations run smoothly, guests often feel welcomed and well informed.","zh":"當前堂運作順暢時，住客通常會感到受歡迎並得到清楚資訊。"},{"en":"Front-office operations are important because they shape the first and last impressions of a hotel.","zh":"前堂運作很重要，因為它塑造住客對酒店的第一和最後印象。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"from…to…","meaning":"由……到……","examples":[{"en":"From check-in procedures to post-stay follow-up, small details shape a guest’s impression.","zh":"由入住登記程序到退房後跟進，小細節都會塑造住客對酒店的印象。"},{"en":"“From…to…” shows a range that includes the first thing, the last thing, and often the stages between them.","zh":"“From…to…” 顯示一個範圍，包括第一項、最後一項，通常也包括中間階段。"},{"en":"From booking tickets to finding seats, every step affects a visitor’s experience.","zh":"由訂票到找座位，每一步都影響訪客體驗。"},{"en":"A teacher supports students from the first lesson to the final examination.","zh":"老師由第一堂課到最後考試都支持學生。"},{"en":"This structure is useful for showing that many different stages are included.","zh":"這個結構適合用來顯示很多不同階段都包括在內。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"check-in procedures","meaning":"入住登記程序","examples":[{"en":"I have experience in check-in procedures and room allocation.","zh":"本人有入住登記程序和房間分配方面的經驗。"},{"en":"Check-in procedures are the steps guests complete when they arrive at a hotel and officially begin their stay.","zh":"入住登記程序是住客到達酒店並正式開始住宿時需要完成的步驟。"},{"en":"Check-in procedures may include confirming identity, checking the booking, and giving the room key.","zh":"入住登記程序可能包括確認身份、核對預訂和交出房卡。"},{"en":"Clear check-in procedures reduce waiting time and help guests feel that the hotel is organised.","zh":"清晰的入住登記程序可以減少等候時間，並令住客覺得酒店有條理。"},{"en":"If check-in procedures are confusing, guests may feel frustrated before they even reach their room.","zh":"如果入住登記程序混亂，住客甚至未到房間前已可能感到不滿。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"room allocation","meaning":"房間分配","examples":[{"en":"Room allocation is an important part of front-office operations.","zh":"房間分配是前堂運作的重要部分。"},{"en":"Room allocation means assigning available rooms to guests according to bookings, needs, and hotel conditions.","zh":"房間分配指按照預訂、需要和酒店情況，把可用房間安排給住客。"},{"en":"Staff must consider family size, room type, and special requests during room allocation.","zh":"員工在房間分配時必須考慮家庭人數、房間類型和特別要求。"},{"en":"Poor room allocation can cause complaints if guests receive rooms that do not match their bookings.","zh":"如果住客收到與預訂不符的房間，差劣的房間分配可能引起投訴。"},{"en":"Careful room allocation helps guests feel that their needs have been understood.","zh":"細心的房間分配可以令住客覺得自己的需要被理解。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"complaint handling","meaning":"投訴處理","examples":[{"en":"I have learnt a great deal from complaint handling.","zh":"本人從投訴處理中學到了很多。"},{"en":"Complaint handling is the process of listening to, investigating, and responding to a customer’s dissatisfaction.","zh":"投訴處理是聆聽、調查並回應顧客不滿的過程。"},{"en":"Complaint handling in a hotel may involve apologising, checking records, and offering a practical solution.","zh":"酒店的投訴處理可能包括道歉、查核記錄和提供實際解決方法。"},{"en":"Good complaint handling can turn an angry guest into someone who still trusts the hotel.","zh":"良好的投訴處理可以把憤怒的住客轉化為仍然信任酒店的人。"},{"en":"Poor complaint handling often makes the original problem feel even worse.","zh":"差劣的投訴處理往往會令原本的問題感覺更嚴重。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"post-stay follow-up","meaning":"退房後跟進","examples":[{"en":"Post-stay follow-up can help improve guest loyalty.","zh":"退房後跟進可以幫助提升住客忠誠度。"},{"en":"Post-stay follow-up is communication with guests after they have checked out, usually to thank them or respond to feedback.","zh":"退房後跟進是住客退房後與他們的溝通，通常用來致謝或回應意見。"},{"en":"A hotel may send a short survey as part of post-stay follow-up.","zh":"酒店可能會寄出簡短問卷，作為退房後跟進的一部分。"},{"en":"Effective post-stay follow-up can show guests that their opinions still matter after they leave.","zh":"有效的退房後跟進可以向住客顯示，即使離開後，他們的意見仍然重要。"},{"en":"Without post-stay follow-up, hotels may miss useful information about service problems.","zh":"如果沒有退房後跟進，酒店可能錯過有關服務問題的有用資訊。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"small details shape","meaning":"小細節塑造……","examples":[{"en":"Small details shape a guest’s impression of the hotel.","zh":"小細節塑造住客對酒店的印象。"},{"en":"“Small details shape” means little actions or features strongly influence how someone thinks or feels.","zh":"「小細節塑造……」指細小行動或特徵會強烈影響某人的想法或感受。"},{"en":"Clean signs and friendly greetings can shape a visitor’s impression of a school.","zh":"清楚的指示牌和友善問候可以塑造訪客對學校的印象。"},{"en":"Small details shape customer trust because they show whether a company cares about quality.","zh":"小細節會塑造顧客信任，因為它們顯示公司是否重視質素。"},{"en":"This phrase reminds us that ordinary details can have a large effect.","zh":"這個說法提醒我們，普通細節也可以有很大影響。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"a guest’s impression of","meaning":"住客對……的印象","examples":[{"en":"Small details shape a guest’s impression of the hotel.","zh":"小細節塑造住客對酒店的印象。"},{"en":"A guest’s impression of a place is the opinion or feeling the guest forms about it.","zh":"住客對某地方的印象，是住客對它形成的看法或感受。"},{"en":"A slow check-in process may damage a guest’s impression of the hotel before the stay begins.","zh":"緩慢的入住登記程序可能在住宿開始前已損害住客對酒店的印象。"},{"en":"A warm welcome can improve a guest’s impression of the staff and the brand.","zh":"熱情接待可以改善住客對員工和品牌的印象。"},{"en":"A guest’s impression of a hotel is shaped by both large services and small details.","zh":"住客對酒店的印象由大型服務和細小細節共同塑造。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"during Golden Week","meaning":"在黃金周期間","examples":[{"en":"During Golden Week last year, a group of business delegates arrived early.","zh":"去年黃金周期間，一組商務代表團提早抵達。"},{"en":"During Golden Week means in the holiday period when many people travel and hotels may become especially busy.","zh":"「在黃金周期間」指在許多人出行、酒店可能特別繁忙的假期時段。"},{"en":"During Golden Week, train stations and hotels often handle many more travellers than usual.","zh":"在黃金周期間，火車站和酒店通常要接待比平日多得多的旅客。"},{"en":"Hotels need extra planning during Golden Week because early arrivals and full bookings are common.","zh":"酒店在黃金周期間需要額外規劃，因為提早抵達和訂房爆滿很常見。"},{"en":"Mentioning Golden Week helps explain why the situation was busy and difficult to manage.","zh":"提到黃金周有助解釋為何情況繁忙且難以處理。"}],"source":"2020 Q4.pdf","sourcePage":4},{"front":"business delegates","meaning":"商務代表團成員","examples":[{"en":"A group of 120 business delegates arrived two hours earlier than scheduled.","zh":"一組一百二十人的商務代表團成員比原定時間早兩小時抵達。"},{"en":"Business delegates are people who attend meetings, conferences, or events on behalf of a company or organisation.","zh":"商務代表團成員是代表公司或機構出席會議、研討會或活動的人。"},{"en":"The hotel prepared meeting rooms and transport for the business delegates.","zh":"酒店為商務代表團成員準備會議室和交通安排。"},{"en":"Business delegates often need efficient service because they may have tight meeting schedules.","zh":"商務代表團成員通常需要高效率服務，因為他們的會議時間表可能很緊密。"},{"en":"When many business delegates arrive together, hotel staff must coordinate check-in carefully.","zh":"當大量商務代表團成員同時抵達時，酒店員工必須仔細協調入住安排。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"earlier than scheduled","meaning":"比原定時間早","examples":[{"en":"The delegates arrived two hours earlier than scheduled.","zh":"代表團成員比原定時間早兩小時抵達。"},{"en":"“Earlier than scheduled” means before the time that had been planned or arranged.","zh":"“Earlier than scheduled” 指早於原本計劃或安排的時間。"},{"en":"The train arrived earlier than scheduled, so passengers had more time to transfer.","zh":"火車比原定時間早到，所以乘客有更多時間轉車。"},{"en":"When guests arrive earlier than scheduled, rooms may not yet be ready.","zh":"當住客比原定時間早到，房間可能尚未準備好。"},{"en":"This phrase is useful when the actual time is different from the planned time.","zh":"當實際時間與計劃時間不同時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"still being inspected","meaning":"仍在檢查中","examples":[{"en":"Several rooms were still being inspected.","zh":"有幾間房仍在檢查中。"},{"en":"“Still being inspected” means someone was continuing to check something, so it was not yet ready or approved.","zh":"“Still being inspected” 表示某物仍然有人在檢查，因此尚未準備好或獲批准使用。"},{"en":"The lifts were still being inspected, so guests had to use another route.","zh":"升降機仍在檢查中，所以住客需要使用另一條路線。"},{"en":"Rooms may still be inspected after cleaning to make sure they meet hotel standards.","zh":"房間清潔後可能仍需檢查，以確保符合酒店標準。"},{"en":"If something is still being inspected, staff should not promise that it is already available.","zh":"如果某物仍在檢查中，員工不應承諾它已經可以使用。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"instead of","meaning":"而不是","examples":[{"en":"Instead of leaving them waiting, I coordinated with Housekeeping.","zh":"我與房務部協調，而不是讓他們等候。"},{"en":"“Instead of” introduces the action not chosen and contrasts it with another action.","zh":"“Instead of” 用來引出沒有選擇的行動，並把它與另一個行動作對比。"},{"en":"Instead of complaining online, I spoke politely to the manager.","zh":"我沒有在網上抱怨，而是有禮地與經理交談。"},{"en":"The team solved the problem instead of blaming one another.","zh":"團隊解決了問題，而不是互相責怪。"},{"en":"“Instead of” is useful when showing a better choice than the obvious or easy one.","zh":"當要顯示比明顯或容易選擇更好的做法時，“instead of” 很有用。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"leave someone waiting","meaning":"讓某人等候","examples":[{"en":"I avoided leaving the guests waiting in the lobby.","zh":"我避免讓住客在大堂等候。"},{"en":"To leave someone waiting means to make someone stay without service, information, or action for a period of time.","zh":"「讓某人等候」指令某人在一段時間內沒有得到服務、資訊或行動。"},{"en":"The clinic should not leave elderly patients waiting without explaining the delay.","zh":"診所不應讓長者病人等候而不解釋延誤原因。"},{"en":"Leaving guests waiting can make them feel ignored and increase their frustration.","zh":"讓住客等候可能令他們覺得被忽視，並增加不滿。"},{"en":"If a delay is unavoidable, giving updates is better than leaving someone waiting silently.","zh":"如果延誤無法避免，提供最新消息比沉默地讓某人等候更好。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"in the lobby","meaning":"在酒店大堂","examples":[{"en":"The guests were waiting in the lobby.","zh":"住客正在酒店大堂等候。"},{"en":"In the lobby means in the public entrance area of a hotel, office, or large building.","zh":"「在大堂」指在酒店、辦公室或大型建築物的公共入口區域。"},{"en":"Please meet the tour guide in the lobby at nine o’clock.","zh":"請於九時在大堂與導遊會合。"},{"en":"Guests often wait in the lobby before check-in, after check-out, or while transport is being arranged.","zh":"住客常在入住前、退房後或等候交通安排時留在大堂。"},{"en":"A comfortable lobby can make waiting feel less stressful.","zh":"舒適的大堂可以令等候感覺沒那麼有壓力。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"coordinate with","meaning":"與……協調","examples":[{"en":"I coordinated with Housekeeping to prepare the rooms.","zh":"我與房務部協調，以準備房間。"},{"en":"To coordinate with another person or team means to organise actions together so the work fits smoothly.","zh":"「與……協調」指與另一個人或團隊一起安排工作，使行動順利配合。"},{"en":"The teacher coordinated with parents to arrange the school trip.","zh":"老師與家長協調，安排學校旅行。"},{"en":"Hotel staff must coordinate with different departments when guests arrive early or special requests appear.","zh":"當住客提早抵達或有特別要求時，酒店員工必須與不同部門協調。"},{"en":"Good coordination prevents duplicated work, delays, and confusion.","zh":"良好協調可以避免重複工作、延誤和混亂。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"Housekeeping","meaning":"房務部","examples":[{"en":"I coordinated with Housekeeping during the early arrival.","zh":"住客提早抵達期間，我與房務部協調。"},{"en":"Housekeeping is the hotel department responsible for cleaning rooms, checking supplies, and keeping guest areas ready.","zh":"房務部是酒店中負責清潔房間、檢查用品和保持住客區域準備妥當的部門。"},{"en":"Housekeeping prepared extra towels after the family requested them.","zh":"那個家庭要求額外毛巾後，房務部為他們準備了。"},{"en":"Front desk staff often work with Housekeeping to know whether rooms are ready for guests.","zh":"前台員工常與房務部合作，以了解房間是否已準備好給住客入住。"},{"en":"Without efficient Housekeeping, even a well-designed hotel can disappoint guests.","zh":"如果房務部效率低，即使酒店設計良好，也可能令住客失望。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"temporary luggage storage","meaning":"臨時行李寄存","examples":[{"en":"I arranged temporary luggage storage for the guests.","zh":"我為住客安排臨時行李寄存。"},{"en":"Temporary luggage storage is a short-term service that keeps guests’ bags safely before they can take them to their rooms or transport.","zh":"臨時行李寄存是一項短期服務，在住客能把行李帶到房間或交通工具前，安全保管他們的行李。"},{"en":"The hotel offered temporary luggage storage because the family arrived before check-in time.","zh":"因為那個家庭在入住時間前抵達，酒店提供了臨時行李寄存。"},{"en":"Temporary luggage storage allows guests to attend meetings or explore the city without carrying heavy bags.","zh":"臨時行李寄存讓住客不用拿着沉重行李，也可以出席會議或遊覽城市。"},{"en":"This service is useful when rooms are not ready but guests need to move around comfortably.","zh":"當房間尚未準備好，但住客需要舒適地活動時，這項服務很有用。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"prepare refreshments","meaning":"準備茶點","examples":[{"en":"I prepared refreshments in the lounge for the delegates.","zh":"我在休息室為代表團成員準備茶點。"},{"en":"To prepare refreshments means to arrange light food or drinks for people during a wait, meeting, or event.","zh":"「準備茶點」指在等候、會議或活動期間安排簡單食物或飲品。"},{"en":"The school prepared refreshments for parents after the graduation ceremony.","zh":"畢業典禮後，學校為家長準備茶點。"},{"en":"Preparing refreshments can make guests feel cared for while they wait.","zh":"準備茶點可以令住客在等候時感到被照顧。"},{"en":"Refreshments do not solve every problem, but they can reduce discomfort during a delay.","zh":"茶點不能解決所有問題，但可以在延誤期間減少不適感。"}],"source":"2020 Q4.pdf","sourcePage":5},{"front":"in the lounge","meaning":"在休息室","examples":[{"en":"The delegates waited in the lounge with refreshments.","zh":"代表團成員在休息室享用茶點並等候。"},{"en":"In the lounge means in a comfortable waiting or resting area, often found in hotels, airports, or offices.","zh":"「在休息室」指在舒適的等候或休息區，通常可見於酒店、機場或辦公室。"},{"en":"The family waited in the lounge while staff prepared their room.","zh":"員工準備房間時，那個家庭在休息室等候。"},{"en":"Guests may prefer waiting in the lounge rather than standing in a crowded lobby.","zh":"住客可能較喜歡在休息室等候，而不是站在擠迫的大堂。"},{"en":"A quiet lounge can help business travellers continue working during a delay.","zh":"安靜的休息室可以幫助商務旅客在延誤期間繼續工作。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"the revised schedule","meaning":"修改後的時間表","examples":[{"en":"I explained the revised schedule in English and Putonghua.","zh":"我用英語和普通話解釋修改後的時間表。"},{"en":"The revised schedule is the updated timetable after changes have been made.","zh":"修改後的時間表是作出變更後更新了的安排表。"},{"en":"After the flight delay, the tour guide sent everyone the revised schedule.","zh":"航班延誤後，導遊把修改後的時間表傳給所有人。"},{"en":"Explaining the revised schedule clearly prevents confusion when original plans have changed.","zh":"清楚解釋修改後的時間表，可以在原有計劃改變時避免混亂。"},{"en":"A revised schedule should show what has changed, when it will happen, and what people should do next.","zh":"修改後的時間表應顯示改了甚麼、何時發生，以及人們下一步應做甚麼。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time the rooms were ready, the situation had improved.","zh":"到房間準備好的時候，情況已經改善。"},{"en":"“By the time” means at or before the moment when something happened.","zh":"“By the time” 指在某件事發生的時候或之前。"},{"en":"By the time I arrived at school, the rain had already stopped.","zh":"到我抵達學校的時候，雨已經停了。"},{"en":"By the time the manager came out, the staff had already solved the problem.","zh":"到經理出來的時候，員工已經解決了問題。"},{"en":"This phrase often links a later moment with something that had already happened before it.","zh":"這個說法常把一個較後的時刻與在那之前已發生的事連接起來。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"what could have become","meaning":"原本可能變成……的事","examples":[{"en":"What could have become a serious complaint turned into written compliments.","zh":"原本可能變成嚴重投訴的事情，變成了書面讚揚。"},{"en":"“What could have become” describes a possible negative result that might have happened but did not.","zh":"“What could have become” 描述一個原本可能發生、但最終沒有發生的負面結果。"},{"en":"What could have become a long argument ended as a calm discussion.","zh":"原本可能變成長時間爭吵的事情，最後成為一次冷靜討論。"},{"en":"Quick action can prevent what could have become a service failure from damaging customer trust.","zh":"迅速行動可以防止原本可能變成服務失誤的事情損害顧客信任。"},{"en":"This phrase shows the risk that existed before someone managed the situation well.","zh":"這個說法顯示在有人妥善處理前，當時存在的風險。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"a serious complaint","meaning":"嚴重投訴","examples":[{"en":"The delay could have become a serious complaint.","zh":"那次延誤原本可能變成嚴重投訴。"},{"en":"A serious complaint is a strong formal expression of dissatisfaction about an important problem.","zh":"嚴重投訴是針對重要問題而提出的強烈正式不滿。"},{"en":"A guest may make a serious complaint if a promised room is unavailable and no explanation is given.","zh":"如果承諾的房間無法提供，而且沒有任何解釋，住客可能會作出嚴重投訴。"},{"en":"Serious complaints can damage a hotel’s reputation if staff ignore them or respond carelessly.","zh":"如果員工忽視嚴重投訴或草率回應，酒店聲譽可能受損。"},{"en":"Handling a problem early can stop a small inconvenience from becoming a serious complaint.","zh":"及早處理問題可以防止小小的不便變成嚴重投訴。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"turn into","meaning":"變成","examples":[{"en":"The problem turned into several written compliments.","zh":"那個問題變成了幾封書面讚揚。"},{"en":"To turn into something means to change and become that thing.","zh":"“Turn into” 指改變並成為另一種事物或狀態。"},{"en":"A small misunderstanding turned into a serious argument because no one explained clearly.","zh":"一個小誤會因沒有人清楚解釋而變成嚴重爭吵。"},{"en":"With careful service, a difficult guest experience can turn into a positive memory.","zh":"透過細心服務，艱難的住客經歷可以變成正面回憶。"},{"en":"“Turn into” is useful for showing how a situation changes from one state to another.","zh":"“Turn into” 適合用來顯示情況如何由一種狀態變成另一種。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"written compliments","meaning":"書面讚揚","examples":[{"en":"The hotel received several written compliments after the incident.","zh":"事件後，酒店收到幾封書面讚揚。"},{"en":"Written compliments are positive comments recorded in writing, such as emails, letters, or feedback forms.","zh":"書面讚揚是以文字記錄下來的正面評語，例如電郵、信件或意見表。"},{"en":"A guest sent written compliments after the front desk helped recover her lost passport.","zh":"前台協助一位住客找回遺失的護照後，她寄來書面讚揚。"},{"en":"Written compliments are valuable because managers can keep them as evidence of good service.","zh":"書面讚揚很有價值，因為經理可以把它們保留下來，作為優良服務的證明。"},{"en":"Staff often feel encouraged when guests take time to give written compliments.","zh":"當住客花時間給予書面讚揚，員工通常會受到鼓舞。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"not to mention","meaning":"更不用說","examples":[{"en":"This experience made me a better communicator, not to mention a calmer decision-maker.","zh":"這次經驗令我成為更好的溝通者，更不用說也令我成為更沉着的決策者。"},{"en":"“Not to mention” adds another point that is also important and often even more impressive.","zh":"“Not to mention” 用來加入另一個同樣重要、甚至更有力的點。"},{"en":"The new system saves time, not to mention reducing mistakes.","zh":"新系統節省時間，更不用說也減少錯誤。"},{"en":"Learning another language improves communication, not to mention creating more career opportunities.","zh":"學習另一種語言可以改善溝通，更不用說還能創造更多事業機會。"},{"en":"This phrase is useful when you want to add an extra benefit after the main point.","zh":"當你想在主要重點後加入額外好處時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"a calmer decision-maker","meaning":"更沉着的決策者","examples":[{"en":"The experience made me a calmer decision-maker under pressure.","zh":"這次經驗令我在壓力下成為更沉着的決策者。"},{"en":"A calmer decision-maker is someone who can make choices thoughtfully even in stressful situations.","zh":"更沉着的決策者是即使在有壓力的情況下，也能仔細作出選擇的人。"},{"en":"After handling several emergencies, the team leader became a calmer decision-maker.","zh":"處理過幾次緊急情況後，組長成為更沉着的決策者。"},{"en":"A calmer decision-maker can prevent panic from spreading through the whole team.","zh":"更沉着的決策者可以防止恐慌在整個團隊中蔓延。"},{"en":"Good training helps staff become calmer decision-makers when customers are upset.","zh":"良好培訓可以幫助員工在顧客不滿時成為更沉着的決策者。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"under pressure","meaning":"在壓力下","examples":[{"en":"I became a calmer decision-maker under pressure.","zh":"我在壓力下成為更沉着的決策者。"},{"en":"Under pressure means in a stressful situation where there is urgency, responsibility, or difficulty.","zh":"「在壓力下」指處於緊急、有責任或困難的 stressful 情況中。"},{"en":"Nurses often have to stay focused under pressure during emergencies.","zh":"護士在緊急情況下常要在壓力下保持專注。"},{"en":"People may make careless mistakes under pressure if they do not have clear procedures.","zh":"如果沒有清晰程序，人們在壓力下可能會犯粗心錯誤。"},{"en":"Staying calm under pressure is important in service work because guests notice staff reactions quickly.","zh":"在壓力下保持冷靜對服務工作很重要，因為住客很快會注意到員工反應。"}],"source":"2020 Q4.pdf","sourcePage":6},{"front":"train junior colleagues on","meaning":"培訓初級同事使用……","examples":[{"en":"I trained six junior colleagues on service recovery scripts.","zh":"我培訓六位初級同事使用服務補救話術。"},{"en":"To train junior colleagues on something means to teach less experienced staff how to use or do it.","zh":"「培訓初級同事使用……」指教導經驗較少的員工如何使用或處理某事。"},{"en":"The supervisor trained junior colleagues on how to handle online bookings.","zh":"主管培訓初級同事處理網上預訂。"},{"en":"Training junior colleagues on standard procedures helps the whole team respond more consistently.","zh":"培訓初級同事使用標準程序，可以幫助整個團隊更一致地回應。"},{"en":"This phrase is useful when describing leadership or mentoring experience at work.","zh":"這個說法適合用來描述工作中的領導或指導經驗。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"junior colleagues","meaning":"初級同事","examples":[{"en":"I trained six junior colleagues on service recovery procedures.","zh":"我培訓六位初級同事使用服務補救程序。"},{"en":"Junior colleagues are less experienced or lower-ranking coworkers in the same workplace.","zh":"初級同事是在同一工作場所中經驗較少或職級較低的同事。"},{"en":"Junior colleagues may ask senior staff for advice when facing difficult guests.","zh":"初級同事面對難處理的住客時，可能會向資深員工請教。"},{"en":"Supporting junior colleagues helps a team grow because knowledge is shared instead of staying with one person.","zh":"支援初級同事可以幫助團隊成長，因為知識會被分享，而不是只留在一個人身上。"},{"en":"A good senior employee corrects junior colleagues without embarrassing them.","zh":"好的資深員工會糾正初級同事，但不會令他們難堪。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"service recovery scripts","meaning":"服務補救話術","examples":[{"en":"I trained junior colleagues on service recovery scripts.","zh":"我培訓初級同事使用服務補救話術。"},{"en":"Service recovery scripts are prepared phrases that help staff respond politely and consistently after a service problem.","zh":"服務補救話術是預先準備好的句子，幫助員工在服務出現問題後有禮而一致地回應。"},{"en":"A service recovery script may begin with an apology and then offer a clear next step.","zh":"服務補救話術可能先以道歉開始，然後提供清楚的下一步。"},{"en":"Service recovery scripts help new staff avoid sounding careless when guests are upset.","zh":"服務補救話術幫助新員工在住客不滿時避免聽起來草率。"},{"en":"Scripts are useful, but staff must still listen carefully and adapt to the guest’s real concern.","zh":"話術很有用，但員工仍必須細心聆聽，並根據住客真正的關注作調整。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"guest-preference log","meaning":"住客偏好記錄","examples":[{"en":"The guest-preference log helps staff respond more consistently.","zh":"住客偏好記錄幫助員工更一致地回應。"},{"en":"A guest-preference log is a record of guests’ likes, needs, and special requests for future service.","zh":"住客偏好記錄是記下住客喜好、需要和特別要求的資料，以便日後提供服務。"},{"en":"The guest-preference log may note that a guest prefers a quiet room or extra pillows.","zh":"住客偏好記錄可能會注明某位住客喜歡安靜房間或額外枕頭。"},{"en":"A guest-preference log helps staff personalise service without asking the same questions every time.","zh":"住客偏好記錄幫助員工提供個人化服務，而不用每次都問同樣問題。"},{"en":"Keeping the guest-preference log accurate is important because wrong information can create new problems.","zh":"保持住客偏好記錄準確很重要，因為錯誤資料可能造成新問題。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"thereby helping","meaning":"從而幫助","examples":[{"en":"I trained colleagues, thereby helping the team respond more consistently.","zh":"我培訓同事，從而幫助團隊更一致地回應。"},{"en":"“Thereby helping” means helping as a result of the action just mentioned.","zh":"“Thereby helping” 指由於剛提到的行動而帶來幫助。"},{"en":"The school added clearer signs, thereby helping visitors find classrooms more easily.","zh":"學校加設更清楚的指示牌，從而幫助訪客更容易找到課室。"},{"en":"The hotel updated its guest records, thereby helping staff avoid repeated mistakes.","zh":"酒店更新住客記錄，從而幫助員工避免重複犯錯。"},{"en":"This phrase is formal and useful when linking an action to its positive result.","zh":"這個說法較正式，適合用來把行動與正面結果連接起來。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"respond more consistently","meaning":"更一致地回應","examples":[{"en":"The training helped the team respond more consistently when difficulties arose.","zh":"培訓幫助團隊在困難出現時更一致地回應。"},{"en":"To respond more consistently means to answer or act in a steadier and more similar way each time.","zh":"「更一致地回應」指每次回答或行動都更穩定、更相近。"},{"en":"Clear guidelines helped teachers respond more consistently to late homework.","zh":"清楚的指引幫助老師更一致地處理遲交功課。"},{"en":"Teams respond more consistently when everyone understands the same procedure.","zh":"當每個人都明白同一套程序時，團隊會更一致地回應。"},{"en":"Consistent responses are important because customers feel confused if every staff member says something different.","zh":"一致回應很重要，因為如果每位員工說法不同，顧客會感到困惑。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"when difficulties arise","meaning":"當困難出現時","examples":[{"en":"The team must respond consistently when difficulties arise.","zh":"當困難出現時，團隊必須一致地回應。"},{"en":"“When difficulties arise” means when problems, obstacles, or challenging situations appear.","zh":"“When difficulties arise” 指當問題、障礙或具挑戰性的情況出現時。"},{"en":"When difficulties arise during a group project, members should discuss them early.","zh":"當小組項目出現困難時，成員應及早討論。"},{"en":"Staff need clear procedures when difficulties arise so they do not panic or give mixed answers.","zh":"當困難出現時，員工需要清晰程序，才不會驚慌或給出不同答案。"},{"en":"This phrase is often used in formal writing to describe how people should act during problems.","zh":"這個說法常用於正式寫作，描述人在問題出現時應如何行動。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"my wish to transfer","meaning":"我的調職意願","examples":[{"en":"My wish to transfer comes from a sincere desire to grow with the company.","zh":"我的調職意願來自與公司一同成長的真誠希望。"},{"en":"My wish to transfer means my personal hope or intention to move to another branch or position.","zh":"「我的調職意願」指我希望或打算轉到另一間分店或另一個職位。"},{"en":"My wish to transfer began after I learned more about the company’s regional development.","zh":"在更了解公司的區域發展後，我開始有調職意願。"},{"en":"Explaining my wish to transfer helps the manager understand that the request is thoughtful, not sudden.","zh":"解釋我的調職意願可以幫助經理明白，這個請求是經過思考的，不是一時衝動。"},{"en":"A strong application should connect my wish to transfer with both personal growth and company needs.","zh":"有力的申請應把我的調職意願與個人成長和公司需要連繫起來。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"be based on","meaning":"基於","examples":[{"en":"My wish to transfer is not based on impatience with my current post.","zh":"我的調職意願並非基於對現任職位感到不耐煩。"},{"en":"If something is based on a reason, that reason is the foundation or cause behind it.","zh":"如果某事基於某個原因，該原因就是它背後的基礎或成因。"},{"en":"The decision was based on student safety, not convenience.","zh":"這個決定是基於學生安全，而不是方便。"},{"en":"A strong argument should be based on evidence rather than guesses.","zh":"有力的論點應基於證據，而不是猜測。"},{"en":"Saying what a request is based on helps readers understand the true reason behind it.","zh":"說明請求基於甚麼，可以幫助讀者理解背後真正原因。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"impatience with","meaning":"對……感到不耐煩","examples":[{"en":"My wish to transfer is not based on impatience with my current post.","zh":"我的調職意願並非基於對現任職位感到不耐煩。"},{"en":"Impatience with something means feeling annoyed or unwilling to continue waiting for or dealing with it.","zh":"「對……感到不耐煩」指因要繼續等待或處理某事而感到煩躁或不願意。"},{"en":"His impatience with slow service made him speak too sharply to the waiter.","zh":"他對緩慢服務感到不耐煩，所以對侍應說話太尖銳。"},{"en":"Impatience with routine work can lead to careless mistakes if a person stops paying attention.","zh":"對例行工作感到不耐煩，可能會令人不再專心，從而犯粗心錯誤。"},{"en":"In a transfer request, it is wise to show that the move is not caused by impatience with the current job.","zh":"在調職申請中，最好顯示這次調動不是因為對現職不耐煩。"}],"source":"2020 Q4.pdf","sourcePage":7},{"front":"current post","meaning":"現任職位","examples":[{"en":"I am not impatient with my current post.","zh":"我並非對現任職位感到不耐煩。"},{"en":"A current post is the job or position someone holds at present.","zh":"現任職位是某人目前擔任的工作或崗位。"},{"en":"Her current post is assistant manager, but she hopes to lead a larger team one day.","zh":"她的現任職位是助理經理，但她希望有一天能帶領更大的團隊。"},{"en":"Understanding your current post well can prepare you for a future promotion or transfer.","zh":"充分了解現任職位可以為日後升職或調職作準備。"},{"en":"When applying for a transfer, you should avoid sounding disrespectful towards your current post.","zh":"申請調職時，應避免表現得不尊重現任職位。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"rather","meaning":"而是","examples":[{"en":"Rather, my wish comes from a sincere desire to grow with the company.","zh":"而是，我的意願來自與公司一同成長的真誠希望。"},{"en":"“Rather” introduces the real explanation after rejecting or correcting another idea.","zh":"“Rather” 在否定或修正一個想法後，引出真正的解釋。"},{"en":"I am not leaving because I dislike the team; rather, I want to take on new responsibilities.","zh":"我不是因為不喜歡團隊而離開；而是想承擔新的責任。"},{"en":"The delay was not caused by laziness; rather, the system had stopped working.","zh":"延誤不是因為懶惰；而是系統停止運作。"},{"en":"This word helps make a contrast between a wrong reason and the true reason.","zh":"這個詞有助對比錯誤原因和真正原因。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"a sincere desire to","meaning":"真誠希望","examples":[{"en":"My wish comes from a sincere desire to grow with the company.","zh":"我的意願來自真誠希望與公司一同成長。"},{"en":"A sincere desire to do something is an honest and genuine wish to achieve it.","zh":"「真誠希望」指誠實而真切地想做到某事。"},{"en":"She showed a sincere desire to help younger students, not just to improve her record.","zh":"她真誠希望幫助低年級學生，而不只是為了改善自己的履歷。"},{"en":"A sincere desire to learn can make someone accept feedback more positively.","zh":"真誠希望學習的人，通常會較正面地接受意見。"},{"en":"In formal writing, this phrase helps show that the intention is serious and not selfish.","zh":"在正式寫作中，這個說法有助顯示意圖認真，而且不是自私的。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"grow with the company","meaning":"與公司一同成長","examples":[{"en":"I have a sincere desire to grow with the company.","zh":"我真誠希望與公司一同成長。"},{"en":"To grow with the company means to develop your skills and career as the company develops.","zh":"「與公司一同成長」指隨着公司發展，同時發展自己的技能和事業。"},{"en":"A new employee may hope to grow with the company by learning different roles over time.","zh":"新員工可能希望透過逐步學習不同職務，與公司一同成長。"},{"en":"Employees grow with the company when they take on new responsibilities as the business expands.","zh":"當業務擴展而員工承擔新責任時，他們就是在與公司一同成長。"},{"en":"This phrase shows loyalty because the person wants personal progress and company progress together.","zh":"這個說法顯示忠誠，因為說話者希望個人進步和公司進步同時發生。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"one of the most competitive","meaning":"最具競爭力的……之一","examples":[{"en":"Shanghai is one of the most competitive hospitality markets in the region.","zh":"上海是區內最具競爭力的酒店業市場之一。"},{"en":"“One of the most competitive” means among the places or fields where competition is strongest.","zh":"“One of the most competitive” 指在競爭最激烈的地方或領域之中。"},{"en":"Law is one of the most competitive subjects at many universities.","zh":"法律是許多大學中最具競爭力的學科之一。"},{"en":"A company needs strong service to succeed in one of the most competitive markets.","zh":"公司若要在最具競爭力的市場之一成功，便需要強大的服務。"},{"en":"This phrase highlights that success is difficult because many strong rivals are present.","zh":"這個說法強調成功並不容易，因為當中有很多強勁對手。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"hospitality markets","meaning":"酒店業市場","examples":[{"en":"Shanghai is a highly competitive hospitality market.","zh":"上海是一個競爭非常激烈的酒店業市場。"},{"en":"Hospitality markets are business environments involving hotels, restaurants, travel services, and guest experiences.","zh":"酒店業市場是涉及酒店、餐廳、旅遊服務和客人體驗的商業環境。"},{"en":"Tourist cities usually have active hospitality markets because many visitors need places to stay and eat.","zh":"旅遊城市通常有活躍的酒店業市場，因為許多訪客需要住宿和餐飲。"},{"en":"Hospitality markets change when travellers’ habits, spending patterns, and service expectations change.","zh":"當旅客習慣、消費模式和服務期望改變時，酒店業市場也會改變。"},{"en":"Understanding hospitality markets helps hotels decide what services guests will value.","zh":"了解酒店業市場可以幫助酒店決定住客重視哪些服務。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"in the region","meaning":"在區內","examples":[{"en":"Shanghai is one of the most competitive hospitality markets in the region.","zh":"上海是區內最具競爭力的酒店業市場之一。"},{"en":"In the region means within a particular area, usually a city group, country area, or part of the world.","zh":"「在區內」指在某個特定地區之內，通常是城市群、國家某部分或世界某區域。"},{"en":"This hospital is one of the largest medical centres in the region.","zh":"這間醫院是區內最大的醫療中心之一。"},{"en":"A hotel’s reputation in the region can attract guests from nearby cities.","zh":"酒店在區內的聲譽可以吸引附近城市的住客。"},{"en":"This phrase helps compare one place with other places around it.","zh":"這個說法有助把某個地方與周邊地方作比較。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"domestic tourists","meaning":"內地遊客","examples":[{"en":"Shanghai attracts domestic tourists and expatriates.","zh":"上海吸引內地遊客和外籍居民。"},{"en":"Domestic tourists are people who travel within their own country instead of travelling abroad.","zh":"內地遊客是在自己國家內旅遊，而不是到外國旅遊的人。"},{"en":"During long holidays, domestic tourists may visit major cities, theme parks, or historical sites.","zh":"長假期間，內地遊客可能會到主要城市、主題公園或歷史景點。"},{"en":"Hotels serve domestic tourists better when they understand local payment habits and travel expectations.","zh":"酒店若了解本地付款習慣和旅遊期望，便能更好地服務內地遊客。"},{"en":"Domestic tourists can be an important source of business even when international travel slows down.","zh":"即使國際旅遊放緩，內地遊客仍可以是重要客源。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"expatriates","meaning":"外籍居民","examples":[{"en":"Shanghai attracts domestic tourists, expatriates, and luxury travellers.","zh":"上海吸引內地遊客、外籍居民和高端旅客。"},{"en":"Expatriates are people who live outside their home country, usually for work, study, or family reasons.","zh":"外籍居民是居住在自己國家以外的人，通常因工作、學習或家庭原因而移居。"},{"en":"Many expatriates need long-stay accommodation when they first move to a new city.","zh":"許多外籍居民剛搬到新城市時，需要長期住宿安排。"},{"en":"Hotels serving expatriates may need staff who understand different languages and cultural habits.","zh":"服務外籍居民的酒店可能需要了解不同語言和文化習慣的員工。"},{"en":"Expatriates are not short-term tourists; they usually live in the host country for a longer period.","zh":"外籍居民不是短期遊客；他們通常會在居住國生活較長時間。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"conference organisers","meaning":"會議籌辦者","examples":[{"en":"Shanghai attracts conference organisers from around the world.","zh":"上海吸引來自世界各地的會議籌辦者。"},{"en":"Conference organisers are people or companies that plan meetings, exhibitions, or professional events.","zh":"會議籌辦者是負責規劃會議、展覽或專業活動的人或公司。"},{"en":"Conference organisers may book hotel rooms, meeting halls, meals, and transport for participants.","zh":"會議籌辦者可能為參加者預訂酒店房間、會議廳、膳食和交通。"},{"en":"Hotels value conference organisers because one event can bring many guests at the same time.","zh":"酒店重視會議籌辦者，因為一個活動可以同時帶來很多住客。"},{"en":"Good service for conference organisers requires clear communication and careful scheduling.","zh":"為會議籌辦者提供良好服務，需要清楚溝通和仔細安排時間。"}],"source":"2020 Q4.pdf","sourcePage":8},{"front":"luxury travellers","meaning":"高端旅客","examples":[{"en":"Shanghai attracts luxury travellers from around the world.","zh":"上海吸引來自世界各地的高端旅客。"},{"en":"Luxury travellers are travellers who expect high-end service, comfort, privacy, and quality.","zh":"高端旅客是期望高級服務、舒適、私隱和品質的旅客。"},{"en":"Luxury travellers may choose hotels with fine dining, personal assistance, and spacious rooms.","zh":"高端旅客可能選擇有高級餐飲、個人化協助和寬敞房間的酒店。"},{"en":"Serving luxury travellers requires attention to detail because expectations are usually high.","zh":"服務高端旅客需要注意細節，因為他們的期望通常很高。"},{"en":"Luxury travellers may pay more, but they also notice mistakes quickly.","zh":"高端旅客可能願意支付較高費用，但他們也很快會注意到錯誤。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"from around the world","meaning":"來自世界各地","examples":[{"en":"Shanghai attracts travellers from around the world.","zh":"上海吸引來自世界各地的旅客。"},{"en":"From around the world means from many different countries or regions internationally.","zh":"「來自世界各地」指來自國際上許多不同國家或地區。"},{"en":"The exhibition attracted artists from around the world.","zh":"那個展覽吸引了來自世界各地的藝術家。"},{"en":"A hotel that receives guests from around the world must be ready for different languages and customs.","zh":"接待來自世界各地住客的酒店，必須準備好面對不同語言和習俗。"},{"en":"This phrase emphasises international variety, not just visitors from one nearby place.","zh":"這個說法強調國際多樣性，而不只是來自附近某一個地方的訪客。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"allow me to understand","meaning":"讓我了解","examples":[{"en":"Working there would allow me to understand excellent service in a different setting.","zh":"在那裏工作會讓我了解在不同環境中的優質服務。"},{"en":"“Allow me to understand” means give me the chance or conditions to learn something clearly.","zh":"“Allow me to understand” 指給我機會或條件去清楚學習某事。"},{"en":"Visiting the factory allowed me to understand how the product was actually made.","zh":"參觀工廠讓我了解產品實際上如何製造。"},{"en":"Working with different customers can allow me to understand needs that I had not noticed before.","zh":"與不同顧客工作可以讓我了解以前沒有留意到的需要。"},{"en":"This phrase is useful when explaining how an experience will create learning.","zh":"當解釋某段經驗如何帶來學習時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"what counts as","meaning":"怎樣才算是","examples":[{"en":"Working in Shanghai would show me what counts as excellent service there.","zh":"在上海工作會讓我明白在那裏怎樣才算是優質服務。"},{"en":"“What counts as” means what is considered or accepted as a particular thing in a certain situation.","zh":"“What counts as” 指在某個情況中甚麼被視為或接受為某件事。"},{"en":"In this course, regular attendance counts as part of the final grade.","zh":"在這個課程中，定期出席也算是總成績的一部分。"},{"en":"What counts as polite behaviour may differ between cultures and workplaces.","zh":"怎樣才算是有禮貌的行為，可能因文化和工作場所而不同。"},{"en":"This phrase is useful when standards depend on context.","zh":"當標準取決於語境時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"excellent service","meaning":"優質服務","examples":[{"en":"I want to understand what counts as excellent service in Shanghai.","zh":"我希望了解在上海怎樣才算是優質服務。"},{"en":"Excellent service is service that is helpful, reliable, polite, efficient, and suited to the customer’s needs.","zh":"優質服務是有幫助、可靠、有禮、有效率，並符合顧客需要的服務。"},{"en":"Excellent service in a hotel may include fast check-in, accurate information, and thoughtful problem-solving.","zh":"酒店的優質服務可能包括快速入住登記、準確資訊和細心解決問題。"},{"en":"Excellent service creates trust because guests feel their time and comfort are respected.","zh":"優質服務能建立信任，因為住客感到自己的時間和舒適受到尊重。"},{"en":"What counts as excellent service can vary between markets, but respect and reliability always matter.","zh":"怎樣才算是優質服務可能因市場而異，但尊重和可靠永遠重要。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"cultural and commercial setting","meaning":"文化和商業環境","examples":[{"en":"Shanghai offers a different cultural and commercial setting.","zh":"上海提供一個不同的文化和商業環境。"},{"en":"A cultural and commercial setting is the social, cultural, and business environment in which work happens.","zh":"文化和商業環境是工作發生其中的社會、文化和商業背景。"},{"en":"A shop in a tourist district operates in a different cultural and commercial setting from a shop in a quiet neighbourhood.","zh":"旅遊區商店所處的文化和商業環境，與安靜社區的小店不同。"},{"en":"Understanding the cultural and commercial setting helps staff communicate with customers more appropriately.","zh":"了解文化和商業環境可以幫助員工更恰當地與顧客溝通。"},{"en":"A new cultural and commercial setting can teach workers different expectations and business habits.","zh":"新的文化和商業環境可以教會員工不同的期望和商業習慣。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"teach someone speed and flexibility","meaning":"教會某人速度與靈活性","examples":[{"en":"Hong Kong has taught me speed, flexibility, and international etiquette.","zh":"香港教會了我速度、靈活性和國際禮儀。"},{"en":"To teach someone speed and flexibility means to train them to work quickly and adapt when situations change.","zh":"「教會某人速度與靈活性」指訓練某人快速工作，並在情況改變時作出調整。"},{"en":"Working in a busy restaurant taught me speed and flexibility during lunch hours.","zh":"在繁忙餐廳工作，教會了我在午市時間保持速度和靈活性。"},{"en":"Handling different guest requests can teach staff speed and flexibility because plans often change suddenly.","zh":"處理不同住客要求可以教會員工速度與靈活性，因為計劃常突然改變。"},{"en":"Speed without flexibility can become careless, while flexibility without speed may be too slow for service work.","zh":"有速度但沒有靈活性可能變得草率；有靈活性但沒有速度，對服務工作來說可能太慢。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"international etiquette","meaning":"國際禮儀","examples":[{"en":"Hong Kong has taught me international etiquette.","zh":"香港教會了我國際禮儀。"},{"en":"International etiquette is the polite behaviour expected when dealing with people from different countries or cultures.","zh":"國際禮儀是與來自不同國家或文化的人相處時所期望的得體行為。"},{"en":"International etiquette includes greeting guests respectfully, avoiding rude gestures, and understanding cultural differences.","zh":"國際禮儀包括有禮地問候住客、避免無禮手勢，以及理解文化差異。"},{"en":"Hotel staff need international etiquette because guests may have different ideas about privacy, time, and communication.","zh":"酒店員工需要國際禮儀，因為住客對私隱、時間和溝通可能有不同看法。"},{"en":"Good international etiquette helps avoid misunderstandings and makes guests feel respected.","zh":"良好的國際禮儀有助避免誤會，並令住客感到被尊重。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"broaden my understanding of","meaning":"擴闊我對……的理解","examples":[{"en":"Shanghai would broaden my understanding of Mainland consumer expectations.","zh":"上海會擴闊我對內地消費者期望的理解。"},{"en":"To broaden my understanding of something means to help me know it in a wider, deeper, or more complete way.","zh":"「擴闊我對……的理解」指幫助我以更廣、更深或更完整的方式認識某事。"},{"en":"Volunteering at a care home broadened my understanding of elderly people’s daily needs.","zh":"在安老院做義工擴闊了我對長者日常需要的理解。"},{"en":"Working with different teams can broaden my understanding of how a company really operates.","zh":"與不同團隊合作可以擴闊我對公司實際運作方式的理解。"},{"en":"This phrase is useful when explaining how an experience will expand someone’s knowledge.","zh":"當解釋某段經驗如何擴展知識時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"Mainland consumer expectations","meaning":"內地消費者期望","examples":[{"en":"Shanghai would help me understand Mainland consumer expectations.","zh":"上海會幫助我了解內地消費者期望。"},{"en":"Mainland consumer expectations are the needs, habits, and service standards that customers in Mainland China commonly expect.","zh":"內地消費者期望是中國內地顧客普遍期待的需要、習慣和服務標準。"},{"en":"Mainland consumer expectations may include fast digital payment, quick responses, and clear online information.","zh":"內地消費者期望可能包括快捷電子支付、迅速回應和清楚的網上資訊。"},{"en":"Businesses must understand Mainland consumer expectations if they want to serve customers there well.","zh":"企業如果想好好服務當地顧客，就必須了解內地消費者期望。"},{"en":"These expectations may change over time, so staff should keep learning from real customers.","zh":"這些期望可能隨時間改變，所以員工應持續從真實顧客身上學習。"}],"source":"2020 Q4.pdf","sourcePage":9},{"front":"digital payment habits","meaning":"電子支付習慣","examples":[{"en":"I hope to learn more about digital payment habits in Shanghai.","zh":"我希望進一步了解上海的電子支付習慣。"},{"en":"Digital payment habits are the ways people commonly pay using phones, apps, cards, or online systems instead of cash.","zh":"電子支付習慣是人們常用電話、應用程式、信用卡或網上系統，而不是現金付款的方式。"},{"en":"A café must understand customers’ digital payment habits if most people pay by mobile wallet.","zh":"如果大多數顧客使用手機錢包付款，咖啡店便必須了解顧客的電子支付習慣。"},{"en":"Digital payment habits affect hotel service because guests may expect fast, cashless payment options.","zh":"電子支付習慣會影響酒店服務，因為住客可能期望快速的無現金付款選擇。"},{"en":"Learning local digital payment habits helps staff reduce delays at reception or checkout.","zh":"了解本地電子支付習慣，有助員工減少接待處或退房時的延誤。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"corporate travel needs","meaning":"商務旅遊需要","examples":[{"en":"Shanghai would help me understand corporate travel needs.","zh":"上海會幫助我了解商務旅遊需要。"},{"en":"Corporate travel needs are the requirements of people travelling for business, such as meeting spaces, reliable internet, and flexible schedules.","zh":"商務旅遊需要是商務旅客的要求，例如會議空間、可靠網絡和靈活時間安排。"},{"en":"A business hotel should understand corporate travel needs because guests may arrive late and leave early for meetings.","zh":"商務酒店應了解商務旅遊需要，因為住客可能因會議而很晚抵達、很早離開。"},{"en":"Corporate travel needs affect room design, breakfast times, transport arrangements, and invoice handling.","zh":"商務旅遊需要會影響房間設計、早餐時間、交通安排和發票處理。"},{"en":"Serving corporate travellers well means solving practical problems quickly and professionally.","zh":"好好服務商務旅客，就是快速而專業地解決實際問題。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"only by working in","meaning":"只有在……工作才可以","examples":[{"en":"Only by working in such an environment can I develop wider judgement.","zh":"只有在這樣的環境中工作，我才可以培養更全面的判斷力。"},{"en":"“Only by working in” means that working in a particular place or situation is necessary to achieve a certain result.","zh":"“Only by working in” 表示只有在特定地方或情況中工作，才有可能達成某個結果。"},{"en":"Only by working in a real kitchen can students understand the pressure of restaurant service.","zh":"只有在真實廚房工作，學生才可以了解餐廳服務的壓力。"},{"en":"Only by working in different markets can a manager compare customer expectations fairly.","zh":"只有在不同市場工作，管理人員才可以公平比較顧客期望。"},{"en":"This structure is formal and emphasises that the experience cannot be replaced by theory alone.","zh":"這個結構較正式，並強調單靠理論不能取代實際經驗。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"develop the wider judgement required of","meaning":"培養……所需的更全面判斷力","examples":[{"en":"I hope to develop the wider judgement required of a future manager.","zh":"我希望培養未來管理人員所需的更全面判斷力。"},{"en":"To develop the wider judgement required of a role means to build the broader decision-making ability that the role needs.","zh":"「培養某角色所需的更全面判斷力」指建立該角色需要的更廣闊決策能力。"},{"en":"Leading different projects helped her develop the wider judgement required of a department head.","zh":"帶領不同項目幫助她培養部門主管所需的更全面判斷力。"},{"en":"Wider judgement is developed when people face varied problems and learn to balance different needs.","zh":"當人面對多樣化問題並學會平衡不同需要時，更全面的判斷力便會逐漸形成。"},{"en":"This phrase is useful for showing that a person is preparing for higher responsibility.","zh":"這個說法適合用來顯示某人正在為更高責任作準備。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"a future manager","meaning":"未來管理人員","examples":[{"en":"The transfer would help me prepare to become a future manager.","zh":"這次調職會幫助我準備成為未來管理人員。"},{"en":"A future manager is someone who may take on management responsibilities later in their career.","zh":"未來管理人員是日後可能在事業中承擔管理責任的人。"},{"en":"A future manager should learn how to lead people, solve problems, and understand business goals.","zh":"未來管理人員應學習如何帶領別人、解決問題和理解業務目標。"},{"en":"Working in different branches can prepare a future manager to make decisions across wider contexts.","zh":"在不同分店工作可以幫助未來管理人員在更廣闊的情境中作決定。"},{"en":"A future manager needs not only technical skill, but also judgement, communication, and responsibility.","zh":"未來管理人員不只需要技術能力，也需要判斷力、溝通能力和責任感。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"in other words","meaning":"換言之","examples":[{"en":"In other words, this transfer would turn my experience into cross-market expertise.","zh":"換言之，這次調職會把我的經驗轉化為跨市場專業知識。"},{"en":"“In other words” introduces the same idea again in a clearer, simpler, or more direct way.","zh":"“In other words” 用來以更清楚、更簡單或更直接的方式重新表達同一個想法。"},{"en":"The plan is too expensive; in other words, we need a cheaper option.","zh":"這個計劃太昂貴；換言之，我們需要一個較便宜的選擇。"},{"en":"She learns best through examples; in other words, theory alone is not enough for her.","zh":"她最適合透過例子學習；換言之，單靠理論對她並不足夠。"},{"en":"This phrase helps explain a point again so the reader can understand the meaning more clearly.","zh":"這個說法有助再次解釋重點，讓讀者更清楚明白意思。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"turn existing experience into","meaning":"把現有經驗轉化為……","examples":[{"en":"This transfer would turn my existing experience into cross-market expertise.","zh":"這次調職會把我的現有經驗轉化為跨市場專業知識。"},{"en":"To turn existing experience into something means to use what you already know and develop it into a new ability or value.","zh":"「把現有經驗轉化為……」指運用已有知識，並把它發展成新的能力或價值。"},{"en":"Teaching younger students turned my existing experience in debating into leadership practice.","zh":"教導低年級學生把我現有的辯論經驗轉化為領導實踐。"},{"en":"A new role can turn existing experience into broader professional skill.","zh":"新職位可以把現有經驗轉化為更廣闊的專業技能。"},{"en":"This phrase shows that past experience will not be wasted but expanded.","zh":"這個說法顯示過往經驗不會被浪費，而是會被擴展。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"cross-market expertise","meaning":"跨市場專業知識","examples":[{"en":"This transfer would help me develop cross-market expertise.","zh":"這次調職會幫助我發展跨市場專業知識。"},{"en":"Cross-market expertise is professional knowledge gained from understanding and working across different markets.","zh":"跨市場專業知識是透過理解和參與不同市場而得到的專業知識。"},{"en":"A manager with cross-market expertise can compare customer habits in Hong Kong and Shanghai.","zh":"具備跨市場專業知識的管理人員，可以比較香港和上海顧客的習慣。"},{"en":"Cross-market expertise helps companies adapt services instead of using the same method everywhere.","zh":"跨市場專業知識幫助公司調整服務，而不是在每個地方都使用同一方法。"},{"en":"Developing cross-market expertise is valuable when a business operates in more than one region.","zh":"當企業在多於一個地區營運時，發展跨市場專業知識很有價值。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"benefit the organisation","meaning":"對機構有利","examples":[{"en":"I believe my transfer would benefit the organisation in practical ways.","zh":"本人相信我的調職會以實際方式對機構有利。"},{"en":"To benefit the organisation means to help the company or institution improve, save resources, serve better, or reach its goals.","zh":"「對機構有利」指幫助公司或機構改善、節省資源、提升服務或達成目標。"},{"en":"A new booking system can benefit the organisation by reducing mistakes.","zh":"新預訂系統可以透過減少錯誤而對機構有利。"},{"en":"Staff training benefits the organisation when it improves service quality across the team.","zh":"當職員培訓提升整個團隊的服務質素時，便會對機構有利。"},{"en":"In an application, it is persuasive to explain how your request would benefit the organisation, not only yourself.","zh":"在申請中，說明請求如何對機構有利，而不只對自己有利，會更有說服力。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"in practical ways","meaning":"以實際方式","examples":[{"en":"My transfer would benefit the organisation in practical ways.","zh":"我的調職會以實際方式對機構有利。"},{"en":"“In practical ways” means through real, useful, and specific results rather than only general ideas.","zh":"“In practical ways” 指透過真實、有用和具體的結果，而不只是一般想法。"},{"en":"The new timetable helped students in practical ways by reducing long waiting times.","zh":"新時間表透過減少長時間等候，以實際方式幫助學生。"},{"en":"A transfer can help a company in practical ways if the employee brings skills that solve current problems.","zh":"如果員工帶來能解決現有問題的技能，調職便可以以實際方式幫助公司。"},{"en":"This phrase encourages the writer to explain concrete benefits clearly.","zh":"這個說法提醒作者要清楚解釋具體好處。"}],"source":"2020 Q4.pdf","sourcePage":10},{"front":"serve as a bridge between","meaning":"作為……之間的橋樑","examples":[{"en":"I could serve as a bridge between the Hong Kong and Shanghai branches.","zh":"本人可以作為香港和上海分店之間的橋樑。"},{"en":"To serve as a bridge between two groups means to help them understand, communicate, and work with each other.","zh":"「作為兩者之間的橋樑」指幫助兩個群體互相理解、溝通和合作。"},{"en":"A bilingual teacher can serve as a bridge between new students and the school community.","zh":"一位雙語老師可以作為新生與學校社群之間的橋樑。"},{"en":"An employee who knows two markets can serve as a bridge between teams in different cities.","zh":"熟悉兩個市場的員工可以作為不同城市團隊之間的橋樑。"},{"en":"This phrase suggests connection, communication, and cooperation.","zh":"這個說法帶出連繫、溝通和合作的意思。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"travel between the two cities","meaning":"往返兩地","examples":[{"en":"Many guests travel between the two cities for business and family visits.","zh":"許多住客因商務和探親而往返兩地。"},{"en":"To travel between the two cities means to move regularly or occasionally from one city to the other.","zh":"「往返兩地」指經常或偶爾由一個城市去到另一個城市。"},{"en":"Some employees travel between the two cities every month for meetings.","zh":"有些員工每月因會議往返兩地。"},{"en":"Guests who travel between the two cities may expect consistent service from the same hotel group.","zh":"往返兩地的住客可能期望同一酒店集團提供一致服務。"},{"en":"Understanding why people travel between the two cities helps hotels design better services.","zh":"了解人們為何往返兩地，可以幫助酒店設計更好的服務。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"finance","meaning":"金融業務","examples":[{"en":"Many guests travel between Hong Kong and Shanghai for finance.","zh":"許多住客因金融業務往返香港和上海。"},{"en":"Finance refers to activities involving money, banking, investment, business funding, or financial services.","zh":"金融業務指與金錢、銀行、投資、商業資金或金融服務有關的活動。"},{"en":"A visitor may come to the city for finance meetings with banks and investors.","zh":"訪客可能因與銀行和投資者開金融會議而來到城市。"},{"en":"Hotels near business districts often serve guests connected with finance because they attend meetings nearby.","zh":"商業區附近的酒店常接待與金融業務有關的住客，因為他們會在附近開會。"},{"en":"In this context, finance explains one business reason why guests travel.","zh":"在這個語境中，金融業務解釋住客出行的一個商務原因。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"trade fairs","meaning":"貿易展覽","examples":[{"en":"Many guests travel between the two cities for trade fairs.","zh":"許多住客因貿易展覽而往返兩地。"},{"en":"Trade fairs are large events where companies show products, meet buyers, and discuss business opportunities.","zh":"貿易展覽是公司展示產品、會見買家和討論商機的大型活動。"},{"en":"A furniture company may join a trade fair to find new customers and suppliers.","zh":"家具公司可能參加貿易展覽，以尋找新顧客和供應商。"},{"en":"Trade fairs can increase hotel demand because many exhibitors and visitors need accommodation.","zh":"貿易展覽可以增加酒店需求，因為許多參展商和訪客需要住宿。"},{"en":"Guests attending trade fairs often need convenient transport, early breakfast, and business services.","zh":"參加貿易展覽的住客通常需要方便交通、提早早餐和商務服務。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"family visits","meaning":"探親","examples":[{"en":"Many guests travel between the two cities for family visits.","zh":"許多住客因探親而往返兩地。"},{"en":"Family visits are trips made to see relatives, often during holidays, important events, or personal occasions.","zh":"探親是為了見親人而進行的旅程，常發生在假期、重要活動或私人場合。"},{"en":"A grandmother may travel for family visits when her grandchildren have school holidays.","zh":"祖母可能在孫兒放學假時出行探親。"},{"en":"Hotels serving family visits should understand needs such as connecting rooms, child-friendly meals, and flexible check-in.","zh":"服務探親住客的酒店應了解相連房間、適合兒童的餐飲和彈性入住等需要。"},{"en":"Family visits may not be business trips, but they still require reliable and caring service.","zh":"探親未必是商務旅程，但仍需要可靠和貼心的服務。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"sharing of guest profiles","meaning":"住客資料共享","examples":[{"en":"Better sharing of guest profiles would make stays more personal.","zh":"更好的住客資料共享會令住宿體驗更個人化。"},{"en":"Sharing of guest profiles means exchanging information about guests’ preferences, history, and needs between staff or branches.","zh":"住客資料共享指員工或分店之間交換有關住客偏好、過往紀錄和需要的資訊。"},{"en":"Sharing of guest profiles can help a hotel remember that a returning guest prefers a high floor.","zh":"住客資料共享可以幫助酒店記得回頭住客喜歡高樓層房間。"},{"en":"Better sharing of guest profiles prevents guests from repeating the same information at every branch.","zh":"更好的住客資料共享可以避免住客在每間分店都重複提供同樣資料。"},{"en":"This practice must be handled carefully so guest privacy is respected.","zh":"這種做法必須謹慎處理，以尊重住客私隱。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"room preferences","meaning":"房間偏好","examples":[{"en":"Sharing room preferences can make guests’ stays more personal.","zh":"共享房間偏好可以令住客住宿體驗更個人化。"},{"en":"Room preferences are the types of rooms, locations, or features that guests prefer.","zh":"房間偏好是住客較喜歡的房間種類、位置或特徵。"},{"en":"A guest’s room preferences may include a quiet floor, a bathtub, or a room near the lift.","zh":"住客的房間偏好可能包括安靜樓層、浴缸或靠近升降機的房間。"},{"en":"Recording room preferences helps staff prepare suitable rooms before guests arrive.","zh":"記錄房間偏好可以幫助員工在住客抵達前準備合適房間。"},{"en":"Room preferences cannot always be guaranteed, but knowing them helps hotels serve guests better.","zh":"房間偏好未必一定能滿足，但了解它們可以幫助酒店更好地服務住客。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"complaint records","meaning":"投訴記錄","examples":[{"en":"Sharing complaint records can help staff avoid repeated problems.","zh":"共享投訴記錄可以幫助員工避免重複問題。"},{"en":"Complaint records are written notes about past complaints, including what happened and how the issue was handled.","zh":"投訴記錄是有關過往投訴的書面紀錄，包括發生了甚麼事和如何處理。"},{"en":"A complaint record may show that a guest previously had problems with noise.","zh":"投訴記錄可能顯示某位住客過去曾遇到噪音問題。"},{"en":"Reviewing complaint records helps staff prevent the same mistake from happening again.","zh":"查看投訴記錄可以幫助員工防止同樣錯誤再次發生。"},{"en":"Accurate complaint records protect both guests and the hotel because they preserve important details.","zh":"準確的投訴記錄可以保護住客和酒店，因為它保存重要細節。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"make their stays feel more personal","meaning":"令住宿體驗更個人化","examples":[{"en":"Better information sharing would make guests’ stays feel more personal.","zh":"更好的資訊共享會令住客住宿體驗更個人化。"},{"en":"To make their stays feel more personal means to make guests feel the service is designed around their own needs and preferences.","zh":"「令住宿體驗更個人化」指令住客感到服務是按他們自己的需要和偏好而設。"},{"en":"Remembering a guest’s favourite tea can make their stay feel more personal.","zh":"記得住客喜歡的茶，可以令他們的住宿體驗更個人化。"},{"en":"A hotel can make stays feel more personal by using guest information thoughtfully and respectfully.","zh":"酒店可以透過有心而尊重地使用住客資料，令住宿體驗更個人化。"},{"en":"Personal service makes guests feel recognised rather than treated like strangers.","zh":"個人化服務令住客感到被認出，而不是像陌生人一樣被對待。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"contribute to","meaning":"為……作出貢獻","examples":[{"en":"I could contribute to staff training in Shanghai.","zh":"本人可以為上海的職員培訓作出貢獻。"},{"en":"To contribute to something means to help add value, effort, knowledge, or support to it.","zh":"「為……作出貢獻」指為某事增加價值、努力、知識或支援。"},{"en":"Every team member can contribute to a cleaner classroom by putting rubbish away.","zh":"每位同學都可以透過收拾垃圾，為更清潔的課室作出貢獻。"},{"en":"Experienced employees contribute to training when they share real examples with new staff.","zh":"當有經驗的員工與新員工分享真實例子時，他們就是在為培訓作出貢獻。"},{"en":"This phrase is useful when explaining how your skills can help a larger goal.","zh":"當解釋你的技能如何幫助更大目標時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":11},{"front":"staff training","meaning":"職員培訓","examples":[{"en":"I could contribute to staff training in Shanghai.","zh":"本人可以為上海的職員培訓作出貢獻。"},{"en":"Staff training is the process of teaching employees the skills, procedures, and standards they need for their work.","zh":"職員培訓是教導員工工作所需技能、程序和標準的過程。"},{"en":"Staff training may include role-play, service scripts, safety rules, and system practice.","zh":"職員培訓可能包括角色扮演、服務話術、安全規則和系統練習。"},{"en":"Good staff training reduces mistakes because employees know what to do before problems appear.","zh":"良好的職員培訓可以減少錯誤，因為員工在問題出現前已知道該怎樣做。"},{"en":"Staff training should be updated when customer needs or company procedures change.","zh":"當顧客需要或公司程序改變時，職員培訓應該更新。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"procedures that have worked well","meaning":"行之有效的程序","examples":[{"en":"I could share procedures that have worked well in Hong Kong.","zh":"本人可以分享在香港行之有效的程序。"},{"en":"Procedures that have worked well are methods or steps that have already been tested and shown to be effective.","zh":"行之有效的程序是已經試用過，並證明有效的方法或步驟。"},{"en":"The school kept the safety procedures that had worked well during previous trips.","zh":"學校保留了以往旅行中行之有效的安全程序。"},{"en":"Sharing procedures that have worked well can save another team time and reduce trial and error.","zh":"分享行之有效的程序可以為另一個團隊節省時間，並減少摸索。"},{"en":"Even successful procedures should be adjusted if the new situation is different.","zh":"即使程序曾經成功，如果新情況不同，也應作出調整。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"approach to handling","meaning":"處理……的方法","examples":[{"en":"I could share our approach to handling dissatisfied guests.","zh":"本人可以分享我們處理不滿住客的方法。"},{"en":"An approach to handling something is the method or attitude used to deal with a problem or situation.","zh":"「處理……的方法」指處理某個問題或情況時所用的方法或態度。"},{"en":"The teacher’s approach to handling late homework was firm but fair.","zh":"老師處理遲交功課的方法堅定但公平。"},{"en":"A hotel’s approach to handling complaints should include listening, apologising, and offering solutions.","zh":"酒店處理投訴的方法應包括聆聽、道歉和提供解決方案。"},{"en":"Different approaches to handling the same issue can lead to very different results.","zh":"用不同方法處理同一個問題，可能會帶來非常不同的結果。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"dissatisfied guests","meaning":"不滿的住客","examples":[{"en":"Staff need to handle dissatisfied guests without making them feel blamed.","zh":"員工需要處理不滿的住客，而不令他們覺得被責怪。"},{"en":"Dissatisfied guests are guests who feel unhappy because the service, room, or experience did not meet their expectations.","zh":"不滿的住客是因服務、房間或體驗未達期望而感到不高興的住客。"},{"en":"Dissatisfied guests may complain about noise, delays, incorrect bookings, or poor communication.","zh":"不滿的住客可能投訴噪音、延誤、錯誤預訂或溝通不清。"},{"en":"If staff listen carefully, dissatisfied guests may feel respected even before the problem is fully solved.","zh":"如果員工細心聆聽，即使問題尚未完全解決，不滿的住客也可能感到被尊重。"},{"en":"Handling dissatisfied guests well can protect the relationship between the guest and the hotel.","zh":"妥善處理不滿的住客，可以保護住客與酒店之間的關係。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"without making someone feel blamed","meaning":"不令某人覺得被責怪","examples":[{"en":"We handle dissatisfied guests without making them feel blamed.","zh":"我們處理不滿的住客時，不令他們覺得被責怪。"},{"en":"Without making someone feel blamed means dealing with a problem without suggesting that the person is at fault.","zh":"「不令某人覺得被責怪」指處理問題時，不暗示對方有錯。"},{"en":"The teacher corrected the student’s mistake without making him feel blamed.","zh":"老師糾正學生的錯誤，但沒有令他覺得被責怪。"},{"en":"In service work, staff should solve problems without making customers feel blamed for complaining.","zh":"在服務工作中，員工應解決問題，而不令顧客因投訴而覺得被責怪。"},{"en":"This approach keeps communication open because people feel respected, not attacked.","zh":"這種做法能保持溝通開放，因為人會感到被尊重，而不是被攻擊。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"reputation","meaning":"聲譽","examples":[{"en":"A hotel’s reputation is protected when staff respond well to problems.","zh":"當員工妥善回應問題時，酒店聲譽便受到保護。"},{"en":"Reputation is the general opinion people have about a person, company, or organisation.","zh":"聲譽是人們對某個人、公司或機構的一般看法。"},{"en":"A restaurant’s reputation can improve when customers consistently receive good food and service.","zh":"當顧客持續得到良好食物和服務，餐廳的聲譽可以提升。"},{"en":"Poor handling of complaints can damage a company’s reputation quickly.","zh":"差劣地處理投訴可能很快損害公司的聲譽。"},{"en":"Reputation is built over time through repeated actions, not just one advertisement.","zh":"聲譽是透過長期重複的行動建立的，不只是靠一個廣告。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"not built only when","meaning":"不只是在……時建立","examples":[{"en":"A hotel’s reputation is not built only when everything goes smoothly.","zh":"酒店聲譽不只是在一切順利時建立。"},{"en":"“Not built only when” means something is not created only in easy or successful situations.","zh":"“Not built only when” 表示某事並不只在容易或成功的情況中形成。"},{"en":"Trust is not built only when people agree; it is also built when disagreements are handled respectfully.","zh":"信任不只是在大家同意時建立；也在分歧被尊重地處理時建立。"},{"en":"A team spirit is not built only when projects succeed, but also when members support one another during failure.","zh":"團隊精神不只是在項目成功時建立，也在成員於失敗時互相支持時建立。"},{"en":"This phrase helps show that difficult moments can also create value.","zh":"這個說法有助顯示困難時刻也可以創造價值。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"go smoothly","meaning":"順利進行","examples":[{"en":"A hotel’s reputation is not built only when everything goes smoothly.","zh":"酒店聲譽不只是在一切順利進行時建立。"},{"en":"If something goes smoothly, it happens without serious problems, delays, or confusion.","zh":"如果某事順利進行，表示它沒有嚴重問題、延誤或混亂。"},{"en":"The school trip went smoothly because teachers planned transport and lunch carefully.","zh":"學校旅行順利進行，因為老師仔細安排了交通和午餐。"},{"en":"Things are more likely to go smoothly when people communicate early and prepare well.","zh":"當人們及早溝通並準備充足時，事情更有可能順利進行。"},{"en":"Even when work does not go smoothly, a calm response can still protect trust.","zh":"即使工作沒有順利進行，冷靜回應仍可以保護信任。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"quite the contrary","meaning":"正好相反","examples":[{"en":"Quite the contrary, reputation is often protected when something goes wrong.","zh":"正好相反，聲譽往往是在事情出錯時受到保護。"},{"en":"“Quite the contrary” means the opposite of what was just suggested is actually true.","zh":"“Quite the contrary” 表示剛才暗示的事情其實正好相反。"},{"en":"Some people think strict feedback discourages students; quite the contrary, fair feedback can help them improve.","zh":"有些人認為嚴格意見會打擊學生；正好相反，公平的意見可以幫助他們進步。"},{"en":"The hotel did not lose trust after the mistake; quite the contrary, its careful response impressed the guests.","zh":"酒店沒有因錯誤失去信任；正好相反，它細心的回應令住客留下好印象。"},{"en":"This phrase is useful when strongly correcting a mistaken idea.","zh":"當要強烈糾正錯誤想法時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"when something goes wrong","meaning":"當事情出錯時","examples":[{"en":"A hotel’s reputation is protected when something goes wrong and staff respond well.","zh":"當事情出錯而員工妥善回應時，酒店聲譽便受到保護。"},{"en":"“When something goes wrong” means when a problem, mistake, accident, or unexpected difficulty happens.","zh":"“When something goes wrong” 指當問題、錯誤、意外或突發困難發生時。"},{"en":"When something goes wrong during a flight, passengers need clear information quickly.","zh":"當航班出錯時，乘客需要迅速得到清楚資訊。"},{"en":"Staff training is most important when something goes wrong because employees must act under pressure.","zh":"當事情出錯時，職員培訓最重要，因為員工必須在壓力下行動。"},{"en":"People often judge service quality by what happens when something goes wrong.","zh":"人們常根據事情出錯時的處理方式來判斷服務質素。"}],"source":"2020 Q4.pdf","sourcePage":12},{"front":"respond with dignity","meaning":"有尊嚴地回應","examples":[{"en":"Staff should respond with dignity when something goes wrong.","zh":"當事情出錯時，員工應有尊嚴地回應。"},{"en":"To respond with dignity means to react calmly, respectfully, and professionally even in a difficult situation.","zh":"「有尊嚴地回應」指即使在困難情況中，也冷靜、有禮和專業地作出反應。"},{"en":"The manager responded with dignity when the customer shouted, keeping her voice calm and polite.","zh":"當顧客大聲責罵時，經理保持冷靜有禮，以有尊嚴的方式回應。"},{"en":"Responding with dignity can stop a conflict from becoming more emotional.","zh":"有尊嚴地回應可以防止衝突變得更加情緒化。"},{"en":"In hospitality, staff protect the brand when they respond with dignity under pressure.","zh":"在酒店業中，員工在壓力下有尊嚴地回應，就是在保護品牌。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"brand values","meaning":"品牌價值","examples":[{"en":"I already understand Park Hotel’s standards, reservation system, and brand values.","zh":"本人已了解百樂酒店的標準、預訂系統和品牌價值。"},{"en":"Brand values are the principles and qualities a company wants people to associate with its name.","zh":"品牌價值是公司希望人們與其名稱聯繫起來的原則和特質。"},{"en":"A hotel’s brand values may include warmth, reliability, efficiency, and respect.","zh":"酒店的品牌價值可能包括溫暖、可靠、效率和尊重。"},{"en":"Staff who understand brand values can make decisions that match the company’s image.","zh":"了解品牌價值的員工，能作出符合公司形象的決定。"},{"en":"Brand values should appear in daily service, not only in advertisements.","zh":"品牌價值應體現在日常服務中，而不只是出現在廣告裏。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"reservation system","meaning":"預訂系統","examples":[{"en":"I already understand the company’s reservation system.","zh":"本人已了解公司的預訂系統。"},{"en":"A reservation system is the tool or process used to record, manage, and check bookings.","zh":"預訂系統是用來記錄、管理和查核預訂的工具或流程。"},{"en":"Hotel staff use the reservation system to confirm guest names, dates, room types, and payment details.","zh":"酒店員工使用預訂系統確認住客姓名、日期、房間類型和付款資料。"},{"en":"A reliable reservation system reduces double bookings and check-in mistakes.","zh":"可靠的預訂系統可以減少重複預訂和入住登記錯誤。"},{"en":"New staff usually need training before they can use the reservation system accurately.","zh":"新員工通常需要培訓，才能準確使用預訂系統。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"invest time in","meaning":"投入時間於……","examples":[{"en":"The company would not have to invest as much time in basic orientation.","zh":"公司不需要在基本入職指導上投入那麼多時間。"},{"en":"To invest time in something means to spend time on it because it is expected to bring value later.","zh":"「投入時間於……」指花時間在某事上，因為預期它之後會帶來價值。"},{"en":"Teachers invest time in lesson planning so students can learn more clearly.","zh":"老師投入時間於備課，讓學生能更清楚地學習。"},{"en":"A company invests time in training because skilled employees make fewer mistakes.","zh":"公司投入時間於培訓，因為熟練員工較少犯錯。"},{"en":"Time invested in preparation can save much more time when problems appear later.","zh":"投入時間於準備，可以在之後問題出現時節省更多時間。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"basic orientation","meaning":"基本入職指導","examples":[{"en":"An internal transfer would require less basic orientation.","zh":"內部調職需要較少基本入職指導。"},{"en":"Basic orientation is the introductory training that helps new staff understand the workplace, rules, systems, and culture.","zh":"基本入職指導是幫助新員工了解工作場所、規則、系統和文化的入門培訓。"},{"en":"Basic orientation may include learning emergency exits, computer systems, and company policies.","zh":"基本入職指導可能包括認識緊急出口、電腦系統和公司政策。"},{"en":"An employee from the same company may need less basic orientation because they already know many internal standards.","zh":"來自同一公司的員工可能需要較少基本入職指導，因為他們已了解許多內部標準。"},{"en":"Basic orientation is important, but experienced internal staff can often move beyond it faster.","zh":"基本入職指導很重要，但有經驗的內部員工通常可以更快越過這個階段。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"external recruit","meaning":"外部招聘人員","examples":[{"en":"The company would need more time to train an external recruit.","zh":"公司需要更多時間培訓外部招聘人員。"},{"en":"An external recruit is a new employee hired from outside the organisation.","zh":"外部招聘人員是從機構外聘請的新員工。"},{"en":"An external recruit may bring fresh ideas but also needs time to learn internal systems.","zh":"外部招聘人員可能帶來新想法，但也需要時間學習內部系統。"},{"en":"Training an external recruit can take longer because they may not know the company’s culture or procedures.","zh":"培訓外部招聘人員可能需時較長，因為他們未必了解公司文化或程序。"},{"en":"Comparing an internal transfer with an external recruit can show why company knowledge is valuable.","zh":"比較內部調職和外部招聘人員，可以顯示公司知識的價值。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"what the Shanghai branch would gain","meaning":"上海分店將會得到的是","examples":[{"en":"What the Shanghai branch would gain is a colleague with proven practices.","zh":"上海分店將會得到的是一位具備已驗證做法的同事。"},{"en":"“What the Shanghai branch would gain” means the benefit or value the Shanghai branch would receive.","zh":"“What the Shanghai branch would gain” 指上海分店將會得到的好處或價值。"},{"en":"What the new team would gain is a member who already understands customer service systems.","zh":"新團隊將會得到的是一位已了解客戶服務系統的成員。"},{"en":"Explaining what a branch would gain makes a transfer request less self-centred.","zh":"解釋某分店將會得到甚麼，可以令調職申請不那麼以自我為中心。"},{"en":"This phrase focuses the reader on the practical advantage for the receiving workplace.","zh":"這個說法把讀者注意力放在接收工作地點的實際好處上。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"carry proven practices across borders","meaning":"跨地區帶來已驗證的做法","examples":[{"en":"I can carry proven practices across borders.","zh":"本人可以跨地區帶來已驗證的做法。"},{"en":"To carry proven practices across borders means to bring methods that have worked well in one place to another country or region.","zh":"「跨地區帶來已驗證的做法」指把在某地行之有效的方法帶到另一個國家或地區。"},{"en":"A hotel manager can carry proven practices across borders by adapting successful training from one branch to another.","zh":"酒店經理可以把一間分店成功的培訓方法調整後帶到另一地，從而跨地區帶來已驗證的做法。"},{"en":"Carrying proven practices across borders can save time because the method has already been tested.","zh":"跨地區帶來已驗證的做法可以節省時間，因為方法已經測試過。"},{"en":"However, proven practices must still be adjusted to fit local culture and customer expectations.","zh":"然而，已驗證的做法仍必須按本地文化和顧客期望作出調整。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"fully understand that","meaning":"充分明白","examples":[{"en":"I fully understand that any transfer must be arranged carefully.","zh":"本人充分明白任何調職都必須仔細安排。"},{"en":"“Fully understand that” means to clearly and completely recognise an important fact or condition.","zh":"“Fully understand that” 指清楚而完整地認識某個重要事實或條件。"},{"en":"I fully understand that the deadline cannot be changed for one student only.","zh":"我充分明白截止日期不能只為一名學生更改。"},{"en":"Saying “I fully understand that” shows respect for the reader’s concerns or responsibilities.","zh":"說 “I fully understand that” 可以顯示你尊重讀者的關注或責任。"},{"en":"This phrase is useful when acknowledging limits before making a request.","zh":"當你在提出請求前承認限制時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"be arranged without weakening","meaning":"在不削弱……的情況下安排","examples":[{"en":"Any transfer must be arranged without weakening the Hong Kong team.","zh":"任何調職都必須在不削弱香港團隊的情況下安排。"},{"en":"To be arranged without weakening something means to organise a change while making sure the original team or system remains strong.","zh":"「在不削弱某事的情況下安排」指安排一項改變時，確保原有團隊或系統仍然穩健。"},{"en":"The teacher’s absence was arranged without weakening the class because another teacher prepared the lesson in advance.","zh":"那位老師缺席的安排沒有削弱班級，因為另一位老師已預先準備課堂。"},{"en":"A transfer should be arranged without weakening the current team by preparing handover notes and training support.","zh":"調職應透過準備交接筆記和培訓支援，在不削弱現有團隊的情況下安排。"},{"en":"This phrase shows that the writer understands the possible cost of the request.","zh":"這個說法顯示作者明白請求可能帶來的成本。"}],"source":"2020 Q4.pdf","sourcePage":13},{"front":"if my application is approved","meaning":"如果我的申請獲批","examples":[{"en":"If my application is approved, I will prepare a detailed handover plan.","zh":"如果我的申請獲批，本人會準備詳細交接計劃。"},{"en":"“If my application is approved” means if the person or organisation officially accepts the request.","zh":"“If my application is approved” 指如果相關人士或機構正式接受該請求。"},{"en":"If my application is approved, I will confirm my start date with the new department.","zh":"如果我的申請獲批，我會與新部門確認開始日期。"},{"en":"This phrase is useful because it shows the writer understands approval has not yet been granted.","zh":"這個說法很有用，因為它顯示作者明白申請尚未獲批准。"},{"en":"After an application is approved, the applicant should follow the next steps carefully.","zh":"申請獲批後，申請人應仔細跟進下一步。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"be glad to","meaning":"很樂意","examples":[{"en":"I would be glad to prepare a detailed handover plan.","zh":"本人很樂意準備詳細交接計劃。"},{"en":"“Be glad to” means to be willing and happy to do something.","zh":"“Be glad to” 指願意並樂於做某事。"},{"en":"I would be glad to answer any questions about the report.","zh":"本人很樂意回答任何有關報告的問題。"},{"en":"This phrase sounds polite and helpful in formal emails and letters.","zh":"這個說法在正式電郵和信件中聽起來有禮而樂於幫忙。"},{"en":"“I would be glad to” is softer and more professional than simply saying “I can.”","zh":"“I would be glad to” 比單純說 “I can” 更委婉和專業。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"a detailed handover plan","meaning":"詳細交接計劃","examples":[{"en":"I would prepare a detailed handover plan before leaving.","zh":"本人會在離任前準備詳細交接計劃。"},{"en":"A detailed handover plan is a clear document or arrangement explaining how duties, information, and unfinished work will be passed to others.","zh":"詳細交接計劃是清楚說明職責、資料和未完成工作如何交給他人的文件或安排。"},{"en":"A detailed handover plan may include contact lists, deadlines, training notes, and current problems.","zh":"詳細交接計劃可能包括聯絡名單、截止日期、培訓筆記和現有問題。"},{"en":"Preparing a detailed handover plan helps the team continue working smoothly after someone leaves.","zh":"準備詳細交接計劃可以幫助團隊在某人離開後仍然順利運作。"},{"en":"Without a detailed handover plan, important tasks may be forgotten or repeated.","zh":"如果沒有詳細交接計劃，重要任務可能會被遺忘或重複處理。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"update the front-desk training notes","meaning":"更新前台培訓筆記","examples":[{"en":"I would update the front-desk training notes before departure.","zh":"本人會在離任前更新前台培訓筆記。"},{"en":"To update the front-desk training notes means to revise the written instructions used to train reception staff.","zh":"「更新前台培訓筆記」指修訂用來培訓接待處員工的書面指引。"},{"en":"The supervisor updated the front-desk training notes after the hotel changed its check-in system.","zh":"酒店更改入住登記系統後，主管更新了前台培訓筆記。"},{"en":"Updating the front-desk training notes helps new staff learn the latest procedures.","zh":"更新前台培訓筆記可以幫助新員工學習最新程序。"},{"en":"Training notes should be updated before they become outdated or misleading.","zh":"培訓筆記應在變得過時或具誤導性之前更新。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"front-desk training notes","meaning":"前台培訓筆記","examples":[{"en":"The front-desk training notes should be updated before my transfer.","zh":"前台培訓筆記應在本人調職前更新。"},{"en":"Front-desk training notes are written materials that teach reception staff how to handle daily duties and guest situations.","zh":"前台培訓筆記是教導接待處員工如何處理日常職責和住客情況的書面材料。"},{"en":"Front-desk training notes may explain check-in steps, phone greetings, and complaint responses.","zh":"前台培訓筆記可能解釋入住登記步驟、電話問候語和投訴回應。"},{"en":"Clear front-desk training notes help new staff work more confidently.","zh":"清楚的前台培訓筆記可以幫助新員工更有信心地工作。"},{"en":"If front-desk training notes are unclear, staff may give guests inconsistent answers.","zh":"如果前台培訓筆記不清楚，員工可能會向住客給出不一致的答案。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"assist in coaching","meaning":"協助指導","examples":[{"en":"I would assist in coaching my replacement before departure.","zh":"本人會在離任前協助指導接替我的同事。"},{"en":"To assist in coaching someone means to help train, guide, and prepare that person for a role.","zh":"「協助指導」指幫助培訓、引導和準備某人擔任某個角色。"},{"en":"The senior nurse assisted in coaching new staff during their first week.","zh":"資深護士在新員工第一星期協助指導他們。"},{"en":"Assisting in coaching a replacement can reduce disruption when an employee leaves.","zh":"協助指導接替者可以減少員工離開時造成的影響。"},{"en":"This phrase shows willingness to support the team during a transition.","zh":"這個說法顯示願意在過渡期間支援團隊。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"my replacement","meaning":"接替我的同事","examples":[{"en":"I would help coach my replacement before departure.","zh":"本人會在離任前協助指導接替我的同事。"},{"en":"My replacement is the person who will take over my role or duties after I leave or move.","zh":"接替我的同事是我離開或調職後接手我職位或職責的人。"},{"en":"I wrote clear notes so my replacement could understand the project quickly.","zh":"我寫下清楚筆記，讓接替我的同事能快速了解項目。"},{"en":"Training my replacement well helps the team continue working without confusion.","zh":"好好培訓接替我的同事，可以幫助團隊繼續工作而不混亂。"},{"en":"A responsible employee supports their replacement instead of leaving problems behind.","zh":"負責任的員工會支援接替自己的同事，而不是留下問題。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"before departure","meaning":"離任前；出發前","examples":[{"en":"I would complete the handover before departure.","zh":"本人會在離任前完成交接。"},{"en":"Before departure means before leaving a place, job, branch, or journey starting point.","zh":"“Before departure” 指在離開某個地方、工作、分店或旅程起點之前。"},{"en":"Please check your passport before departure.","zh":"出發前請檢查你的護照。"},{"en":"Employees should complete urgent tasks before departure so colleagues are not left confused.","zh":"員工應在離任前完成緊急任務，讓同事不會感到混亂。"},{"en":"This phrase is useful when describing preparation that must happen before someone leaves.","zh":"當描述某人離開前必須完成的準備時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"remain available to","meaning":"繼續可以","examples":[{"en":"I would remain available to answer follow-up questions.","zh":"本人會繼續可以回答跟進問題。"},{"en":"To remain available to do something means to continue being ready and reachable for that purpose.","zh":"“Remain available to” 指繼續為某個目的保持可聯絡和可提供協助。"},{"en":"The teacher remained available to answer questions after class.","zh":"老師課後仍可繼續回答問題。"},{"en":"After moving to another branch, an employee may remain available to explain old files when needed.","zh":"調到另一間分店後，員工在需要時仍可繼續解釋舊檔案。"},{"en":"This phrase shows continued responsibility even after the main task has ended.","zh":"這個說法顯示即使主要任務結束後，仍然保持責任感。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"follow-up questions","meaning":"跟進問題","examples":[{"en":"I would answer follow-up questions from Hong Kong after settling in Shanghai.","zh":"本人在上海安頓下來後，會回答香港方面的跟進問題。"},{"en":"Follow-up questions are later questions asked to clarify, continue, or check something already discussed.","zh":"跟進問題是之後提出，用來澄清、延續或查核已討論事情的問題。"},{"en":"After the training session, new staff sent follow-up questions about the booking system.","zh":"培訓課程後，新員工傳來有關預訂系統的跟進問題。"},{"en":"Answering follow-up questions helps prevent confusion after a handover.","zh":"回答跟進問題有助在交接後避免混亂。"},{"en":"Good instructions reduce follow-up questions, but some later questions are still normal.","zh":"良好的指示可以減少跟進問題，但之後仍有一些問題是正常的。"}],"source":"2020 Q4.pdf","sourcePage":14},{"front":"after settling in","meaning":"安頓下來後","examples":[{"en":"I would answer questions after settling in Shanghai.","zh":"本人在上海安頓下來後，會回答問題。"},{"en":"After settling in means after becoming more comfortable and organised in a new place or situation.","zh":"「安頓下來後」指在新地方或新情況中變得較舒適和有條理之後。"},{"en":"After settling in at university, she joined two clubs and made new friends.","zh":"在大學安頓下來後，她加入了兩個學會並結識新朋友。"},{"en":"An employee may need a few weeks after settling in before taking on extra duties.","zh":"員工安頓下來後，可能仍需要幾星期才承擔額外職責。"},{"en":"This phrase suggests that the person has adjusted enough to function normally.","zh":"這個說法表示某人已適應到能正常運作的程度。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"the transition","meaning":"過渡","examples":[{"en":"I would help make the transition as smooth as possible.","zh":"本人會幫助令過渡盡量順利。"},{"en":"The transition is the process of changing from one situation, role, place, or system to another.","zh":"過渡是由一種情況、角色、地方或系統轉到另一種的過程。"},{"en":"The transition from primary school to secondary school can be difficult for some students.","zh":"由小學過渡到中學，對一些學生來說可能很困難。"},{"en":"A careful handover makes the transition easier when a staff member leaves.","zh":"當員工離開時，仔細交接可以令過渡更容易。"},{"en":"During a transition, clear communication reduces uncertainty and mistakes.","zh":"在過渡期間，清楚溝通可以減少不確定和錯誤。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"as smooth as possible","meaning":"盡量順利","examples":[{"en":"I would help make the transition as smooth as possible.","zh":"本人會幫助令過渡盡量順利。"},{"en":"As smooth as possible means with as few problems, delays, or difficulties as can reasonably be achieved.","zh":"“As smooth as possible” 指在合理可行範圍內，盡量減少問題、延誤或困難。"},{"en":"The school prepared maps and guides to make the first day as smooth as possible.","zh":"學校準備地圖和指南，令開學第一天盡量順利。"},{"en":"A detailed plan can make a staff change as smooth as possible for the whole team.","zh":"詳細計劃可以令員工變動對整個團隊而言盡量順利。"},{"en":"This phrase shows a realistic goal: problems may appear, but preparation can reduce them.","zh":"這個說法顯示一個現實目標：問題可能出現，但準備可以減少它們。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"thank you very much for considering","meaning":"非常感謝你考慮……","examples":[{"en":"Thank you very much for considering my request.","zh":"非常感謝你考慮本人的請求。"},{"en":"“Thank you very much for considering” is a polite way to thank someone for taking time to think about a request or application.","zh":"“Thank you very much for considering” 是有禮地感謝別人花時間思考請求或申請的說法。"},{"en":"Thank you very much for considering my proposal for the school event.","zh":"非常感謝你考慮本人有關學校活動的建議。"},{"en":"This phrase is often placed near the end of a formal letter to show respect and appreciation.","zh":"這個說法常放在正式信件結尾附近，用來表示尊重和感謝。"},{"en":"It does not assume approval; it simply thanks the reader for giving the matter attention.","zh":"它並不假定申請獲批；只是感謝讀者願意關注此事。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"I would appreciate it if","meaning":"如你能……我將不勝感激","examples":[{"en":"I would appreciate it if you could advise me on the next steps.","zh":"如你能就下一步給予本人指示，本人將不勝感激。"},{"en":"“I would appreciate it if” is a polite way to ask someone to do something for you.","zh":"“I would appreciate it if” 是有禮地請求別人為你做某事的句式。"},{"en":"I would appreciate it if you could send me the meeting notes by Friday.","zh":"如你能在星期五前把會議筆記寄給我，我將不勝感激。"},{"en":"This phrase is softer and more formal than directly saying “please do this.”","zh":"這個說法比直接說「請做這件事」更委婉和正式。"},{"en":"It is useful when the request depends on the other person’s time, authority, or help.","zh":"當請求取決於對方的時間、權力或協助時，這個句式很有用。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"advise me on","meaning":"就……給予指示","examples":[{"en":"Please advise me on the next steps.","zh":"請就下一步給予本人指示。"},{"en":"To advise me on something means to give me guidance, information, or suggestions about it.","zh":"“Advise me on” 指就某事給我指導、資訊或建議。"},{"en":"Could you advise me on which documents I should submit with the application?","zh":"你可否就申請時應提交哪些文件給予我指示？"},{"en":"A manager may advise me on how to prepare for a transfer interview.","zh":"經理可能就如何準備調職面試給予我指導。"},{"en":"This phrase is formal and suitable when asking someone with more knowledge or authority for direction.","zh":"當向更有知識或權力的人請求方向時，這個正式說法很合適。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"the next steps","meaning":"下一步","examples":[{"en":"I would appreciate advice on the next steps.","zh":"如能就下一步給予建議，本人將不勝感激。"},{"en":"The next steps are the actions that should be taken after the current stage.","zh":"下一步是目前階段之後應採取的行動。"},{"en":"After the interview, the next steps may include submitting documents and waiting for approval.","zh":"面試後，下一步可能包括提交文件和等候批准。"},{"en":"Asking about the next steps shows that you are ready to continue the process properly.","zh":"詢問下一步顯示你已準備好妥善繼續程序。"},{"en":"Clear next steps prevent people from feeling uncertain about what to do after a decision.","zh":"清楚的下一步可以避免人們在決定後不知道該做甚麼。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"grant me an opportunity to","meaning":"給予我機會去","examples":[{"en":"I would appreciate it if you could grant me an opportunity to discuss the matter.","zh":"如你能給予我機會商討此事，本人將不勝感激。"},{"en":"To grant me an opportunity to do something means to give me a chance to do it.","zh":"“Grant me an opportunity to” 指給我一個做某事的機會。"},{"en":"I would be grateful if the school could grant me an opportunity to explain my situation.","zh":"如學校能給予我機會解釋自己的情況，本人將十分感激。"},{"en":"This phrase is formal and respectful because it recognises that the chance depends on the reader’s decision.","zh":"這個說法正式而有禮，因為它承認機會取決於讀者的決定。"},{"en":"It is often used when requesting a meeting, interview, or discussion.","zh":"它常用於請求會面、面試或討論時。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"discuss the matter in person","meaning":"親身商討此事","examples":[{"en":"I hope to discuss the matter in person.","zh":"本人希望親身商討此事。"},{"en":"To discuss the matter in person means to talk about the issue face to face rather than only by message or email.","zh":"「親身商討此事」指面對面談論這個問題，而不是只用訊息或電郵溝通。"},{"en":"The manager invited the employee to discuss the matter in person after reading the application.","zh":"經理閱讀申請後，邀請員工親身商討此事。"},{"en":"Discussing the matter in person can make complicated details easier to explain.","zh":"親身商討此事可以令複雜細節更容易解釋。"},{"en":"This phrase is useful when a topic is important enough to require direct conversation.","zh":"當一個議題重要到需要直接對話時，這個說法很有用。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"look forward to your guidance","meaning":"期待你的指導","examples":[{"en":"I look forward to your guidance.","zh":"本人期待你的指導。"},{"en":"“I look forward to your guidance” is a polite closing phrase showing that the writer expects and values the reader’s advice.","zh":"“I look forward to your guidance” 是有禮的結尾語，表示作者期待並重視讀者的建議。"},{"en":"I look forward to your guidance on how to prepare the final report.","zh":"本人期待你就如何準備最終報告給予指導。"},{"en":"This phrase is suitable when writing to a supervisor, teacher, or manager.","zh":"這個說法適合寫給上司、老師或經理。"},{"en":"It sounds respectful because it recognises the reader’s experience or authority.","zh":"它聽起來有禮，因為它承認讀者的經驗或權威。"}],"source":"2020 Q4.pdf","sourcePage":15},{"front":"Yours sincerely","meaning":"謹啟","examples":[{"en":"Yours sincerely, Chris Wong.","zh":"Chris Wong 謹啟。"},{"en":"“Yours sincerely” is a formal closing used at the end of a letter when the writer knows the recipient’s name.","zh":"“Yours sincerely” 是在知道收件人姓名時，用於信件結尾的正式結語。"},{"en":"Yours sincerely, Amy Chan.","zh":"Amy Chan 謹啟。"},{"en":"In a job application letter, “Yours sincerely” sounds polite and professional.","zh":"在求職申請信中，“Yours sincerely” 聽起來有禮而專業。"},{"en":"The writer’s name usually appears after “Yours sincerely” to show who sent the letter.","zh":"作者姓名通常放在 “Yours sincerely” 之後，以顯示寄信人身份。"}],"source":"2020 Q4.pdf","sourcePage":16}],"dse/writing/part-b/2020/Q5":[{"front":"making room at","meaning":"為……騰出位置","examples":[{"en":"The proposal argues for making room at the Games for Dragon Boat Racing.","zh":"這份建議書主張在奧運會中為龍舟競賽騰出位置。"},{"en":"Making room at an event means creating space in its programme for something new.","zh":"在活動中為某事騰出位置，意思是在項目安排中為新事物創造空間。"},{"en":"A school fair may make room at its schedule for a student music performance.","zh":"學校嘉年華可能在時間表中為學生音樂表演騰出位置。"},{"en":"Organisers make room at a competition when a new activity attracts strong public interest.","zh":"當一項新活動吸引大量公眾興趣，主辦者會在比賽中為它騰出位置。"},{"en":"Making room at the Games would add Dragon Boat Racing without weakening the Olympic spirit.","zh":"在奧運會中為龍舟競賽騰出位置，會增加新項目而不削弱奧運精神。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"a proposal to include","meaning":"建議納入……","examples":[{"en":"This is a proposal to include Dragon Boat Racing in the Olympic Games.","zh":"這是一份建議把龍舟競賽納入奧運會的建議書。"},{"en":"A proposal to include something is a formal suggestion that it should be added.","zh":"建議納入某事，是正式提出應把它加入其中。"},{"en":"A student council may write a proposal to include healthier food in the school canteen.","zh":"學生會可能撰寫建議，要求把更健康的食物納入學校飯堂。"},{"en":"If many people support an activity, leaders may consider a proposal to include it in the programme.","zh":"如果很多人支持一項活動，領導者可能會考慮把它納入項目安排。"},{"en":"A proposal to include a new sport should explain why it is useful, fair, and practical.","zh":"建議納入一項新運動時，應解釋它為何有用、公平和可行。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"Dragon Boat Racing","meaning":"龍舟競賽","examples":[{"en":"Dragon Boat Racing should be included in future Olympic Games.","zh":"龍舟競賽應該被納入未來的奧運會。"},{"en":"Dragon Boat Racing is a team water sport in which paddlers move a long boat together to a drumbeat.","zh":"龍舟競賽是一項團隊水上運動，划手隨鼓聲一起划動長船。"},{"en":"At a school festival, students may join Dragon Boat Racing to learn timing and teamwork.","zh":"在學校節日中，學生可能參加龍舟競賽，以學習節奏和團隊合作。"},{"en":"Dragon Boat Racing becomes exciting because every paddler must move at the same rhythm.","zh":"龍舟競賽令人興奮，因為每位划手都必須按同一節奏前進。"},{"en":"Dragon Boat Racing is not only fast; it also shows culture, discipline, and cooperation.","zh":"龍舟競賽不只是快速；它也展現文化、紀律和合作。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"Dear President","meaning":"尊敬的主席","examples":[{"en":"The letter begins with Dear President.","zh":"這封信以「尊敬的主席」開始。"},{"en":"Dear President is a formal greeting used when writing respectfully to a president or chairperson.","zh":"「尊敬的主席」是寫信給主席或會長時使用的正式問候語。"},{"en":"A student may write Dear President at the start of a letter to a club president.","zh":"學生寫信給學會主席時，可能在開首寫「尊敬的主席」。"},{"en":"Using Dear President shows that the writer knows the reader’s position and wants to sound polite.","zh":"使用「尊敬的主席」表示作者知道讀者的職位，並希望語氣禮貌。"},{"en":"Dear President is suitable for a formal letter, not a casual message to a friend.","zh":"「尊敬的主席」適合正式書信，而不是給朋友的隨意訊息。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"in response to","meaning":"回應……","examples":[{"en":"I am writing in response to the IOC’s invitation.","zh":"我寫信是為了回應國際奧委會的邀請。"},{"en":"In response to something means because of it, or as an answer to it.","zh":"回應某事，意思是因為它而作出回答或行動。"},{"en":"A parent may call the school in response to a teacher’s note.","zh":"家長可能會回應老師的便條而致電學校。"},{"en":"In response to heavy traffic, the city may add more buses.","zh":"為回應嚴重交通擠塞，城市可能增加巴士班次。"},{"en":"A good response should deal directly with the question or request that came first.","zh":"好的回應應直接處理先前提出的問題或要求。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"the IOC’s invitation","meaning":"國際奧委會的邀請","examples":[{"en":"The writer responds to the IOC’s invitation to suggest sports.","zh":"作者回應國際奧委會邀請人們建議運動項目。"},{"en":"The IOC’s invitation means the International Olympic Committee’s request for people to give suggestions.","zh":"國際奧委會的邀請，意思是國際奧林匹克委員會要求人們提出建議。"},{"en":"A school’s invitation may ask students to suggest new activities for sports day.","zh":"學校的邀請可能要求學生為運動會建議新活動。"},{"en":"When people receive the IOC’s invitation, they can explain which sport deserves attention.","zh":"當人們收到國際奧委會的邀請，他們可以解釋哪項運動值得關注。"},{"en":"The IOC’s invitation gives ordinary supporters a chance to join the discussion.","zh":"國際奧委會的邀請給普通支持者一個參與討論的機會。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"suggest sports for","meaning":"為……建議運動項目","examples":[{"en":"The IOC invited people to suggest sports for future Olympic Games.","zh":"國際奧委會邀請人們為未來的奧運會建議運動項目。"},{"en":"To suggest sports for an event means to name possible sports that could be added.","zh":"為某活動建議運動項目，意思是提出可能加入的運動。"},{"en":"Students may suggest sports for a school tournament, such as badminton or basketball.","zh":"學生可能為學校比賽建議運動項目，例如羽毛球或籃球。"},{"en":"Organisers ask people to suggest sports for a programme when they want fresh ideas.","zh":"當主辦者想要新想法時，會請人們為項目安排建議運動。"},{"en":"When suggesting sports for the Olympics, people should consider fairness, safety, and audience appeal.","zh":"為奧運會建議運動項目時，人們應考慮公平、安全和觀眾吸引力。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"future Olympic Games","meaning":"未來的奧運會","examples":[{"en":"Dragon Boat Racing is suggested for future Olympic Games.","zh":"龍舟競賽被建議納入未來的奧運會。"},{"en":"Future Olympic Games means Olympic Games that will take place in later years.","zh":"未來的奧運會，是指將來年份舉行的奧運會。"},{"en":"Young athletes train hard because they hope to compete in future Olympic Games.","zh":"年輕運動員努力訓練，因為他們希望參加未來的奧運會。"},{"en":"If a sport becomes more popular worldwide, it may be considered for future Olympic Games.","zh":"如果一項運動在世界各地更受歡迎，它可能被考慮納入未來的奧運會。"},{"en":"Thinking about future Olympic Games helps the IOC plan for younger audiences.","zh":"思考未來的奧運會，有助國際奧委會為年輕觀眾作規劃。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"for better or worse","meaning":"不論好壞；無論如何","examples":[{"en":"For better or worse, the Olympic programme must change with the times.","zh":"不論好壞，奧運項目安排都必須與時並進。"},{"en":"For better or worse means whether the result is good or bad, the situation is real and must be accepted.","zh":"不論好壞，意思是不管結果是好是壞，情況已經存在，必須接受。"},{"en":"For better or worse, smartphones have changed how students learn and communicate.","zh":"不論好壞，智能手機已改變學生學習和溝通的方式。"},{"en":"When society changes, schools must respond, for better or worse.","zh":"當社會改變，學校無論如何都必須回應。"},{"en":"This phrase often shows that change has both benefits and risks.","zh":"這個短語常表示改變同時有好處和風險。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"the Olympic programme","meaning":"奧運項目安排","examples":[{"en":"The Olympic programme can no longer be judged only by tradition.","zh":"奧運項目安排不能再只以傳統來判斷。"},{"en":"The Olympic programme is the list and arrangement of sports and events in the Olympics.","zh":"奧運項目安排，是指奧運會中的運動和賽事清單及安排。"},{"en":"Adding a new event to a school sports day changes the school’s programme.","zh":"在學校運動日加入新項目，會改變學校的項目安排。"},{"en":"If the Olympic programme becomes too old-fashioned, young viewers may lose interest.","zh":"如果奧運項目安排變得太守舊，年輕觀眾可能失去興趣。"},{"en":"A strong Olympic programme should respect history while making space for new excellence.","zh":"強大的奧運項目安排應尊重歷史，同時為新的卓越表現留出空間。"}],"source":"2020 Q5.pdf","sourcePage":1},{"front":"can no longer be judged only by","meaning":"不能再只以……判斷","examples":[{"en":"The Olympic programme can no longer be judged only by tradition.","zh":"奧運項目安排不能再只以傳統來判斷。"},{"en":"If something can no longer be judged only by one factor, other factors must also be considered.","zh":"如果某事不能再只以一個因素判斷，就必須考慮其他因素。"},{"en":"A student can no longer be judged only by exam marks if teamwork and creativity also matter.","zh":"如果團隊合作和創意也重要，學生就不能再只以考試分數判斷。"},{"en":"A restaurant can no longer be judged only by price when hygiene and service affect customers.","zh":"當衛生和服務影響顧客時，餐廳不能再只以價錢判斷。"},{"en":"The phrase helps show that an old standard is now too narrow.","zh":"這個短語幫助說明舊標準現在已經太狹窄。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"tradition","meaning":"傳統","examples":[{"en":"The Olympic Games must honour tradition while welcoming new sports.","zh":"奧運會必須尊重傳統，同時歡迎新運動。"},{"en":"Tradition means customs, beliefs, or practices passed down over time.","zh":"傳統是長時間流傳下來的習俗、信念或做法。"},{"en":"A family tradition may be eating together on the first day of the Lunar New Year.","zh":"家庭傳統可能是在農曆新年第一天一起吃飯。"},{"en":"Tradition can keep a community connected, but it may also need careful renewal.","zh":"傳統可以令社區保持連繫，但也可能需要小心更新。"},{"en":"Respecting tradition does not mean refusing every new idea.","zh":"尊重傳統並不等於拒絕每一個新想法。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"simultaneously","meaning":"同時","examples":[{"en":"The programme must simultaneously speak to young spectators and model equality.","zh":"項目安排必須同時打動年輕觀眾並示範平等。"},{"en":"Simultaneously means doing two or more things at the same time.","zh":"同時，意思是在同一時間做兩件或多件事。"},{"en":"A teacher may explain a word and simultaneously show a picture to help students understand.","zh":"老師可能解釋一個詞，同時展示圖片幫助學生理解。"},{"en":"If a city builds homes and improves transport simultaneously, daily life may become easier.","zh":"如果城市同時興建房屋和改善交通，日常生活可能變得更方便。"},{"en":"The word is useful when two aims happen together, not one after the other.","zh":"當兩個目標一起發生，而不是先後發生時，這個詞很有用。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"speak to young spectators","meaning":"打動年輕觀眾","examples":[{"en":"The Olympic programme must speak to young spectators.","zh":"奧運項目安排必須打動年輕觀眾。"},{"en":"To speak to young spectators means to attract, interest, and feel relevant to younger viewers.","zh":"打動年輕觀眾，意思是吸引年輕觀眾、令他們感興趣並覺得相關。"},{"en":"A school event speaks to young spectators when it includes music, teamwork, and clear rules.","zh":"當學校活動包括音樂、團隊合作和清晰規則時，就能打動年輕觀眾。"},{"en":"If a sport is too slow or confusing, it may fail to speak to young spectators.","zh":"如果一項運動太慢或太難明，它可能無法打動年輕觀眾。"},{"en":"Dragon Boat Racing can speak to young spectators because it is fast, visual, and social.","zh":"龍舟競賽可以打動年輕觀眾，因為它快速、具視覺效果和社交性。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"model equality","meaning":"示範平等","examples":[{"en":"The Games should model equality through inclusive events.","zh":"奧運會應透過包容性賽事示範平等。"},{"en":"To model equality means to show fairness in a way that others can see and learn from.","zh":"示範平等，意思是以別人能看見和學習的方式展現公平。"},{"en":"A classroom models equality when every student has a chance to speak.","zh":"當每位學生都有發言機會，課室就在示範平等。"},{"en":"Sports can model equality when rules protect both stronger and weaker participants fairly.","zh":"當規則公平保護較強和較弱的參加者時，運動就能示範平等。"},{"en":"Mixed-team racing can model equality because men and women work towards one result.","zh":"男女混合賽可以示範平等，因為男性和女性朝同一結果努力。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"attract attention","meaning":"吸引注意","examples":[{"en":"The Games must attract attention in a crowded media landscape.","zh":"奧運會必須在擁擠的媒體環境中吸引注意。"},{"en":"To attract attention means to make people notice and become interested.","zh":"吸引注意，意思是令人留意並產生興趣。"},{"en":"A colourful poster can attract attention at a school noticeboard.","zh":"色彩鮮明的海報可以在學校告示板上吸引注意。"},{"en":"Exciting races attract attention because people want to know who will win.","zh":"刺激的比賽會吸引注意，因為人們想知道誰會勝出。"},{"en":"A sport must attract attention without becoming shallow or disrespectful.","zh":"一項運動必須吸引注意，但不能變得膚淺或不莊重。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"a crowded media landscape","meaning":"擁擠的媒體環境","examples":[{"en":"The Olympics compete for attention in a crowded media landscape.","zh":"奧運會在擁擠的媒體環境中爭取注意。"},{"en":"A crowded media landscape means there are many platforms, programmes, and messages fighting for people’s attention.","zh":"擁擠的媒體環境，是指許多平台、節目和訊息都在爭奪人們的注意。"},{"en":"Students live in a crowded media landscape when videos, games, and news all appear on their phones.","zh":"當影片、遊戲和新聞都出現在手機上，學生就生活在擁擠的媒體環境中。"},{"en":"In a crowded media landscape, boring events may be ignored quickly.","zh":"在擁擠的媒體環境中，沉悶的活動可能很快被忽略。"},{"en":"Clear stories and exciting images help sports survive in a crowded media landscape.","zh":"清晰故事和刺激影像能幫助運動在擁擠的媒體環境中生存。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"make someone consider","meaning":"令某人考慮","examples":[{"en":"This has made the IOC consider new events.","zh":"這令國際奧委會考慮新項目。"},{"en":"To make someone consider something means to cause them to think seriously about it.","zh":"令某人考慮某事，意思是使他們認真思考它。"},{"en":"A poor test result may make a student consider changing study habits.","zh":"一次差的測驗成績可能令學生考慮改變學習習慣。"},{"en":"Strong public support can make leaders consider a new policy.","zh":"強大的公眾支持可以令領導者考慮新政策。"},{"en":"Dragon Boat Racing’s popularity may make the IOC consider it more carefully.","zh":"龍舟競賽的受歡迎程度可能令國際奧委會更仔細考慮它。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"refresh the Games","meaning":"為奧運注入新氣象","examples":[{"en":"New events can refresh the Games.","zh":"新項目可以為奧運注入新氣象。"},{"en":"To refresh the Games means to make the Olympics feel new, lively, and relevant again.","zh":"為奧運注入新氣象，意思是令奧運再次感覺新鮮、有活力和有時代感。"},{"en":"A school can refresh sports day by adding events that more students enjoy.","zh":"學校可以加入更多學生喜歡的項目，為運動日注入新氣象。"},{"en":"If younger audiences lose interest, new formats may refresh the Games.","zh":"如果年輕觀眾失去興趣，新賽制可能為奧運注入新氣象。"},{"en":"Refreshing the Games should add energy without losing Olympic dignity.","zh":"為奧運注入新氣象應增加活力，而不失去奧運莊嚴性。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"without weakening","meaning":"而不削弱","examples":[{"en":"New events can refresh the Games without weakening their dignity.","zh":"新項目可以為奧運注入新氣象，而不削弱其莊嚴性。"},{"en":"Without weakening something means changing it while keeping its strength or value.","zh":"而不削弱某事，意思是改變它但保留其力量或價值。"},{"en":"A teacher can make lessons fun without weakening academic standards.","zh":"老師可以令課堂有趣，而不削弱學術標準。"},{"en":"A city can welcome tourists without weakening local traditions if residents stay involved.","zh":"如果居民保持參與，城市可以歡迎遊客而不削弱本地傳統。"},{"en":"Dragon Boat Racing could modernise the Olympics without weakening their identity.","zh":"龍舟競賽可以令奧運現代化，而不削弱其身份。"}],"source":"2020 Q5.pdf","sourcePage":2},{"front":"dignity","meaning":"莊嚴性；尊嚴","examples":[{"en":"The IOC must protect the dignity of the Games.","zh":"國際奧委會必須保護奧運會的莊嚴性。"},{"en":"Dignity means seriousness, respect, and worth that should not be treated cheaply.","zh":"莊嚴性或尊嚴，是指不應被輕率對待的嚴肅、尊重和價值。"},{"en":"A school ceremony has dignity when students behave respectfully.","zh":"當學生表現尊重時，學校典禮就有莊嚴性。"},{"en":"If a competition becomes only a show for attention, it may lose dignity.","zh":"如果比賽只變成吸引注意的表演，它可能失去莊嚴性。"},{"en":"Olympic dignity can be protected while still welcoming exciting new sports.","zh":"奧運莊嚴性可以被保護，同時仍歡迎刺激的新運動。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"strongly believe that","meaning":"堅信","examples":[{"en":"I strongly believe that Dragon Boat Racing should be included.","zh":"我堅信龍舟競賽應該被納入。"},{"en":"Strongly believe that means to be very sure about an opinion.","zh":"堅信，意思是對某個看法非常肯定。"},{"en":"I strongly believe that students learn better when examples are clear.","zh":"我堅信當例子清楚時，學生學得更好。"},{"en":"People may strongly believe that public parks should remain open to everyone.","zh":"人們可能堅信公共公園應繼續向所有人開放。"},{"en":"This phrase is useful when a writer wants to state a firm view respectfully.","zh":"當作者想有禮貌地表達堅定看法時，這個短語很有用。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"should be included","meaning":"應該被納入","examples":[{"en":"Dragon Boat Racing should be included in the Olympic Games.","zh":"龍舟競賽應該被納入奧運會。"},{"en":"Should be included means something deserves to be added or counted as part of a group.","zh":"應該被納入，意思是某事值得被加入或算作其中一部分。"},{"en":"Healthy food should be included in a school lunch menu.","zh":"健康食物應該被納入學校午餐餐單。"},{"en":"If a topic affects many people, it should be included in the discussion.","zh":"如果一個議題影響很多人，它應該被納入討論。"},{"en":"A sport should be included only when it is fair, popular, and well organised.","zh":"一項運動只有在公平、受歡迎和組織完善時，才應該被納入。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"youthful in spirit","meaning":"精神上充滿青春活力","examples":[{"en":"Dragon Boat Racing is youthful in spirit.","zh":"龍舟競賽精神上充滿青春活力。"},{"en":"Youthful in spirit means full of energy, freshness, and openness to new ideas.","zh":"精神上充滿青春活力，意思是充滿能量、新鮮感和接受新想法的態度。"},{"en":"A teacher can be youthful in spirit if they enjoy learning from students.","zh":"如果老師樂於向學生學習，也可以在精神上充滿青春活力。"},{"en":"An event feels youthful in spirit when it is active, social, and hopeful.","zh":"當活動活躍、具社交性和充滿希望時，就顯得精神上充滿青春活力。"},{"en":"Dragon Boat Racing is youthful in spirit because it moves quickly and depends on shared energy.","zh":"龍舟競賽精神上充滿青春活力，因為它節奏快並依靠共同力量。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"naturally inclusive","meaning":"自然具包容性","examples":[{"en":"Dragon Boat Racing is naturally inclusive.","zh":"龍舟競賽自然具包容性。"},{"en":"Naturally inclusive means it easily allows different people to take part together.","zh":"自然具包容性，意思是它容易讓不同的人一起參與。"},{"en":"A group project is naturally inclusive when every student has a useful role.","zh":"當每位學生都有有用角色，小組 project 就自然具包容性。"},{"en":"Dragon Boat Racing is naturally inclusive because paddlers, a drummer, and a steersperson all matter.","zh":"龍舟競賽自然具包容性，因為划手、鼓手和舵手都很重要。"},{"en":"A naturally inclusive sport helps people feel they belong, not just watch from outside.","zh":"自然具包容性的運動幫助人感到自己屬於其中，而不只是旁觀。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"made for powerful broadcasting","meaning":"適合製作具震撼力的轉播","examples":[{"en":"Dragon Boat Racing is made for powerful broadcasting.","zh":"龍舟競賽適合製作具震撼力的轉播。"},{"en":"Made for powerful broadcasting means a sport looks and sounds strong on television or online.","zh":"適合製作具震撼力的轉播，意思是某項運動在電視或網上看起來和聽起來都很有力量。"},{"en":"A short race with clear action is made for powerful broadcasting because viewers can follow it easily.","zh":"動作清晰的短途比賽適合製作具震撼力的轉播，因為觀眾容易跟上。"},{"en":"Bright boats, drumbeats, and close finishes make Dragon Boat Racing suitable for powerful broadcasting.","zh":"醒目的船、鼓聲和接近的衝線，使龍舟競賽適合製作具震撼力的轉播。"},{"en":"A sport made for powerful broadcasting can attract people even if they know little about its rules.","zh":"適合製作具震撼力轉播的運動，即使觀眾不太懂規則，也能吸引他們。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"appeal to young people","meaning":"吸引年輕人","examples":[{"en":"Dragon Boat Racing would appeal to young people.","zh":"龍舟競賽會吸引年輕人。"},{"en":"To appeal to young people means to attract their interest and feel exciting or relevant to them.","zh":"吸引年輕人，意思是引起他們的興趣，並令他們覺得刺激或相關。"},{"en":"A school club may appeal to young people if it is active, friendly, and creative.","zh":"如果學校學會活躍、友善和有創意，可能會吸引年輕人。"},{"en":"Short, visual sports appeal to young people because they are easy to follow online.","zh":"短而具視覺效果的運動吸引年輕人，因為它們在網上容易觀看。"},{"en":"Dragon Boat Racing can appeal to young people without losing seriousness.","zh":"龍舟競賽可以吸引年輕人，而不失去嚴肅性。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"turn sport into shared energy","meaning":"把運動變成共同的力量","examples":[{"en":"Dragon Boat Racing turns sport into shared energy.","zh":"龍舟競賽把運動變成共同的力量。"},{"en":"To turn sport into shared energy means to make athletic effort feel collective and powerful.","zh":"把運動變成共同的力量，意思是令體育努力變得集體而有力量。"},{"en":"A cheering crowd can turn a school match into shared energy.","zh":"歡呼的觀眾可以把學校比賽變成共同的力量。"},{"en":"When a whole crew paddles together, individual effort becomes shared energy.","zh":"當整隊人一起划槳，個人努力就變成共同的力量。"},{"en":"This phrase shows that sport can connect people, not only test individuals.","zh":"這個短語顯示運動可以連結人，而不只是考驗個人。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"be drawn to","meaning":"被……吸引","examples":[{"en":"Many teenagers are drawn to fast and social activities.","zh":"許多青少年被快速和具社交性的活動吸引。"},{"en":"To be drawn to something means to feel attracted to it naturally.","zh":"被某事吸引，意思是自然地對它產生興趣。"},{"en":"Some students are drawn to music clubs because they enjoy performing with friends.","zh":"有些學生被音樂學會吸引，因為他們喜歡和朋友一起表演。"},{"en":"People may be drawn to a sport when it looks exciting and easy to understand.","zh":"當一項運動看起來刺激又容易理解，人們可能會被它吸引。"},{"en":"Teenagers may be drawn to Dragon Boat Racing because it combines speed, teamwork, and sound.","zh":"青少年可能被龍舟競賽吸引，因為它結合速度、團隊合作和聲音。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"fast, social and visually exciting","meaning":"快速、具社交性和視覺刺激","examples":[{"en":"Dragon boat racing is fast, social and visually exciting.","zh":"龍舟競賽快速、具社交性和視覺刺激。"},{"en":"Fast, social and visually exciting describes an activity that moves quickly, involves people, and looks interesting.","zh":"快速、具社交性和視覺刺激，是形容活動節奏快、涉及人群並且看起來有趣。"},{"en":"A school relay race can be fast, social and visually exciting for both runners and spectators.","zh":"學校接力賽對跑手和觀眾來說都可以快速、具社交性和視覺刺激。"},{"en":"Activities with speed, teamwork, and colourful movement often feel fast, social and visually exciting.","zh":"有速度、團隊合作和彩色動作的活動，通常快速、具社交性和視覺刺激。"},{"en":"This quality helps Dragon Boat Racing attract viewers who want action and connection.","zh":"這種特質幫助龍舟競賽吸引想看動作和連結的觀眾。"}],"source":"2020 Q5.pdf","sourcePage":3},{"front":"offer all three","meaning":"三者兼備","examples":[{"en":"Dragon boat racing offers all three qualities.","zh":"龍舟競賽三者兼備。"},{"en":"To offer all three means to provide the three qualities just mentioned.","zh":"三者兼備，意思是提供剛剛提到的三種特質。"},{"en":"A good school trip may offer all three: learning, fun, and safety.","zh":"一次好的學校旅行可能三者兼備：學習、樂趣和安全。"},{"en":"If an activity is exciting, simple, and meaningful, it offers all three things organisers want.","zh":"如果一項活動刺激、簡單和有意義，它就具備主辦者想要的三種特質。"},{"en":"Dragon Boat Racing offers all three qualities of speed, teamwork, and visual excitement.","zh":"龍舟競賽具備速度、團隊合作和視覺刺激這三種特質。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"short enough to","meaning":"短到足以……","examples":[{"en":"A race is short enough to hold attention.","zh":"一場比賽短到足以吸引注意力。"},{"en":"Short enough to do something means not too long, so a result can happen.","zh":"短到足以做某事，意思是不太長，所以能達到某種效果。"},{"en":"A video may be short enough to keep students focused before a lesson begins.","zh":"影片可能短到足以在課堂開始前讓學生保持專注。"},{"en":"If a speech is short enough to be remembered, listeners may take away its main point.","zh":"如果演講短到足以被記住，聽眾可能帶走其重點。"},{"en":"Dragon boat races are short enough to excite viewers without tiring them.","zh":"龍舟比賽短到足以令觀眾興奮，而不令他們疲倦。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"hold attention","meaning":"吸引注意力","examples":[{"en":"A dragon boat race is short enough to hold attention.","zh":"龍舟比賽短到足以吸引注意力。"},{"en":"To hold attention means to keep people interested so they continue watching or listening.","zh":"吸引注意力，意思是保持人們的興趣，令他們繼續觀看或聆聽。"},{"en":"A teacher uses real examples to hold attention during a difficult lesson.","zh":"老師在困難課堂中用真實例子吸引注意力。"},{"en":"Close competition can hold attention because the result is uncertain.","zh":"接近的競爭可以吸引注意力，因為結果不確定。"},{"en":"Dragon Boat Racing holds attention through rhythm, speed, and teamwork.","zh":"龍舟競賽透過節奏、速度和團隊合作吸引注意力。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"physical enough to","meaning":"體能要求足以……","examples":[{"en":"The sport is physical enough to command respect.","zh":"這項運動的體能要求足以令人尊重。"},{"en":"Physical enough to do something means demanding enough strength, effort, or movement to create that result.","zh":"體能要求足以做某事，意思是需要足夠力量、努力或動作去產生某種結果。"},{"en":"A hiking trip may be physical enough to challenge students safely.","zh":"遠足活動的體能要求可能足以安全地挑戰學生。"},{"en":"If a job is physical enough to cause tiredness, workers need rest and protection.","zh":"如果工作體能要求足以令人疲倦，工人就需要休息和保護。"},{"en":"Dragon Boat Racing is physical enough to show real athletic ability.","zh":"龍舟競賽的體能要求足以展現真正的運動能力。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"command respect","meaning":"令人尊重","examples":[{"en":"The physical demands of the sport command respect.","zh":"這項運動的體能要求令人尊重。"},{"en":"To command respect means to deserve respect because something is difficult, serious, or impressive.","zh":"令人尊重，意思是因為困難、嚴肅或令人佩服而值得尊敬。"},{"en":"A nurse’s calm work during emergencies can command respect.","zh":"護士在緊急情況中冷靜工作，可以令人尊重。"},{"en":"Athletes command respect when they train hard and compete fairly.","zh":"運動員努力訓練並公平比賽時，會令人尊重。"},{"en":"Dragon Boat Racing commands respect because every race requires strength and discipline.","zh":"龍舟競賽令人尊重，因為每場比賽都需要力量和紀律。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"simple enough to understand instantly","meaning":"簡單到即時明白","examples":[{"en":"The race is simple enough to understand instantly.","zh":"這場比賽簡單到即時明白。"},{"en":"Simple enough to understand instantly means people can grasp the basic idea at once.","zh":"簡單到即時明白，意思是人們可以立刻掌握基本意思。"},{"en":"A game with one clear goal is simple enough to understand instantly.","zh":"只有一個清晰目標的遊戲，簡單到即時明白。"},{"en":"If instructions are simple enough to understand instantly, fewer students feel confused.","zh":"如果指示簡單到即時明白，較少學生會感到混亂。"},{"en":"Dragon Boat Racing is simple enough to understand instantly because the first boat to finish wins.","zh":"龍舟競賽簡單到即時明白，因為最先到達終點的船勝出。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"surge forward","meaning":"向前衝","examples":[{"en":"The boat surges forward during the race.","zh":"船在比賽中向前衝。"},{"en":"To surge forward means to move suddenly and powerfully ahead.","zh":"向前衝，意思是突然有力地向前移動。"},{"en":"A bus may surge forward when the driver presses the accelerator too hard.","zh":"當司機太用力踩油門，巴士可能會向前衝。"},{"en":"In a race, a team may surge forward when all members increase their effort together.","zh":"在比賽中，當所有隊員一起加大努力，隊伍可能向前衝。"},{"en":"The phrase suggests strong movement, not slow or gentle progress.","zh":"這個短語表示強而有力的移動，不是緩慢或溫和的前進。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"strike the water together","meaning":"一起划水","examples":[{"en":"The paddlers strike the water together.","zh":"划手一起划水。"},{"en":"To strike the water together means paddlers hit or pull the water at the same time with their paddles.","zh":"一起划水，意思是划手用槳同時拍入或拉動水面。"},{"en":"Beginners must practise until they can strike the water together smoothly.","zh":"初學者必須練習，直到能順暢地一起划水。"},{"en":"If paddlers fail to strike the water together, the boat may lose speed.","zh":"如果划手不能一起划水，船可能會失去速度。"},{"en":"This action shows why timing is so important in Dragon Boat Racing.","zh":"這個動作顯示為何配合時機在龍舟競賽中如此重要。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"drive the rhythm","meaning":"帶動節奏","examples":[{"en":"The drummer drives the rhythm of the crew.","zh":"鼓手帶動整隊的節奏。"},{"en":"To drive the rhythm means to lead and control the beat that others follow.","zh":"帶動節奏，意思是引領和控制其他人跟隨的拍子。"},{"en":"In a music class, a drum can drive the rhythm so singers enter together.","zh":"在音樂課中，鼓可以帶動節奏，讓歌手一起進入。"},{"en":"If the drummer drives the rhythm clearly, paddlers can move as one.","zh":"如果鼓手清楚帶動節奏，划手就能動作一致。"},{"en":"Dragon Boat Racing needs someone to drive the rhythm because teamwork depends on timing.","zh":"龍舟競賽需要有人帶動節奏，因為團隊合作取決於時機配合。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"be decided by inches","meaning":"以些微距離分勝負","examples":[{"en":"The finish may be decided by inches.","zh":"終點可能以些微距離分勝負。"},{"en":"Be decided by inches means the result is extremely close, with only a tiny distance between competitors.","zh":"以些微距離分勝負，意思是結果非常接近，競爭者之間只有極小距離。"},{"en":"A running race may be decided by inches when two students reach the line almost together.","zh":"當兩名學生幾乎同時到達終點，跑步比賽可能以些微距離分勝負。"},{"en":"Close races are exciting because the winner may be decided by inches.","zh":"接近的比賽令人興奮，因為勝負可能只差些微距離。"},{"en":"This phrase shows that small differences in timing can change the whole result.","zh":"這個短語顯示時機上的小差異可以改變整個結果。"}],"source":"2020 Q5.pdf","sourcePage":4},{"front":"unlike sports whose rules","meaning":"不像那些規則……的運動","examples":[{"en":"Unlike sports whose rules take years to appreciate, dragon boat is easy to enjoy.","zh":"不像那些規則需要多年才懂得欣賞的運動，龍舟容易享受。"},{"en":"Unlike sports whose rules are difficult, some games can be understood after one look.","zh":"不像那些規則困難的運動，有些遊戲看一眼就能明白。"},{"en":"Unlike sports whose rules confuse beginners, a simple race lets spectators follow the result quickly.","zh":"不像那些規則令初學者困惑的運動，簡單的比賽讓觀眾快速跟上結果。"},{"en":"If rules are too complicated, new viewers may stop watching before they understand the sport.","zh":"如果規則太複雜，新觀眾可能在理解前就停止觀看。"},{"en":"This phrase contrasts dragon boat racing with sports that require long study.","zh":"這個短語把龍舟競賽與需要長時間學習的運動作對比。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"take years to appreciate","meaning":"需要多年才懂得欣賞","examples":[{"en":"Some sports have rules that take years to appreciate.","zh":"有些運動的規則需要多年才懂得欣賞。"},{"en":"If something takes years to appreciate, people need a long time to understand its value.","zh":"如果某事需要多年才懂得欣賞，人們需要很長時間才理解其價值。"},{"en":"Classical music may take years to appreciate if listeners are new to it.","zh":"如果聽眾剛接觸古典音樂，可能需要多年才懂得欣賞。"},{"en":"A complex strategy game can take years to appreciate because each move has hidden meaning.","zh":"複雜的策略遊戲可能需要多年才懂得欣賞，因為每一步都有隱藏意義。"},{"en":"Dragon Boat Racing does not take years to appreciate because its basic action is clear.","zh":"龍舟競賽不需要多年才懂得欣賞，因為其基本動作清楚。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"the moment one sees it","meaning":"一看見就","examples":[{"en":"Dragon boat can be enjoyed the moment one sees it.","zh":"龍舟一看見就可以享受。"},{"en":"The moment one sees it means immediately after seeing it for the first time.","zh":"一看見就，意思是第一次看見後立即發生。"},{"en":"A child may understand a picture book the moment one sees it because the drawings tell the story.","zh":"孩子可能一看見圖畫書就明白，因為圖畫在說故事。"},{"en":"When a sport is visually clear, people can enjoy it the moment they see it.","zh":"當一項運動視覺上清楚，人們一看見就能享受。"},{"en":"This phrase shows that Dragon Boat Racing has instant visual appeal.","zh":"這個短語顯示龍舟競賽有即時的視覺吸引力。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, the sport teaches teamwork.","zh":"更重要的是，這項運動教導團隊合作。"},{"en":"More importantly is used to introduce a point that matters even more than the previous one.","zh":"更重要的是，用來引出比前一點更重要的內容。"},{"en":"The trip was fun; more importantly, students learned to care for one another.","zh":"這次旅行很有趣；更重要的是，學生學會關心彼此。"},{"en":"A phone may be cheap, but more importantly, it must be safe and reliable.","zh":"一部手機可能便宜，但更重要的是，它必須安全可靠。"},{"en":"This phrase helps a writer move from an interesting point to a stronger reason.","zh":"這個短語幫助作者由有趣的一點轉向更強的理由。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"give young athletes a rare lesson in","meaning":"給年輕運動員上了難得的一課","examples":[{"en":"Dragon Boat Racing gives young athletes a rare lesson in teamwork.","zh":"龍舟競賽給年輕運動員上了難得的團隊合作一課。"},{"en":"To give someone a rare lesson in something means to teach them something valuable that they do not often experience.","zh":"給某人上了難得的一課，意思是教他們平時不常經歷但很有價值的事情。"},{"en":"Volunteering can give students a rare lesson in responsibility.","zh":"做義工可以給學生上了難得的責任一課。"},{"en":"Losing a close match may give young athletes a rare lesson in humility.","zh":"輸掉一場接近的比賽，可能給年輕運動員上了難得的謙遜一課。"},{"en":"Dragon Boat Racing gives young athletes a rare lesson in moving as one team.","zh":"龍舟競賽給年輕運動員上了難得的一課：如何像一隊人一樣前進。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"teamwork","meaning":"團隊合作","examples":[{"en":"Dragon Boat Racing gives young athletes a lesson in teamwork.","zh":"龍舟競賽給年輕運動員上一課團隊合作。"},{"en":"Teamwork means people working together to reach a shared goal.","zh":"團隊合作，意思是人們一起努力達成共同目標。"},{"en":"Students use teamwork when they divide tasks fairly for a group project.","zh":"學生在小組 project 中公平分工時，就是使用團隊合作。"},{"en":"Poor teamwork can cause delays because everyone moves in different directions.","zh":"差的團隊合作可能造成延誤，因為每個人都朝不同方向行動。"},{"en":"Dragon Boat Racing shows teamwork clearly because no paddler can win alone.","zh":"龍舟競賽清楚展現團隊合作，因為沒有划手可以單獨勝出。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"a school crew","meaning":"學校隊伍","examples":[{"en":"A school crew in Hong Kong can train beginners quickly.","zh":"香港的一支學校隊伍可以快速訓練初學者。"},{"en":"A school crew is a team of students who practise and compete together, often in rowing or dragon boat racing.","zh":"學校隊伍，是指一起練習和比賽的一隊學生，常用於划艇或龍舟競賽。"},{"en":"A school crew may meet after lessons to practise timing and strength.","zh":"學校隊伍可能放學後集合，練習節奏和力量。"},{"en":"If a school crew has good guidance, new members can improve quickly.","zh":"如果學校隊伍有良好指導，新成員可以快速進步。"},{"en":"A school crew teaches students discipline because everyone depends on the group.","zh":"學校隊伍教導學生紀律，因為每個人都依靠團隊。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"a university team overseas","meaning":"海外大學隊伍","examples":[{"en":"A university team overseas can also train beginners quickly.","zh":"海外大學隊伍也可以快速訓練初學者。"},{"en":"A university team overseas is a college or university sports group in another country.","zh":"海外大學隊伍，是指另一個國家的大學或學院運動隊。"},{"en":"A university team overseas may welcome exchange students who want to try dragon boating.","zh":"海外大學隊伍可能歡迎想嘗試龍舟的交換生。"},{"en":"If a sport spreads internationally, a university team overseas can help more beginners learn it.","zh":"如果一項運動傳播到國際，海外大學隊伍可以幫助更多初學者學習。"},{"en":"This phrase shows that Dragon Boat Racing is not limited to one local community.","zh":"這個短語顯示龍舟競賽不限於單一本地社群。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"train beginners quickly","meaning":"快速訓練初學者","examples":[{"en":"A dragon boat team can train beginners quickly.","zh":"龍舟隊可以快速訓練初學者。"},{"en":"To train beginners quickly means to help new learners understand basic skills in a short time.","zh":"快速訓練初學者，意思是在短時間內幫助新學習者明白基本技能。"},{"en":"A swimming coach can train beginners quickly by teaching safety first.","zh":"游泳教練可以先教授安全知識，快速訓練初學者。"},{"en":"Clear rules and repeated practice help teams train beginners quickly.","zh":"清晰規則和反覆練習幫助隊伍快速訓練初學者。"},{"en":"Dragon Boat Racing can train beginners quickly because the basic action is simple but meaningful.","zh":"龍舟競賽可以快速訓練初學者，因為基本動作簡單但有意義。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"on enthusiasm alone","meaning":"單靠熱情","examples":[{"en":"No one can win on enthusiasm alone.","zh":"沒有人可以單靠熱情取勝。"},{"en":"On enthusiasm alone means using only excitement or passion, without enough skill, planning, or discipline.","zh":"單靠熱情，意思是只靠興奮或激情，而沒有足夠技能、計劃或紀律。"},{"en":"A student cannot pass an exam on enthusiasm alone if they never revise.","zh":"如果學生從不溫習，就不能單靠熱情通過考試。"},{"en":"A club may fail on enthusiasm alone when members have no clear plan.","zh":"當成員沒有清晰計劃，學會可能單靠熱情而失敗。"},{"en":"Dragon Boat Racing shows that passion matters, but timing and discipline matter too.","zh":"龍舟競賽顯示熱情重要，但配合時機和紀律也重要。"}],"source":"2020 Q5.pdf","sourcePage":5},{"front":"timing matters more than ego","meaning":"配合時機比自我更重要","examples":[{"en":"In dragon boat racing, timing matters more than ego.","zh":"在龍舟競賽中，配合時機比自我更重要。"},{"en":"Timing matters more than ego means doing things at the right moment is more important than showing off.","zh":"配合時機比自我更重要，意思是在正確時間行動比表現自己更重要。"},{"en":"In a group presentation, timing matters more than ego because everyone must speak in order.","zh":"在小組匯報中，配合時機比自我更重要，因為每個人都必須按次序發言。"},{"en":"If one paddler tries to stand out, the team’s timing may suffer.","zh":"如果一名划手想突出自己，隊伍的時機配合可能受影響。"},{"en":"This phrase teaches that cooperation is stronger than personal pride.","zh":"這個短語教人合作比個人驕傲更有力量。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"discipline matters more than display","meaning":"紀律比表現自己更重要","examples":[{"en":"In dragon boat racing, discipline matters more than display.","zh":"在龍舟競賽中，紀律比表現自己更重要。"},{"en":"Discipline matters more than display means steady control is more important than showing off.","zh":"紀律比表現自己更重要，意思是穩定控制比炫耀更重要。"},{"en":"In a choir, discipline matters more than display because singers must follow the conductor.","zh":"在合唱團中，紀律比表現自己更重要，因為歌手必須跟隨指揮。"},{"en":"A team loses rhythm when members care more about display than discipline.","zh":"當隊員更重視表現自己而不是紀律，隊伍就會失去節奏。"},{"en":"Dragon Boat Racing rewards disciplined teamwork, not flashy individual action.","zh":"龍舟競賽獎勵有紀律的團隊合作，而不是花巧的個人動作。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"in that sense","meaning":"從這個意義上說","examples":[{"en":"In that sense, dragon boat would not just entertain the young.","zh":"從這個意義上說，龍舟不只是娛樂年輕人。"},{"en":"In that sense means from that point of view or for that reason.","zh":"從這個意義上說，意思是從那個角度或基於那個原因來看。"},{"en":"A library gives students a quiet place to think; in that sense, it supports mental health too.","zh":"圖書館給學生安靜思考的地方；從這個意義上說，它也支持心理健康。"},{"en":"Sports teach patience and respect; in that sense, they are part of education.","zh":"運動教導耐性和尊重；從這個意義上說，它也是教育的一部分。"},{"en":"This phrase helps connect an example to a wider meaning.","zh":"這個短語幫助把例子連接到更廣泛的意義。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"not just entertain","meaning":"不只是娛樂","examples":[{"en":"Dragon boat would not just entertain the young.","zh":"龍舟不只是娛樂年輕人。"},{"en":"Not just entertain means something does more than provide fun; it also teaches or develops people.","zh":"不只是娛樂，意思是某事不只提供樂趣，還教導或培養人。"},{"en":"A school play does not just entertain students; it builds confidence and cooperation.","zh":"學校戲劇不只是娛樂學生；它建立信心和合作。"},{"en":"A museum does not just entertain visitors if it also explains history clearly.","zh":"如果博物館也清楚解釋歷史，它就不只是娛樂訪客。"},{"en":"Dragon Boat Racing does not just entertain because it teaches rhythm, discipline, and shared effort.","zh":"龍舟競賽不只是娛樂，因為它教導節奏、紀律和共同努力。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"collective excellence","meaning":"集體卓越","examples":[{"en":"The sport shows young people what collective excellence looks like.","zh":"這項運動向年輕人展示集體卓越是甚麼模樣。"},{"en":"Collective excellence means high achievement created by a group working well together.","zh":"集體卓越，意思是由一群人良好合作所創造的高水平成就。"},{"en":"A school orchestra shows collective excellence when every player follows the same piece carefully.","zh":"當學校管弦樂團每位樂手都細心跟隨同一樂曲時，就展現集體卓越。"},{"en":"Collective excellence happens when teamwork turns many small efforts into one strong result.","zh":"當團隊合作把許多小努力變成一個強大結果時，集體卓越就出現。"},{"en":"Dragon Boat Racing is a clear image of collective excellence on water.","zh":"龍舟競賽是水上集體卓越的清晰畫面。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"what something looks like","meaning":"……是甚麼模樣","examples":[{"en":"The sport shows what collective excellence looks like.","zh":"這項運動展示集體卓越是甚麼模樣。"},{"en":"What something looks like means what it appears to be in real life or in practice.","zh":"某事是甚麼模樣，意思是它在現實或實踐中看起來怎樣。"},{"en":"A teacher may show students what good teamwork looks like by giving them a clear group task.","zh":"老師可以透過清晰的小組任務，向學生展示良好團隊合作是甚麼模樣。"},{"en":"Photos can show what flood damage looks like better than numbers alone.","zh":"照片比單靠數字更能展示水災破壞是甚麼模樣。"},{"en":"Dragon Boat Racing shows what unity looks like when people move together.","zh":"龍舟競賽展示當人們一起前進時，團結是甚麼模樣。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"exceptionally well suited to","meaning":"極為適合","examples":[{"en":"Dragon Boat Racing is exceptionally well suited to promoting gender equality.","zh":"龍舟競賽極為適合推動性別平等。"},{"en":"Exceptionally well suited to something means especially appropriate or useful for that purpose.","zh":"極為適合某事，意思是特別適合或有助於某個目的。"},{"en":"Group discussion is exceptionally well suited to teaching students how to listen.","zh":"小組討論極為適合教學生如何聆聽。"},{"en":"A small park is exceptionally well suited to community exercise if many residents live nearby.","zh":"如果附近住著許多居民，小公園極為適合社區運動。"},{"en":"Dragon Boat Racing is exceptionally well suited to mixed teams because everyone shares one rhythm.","zh":"龍舟競賽極為適合男女混合隊，因為每個人共享同一節奏。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"promote gender equality","meaning":"推動性別平等","examples":[{"en":"Dragon Boat Racing can promote gender equality.","zh":"龍舟競賽可以推動性別平等。"},{"en":"To promote gender equality means to support fair treatment and equal respect for men and women.","zh":"推動性別平等，意思是支持男性和女性受到公平對待和同等尊重。"},{"en":"A school can promote gender equality by encouraging girls and boys to join the same clubs.","zh":"學校可以鼓勵女生和男生參加同一學會，以推動性別平等。"},{"en":"Mixed teams promote gender equality when every member has a real role.","zh":"當每位成員都有真實角色，男女混合隊就能推動性別平等。"},{"en":"Dragon Boat Racing can promote gender equality because cooperation matters more than display.","zh":"龍舟競賽可以推動性別平等，因為合作比表現自己更重要。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"redesign formats","meaning":"重新設計賽制","examples":[{"en":"Some sports have had to redesign formats to include women more fully.","zh":"有些運動不得不重新設計賽制，以更全面地納入女性。"},{"en":"To redesign formats means to change the structure or rules of an event.","zh":"重新設計賽制，意思是改變活動的結構或規則。"},{"en":"A school may redesign formats for debates so quieter students can speak more easily.","zh":"學校可能重新設計辯論賽制，讓較安靜的學生更容易發言。"},{"en":"Sports redesign formats when old rules do not include everyone fairly.","zh":"當舊規則不能公平納入所有人，運動就會重新設計賽制。"},{"en":"Dragon Boat Racing may need fewer changes because mixed participation already fits it well.","zh":"龍舟競賽可能需要較少改變，因為男女混合參與已經很適合它。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"include women more fully","meaning":"更全面地納入女性","examples":[{"en":"Some sports changed their formats to include women more fully.","zh":"有些運動改變賽制，以更全面地納入女性。"},{"en":"To include women more fully means to give women real and equal opportunities to take part.","zh":"更全面地納入女性，意思是給女性真實和平等的參與機會。"},{"en":"A school club includes women more fully when girls can lead, compete, and make decisions.","zh":"當女生可以領導、比賽和作決定時，學校學會就更全面地納入女性。"},{"en":"If women are only invited to watch, they are not included more fully.","zh":"如果女性只是被邀請觀看，她們就沒有被更全面地納入。"},{"en":"Mixed dragon boat crews can include women more fully by making their roles central to the result.","zh":"男女混合龍舟隊可以透過令女性角色對結果重要，更全面地納入女性。"}],"source":"2020 Q5.pdf","sourcePage":6},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"Dragon boat, by contrast, already lends itself to mixed participation.","zh":"相比之下，龍舟本身已經適合男女混合參與。"},{"en":"By contrast is used to show a clear difference from the point just mentioned.","zh":"相比之下，用來顯示與剛才一點的清楚差異。"},{"en":"Some students prefer silent reading; by contrast, others learn better through discussion.","zh":"有些學生喜歡安靜閱讀；相比之下，其他學生透過討論學得更好。"},{"en":"A sport with separate events may divide athletes; by contrast, mixed racing brings them together.","zh":"分開項目的運動可能把運動員分開；相比之下，男女混合賽把他們聚在一起。"},{"en":"This phrase helps a writer compare two situations clearly.","zh":"這個短語幫助作者清楚比較兩種情況。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"lend itself to","meaning":"適合用於……","examples":[{"en":"Dragon boat already lends itself to mixed participation.","zh":"龍舟本身已經適合用於男女混合參與。"},{"en":"To lend itself to something means to be naturally suitable for that use or purpose.","zh":"適合用於某事，意思是自然適合某種用途或目的。"},{"en":"A large classroom lends itself to group activities because students can move around.","zh":"大課室適合用於小組活動，因為學生可以走動。"},{"en":"A simple story lends itself to teaching children new vocabulary.","zh":"簡單故事適合用於教孩子新詞彙。"},{"en":"Dragon Boat Racing lends itself to teamwork because everyone must follow one rhythm.","zh":"龍舟競賽適合用於團隊合作，因為每個人都必須跟隨同一節奏。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"mixed participation","meaning":"男女混合參與","examples":[{"en":"Dragon boat racing naturally allows mixed participation.","zh":"龍舟競賽自然允許男女混合參與。"},{"en":"Mixed participation means people of different groups, such as men and women, take part together.","zh":"男女混合參與，意思是不同群體的人，例如男性和女性，一起參加。"},{"en":"A school project encourages mixed participation when students from different classes work together.","zh":"當不同班級的學生一起合作，學校 project 就鼓勵混合參與。"},{"en":"Mixed participation can reduce separation because people share the same task.","zh":"混合參與可以減少分隔，因為人們共享同一任務。"},{"en":"Dragon Boat Racing supports mixed participation through one boat and one rhythm.","zh":"龍舟競賽透過同一條船和同一節奏支持男女混合參與。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"side by side","meaning":"並肩","examples":[{"en":"Men and women can paddle side by side.","zh":"男性和女性可以並肩划槳。"},{"en":"Side by side means next to each other, often while doing the same activity.","zh":"並肩，意思是在彼此旁邊，通常一起做同一件事。"},{"en":"Students may sit side by side when they work on a shared project.","zh":"學生做共同 project 時，可能並肩坐著。"},{"en":"Working side by side can build trust because people see each other’s effort.","zh":"並肩工作可以建立信任，因為人們看見彼此的努力。"},{"en":"In Dragon Boat Racing, side-by-side effort shows practical equality.","zh":"在龍舟競賽中，並肩努力展現實際平等。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"share the same rhythm","meaning":"共享同一節奏","examples":[{"en":"Men and women can share the same rhythm in one boat.","zh":"男性和女性可以在同一條船上共享同一節奏。"},{"en":"To share the same rhythm means to move or act in the same timing.","zh":"共享同一節奏，意思是以同一時機移動或行動。"},{"en":"Dancers must share the same rhythm so the performance looks united.","zh":"舞者必須共享同一節奏，表演才看起來團結。"},{"en":"If paddlers do not share the same rhythm, the boat becomes slower.","zh":"如果划手不共享同一節奏，船就會變慢。"},{"en":"Sharing the same rhythm turns separate athletes into one crew.","zh":"共享同一節奏把個別運動員變成一隊人。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"contribute to the same result","meaning":"為同一結果作出貢獻","examples":[{"en":"Every crew member contributes to the same result.","zh":"每位隊員都為同一結果作出貢獻。"},{"en":"To contribute to the same result means each person helps create one shared outcome.","zh":"為同一結果作出貢獻，意思是每個人都幫助創造一個共同成果。"},{"en":"In a group report, writers, editors, and presenters all contribute to the same result.","zh":"在小組報告中，撰寫者、編輯和匯報者都為同一結果作出貢獻。"},{"en":"If one member does not contribute, the same result becomes harder to reach.","zh":"如果一名成員沒有貢獻，同一結果就更難達成。"},{"en":"Dragon Boat Racing shows that different roles can contribute to the same result.","zh":"龍舟競賽顯示不同角色可以為同一結果作出貢獻。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"symbolic equality","meaning":"象徵式平等","examples":[{"en":"This is not merely symbolic equality.","zh":"這不只是象徵式平等。"},{"en":"Symbolic equality means equality that looks fair in name or appearance but may not give real power.","zh":"象徵式平等，意思是名稱或表面上看似公平，但未必給予真正權力。"},{"en":"A school shows only symbolic equality if students may join a meeting but cannot speak.","zh":"如果學生可以參加會議但不能發言，學校只是展示象徵式平等。"},{"en":"Symbolic equality can disappoint people when labels change but daily treatment stays unfair.","zh":"當標籤改變但日常待遇仍不公平，象徵式平等會令人失望。"},{"en":"Dragon Boat Racing can go beyond symbolic equality because every role affects the race.","zh":"龍舟競賽可以超越象徵式平等，因為每個角色都影響比賽。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"be separated","meaning":"被分開","examples":[{"en":"In symbolic equality, athletes may be separated and given similar labels.","zh":"在象徵式平等中，運動員可能被分開並被給予相似標籤。"},{"en":"To be separated means to be put apart instead of being together.","zh":"被分開，意思是被放在不同地方，而不是在一起。"},{"en":"Students may be separated into groups for safety during a science experiment.","zh":"在科學實驗中，學生可能為安全而被分成小組。"},{"en":"If athletes are separated too much, they may not feel they are sharing the same event.","zh":"如果運動員被分開太多，他們可能不覺得自己共享同一賽事。"},{"en":"Dragon Boat Racing can reduce separation by placing different athletes in one boat.","zh":"龍舟競賽可以透過把不同運動員放在同一條船上來減少分隔。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"merely given similar labels","meaning":"只是被給予相似標籤","examples":[{"en":"Athletes may be separated and merely given similar labels.","zh":"運動員可能被分開，並只是被給予相似標籤。"},{"en":"Merely given similar labels means people receive words that sound equal, but their real experience may still differ.","zh":"只是被給予相似標籤，意思是人們得到聽起來平等的名稱，但真實經驗可能仍不同。"},{"en":"A school is not fair if students are merely given similar labels but unequal support.","zh":"如果學生只是被給予相似標籤，卻得到不平等支援，學校就不公平。"},{"en":"When workers are called partners but have no voice, they are merely given similar labels.","zh":"當工人被稱為夥伴但沒有發言權，他們只是被給予相似標籤。"},{"en":"Real equality needs shared power, not merely similar labels.","zh":"真正平等需要共享權力，而不是只是相似標籤。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"practical equality","meaning":"實際平等","examples":[{"en":"Rather, it is practical equality, where everyone in the boat matters.","zh":"相反，這是實際平等，因為船上每個人都重要。"},{"en":"Practical equality means fairness that works in real action, not only in words.","zh":"實際平等，意思是在真實行動中有效的公平，而不只是口頭上的公平。"},{"en":"A classroom has practical equality when every student receives help they can actually use.","zh":"當每位學生都得到真正可用的幫助，課室就有實際平等。"},{"en":"Practical equality grows when rules make participation fair in daily practice.","zh":"當規則令日常參與變得公平，實際平等就會增長。"},{"en":"Dragon Boat Racing shows practical equality because each role helps move the boat.","zh":"龍舟競賽展現實際平等，因為每個角色都幫助船前進。"}],"source":"2020 Q5.pdf","sourcePage":7},{"front":"everyone in the boat matters","meaning":"船上每個人都重要","examples":[{"en":"Practical equality means everyone in the boat matters.","zh":"實際平等意味著船上每個人都重要。"},{"en":"Everyone in the boat matters means every crew member has a real effect on the team’s success.","zh":"船上每個人都重要，意思是每位隊員都真正影響團隊成功。"},{"en":"In a group project, everyone matters when each task is necessary.","zh":"在小組 project 中，當每項任務都必要時，每個人都重要。"},{"en":"If one paddler loses rhythm, the whole boat may slow down, so everyone matters.","zh":"如果一名划手失去節奏，整條船可能變慢，所以每個人都重要。"},{"en":"This phrase shows equality through shared responsibility, not empty praise.","zh":"這個短語透過共同責任展現平等，而不是空洞讚美。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"paddlers, drummer and steersperson","meaning":"划手、鼓手和舵手","examples":[{"en":"The paddlers, drummer and steersperson all have important roles.","zh":"划手、鼓手和舵手都有重要角色。"},{"en":"Paddlers, drummer and steersperson are the crew members who move, guide rhythm, and steer the boat.","zh":"划手、鼓手和舵手，是指負責推動、帶節奏和掌舵的隊員。"},{"en":"In practice, paddlers build speed, the drummer sets timing, and the steersperson keeps direction.","zh":"在練習中，划手建立速度，鼓手設定節奏，舵手保持方向。"},{"en":"If any of these roles fails, the boat may lose balance, speed, or direction.","zh":"如果任何一個角色失誤，船可能失去平衡、速度或方向。"},{"en":"Dragon Boat Racing values paddlers, drummer and steersperson because teamwork needs all three.","zh":"龍舟競賽重視划手、鼓手和舵手，因為團隊合作需要三者。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"have different roles","meaning":"擔任不同角色","examples":[{"en":"The paddlers, drummer and steersperson have different roles.","zh":"划手、鼓手和舵手擔任不同角色。"},{"en":"To have different roles means each person has a separate job or responsibility.","zh":"擔任不同角色，意思是每個人有不同工作或責任。"},{"en":"In a school play, actors, writers, and stage helpers have different roles.","zh":"在學校戲劇中，演員、編劇和舞台助手擔任不同角色。"},{"en":"Teams work better when people understand their different roles clearly.","zh":"當人們清楚理解自己的不同角色，團隊會運作得更好。"},{"en":"Dragon Boat Racing shows that different roles can still serve one shared goal.","zh":"龍舟競賽顯示不同角色仍可以服務同一共同目標。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"no role is ornamental","meaning":"沒有角色只是裝飾","examples":[{"en":"No role in the boat is ornamental.","zh":"船上沒有角色只是裝飾。"},{"en":"No role is ornamental means every position has a real function, not just a decorative purpose.","zh":"沒有角色只是裝飾，意思是每個位置都有真實功能，而不只是作裝飾。"},{"en":"In a good group project, no role is ornamental because each student must contribute.","zh":"在好的小組 project 中，沒有角色只是裝飾，因為每位學生都必須貢獻。"},{"en":"If a role is only ornamental, people may feel included in name but not in practice.","zh":"如果角色只是裝飾，人們可能只是名義上被納入，而不是實際參與。"},{"en":"Dragon Boat Racing avoids ornamental roles because every crew member affects performance.","zh":"龍舟競賽避免裝飾性角色，因為每位隊員都影響表現。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, critics may argue that mixed racing could be unfair.","zh":"誠然，批評者可能會說男女混合賽可能不公平。"},{"en":"Granted is used to admit that an opposing point has some truth before answering it.","zh":"誠然，用來承認相反觀點有一定道理，然後再回應它。"},{"en":"Granted, the plan is expensive, but it may save money in the long term.","zh":"誠然，這個計劃昂貴，但長遠而言可能節省金錢。"},{"en":"A writer uses granted to sound fair instead of ignoring other views.","zh":"作者使用「誠然」，是為了顯得公平，而不是忽視其他看法。"},{"en":"Granted, mixed racing raises questions, but clear rules can answer them.","zh":"誠然，男女混合賽提出問題，但清晰規則可以回應這些問題。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"physical strength","meaning":"體力","examples":[{"en":"Critics may point to differences in physical strength.","zh":"批評者可能指出體力上的差異。"},{"en":"Physical strength means the power of the body to push, pull, lift, or move things.","zh":"體力，意思是身體推、拉、提起或移動東西的力量。"},{"en":"Carrying heavy boxes at work requires physical strength.","zh":"在工作中搬重箱需要體力。"},{"en":"Differences in physical strength can affect sports, so rules may need careful design.","zh":"體力差異可以影響運動，所以規則可能需要小心設計。"},{"en":"Dragon Boat Racing can manage physical strength differences through standardised crew requirements.","zh":"龍舟競賽可以透過標準化隊伍要求處理體力差異。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"mixed racing","meaning":"男女混合賽","examples":[{"en":"Some critics may argue that mixed racing is unfair.","zh":"有些批評者可能會說男女混合賽不公平。"},{"en":"Mixed racing means men and women compete together in the same race or team format.","zh":"男女混合賽，意思是男性和女性在同一場比賽或同一隊伍賽制中一起競賽。"},{"en":"A school may use mixed racing so boys and girls learn to cooperate in one team.","zh":"學校可能使用男女混合賽，讓男生和女生在同一隊中學習合作。"},{"en":"Mixed racing needs clear rules so no team gains an unfair advantage.","zh":"男女混合賽需要清晰規則，避免任何隊伍獲得不公平優勢。"},{"en":"Dragon Boat Racing is suitable for mixed racing because shared timing is central.","zh":"龍舟競賽適合男女混合賽，因為共享節奏是核心。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"standardised crew requirements","meaning":"標準化隊伍要求","examples":[{"en":"Standardised crew requirements could address this concern clearly.","zh":"標準化隊伍要求可以清楚處理這個憂慮。"},{"en":"Standardised crew requirements are fixed rules about who must be included in each team.","zh":"標準化隊伍要求，是關於每隊必須包括哪些人的固定規則。"},{"en":"A school tournament may use standardised team requirements so every class has the same number of players.","zh":"學校比賽可能使用標準化隊伍要求，讓每班都有相同數目的隊員。"},{"en":"Standardised crew requirements protect fairness by making all teams follow the same structure.","zh":"標準化隊伍要求透過令所有隊伍遵守同一結構來保障公平。"},{"en":"In mixed dragon boat racing, they could set a fixed number of male and female athletes.","zh":"在男女混合龍舟賽中，它們可以設定固定數目的男、女運動員。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"address this concern","meaning":"處理這個憂慮","examples":[{"en":"Standardised crew requirements could address this concern.","zh":"標準化隊伍要求可以處理這個憂慮。"},{"en":"To address this concern means to deal with a worry directly and seriously.","zh":"處理這個憂慮，意思是直接而認真地應對某個擔心。"},{"en":"A school may address parents’ concern by explaining safety rules before a trip.","zh":"學校可能在旅行前解釋安全規則，以處理家長的憂慮。"},{"en":"Clear evidence can address this concern better than simply saying people should not worry.","zh":"清晰證據比單純叫人不要擔心，更能處理這個憂慮。"},{"en":"Fixed crew rules can address this concern about fairness in mixed racing.","zh":"固定隊伍規則可以處理男女混合賽中關於公平的憂慮。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"provided that","meaning":"只要","examples":[{"en":"Provided that every team includes a fixed number of male and female athletes, fairness can be protected.","zh":"只要每隊包括固定數目的男、女運動員，公平就能得到保障。"},{"en":"Provided that means if, but it often sounds more formal and conditional.","zh":"只要，意思是如果，但語氣通常較正式和有條件。"},{"en":"Students may use the library provided that they keep quiet.","zh":"只要學生保持安靜，就可以使用圖書館。"},{"en":"A school trip can go ahead provided that the weather is safe.","zh":"只要天氣安全，學校旅行就可以繼續進行。"},{"en":"Mixed racing can be fair provided that all teams follow the same crew rules.","zh":"只要所有隊伍遵守相同隊伍規則，男女混合賽就可以公平。"}],"source":"2020 Q5.pdf","sourcePage":8},{"front":"a fixed number of","meaning":"固定數目的……","examples":[{"en":"Every team could include a fixed number of male and female athletes.","zh":"每隊可以包括固定數目的男、女運動員。"},{"en":"A fixed number of something means a set amount that does not change from team to team or case to case.","zh":"固定數目的某物，意思是設定好的數量，不會因隊伍或情況而改變。"},{"en":"A class may allow a fixed number of students in each discussion group.","zh":"班級可能規定每個討論小組有固定數目的學生。"},{"en":"A fixed number of players helps make a game fair and organised.","zh":"固定數目的球員有助令遊戲公平和有組織。"},{"en":"Dragon boat rules could require a fixed number of male and female athletes.","zh":"龍舟規則可以要求固定數目的男、女運動員。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"male and female athletes","meaning":"男、女運動員","examples":[{"en":"Each team should include both male and female athletes.","zh":"每隊應包括男、女運動員。"},{"en":"Male and female athletes means sportspeople who are men and women.","zh":"男、女運動員，意思是男性和女性的運動參與者。"},{"en":"A school relay may include male and female athletes to encourage cooperation.","zh":"學校接力賽可能包括男、女運動員，以鼓勵合作。"},{"en":"When male and female athletes train together, they can learn respect through shared effort.","zh":"當男、女運動員一起訓練，他們可以透過共同努力學習尊重。"},{"en":"Dragon Boat Racing can give male and female athletes meaningful roles in one crew.","zh":"龍舟競賽可以給男、女運動員在同一隊中有意義的角色。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"fairness would be protected","meaning":"公平會得到保障","examples":[{"en":"Fairness would be protected by standardised crew requirements.","zh":"公平會透過標準化隊伍要求得到保障。"},{"en":"Fairness would be protected means rules would help prevent unfair advantage or unfair treatment.","zh":"公平會得到保障，意思是規則會幫助防止不公平優勢或不公平待遇。"},{"en":"In an exam, fairness would be protected if all students received the same time limit.","zh":"在考試中，如果所有學生得到相同時間限制，公平會得到保障。"},{"en":"Clear judging rules mean fairness would be protected during a competition.","zh":"清晰評分規則意味著比賽中的公平會得到保障。"},{"en":"In mixed dragon boat racing, fairness would be protected if team structures were equal.","zh":"在男女混合龍舟賽中，如果隊伍結構相同，公平會得到保障。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"cooperation would be celebrated","meaning":"合作會受到肯定","examples":[{"en":"Cooperation would be celebrated through mixed-team racing.","zh":"合作會透過男女混合隊比賽受到肯定。"},{"en":"Cooperation would be celebrated means teamwork would be publicly valued and praised.","zh":"合作會受到肯定，意思是團隊合作會被公開重視和讚揚。"},{"en":"At school, cooperation is celebrated when group awards recognise every member’s effort.","zh":"在學校，當小組獎項肯定每位成員的努力，合作就受到肯定。"},{"en":"If a festival highlights volunteer teams, cooperation is celebrated in the community.","zh":"如果節日突出義工團隊，合作就在社區中受到肯定。"},{"en":"Mixed dragon boat racing celebrates cooperation because success depends on moving together.","zh":"男女混合龍舟賽肯定合作，因為成功取決於一起前進。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"few sports, if any","meaning":"即使有，也很少","examples":[{"en":"Few sports, if any, show equality so naturally.","zh":"即使有，也很少運動能如此自然地展現平等。"},{"en":"Few, if any, means almost none, and possibly none at all.","zh":"即使有，也很少，意思是幾乎沒有，甚至可能完全沒有。"},{"en":"Few students, if any, can finish a major project well without planning.","zh":"即使有，也很少學生能在沒有計劃下完成大型 project。"},{"en":"Few activities, if any, show teamwork as clearly as a crew moving together.","zh":"即使有，也很少活動能像一隊人一致前進那樣清楚展現團隊合作。"},{"en":"This phrase is used to make a strong comparison without sounding absolute.","zh":"這個短語用來作強烈比較，但又不顯得完全絕對。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"making everyone identical","meaning":"令每個人變得一模一樣","examples":[{"en":"Equality is not about making everyone identical.","zh":"平等不是令每個人變得一模一樣。"},{"en":"Making everyone identical means forcing people to be exactly the same instead of respecting differences.","zh":"令每個人變得一模一樣，意思是強迫人完全相同，而不是尊重差異。"},{"en":"A fair classroom is not about making everyone identical; students may need different kinds of help.","zh":"公平的課室不是令每個人變得一模一樣；學生可能需要不同種類的幫助。"},{"en":"Trying to make everyone identical can hide people’s real needs.","zh":"試圖令每個人變得一模一樣，可能掩蓋人們真正的需要。"},{"en":"Dragon Boat Racing shows equality by joining different roles, not by making everyone identical.","zh":"龍舟競賽透過結合不同角色展現平等，而不是令每個人變得一模一樣。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"allowing different athletes to","meaning":"讓不同運動員去……","examples":[{"en":"Equality is about allowing different athletes to work together.","zh":"平等是讓不同運動員一起合作。"},{"en":"Allowing different athletes to do something means giving athletes with different strengths a real chance to act together.","zh":"讓不同運動員去做某事，意思是給不同強項的運動員真正機會一起行動。"},{"en":"A school tournament can build respect by allowing different athletes to join mixed teams.","zh":"學校比賽可以透過讓不同運動員加入混合隊來建立尊重。"},{"en":"Allowing different athletes to cooperate may create fairer and richer competition.","zh":"讓不同運動員合作，可能創造更公平和更豐富的競爭。"},{"en":"Dragon Boat Racing supports equality by allowing different athletes to pull in one direction.","zh":"龍舟競賽透過讓不同運動員朝同一方向划動來支持平等。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"pull towards the same finish line","meaning":"朝同一終點努力","examples":[{"en":"Different athletes can pull towards the same finish line.","zh":"不同運動員可以朝同一終點努力。"},{"en":"To pull towards the same finish line means to work together for one shared goal.","zh":"朝同一終點努力，意思是為一個共同目標一起工作。"},{"en":"In a charity event, volunteers pull towards the same finish line when they serve the same community purpose.","zh":"在慈善活動中，當義工服務同一社區目的時，他們就是朝同一終點努力。"},{"en":"Teams become stronger when different members pull towards the same finish line instead of separate goals.","zh":"當不同成員朝同一終點努力，而不是追求分開目標，團隊會更強。"},{"en":"Dragon Boat Racing makes this idea visible because everyone literally pulls the boat forward.","zh":"龍舟競賽令這個概念可見，因為每個人真的把船向前划。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"attract media coverage","meaning":"吸引傳媒報道","examples":[{"en":"Dragon Boat Racing would attract media coverage.","zh":"龍舟競賽會吸引傳媒報道。"},{"en":"To attract media coverage means to make newspapers, television, websites, or social media report on something.","zh":"吸引傳媒報道，意思是令報紙、電視、網站或社交媒體報道某事。"},{"en":"A school charity run may attract media coverage if it raises money for a local hospital.","zh":"如果學校慈善跑為本地醫院籌款，可能會吸引傳媒報道。"},{"en":"Colourful and emotional events attract media coverage because they give reporters clear stories.","zh":"色彩豐富和富情感的活動會吸引傳媒報道，因為它們給記者清晰故事。"},{"en":"Dragon Boat Racing could attract media coverage through close races and cultural meaning.","zh":"龍舟競賽可以透過接近的比賽和文化意義吸引傳媒報道。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"spectacular","meaning":"壯觀的","examples":[{"en":"Dragon Boat Racing is spectacular and easy to broadcast.","zh":"龍舟競賽壯觀而且易於轉播。"},{"en":"Spectacular means very impressive to see, especially because of size, colour, movement, or excitement.","zh":"壯觀的，意思是看起來非常令人印象深刻，特別是因為規模、色彩、動作或刺激感。"},{"en":"A fireworks show can be spectacular when it lights up the whole harbour.","zh":"當煙花照亮整個海港，煙花表演可以很壯觀。"},{"en":"Sports feel spectacular when movement, sound, and suspense happen together.","zh":"當動作、聲音和懸念一起出現，運動就會顯得壯觀。"},{"en":"Dragon Boat Racing is spectacular because long boats, drums, and teams create a powerful image.","zh":"龍舟競賽很壯觀，因為長船、鼓聲和隊伍創造強烈畫面。"}],"source":"2020 Q5.pdf","sourcePage":9},{"front":"culturally distinctive","meaning":"具文化特色","examples":[{"en":"The sport is culturally distinctive.","zh":"這項運動具文化特色。"},{"en":"Culturally distinctive means clearly connected to a particular culture or tradition.","zh":"具文化特色，意思是清楚連繫到某種文化或傳統。"},{"en":"A festival is culturally distinctive when its food, music, and rituals belong to a specific community.","zh":"當節日的食物、音樂和儀式屬於特定社群，它就具文化特色。"},{"en":"Culturally distinctive sports attract interest because they carry stories as well as rules.","zh":"具文化特色的運動會吸引興趣，因為它們不只有規則，也承載故事。"},{"en":"Dragon Boat Racing is culturally distinctive because it is rooted in Chinese tradition.","zh":"龍舟競賽具文化特色，因為它植根於中華傳統。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"easy to broadcast","meaning":"易於轉播","examples":[{"en":"Dragon Boat Racing is easy to broadcast.","zh":"龍舟競賽易於轉播。"},{"en":"Easy to broadcast means suitable for showing clearly on television, online video, or live streams.","zh":"易於轉播，意思是適合在電視、網上影片或直播中清楚展示。"},{"en":"A race on a straight course is easy to broadcast because cameras can follow the action.","zh":"直線賽道上的比賽易於轉播，因為鏡頭可以跟隨動作。"},{"en":"Sports with clear winners and visible movement are easier to broadcast.","zh":"有清楚勝負和可見動作的運動較易於轉播。"},{"en":"Dragon Boat Racing is easy to broadcast because viewers can see the boat, rhythm, and finish.","zh":"龍舟競賽易於轉播，因為觀眾能看見船、節奏和終點。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"television and online audiences","meaning":"電視及網上觀眾","examples":[{"en":"Television and online audiences respond to movement and suspense.","zh":"電視及網上觀眾會被動感和懸念吸引。"},{"en":"Television and online audiences are people who watch programmes on TV or digital platforms.","zh":"電視及網上觀眾，是指透過電視或數碼平台觀看節目的人。"},{"en":"A sports final can reach television and online audiences at the same time.","zh":"體育決賽可以同時接觸電視及網上觀眾。"},{"en":"If an event looks exciting on screen, television and online audiences may share it quickly.","zh":"如果活動在螢幕上看起來刺激，電視及網上觀眾可能很快分享它。"},{"en":"Dragon Boat Racing can attract television and online audiences through strong images and close finishes.","zh":"龍舟競賽可以透過強烈畫面和接近的衝線吸引電視及網上觀眾。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"respond to","meaning":"對……有反應；受……吸引","examples":[{"en":"Audiences respond to movement, colour, sound and suspense.","zh":"觀眾會對動感、色彩、聲音和懸念有反應。"},{"en":"To respond to something means to react to it emotionally, mentally, or through action.","zh":"對某事有反應，意思是在情感、思想或行動上作出回應。"},{"en":"Students respond to clear examples because they make difficult ideas easier.","zh":"學生會對清晰例子有反應，因為它們令困難概念較容易。"},{"en":"Viewers respond to close races because the result is uncertain.","zh":"觀眾會受接近的比賽吸引，因為結果不確定。"},{"en":"Media audiences respond to Dragon Boat Racing because it gives them sound, motion, and drama.","zh":"媒體觀眾會對龍舟競賽有反應，因為它給他們聲音、動作和戲劇感。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"movement, colour, sound and suspense","meaning":"動感、色彩、聲音和懸念","examples":[{"en":"Dragon boat racing supplies movement, colour, sound and suspense.","zh":"龍舟競賽提供動感、色彩、聲音和懸念。"},{"en":"Movement, colour, sound and suspense are features that make an event lively and exciting to watch.","zh":"動感、色彩、聲音和懸念，是令活動觀看起來生動刺激的特徵。"},{"en":"A parade uses movement, colour, sound and suspense to keep people watching.","zh":"巡遊使用動感、色彩、聲音和懸念來令市民繼續觀看。"},{"en":"When these features appear together, an ordinary event can become memorable.","zh":"當這些特徵一起出現，普通活動也可以變得令人難忘。"},{"en":"Dragon Boat Racing has movement from paddles, colour from boats, sound from drums, and suspense at the finish.","zh":"龍舟競賽有槳帶來的動感、船帶來的色彩、鼓帶來的聲音，以及終點的懸念。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"supply them all","meaning":"全部具備","examples":[{"en":"Dragon boat racing supplies all these qualities.","zh":"龍舟競賽全部具備這些特質。"},{"en":"To supply them all means to provide every quality that has just been mentioned.","zh":"全部具備，意思是提供剛剛提到的每一種特質。"},{"en":"A good lesson needs clarity, practice, and feedback; a strong teacher supplies them all.","zh":"好課堂需要清晰、練習和回饋；好的老師會全部具備。"},{"en":"If an event supplies all the qualities audiences enjoy, it becomes easier to promote.","zh":"如果活動具備觀眾喜歡的所有特質，它就更容易推廣。"},{"en":"Dragon Boat Racing supplies them all: movement, colour, sound, and suspense.","zh":"龍舟競賽全部具備：動感、色彩、聲音和懸念。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"striking","meaning":"醒目；引人注目","examples":[{"en":"The boats are striking.","zh":"這些船很醒目。"},{"en":"Striking means very noticeable or impressive, especially visually.","zh":"醒目或引人注目，意思是非常明顯或令人印象深刻，特別是在視覺上。"},{"en":"A bright red poster can be striking on a plain wall.","zh":"鮮紅色海報在素色牆上可以很醒目。"},{"en":"Striking images help people remember an event after it ends.","zh":"引人注目的畫面幫助人們在活動結束後仍記得它。"},{"en":"Dragon boats are striking because their long shape and colourful designs catch the eye.","zh":"龍舟很醒目，因為它們的長形和鮮艷設計吸引目光。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"drumbeat","meaning":"鼓聲節奏","examples":[{"en":"The drumbeat is memorable.","zh":"鼓聲節奏令人難忘。"},{"en":"A drumbeat is the repeated sound or rhythm made by a drum.","zh":"鼓聲節奏，是鼓發出的重複聲音或節拍。"},{"en":"During a school performance, a steady drumbeat can help dancers move together.","zh":"在學校表演中，穩定的鼓聲節奏可以幫助舞者一起移動。"},{"en":"A strong drumbeat can make an event feel energetic and urgent.","zh":"強烈的鼓聲節奏可以令活動感覺有活力和緊張。"},{"en":"In Dragon Boat Racing, the drumbeat guides the paddlers and excites the crowd.","zh":"在龍舟競賽中，鼓聲節奏引導划手並令觀眾興奮。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"memorable","meaning":"令人難忘","examples":[{"en":"The drumbeat is memorable.","zh":"鼓聲節奏令人難忘。"},{"en":"Memorable means easy to remember because something is special, clear, or emotional.","zh":"令人難忘，意思是因為特別、清晰或有情感而容易記住。"},{"en":"A teacher’s story becomes memorable when it connects a lesson to real life.","zh":"當老師把課堂連接到現實生活，故事就變得令人難忘。"},{"en":"Events become memorable when people see, hear, and feel something powerful.","zh":"當人們看見、聽見和感受到有力量的東西，活動就變得令人難忘。"},{"en":"Dragon Boat Racing is memorable because the sound and movement stay in people’s minds.","zh":"龍舟競賽令人難忘，因為聲音和動作會留在人們腦海中。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"a crew moving as one","meaning":"一隊人動作一致","examples":[{"en":"The image of a crew moving as one is powerful.","zh":"一隊人動作一致的畫面很有力量。"},{"en":"A crew moving as one means a team acting together with the same timing and purpose.","zh":"一隊人動作一致，意思是一個團隊以相同時機和目標一起行動。"},{"en":"A dance group moving as one can make a simple performance look strong.","zh":"舞蹈隊動作一致時，可以令簡單表演看起來很有力量。"},{"en":"When a crew moves as one, the boat becomes faster and the teamwork becomes visible.","zh":"當一隊人動作一致，船會更快，團隊合作也變得可見。"},{"en":"Dragon Boat Racing gives viewers a clear image of unity through a crew moving as one.","zh":"龍舟競賽透過一隊人動作一致，給觀眾清楚的團結畫面。"}],"source":"2020 Q5.pdf","sourcePage":10},{"front":"even without commentary","meaning":"即使沒有旁述","examples":[{"en":"The image is powerful even without commentary.","zh":"這個畫面即使沒有旁述也很有力量。"},{"en":"Even without commentary means something is clear or moving without spoken explanation.","zh":"即使沒有旁述，意思是沒有口頭解釋，某事仍清楚或令人感動。"},{"en":"A photo of flooded homes can be powerful even without commentary.","zh":"被水淹沒的房屋照片，即使沒有旁述也可以很有力量。"},{"en":"If an action is easy to understand, viewers may feel its meaning even without commentary.","zh":"如果一個動作容易理解，觀眾即使沒有旁述也可能感受到其意義。"},{"en":"Dragon Boat Racing can impress audiences even without commentary because its teamwork is visible.","zh":"龍舟競賽即使沒有旁述也能打動觀眾，因為其團隊合作是可見的。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"better still","meaning":"更理想的是","examples":[{"en":"Better still, the sport carries cultural depth.","zh":"更理想的是，這項運動承載文化深度。"},{"en":"Better still is used to add an even stronger or more attractive point.","zh":"更理想的是，用來加入一個更強或更吸引的重點。"},{"en":"The library is quiet; better still, it stays open after school.","zh":"圖書館很安靜；更理想的是，它放學後仍然開放。"},{"en":"A sports event may be exciting; better still, it can also teach values.","zh":"體育活動可能很刺激；更理想的是，它也可以教導價值觀。"},{"en":"Better still, Dragon Boat Racing is not only visual but culturally meaningful.","zh":"更理想的是，龍舟競賽不只有視覺效果，還有文化意義。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"cultural depth","meaning":"文化深度","examples":[{"en":"Dragon Boat Racing carries cultural depth.","zh":"龍舟競賽承載文化深度。"},{"en":"Cultural depth means an activity has history, meaning, and traditions behind it.","zh":"文化深度，意思是活動背後有歷史、意義和傳統。"},{"en":"A festival has cultural depth when people understand the stories behind its rituals.","zh":"當人們理解節日儀式背後的故事，節日就有文化深度。"},{"en":"Cultural depth makes an event more than entertainment because it connects people to memory.","zh":"文化深度令活動不只是娛樂，因為它把人們與記憶連結起來。"},{"en":"Dragon Boat Racing has cultural depth because it links sport with heritage.","zh":"龍舟競賽有文化深度，因為它把運動與文化傳承連結起來。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"be rooted in","meaning":"植根於","examples":[{"en":"The sport is rooted in Chinese tradition.","zh":"這項運動植根於中華傳統。"},{"en":"To be rooted in something means to come from it deeply or be strongly connected to it.","zh":"植根於某事，意思是深深來自它或與它有強烈連繫。"},{"en":"A family recipe may be rooted in village life and old cooking habits.","zh":"家庭食譜可能植根於鄉村生活和舊烹調習慣。"},{"en":"A festival rooted in history can help people remember where they came from.","zh":"植根於歷史的節日可以幫助人們記得自己的來源。"},{"en":"Dragon Boat Racing is rooted in tradition but can still travel across the world.","zh":"龍舟競賽植根於傳統，但仍可以傳播到世界各地。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"Chinese tradition","meaning":"中華傳統","examples":[{"en":"Dragon Boat Racing is rooted in Chinese tradition.","zh":"龍舟競賽植根於中華傳統。"},{"en":"Chinese tradition means customs, beliefs, festivals, arts, and practices passed down in Chinese culture.","zh":"中華傳統，意思是在中華文化中流傳下來的習俗、信念、節日、藝術和做法。"},{"en":"The Dragon Boat Festival is part of Chinese tradition and is celebrated with food and racing.","zh":"端午節是中華傳統的一部分，人們以食物和競賽來慶祝。"},{"en":"Chinese tradition remains alive when younger people practise and understand it.","zh":"當年輕人實踐並理解中華傳統，它就保持活力。"},{"en":"Dragon Boat Racing shows Chinese tradition through teamwork, rhythm, and festival memory.","zh":"龍舟競賽透過團隊合作、節奏和節日記憶展現中華傳統。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"travel far beyond","meaning":"遠遠傳播至……之外","examples":[{"en":"The sport has travelled far beyond one community.","zh":"這項運動已遠遠傳播至單一社群之外。"},{"en":"To travel far beyond something means to spread much further than its original place or group.","zh":"遠遠傳播至某處之外，意思是比原來地方或群體傳播得遠得多。"},{"en":"A local song may travel far beyond its village when people share it online.","zh":"當人們在網上分享，本地歌曲可能遠遠傳播至村莊之外。"},{"en":"Traditions travel far beyond one community when others practise them respectfully.","zh":"當其他人尊重地實踐傳統，它們會遠遠傳播至單一社群之外。"},{"en":"Dragon Boat Racing has travelled far beyond its origins and become a global sport.","zh":"龍舟競賽已遠遠傳播至其起源之外，成為全球運動。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"one community","meaning":"單一社群","examples":[{"en":"Dragon Boat Racing has travelled beyond one community.","zh":"龍舟競賽已傳播至單一社群之外。"},{"en":"One community means a single group of people who share a place, culture, or interest.","zh":"單一社群，意思是共享地方、文化或興趣的一個群體。"},{"en":"A school project may begin in one community and later inspire others.","zh":"學校 project 可能始於單一社群，後來啟發其他人。"},{"en":"When an activity spreads beyond one community, more people can learn its meaning.","zh":"當活動傳播至單一社群之外，更多人可以學習其意義。"},{"en":"Dragon Boat Racing is no longer limited to one community because it is practised worldwide.","zh":"龍舟競賽不再限於單一社群，因為它在世界各地被實踐。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"charity races","meaning":"慈善賽事","examples":[{"en":"The sport has spread through festivals and charity races.","zh":"這項運動透過節日和慈善賽事傳播。"},{"en":"Charity races are competitions organised to raise money or awareness for a good cause.","zh":"慈善賽事，是為善因籌款或提高關注而舉辦的比賽。"},{"en":"A school may hold charity races to support children in need.","zh":"學校可能舉辦慈善賽事來支持有需要的孩子。"},{"en":"Charity races can bring people together because sport becomes linked to helping others.","zh":"慈善賽事可以把人們聚在一起，因為運動與幫助他人連結起來。"},{"en":"Dragon Boat Racing often grows through charity races that welcome community teams.","zh":"龍舟競賽常透過歡迎社區隊伍的慈善賽事成長。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"school competitions","meaning":"學校比賽","examples":[{"en":"Dragon Boat Racing appears in school competitions around the world.","zh":"龍舟競賽出現在世界各地的學校比賽中。"},{"en":"School competitions are contests organised for students to practise skills and compete fairly.","zh":"學校比賽，是為學生練習技能和公平競爭而舉辦的比賽。"},{"en":"School competitions can include sports, speeches, music, or science projects.","zh":"學校比賽可以包括運動、演講、音樂或科學 project。"},{"en":"When Dragon Boat Racing enters school competitions, young people learn teamwork early.","zh":"當龍舟競賽進入學校比賽，年輕人會較早學到團隊合作。"},{"en":"School competitions help a sport spread because students carry the experience home.","zh":"學校比賽幫助運動傳播，因為學生會把經驗帶回家。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"around the world","meaning":"世界各地","examples":[{"en":"Dragon Boat Racing is practised around the world.","zh":"龍舟競賽在世界各地被實踐。"},{"en":"Around the world means in many countries or places across the globe.","zh":"世界各地，意思是在全球許多國家或地方。"},{"en":"Students around the world use online videos to learn new skills.","zh":"世界各地的學生使用網上影片學習新技能。"},{"en":"A sport becomes stronger when people around the world practise it seriously.","zh":"當世界各地的人認真實踐一項運動，它就會變得更強。"},{"en":"Dragon Boat Racing has reached clubs, schools, and festivals around the world.","zh":"龍舟競賽已到達世界各地的學會、學校和節日。"}],"source":"2020 Q5.pdf","sourcePage":11},{"front":"in media terms","meaning":"從媒體角度而言","examples":[{"en":"In media terms, the sport gives journalists two stories at once.","zh":"從媒體角度而言，這項運動同時給記者兩個故事。"},{"en":"In media terms means from the point of view of news, broadcasting, or public communication.","zh":"從媒體角度而言，意思是從新聞、轉播或公共傳播的角度來看。"},{"en":"In media terms, a school charity event is interesting if it has people, emotion, and a clear purpose.","zh":"從媒體角度而言，如果學校慈善活動有人物、情感和清晰目的，就很有趣。"},{"en":"In media terms, sports with strong images are easier to explain to audiences.","zh":"從媒體角度而言，有強烈畫面的運動更容易向觀眾解釋。"},{"en":"In media terms, Dragon Boat Racing offers both competition and culture.","zh":"從媒體角度而言，龍舟競賽同時提供競爭和文化。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"journalists","meaning":"記者","examples":[{"en":"Dragon Boat Racing gives journalists two stories at once.","zh":"龍舟競賽同時給記者兩個故事。"},{"en":"Journalists are people who collect information and report news to the public.","zh":"記者，是收集資料並向公眾報道新聞的人。"},{"en":"Journalists may interview students after a school event to understand what happened.","zh":"學校活動後，記者可能訪問學生以了解發生了甚麼。"},{"en":"Journalists look for clear stories, strong images, and public interest.","zh":"記者尋找清晰故事、強烈畫面和公眾興趣。"},{"en":"Dragon Boat Racing gives journalists material because it has sport, culture, and human teamwork.","zh":"龍舟競賽給記者素材，因為它有運動、文化和人的團隊合作。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"two stories at once","meaning":"同時提供兩個故事","examples":[{"en":"The sport offers journalists two stories at once.","zh":"這項運動同時給記者提供兩個故事。"},{"en":"Two stories at once means two different angles or meanings are available at the same time.","zh":"同時提供兩個故事，意思是同一時間有兩個不同角度或意義。"},{"en":"A school garden gives two stories at once: environmental learning and student cooperation.","zh":"學校花園同時提供兩個故事：環境學習和學生合作。"},{"en":"Dragon Boat Racing gives two stories at once because it is both a race and a cultural tradition.","zh":"龍舟競賽同時提供兩個故事，因為它既是比賽，也是文化傳統。"},{"en":"This phrase helps show why an event is rich enough for media coverage.","zh":"這個短語幫助說明為何活動足夠豐富，值得傳媒報道。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"a thrilling race","meaning":"刺激的比賽","examples":[{"en":"Dragon Boat Racing offers the story of a thrilling race.","zh":"龍舟競賽提供刺激比賽的故事。"},{"en":"A thrilling race is an exciting competition that keeps people eager to know the result.","zh":"刺激的比賽，是令人興奮並讓人急於知道結果的競爭。"},{"en":"A school relay can become a thrilling race when teams are close until the final step.","zh":"當各隊直到最後一步都很接近，學校接力賽可以變成刺激的比賽。"},{"en":"A thrilling race creates suspense because the winner is not clear too early.","zh":"刺激的比賽會創造懸念，因為勝者不會太早明朗。"},{"en":"Dragon Boat Racing often becomes a thrilling race when boats finish only inches apart.","zh":"當船隻只差些微距離衝線，龍舟競賽常變成刺激的比賽。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"a living heritage","meaning":"活的文化傳承","examples":[{"en":"The sport also tells the story of a living heritage.","zh":"這項運動也講述活的文化傳承的故事。"},{"en":"A living heritage is a tradition that people still practise, understand, and pass on today.","zh":"活的文化傳承，是人們今天仍在實踐、理解和傳下去的傳統。"},{"en":"A festival becomes a living heritage when families teach children its songs and rituals.","zh":"當家庭教孩子節日歌曲和儀式，節日就成為活的文化傳承。"},{"en":"Living heritage survives because people use it in real life, not only display it in museums.","zh":"活的文化傳承能延續，因為人們在現實生活中使用它，而不只是把它放在博物館展示。"},{"en":"Dragon Boat Racing is a living heritage because communities continue to race, drum, and celebrate.","zh":"龍舟競賽是活的文化傳承，因為社群仍繼續比賽、打鼓和慶祝。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"the Olympic schedule","meaning":"奧運賽程","examples":[{"en":"Some may worry that the Olympic schedule is already crowded.","zh":"有些人可能擔心奧運賽程已經很擁擠。"},{"en":"The Olympic schedule is the timetable of events during the Olympic Games.","zh":"奧運賽程，是奧運會期間各項賽事的時間表。"},{"en":"A school schedule becomes crowded when too many activities are placed on the same day.","zh":"當太多活動被安排在同一天，學校時間表就會很擁擠。"},{"en":"If the Olympic schedule is crowded, new events must be planned carefully.","zh":"如果奧運賽程很擁擠，新項目就必須小心安排。"},{"en":"A crowded Olympic schedule is a concern, but it does not automatically rule out every new sport.","zh":"擁擠的奧運賽程是一個憂慮，但它不會自動排除每一項新運動。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"already crowded","meaning":"已經很擁擠","examples":[{"en":"The Olympic schedule is already crowded.","zh":"奧運賽程已經很擁擠。"},{"en":"Already crowded means there is little space left because many things are included now.","zh":"已經很擁擠，意思是因為現在已包括很多東西，所以剩下空間很少。"},{"en":"A classroom is already crowded if every seat is taken before new students arrive.","zh":"如果新學生到來前每個座位都有人，課室就已經很擁擠。"},{"en":"When a timetable is already crowded, adding one more activity becomes difficult.","zh":"當時間表已經很擁擠，再加入一項活動就變得困難。"},{"en":"The Olympic schedule may be already crowded, so Dragon Boat Racing would need a compact format.","zh":"奧運賽程可能已經很擁擠，所以龍舟競賽需要緊湊賽制。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"that concern is understandable","meaning":"這個憂慮可以理解","examples":[{"en":"That concern is understandable.","zh":"這個憂慮可以理解。"},{"en":"That concern is understandable means the worry is reasonable and should not be dismissed.","zh":"這個憂慮可以理解，意思是這個擔心有道理，不應被忽視。"},{"en":"Parents’ concern about school-trip safety is understandable.","zh":"家長對學校旅行安全的憂慮可以理解。"},{"en":"When people worry about costs, that concern is understandable because budgets are limited.","zh":"當人們擔心成本，這個憂慮可以理解，因為預算有限。"},{"en":"The crowded schedule concern is understandable, but careful planning can reduce it.","zh":"賽程擁擠這個憂慮可以理解，但小心規劃可以減少問題。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"rule out","meaning":"排除","examples":[{"en":"The concern should not rule out Dragon Boat Racing.","zh":"這個憂慮不應排除龍舟競賽。"},{"en":"To rule out something means to reject it or decide it is not possible.","zh":"排除某事，意思是拒絕它或判定它不可能。"},{"en":"A doctor may rule out a serious illness after checking test results.","zh":"醫生檢查測試結果後，可能排除嚴重疾病。"},{"en":"High cost may make a plan difficult, but it does not always rule it out.","zh":"高成本可能令計劃困難，但不一定會排除它。"},{"en":"A crowded Olympic schedule should not rule out Dragon Boat Racing if it can be compact.","zh":"如果龍舟競賽可以緊湊安排，擁擠的奧運賽程不應排除它。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"meet the IOC’s criteria","meaning":"符合國際奧委會的準則","examples":[{"en":"Dragon Boat Racing meets the IOC’s criteria directly.","zh":"龍舟競賽直接符合國際奧委會的準則。"},{"en":"To meet the IOC’s criteria means to satisfy the standards used by the International Olympic Committee.","zh":"符合國際奧委會的準則，意思是滿足國際奧林匹克委員會使用的標準。"},{"en":"A school club meets safety criteria when it has trained teachers and clear rules.","zh":"當學會有受訓老師和清晰規則，它就符合安全準則。"},{"en":"A sport may meet the IOC’s criteria if it is international, fair, and well organised.","zh":"如果一項運動具國際性、公平和組織完善，它可能符合國際奧委會的準則。"},{"en":"Dragon Boat Racing could meet the IOC’s criteria through global participation and clear formats.","zh":"龍舟競賽可以透過全球參與和清晰賽制符合國際奧委會的準則。"}],"source":"2020 Q5.pdf","sourcePage":12},{"front":"compact sprint events","meaning":"緊湊的短途競賽項目","examples":[{"en":"Compact sprint events could be held over a limited number of days.","zh":"緊湊的短途競賽項目可以在有限數目的日子內舉行。"},{"en":"Compact sprint events are short, tightly organised races that do not take much time.","zh":"緊湊的短途競賽項目，是短而安排緊密、不花太多時間的比賽。"},{"en":"A school may use compact sprint events when sports day has only one afternoon.","zh":"當運動日只有一個下午，學校可能使用緊湊的短途競賽項目。"},{"en":"Compact sprint events help organisers manage a crowded schedule.","zh":"緊湊的短途競賽項目幫助主辦者管理擁擠的時間表。"},{"en":"Dragon Boat Racing could fit the Olympics through compact sprint events.","zh":"龍舟競賽可以透過緊湊的短途競賽項目適合奧運。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"be held over","meaning":"在……期間舉行","examples":[{"en":"Compact sprint events could be held over a limited number of days.","zh":"緊湊的短途競賽項目可以在有限數目的日子期間舉行。"},{"en":"Be held over a period means to take place during that period.","zh":"在某段期間舉行，意思是在那段時間內發生。"},{"en":"A school music festival may be held over three afternoons.","zh":"學校音樂節可能在三個下午期間舉行。"},{"en":"If an event is held over fewer days, it may be easier to manage.","zh":"如果活動在較少日子內舉行，它可能較容易管理。"},{"en":"Dragon Boat Racing could be held over a short period to reduce pressure on the Olympic schedule.","zh":"龍舟競賽可以在短時間內舉行，以減輕奧運賽程壓力。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"a limited number of days","meaning":"有限數目的日子","examples":[{"en":"The events could be held over a limited number of days.","zh":"這些賽事可以在有限數目的日子內舉行。"},{"en":"A limited number of days means only a small, fixed amount of time is available.","zh":"有限數目的日子，意思是只有少量、固定的時間可用。"},{"en":"Students may have a limited number of days to finish a project before the deadline.","zh":"學生可能只有有限數目的日子在限期前完成 project。"},{"en":"A limited number of days forces organisers to plan the most important events first.","zh":"有限數目的日子迫使主辦者先安排最重要的活動。"},{"en":"Dragon Boat Racing could use a limited number of days if the races are compact.","zh":"如果比賽緊湊，龍舟競賽可以使用有限數目的日子。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"waterfront facilities","meaning":"海濱設施","examples":[{"en":"The events could use waterfront facilities where possible.","zh":"這些賽事可以在可行情況下使用海濱設施。"},{"en":"Waterfront facilities are places and equipment beside water that can support activities or events.","zh":"海濱設施，是水邊能支持活動或賽事的地方和設備。"},{"en":"A city may use waterfront facilities for sailing lessons or community races.","zh":"城市可能使用海濱設施舉辦帆船課或社區比賽。"},{"en":"Good waterfront facilities make water sports safer and easier to organise.","zh":"良好的海濱設施令水上運動更安全和更容易組織。"},{"en":"Dragon Boat Racing needs suitable waterfront facilities for launching boats and managing spectators.","zh":"龍舟競賽需要合適海濱設施來下水、停泊船隻和管理觀眾。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"where possible","meaning":"在可行情況下","examples":[{"en":"Waterfront facilities could be used where possible.","zh":"在可行情況下，可以使用海濱設施。"},{"en":"Where possible means if it can be done or if conditions allow it.","zh":"在可行情況下，意思是如果能做到或條件容許。"},{"en":"Students should recycle paper where possible.","zh":"學生應在可行情況下回收紙張。"},{"en":"Schools may hold outdoor lessons where possible when the weather is safe.","zh":"當天氣安全時，學校可在可行情況下舉行戶外課堂。"},{"en":"Dragon Boat Racing could use existing waterfront facilities where possible to reduce cost.","zh":"龍舟競賽可以在可行情況下使用現有海濱設施，以降低成本。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"the question is not whether…but whether…","meaning":"問題不在於是否……而在於是否……","examples":[{"en":"The question is not whether every sport deserves a place, but whether this sport brings something distinctive.","zh":"問題不在於是否每項運動都值得佔一席位，而在於這項運動是否帶來獨特之處。"},{"en":"The question is not whether…but whether… is used to shift attention from the wrong issue to the real issue.","zh":"問題不在於是否……而在於是否……，用來把注意力由錯誤問題轉向真正問題。"},{"en":"The question is not whether students enjoy games, but whether games help them learn.","zh":"問題不在於學生是否喜歡遊戲，而在於遊戲是否幫助他們學習。"},{"en":"This structure helps writers make a sharper argument by comparing two questions.","zh":"這個結構透過比較兩個問題，幫助作者提出更清晰的論點。"},{"en":"For Dragon Boat Racing, the issue is not only space, but the special value it brings.","zh":"對龍舟競賽而言，問題不只是空間，而是它帶來的特別價值。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"deserve a place","meaning":"值得佔一席位","examples":[{"en":"Not every sport deserves a place in the Olympics.","zh":"不是每項運動都值得在奧運中佔一席位。"},{"en":"To deserve a place means to be worthy of being included.","zh":"值得佔一席位，意思是值得被納入其中。"},{"en":"A student’s idea deserves a place in the discussion if it is useful and well explained.","zh":"如果學生的想法有用並解釋清楚，就值得在討論中佔一席位。"},{"en":"A sport deserves a place when it adds clear value and can be organised fairly.","zh":"當一項運動加入清晰價值並能公平組織，它就值得佔一席位。"},{"en":"Dragon Boat Racing deserves a place if it can serve youth, equality, and media interest.","zh":"如果龍舟競賽能服務青年、平等和媒體興趣，它就值得佔一席位。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"bring something distinctive","meaning":"帶來獨特之處","examples":[{"en":"Dragon Boat Racing brings something distinctive to the Games.","zh":"龍舟競賽為奧運會帶來獨特之處。"},{"en":"To bring something distinctive means to add a quality that is special and different from others.","zh":"帶來獨特之處，意思是加入一種特別並不同於其他事物的特質。"},{"en":"A local singer brings something distinctive to a concert by using a traditional instrument.","zh":"本地歌手透過使用傳統樂器，為音樂會帶來獨特之處。"},{"en":"A new event should bring something distinctive, not simply copy existing events.","zh":"新項目應帶來獨特之處，而不是單純複製現有項目。"},{"en":"Dragon Boat Racing brings something distinctive through culture, teamwork, rhythm, and spectacle.","zh":"龍舟競賽透過文化、團隊合作、節奏和壯觀畫面帶來獨特之處。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"all things considered","meaning":"綜合考慮各方面","examples":[{"en":"All things considered, the IOC should give Dragon Boat Racing serious consideration.","zh":"綜合考慮各方面，國際奧委會應認真考慮龍舟競賽。"},{"en":"All things considered means after thinking about all important points together.","zh":"綜合考慮各方面，意思是在一起思考所有重要因素之後。"},{"en":"All things considered, the school should keep the library open after lessons.","zh":"綜合考慮各方面，學校應在放學後保持圖書館開放。"},{"en":"Writers use all things considered before giving a balanced final judgement.","zh":"作者在給出平衡的最終判斷前，會使用「綜合考慮各方面」。"},{"en":"All things considered, Dragon Boat Racing offers enough benefits to deserve careful attention.","zh":"綜合考慮各方面，龍舟競賽提供足夠好處，值得仔細關注。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"respectfully urge","meaning":"恭敬地敦促","examples":[{"en":"I respectfully urge the IOC to consider Dragon Boat Racing seriously.","zh":"我恭敬地敦促國際奧委會認真考慮龍舟競賽。"},{"en":"To respectfully urge someone means to strongly ask them to do something in a polite way.","zh":"恭敬地敦促某人，意思是以禮貌方式強烈要求對方做某事。"},{"en":"Students may respectfully urge the school to improve lunch choices.","zh":"學生可能恭敬地敦促學校改善午餐選擇。"},{"en":"A formal letter uses respectfully urge when the writer wants to be firm but courteous.","zh":"當作者想堅定但有禮貌時，正式信件會使用「恭敬地敦促」。"},{"en":"The writer respectfully urges the IOC because the request is serious, not casual.","zh":"作者恭敬地敦促國際奧委會，因為這個要求是嚴肅的，不是隨便的。"}],"source":"2020 Q5.pdf","sourcePage":13},{"front":"give serious consideration","meaning":"認真考慮","examples":[{"en":"The IOC should give Dragon Boat Racing serious consideration.","zh":"國際奧委會應認真考慮龍舟競賽。"},{"en":"To give serious consideration means to think about something carefully before deciding.","zh":"認真考慮，意思是在決定前仔細思考某事。"},{"en":"A principal should give serious consideration to students’ safety concerns.","zh":"校長應認真考慮學生的安全憂慮。"},{"en":"New ideas deserve serious consideration when they solve real problems.","zh":"當新想法解決真實問題，它們就值得認真考慮。"},{"en":"Dragon Boat Racing deserves serious consideration because it has sporting and cultural value.","zh":"龍舟競賽值得認真考慮，因為它有體育和文化價值。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"make room at the Olympic table","meaning":"在奧運舞台上騰出位置","examples":[{"en":"The IOC should make room at the Olympic table for Dragon Boat Racing.","zh":"國際奧委會應在奧運舞台上為龍舟競賽騰出位置。"},{"en":"To make room at the Olympic table means to give a sport a recognised place in the Olympic family.","zh":"在奧運舞台上騰出位置，意思是給一項運動在奧運大家庭中獲認可的位置。"},{"en":"A school may make room at the table for student voices during planning.","zh":"學校在規劃時可能為學生聲音騰出位置。"},{"en":"When an organisation makes room at the table, it allows new groups to take part seriously.","zh":"當組織騰出位置，它就讓新群體認真參與。"},{"en":"Making room at the Olympic table would show that tradition and innovation can sit together.","zh":"在奧運舞台上騰出位置，會顯示傳統和創新可以並存。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"appeal to youth","meaning":"吸引年輕人","examples":[{"en":"The sport appeals to youth.","zh":"這項運動吸引年輕人。"},{"en":"To appeal to youth means to attract young people’s interest, energy, and imagination.","zh":"吸引年輕人，意思是引起年輕人的興趣、活力和想像。"},{"en":"A school campaign appeals to youth when it uses real student concerns.","zh":"當學校宣傳使用真實學生關注，它就能吸引年輕人。"},{"en":"Sports appeal to youth when they are active, social, and easy to share online.","zh":"當運動活躍、具社交性並容易在網上分享，就會吸引年輕人。"},{"en":"Dragon Boat Racing appeals to youth because it combines teamwork with excitement.","zh":"龍舟競賽吸引年輕人，因為它結合團隊合作和刺激感。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"advance gender equality","meaning":"推動性別平等","examples":[{"en":"Dragon Boat Racing can advance gender equality.","zh":"龍舟競賽可以推動性別平等。"},{"en":"To advance gender equality means to help fair treatment between men and women move forward.","zh":"推動性別平等，意思是幫助男性和女性之間的公平待遇向前發展。"},{"en":"A company can advance gender equality by giving equal promotion opportunities.","zh":"公司可以透過提供平等晉升機會來推動性別平等。"},{"en":"Mixed teams can advance gender equality when every member’s contribution matters.","zh":"當每位成員的貢獻都重要，男女混合隊可以推動性別平等。"},{"en":"Dragon Boat Racing advances gender equality by allowing men and women to race together.","zh":"龍舟競賽透過讓男性和女性一起比賽來推動性別平等。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"offer the media","meaning":"為傳媒提供","examples":[{"en":"The sport offers the media a vivid global story.","zh":"這項運動為傳媒提供一個生動的全球故事。"},{"en":"To offer the media something means to give reporters and broadcasters material they can report or present.","zh":"為傳媒提供某事，意思是給記者和廣播機構可報道或呈現的素材。"},{"en":"A community clean-up offers the media a positive story about local action.","zh":"社區清潔活動為傳媒提供一個關於本地行動的正面故事。"},{"en":"Events offer the media strong stories when they include people, conflict, colour, and meaning.","zh":"當活動包括人物、衝突、色彩和意義，它就為傳媒提供強故事。"},{"en":"Dragon Boat Racing offers the media both a race and a cultural journey.","zh":"龍舟競賽為傳媒同時提供一場比賽和一段文化旅程。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"a vivid global story","meaning":"生動的全球故事","examples":[{"en":"Dragon Boat Racing offers the media a vivid global story.","zh":"龍舟競賽為傳媒提供一個生動的全球故事。"},{"en":"A vivid global story is a clear, colourful story that can interest people across the world.","zh":"生動的全球故事，是清晰、有色彩並能吸引世界各地人們的故事。"},{"en":"A student climate project can become a vivid global story if it connects local action to worldwide concern.","zh":"如果學生氣候 project 把本地行動連接到全球關注，它可以成為生動的全球故事。"},{"en":"A vivid global story helps audiences understand why an event matters beyond one place.","zh":"生動的全球故事幫助觀眾理解活動為何不只對一個地方重要。"},{"en":"Dragon Boat Racing is a vivid global story because it joins heritage, teamwork, and international participation.","zh":"龍舟競賽是一個生動的全球故事，因為它結合文化傳承、團隊合作和國際參與。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"at their best","meaning":"處於最佳狀態","examples":[{"en":"The Olympics are at their best when they honour tradition and welcome new excellence.","zh":"當奧運尊重傳統並歡迎新的卓越表現時，它們處於最佳狀態。"},{"en":"At their best means in the strongest, most meaningful, or most successful form.","zh":"處於最佳狀態，意思是處於最強、最有意義或最成功的形式。"},{"en":"Schools are at their best when they care about both results and students’ growth.","zh":"當學校同時關心成績和學生成長，它們就處於最佳狀態。"},{"en":"Communities are at their best when people help one another during difficult times.","zh":"當人們在困難時互相幫助，社區就處於最佳狀態。"},{"en":"The Olympics are at their best when they unite old values with new achievements.","zh":"當奧運把舊價值與新成就結合，它就處於最佳狀態。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"honour tradition","meaning":"尊重傳統","examples":[{"en":"The Olympics should honour tradition.","zh":"奧運應該尊重傳統。"},{"en":"To honour tradition means to respect and preserve important customs from the past.","zh":"尊重傳統，意思是尊敬和保存過去的重要習俗。"},{"en":"A family honours tradition when it teaches children why a festival matters.","zh":"當家庭教孩子節日為何重要，它就是在尊重傳統。"},{"en":"Schools can honour tradition by explaining old ceremonies instead of repeating them blindly.","zh":"學校可以透過解釋舊典禮，而不是盲目重複，來尊重傳統。"},{"en":"The Olympics can honour tradition while still adding new sports.","zh":"奧運可以尊重傳統，同時仍加入新運動。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"welcome new forms of","meaning":"歡迎新的……形式","examples":[{"en":"The Olympics should welcome new forms of human excellence.","zh":"奧運應該歡迎新的人類卓越表現形式。"},{"en":"To welcome new forms of something means to accept fresh ways in which that thing appears.","zh":"歡迎新的某種形式，意思是接受某事出現的新方式。"},{"en":"A school can welcome new forms of learning, such as project work and discussion.","zh":"學校可以歡迎新的學習形式，例如 project work 和討論。"},{"en":"Communities grow when they welcome new forms of culture without forgetting old ones.","zh":"當社區歡迎新的文化形式而不忘記舊文化，它就會成長。"},{"en":"The Olympics welcome new forms of excellence when they recognise sports with modern energy.","zh":"當奧運認可具有現代活力的運動，它就是歡迎新的卓越形式。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"human excellence","meaning":"人類卓越表現","examples":[{"en":"Dragon Boat Racing shows a new form of human excellence.","zh":"龍舟競賽展示一種新的人類卓越表現。"},{"en":"Human excellence means the best abilities people can show, such as strength, skill, courage, or cooperation.","zh":"人類卓越表現，意思是人能展現的最佳能力，例如力量、技巧、勇氣或合作。"},{"en":"A rescue team shows human excellence when members risk themselves to save others.","zh":"當救援隊員冒險救人，他們就展現人類卓越表現。"},{"en":"Sports show human excellence not only through victory, but through discipline and respect.","zh":"運動不只透過勝利展現人類卓越表現，也透過紀律和尊重展現。"},{"en":"Dragon Boat Racing shows human excellence through shared rhythm and collective strength.","zh":"龍舟競賽透過共享節奏和集體力量展現人類卓越表現。"}],"source":"2020 Q5.pdf","sourcePage":14},{"front":"I would be grateful if","meaning":"如蒙……我將十分感激","examples":[{"en":"I would be grateful if the Committee could explore a demonstration event.","zh":"如蒙委員會探討示範項目，我將十分感激。"},{"en":"I would be grateful if is a polite way to ask someone to do something.","zh":"如蒙……我將十分感激，是禮貌地請求某人做某事的說法。"},{"en":"I would be grateful if the school could reply before Friday.","zh":"如蒙學校能在星期五前回覆，我將十分感激。"},{"en":"This phrase softens a request while still making the writer’s wish clear.","zh":"這個短語令請求較溫和，同時仍清楚表達作者希望。"},{"en":"In a formal letter, I would be grateful if sounds more respectful than a direct command.","zh":"在正式信件中，「如蒙……我將十分感激」比直接命令更有禮貌。"}],"source":"2020 Q5.pdf","sourcePage":15},{"front":"the Committee","meaning":"委員會","examples":[{"en":"The writer asks the Committee to explore a demonstration event.","zh":"作者請委員會探討示範項目。"},{"en":"The Committee means the official group responsible for discussing or deciding a matter.","zh":"委員會，是負責討論或決定某事的正式小組。"},{"en":"A school committee may decide how to use funds for student activities.","zh":"學校委員會可能決定如何使用學生活動資金。"},{"en":"The Committee should review evidence before making an important decision.","zh":"委員會在作出重要決定前應審視證據。"},{"en":"In this letter, the Committee is asked to consider Dragon Boat Racing seriously.","zh":"在這封信中，委員會被請求認真考慮龍舟競賽。"}],"source":"2020 Q5.pdf","sourcePage":15},{"front":"explore a demonstration event","meaning":"探討示範項目","examples":[{"en":"The Committee could explore a demonstration event for Dragon Boat Racing.","zh":"委員會可以為龍舟競賽探討示範項目。"},{"en":"To explore a demonstration event means to consider testing an event first before full inclusion.","zh":"探討示範項目，意思是在正式納入前先考慮試行一個項目。"},{"en":"A school may explore a demonstration event before adding a new sport to sports day.","zh":"學校可能在把新運動加入運動日前，先探討示範項目。"},{"en":"Demonstration events help organisers see whether rules, safety, and audience interest work well.","zh":"示範項目幫助主辦者了解規則、安全和觀眾興趣是否運作良好。"},{"en":"Exploring a demonstration event would let the IOC test Dragon Boat Racing carefully.","zh":"探討示範項目可以讓國際奧委會小心測試龍舟競賽。"}],"source":"2020 Q5.pdf","sourcePage":15},{"front":"consult international dragon boat bodies","meaning":"諮詢國際龍舟組織","examples":[{"en":"The Committee should consult international dragon boat bodies.","zh":"委員會應諮詢國際龍舟組織。"},{"en":"To consult international dragon boat bodies means to ask global dragon boat organisations for advice.","zh":"諮詢國際龍舟組織，意思是向全球龍舟組織尋求意見。"},{"en":"A school consults sports coaches before starting a new training programme.","zh":"學校在開始新訓練計劃前會諮詢體育教練。"},{"en":"Consulting expert bodies can prevent mistakes because organisers learn from experience.","zh":"諮詢專業組織可以避免錯誤，因為主辦者能從經驗中學習。"},{"en":"The IOC should consult international dragon boat bodies to design fair and safe formats.","zh":"國際奧委會應諮詢國際龍舟組織，以設計公平和安全的賽制。"}],"source":"2020 Q5.pdf","sourcePage":15},{"front":"international dragon boat bodies","meaning":"國際龍舟組織","examples":[{"en":"International dragon boat bodies could advise the IOC.","zh":"國際龍舟組織可以向國際奧委會提供意見。"},{"en":"International dragon boat bodies are organisations that govern, promote, or support dragon boat racing across countries.","zh":"國際龍舟組織，是在跨國層面管理、推廣或支持龍舟競賽的組織。"},{"en":"Sports bodies often write rules, train officials, and organise competitions.","zh":"體育組織通常制定規則、訓練裁判和舉辦比賽。"},{"en":"International dragon boat bodies can help because they understand safety, formats, and global participation.","zh":"國際龍舟組織能提供幫助，因為它們了解安全、賽制和全球參與。"},{"en":"The IOC would need advice from international dragon boat bodies before serious inclusion.","zh":"國際奧委會在認真納入前，需要國際龍舟組織的意見。"}],"source":"2020 Q5.pdf","sourcePage":15},{"front":"consider a mixed-team sprint format","meaning":"考慮男女混合短途賽制","examples":[{"en":"The IOC could consider a mixed-team sprint format.","zh":"國際奧委會可以考慮男女混合短途賽制。"},{"en":"To consider a mixed-team sprint format means to think about using short races with men and women in the same team.","zh":"考慮男女混合短途賽制，意思是思考使用男女同隊的短距離比賽。"},{"en":"A school may consider a mixed-team format to encourage boys and girls to cooperate.","zh":"學校可能考慮男女混合賽制，以鼓勵男生和女生合作。"},{"en":"Sprint formats can save time because races are short and clear.","zh":"短途賽制可以節省時間，因為比賽短而清晰。"},{"en":"A mixed-team sprint format could show speed, fairness, and equality together.","zh":"男女混合短途賽制可以同時展現速度、公平和平等。"}],"source":"2020 Q5.pdf","sourcePage":15},{"front":"as a first step","meaning":"作為第一步","examples":[{"en":"A mixed-team sprint format could be considered as a first step.","zh":"男女混合短途賽制可以作為第一步被考慮。"},{"en":"As a first step means as the first action in a longer process.","zh":"作為第一步，意思是在較長過程中的第一個行動。"},{"en":"A student may make a study timetable as a first step before revising.","zh":"學生可能先制定溫習時間表，作為第一步。"},{"en":"Organisations often test a small plan as a first step before making a big decision.","zh":"組織通常先測試小計劃，作為第一步，然後才作大決定。"},{"en":"Considering a mixed-team sprint format as a first step would let the IOC move carefully.","zh":"把男女混合短途賽制作為第一步來考慮，可以讓國際奧委會謹慎前進。"}],"source":"2020 Q5.pdf","sourcePage":15}],"dse/writing/part-b/2020/Q6":[{"front":"warning labels","meaning":"警告標籤","examples":[{"en":"Warning labels can help consumers recognise nutritional risks.","zh":"警告標籤可以幫助消費者識別營養風險。"},{"en":"Warning labels are signs that warn people about possible health risks.","zh":"警告標籤是提醒人們注意潛在健康風險的標誌。"},{"en":"A snack packet may carry warning labels if it is high in sugar or salt.","zh":"如果零食糖分或鹽分高，包裝上可能有警告標籤。"},{"en":"Warning labels help shoppers pause before buying unhealthy food.","zh":"警告標籤幫助購物者在購買不健康食物前停一停。"},{"en":"Without warning labels, many risks may stay hidden in small print.","zh":"沒有警告標籤，許多風險可能仍隱藏在細字之中。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"a small sign with a large public purpose","meaning":"小標誌，大公共用途","examples":[{"en":"A warning label is a small sign with a large public purpose.","zh":"警告標籤是一個小標誌，卻有大的公共用途。"},{"en":"This phrase means a simple notice can serve an important social aim.","zh":"這個短語意思是簡單提示可以服務重要的社會目標。"},{"en":"A tiny label on a drink can protect many children from too much sugar.","zh":"飲品上的小標籤可以保護許多孩子避免攝取過多糖分。"},{"en":"The sign is small, but its purpose is large because it guides public health.","zh":"標誌雖小，但用途很大，因為它引導公共健康。"},{"en":"A small sign with a large public purpose can change daily choices.","zh":"一個小標誌、大公共用途的設計可以改變日常選擇。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"supermarket shelves","meaning":"超級市場貨架","examples":[{"en":"Supermarket shelves are crowded with snacks and sweetened drinks.","zh":"超級市場貨架上擺滿零食和加糖飲品。"},{"en":"Supermarket shelves are the places where shops display food and products.","zh":"超級市場貨架是商店展示食物和產品的地方。"},{"en":"Shoppers see colourful boxes and bottles on supermarket shelves every day.","zh":"購物者每天在超級市場貨架上看見色彩鮮艷的盒子和瓶子。"},{"en":"Crowded supermarket shelves can make unhealthy choices seem normal.","zh":"擁擠的超級市場貨架可能令不健康選擇看似正常。"},{"en":"Clear labels help people choose more wisely from supermarket shelves.","zh":"清晰標籤幫助人們從超級市場貨架上作出更明智選擇。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"become crowded with","meaning":"充斥著","examples":[{"en":"Supermarket shelves have become crowded with unhealthy products.","zh":"超級市場貨架已充斥著不健康產品。"},{"en":"To become crowded with something means to be filled with many of those things.","zh":"充斥著某物意思是被大量同類東西填滿。"},{"en":"A school noticeboard may become crowded with posters before exams.","zh":"考試前，學校壁報板可能充斥著海報。"},{"en":"Shelves become crowded with unhealthy food when companies sell many similar snacks.","zh":"當公司出售大量相似零食時，貨架便會充斥著不健康食物。"},{"en":"When choices become crowded with advertisements, simple warnings become useful.","zh":"當選擇充斥著廣告時，簡單警告便變得有用。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"instant meals","meaning":"即食餐","examples":[{"en":"Instant meals are often high in salt or saturated fat.","zh":"即食餐通常鹽分或飽和脂肪高。"},{"en":"Instant meals are ready-made foods that can be cooked or heated quickly.","zh":"即食餐是可以快速煮熟或翻熱的現成食物。"},{"en":"Busy students may eat instant meals when they have little time to cook.","zh":"忙碌學生沒有太多時間煮飯時，可能會吃即食餐。"},{"en":"Eating instant meals too often can increase salt and fat intake.","zh":"太常吃即食餐可能增加鹽分和脂肪攝取。"},{"en":"Instant meals are convenient, but consumers should check their labels.","zh":"即食餐很方便，但消費者應查看標籤。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"sweetened drinks","meaning":"加糖飲品","examples":[{"en":"Sweetened drinks may contain large amounts of sugar.","zh":"加糖飲品可能含有大量糖分。"},{"en":"Sweetened drinks are drinks with added sugar or sweet flavouring.","zh":"加糖飲品是加入糖或甜味調味的飲料。"},{"en":"Bubble tea, soda, and bottled tea can be sweetened drinks.","zh":"珍珠奶茶、汽水和樽裝茶都可以是加糖飲品。"},{"en":"Drinking sweetened drinks daily may increase sugar intake without people noticing.","zh":"每天喝加糖飲品可能令人在不知不覺中攝取更多糖分。"},{"en":"Water is often a healthier choice than sweetened drinks.","zh":"水通常比加糖飲品更健康。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"unhealthy eating","meaning":"不健康飲食","examples":[{"en":"Unhealthy eating is no longer simply a matter of weak will.","zh":"不健康飲食不再只是意志薄弱的問題。"},{"en":"Unhealthy eating means eating too much food that harms the body over time.","zh":"不健康飲食是指長期進食過多有害身體的食物。"},{"en":"A person practises unhealthy eating if most meals are sugary, salty, or oily.","zh":"如果一個人大部分餐膳都高糖、高鹽或油膩，就是不健康飲食。"},{"en":"Unhealthy eating can lead to weight gain, tiredness, and long-term illness.","zh":"不健康飲食可能導致體重增加、疲倦和長期疾病。"},{"en":"Warning labels can help reduce unhealthy eating by making risks easier to see.","zh":"警告標籤令風險更容易看見，有助減少不健康飲食。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"no longer simply","meaning":"不再只是","examples":[{"en":"Unhealthy eating is no longer simply a matter of weak will.","zh":"不健康飲食不再只是意志薄弱的問題。"},{"en":"No longer simply means something has become more complex than before.","zh":"不再只是意思是某事比以前更加複雜。"},{"en":"School success is no longer simply about memorising facts.","zh":"學業成功不再只是背誦事實。"},{"en":"Food choice is no longer simply personal because marketing also shapes it.","zh":"食物選擇不再只是個人問題，因為市場推廣也會塑造它。"},{"en":"This phrase helps show that one explanation is not enough.","zh":"這個短語幫助顯示單一解釋並不足夠。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"a matter of","meaning":"關乎……的事","examples":[{"en":"It is also a matter of information, habit and marketing.","zh":"這也關乎資訊、習慣和市場推廣。"},{"en":"A matter of something means an issue connected with that thing.","zh":"A matter of something 意思是與某事有關的問題。"},{"en":"Healthy eating is a matter of price, time, knowledge, and choice.","zh":"健康飲食關乎價格、時間、知識和選擇。"},{"en":"If food labels are unclear, the problem becomes a matter of information.","zh":"如果食物標籤不清楚，問題就變成關乎資訊的事。"},{"en":"Calling it a matter of marketing shows that companies influence consumers.","zh":"稱它為關乎市場推廣的事，顯示公司會影響消費者。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"weak will","meaning":"意志薄弱","examples":[{"en":"Unhealthy eating is not always caused by weak will.","zh":"不健康飲食不一定由意志薄弱造成。"},{"en":"Weak will means poor self-control when facing temptation or difficulty.","zh":"意志薄弱是指面對誘惑或困難時自制力不足。"},{"en":"A tired worker may buy fast food, not because of weak will, but because of limited time.","zh":"疲倦的員工買快餐，未必因為意志薄弱，而可能因為時間有限。"},{"en":"Blaming weak will ignores prices, advertising, and food availability.","zh":"只責怪意志薄弱會忽略價格、廣告和食物供應。"},{"en":"Warning labels help because not every unhealthy choice comes from weak will.","zh":"警告標籤有幫助，因為不是每個不健康選擇都來自意志薄弱。"}],"source":"2020 Q6.pdf","sourcePage":1},{"front":"in response","meaning":"作為回應","examples":[{"en":"In response, some countries require warning labels on unhealthy products.","zh":"作為回應，一些國家要求在不健康產品上加上警告標籤。"},{"en":"In response means as an answer or reaction to a problem.","zh":"作為回應意思是對問題作出答案或反應。"},{"en":"In response to rising obesity, schools may offer healthier lunches.","zh":"作為對肥胖率上升的回應，學校可能提供較健康午餐。"},{"en":"Governments use warning labels in response to public health concerns.","zh":"政府使用警告標籤，是對公共健康憂慮作出回應。"},{"en":"This phrase shows that an action happens because something has already happened.","zh":"這個短語顯示某行動因先前發生的事情而出現。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"public health authorities","meaning":"公共衞生當局","examples":[{"en":"Public health authorities now require warning labels in some countries.","zh":"在一些國家，公共衞生當局現在要求使用警告標籤。"},{"en":"Public health authorities are official organisations that protect people’s health.","zh":"公共衞生當局是保護人民健康的官方組織。"},{"en":"Public health authorities may advise people to eat less sugar and salt.","zh":"公共衞生當局可能建議人們少吃糖和鹽。"},{"en":"They require labels when unhealthy food becomes a public concern.","zh":"當不健康食物成為公共問題時，它們便要求使用標籤。"},{"en":"Public health authorities focus on prevention, not only treatment.","zh":"公共衞生當局重視預防，而不只是治療。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"require warning labels on","meaning":"要求在……加上警告標籤","examples":[{"en":"Some countries require warning labels on products high in sugar.","zh":"一些國家要求在高糖產品上加上警告標籤。"},{"en":"To require warning labels on products means to make labels legally necessary.","zh":"要求在產品上加上警告標籤，意思是依法規定標籤必須出現。"},{"en":"A government may require warning labels on drinks with too much sugar.","zh":"政府可能要求在糖分過高的飲品上加上警告標籤。"},{"en":"This rule helps shoppers notice risks before they buy.","zh":"這條規則幫助購物者在購買前注意風險。"},{"en":"Companies may change recipes if labels are required on unhealthy products.","zh":"如果不健康產品必須加上標籤，公司可能會改變配方。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"high in sugar","meaning":"糖分高","examples":[{"en":"Some drinks are high in sugar.","zh":"有些飲品糖分高。"},{"en":"High in sugar means containing a large amount of sugar.","zh":"糖分高意思是含有大量糖。"},{"en":"A bottle of soda may be high in sugar even if it looks refreshing.","zh":"一樽汽水即使看起來清爽，也可能糖分高。"},{"en":"Foods high in sugar can increase calorie intake quickly.","zh":"糖分高的食物可以快速增加卡路里攝取。"},{"en":"A high-sugar warning helps consumers notice this risk.","zh":"高糖警告幫助消費者注意這個風險。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"saturated fat","meaning":"飽和脂肪","examples":[{"en":"Some snacks are high in saturated fat.","zh":"有些零食飽和脂肪高。"},{"en":"Saturated fat is a type of fat often found in butter, fatty meat, and fried food.","zh":"飽和脂肪是一種常見於牛油、肥肉和油炸食物中的脂肪。"},{"en":"Crisps and pastries may contain saturated fat.","zh":"薯片和酥皮糕點可能含有飽和脂肪。"},{"en":"Eating too much saturated fat may harm heart health over time.","zh":"長期攝取過多飽和脂肪可能損害心臟健康。"},{"en":"Warning labels can show when a product contains too much saturated fat.","zh":"警告標籤可以顯示產品是否含有過多飽和脂肪。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"high in salt","meaning":"鹽分高","examples":[{"en":"Instant noodles can be high in salt.","zh":"即食麵可能鹽分高。"},{"en":"High in salt means containing a large amount of salt or sodium.","zh":"鹽分高意思是含有大量鹽或鈉。"},{"en":"Soup, crisps, and instant meals may be high in salt.","zh":"湯、薯片和即食餐都可能鹽分高。"},{"en":"Eating food high in salt too often may affect blood pressure.","zh":"太常吃鹽分高的食物可能影響血壓。"},{"en":"A high-salt label helps shoppers compare products quickly.","zh":"高鹽標籤幫助購物者快速比較產品。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"consumers","meaning":"消費者","examples":[{"en":"Warning labels help consumers make healthier choices.","zh":"警告標籤幫助消費者作出較健康選擇。"},{"en":"Consumers are people who buy or use goods and services.","zh":"消費者是購買或使用商品和服務的人。"},{"en":"Parents, students, and office workers are all consumers in a supermarket.","zh":"父母、學生和上班族在超級市場都是消費者。"},{"en":"Consumers need clear information because packaging can be misleading.","zh":"消費者需要清晰資訊，因為包裝可能令人誤解。"},{"en":"When consumers understand labels, they can choose more carefully.","zh":"當消費者明白標籤時，他們可以更謹慎選擇。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"recognise nutritional risks","meaning":"識別營養風險","examples":[{"en":"Consumers can recognise nutritional risks before buying the product.","zh":"消費者可以在購買產品前識別營養風險。"},{"en":"To recognise nutritional risks means to notice possible health problems in food content.","zh":"識別營養風險意思是注意食物成分中的潛在健康問題。"},{"en":"A shopper recognises nutritional risks when they see a high-sugar warning.","zh":"購物者看見高糖警告時，就是在識別營養風險。"},{"en":"Recognising risks early can stop careless purchases.","zh":"及早識別風險可以阻止不經意購買。"},{"en":"Labels make it easier to recognise nutritional risks without expert knowledge.","zh":"標籤令人在沒有專業知識下也較容易識別營養風險。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"nutritional risks","meaning":"營養風險","examples":[{"en":"Warning labels make nutritional risks easier to notice.","zh":"警告標籤令營養風險更容易被注意。"},{"en":"Nutritional risks are possible health problems caused by food content.","zh":"營養風險是由食物成分造成的潛在健康問題。"},{"en":"Too much sugar, salt, or saturated fat can create nutritional risks.","zh":"過多糖、鹽或飽和脂肪都可以造成營養風險。"},{"en":"Nutritional risks matter because they may build up through daily eating.","zh":"營養風險很重要，因為它們可能透過日常飲食累積。"},{"en":"Clear labels turn hidden nutritional risks into visible warnings.","zh":"清晰標籤把隱藏的營養風險變成可見警告。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"before the packet reaches the checkout","meaning":"在付款前","examples":[{"en":"Consumers can see the warning before the packet reaches the checkout.","zh":"消費者可以在包裝到達收銀處前看見警告。"},{"en":"This phrase means shoppers notice the warning before paying.","zh":"這個短語意思是購物者在付款前注意到警告。"},{"en":"A parent may return a sugary snack before the packet reaches the checkout.","zh":"家長可能在付款前把高糖零食放回貨架。"},{"en":"Seeing risks early gives consumers time to change their choice.","zh":"及早看見風險讓消費者有時間改變選擇。"},{"en":"Once the packet reaches the checkout, the decision is harder to reverse.","zh":"一旦商品到了收銀處，決定便較難改變。"}],"source":"2020 Q6.pdf","sourcePage":2},{"front":"checkout","meaning":"收銀處；結帳處","examples":[{"en":"The warning appears before the product reaches the checkout.","zh":"警告在產品到達收銀處前出現。"},{"en":"A checkout is the place where shoppers pay for goods.","zh":"收銀處是購物者付款的地方。"},{"en":"Long queues often form near the checkout after school or work.","zh":"放學或下班後，收銀處附近常出現長隊。"},{"en":"If a warning is seen before checkout, shoppers can still choose another product.","zh":"如果在結帳前看見警告，購物者仍可選擇另一件產品。"},{"en":"Labels are most useful before the checkout, not after payment.","zh":"標籤在付款前最有用，而不是付款後。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"strongly believe that","meaning":"堅信","examples":[{"en":"I strongly believe that warning labels are effective.","zh":"我堅信警告標籤是有效的。"},{"en":"Strongly believe that means to have a firm opinion about something.","zh":"堅信某事意思是對某事有堅定看法。"},{"en":"I strongly believe that students learn better with clear examples.","zh":"我堅信學生透過清晰例子會學得更好。"},{"en":"Writers use this phrase to present a confident argument.","zh":"作者使用這個短語來提出有信心的論點。"},{"en":"A strong belief should still be supported by reasons and evidence.","zh":"堅定信念仍應由理由和證據支持。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"effective in changing","meaning":"有效改變","examples":[{"en":"Warning labels are effective in changing people’s eating habits.","zh":"警告標籤能有效改變人們的飲食習慣。"},{"en":"Effective in changing means successful in causing a real difference.","zh":"有效改變意思是成功造成真正差異。"},{"en":"Daily reminders can be effective in changing study habits.","zh":"每日提醒可以有效改變學習習慣。"},{"en":"Labels are effective in changing choices when they appear at the buying moment.","zh":"標籤在購買一刻出現時，能有效改變選擇。"},{"en":"Something is not effective in changing behaviour if people never notice it.","zh":"如果人們從不注意到某物，它就不能有效改變行為。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"eating habits","meaning":"飲食習慣","examples":[{"en":"Warning labels may gradually change eating habits.","zh":"警告標籤可能逐漸改變飲食習慣。"},{"en":"Eating habits are the usual ways people choose, prepare, and eat food.","zh":"飲食習慣是人們選擇、準備和進食食物的慣常方式。"},{"en":"A student’s eating habits may include buying a sweet drink after school.","zh":"學生的飲食習慣可能包括放學後買加糖飲品。"},{"en":"Eating habits are hard to change because they are repeated daily.","zh":"飲食習慣難以改變，因為它們每天重複。"},{"en":"Small reminders can slowly guide people toward healthier eating habits.","zh":"小提醒可以慢慢引導人們建立較健康的飲食習慣。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"not because…, but because…","meaning":"不是因為……，而是因為……","examples":[{"en":"Labels work not because they are magical, but because they interrupt careless choices.","zh":"標籤有效不是因為它們有魔法，而是因為它們打斷不經意的選擇。"},{"en":"This structure contrasts a false reason with the real reason.","zh":"這個結構把錯誤原因和真正原因作對比。"},{"en":"Students improve not because exams are easy, but because they practise daily.","zh":"學生進步不是因為考試容易，而是因為他們每天練習。"},{"en":"Labels help not because they force people, but because they inform them.","zh":"標籤有幫助不是因為它們強迫人，而是因為它們提供資訊。"},{"en":"This pattern makes an argument clearer and more persuasive.","zh":"這個句式令論點更清晰、更有說服力。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"turn someone into","meaning":"將某人變成","examples":[{"en":"Warning labels cannot magically turn everyone into a nutritionist.","zh":"警告標籤不能神奇地將每個人變成營養師。"},{"en":"To turn someone into something means to change them into that kind of person.","zh":"將某人變成某種人，意思是使他成為那類人。"},{"en":"One lesson cannot turn a beginner into an expert.","zh":"一堂課不能把初學者變成專家。"},{"en":"Labels do not turn shoppers into experts, but they give simple guidance.","zh":"標籤不會把購物者變成專家，但會提供簡單指引。"},{"en":"This phrase often shows a big change that may be unrealistic.","zh":"這個短語常顯示一種可能不現實的巨大改變。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"nutritionist","meaning":"營養師","examples":[{"en":"A warning label does not turn everyone into a nutritionist.","zh":"警告標籤不會把每個人變成營養師。"},{"en":"A nutritionist is a person trained to give advice about food and health.","zh":"營養師是受訓提供食物和健康建議的人。"},{"en":"A school may invite a nutritionist to teach students about balanced meals.","zh":"學校可能邀請營養師教學生認識均衡膳食。"},{"en":"Most shoppers are not nutritionists, so labels must be simple.","zh":"大多數購物者不是營養師，所以標籤必須簡單。"},{"en":"Warning labels help ordinary people make choices without becoming nutritionists.","zh":"警告標籤幫助普通人作選擇，而不需要成為營養師。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"interrupt careless choices","meaning":"打斷不經意的選擇","examples":[{"en":"Warning labels interrupt careless choices at the point of purchase.","zh":"警告標籤在購買點打斷不經意的選擇。"},{"en":"To interrupt careless choices means to stop people before they buy without thinking.","zh":"打斷不經意的選擇意思是在人們未經思考購買前阻止一下。"},{"en":"A red warning can interrupt careless choices when a student reaches for crisps.","zh":"當學生伸手拿薯片時，紅色警告可以打斷不經意的選擇。"},{"en":"This interruption matters because many food choices are quick and automatic.","zh":"這種打斷很重要，因為許多飲食選擇快速而自動。"},{"en":"Labels interrupt careless choices by creating a moment of attention.","zh":"標籤透過製造注意的一刻來打斷不經意的選擇。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"reshape the food environment","meaning":"重塑食物環境","examples":[{"en":"Warning labels can reshape the food environment.","zh":"警告標籤可以重塑食物環境。"},{"en":"To reshape the food environment means to change the choices and signals around food.","zh":"重塑食物環境意思是改變圍繞食物的選擇和訊號。"},{"en":"Clear labels reshape the food environment by making unhealthy products stand out.","zh":"清晰標籤令不健康產品突出，從而重塑食物環境。"},{"en":"If companies reduce sugar, the whole food environment becomes healthier.","zh":"如果公司減糖，整個食物環境會變得較健康。"},{"en":"Reshaping the food environment helps people without blaming them alone.","zh":"重塑食物環境能幫助人們，而不是只責怪個人。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"give families a simple language for","meaning":"為家庭提供……的簡單語言","examples":[{"en":"Labels give families a simple language for healthier decisions.","zh":"標籤為家庭提供作出較健康決定的簡單語言。"},{"en":"This phrase means labels give families easy words or signs to discuss choices.","zh":"這個短語意思是標籤給家庭容易使用的詞語或標誌去討論選擇。"},{"en":"A parent can say, “This has a high-sugar warning,” instead of giving a long lecture.","zh":"家長可以說「這個有高糖警告」，而不用長篇說教。"},{"en":"Simple language helps families talk about food without confusion.","zh":"簡單語言幫助家庭清楚討論食物。"},{"en":"Labels give families a simple language for care, not blame.","zh":"標籤為家庭提供關心而非責備的簡單語言。"}],"source":"2020 Q6.pdf","sourcePage":3},{"front":"healthier decisions","meaning":"較健康的決定","examples":[{"en":"Families can use labels to make healthier decisions.","zh":"家庭可以使用標籤作出較健康的決定。"},{"en":"Healthier decisions are choices that are better for the body over time.","zh":"較健康的決定是長遠而言對身體較好的選擇。"},{"en":"Choosing water instead of soda is a healthier decision.","zh":"選擇水而不是汽水，就是較健康的決定。"},{"en":"Healthier decisions become easier when risks are shown clearly.","zh":"當風險清楚顯示時，較健康的決定會更容易作出。"},{"en":"Labels do not guarantee perfect choices, but they support healthier decisions.","zh":"標籤不能保證完美選擇，但能支持較健康的決定。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"hidden technical issue","meaning":"隱藏的技術性問題","examples":[{"en":"Nutrition often feels like a hidden technical issue.","zh":"營養常令人感覺像隱藏的技術性問題。"},{"en":"A hidden technical issue is a difficult problem that ordinary people may not easily understand.","zh":"隱藏的技術性問題是普通人不易理解的困難問題。"},{"en":"Small numbers in a nutrition table can make sugar intake feel like a hidden technical issue.","zh":"營養資料表中的細小數字可能令糖分攝取感覺像隱藏的技術性問題。"},{"en":"When information feels technical, shoppers may ignore it.","zh":"當資訊感覺很技術性，購物者可能會忽略它。"},{"en":"Warning labels make a hidden technical issue easier to understand.","zh":"警告標籤令隱藏的技術性問題較容易理解。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"immediate everyday choice","meaning":"即時的日常選擇","examples":[{"en":"Warning labels turn nutrition into an immediate everyday choice.","zh":"警告標籤把營養變成即時的日常選擇。"},{"en":"An immediate everyday choice is a decision people make now in ordinary life.","zh":"即時的日常選擇是人們在普通生活中當下作出的決定。"},{"en":"Choosing a drink at lunch is an immediate everyday choice.","zh":"午餐時選擇飲品就是即時的日常選擇。"},{"en":"Labels make nutrition immediate because the warning appears at the buying moment.","zh":"標籤令營養變得即時，因為警告在購買一刻出現。"},{"en":"Health becomes practical when it is linked to immediate everyday choices.","zh":"當健康連繫到即時的日常選擇時，它就變得實際。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"buy after calmly calculating","meaning":"在冷靜計算後購買","examples":[{"en":"Most consumers do not buy food after calmly calculating every nutrient.","zh":"大多數消費者不會在冷靜計算每種營養素後才買食物。"},{"en":"To buy after calmly calculating means to purchase only after carefully working out details.","zh":"在冷靜計算後購買，意思是仔細算清細節後才購買。"},{"en":"Few shoppers buy after calmly calculating salt, sugar, fat, and calories.","zh":"很少購物者會在冷靜計算鹽、糖、脂肪和卡路里後才購買。"},{"en":"People often buy quickly, so simple warnings are more useful than complex numbers.","zh":"人們常快速購買，所以簡單警告比複雜數字更有用。"},{"en":"Labels help those who do not buy after calmly calculating.","zh":"標籤能幫助那些不會在冷靜計算後購買的人。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"grams of sugar","meaning":"糖的克數","examples":[{"en":"Few shoppers calculate grams of sugar before buying a drink.","zh":"很少購物者會在買飲品前計算糖的克數。"},{"en":"Grams of sugar show the amount of sugar in a food or drink.","zh":"糖的克數顯示食物或飲品中的糖分份量。"},{"en":"A bottle may contain many grams of sugar even if it tastes only slightly sweet.","zh":"一樽飲品即使只帶少許甜味，也可能含有很多克糖。"},{"en":"Checking grams of sugar helps people understand hidden sweetness.","zh":"查看糖的克數幫助人了解隱藏甜味。"},{"en":"Warning labels are useful when shoppers do not read exact grams of sugar.","zh":"當購物者不閱讀準確糖的克數時，警告標籤便很有用。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"percentages of fat","meaning":"脂肪百分比","examples":[{"en":"Consumers rarely check percentages of fat while shopping quickly.","zh":"消費者快速購物時很少查看脂肪百分比。"},{"en":"Percentages of fat show how much of a product is fat.","zh":"脂肪百分比顯示產品中有多少比例是脂肪。"},{"en":"A biscuit packet may list percentages of fat in a small nutrition table.","zh":"餅乾包裝可能在細小的營養資料表中列出脂肪百分比。"},{"en":"Fast shopping makes people less likely to study percentages of fat.","zh":"快速購物令人較少仔細研究脂肪百分比。"},{"en":"A warning label can summarise the risk more quickly than percentages of fat.","zh":"警告標籤比脂肪百分比更快概括風險。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"daily sodium limits","meaning":"每日鈉攝取上限","examples":[{"en":"Most shoppers do not calculate daily sodium limits.","zh":"大多數購物者不會計算每日鈉攝取上限。"},{"en":"Daily sodium limits are the recommended maximum amount of sodium people should have each day.","zh":"每日鈉攝取上限是人每天建議攝取鈉的最高份量。"},{"en":"Instant noodles may contain much of a person’s daily sodium limit.","zh":"即食麵可能已含有一個人每日鈉攝取上限的大部分。"},{"en":"If shoppers ignore daily sodium limits, they may eat too much salt.","zh":"如果購物者忽略每日鈉攝取上限，他們可能吃太多鹽。"},{"en":"High-salt labels help people who do not know their daily sodium limits.","zh":"高鹽標籤能幫助不知道每日鈉攝取上限的人。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"more often than not","meaning":"往往；多數情況下","examples":[{"en":"More often than not, consumers shop quickly.","zh":"多數情況下，消費者購物很快。"},{"en":"More often than not means usually or in most cases.","zh":"More often than not 意思是通常或在大多數情況下。"},{"en":"More often than not, students buy snacks between lessons without reading labels.","zh":"多數情況下，學生在課堂之間買零食時不會閱讀標籤。"},{"en":"This phrase shows that a behaviour happens frequently, though not always.","zh":"這個短語顯示某行為經常發生，但並非永遠如此。"},{"en":"More often than not, simple information works better than detailed calculations.","zh":"往往簡單資訊比詳細計算更有效。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"respond to taste","meaning":"受味道影響","examples":[{"en":"Consumers often respond to taste and attractive packaging.","zh":"消費者常受味道和吸引人的包裝影響。"},{"en":"To respond to taste means to choose food because its flavour attracts you.","zh":"受味道影響意思是因食物味道吸引而選擇它。"},{"en":"A child may respond to taste and choose sweet cereal over plain oats.","zh":"孩子可能受味道影響，選擇甜早餐穀物而不是原味燕麥。"},{"en":"Taste strongly affects buying because people want immediate pleasure.","zh":"味道強烈影響購買，因為人們想得到即時愉悅。"},{"en":"Warning labels remind consumers to think beyond taste.","zh":"警告標籤提醒消費者不要只考慮味道。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"attractive packaging","meaning":"吸引人的包裝","examples":[{"en":"Attractive packaging can make unhealthy food look harmless.","zh":"吸引人的包裝可以令不健康食物看起來無害。"},{"en":"Attractive packaging means colourful or pleasing wrapping that draws attention.","zh":"吸引人的包裝是指色彩鮮艷或令人喜歡、能吸引注意的包裝。"},{"en":"Cartoon characters on a cereal box are a form of attractive packaging.","zh":"早餐穀物盒上的卡通人物就是吸引人的包裝。"},{"en":"Attractive packaging can hide nutritional risks by making food look fun.","zh":"吸引人的包裝可以令食物看起來有趣，從而掩蓋營養風險。"},{"en":"Clear warnings balance the power of attractive packaging.","zh":"清晰警告可以平衡吸引人的包裝的力量。"}],"source":"2020 Q6.pdf","sourcePage":4},{"front":"chocolate cereal","meaning":"朱古力早餐穀物","examples":[{"en":"A chocolate cereal can look cheerful and child-friendly.","zh":"朱古力早餐穀物可以看起來令人愉快又適合兒童。"},{"en":"Chocolate cereal is breakfast cereal with chocolate flavour or added cocoa and sugar.","zh":"朱古力早餐穀物是有朱古力味或加入可可和糖的早餐穀物。"},{"en":"Children may ask for chocolate cereal because the box looks fun.","zh":"孩子可能因盒子看起來有趣而想買朱古力早餐穀物。"},{"en":"Chocolate cereal can contain more sugar than parents expect.","zh":"朱古力早餐穀物的糖分可能比父母預期更多。"},{"en":"A warning label helps families judge chocolate cereal more carefully.","zh":"警告標籤幫助家庭更謹慎判斷朱古力早餐穀物。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"look cheerful","meaning":"看起來令人愉快","examples":[{"en":"A chocolate cereal can look cheerful on the shelf.","zh":"朱古力早餐穀物在貨架上可以看起來令人愉快。"},{"en":"To look cheerful means to appear bright, happy, and pleasant.","zh":"看起來令人愉快意思是外觀看似明亮、開心和吸引。"},{"en":"A colourful snack packet may look cheerful even if it is unhealthy.","zh":"色彩鮮艷的零食包裝即使不健康，也可能看起來令人愉快。"},{"en":"Products look cheerful to attract children and busy shoppers.","zh":"產品看起來令人愉快，是為了吸引孩子和忙碌購物者。"},{"en":"Looking cheerful does not mean a food is nutritious.","zh":"看起來令人愉快不代表食物有營養。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"energy drink","meaning":"能量飲品","examples":[{"en":"An energy drink can look sporty.","zh":"能量飲品可以看起來有運動感。"},{"en":"An energy drink is a drink marketed as giving people more energy or alertness.","zh":"能量飲品是被宣傳為能令人更有精力或更清醒的飲料。"},{"en":"Students may buy an energy drink before revision or sports practice.","zh":"學生可能在溫習或運動練習前買能量飲品。"},{"en":"Some energy drinks contain high sugar or caffeine.","zh":"有些能量飲品含有高糖分或咖啡因。"},{"en":"A sporty image can make an energy drink seem healthier than it is.","zh":"運動形象可以令能量飲品看起來比實際更健康。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"look sporty","meaning":"看起來有運動感","examples":[{"en":"An energy drink can look sporty and healthy.","zh":"能量飲品可以看起來有運動感又健康。"},{"en":"To look sporty means to appear connected with fitness, strength, or exercise.","zh":"看起來有運動感意思是外觀看似與健身、力量或運動有關。"},{"en":"A bottle with a running figure may look sporty.","zh":"有跑步人像的瓶子可能看起來有運動感。"},{"en":"Products look sporty to make consumers think of health and performance.","zh":"產品看起來有運動感，是為了令人聯想到健康和表現。"},{"en":"Looking sporty does not prove that a drink is good for the body.","zh":"看起來有運動感並不能證明飲品對身體有益。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"packet of crisps","meaning":"一包薯片","examples":[{"en":"A packet of crisps can look harmless.","zh":"一包薯片可以看起來無害。"},{"en":"A packet of crisps is a bag of thin fried potato snacks.","zh":"一包薯片是指一袋薄薄的油炸馬鈴薯零食。"},{"en":"A student may buy a packet of crisps during recess.","zh":"學生可能在小息時買一包薯片。"},{"en":"A packet of crisps may contain high salt or saturated fat.","zh":"一包薯片可能含有高鹽或飽和脂肪。"},{"en":"Warning labels remind shoppers that a packet of crisps is not always a light snack.","zh":"警告標籤提醒購物者，一包薯片不一定只是輕便零食。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"look harmless","meaning":"看起來無害","examples":[{"en":"A packet of crisps can look harmless.","zh":"一包薯片可以看起來無害。"},{"en":"To look harmless means to seem safe or unlikely to cause damage.","zh":"看起來無害意思是似乎安全或不會造成傷害。"},{"en":"A small sweet drink may look harmless because the bottle is tiny.","zh":"一小樽甜飲品可能因瓶子很小而看起來無害。"},{"en":"Food can look harmless when the health risk is not obvious.","zh":"當健康風險不明顯時，食物可以看起來無害。"},{"en":"Looking harmless is different from being healthy.","zh":"看起來無害和真正健康並不相同。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"all the while","meaning":"與此同時","examples":[{"en":"All the while, the health cost remains hidden.","zh":"與此同時，健康代價仍然隱藏。"},{"en":"All the while means during the whole time something else is happening.","zh":"與此同時意思是在另一件事發生的整段時間中。"},{"en":"The packet looks fun; all the while, its sugar level is very high.","zh":"包裝看起來有趣；與此同時，它的糖分非常高。"},{"en":"This phrase helps show a hidden problem behind an attractive surface.","zh":"這個短語幫助顯示吸引外表背後的隱藏問題。"},{"en":"All the while, consumers may be influenced without noticing it.","zh":"與此同時，消費者可能在不知不覺中受影響。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"health cost","meaning":"健康代價","examples":[{"en":"The health cost remains buried in a small nutrition table.","zh":"健康代價仍然隱藏在細小的營養資料表中。"},{"en":"Health cost means the harm a choice may bring to the body.","zh":"健康代價是指一個選擇可能帶給身體的傷害。"},{"en":"The health cost of daily sugary drinks may appear years later.","zh":"每天喝含糖飲品的健康代價可能多年後才出現。"},{"en":"If the health cost is hidden, people may choose carelessly.","zh":"如果健康代價被隱藏，人們可能會隨便選擇。"},{"en":"Warning labels make the health cost easier to notice immediately.","zh":"警告標籤令健康代價更容易即時看見。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"remain buried in","meaning":"仍然隱藏在","examples":[{"en":"The health cost remains buried in a small nutrition table.","zh":"健康代價仍然隱藏在細小的營養資料表中。"},{"en":"To remain buried in something means to stay hidden inside it.","zh":"仍然隱藏在某處，意思是繼續藏在其中而不明顯。"},{"en":"Important information may remain buried in long terms and conditions.","zh":"重要資訊可能仍然隱藏在冗長條款中。"},{"en":"Nutritional risk remains buried in small print when labels are unclear.","zh":"當標籤不清楚，營養風險便仍然隱藏在細字中。"},{"en":"A warning label prevents key facts from remaining buried in details.","zh":"警告標籤防止關鍵事實仍然隱藏在細節裏。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"nutrition table","meaning":"營養資料表","examples":[{"en":"The nutrition table is often printed in small letters.","zh":"營養資料表通常以細小字體印刷。"},{"en":"A nutrition table lists the nutrients in a food, such as sugar, salt, and fat.","zh":"營養資料表列出食物中的營養成分，例如糖、鹽和脂肪。"},{"en":"Shoppers can read the nutrition table to compare two drinks.","zh":"購物者可以閱讀營養資料表來比較兩款飲品。"},{"en":"Many people ignore the nutrition table because it looks technical.","zh":"許多人忽略營養資料表，因為它看起來很技術性。"},{"en":"Warning labels make the message clearer than a small nutrition table alone.","zh":"警告標籤比單靠細小營養資料表更能清楚傳達訊息。"}],"source":"2020 Q6.pdf","sourcePage":5},{"front":"clear warning label","meaning":"清晰的警告標籤","examples":[{"en":"A clear warning label changes the buying moment.","zh":"清晰的警告標籤會改變購買一刻。"},{"en":"A clear warning label is easy to see, read, and understand.","zh":"清晰的警告標籤是容易看見、閱讀和理解的標籤。"},{"en":"A red label saying “high in sugar” is a clear warning label.","zh":"寫著「高糖」的紅色標籤就是清晰的警告標籤。"},{"en":"Clear labels matter because shoppers often make quick decisions.","zh":"清晰標籤很重要，因為購物者常快速作決定。"},{"en":"An unclear label may exist on the packet but fail to help consumers.","zh":"不清晰的標籤即使存在於包裝上，也可能幫不到消費者。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"create a pause","meaning":"令人停一停想一想","examples":[{"en":"A warning label creates a pause before purchase.","zh":"警告標籤令人在購買前停一停想一想。"},{"en":"To create a pause means to make people stop briefly and think.","zh":"令人停一停想一想意思是使人短暫停止並思考。"},{"en":"A high-salt label can create a pause when a parent chooses noodles.","zh":"高鹽標籤可以令家長選麵時停一停想一想。"},{"en":"This pause matters because it interrupts automatic buying.","zh":"這一停很重要，因為它打斷自動購買。"},{"en":"A small pause can lead to a healthier decision.","zh":"小小停頓可以帶來較健康的決定。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"reach for","meaning":"伸手拿","examples":[{"en":"A student may reach for a bottled tea.","zh":"學生可能伸手拿一樽樽裝茶。"},{"en":"To reach for something means to stretch your hand toward it to take it.","zh":"伸手拿某物意思是把手伸向它，準備拿起。"},{"en":"A child may reach for sweets near the checkout.","zh":"孩子可能伸手拿收銀處附近的糖果。"},{"en":"People often reach for familiar snacks without thinking carefully.","zh":"人們常不加思索地伸手拿熟悉零食。"},{"en":"A warning label can stop someone just as they reach for a product.","zh":"警告標籤可以在某人伸手拿產品時阻止一下。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"bottled tea","meaning":"樽裝茶","examples":[{"en":"A bottled tea may carry a high-sugar warning.","zh":"樽裝茶可能帶有高糖警告。"},{"en":"Bottled tea is tea sold in a bottle, often with added sugar or flavouring.","zh":"樽裝茶是以瓶裝出售的茶，通常加入糖或調味。"},{"en":"Students may buy bottled tea because it feels lighter than soda.","zh":"學生可能買樽裝茶，因為它感覺比汽水清淡。"},{"en":"Some bottled tea contains more sugar than consumers expect.","zh":"有些樽裝茶的糖分比消費者預期更多。"},{"en":"A warning label helps shoppers judge bottled tea more carefully.","zh":"警告標籤幫助購物者更謹慎判斷樽裝茶。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"high-sugar warning","meaning":"高糖警告","examples":[{"en":"A student may notice a high-sugar warning and choose water instead.","zh":"學生可能注意到高糖警告，並改為選擇水。"},{"en":"A high-sugar warning tells consumers that a product contains too much sugar.","zh":"高糖警告告訴消費者產品含有過多糖分。"},{"en":"A high-sugar warning on a drink may surprise parents.","zh":"飲品上的高糖警告可能令家長驚訝。"},{"en":"The warning helps because sweetness is not always obvious from taste alone.","zh":"這種警告有幫助，因為單靠味道不一定能知道糖分。"},{"en":"A high-sugar warning can turn a quick choice into a thoughtful one.","zh":"高糖警告可以把快速選擇變成經思考的選擇。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"choose water instead","meaning":"改為選擇水","examples":[{"en":"A student may choose water instead of a sweetened drink.","zh":"學生可能改為選擇水，而不是加糖飲品。"},{"en":"To choose water instead means to pick water as the healthier alternative.","zh":"改為選擇水意思是把水作為較健康替代選擇。"},{"en":"After seeing a sugar warning, a teenager may choose water instead.","zh":"看見高糖警告後，青少年可能改為選擇水。"},{"en":"Choosing water instead reduces sugar intake immediately.","zh":"改為選擇水可以即時減少糖分攝取。"},{"en":"The phrase shows a clear change from a less healthy choice to a better one.","zh":"這個短語顯示從較不健康選擇轉向較好選擇。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"compare two brands of","meaning":"比較兩個品牌的……","examples":[{"en":"A parent may compare two brands of noodles.","zh":"家長可能比較兩個品牌的麵。"},{"en":"To compare two brands of something means to look at differences between two companies’ products.","zh":"比較兩個品牌的某物意思是查看兩家公司產品之間的差異。"},{"en":"A shopper may compare two brands of cereal by checking sugar levels.","zh":"購物者可能透過查看糖分來比較兩個品牌的早餐穀物。"},{"en":"Comparing brands helps consumers avoid the less healthy option.","zh":"比較品牌幫助消費者避免較不健康的選項。"},{"en":"Warning labels make it faster to compare two brands of the same food.","zh":"警告標籤令比較兩個品牌的同類食物更快捷。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"pick the one without","meaning":"選擇沒有……的那一款","examples":[{"en":"A parent may pick the one without a high-salt label.","zh":"家長可能選擇沒有高鹽標籤的那一款。"},{"en":"To pick the one without something means to choose the option that does not have it.","zh":"選擇沒有某物的那一款，意思是選沒有該特徵的選項。"},{"en":"A shopper may pick the one without added sugar.","zh":"購物者可能選擇沒有添加糖的那一款。"},{"en":"This choice reduces risk because the warning is absent.","zh":"這種選擇能降低風險，因為警告不存在。"},{"en":"Labels help people pick the one without the clearest health warning.","zh":"標籤幫助人們選擇沒有明顯健康警告的那一款。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"high-salt label","meaning":"高鹽標籤","examples":[{"en":"A parent may avoid noodles with a high-salt label.","zh":"家長可能避免選擇帶有高鹽標籤的麵。"},{"en":"A high-salt label warns that a product contains too much salt or sodium.","zh":"高鹽標籤警告產品含有過多鹽或鈉。"},{"en":"Instant soup may carry a high-salt label.","zh":"即食湯可能帶有高鹽標籤。"},{"en":"A high-salt label can help families reduce sodium intake.","zh":"高鹽標籤可以幫助家庭減少鈉攝取。"},{"en":"Without a high-salt label, shoppers may not notice the risk.","zh":"沒有高鹽標籤，購物者可能不會注意到風險。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"appear small","meaning":"看似微小","examples":[{"en":"These choices may appear small, but habits are built through repetition.","zh":"這些選擇可能看似微小，但習慣是透過重複建立的。"},{"en":"To appear small means to seem minor or unimportant at first.","zh":"看似微小意思是一開始似乎很小或不重要。"},{"en":"Choosing water once may appear small, but repeated choices matter.","zh":"選一次水可能看似微小，但重複的選擇很重要。"},{"en":"Small choices build habits because they happen every day.","zh":"小選擇會建立習慣，因為它們每天發生。"},{"en":"Something may appear small but still have long-term effects.","zh":"某事可能看似微小，卻仍有長遠影響。"}],"source":"2020 Q6.pdf","sourcePage":6},{"front":"built through repetition","meaning":"透過重複建立","examples":[{"en":"Habits are built through repetition.","zh":"習慣是透過重複建立的。"},{"en":"Built through repetition means formed by doing something again and again.","zh":"透過重複建立意思是一次又一次做某事而形成。"},{"en":"A student’s reading habit is built through repetition, not one long session.","zh":"學生的閱讀習慣是透過重複建立的，而不是靠一次長時間閱讀。"},{"en":"Healthy eating is built through repeated small choices.","zh":"健康飲食是透過重複的小選擇建立的。"},{"en":"Warning labels help because repeated reminders can shape habits.","zh":"警告標籤有幫助，因為反覆提醒可以塑造習慣。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"the more often…, the more likely…","meaning":"越經常……，就越有可能……","examples":[{"en":"The more often consumers are reminded, the more likely they are to change.","zh":"消費者越經常被提醒，就越有可能改變。"},{"en":"This structure shows that one increase causes another increase.","zh":"這個結構顯示一件事增加會導致另一件事增加。"},{"en":"The more often students practise, the more likely they are to improve.","zh":"學生越經常練習，就越有可能進步。"},{"en":"The more often shoppers see warnings, the more likely they are to think twice.","zh":"購物者越經常看見警告，就越有可能三思。"},{"en":"This pattern is useful for explaining cause and effect.","zh":"這個句式適合解釋因果關係。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"be reminded","meaning":"被提醒","examples":[{"en":"Consumers are reminded whenever they see a warning label.","zh":"消費者每次看見警告標籤都會被提醒。"},{"en":"To be reminded means to be made to remember or think about something again.","zh":"被提醒意思是被促使再次記起或思考某事。"},{"en":"A calendar note reminds students of a test date.","zh":"日曆提示會提醒學生測驗日期。"},{"en":"Warning labels remind shoppers that taste is not the only issue.","zh":"警告標籤提醒購物者味道不是唯一問題。"},{"en":"People make better choices when they are reminded at the right moment.","zh":"人們在適當時刻被提醒時，會作出更好選擇。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"associate certain products with risk","meaning":"將某些產品與風險聯繫起來","examples":[{"en":"Consumers may associate certain products with risk.","zh":"消費者可能將某些產品與風險聯繫起來。"},{"en":"To associate products with risk means to connect them mentally with possible harm.","zh":"將產品與風險聯繫起來，意思是在腦海中把產品和潛在傷害連起來。"},{"en":"A shopper may associate sugary drinks with risk after seeing repeated warnings.","zh":"購物者反覆看見警告後，可能把含糖飲品與風險聯繫起來。"},{"en":"This association can make people hesitate before buying.","zh":"這種聯想可以令人購買前猶豫。"},{"en":"Labels work slowly by helping consumers associate unhealthy products with risk.","zh":"標籤透過幫助消費者把不健康產品與風險聯繫起來，慢慢發揮作用。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"in this sense","meaning":"從這個意義上說","examples":[{"en":"In this sense, warning labels influence everyday decisions.","zh":"從這個意義上說，警告標籤會影響日常決定。"},{"en":"In this sense means from this particular point of view.","zh":"從這個意義上說，意思是從這個特定角度理解。"},{"en":"In this sense, a label is not just information but also guidance.","zh":"從這個意義上說，標籤不只是資訊，也是指引。"},{"en":"Writers use this phrase to explain how a previous idea should be understood.","zh":"作者使用這個短語來解釋前一個想法應如何理解。"},{"en":"In this sense, small warnings can have large effects.","zh":"從這個意義上說，小警告可以產生大影響。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"work by nudging","meaning":"透過輕推發揮作用","examples":[{"en":"Warning labels work by nudging consumers where decisions are made.","zh":"警告標籤在作出決定的地方透過輕推消費者發揮作用。"},{"en":"To work by nudging means to influence people gently rather than forcing them.","zh":"透過輕推發揮作用意思是溫和影響人，而不是強迫人。"},{"en":"A reminder near a recycling bin works by nudging people to recycle.","zh":"回收箱旁的提醒透過輕推人們回收發揮作用。"},{"en":"Labels nudge shoppers at the exact moment of choice.","zh":"標籤在選擇的一刻輕推購物者。"},{"en":"Nudging respects choice while making healthier behaviour more likely.","zh":"輕推尊重選擇，同時令較健康行為更可能出現。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"nudge consumers","meaning":"輕推消費者","examples":[{"en":"Labels can nudge consumers towards healthier choices.","zh":"標籤可以輕推消費者走向較健康選擇。"},{"en":"To nudge consumers means to gently guide shoppers without removing their freedom.","zh":"輕推消費者意思是溫和引導購物者，而不取消他們的自由。"},{"en":"A high-sugar label may nudge consumers to choose water.","zh":"高糖標籤可能輕推消費者選擇水。"},{"en":"Nudging works because people often need a small reminder, not a lecture.","zh":"輕推有效，因為人們常需要小提醒，而不是說教。"},{"en":"Labels nudge consumers, but the final decision remains theirs.","zh":"標籤輕推消費者，但最終決定仍屬於他們。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"where decisions are made","meaning":"在作出決定的地方","examples":[{"en":"Warning labels appear where decisions are made.","zh":"警告標籤出現在作出決定的地方。"},{"en":"Where decisions are made means the place or moment people choose what to do.","zh":"在作出決定的地方，意思是人們選擇做甚麼的位置或時刻。"},{"en":"Supermarket shelves are where many food decisions are made.","zh":"超級市場貨架就是許多飲食決定被作出的地方。"},{"en":"A reminder is most useful where decisions are made, not after the event.","zh":"提醒在作出決定的地方最有用，而不是事後。"},{"en":"Labels work because they meet shoppers where decisions are made.","zh":"標籤有效，因為它們在作出決定的地方遇見購物者。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"indirectly","meaning":"間接地","examples":[{"en":"Warning labels can change eating habits indirectly.","zh":"警告標籤可以間接地改變飲食習慣。"},{"en":"Indirectly means not by a straight or immediate action, but through another effect.","zh":"間接地意思是不是透過直接或即時行動，而是透過另一種影響。"},{"en":"Labels may indirectly improve diets by pushing companies to reduce sugar.","zh":"標籤可能透過推動公司減糖，間接地改善飲食。"},{"en":"A teacher indirectly builds confidence by praising effort.","zh":"老師透過稱讚努力間接地建立學生信心。"},{"en":"Indirect change can still be powerful over time.","zh":"間接改變隨時間仍可以很有力量。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"put pressure on","meaning":"向……施壓","examples":[{"en":"Warning labels put pressure on food manufacturers.","zh":"警告標籤向食品製造商施壓。"},{"en":"To put pressure on someone means to make them feel they should act or change.","zh":"向某人施壓意思是令他感到應該行動或改變。"},{"en":"Customer complaints put pressure on a restaurant to improve hygiene.","zh":"顧客投訴會向餐廳施壓，要求改善衞生。"},{"en":"Labels put pressure on companies because unhealthy products become visible.","zh":"標籤向公司施壓，因為不健康產品變得明顯。"},{"en":"Pressure can lead manufacturers to create healthier recipes.","zh":"壓力可以促使製造商創造較健康配方。"}],"source":"2020 Q6.pdf","sourcePage":7},{"front":"food manufacturers","meaning":"食品製造商","examples":[{"en":"Food manufacturers may reformulate products to avoid warnings.","zh":"食品製造商可能重新調整產品配方以避免警告。"},{"en":"Food manufacturers are companies that produce packaged food and drinks.","zh":"食品製造商是生產包裝食物和飲品的公司。"},{"en":"A food manufacturer may make biscuits, noodles, or bottled drinks.","zh":"食品製造商可能生產餅乾、麵或樽裝飲品。"},{"en":"Food manufacturers can improve public health by reducing sugar, salt, and fat.","zh":"食品製造商可以透過減糖、減鹽和減脂改善公共健康。"},{"en":"Warning labels influence food manufacturers as well as consumers.","zh":"警告標籤不但影響消費者，也影響食品製造商。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"social groups","meaning":"社群；社會群體","examples":[{"en":"Labels can also influence social groups such as schools and families.","zh":"標籤也可以影響學校和家庭等社群。"},{"en":"Social groups are groups of people connected by shared places, roles, or relationships.","zh":"社群是由共同地方、角色或關係連繫起來的一群人。"},{"en":"A class, family, or office can be a social group.","zh":"一個班、一個家庭或一間辦公室都可以是社群。"},{"en":"Labels influence social groups because people discuss food choices together.","zh":"標籤會影響社群，因為人們會一起討論食物選擇。"},{"en":"Healthy habits spread more easily when social groups support them.","zh":"當社群支持健康習慣時，健康習慣較容易擴散。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"in the eyes of the public","meaning":"在公眾眼中","examples":[{"en":"In the eyes of the public, several warnings make a product look unhealthy.","zh":"在公眾眼中，多個警告會令產品看起來不健康。"},{"en":"In the eyes of the public means in the opinion or view of ordinary people.","zh":"在公眾眼中意思是在普通人的看法或觀感中。"},{"en":"In the eyes of the public, a school should protect children’s health.","zh":"在公眾眼中，學校應保護兒童健康。"},{"en":"A product with many warnings may lose trust in the eyes of the public.","zh":"帶有多個警告的產品可能在公眾眼中失去信任。"},{"en":"This phrase is useful when discussing public image.","zh":"這個短語適合討論公眾形象。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"carrying several warnings","meaning":"帶有多個警告","examples":[{"en":"A product carrying several warnings looks visibly unhealthy.","zh":"帶有多個警告的產品看起來明顯不健康。"},{"en":"Carrying several warnings means having more than one warning label on the package.","zh":"帶有多個警告意思是包裝上有超過一個警告標籤。"},{"en":"A ready-made meal may be carrying several warnings for sugar, salt, and fat.","zh":"一份現成餐食可能因糖、鹽和脂肪而帶有多個警告。"},{"en":"Several warnings make nutritional problems harder to ignore.","zh":"多個警告令營養問題更難被忽視。"},{"en":"A product carrying several warnings may push shoppers toward another choice.","zh":"帶有多個警告的產品可能推動購物者轉向另一個選擇。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"no longer just","meaning":"不再只是","examples":[{"en":"The product is no longer just tasty.","zh":"產品不再只是美味。"},{"en":"No longer just means it has another important meaning besides the first one.","zh":"不再只是意思是除了第一個意思外，還有另一個重要含義。"},{"en":"A sugary drink is no longer just refreshing when it carries a health warning.","zh":"當含糖飲品帶有健康警告時，它不再只是清爽。"},{"en":"Labels show that food is no longer just about pleasure.","zh":"標籤顯示食物不再只是關於享受。"},{"en":"This phrase helps add a deeper point to a simple description.","zh":"這個短語幫助在簡單描述中加入更深一點。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"visibly unhealthy","meaning":"明顯不健康","examples":[{"en":"A heavily labelled product becomes visibly unhealthy.","zh":"帶有很多標籤的產品會變得明顯不健康。"},{"en":"Visibly unhealthy means looking clearly bad for health.","zh":"明顯不健康意思是看起來清楚對健康不好。"},{"en":"A snack with sugar, salt, and fat warnings looks visibly unhealthy.","zh":"同時有糖、鹽和脂肪警告的零食看起來明顯不健康。"},{"en":"Making risk visible helps consumers notice what packaging may hide.","zh":"令風險可見，有助消費者注意包裝可能隱藏的東西。"},{"en":"A product can be tasty and still look visibly unhealthy.","zh":"產品可以美味，同時仍看起來明顯不健康。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"ready-made meals","meaning":"現成餐食","examples":[{"en":"Ready-made meals may be covered with warnings.","zh":"現成餐食可能滿是警告。"},{"en":"Ready-made meals are prepared meals that consumers can heat and eat quickly.","zh":"現成餐食是已準備好、消費者可以快速翻熱和食用的餐膳。"},{"en":"Busy families may buy ready-made meals after work.","zh":"忙碌家庭可能下班後購買現成餐食。"},{"en":"Some ready-made meals contain high salt, sugar, or fat.","zh":"有些現成餐食含有高鹽、高糖或高脂肪。"},{"en":"Warning labels help shoppers compare ready-made meals more safely.","zh":"警告標籤幫助購物者更安全地比較現成餐食。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"covered with warnings","meaning":"滿是警告","examples":[{"en":"A company’s products may be covered with warnings.","zh":"一間公司的產品可能滿是警告。"},{"en":"Covered with warnings means having many warning labels clearly shown.","zh":"滿是警告意思是清楚顯示很多警告標籤。"},{"en":"A snack bag covered with warnings may look less attractive to parents.","zh":"滿是警告的零食包裝對家長來說可能較不吸引。"},{"en":"Products covered with warnings can damage a brand’s healthy image.","zh":"滿是警告的產品可能損害品牌的健康形象。"},{"en":"Companies may reformulate products so they are not covered with warnings.","zh":"公司可能重新調整配方，以免產品滿是警告。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"risk losing","meaning":"冒著失去……的風險","examples":[{"en":"The company risks losing its family-friendly image.","zh":"公司冒著失去適合家庭形象的風險。"},{"en":"To risk losing something means to face the possibility of losing it.","zh":"冒著失去某物的風險，意思是面對可能失去它的情況。"},{"en":"A restaurant risks losing customers if its food looks unsafe.","zh":"如果食物看起來不安全，餐廳便冒著失去顧客的風險。"},{"en":"A brand risks losing trust when many products carry warnings.","zh":"當很多產品帶有警告，品牌便冒著失去信任的風險。"},{"en":"Companies change recipes because they do not want to risk losing public confidence.","zh":"公司改變配方，因為它們不想冒著失去公眾信心的風險。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"family-friendly","meaning":"適合家庭的","examples":[{"en":"The company wants to keep a family-friendly image.","zh":"公司想保持適合家庭的形象。"},{"en":"Family-friendly means suitable, safe, or welcoming for families and children.","zh":"適合家庭的意思是適合、安全或歡迎家庭和兒童。"},{"en":"A family-friendly restaurant offers healthy choices and comfortable seating.","zh":"適合家庭的餐廳會提供健康選擇和舒適座位。"},{"en":"Products with many warnings may no longer look family-friendly.","zh":"帶有很多警告的產品可能不再看起來適合家庭。"},{"en":"A family-friendly image is valuable because parents care about children’s health.","zh":"適合家庭的形象很有價值，因為父母關心孩子健康。"}],"source":"2020 Q6.pdf","sourcePage":8},{"front":"it therefore follows that","meaning":"因此可以推論","examples":[{"en":"It therefore follows that manufacturers have a reason to reformulate.","zh":"因此可以推論，製造商有理由重新調整配方。"},{"en":"It therefore follows that means this conclusion logically comes from the previous point.","zh":"因此可以推論意思是這個結論合乎邏輯地來自前一點。"},{"en":"If warnings hurt sales, it therefore follows that companies may reduce sugar.","zh":"如果警告影響銷售，因此可以推論公司可能會減糖。"},{"en":"Writers use this phrase to show reasoning, not just opinion.","zh":"作者使用這個短語來顯示推理，而不只是意見。"},{"en":"It therefore follows that visible labels can influence business behaviour.","zh":"因此可以推論，可見標籤可以影響商業行為。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"practical reason to","meaning":"實際理由去","examples":[{"en":"Manufacturers have a practical reason to reduce sugar.","zh":"製造商有實際理由去減糖。"},{"en":"A practical reason to do something is a real-life motive for action.","zh":"實際理由去做某事，是指現實生活中的行動動機。"},{"en":"A school has a practical reason to provide water if students drink too much soda.","zh":"如果學生喝太多汽水，學校便有實際理由去提供水。"},{"en":"Warning labels give companies a practical reason to improve recipes.","zh":"警告標籤給公司實際理由去改善配方。"},{"en":"Practical reasons often change behaviour faster than moral advice alone.","zh":"實際理由往往比單靠道德建議更快改變行為。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"reduce sugar","meaning":"減糖","examples":[{"en":"Manufacturers may reduce sugar to avoid warning labels.","zh":"製造商可能減糖以避免警告標籤。"},{"en":"To reduce sugar means to lower the amount of sugar in food or drinks.","zh":"減糖意思是降低食物或飲品中的糖分。"},{"en":"A drink company can reduce sugar while keeping some sweetness.","zh":"飲品公司可以在保持一些甜味的同時減糖。"},{"en":"Reducing sugar may help products avoid a high-sugar warning.","zh":"減糖可能幫助產品避免高糖警告。"},{"en":"Consumers benefit when companies reduce sugar across many products.","zh":"當公司在多種產品中減糖，消費者會受益。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"thereby","meaning":"從而","examples":[{"en":"Manufacturers may reduce salt, thereby making healthier options more common.","zh":"製造商可能減鹽，從而令較健康選擇更常見。"},{"en":"Thereby means as a result of that action.","zh":"從而意思是由於那個行動而產生某結果。"},{"en":"Schools may ban sugary drinks, thereby encouraging students to drink water.","zh":"學校可能禁止含糖飲品，從而鼓勵學生喝水。"},{"en":"Companies reformulate products, thereby reducing hidden health risks.","zh":"公司重新調整產品配方，從而減少隱藏健康風險。"},{"en":"This word connects an action with its result.","zh":"這個詞把行動和結果連接起來。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"healthier options","meaning":"較健康的選擇","examples":[{"en":"Warning labels may make healthier options more common.","zh":"警告標籤可能令較健康的選擇更常見。"},{"en":"Healthier options are choices that are better for health than other choices.","zh":"較健康的選擇是比其他選擇對健康更好的選項。"},{"en":"Water, fruit, and low-salt noodles can be healthier options.","zh":"水、水果和低鹽麵都可以是較健康的選擇。"},{"en":"Healthier options become easier to choose when they are widely available.","zh":"當較健康的選擇廣泛供應時，人們會更容易選擇它們。"},{"en":"Labels help by pushing shops and companies to offer healthier options.","zh":"標籤透過推動商店和公司提供較健康的選擇來幫助人們。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"more common","meaning":"更常見","examples":[{"en":"Healthier options may become more common.","zh":"較健康的選擇可能變得更常見。"},{"en":"More common means happening or appearing more often.","zh":"更常見意思是更經常發生或出現。"},{"en":"Low-sugar drinks become more common when shoppers ask for them.","zh":"當購物者要求低糖飲品時，它們會變得更常見。"},{"en":"If healthy food is more common, people need less effort to choose it.","zh":"如果健康食物更常見，人們選擇它時就較少需要努力。"},{"en":"Warning labels can make improved recipes more common.","zh":"警告標籤可以令改良配方更常見。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"personal choice","meaning":"個人選擇","examples":[{"en":"Personal choice is shaped by what is available.","zh":"個人選擇受可選擇的東西塑造。"},{"en":"Personal choice means an individual’s own decision.","zh":"個人選擇是指個人自己的決定。"},{"en":"Buying lunch may seem like personal choice, but shops decide what is offered.","zh":"買午餐看似個人選擇，但商店決定供應甚麼。"},{"en":"Personal choice becomes healthier when the environment offers better options.","zh":"當環境提供較好選項時，個人選擇會變得較健康。"},{"en":"Blaming personal choice alone ignores price, access, and marketing.","zh":"只責怪個人選擇會忽略價格、可取得性和市場推廣。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"be shaped by","meaning":"受……塑造","examples":[{"en":"Personal choice is shaped by the food environment.","zh":"個人選擇受食物環境塑造。"},{"en":"To be shaped by something means to be influenced or formed by it.","zh":"受某事塑造意思是被它影響或形成。"},{"en":"Children’s habits are shaped by family meals and school lunches.","zh":"孩子的習慣受家庭餐膳和學校午餐塑造。"},{"en":"Food choices are shaped by price, packaging, and availability.","zh":"飲食選擇受價格、包裝和供應塑造。"},{"en":"If choices are shaped by the environment, policy can help improve them.","zh":"如果選擇受環境塑造，政策便可以幫助改善它們。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"what is available","meaning":"可選擇的東西","examples":[{"en":"Consumers’ choices depend on what is available.","zh":"消費者的選擇取決於可選擇的東西。"},{"en":"What is available means the things people can actually get or choose.","zh":"可選擇的東西是指人們實際可以取得或選擇的事物。"},{"en":"If only sugary drinks are sold, what is available limits healthy choice.","zh":"如果只售賣含糖飲品，可選擇的東西就會限制健康選擇。"},{"en":"People choose better when healthier food is available nearby.","zh":"當附近有較健康食物可選時，人們會作出較好選擇。"},{"en":"Warning labels may change what is available by pushing companies to reformulate.","zh":"警告標籤可能透過推動公司改配方來改變可選擇的東西。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"excessively sweet or salty","meaning":"過甜或過鹹","examples":[{"en":"Fewer products should be excessively sweet or salty.","zh":"應該有更少產品過甜或過鹹。"},{"en":"Excessively sweet or salty means containing too much sugar or salt.","zh":"過甜或過鹹意思是含有過多糖分或鹽分。"},{"en":"Some sauces taste good but are excessively sweet or salty.","zh":"有些醬汁味道好，但過甜或過鹹。"},{"en":"Products that are excessively sweet or salty can train people to prefer strong flavours.","zh":"過甜或過鹹的產品可能令人口味變得偏好濃味。"},{"en":"Reformulation can make food less excessively sweet or salty.","zh":"重新調整配方可以令食物不那麼過甜或過鹹。"}],"source":"2020 Q6.pdf","sourcePage":9},{"front":"depend on discipline alone","meaning":"單靠自律","examples":[{"en":"Consumers should not have to depend on discipline alone.","zh":"消費者不應只能單靠自律。"},{"en":"To depend on discipline alone means to rely only on self-control.","zh":"單靠自律意思是只依賴自制力。"},{"en":"Students should not depend on discipline alone if the canteen sells mostly junk food.","zh":"如果飯堂主要售賣垃圾食物，學生不應只能單靠自律。"},{"en":"Healthy environments reduce the need to depend on discipline alone.","zh":"健康環境可以減少人們單靠自律的需要。"},{"en":"Warning labels help because willpower alone is often not enough.","zh":"警告標籤有幫助，因為單靠意志力往往不足夠。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"the same principle applies to","meaning":"同一道理適用於","examples":[{"en":"The same principle applies to schools, offices and families.","zh":"同一道理適用於學校、辦公室和家庭。"},{"en":"This phrase means the same idea is true in another situation too.","zh":"這個短語意思是同一想法在另一種情況中也成立。"},{"en":"The same principle applies to homework: clear instructions help everyone.","zh":"同一道理適用於功課：清楚指示能幫助每個人。"},{"en":"If labels help families choose food, the same principle applies to school canteens.","zh":"如果標籤幫助家庭選擇食物，同一道理也適用於學校飯堂。"},{"en":"This phrase helps writers extend an argument to new examples.","zh":"這個短語幫助作者把論點延伸到新例子。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"choose snacks for a picnic","meaning":"為野餐選擇零食","examples":[{"en":"A class may choose snacks for a picnic.","zh":"一個班可能為野餐選擇零食。"},{"en":"To choose snacks for a picnic means to select small foods for an outdoor meal.","zh":"為野餐選擇零食意思是為戶外用餐挑選小食。"},{"en":"Students may choose snacks for a picnic by comparing warning labels.","zh":"學生可能透過比較警告標籤為野餐選擇零食。"},{"en":"This choice matters because group snacks affect many people.","zh":"這個選擇很重要，因為集體零食會影響很多人。"},{"en":"Choosing snacks for a picnic can become a chance to learn healthy habits.","zh":"為野餐選擇零食可以成為學習健康習慣的機會。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"compare options","meaning":"比較選項","examples":[{"en":"Warning labels make it easier to compare options.","zh":"警告標籤令比較選項更容易。"},{"en":"To compare options means to look at different choices before deciding.","zh":"比較選項意思是在決定前查看不同選擇。"},{"en":"A shopper may compare options by checking which drink has fewer warnings.","zh":"購物者可能查看哪款飲品警告較少來比較選項。"},{"en":"Comparing options prevents people from choosing only by colour or taste.","zh":"比較選項可防止人們只按顏色或味道選擇。"},{"en":"Simple labels help consumers compare options quickly.","zh":"簡單標籤幫助消費者快速比較選項。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"without embarrassing anyone","meaning":"不令任何人尷尬","examples":[{"en":"Students can compare snacks without embarrassing anyone.","zh":"學生可以比較零食，而不令任何人尷尬。"},{"en":"Without embarrassing anyone means without making someone feel ashamed or awkward.","zh":"不令任何人尷尬意思是不使人感到羞愧或不自在。"},{"en":"A label lets a teacher discuss sugar without embarrassing a student’s family.","zh":"標籤讓老師討論糖分，而不令學生家庭尷尬。"},{"en":"Clear signs make the discussion about food, not personal blame.","zh":"清晰標誌令討論集中在食物，而不是個人責備。"},{"en":"Health advice works better when it helps without embarrassing anyone.","zh":"健康建議在能幫助人又不令任何人尷尬時更有效。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"grandparents","meaning":"祖父母；外祖父母","examples":[{"en":"Grandparents may use labels when buying food for children.","zh":"祖父母或外祖父母為孩子買食物時可能使用標籤。"},{"en":"Grandparents are the parents of a person’s mother or father.","zh":"祖父母或外祖父母是父母的父母。"},{"en":"Grandparents may buy snacks for children after school.","zh":"祖父母或外祖父母可能放學後為孩子買零食。"},{"en":"Clear labels help grandparents choose food even if nutrition terms are difficult.","zh":"即使營養術語困難，清晰標籤也能幫助祖父母作選擇。"},{"en":"Grandparents can support healthy habits through small shopping choices.","zh":"祖父母或外祖父母可以透過小小購物選擇支持健康習慣。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"a simple sign to follow","meaning":"可跟隨的簡單標誌","examples":[{"en":"The label gives grandparents a simple sign to follow.","zh":"標籤給祖父母一個可跟隨的簡單標誌。"},{"en":"A simple sign to follow is an easy signal that guides action.","zh":"可跟隨的簡單標誌是能引導行動的容易訊號。"},{"en":"A red warning gives shoppers a simple sign to follow when they are unsure.","zh":"紅色警告在購物者不確定時，給他們一個可跟隨的簡單標誌。"},{"en":"Simple signs help because not everyone understands nutrition numbers.","zh":"簡單標誌有幫助，因為不是人人都明白營養數字。"},{"en":"A simple sign to follow can make healthy choice less stressful.","zh":"可跟隨的簡單標誌可以令健康選擇不那麼有壓力。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"complex nutrition terms","meaning":"複雜營養術語","examples":[{"en":"Some people do not understand complex nutrition terms.","zh":"有些人不明白複雜營養術語。"},{"en":"Complex nutrition terms are difficult words about food content and health.","zh":"複雜營養術語是關於食物成分和健康的困難詞語。"},{"en":"Words like sodium and saturated fat may be complex nutrition terms for some shoppers.","zh":"鈉和飽和脂肪等字眼對一些購物者來說可能是複雜營養術語。"},{"en":"If terms are too complex, people may ignore the label.","zh":"如果術語太複雜，人們可能會忽略標籤。"},{"en":"Warning signs translate complex nutrition terms into simple messages.","zh":"警告標誌把複雜營養術語轉化成簡單訊息。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"gradually change","meaning":"逐漸改變","examples":[{"en":"Labels can gradually change what people consider normal food.","zh":"標籤可以逐漸改變人們視為正常食物的東西。"},{"en":"To gradually change means to change slowly over time.","zh":"逐漸改變意思是隨時間慢慢改變。"},{"en":"Daily reminders can gradually change a student’s study habits.","zh":"每日提醒可以逐漸改變學生的學習習慣。"},{"en":"Labels gradually change choices because people see them again and again.","zh":"標籤會逐漸改變選擇，因為人們一次又一次看見它們。"},{"en":"Gradual change may look small at first but become important later.","zh":"逐漸改變一開始可能看似微小，但日後會變得重要。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"what counts as","meaning":"被視為","examples":[{"en":"Labels can change what counts as normal food.","zh":"標籤可以改變甚麼被視為正常食物。"},{"en":"What counts as something means what is accepted as that thing.","zh":"What counts as something 意思是甚麼被接受為某事物。"},{"en":"Schools can influence what counts as a healthy lunch.","zh":"學校可以影響甚麼被視為健康午餐。"},{"en":"If low-sugar drinks become common, people may change what counts as normal.","zh":"如果低糖飲品變得常見，人們可能改變甚麼被視為正常。"},{"en":"This phrase is useful when discussing changing standards.","zh":"這個短語適合討論標準的改變。"}],"source":"2020 Q6.pdf","sourcePage":10},{"front":"normal food","meaning":"正常食物","examples":[{"en":"Warning labels can change people’s idea of normal food.","zh":"警告標籤可以改變人們對正常食物的看法。"},{"en":"Normal food means food people see as usual, acceptable, or everyday.","zh":"正常食物是人們視為平常、可接受或日常的食物。"},{"en":"If children eat fruit daily, fruit becomes normal food to them.","zh":"如果孩子每天吃水果，水果對他們來說就成為正常食物。"},{"en":"Heavy marketing can make sugary snacks seem like normal food.","zh":"強烈市場推廣可能令含糖零食看似正常食物。"},{"en":"Labels help society rethink what should count as normal food.","zh":"標籤幫助社會重新思考甚麼應被視為正常食物。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, warning labels cannot solve every problem.","zh":"誠然，警告標籤不能解決每個問題。"},{"en":"Granted means the writer accepts one point before giving another argument.","zh":"Granted 意思是作者先承認一點，再提出另一個論點。"},{"en":"Granted, healthy food can be expensive, but clear labels still help.","zh":"誠然，健康食物可能昂貴，但清晰標籤仍有幫助。"},{"en":"This word makes an argument sound fair and balanced.","zh":"這個詞令論點聽起來公平和平衡。"},{"en":"Granted, labels are limited, but they can still influence choices.","zh":"誠然，標籤有限制，但仍能影響選擇。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"critics may argue that","meaning":"批評者可能會認為","examples":[{"en":"Critics may argue that warning labels are too simple.","zh":"批評者可能會認為警告標籤太簡單。"},{"en":"Critics may argue that means opponents may claim or believe something.","zh":"批評者可能會認為，意思是反對者可能聲稱或相信某事。"},{"en":"Critics may argue that school rules do not change real habits.","zh":"批評者可能會認為校規不能改變真正習慣。"},{"en":"This phrase introduces the opposing view in an essay.","zh":"這個短語在文章中引出反方觀點。"},{"en":"After using this phrase, writers should respond with reasons.","zh":"使用這個短語後，作者應以理由回應。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"too simple to overcome","meaning":"太簡單而不能克服","examples":[{"en":"Labels may seem too simple to overcome strong cravings.","zh":"標籤可能看似太簡單，不能克服強烈渴望。"},{"en":"Too simple to overcome something means not powerful enough to defeat it.","zh":"太簡單而不能克服某事，意思是不夠有力去戰勝它。"},{"en":"A small reminder may be too simple to overcome years of bad habits.","zh":"小提醒可能太簡單，不能克服多年的壞習慣。"},{"en":"Critics say labels are too simple to overcome cheap prices and advertising.","zh":"批評者說標籤太簡單，不能克服低價和廣告。"},{"en":"However, simple does not always mean useless.","zh":"然而，簡單不一定等於無用。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"strong cravings","meaning":"強烈渴望","examples":[{"en":"Strong cravings can make people ignore warning labels.","zh":"強烈渴望可以令人無視警告標籤。"},{"en":"Strong cravings are powerful desires for a particular food or drink.","zh":"強烈渴望是對某種食物或飲品的強大慾望。"},{"en":"A tired student may have strong cravings for sweet snacks after school.","zh":"疲倦學生放學後可能強烈渴望甜零食。"},{"en":"Strong cravings can weaken self-control at the buying moment.","zh":"強烈渴望可以在購買一刻削弱自制力。"},{"en":"Labels may not remove strong cravings, but they can still create a pause.","zh":"標籤未必能消除強烈渴望，但仍可以令人停一停。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"low prices","meaning":"低價","examples":[{"en":"Low prices can encourage people to buy unhealthy food.","zh":"低價可以鼓勵人們購買不健康食物。"},{"en":"Low prices mean products cost little money.","zh":"低價意思是產品花費很少金錢。"},{"en":"Students may choose crisps because low prices fit their pocket money.","zh":"學生可能選擇薯片，因為低價符合他們的零用錢。"},{"en":"Low prices can make unhealthy food more attractive than fresh food.","zh":"低價可以令不健康食物比新鮮食物更吸引。"},{"en":"Warning labels help, but low prices remain a powerful influence.","zh":"警告標籤有幫助，但低價仍是強大影響。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"long-established eating habits","meaning":"長久形成的飲食習慣","examples":[{"en":"Long-established eating habits are difficult to change.","zh":"長久形成的飲食習慣難以改變。"},{"en":"Long-established eating habits are food routines built over many years.","zh":"長久形成的飲食習慣是多年建立的飲食模式。"},{"en":"A family may have long-established eating habits of drinking soda with dinner.","zh":"一個家庭可能有晚餐喝汽水的長久形成飲食習慣。"},{"en":"These habits are difficult because they feel normal and comfortable.","zh":"這些習慣困難，因為它們感覺正常又舒服。"},{"en":"Labels cannot erase long-established eating habits overnight.","zh":"標籤不能一夜之間消除長久形成的飲食習慣。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"there is no denying that","meaning":"無可否認","examples":[{"en":"There is no denying that some consumers may ignore the label.","zh":"無可否認，有些消費者可能會無視標籤。"},{"en":"There is no denying that means it is impossible to honestly reject a fact.","zh":"無可否認意思是無法誠實地否定某個事實。"},{"en":"There is no denying that healthy food can cost more.","zh":"無可否認，健康食物可能較昂貴。"},{"en":"This phrase admits a weakness before defending a larger argument.","zh":"這個短語先承認弱點，再維護較大的論點。"},{"en":"There is no denying that labels are imperfect, but they may still help.","zh":"無可否認，標籤並不完美，但它們仍可能有幫助。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"sugary drinks","meaning":"含糖飲品","examples":[{"en":"Some people love sugary drinks and ignore the warning.","zh":"有些人喜愛含糖飲品，並無視警告。"},{"en":"Sugary drinks are drinks that contain a lot of sugar.","zh":"含糖飲品是含有大量糖分的飲料。"},{"en":"Soda, sweet tea, and some fruit drinks can be sugary drinks.","zh":"汽水、甜茶和某些果汁飲品都可以是含糖飲品。"},{"en":"Sugary drinks can add many calories without making people feel full.","zh":"含糖飲品可以增加很多卡路里，卻不令人有飽足感。"},{"en":"Warning labels help consumers notice how risky sugary drinks can be.","zh":"警告標籤幫助消費者注意含糖飲品可能有多大風險。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"ignore the label","meaning":"無視標籤","examples":[{"en":"A person who loves sugary drinks may ignore the label.","zh":"喜愛含糖飲品的人可能會無視標籤。"},{"en":"To ignore the label means to see it but choose not to follow its message.","zh":"無視標籤意思是看見它，但選擇不理會它的訊息。"},{"en":"A shopper may ignore the label if the snack is cheap and familiar.","zh":"如果零食便宜又熟悉，購物者可能會無視標籤。"},{"en":"Ignoring the label can lead to repeated unhealthy choices.","zh":"無視標籤可能導致反覆作出不健康選擇。"},{"en":"Some people ignore the label, but others may change because of it.","zh":"有些人無視標籤，但另一些人可能因它而改變。"}],"source":"2020 Q6.pdf","sourcePage":11},{"front":"just as","meaning":"正如","examples":[{"en":"Some people ignore warning labels, just as others ignore exercise advice.","zh":"有些人無視警告標籤，正如另一些人無視運動建議。"},{"en":"Just as means in the same way that.","zh":"正如意思是以相同方式。"},{"en":"Some students ignore sleep advice, just as they ignore revision plans.","zh":"有些學生無視睡眠建議，正如他們無視溫習計劃。"},{"en":"This phrase compares two similar situations.","zh":"這個短語比較兩個相似情況。"},{"en":"Just as advice can still be useful when ignored by some, labels can still help others.","zh":"正如建議即使被一些人忽視仍可有用，標籤也仍可幫助其他人。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"exercise advice","meaning":"運動建議","examples":[{"en":"Some people ignore exercise advice.","zh":"有些人無視運動建議。"},{"en":"Exercise advice is guidance about physical activity and fitness.","zh":"運動建議是關於體能活動和健身的指引。"},{"en":"A doctor may give exercise advice to someone who sits all day.","zh":"醫生可能給整天坐著的人運動建議。"},{"en":"People may ignore exercise advice even when they know it is sensible.","zh":"即使人們知道運動建議合理，也可能無視它。"},{"en":"Like warning labels, exercise advice helps most when it is clear and practical.","zh":"像警告標籤一樣，運動建議在清晰而實際時最有幫助。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"to say that… is not to say that…","meaning":"說……並不等於說……","examples":[{"en":"To say that labels are imperfect is not to say that they are ineffective.","zh":"說標籤不完美，並不等於說它們無效。"},{"en":"This structure means one statement should not be confused with a stronger claim.","zh":"這個結構意思是一個說法不應被誤解為更強烈的主張。"},{"en":"To say that exams are stressful is not to say that all exams are useless.","zh":"說考試有壓力，並不等於說所有考試都無用。"},{"en":"This phrase helps writers make a careful distinction.","zh":"這個短語幫助作者作出謹慎區分。"},{"en":"It shows that a weakness does not destroy the whole argument.","zh":"它顯示一個弱點不會推翻整個論點。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"imperfect","meaning":"不完美的","examples":[{"en":"Warning labels are imperfect but still useful.","zh":"警告標籤不完美，但仍然有用。"},{"en":"Imperfect means not complete, faultless, or successful in every case.","zh":"不完美的意思是不完整、並非毫無缺點，或不是每種情況都成功。"},{"en":"An imperfect study plan may still help a student improve.","zh":"不完美的溫習計劃仍可能幫助學生進步。"},{"en":"A policy can be imperfect because some people ignore it.","zh":"政策可能不完美，因為有些人會忽略它。"},{"en":"Imperfect does not automatically mean useless.","zh":"不完美不自動等於無用。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"ineffective","meaning":"無效的","examples":[{"en":"An imperfect policy is not necessarily ineffective.","zh":"不完美的政策不一定是無效的。"},{"en":"Ineffective means not producing the desired result.","zh":"無效的意思是不能產生想要的結果。"},{"en":"A warning is ineffective if shoppers never see or understand it.","zh":"如果購物者從不看見或明白警告，它就是無效的。"},{"en":"A policy may be partly effective even if it does not solve everything.","zh":"即使政策不能解決所有問題，也可能部分有效。"},{"en":"Labels are not ineffective simply because some consumers ignore them.","zh":"標籤不會只因有些消費者忽略它們就變得無效。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"the real question is not whether…, but whether…","meaning":"真正問題不是是否……，而是是否……","examples":[{"en":"The real question is not whether labels can solve everything, but whether they can help.","zh":"真正問題不是標籤是否能解決一切，而是它們是否能幫忙。"},{"en":"This structure shifts attention from an extreme test to a fairer test.","zh":"這個結構把注意力從極端標準轉向較公平標準。"},{"en":"The real question is not whether homework is perfect, but whether it supports learning.","zh":"真正問題不是功課是否完美，而是它是否支持學習。"},{"en":"It helps writers reject an unfair standard.","zh":"它幫助作者拒絕不公平標準。"},{"en":"For warning labels, the fair question is whether they make healthier choices easier.","zh":"對警告標籤而言，公平問題是它們是否令較健康選擇更容易。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"by themselves","meaning":"單靠它們自己","examples":[{"en":"Labels cannot solve unhealthy eating by themselves.","zh":"標籤不能單靠它們自己解決不健康飲食。"},{"en":"By themselves means alone, without help from other things.","zh":"單靠它們自己意思是獨自地，沒有其他事物幫助。"},{"en":"Exercise by itself cannot create health if diet and sleep are poor.","zh":"如果飲食和睡眠差，單靠運動也不能創造健康。"},{"en":"Labels need education and affordable food to work better.","zh":"標籤需要教育和買得起的食物配合，才能更有效。"},{"en":"Saying labels cannot work by themselves does not mean they have no value.","zh":"說標籤不能單靠它們自己發揮作用，並不代表它們沒有價值。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"make healthier choices more likely","meaning":"令較健康選擇更有可能出現","examples":[{"en":"Warning labels can make healthier choices more likely.","zh":"警告標籤可以令較健康選擇更有可能出現。"},{"en":"To make something more likely means to increase the chance that it will happen.","zh":"令某事更有可能出現，意思是增加它發生的機會。"},{"en":"Clear signs make healthier choices more likely in a school canteen.","zh":"清晰標誌令較健康選擇在學校飯堂更有可能出現。"},{"en":"Labels help by turning attention toward risk before purchase.","zh":"標籤透過在購買前把注意力轉向風險來提供幫助。"},{"en":"A policy has value if it makes healthier choices more likely.","zh":"如果政策能令較健康選擇更有可能出現，它便有價值。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"on that test","meaning":"以這個標準來看","examples":[{"en":"On that test, warning labels clearly have value.","zh":"以這個標準來看，警告標籤明顯有價值。"},{"en":"On that test means judged by that particular standard.","zh":"以這個標準來看，意思是按那個特定標準判斷。"},{"en":"If the test is clarity, this label succeeds on that test.","zh":"如果標準是清晰度，這個標籤以這個標準來看是成功的。"},{"en":"On the test of helping quick shoppers, warning labels are useful.","zh":"以幫助快速購物者這個標準來看，警告標籤是有用的。"},{"en":"This phrase helps writers make a focused judgement.","zh":"這個短語幫助作者作出聚焦判斷。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"have value","meaning":"有價值","examples":[{"en":"Warning labels clearly have value.","zh":"警告標籤明顯有價值。"},{"en":"To have value means to be useful, important, or worth keeping.","zh":"有價值意思是有用、重要或值得保留。"},{"en":"A simple rule can have value if it prevents harm.","zh":"如果簡單規則能防止傷害，它就有價值。"},{"en":"Labels have value because they make hidden risks easier to notice.","zh":"標籤有價值，因為它們令隱藏風險更容易被注意。"},{"en":"Something does not need to be perfect to have value.","zh":"某事不需要完美才有價值。"}],"source":"2020 Q6.pdf","sourcePage":12},{"front":"switch from… to…","meaning":"從……轉為……","examples":[{"en":"Some consumers may switch from a heavily labelled snack to a less harmful one.","zh":"有些消費者可能從帶有多個標籤的零食轉為危害較小的零食。"},{"en":"To switch from one thing to another means to stop choosing the first and choose the second.","zh":"從一物轉為另一物意思是不再選第一個，而選第二個。"},{"en":"A student may switch from soda to water after seeing a warning.","zh":"學生看見警告後，可能從汽水轉為水。"},{"en":"Switching choices can reduce risk even if the change is small.","zh":"轉換選擇即使幅度小，也可以降低風險。"},{"en":"This phrase clearly shows movement from one option to another.","zh":"這個短語清楚顯示從一個選項轉向另一個選項。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"heavily labelled snack","meaning":"帶有多個標籤的零食","examples":[{"en":"A heavily labelled snack may discourage some consumers.","zh":"帶有多個標籤的零食可能令一些消費者卻步。"},{"en":"A heavily labelled snack is a snack with many warning labels on its package.","zh":"帶有多個標籤的零食是包裝上有許多警告標籤的零食。"},{"en":"A packet of crisps with sugar, salt, and fat warnings is heavily labelled.","zh":"同時有糖、鹽和脂肪警告的一包薯片，就是帶有多個標籤的零食。"},{"en":"Heavy labelling makes health risks difficult to ignore.","zh":"多個標籤令健康風險難以忽視。"},{"en":"Some shoppers may avoid a heavily labelled snack and choose fruit instead.","zh":"有些購物者可能避開帶有多個標籤的零食，改選水果。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"less harmful","meaning":"危害較小的","examples":[{"en":"Some consumers may choose a less harmful product.","zh":"有些消費者可能選擇危害較小的產品。"},{"en":"Less harmful means causing less damage or risk than another choice.","zh":"危害較小的意思是比另一個選擇造成較少傷害或風險。"},{"en":"A low-sugar drink may be less harmful than a full-sugar soda.","zh":"低糖飲品可能比全糖汽水危害較小。"},{"en":"Choosing a less harmful snack can still improve daily eating habits.","zh":"選擇危害較小的零食仍可改善日常飲食習慣。"},{"en":"Less harmful does not always mean fully healthy, but it is a better step.","zh":"危害較小不一定等於完全健康，但它是較好一步。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"meaningful","meaning":"有意義的","examples":[{"en":"The effect is meaningful because food decisions are made every day.","zh":"這種效果是有意義的，因為飲食決定每天都會作出。"},{"en":"Meaningful means important because it has real value or effect.","zh":"有意義的意思是因有真正價值或效果而重要。"},{"en":"A small change in breakfast can be meaningful if repeated daily.","zh":"如果每天重複，早餐中的小改變也可以很有意義。"},{"en":"Warning labels are meaningful because they influence ordinary routines.","zh":"警告標籤有意義，因為它們影響日常習慣。"},{"en":"A meaningful policy does not need to solve every problem alone.","zh":"有意義的政策不需要單獨解決每個問題。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"food decisions","meaning":"飲食決定","examples":[{"en":"Food decisions are made every day.","zh":"飲食決定每天都會作出。"},{"en":"Food decisions are choices about what to eat, drink, buy, or cook.","zh":"飲食決定是關於吃甚麼、喝甚麼、買甚麼或煮甚麼的選擇。"},{"en":"Choosing breakfast, lunch, and snacks all involves food decisions.","zh":"選早餐、午餐和零食都涉及飲食決定。"},{"en":"Small food decisions matter because they repeat many times.","zh":"小小飲食決定很重要，因為它們會重複很多次。"},{"en":"Warning labels guide food decisions at the moment they happen.","zh":"警告標籤在飲食決定發生的一刻提供指引。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"not meant to replace","meaning":"不是用來取代","examples":[{"en":"Labels are not meant to replace nutrition education.","zh":"標籤不是用來取代營養教育。"},{"en":"Not meant to replace means not designed to take the place of something else.","zh":"不是用來取代意思是不是設計來代替另一事物。"},{"en":"A calculator is not meant to replace understanding in maths.","zh":"計算機不是用來取代數學理解。"},{"en":"Labels help quick choices but are not meant to replace deeper learning.","zh":"標籤幫助快速選擇，但不是用來取代更深入學習。"},{"en":"This phrase shows that two measures can work together.","zh":"這個短語顯示兩種措施可以一起運作。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"nutrition education","meaning":"營養教育","examples":[{"en":"Warning labels should work alongside nutrition education.","zh":"警告標籤應與營養教育配合。"},{"en":"Nutrition education teaches people how food affects health.","zh":"營養教育教人們食物如何影響健康。"},{"en":"Schools provide nutrition education when they teach students about sugar, salt, and balanced meals.","zh":"學校教授糖、鹽和均衡膳食時，就是提供營養教育。"},{"en":"Labels are clearer when people already have basic nutrition education.","zh":"當人們已有基本營養教育時，標籤會更清楚。"},{"en":"Nutrition education helps people understand why warnings matter.","zh":"營養教育幫助人們明白警告為何重要。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"affordable fresh food","meaning":"買得起的新鮮食物","examples":[{"en":"People also need affordable fresh food.","zh":"人們也需要買得起的新鮮食物。"},{"en":"Affordable fresh food is fresh food that ordinary people can pay for.","zh":"買得起的新鮮食物是普通人能負擔的新鮮食物。"},{"en":"Fruit, vegetables, and plain meat should be affordable fresh food in every community.","zh":"水果、蔬菜和原味肉類應在每個社區成為買得起的新鮮食物。"},{"en":"Labels help less if healthy alternatives are too expensive.","zh":"如果健康替代品太昂貴，標籤的幫助會較少。"},{"en":"Affordable fresh food makes healthy eating practical.","zh":"買得起的新鮮食物令健康飲食變得實際。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"responsible advertising rules","meaning":"負責任的廣告規則","examples":[{"en":"Labels should be supported by responsible advertising rules.","zh":"標籤應由負責任的廣告規則支持。"},{"en":"Responsible advertising rules limit misleading or harmful promotion.","zh":"負責任的廣告規則限制誤導性或有害宣傳。"},{"en":"Rules may stop companies from marketing sugary drinks as sports products.","zh":"規則可能阻止公司把含糖飲品宣傳成運動產品。"},{"en":"Advertising rules matter because packaging and adverts influence children.","zh":"廣告規則很重要，因為包裝和廣告會影響孩子。"},{"en":"Warning labels work better when responsible advertising rules reduce confusion.","zh":"當負責任的廣告規則減少混亂時，警告標籤更有效。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"work best alongside","meaning":"與……配合時最有效","examples":[{"en":"Labels work best alongside other health measures.","zh":"標籤與其他健康措施配合時最有效。"},{"en":"To work best alongside something means to be most effective when used with it.","zh":"與某事配合時最有效，意思是與它一起使用時效果最好。"},{"en":"Exercise works best alongside enough sleep and balanced meals.","zh":"運動與充足睡眠和均衡飲食配合時最有效。"},{"en":"Labels work best alongside education, fair prices, and healthier options.","zh":"標籤與教育、公平價格和較健康選擇配合時最有效。"},{"en":"This phrase shows that one solution needs support from others.","zh":"這個短語顯示一種解決方法需要其他方法支持。"}],"source":"2020 Q6.pdf","sourcePage":13},{"front":"these measures","meaning":"這些措施","examples":[{"en":"Warning labels should work alongside these measures.","zh":"警告標籤應與這些措施配合。"},{"en":"These measures means the actions or policies just mentioned.","zh":"這些措施意思是剛才提到的行動或政策。"},{"en":"Nutrition education and advertising rules are examples of these measures.","zh":"營養教育和廣告規則就是這些措施的例子。"},{"en":"These measures support labels by making healthy choice easier.","zh":"這些措施透過令健康選擇更容易來支持標籤。"},{"en":"Without these measures, labels may have a weaker effect.","zh":"沒有這些措施，標籤的效果可能較弱。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"warned clearly","meaning":"獲得清楚警告","examples":[{"en":"Consumers should be warned clearly about nutritional risks.","zh":"消費者應就營養風險獲得清楚警告。"},{"en":"To be warned clearly means to receive an easy-to-understand warning.","zh":"獲得清楚警告意思是收到容易理解的警告。"},{"en":"A shopper is warned clearly when a label says “high in salt” in large print.","zh":"當標籤以大字寫著「高鹽」時，購物者便獲得清楚警告。"},{"en":"Clear warnings help people act before damage happens.","zh":"清楚警告幫助人在傷害發生前行動。"},{"en":"If consumers are not warned clearly, they may make uninformed choices.","zh":"如果消費者沒有獲得清楚警告，他們可能作出資訊不足的選擇。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"realistic alternatives","meaning":"實際可行的替代選擇","examples":[{"en":"Healthy eating requires realistic alternatives.","zh":"健康飲食需要實際可行的替代選擇。"},{"en":"Realistic alternatives are choices that people can actually afford and use.","zh":"實際可行的替代選擇是人們真正負擔得起並能使用的選項。"},{"en":"Water fountains are realistic alternatives to sugary drinks in schools.","zh":"學校中的飲水機是含糖飲品的實際可行替代選擇。"},{"en":"Advice is weak if people have no realistic alternatives nearby.","zh":"如果附近沒有實際可行的替代選擇，建議便較無力。"},{"en":"Labels work better when realistic alternatives are easy to find.","zh":"當實際可行的替代選擇容易找到時，標籤更有效。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"practical rather than idealistic","meaning":"實際可行，而非空談理想","examples":[{"en":"Healthy eating should become practical rather than idealistic.","zh":"健康飲食應變得實際可行，而非空談理想。"},{"en":"Practical rather than idealistic means realistic and doable, not just a perfect dream.","zh":"實際可行，而非空談理想意思是現實和做得到，而不只是完美夢想。"},{"en":"Cheap fruit in school is practical rather than idealistic health policy.","zh":"學校提供便宜水果，是實際可行而非空談理想的健康政策。"},{"en":"Labels become practical when they help people make real shopping decisions.","zh":"當標籤幫助人們作出真正購物決定時，它們就變得實際可行。"},{"en":"Health advice should be practical rather than idealistic if it is meant to change habits.","zh":"如果健康建議想改變習慣，就應實際可行，而非空談理想。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"overall","meaning":"總括而言","examples":[{"en":"Overall, food warning labels are an effective way to change eating habits.","zh":"總括而言，食物警告標籤是改變飲食習慣的有效方法。"},{"en":"Overall means after considering all the main points.","zh":"總括而言意思是在考慮所有主要觀點後。"},{"en":"Overall, a simple policy can still help if it reaches people daily.","zh":"總括而言，如果簡單政策每天接觸到人，它仍可有幫助。"},{"en":"Writers use overall to introduce a final judgement.","zh":"作者使用 overall 來引出最終判斷。"},{"en":"Overall, warning labels have limits but still offer real benefits.","zh":"總括而言，警告標籤有限制，但仍提供真正好處。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"effective way to","meaning":"有效方法去","examples":[{"en":"Food warning labels are an effective way to change habits.","zh":"食物警告標籤是改變習慣的有效方法。"},{"en":"An effective way to do something is a method that helps achieve a result.","zh":"有效方法去做某事，是指有助達成結果的方法。"},{"en":"Daily reading is an effective way to improve vocabulary.","zh":"每天閱讀是提升詞彙的有效方法。"},{"en":"Labels are effective because they guide people at the buying moment.","zh":"標籤有效，因為它們在購買一刻引導人們。"},{"en":"An effective way does not need to be the only way.","zh":"有效方法不需要是唯一方法。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"hidden risks","meaning":"隱藏風險","examples":[{"en":"Warning labels make hidden risks visible.","zh":"警告標籤令隱藏風險變得可見。"},{"en":"Hidden risks are dangers that are not easy to see at first.","zh":"隱藏風險是一開始不容易看見的危險。"},{"en":"A sweet drink may have hidden risks if its sugar level is not obvious.","zh":"如果甜飲品的糖分不明顯，它可能有隱藏風險。"},{"en":"Hidden risks are dangerous because people may act without enough information.","zh":"隱藏風險危險，因為人們可能在資訊不足下行動。"},{"en":"Labels protect consumers by bringing hidden risks to the surface.","zh":"標籤透過把隱藏風險帶到表面來保護消費者。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"make hidden risks visible","meaning":"令隱藏風險變得可見","examples":[{"en":"Labels make hidden nutritional risks visible.","zh":"標籤令隱藏的營養風險變得可見。"},{"en":"To make hidden risks visible means to show dangers that were not obvious before.","zh":"令隱藏風險變得可見意思是顯示之前不明顯的危險。"},{"en":"A high-salt label makes hidden risk visible on instant noodles.","zh":"高鹽標籤令即食麵上的隱藏風險變得可見。"},{"en":"Visible risks help people think before they buy.","zh":"可見風險幫助人們購買前三思。"},{"en":"Warning labels make hidden risks visible without requiring long calculations.","zh":"警告標籤不需長時間計算，也能令隱藏風險變得可見。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"influence manufacturers","meaning":"影響製造商","examples":[{"en":"Warning labels can influence manufacturers.","zh":"警告標籤可以影響製造商。"},{"en":"To influence manufacturers means to affect how companies design or sell products.","zh":"影響製造商意思是影響公司如何設計或銷售產品。"},{"en":"Labels may influence manufacturers to reduce salt in instant meals.","zh":"標籤可能影響製造商減少即食餐中的鹽分。"},{"en":"Manufacturers change when warnings threaten sales or reputation.","zh":"當警告威脅銷售或聲譽時，製造商會改變。"},{"en":"Influencing manufacturers can improve food choices for everyone.","zh":"影響製造商可以改善所有人的食物選擇。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"quicker, wiser choices","meaning":"更快捷、更明智的選擇","examples":[{"en":"Labels help families make quicker, wiser choices.","zh":"標籤幫助家庭作出更快捷、更明智的選擇。"},{"en":"Quicker, wiser choices are decisions made faster and with better judgement.","zh":"更快捷、更明智的選擇是更快作出且判斷更好的決定。"},{"en":"A parent makes a quicker, wiser choice when a clear label shows high sugar.","zh":"當清晰標籤顯示高糖時，家長就能作出更快捷、更明智的選擇。"},{"en":"Simple warnings save time because families do not need to study every number.","zh":"簡單警告節省時間，因為家庭不用研究每個數字。"},{"en":"Quicker, wiser choices are useful in busy supermarkets.","zh":"更快捷、更明智的選擇在忙碌超級市場中特別有用。"}],"source":"2020 Q6.pdf","sourcePage":14},{"front":"governments should therefore","meaning":"因此政府應該","examples":[{"en":"Governments should therefore keep labels simple and prominent.","zh":"因此政府應該保持標籤簡單和顯眼。"},{"en":"Governments should therefore means this is what governments ought to do as a result.","zh":"因此政府應該意思是基於前面原因，政府應做某事。"},{"en":"If labels are hard to read, governments should therefore improve their design.","zh":"如果標籤難以閱讀，因此政府應該改善設計。"},{"en":"This phrase connects evidence with a policy recommendation.","zh":"這個短語把證據和政策建議連接起來。"},{"en":"Governments should therefore support labels with education and fair rules.","zh":"因此政府應該以教育和公平規則支持標籤。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"simple, prominent and standardised","meaning":"簡單、顯眼和標準化","examples":[{"en":"Labels should be simple, prominent and standardised.","zh":"標籤應該簡單、顯眼和標準化。"},{"en":"Simple, prominent and standardised means easy to understand, easy to see, and used in the same way.","zh":"簡單、顯眼和標準化意思是容易理解、容易看見，並以相同方式使用。"},{"en":"A clear red label on the front of every packet is simple, prominent and standardised.","zh":"每個包裝正面都有清晰紅色標籤，就是簡單、顯眼和標準化。"},{"en":"Standard design helps consumers compare products quickly.","zh":"標準設計幫助消費者快速比較產品。"},{"en":"Labels lose power if they are confusing, hidden, or inconsistent.","zh":"如果標籤混亂、隱藏或不一致，它們會失去力量。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"prominent","meaning":"顯眼的","examples":[{"en":"Warning labels should be prominent on the packet.","zh":"警告標籤應在包裝上顯眼。"},{"en":"Prominent means easy to see because something stands out clearly.","zh":"顯眼的意思是清楚突出，容易看見。"},{"en":"A large warning on the front of a box is prominent.","zh":"盒子正面的大型警告就是顯眼的。"},{"en":"Prominent labels help busy shoppers notice health risks quickly.","zh":"顯眼標籤幫助忙碌購物者快速注意健康風險。"},{"en":"A warning printed on the back in tiny letters is not prominent enough.","zh":"印在背面細字中的警告不夠顯眼。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"standardised","meaning":"標準化的","examples":[{"en":"Warning labels should be standardised across products.","zh":"警告標籤應在不同產品上標準化。"},{"en":"Standardised means following the same design, rule, or format.","zh":"標準化的意思是遵循相同設計、規則或格式。"},{"en":"Standardised labels use similar colours, words, and positions on packages.","zh":"標準化標籤在包裝上使用相似顏色、字眼和位置。"},{"en":"Standardisation helps consumers understand warnings without learning a new system each time.","zh":"標準化幫助消費者不用每次學新系統也能理解警告。"},{"en":"If labels are not standardised, companies may hide warnings creatively.","zh":"如果標籤不標準化，公司可能以創意方式隱藏警告。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"interpret them","meaning":"解讀它們","examples":[{"en":"Schools should teach students how to interpret warning labels.","zh":"學校應教學生如何解讀警告標籤。"},{"en":"To interpret them means to understand what the labels mean and how to use them.","zh":"解讀它們意思是理解標籤的意思，以及如何使用它們。"},{"en":"Students interpret them by learning that “high in sugar” means a health risk.","zh":"學生明白「高糖」代表健康風險時，就是在解讀它們。"},{"en":"Teaching students to interpret labels turns warnings into practical knowledge.","zh":"教學生解讀標籤，可以把警告變成實用知識。"},{"en":"Without guidance, some students may see labels but not interpret them correctly.","zh":"沒有指引，有些學生可能看見標籤卻不能正確解讀它們。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"reformulate products","meaning":"重新調整產品配方","examples":[{"en":"Manufacturers should reformulate products instead of defending unhealthy recipes.","zh":"製造商應重新調整產品配方，而不是為不健康配方辯護。"},{"en":"To reformulate products means to change their ingredients or recipe.","zh":"重新調整產品配方意思是改變產品成分或食譜。"},{"en":"A company may reformulate products by reducing sugar in cereal.","zh":"公司可能透過減少早餐穀物中的糖來重新調整產品配方。"},{"en":"Reformulation can help products avoid warning labels.","zh":"重新調整配方可以幫助產品避免警告標籤。"},{"en":"Reformulating products improves choice more than simply changing advertisements.","zh":"重新調整產品配方比只改變廣告更能改善選擇。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"instead of merely","meaning":"而不是只顧","examples":[{"en":"Manufacturers should reformulate products instead of merely defending them.","zh":"製造商應重新調整產品配方，而不是只顧為它們辯護。"},{"en":"Instead of merely means rather than only doing a limited or weak action.","zh":"而不是只顧意思是不是只做有限或不足的行動。"},{"en":"Schools should improve lunches instead of merely telling students to eat better.","zh":"學校應改善午餐，而不是只顧叫學生吃得更好。"},{"en":"Companies should reduce sugar instead of merely explaining why it tastes good.","zh":"公司應減糖，而不是只顧解釋它為何好味。"},{"en":"This phrase contrasts real action with insufficient response.","zh":"這個短語把真正行動和不足回應作對比。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"defend unhealthy recipes","meaning":"為不健康配方辯護","examples":[{"en":"Companies should not merely defend unhealthy recipes.","zh":"公司不應只顧為不健康配方辯護。"},{"en":"To defend unhealthy recipes means to justify keeping food formulas that harm health.","zh":"為不健康配方辯護意思是為保留有害健康的食物配方找理由。"},{"en":"A company defends unhealthy recipes when it says high sugar is necessary for taste.","zh":"公司說高糖是味道所必需時，就是在為不健康配方辯護。"},{"en":"Defending unhealthy recipes may protect profit but ignore public health.","zh":"為不健康配方辯護可能保護利潤，卻忽視公共健康。"},{"en":"Companies should improve recipes rather than defend unhealthy ones.","zh":"公司應改善配方，而不是為不健康配方辯護。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"will not happen overnight","meaning":"不會一夜之間發生","examples":[{"en":"Eating well will not happen overnight.","zh":"吃得健康不會一夜之間發生。"},{"en":"Will not happen overnight means will not be achieved suddenly or quickly.","zh":"不會一夜之間發生意思是不會突然或很快達成。"},{"en":"Changing a family’s diet will not happen overnight.","zh":"改變一個家庭的飲食不會一夜之間發生。"},{"en":"Habits take time because they are built through repetition.","zh":"習慣需要時間，因為它們是透過重複建立的。"},{"en":"Warning labels help gradually, but healthier eating will not happen overnight.","zh":"警告標籤會逐漸幫助，但較健康飲食不會一夜之間發生。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"prevention is better than cure","meaning":"預防勝於治療","examples":[{"en":"Prevention is better than cure.","zh":"預防勝於治療。"},{"en":"This saying means it is wiser to stop problems before they happen than to fix them later.","zh":"這句話意思是在問題發生前阻止它，比事後補救更明智。"},{"en":"Wearing a seat belt shows that prevention is better than cure.","zh":"扣安全帶顯示預防勝於治療。"},{"en":"Warning labels support prevention by warning people before illness develops.","zh":"警告標籤在疾病出現前提醒人們，從而支持預防。"},{"en":"In public health, prevention is often cheaper and kinder than cure.","zh":"在公共健康中，預防往往比治療更便宜也更仁慈。"}],"source":"2020 Q6.pdf","sourcePage":15},{"front":"healthier citizens","meaning":"更健康的市民","examples":[{"en":"Society should aim to create healthier citizens.","zh":"社會應以培養更健康的市民為目標。"},{"en":"Healthier citizens are people whose daily habits and living conditions support better health.","zh":"更健康的市民是日常習慣和生活條件更支持健康的人。"},{"en":"Schools help create healthier citizens when they teach food knowledge early.","zh":"學校及早教授食物知識時，就是幫助培養更健康的市民。"},{"en":"Healthier citizens reduce pressure on hospitals and families.","zh":"更健康的市民可以減輕醫院和家庭壓力。"},{"en":"Warning labels are one small tool for building healthier citizens.","zh":"警告標籤是建立更健康市民的一個小工具。"}],"source":"2020 Q6.pdf","sourcePage":16},{"front":"the warning should appear before the illness","meaning":"警告應在疾病出現前出現","examples":[{"en":"The warning should appear before the illness, not after it.","zh":"警告應在疾病出現前出現，而不是之後。"},{"en":"This phrase means people should be warned early enough to prevent harm.","zh":"這個短語意思是人們應及早獲得警告，以防止傷害。"},{"en":"A sugar warning should appear before a child develops unhealthy habits.","zh":"高糖警告應在孩子形成不健康習慣前出現。"},{"en":"Early warnings matter because treatment after illness is harder.","zh":"早期警告很重要，因為疾病出現後治療更困難。"},{"en":"Public health works best when the warning appears before the illness.","zh":"當警告在疾病出現前出現時，公共健康最有效。"}],"source":"2020 Q6.pdf","sourcePage":16}],"dse/writing/part-b/2020/Q7":[{"front":"from MTR platforms to music awards","meaning":"從港鐵月台到音樂頒獎禮","examples":[{"en":"Zoe Kwan went from MTR platforms to music awards in less than a year.","zh":"Zoe Kwan 在不到一年內從港鐵月台走到音樂頒獎禮。"},{"en":"From MTR platforms to music awards means moving from ordinary street performance to public success in the music industry.","zh":"從港鐵月台到音樂頒獎禮，意思是由普通街頭表演走向音樂界的公開成功。"},{"en":"A young singer may go from MTR platforms to music awards if one honest song reaches enough listeners.","zh":"如果一首真誠的歌接觸到足夠多聽眾，年輕歌手可能從港鐵月台走到音樂頒獎禮。"},{"en":"This change can feel shocking because the singer moves from being ignored by commuters to being praised by crowds.","zh":"這種轉變會令人震驚，因為歌手由被途人忽略，變成被群眾讚賞。"},{"en":"The phrase shows a dramatic journey from everyday struggle to recognised achievement.","zh":"這個短語展示由日常掙扎走向被認可成就的戲劇性旅程。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"an unlikely first verse","meaning":"意想不到的開端","examples":[{"en":"Zoe Kwan’s career began with an unlikely first verse.","zh":"Zoe Kwan 的事業由一個意想不到的開端開始。"},{"en":"An unlikely first verse means an unexpected beginning to a song, story, or career.","zh":"an unlikely first verse 的意思是一首歌、一個故事或一段事業的意外開端。"},{"en":"A singer’s unlikely first verse may begin outside a station instead of inside a recording studio.","zh":"歌手意想不到的開端可能是在車站外，而不是錄音室裏開始。"},{"en":"Such a beginning can surprise people because success grows from a place no one considered important.","zh":"這種開端會令人驚訝，因為成功來自一個沒有人認為重要的地方。"},{"en":"This phrase suggests that a small and unusual start can lead to something much bigger.","zh":"這個短語暗示細小而不尋常的開始，可以帶來更大的發展。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"no one saw someone coming","meaning":"沒有人預料到某人會冒起","examples":[{"en":"No one saw Zoe Kwan coming.","zh":"沒有人預料到 Zoe Kwan 會冒起。"},{"en":"No one saw someone coming means nobody expected that person to become successful or important.","zh":"no one saw someone coming 的意思是沒有人預期某人會成功或變得重要。"},{"en":"No one saw the quiet student coming until her speech won the whole competition.","zh":"沒有人預料到那位安靜學生會冒起，直到她的演講贏得整個比賽。"},{"en":"People may fail to see someone coming because they judge only by appearance or background.","zh":"人們可能因只看外表或背景，而沒有預料到某人會冒起。"},{"en":"This phrase is useful when someone surprises everyone with sudden ability or success.","zh":"當某人以突然展現的能力或成功令所有人驚訝時，這個短語很有用。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"walk past","meaning":"走過；路過","examples":[{"en":"Commuters once walked past her outside Prince Edward Station.","zh":"通勤者曾經在太子站外從她身旁走過。"},{"en":"To walk past someone means to move by them without stopping.","zh":"walk past someone 的意思是從某人身邊經過而不停下來。"},{"en":"Students may walk past a notice board without reading the important announcement.","zh":"學生可能會走過告示板，卻沒有閱讀重要公告。"},{"en":"When people walk past a street performer, they may not realise how talented that person is.","zh":"當人們走過街頭表演者身旁時，他們可能沒有意識到那個人多有才華。"},{"en":"This phrase can show ordinary neglect when people are too busy to notice what is nearby.","zh":"這個短語可以展示普通的忽視，因為人們太忙而沒有留意身邊事物。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"outside Prince Edward Station","meaning":"太子站外","examples":[{"en":"She used to perform outside Prince Edward Station.","zh":"她以前在太子站外表演。"},{"en":"Outside Prince Edward Station means in the public area near the entrance or exit of Prince Edward MTR Station.","zh":"outside Prince Edward Station 的意思是在太子港鐵站入口或出口附近的公共地方。"},{"en":"A busker outside Prince Edward Station may sing to people rushing home after work.","zh":"太子站外的街頭歌手可能會向下班趕回家的途人唱歌。"},{"en":"Performing outside Prince Edward Station can be difficult because commuters are often tired and hurried.","zh":"在太子站外表演可能很困難，因為通勤者通常疲累又匆忙。"},{"en":"This setting makes her success feel local and believable.","zh":"這個背景令她的成功感覺本地而可信。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"the quiet girl with the guitar","meaning":"那個拿着結他的安靜女生","examples":[{"en":"Her classmates knew her as the quiet girl with the guitar.","zh":"她的同學都認識她是那個拿着結他的安靜女生。"},{"en":"The quiet girl with the guitar describes someone shy or reserved who is strongly linked with music.","zh":"the quiet girl with the guitar 描述一個害羞或內向、並與音樂緊密相連的人。"},{"en":"In school, the quiet girl with the guitar may say little but sing honestly during lunch breaks.","zh":"在學校裏，那個拿着結他的安靜女生可能說話不多，但在午休時真誠地唱歌。"},{"en":"People may underestimate the quiet girl with the guitar because she does not seek attention.","zh":"人們可能低估那個拿着結他的安靜女生，因為她不刻意吸引注意。"},{"en":"This phrase helps create a gentle image before showing her unexpected success.","zh":"這個短語在展示她意想不到的成功之前，先塑造一個溫柔形象。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"certainly not","meaning":"當然不是","examples":[{"en":"Certainly not Zoe herself expected such success.","zh":"當然不是 Zoe 自己預料到這樣的成功。"},{"en":"Certainly not means definitely not or especially not in a surprising situation.","zh":"certainly not 的意思是絕對不是，或在令人驚訝的情況中特別不是。"},{"en":"Many people did not expect the song to go viral, and certainly not the shy singer herself.","zh":"很多人沒有預期那首歌會爆紅，當然那位害羞歌手自己也沒有。"},{"en":"This phrase adds emphasis when one person is the least likely to believe something would happen.","zh":"當某人最不可能相信某事會發生時，這個短語可以加強語氣。"},{"en":"It often shows surprise by strongly rejecting an expected idea.","zh":"它常透過強烈否定某個預期想法來表達驚訝。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"singer-songwriter","meaning":"創作歌手","examples":[{"en":"The 19-year-old singer-songwriter won Best New Artist.","zh":"這位十九歲創作歌手贏得最佳新人。"},{"en":"A singer-songwriter is a musician who both sings and writes their own songs.","zh":"singer-songwriter 是既唱歌又創作自己歌曲的音樂人。"},{"en":"A singer-songwriter may turn personal feelings into lyrics and melodies.","zh":"創作歌手可以把個人感受變成歌詞和旋律。"},{"en":"Because a singer-songwriter creates the music as well as performs it, the songs can feel more personal.","zh":"因為創作歌手既創作音樂也演唱歌曲，作品可以感覺更個人化。"},{"en":"This term is useful when an artist is not only a voice but also a creator.","zh":"當一位藝人不只是聲音，也是創作者時，這個詞很有用。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"stand under the dazzling lights","meaning":"站在耀眼燈光下","examples":[{"en":"She stood under the dazzling lights of the HKTV Music Awards.","zh":"她站在 HKTV 音樂頒獎禮的耀眼燈光下。"},{"en":"To stand under the dazzling lights means to appear on a bright public stage, often during an important event.","zh":"stand under the dazzling lights 的意思是出現在明亮的公開舞台上，通常是在重要活動中。"},{"en":"A young performer may feel nervous when standing under the dazzling lights for the first time.","zh":"年輕表演者第一次站在耀眼燈光下時，可能會感到緊張。"},{"en":"The lights can symbolise fame because everyone is suddenly looking at the person.","zh":"燈光可以象徵名氣，因為所有人突然都在注視那個人。"},{"en":"This phrase contrasts private struggle with public recognition.","zh":"這個短語把私下掙扎與公開認可形成對比。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"hold the trophy for","meaning":"手持……獎座","examples":[{"en":"She held the trophy for Best New Artist.","zh":"她手持最佳新人獎座。"},{"en":"To hold the trophy for an award means to receive and physically carry the prize for winning it.","zh":"hold the trophy for an award 的意思是贏得某獎項並親手拿着獎座。"},{"en":"The athlete held the trophy for first place while her teammates cheered.","zh":"那位運動員手持冠軍獎座，而隊友在旁歡呼。"},{"en":"Holding the trophy can make success feel real after months or years of effort.","zh":"在數月或數年努力後，手持獎座可以令成功感覺真實。"},{"en":"This phrase often appears in scenes of achievement and emotion.","zh":"這個短語常出現在成就與情感交織的場面中。"}],"source":"2020 Q7.pdf","sourcePage":1},{"front":"Best New Artist","meaning":"最佳新人","examples":[{"en":"Zoe won the award for Best New Artist.","zh":"Zoe 贏得最佳新人獎。"},{"en":"Best New Artist is an award given to a new performer who has made a strong first impression.","zh":"Best New Artist 是頒給留下強烈初步印象的新表演者的獎項。"},{"en":"A singer may win Best New Artist after releasing a song that many young listeners love.","zh":"歌手推出一首受許多年輕聽眾喜愛的歌後，可能贏得最佳新人。"},{"en":"Winning Best New Artist can help a newcomer gain more attention and opportunities.","zh":"贏得最佳新人可以幫助新人獲得更多關注和機會。"},{"en":"This award recognises promise as well as early success.","zh":"這個獎項認可潛力，也認可早期成功。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"trembling hands","meaning":"顫抖的雙手","examples":[{"en":"She held the trophy with trembling hands.","zh":"她用顫抖的雙手拿着獎座。"},{"en":"Trembling hands are hands that shake because of fear, excitement, cold, or strong emotion.","zh":"顫抖的雙手，是指因害怕、興奮、寒冷或強烈情緒而發抖的手。"},{"en":"A student may hold a speech card with trembling hands before speaking on stage.","zh":"學生上台演講前，可能用顫抖的雙手拿着演講卡。"},{"en":"Trembling hands can show that a person is overwhelmed by the importance of the moment.","zh":"顫抖的雙手可以顯示一個人被當下的重要性壓倒。"},{"en":"In a story, this detail makes success feel human and fragile.","zh":"在故事中，這個細節令成功顯得有人性而脆弱。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"tearful eyes","meaning":"含淚的雙眼","examples":[{"en":"She accepted the award with tearful eyes.","zh":"她含淚接受獎項。"},{"en":"Tearful eyes are eyes filled with tears because someone feels deeply moved, sad, or grateful.","zh":"tearful eyes 是指因深受感動、悲傷或感激而充滿眼淚的雙眼。"},{"en":"A mother may have tearful eyes when her child graduates.","zh":"孩子畢業時，母親可能會含淚。"},{"en":"Tearful eyes can show emotion before a person says anything.","zh":"含淚的雙眼可以在一個人開口前先顯示情感。"},{"en":"This detail helps readers understand that the award means more than public praise.","zh":"這個細節幫助讀者明白，這個獎不只是公開讚賞。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"it turns out","meaning":"結果是；原來","examples":[{"en":"It turns out she cried because she won.","zh":"原來她哭是因為她贏了。"},{"en":"It turns out introduces the real explanation after people may have guessed something else.","zh":"it turns out 用來在別人可能有其他猜測後，介紹真正解釋。"},{"en":"It turns out the quiet student had been practising the song for months.","zh":"原來那位安靜學生已經練習那首歌幾個月。"},{"en":"This phrase is useful when new information changes how we understand a situation.","zh":"當新資料改變我們對情況的理解時，這個短語很有用。"},{"en":"It often creates a small surprise by revealing the truth.","zh":"它常透過揭示真相製造小小驚訝。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"sudden rise to fame","meaning":"突然成名","examples":[{"en":"Zoe’s sudden rise to fame has been remarkable.","zh":"Zoe 突然成名的過程非常出色。"},{"en":"A sudden rise to fame is a quick change from being unknown to being widely recognised.","zh":"sudden rise to fame 是由默默無聞快速變成廣為人知。"},{"en":"A singer’s sudden rise to fame may begin when one online clip spreads quickly.","zh":"歌手突然成名，可能始於一段網上短片迅速流傳。"},{"en":"Sudden fame can bring opportunities, but it can also create pressure.","zh":"突然成名可以帶來機會，但也可以帶來壓力。"},{"en":"This phrase shows both the speed and the surprise of becoming well known.","zh":"這個短語展示成名的速度和意外性。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"nothing short of remarkable","meaning":"非常出色；非凡","examples":[{"en":"Her rise to fame has been nothing short of remarkable.","zh":"她成名的過程可說非常非凡。"},{"en":"Nothing short of remarkable means truly extraordinary or extremely impressive.","zh":"nothing short of remarkable 的意思是真正非凡或極其令人印象深刻。"},{"en":"A student who improves from failing to winning a prize is nothing short of remarkable.","zh":"一名學生由不及格進步到獲獎，可說非常出色。"},{"en":"This phrase is used when ordinary praise does not seem strong enough.","zh":"當普通讚美似乎不夠強烈時，可以使用這個短語。"},{"en":"It emphasises that the achievement deserves serious attention.","zh":"它強調該成就值得認真注意。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"up until last year","meaning":"直到去年為止","examples":[{"en":"Up until last year, she was performing acoustic covers after school.","zh":"直到去年為止，她還在放學後演唱原音翻唱歌曲。"},{"en":"Up until last year means continuing until the end of the previous year or before a recent change.","zh":"up until last year 的意思是一直持續到去年，或直到最近改變之前。"},{"en":"Up until last year, he had never sung in front of a large audience.","zh":"直到去年為止，他從未在大量觀眾面前唱歌。"},{"en":"This phrase helps show contrast between someone’s old life and present situation.","zh":"這個短語幫助展示某人過去生活與現在情況的對比。"},{"en":"It is often used before describing a surprising change.","zh":"它常在描述令人驚訝的轉變之前使用。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"perform acoustic covers","meaning":"演唱原音翻唱歌曲","examples":[{"en":"She performed acoustic covers after school.","zh":"她放學後演唱原音翻唱歌曲。"},{"en":"To perform acoustic covers means to sing or play simple versions of other people’s songs, usually with instruments like a guitar.","zh":"perform acoustic covers 的意思是用結他等樂器演唱或演奏別人的歌曲的簡約版本。"},{"en":"A student may perform acoustic covers in a café before writing her own songs.","zh":"學生在創作自己的歌曲前，可能會在咖啡店演唱原音翻唱歌曲。"},{"en":"Performing acoustic covers can help a young singer practise voice, rhythm, and confidence.","zh":"演唱原音翻唱歌曲可以幫助年輕歌手練習聲線、節奏和信心。"},{"en":"This activity often becomes a first step before original music.","zh":"這項活動常成為原創音樂之前的第一步。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"after school","meaning":"放學後","examples":[{"en":"She used to sing after school.","zh":"她以前放學後唱歌。"},{"en":"After school means during the time after classes have finished for the day.","zh":"after school 的意思是一天課堂結束之後的時間。"},{"en":"Students may practise music after school before going home for dinner.","zh":"學生可能在放學後練習音樂，然後回家吃晚飯。"},{"en":"A regular after-school habit can slowly turn into a serious skill.","zh":"規律的放學後習慣，可以慢慢變成真正的技能。"},{"en":"This phrase shows that the activity happens outside normal lesson time.","zh":"這個短語表示活動發生在正常上課時間之外。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"upload short clips to social media","meaning":"上載短片到社交媒體","examples":[{"en":"She uploaded short clips to social media.","zh":"她把短片上載到社交媒體。"},{"en":"To upload short clips to social media means to put brief videos online for others to watch.","zh":"upload short clips to social media 的意思是把短影片放到網上讓別人觀看。"},{"en":"A singer may upload short clips to social media to test whether people like her voice.","zh":"歌手可能會把短片上載到社交媒體，以測試別人是否喜歡她的聲音。"},{"en":"Uploading clips can attract attention quickly if viewers share them.","zh":"如果觀眾分享影片，上載短片可以很快吸引注意。"},{"en":"This phrase shows how modern artists can reach audiences without a record company at first.","zh":"這個短語展示現代藝人起初不靠唱片公司，也能接觸觀眾。"}],"source":"2020 Q7.pdf","sourcePage":2},{"front":"social media","meaning":"社交媒體","examples":[{"en":"Her song became popular on social media.","zh":"她的歌曲在社交媒體上流行起來。"},{"en":"Social media refers to online platforms where people share posts, videos, comments, and messages.","zh":"social media 是指人們分享帖文、影片、評論和訊息的網上平台。"},{"en":"A song can spread on social media when users share it with friends.","zh":"當用戶把歌曲分享給朋友時，歌曲可以在社交媒體上流傳。"},{"en":"Social media can make an unknown singer famous very quickly.","zh":"社交媒體可以令一位無名歌手很快成名。"},{"en":"However, attention on social media can also disappear quickly if people move on.","zh":"不過，如果人們轉移注意，社交媒體上的關注也可以很快消失。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"help her mother at","meaning":"在……幫媽媽手","examples":[{"en":"She helped her mother at a small flower shop.","zh":"她在一間小花店幫媽媽手。"},{"en":"To help her mother at a place means to assist her mother with work there.","zh":"help her mother at a place 的意思是在某個地方協助母親工作。"},{"en":"A teenager may help her mother at a bakery by serving customers after school.","zh":"青少年可能放學後在麵包店幫媽媽手，招呼顧客。"},{"en":"Helping her mother at the shop can teach responsibility and patience.","zh":"在店裏幫媽媽手可以教會人責任和耐性。"},{"en":"This phrase shows ordinary family duty behind a public success story.","zh":"這個短語展示公開成功故事背後的普通家庭責任。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"a small flower shop","meaning":"小花店","examples":[{"en":"Her mother owned a small flower shop in Tai Kok Tsui.","zh":"她媽媽在大角咀擁有一間小花店。"},{"en":"A small flower shop is a modest store that sells flowers, plants, and simple gifts.","zh":"小花店是售賣鮮花、植物和簡單禮物的小型店舖。"},{"en":"A small flower shop may serve neighbours buying flowers for birthdays or hospital visits.","zh":"小花店可以服務為生日或探病買花的鄰居。"},{"en":"Running a small flower shop can be tiring because flowers must be cared for every day.","zh":"經營小花店可能很累，因為鮮花每天都需要照顧。"},{"en":"This setting gives Zoe’s story a humble and everyday background.","zh":"這個背景令 Zoe 的故事帶有謙卑而日常的起點。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"breakthrough came when","meaning":"突破出現在……的時候","examples":[{"en":"Her breakthrough came when a video of her song was reposted.","zh":"她的突破出現在她歌曲的影片被轉發的時候。"},{"en":"Breakthrough came when means success began at the moment a key event happened.","zh":"breakthrough came when 的意思是成功在某個關鍵事件發生時開始。"},{"en":"A student’s breakthrough came when one teacher finally noticed her writing talent.","zh":"一名學生的突破出現在一位老師終於注意到她寫作才華的時候。"},{"en":"A breakthrough can change a person’s path because others suddenly pay attention.","zh":"突破可以改變一個人的道路，因為別人突然開始注意。"},{"en":"This phrase helps identify the turning point in a story.","zh":"這個短語幫助指出故事中的轉捩點。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"a 45-second video","meaning":"一段45秒影片","examples":[{"en":"A 45-second video of her song went viral.","zh":"她歌曲的一段45秒影片爆紅。"},{"en":"A 45-second video is a very short clip that lasts less than one minute.","zh":"一段45秒影片，是指長度少於一分鐘的短片。"},{"en":"A 45-second video can show enough of a song to make listeners curious.","zh":"一段45秒影片可以展示一首歌的足夠部分，令聽眾感到好奇。"},{"en":"Short videos often spread quickly because people can watch and share them easily.","zh":"短片常迅速流傳，因為人們可以輕易觀看和分享。"},{"en":"This phrase shows how a brief moment can create a major change.","zh":"這個短語展示短短一刻如何造成重大改變。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"original song","meaning":"原創歌曲","examples":[{"en":"Last Train Home was Zoe’s original song.","zh":"《Last Train Home》是 Zoe 的原創歌曲。"},{"en":"An original song is a song written or created by the performer, not copied from another artist.","zh":"original song 是由表演者寫作或創作的歌曲，不是翻唱其他藝人的作品。"},{"en":"A singer may feel more nervous performing an original song because it reveals personal ideas.","zh":"歌手演唱原創歌曲時可能更緊張，因為它揭示個人想法。"},{"en":"Original songs help listeners understand an artist’s own voice and feelings.","zh":"原創歌曲幫助聽眾理解藝人自己的聲音和感受。"},{"en":"This phrase separates creative work from covers.","zh":"這個短語把創作作品與翻唱分開。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"be reposted by","meaning":"被……轉發","examples":[{"en":"The video was reposted by a popular music blogger.","zh":"這段影片被一位受歡迎的音樂博客轉發。"},{"en":"To be reposted by someone means to be shared again on that person’s online account.","zh":"be reposted by someone 的意思是被某人在其網上帳戶再次分享。"},{"en":"A drawing may be reposted by an art teacher and then reach many students.","zh":"一幅畫可能被美術老師轉發，然後接觸到許多學生。"},{"en":"When a video is reposted by someone influential, many more people may see it.","zh":"當影片被有影響力的人轉發時，更多人可能會看到它。"},{"en":"This phrase shows how online attention can spread through sharing.","zh":"這個短語展示網上關注如何透過分享擴散。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"popular music blogger","meaning":"受歡迎的音樂博客","examples":[{"en":"A popular music blogger reposted her video.","zh":"一位受歡迎的音樂博客轉發了她的影片。"},{"en":"A popular music blogger is an online writer or creator followed by many people for music opinions and recommendations.","zh":"受歡迎的音樂博客，是因音樂意見和推薦而被許多人追蹤的網上作者或創作者。"},{"en":"A popular music blogger may introduce unknown singers to a wider audience.","zh":"受歡迎的音樂博客可以把無名歌手介紹給更廣泛的觀眾。"},{"en":"If a popular music blogger praises a song, listeners may try it immediately.","zh":"如果受歡迎的音樂博客讚賞一首歌，聽眾可能會立刻試聽。"},{"en":"This person can become important because online taste often spreads through trusted voices.","zh":"這種人可以變得重要，因為網上品味常透過可信聲音傳播。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"by the next morning","meaning":"到第二天早上","examples":[{"en":"By the next morning, the clip had gathered hundreds of thousands of views.","zh":"到第二天早上，這段短片已累積數十萬瀏覽量。"},{"en":"By the next morning means before or when the following morning arrived.","zh":"by the next morning 的意思是在翌日早上到來之前或之時。"},{"en":"By the next morning, the school video had been shared by almost every class.","zh":"到第二天早上，學校影片已被幾乎每班分享。"},{"en":"This phrase shows that something happened very quickly overnight.","zh":"這個短語顯示某事在一夜之間很快發生。"},{"en":"It is often used to create a sense of sudden change.","zh":"它常用來製造突然轉變的感覺。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"gather hundreds of thousands of views","meaning":"累積數十萬瀏覽量","examples":[{"en":"The clip gathered hundreds of thousands of views.","zh":"這段短片累積數十萬瀏覽量。"},{"en":"To gather hundreds of thousands of views means to be watched online by several hundred thousand people.","zh":"gather hundreds of thousands of views 的意思是在網上被數十萬人觀看。"},{"en":"A simple cooking video can gather hundreds of thousands of views if it solves a common problem.","zh":"如果簡單烹飪影片解決常見問題，它可以累積數十萬瀏覽量。"},{"en":"Gathering many views can bring attention from fans, reporters, and companies.","zh":"累積大量瀏覽量可以帶來歌迷、記者和公司的注意。"},{"en":"This phrase shows measurable online popularity.","zh":"這個短語展示可量度的網上人氣。"}],"source":"2020 Q7.pdf","sourcePage":3},{"front":"by the end of the week","meaning":"到該星期結束時","examples":[{"en":"By the end of the week, record companies were calling.","zh":"到該星期結束時，唱片公司已開始打電話來。"},{"en":"By the end of the week means before that week finished.","zh":"by the end of the week 的意思是在那個星期完結之前。"},{"en":"By the end of the week, the new café had sold out every dessert.","zh":"到該星期結束時，那間新咖啡店已售罄所有甜品。"},{"en":"This phrase shows how quickly a situation develops over a few days.","zh":"這個短語展示情況如何在幾天內迅速發展。"},{"en":"It often appears when early success leads to new opportunities.","zh":"它常出現在早期成功帶來新機會時。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"record companies","meaning":"唱片公司","examples":[{"en":"Record companies started calling Zoe.","zh":"唱片公司開始打電話給 Zoe。"},{"en":"Record companies are businesses that sign artists, produce music, and help release songs or albums.","zh":"record companies 是簽約藝人、製作音樂並協助推出歌曲或專輯的公司。"},{"en":"Record companies may contact a singer after her online video becomes popular.","zh":"歌手的網上影片流行後，唱片公司可能會聯絡她。"},{"en":"A record company can provide money, promotion, producers, and professional support.","zh":"唱片公司可以提供資金、宣傳、監製和專業支援。"},{"en":"This phrase belongs to the music industry and often signals a career turning point.","zh":"這個短語屬於音樂業，常表示事業轉捩點。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"checking homework messages","meaning":"查看功課訊息","examples":[{"en":"One moment she was checking homework messages.","zh":"前一刻她還在查看功課訊息。"},{"en":"Checking homework messages means reading school-related messages about assignments or classwork.","zh":"checking homework messages 的意思是閱讀關於作業或課堂功課的學校訊息。"},{"en":"A student may be checking homework messages on her phone while waiting for the bus.","zh":"學生等巴士時，可能在手機上查看功課訊息。"},{"en":"This ordinary action can contrast sharply with sudden fame.","zh":"這個普通行動可以與突然成名形成鮮明對比。"},{"en":"The phrase reminds readers that Zoe was still living a normal student life.","zh":"這個短語提醒讀者，Zoe 仍過着普通學生生活。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"strangers were asking","meaning":"陌生人在問","examples":[{"en":"Strangers were asking when her album would come out.","zh":"陌生人在問她的專輯何時會推出。"},{"en":"Strangers were asking means people she did not know began showing interest or asking questions.","zh":"strangers were asking 的意思是她不認識的人開始表示興趣或提出問題。"},{"en":"After the performance, strangers were asking where they could hear more of her songs.","zh":"表演後，陌生人在問哪裏可以聽到她更多歌曲。"},{"en":"When strangers start asking about someone’s future work, public attention has clearly grown.","zh":"當陌生人開始詢問某人未來作品時，公眾關注明顯增加。"},{"en":"This phrase shows the strange shift from private life to public curiosity.","zh":"這個短語展示由私人生活轉向公眾好奇的奇怪變化。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"album would come out","meaning":"專輯會推出","examples":[{"en":"People asked when her album would come out.","zh":"人們問她的專輯何時會推出。"},{"en":"When an album would come out means when a collection of songs would be released to the public.","zh":"album would come out 的意思是一組歌曲何時會向公眾發行。"},{"en":"Fans may ask when the album will come out after hearing a singer’s first single.","zh":"歌迷聽過歌手第一首單曲後，可能會問專輯何時會推出。"},{"en":"An album coming out can mark a bigger step in an artist’s career.","zh":"專輯推出可以標誌藝人事業更大的一步。"},{"en":"This phrase is commonly used when discussing music releases.","zh":"這個短語常用於討論音樂發行。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"what makes someone’s story refreshing","meaning":"令某人的故事令人耳目一新的地方","examples":[{"en":"What makes Zoe’s story refreshing is the way she has remained grounded.","zh":"令 Zoe 的故事令人耳目一新的地方，是她一直保持腳踏實地。"},{"en":"What makes someone’s story refreshing means the special quality that makes the person’s story feel new, honest, or pleasant.","zh":"what makes someone’s story refreshing 的意思是令某人的故事感覺新鮮、真誠或舒服的特質。"},{"en":"What makes a young athlete’s story refreshing may be her kindness after winning.","zh":"令年輕運動員的故事令人耳目一新的地方，可能是她勝利後仍保持善良。"},{"en":"A story feels refreshing when success does not make the person arrogant.","zh":"當成功沒有令一個人變得傲慢，故事就會令人耳目一新。"},{"en":"This phrase is useful for introducing the most attractive part of a person’s journey.","zh":"這個短語適合用來介紹某人旅程中最吸引人的部分。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"the speed of her success","meaning":"成功的速度","examples":[{"en":"The speed of her success surprised many people.","zh":"她成功的速度令許多人驚訝。"},{"en":"The speed of her success means how quickly she became successful.","zh":"the speed of her success 的意思是她成功得有多快。"},{"en":"The speed of her success was unusual because she went from school to award shows in months.","zh":"她成功的速度很不尋常，因為她在幾個月內由校園走到頒獎禮。"},{"en":"Fast success can excite people, but it can also give the artist little time to adjust.","zh":"快速成功可以令人興奮，但也可能令藝人沒有太多時間適應。"},{"en":"This phrase focuses on the pace of change, not only the result.","zh":"這個短語着重轉變的速度，而不只是結果。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"remain grounded","meaning":"保持腳踏實地","examples":[{"en":"Zoe has remained grounded despite her sudden fame.","zh":"儘管突然成名，Zoe 仍保持腳踏實地。"},{"en":"To remain grounded means to stay humble, sensible, and connected to real life.","zh":"remain grounded 的意思是保持謙遜、理性，並與現實生活保持連繫。"},{"en":"A famous student may remain grounded by still helping at home and listening to old friends.","zh":"成名學生仍在家幫忙並聆聽老朋友時，就是保持腳踏實地。"},{"en":"Remaining grounded can protect a person from becoming arrogant after success.","zh":"保持腳踏實地可以保護一個人在成功後不變得傲慢。"},{"en":"This phrase praises someone who does not let fame change their values.","zh":"這個短語讚賞某人沒有讓名氣改變價值觀。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"all the while","meaning":"一直；期間始終","examples":[{"en":"She has remained grounded all the while.","zh":"她期間始終保持腳踏實地。"},{"en":"All the while means during the whole time that something else was happening.","zh":"all the while 的意思是在另一件事發生的整段期間。"},{"en":"The singer became famous, but all the while she kept attending school.","zh":"那位歌手成名了，但一直仍繼續上學。"},{"en":"This phrase shows that one condition continued through many changes.","zh":"這個短語顯示某種狀態在許多改變中持續。"},{"en":"It is useful when emphasising steady behaviour during a busy period.","zh":"當強調某人在忙碌時期仍保持穩定行為時，這個短語很有用。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"in person","meaning":"親身見面時","examples":[{"en":"In person, Zoe is soft-spoken and cautious.","zh":"親身見面時，Zoe 說話溫柔而謹慎。"},{"en":"In person means when meeting someone directly rather than seeing them online or on screen.","zh":"in person 的意思是直接見到某人，而不是在網上或螢幕上看到。"},{"en":"An artist may seem confident on stage but quiet in person.","zh":"藝人在舞台上可能顯得自信，但親身見面時很安靜。"},{"en":"Meeting someone in person can reveal details that interviews or videos do not show.","zh":"親身見面可以揭示訪問或影片沒有展示的細節。"},{"en":"This phrase helps compare public image with real-life presence.","zh":"這個短語幫助比較公眾形象與現實中的樣子。"}],"source":"2020 Q7.pdf","sourcePage":4},{"front":"soft-spoken","meaning":"說話溫柔的；輕聲細語的","examples":[{"en":"Zoe is soft-spoken in interviews.","zh":"Zoe 在訪問中說話溫柔。"},{"en":"Soft-spoken means speaking in a gentle, quiet, and calm way.","zh":"soft-spoken 的意思是以溫柔、輕聲而平靜的方式說話。"},{"en":"A soft-spoken teacher can still control a class through patience and clarity.","zh":"說話溫柔的老師仍可以透過耐性和清晰表達管理課堂。"},{"en":"Being soft-spoken does not mean a person lacks confidence.","zh":"說話溫柔並不代表一個人缺乏信心。"},{"en":"This word often describes someone whose quiet voice feels sincere or thoughtful.","zh":"這個詞常形容聲音安靜但感覺真誠或深思熟慮的人。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"almost cautious","meaning":"幾乎顯得謹慎","examples":[{"en":"She is almost cautious when choosing her words.","zh":"她斟酌用詞時幾乎顯得謹慎。"},{"en":"Almost cautious means nearly careful to the point of hesitation.","zh":"almost cautious 的意思是幾乎小心得有點猶豫。"},{"en":"A new artist may sound almost cautious because she does not want to be misunderstood.","zh":"新藝人可能聽起來幾乎顯得謹慎，因為她不想被誤解。"},{"en":"People become almost cautious when public attention makes every sentence feel important.","zh":"當公眾關注令每句說話都顯得重要時，人們會幾乎顯得謹慎。"},{"en":"This phrase suggests sensitivity rather than weakness.","zh":"這個短語暗示敏感，而不是軟弱。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"choose her words","meaning":"斟酌用詞","examples":[{"en":"She chooses her words slowly and carefully.","zh":"她慢慢而仔細地斟酌用詞。"},{"en":"To choose her words means to think carefully about what to say.","zh":"choose her words 的意思是仔細思考該說甚麼。"},{"en":"A student may choose her words before apologising to a friend.","zh":"學生向朋友道歉前，可能會斟酌用詞。"},{"en":"People choose their words carefully when a topic is emotional or easily misunderstood.","zh":"當話題帶有情緒或容易被誤解時，人們會仔細斟酌用詞。"},{"en":"This phrase shows thoughtfulness in speech.","zh":"這個短語展示說話中的深思熟慮。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"choose her chords","meaning":"選擇和弦","examples":[{"en":"She chooses her chords slowly and carefully.","zh":"她慢慢而仔細地選擇和弦。"},{"en":"To choose her chords means to select the groups of musical notes that shape a song’s mood.","zh":"choose her chords 的意思是選擇塑造歌曲氣氛的一組組音符。"},{"en":"A songwriter may choose her chords carefully to make a sad lyric feel gentle instead of heavy.","zh":"創作人可能仔細選擇和弦，讓悲傷歌詞感覺溫柔而不是沉重。"},{"en":"The wrong chords can change the feeling of a song completely.","zh":"錯誤的和弦可以完全改變歌曲感覺。"},{"en":"This phrase shows musical care and emotional control.","zh":"這個短語展示音樂上的用心和情感控制。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"with feeling","meaning":"帶着感情","examples":[{"en":"She speaks slowly, carefully and with feeling.","zh":"她說話慢慢的、仔細的，並帶着感情。"},{"en":"With feeling means with real emotion, care, or sincerity.","zh":"with feeling 的意思是帶着真實情感、關心或誠意。"},{"en":"A singer can perform a simple line with feeling and make listeners quiet.","zh":"歌手可以帶着感情唱出一句簡單歌詞，令聽眾安靜下來。"},{"en":"Words spoken with feeling often matter more than words spoken loudly.","zh":"帶着感情說出的話，常比大聲說出的話更重要。"},{"en":"This phrase shows that emotion is present in the way something is said or sung.","zh":"這個短語表示情感存在於說話或歌唱方式之中。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"make herself out to be","meaning":"把自己說成……","examples":[{"en":"She does not make herself out to be a genius.","zh":"她沒有把自己說成天才。"},{"en":"To make herself out to be something means to present herself as that kind of person, especially in a way that may be exaggerated.","zh":"make herself out to be something 的意思是把自己呈現成某類人，尤其可能帶有誇張。"},{"en":"A student should not make herself out to be perfect when she also needs help.","zh":"學生在也需要幫助時，不應把自己說成完美。"},{"en":"People may dislike celebrities who make themselves out to be better than everyone else.","zh":"如果名人把自己說成比所有人優越，人們可能會反感。"},{"en":"This phrase often suggests that someone is shaping an image of themselves.","zh":"這個短語常暗示某人在塑造自己的形象。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"a genius discovered overnight","meaning":"一夜之間被發掘的天才","examples":[{"en":"She does not claim to be a genius discovered overnight.","zh":"她沒有聲稱自己是一夜之間被發掘的天才。"},{"en":"A genius discovered overnight is someone suddenly presented as naturally brilliant without showing the long effort behind it.","zh":"一夜之間被發掘的天才，是指突然被描述成天生極聰明，卻看不見背後長期努力的人。"},{"en":"The singer rejects the idea of being a genius discovered overnight because she practised for years.","zh":"這位歌手拒絕被視為一夜之間被發掘的天才，因為她練習了多年。"},{"en":"Calling someone a genius discovered overnight can hide their work, failures, and patience.","zh":"稱某人為一夜之間被發掘的天才，可能掩蓋其努力、失敗和耐性。"},{"en":"This phrase questions the myth of instant success.","zh":"這個短語質疑即時成功的神話。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"insist that","meaning":"堅持認為","examples":[{"en":"She insists that her music grew out of ordinary life.","zh":"她堅持認為她的音樂源自普通生活。"},{"en":"To insist that something is true means to say it strongly and repeatedly because you believe it.","zh":"insist that something is true 的意思是因相信某事而強烈並反覆地說出來。"},{"en":"A songwriter may insist that simple daily experiences can become meaningful songs.","zh":"創作人可能堅持認為簡單日常經歷可以變成有意義的歌曲。"},{"en":"People insist on a point when they want others to understand it clearly.","zh":"當人們想別人清楚明白某點時，就會堅持某個看法。"},{"en":"This phrase shows firm belief, not just casual opinion.","zh":"這個短語表示堅定信念，而不只是隨意意見。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"grow out of","meaning":"源自；由……而來","examples":[{"en":"Her music grew out of ordinary Hong Kong life.","zh":"她的音樂源自平凡的香港生活。"},{"en":"To grow out of something means to develop naturally from it.","zh":"grow out of something 的意思是自然地由某事物發展而來。"},{"en":"A poem may grow out of a student’s memory of walking home in the rain.","zh":"一首詩可能源自學生在雨中回家的記憶。"},{"en":"Songs that grow out of real life often feel more honest.","zh":"源自真實生活的歌曲，往往感覺更真誠。"},{"en":"This phrase shows the source or root of an idea.","zh":"這個短語展示一個想法的來源或根源。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"ordinary Hong Kong life","meaning":"平凡的香港生活","examples":[{"en":"Zoe’s songs often come from ordinary Hong Kong life.","zh":"Zoe 的歌曲常來自平凡的香港生活。"},{"en":"Ordinary Hong Kong life means everyday experiences such as school, transport, small shops, family meals, and crowded streets.","zh":"ordinary Hong Kong life 是指學校、交通、小店、家庭晚飯和擠迫街道等日常經歷。"},{"en":"A song about waiting for the last train can come from ordinary Hong Kong life.","zh":"一首關於等尾班車的歌，可以來自平凡的香港生活。"},{"en":"Ordinary Hong Kong life can feel meaningful when artists notice its small details.","zh":"當藝術家留意細小細節時，平凡的香港生活可以變得有意義。"},{"en":"This phrase shows that art can begin in familiar daily places.","zh":"這個短語展示藝術可以從熟悉的日常地方開始。"}],"source":"2020 Q7.pdf","sourcePage":5},{"front":"dramatic heartbreak","meaning":"戲劇性的心碎經歷","examples":[{"en":"People think songs come from dramatic heartbreak.","zh":"人們以為歌曲來自戲劇性的心碎經歷。"},{"en":"Dramatic heartbreak means intense emotional pain after love ends or goes wrong.","zh":"dramatic heartbreak 是指愛情結束或出問題後強烈的情感痛苦。"},{"en":"A film may show dramatic heartbreak through crying, arguments, and goodbye scenes.","zh":"電影可能透過哭泣、爭吵和告別場面展示戲劇性的心碎經歷。"},{"en":"Not every song needs dramatic heartbreak; some songs come from quiet daily sadness.","zh":"不是每首歌都需要戲劇性的心碎經歷；有些歌來自安靜的日常悲傷。"},{"en":"This phrase describes a strong and obvious kind of emotional suffering.","zh":"這個短語描述強烈而明顯的情感痛苦。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"bus rides","meaning":"巴士車程","examples":[{"en":"Her songs often come from bus rides.","zh":"她的歌曲常來自巴士車程。"},{"en":"Bus rides are journeys taken by bus, often full of small observations and quiet moments.","zh":"bus rides 是乘坐巴士的旅程，常充滿細小觀察和安靜時刻。"},{"en":"A songwriter may notice tired faces, rain on windows, or school uniforms during bus rides.","zh":"創作人可能在巴士車程中注意到疲累的臉、窗上的雨和校服。"},{"en":"Long bus rides can give people time to think about work, family, and dreams.","zh":"漫長巴士車程可以給人時間思考工作、家庭和夢想。"},{"en":"This phrase shows that ordinary travel can become creative material.","zh":"這個短語展示普通交通旅程也可以成為創作材料。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"family dinners","meaning":"家庭晚飯","examples":[{"en":"Her songs often come from family dinners.","zh":"她的歌曲常來自家庭晚飯。"},{"en":"Family dinners are meals shared by relatives, often involving conversation, care, and tension.","zh":"family dinners 是親人一起吃的飯，常包含對話、關心和張力。"},{"en":"A quiet argument at family dinner can become the beginning of a song.","zh":"家庭晚飯中的一場安靜爭吵，可以成為一首歌的開始。"},{"en":"Family dinners reveal relationships because people show love and frustration at the same table.","zh":"家庭晚飯揭示關係，因為人們在同一張桌上展示愛與沮喪。"},{"en":"This phrase suggests that home life can inspire art.","zh":"這個短語暗示家庭生活可以啟發藝術。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"too shy to say","meaning":"太害羞而說不出口","examples":[{"en":"Some songs came from things she was too shy to say.","zh":"有些歌曲來自她太害羞而說不出口的事情。"},{"en":"Too shy to say means feeling too embarrassed, nervous, or afraid to speak openly.","zh":"too shy to say 的意思是因尷尬、緊張或害怕而不敢坦白說出來。"},{"en":"A teenager may be too shy to say thank you to a parent but write it in a song.","zh":"青少年可能太害羞而說不出口感謝父母，但把感謝寫進歌裏。"},{"en":"Feelings that are too shy to say can still appear through music, writing, or art.","zh":"太害羞而說不出口的感受，仍可以透過音樂、寫作或藝術表達。"},{"en":"This phrase shows how silence can become creative expression.","zh":"這個短語展示沉默如何變成創作表達。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"take something for example","meaning":"以……為例","examples":[{"en":"Take Last Train Home, for example.","zh":"以《Last Train Home》為例。"},{"en":"Take something for example is used to introduce one specific case that supports a bigger point.","zh":"take something for example 用來介紹一個支持較大觀點的具體例子。"},{"en":"Take this school project for example: it shows how teamwork can change quiet students.","zh":"以這個學校項目為例：它展示團隊合作如何改變安靜學生。"},{"en":"Writers use this phrase when they want to make a general idea clearer.","zh":"作者想令一般想法更清楚時，會使用這個短語。"},{"en":"After this phrase, readers expect details about the example.","zh":"在這個短語之後，讀者會預期看到該例子的細節。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"be inspired by","meaning":"受……啟發","examples":[{"en":"The song was inspired by late-night journeys after tutorial classes.","zh":"這首歌受補習班後的深夜路程啟發。"},{"en":"To be inspired by something means to get an idea or feeling from it and create something new.","zh":"be inspired by something 的意思是從某事物得到想法或感受，並創作新東西。"},{"en":"A poem may be inspired by a grandmother’s old photograph.","zh":"一首詩可能受祖母的舊相片啟發。"},{"en":"Real experiences often inspire songs because they carry clear images and emotions.","zh":"真實經歷常啟發歌曲，因為它們帶有清晰畫面和情感。"},{"en":"This phrase explains where creative work begins.","zh":"這個短語解釋創作作品從哪裏開始。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"late-night journeys","meaning":"深夜路程","examples":[{"en":"The song was inspired by late-night journeys.","zh":"這首歌受深夜路程啟發。"},{"en":"Late-night journeys are trips taken late in the evening or at night, often when people are tired.","zh":"late-night journeys 是晚上較晚或夜間進行的路程，通常人們已經疲累。"},{"en":"Students may take late-night journeys home after tutorial classes.","zh":"學生可能在補習班後踏上深夜回家路程。"},{"en":"Late-night journeys can feel lonely because streets are quieter and everyone looks exhausted.","zh":"深夜路程可以感覺孤單，因為街道較安靜，每個人都看起來筋疲力盡。"},{"en":"This phrase creates a mood of tiredness, reflection, and city life.","zh":"這個短語營造疲累、反思和城市生活的氣氛。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"tutorial classes","meaning":"補習班；補習堂","examples":[{"en":"Zoe wrote about journeys after tutorial classes.","zh":"Zoe 寫下補習班後的路程。"},{"en":"Tutorial classes are extra lessons students attend outside regular school to improve their studies.","zh":"tutorial classes 是學生在正規學校以外參加的額外課堂，用來改善學業。"},{"en":"Many students go to tutorial classes before exams because they want more practice.","zh":"許多學生在考試前上補習班，因為他們想有更多練習。"},{"en":"Tutorial classes can help students, but they can also make their days longer and more tiring.","zh":"補習班可以幫助學生，但也可以令他們一天更長、更疲累。"},{"en":"This phrase connects the song to student pressure.","zh":"這個短語把歌曲與學生壓力連繫起來。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"notice students and workers","meaning":"留意到學生和工人","examples":[{"en":"Zoe noticed students and workers sharing the same silence.","zh":"Zoe 留意到學生和工人共享同一種沉默。"},{"en":"To notice students and workers means to pay attention to people from different daily lives around you.","zh":"notice students and workers 的意思是留意身邊來自不同日常生活的人。"},{"en":"A songwriter may notice students and workers waiting for the same late train.","zh":"創作人可能留意到學生和工人在等同一班夜車。"},{"en":"Noticing these people can reveal that different groups share similar tiredness.","zh":"留意這些人可以揭示不同群體都有相似疲累。"},{"en":"This phrase shows careful observation of ordinary city life.","zh":"這個短語展示對普通城市生活的細心觀察。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"sharing the same tired silence","meaning":"共享同一種疲憊的沉默","examples":[{"en":"The passengers were sharing the same tired silence.","zh":"乘客共享同一種疲憊的沉默。"},{"en":"Sharing the same tired silence means people are quiet together because they are all exhausted.","zh":"sharing the same tired silence 的意思是人們因同樣疲累而一起沉默。"},{"en":"After a long school day, students on the bus may share the same tired silence.","zh":"漫長上課日後，巴士上的學生可能共享同一種疲憊的沉默。"},{"en":"This silence can make strangers feel connected without speaking.","zh":"這種沉默可以令陌生人在不說話中感到連繫。"},{"en":"The phrase captures a mood that is lonely and communal at the same time.","zh":"這個短語捕捉一種既孤單又共同的氣氛。"}],"source":"2020 Q7.pdf","sourcePage":6},{"front":"look exhausted","meaning":"看起來筋疲力盡","examples":[{"en":"Everyone looked exhausted on the train.","zh":"火車上每個人都看起來筋疲力盡。"},{"en":"To look exhausted means to appear extremely tired.","zh":"look exhausted 的意思是看起來非常疲累。"},{"en":"Workers may look exhausted after standing all day in a shop.","zh":"店員站了一整天後，可能看起來筋疲力盡。"},{"en":"People who look exhausted may need rest even if they keep moving.","zh":"看起來筋疲力盡的人即使仍在活動，也可能需要休息。"},{"en":"This phrase describes visible tiredness on someone’s face or body.","zh":"這個短語描述臉上或身體上可見的疲累。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"still going somewhere","meaning":"仍然在前往某處","examples":[{"en":"Everyone was exhausted, but everyone was still going somewhere.","zh":"每個人都筋疲力盡，但每個人仍然在前往某處。"},{"en":"Still going somewhere means continuing toward a destination or goal despite tiredness.","zh":"still going somewhere 的意思是即使疲累，仍繼續前往某個目的地或目標。"},{"en":"A student may look sleepy but still be going somewhere for an evening class.","zh":"學生可能看起來很睏，但仍然在前往晚間課堂。"},{"en":"The phrase suggests effort because people keep moving even when they are worn out.","zh":"這個短語暗示努力，因為人們即使疲憊仍繼續前行。"},{"en":"It can describe both physical travel and the pursuit of a dream.","zh":"它可以描述實際路程，也可以描述追尋夢想。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"that observation became","meaning":"那個觀察變成了","examples":[{"en":"That observation became a tender ballad.","zh":"那個觀察變成了一首溫柔的抒情歌。"},{"en":"That observation became means something noticed in real life was transformed into another form.","zh":"that observation became 的意思是在現實中留意到的事，被轉化成另一種形式。"},{"en":"A teacher’s small kindness may become a story years later.","zh":"老師的一個小小善舉，多年後可能變成一個故事。"},{"en":"When an observation becomes a song, ordinary life gains emotional shape.","zh":"當一個觀察變成歌曲時，普通生活就有了情感形狀。"},{"en":"This phrase shows how art can grow from watching carefully.","zh":"這個短語展示藝術如何從細心觀看中成長。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"a tender ballad","meaning":"溫柔的抒情歌","examples":[{"en":"Last Train Home is a tender ballad about city life.","zh":"《Last Train Home》是一首關於城市生活的溫柔抒情歌。"},{"en":"A tender ballad is a gentle, emotional song, usually telling a personal or touching story.","zh":"a tender ballad 是溫柔而有情感的歌曲，通常講述個人或感人的故事。"},{"en":"A tender ballad may use a soft melody to describe loneliness after a long day.","zh":"溫柔的抒情歌可能用柔和旋律描述漫長一天後的孤獨。"},{"en":"Tender ballads often move listeners because they do not shout their feelings.","zh":"溫柔的抒情歌常打動聽眾，因為它們不大聲喊出感受。"},{"en":"This phrase describes both the style and emotional tone of a song.","zh":"這個短語同時描述歌曲風格和情感語氣。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"growing up in a city","meaning":"在城市中長大","examples":[{"en":"The song is about growing up in a city.","zh":"這首歌關於在城市中長大。"},{"en":"Growing up in a city means spending childhood and teenage years in an urban environment.","zh":"growing up in a city 的意思是在都市環境中度過童年和青少年時期。"},{"en":"A person growing up in a city may learn to live with crowds, noise, speed, and competition.","zh":"在城市中長大的人，可能學會與人群、噪音、速度和競爭共處。"},{"en":"City life can shape young people by giving them opportunities and pressure at the same time.","zh":"城市生活可以同時給予年輕人機會和壓力，從而塑造他們。"},{"en":"This phrase connects personal development with place.","zh":"這個短語把個人成長與地方連繫起來。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"come at the cost of","meaning":"以犧牲……為代價","examples":[{"en":"Ambition often comes at the cost of rest.","zh":"抱負往往以犧牲休息為代價。"},{"en":"To come at the cost of something means to gain one thing by losing or sacrificing another.","zh":"come at the cost of something 的意思是透過失去或犧牲另一事物來取得某事。"},{"en":"Good exam results may come at the cost of sleep if students study too late every night.","zh":"如果學生每晚溫習到太夜，好成績可能以犧牲睡眠為代價。"},{"en":"Success that comes at the cost of health may not feel worthwhile in the long run.","zh":"以犧牲健康為代價的成功，長遠來說可能不值得。"},{"en":"This phrase shows the hidden price behind achievement.","zh":"這個短語展示成就背後隱藏的代價。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"at the cost of rest","meaning":"以休息作代價","examples":[{"en":"In the song, ambition comes at the cost of rest.","zh":"在這首歌中，抱負以休息作代價。"},{"en":"At the cost of rest means by sacrificing sleep, free time, or recovery.","zh":"at the cost of rest 的意思是以犧牲睡眠、空閒時間或恢復為代價。"},{"en":"A student may improve quickly at the cost of rest if she studies until midnight every day.","zh":"如果學生每天溫習到午夜，她可能以休息作代價而快速進步。"},{"en":"Living at the cost of rest can lead to exhaustion and stress.","zh":"長期以休息作代價生活，可以導致疲憊和壓力。"},{"en":"This phrase warns that constant effort may have a personal price.","zh":"這個短語提醒人們，持續努力可能有個人代價。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"gentle yet haunting","meaning":"溫柔卻縈繞心頭","examples":[{"en":"The chorus is gentle yet haunting.","zh":"副歌溫柔卻縈繞心頭。"},{"en":"Gentle yet haunting means soft and calm, but still staying in the listener’s mind in an emotional way.","zh":"gentle yet haunting 的意思是柔和而平靜，但仍以情感方式停留在聽眾心中。"},{"en":"A lullaby can sound gentle yet haunting if it carries sadness beneath the melody.","zh":"如果搖籃曲在旋律下帶有悲傷，它可以溫柔卻縈繞心頭。"},{"en":"Music that is gentle yet haunting may affect people more deeply than loud music.","zh":"溫柔卻縈繞心頭的音樂，可能比大聲音樂更深刻地影響人。"},{"en":"This phrase describes beauty that quietly refuses to disappear.","zh":"這個短語描述一種安靜卻不肯消失的美。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"capture the loneliness of","meaning":"捕捉……的孤獨感","examples":[{"en":"The chorus captures the loneliness of crowded places.","zh":"副歌捕捉擠迫地方的孤獨感。"},{"en":"To capture the loneliness of something means to express that lonely feeling clearly through art or words.","zh":"capture the loneliness of something 的意思是透過藝術或文字清楚表達那種孤獨感。"},{"en":"A photo can capture the loneliness of a person eating alone in a busy restaurant.","zh":"一張相片可以捕捉一個人在繁忙餐廳獨自吃飯的孤獨感。"},{"en":"Songs capture loneliness well when listeners recognise their own quiet feelings in them.","zh":"當聽眾在歌曲中認出自己的安靜感受時，歌曲就能很好地捕捉孤獨。"},{"en":"This phrase shows that art can make an invisible emotion visible.","zh":"這個短語展示藝術可以令看不見的情感變得可見。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"crowded places","meaning":"擠迫的地方","examples":[{"en":"The song describes the loneliness of crowded places.","zh":"這首歌描述擠迫地方的孤獨感。"},{"en":"Crowded places are areas full of many people, such as trains, markets, stations, or shopping streets.","zh":"crowded places 是充滿許多人的地方，例如火車、街市、車站或購物街。"},{"en":"Crowded places can still feel lonely if nobody speaks to one another.","zh":"如果沒有人彼此說話，擠迫的地方仍可以感覺孤獨。"},{"en":"A person may feel small in crowded places because everyone seems busy with their own life.","zh":"在擠迫的地方，一個人可能感到渺小，因為每個人似乎都忙着自己的生活。"},{"en":"This phrase helps show the contrast between physical closeness and emotional distance.","zh":"這個短語幫助展示身體接近與情感距離之間的對比。"}],"source":"2020 Q7.pdf","sourcePage":7},{"front":"immediately recognised","meaning":"立即認出；馬上有共鳴","examples":[{"en":"Many young listeners immediately recognised that emotion.","zh":"許多年輕聽眾馬上對那種情緒有共鳴。"},{"en":"Immediately recognised means understood or identified something at once.","zh":"immediately recognised 的意思是立刻理解或認出某事物。"},{"en":"Students immediately recognised the pressure in the song because they had felt it themselves.","zh":"學生立即認出歌曲中的壓力，因為他們自己也感受過。"},{"en":"When listeners immediately recognise an emotion, the song feels close to their own lives.","zh":"當聽眾立即認出一種情緒時，歌曲會感覺貼近他們自己的生活。"},{"en":"This phrase shows a quick and strong connection.","zh":"這個短語展示快速而強烈的連繫。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"fan favourite","meaning":"歌迷喜愛的作品","examples":[{"en":"Plastic Roses became another fan favourite.","zh":"《Plastic Roses》成為另一首歌迷喜愛的作品。"},{"en":"A fan favourite is a song, character, or work that fans especially love.","zh":"fan favourite 是歌迷特別喜愛的歌曲、角色或作品。"},{"en":"A quiet album track may become a fan favourite because listeners connect with its honesty.","zh":"一首安靜的專輯歌曲可能因聽眾被其真誠打動而成為歌迷喜愛的作品。"},{"en":"Fan favourites are not always the most famous works, but they often feel personal to supporters.","zh":"歌迷喜愛的作品不一定是最有名的作品，但常令支持者感到個人化。"},{"en":"This phrase shows affection from the audience.","zh":"這個短語展示觀眾的喜愛。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"come from","meaning":"來自；源自","examples":[{"en":"Plastic Roses came from her mother’s flower shop.","zh":"《Plastic Roses》來自她媽媽的花店。"},{"en":"To come from something means to have that thing as the source or origin.","zh":"come from something 的意思是以某事物為來源或起點。"},{"en":"A poem may come from a childhood memory of waiting for rain to stop.","zh":"一首詩可能來自童年等待雨停的記憶。"},{"en":"Songs that come from real places often contain vivid details.","zh":"來自真實地方的歌曲，常包含生動細節。"},{"en":"This phrase explains where an idea, feeling, or object begins.","zh":"這個短語解釋一個想法、感受或物件從哪裏開始。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"artificial flowers","meaning":"人造花","examples":[{"en":"Customers often bought artificial flowers for hospital visits.","zh":"顧客常買人造花去探病。"},{"en":"Artificial flowers are flowers made from materials such as plastic or cloth instead of living plants.","zh":"artificial flowers 是用塑膠或布等材料製成的花，而不是有生命的植物。"},{"en":"Artificial flowers can be useful when fresh flowers are not allowed in a hospital room.","zh":"當病房不允許鮮花時，人造花可以很有用。"},{"en":"They last longer than real flowers, but they do not have natural life or smell.","zh":"人造花比真花維持得更久，但沒有自然生命或香氣。"},{"en":"This phrase can symbolise beauty that looks perfect but is not alive.","zh":"這個短語可以象徵看似完美但沒有生命的美。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"hospital visits","meaning":"探病","examples":[{"en":"People bought artificial flowers for hospital visits.","zh":"人們買人造花去探病。"},{"en":"Hospital visits are trips to see someone who is staying in hospital.","zh":"hospital visits 是到醫院探望住院的人。"},{"en":"During hospital visits, relatives may bring fruit, cards, or flowers to show care.","zh":"探病時，親人可能帶水果、心意卡或花來表示關心。"},{"en":"Hospital visits can be emotional because people want to comfort someone who is ill.","zh":"探病可能帶有情感，因為人們想安慰生病的人。"},{"en":"This phrase connects ordinary gifts with worry, love, and support.","zh":"這個短語把普通禮物與憂慮、愛和支持連繫起來。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"last longer","meaning":"維持得更久","examples":[{"en":"Artificial flowers lasted longer than fresh flowers.","zh":"人造花比鮮花維持得更久。"},{"en":"To last longer means to continue for more time before ending, breaking, or fading.","zh":"last longer 的意思是在結束、損壞或褪色前持續更長時間。"},{"en":"A metal water bottle may last longer than a plastic one.","zh":"金屬水樽可能比塑膠水樽維持得更久。"},{"en":"Things that last longer can be practical, but they are not always more meaningful.","zh":"維持得更久的東西可以很實用，但不一定更有意義。"},{"en":"This phrase often compares durability between two choices.","zh":"這個短語常比較兩個選擇之間的耐用程度。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, the idea seemed practical.","zh":"乍看之下，這個想法似乎很實用。"},{"en":"At first glance means when something is first seen or considered, before deeper thought.","zh":"at first glance 的意思是在初次看見或考慮某事時，還未深入思考。"},{"en":"At first glance, buying artificial flowers seems cheaper and easier.","zh":"乍看之下，買人造花似乎更便宜和方便。"},{"en":"A choice may look sensible at first glance but feel colder after careful thought.","zh":"一個選擇乍看之下可能合理，但仔細思考後可能感覺更冷淡。"},{"en":"This phrase prepares readers for a different view later.","zh":"這個短語為讀者準備之後不同的看法。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"on closer inspection","meaning":"仔細看來","examples":[{"en":"On closer inspection, the idea made her think more deeply.","zh":"仔細看來，這個想法令她思考得更深入。"},{"en":"On closer inspection means after looking at the details more carefully.","zh":"on closer inspection 的意思是在更仔細查看細節之後。"},{"en":"On closer inspection, the perfect plastic flower seemed a little sad.","zh":"仔細看來，那朵完美的塑膠花似乎有點悲傷。"},{"en":"This phrase is useful when a simple idea becomes more complicated after thought.","zh":"當一個簡單想法在思考後變得更複雜時，這個短語很有用。"},{"en":"It shows that first impressions do not always reveal the full meaning.","zh":"它顯示第一印象不一定揭示全部意義。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"choose what lasts over what lives","meaning":"選擇持久而非有生命的東西","examples":[{"en":"Zoe wondered whether people choose what lasts over what lives.","zh":"Zoe 想知道人們是否選擇持久而非有生命的東西。"},{"en":"To choose what lasts over what lives means to prefer something durable but lifeless instead of something alive but temporary.","zh":"choose what lasts over what lives 的意思是偏好耐用但無生命的東西，而不是有生命但短暫的東西。"},{"en":"A person may choose plastic flowers over fresh flowers because they last longer.","zh":"一個人可能選擇塑膠花而非鮮花，因為塑膠花維持更久。"},{"en":"This choice can feel practical, but it may lose warmth and natural beauty.","zh":"這個選擇可以很實用，但可能失去溫度和自然美。"},{"en":"The phrase raises a question about safety, emotion, and the fear of loss.","zh":"這個短語提出關於安全感、情感和害怕失去的問題。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"the result is","meaning":"結果是","examples":[{"en":"The result is a song about love without warmth.","zh":"結果是一首關於沒有溫度的愛的歌曲。"},{"en":"The result is introduces what something finally becomes after a process or choice.","zh":"the result is 用來介紹某事經過過程或選擇後最終變成甚麼。"},{"en":"A diary entry may begin as anger, but the result is a poem about forgiveness.","zh":"一篇日記起初可能是憤怒，但結果是一首關於原諒的詩。"},{"en":"This phrase helps connect the cause or inspiration to the final product.","zh":"這個短語幫助把原因或靈感與最終作品連繫起來。"},{"en":"It is useful when explaining how an idea turns into art.","zh":"當解釋想法如何變成藝術時，它很有用。"}],"source":"2020 Q7.pdf","sourcePage":8},{"front":"from the outside","meaning":"從外表看來","examples":[{"en":"The love looks perfect from the outside.","zh":"從外表看來，這份愛很完美。"},{"en":"From the outside means judging only by appearance, without knowing the inner truth.","zh":"from the outside 的意思是只按外表判斷，而不知道內在真相。"},{"en":"From the outside, the family looked happy, but they rarely talked honestly at home.","zh":"從外表看來，這個家庭很快樂，但他們在家很少坦誠交談。"},{"en":"Things that look perfect from the outside may still feel empty within.","zh":"從外表看來完美的東西，內裏仍可能感到空洞。"},{"en":"This phrase helps contrast public image with private reality.","zh":"這個短語幫助對比公眾形象與私人現實。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"lose its warmth within","meaning":"內裏失去溫度","examples":[{"en":"The relationship has lost its warmth within.","zh":"這段關係內裏失去溫度。"},{"en":"To lose its warmth within means to look fine outside but no longer feel loving, kind, or alive inside.","zh":"lose its warmth within 的意思是外表看來沒問題，但內裏不再有愛、善意或生命力。"},{"en":"A friendship may lose its warmth within if people only send polite messages and never really listen.","zh":"如果朋友只發禮貌訊息卻從不真正聆聽，友誼可能內裏失去溫度。"},{"en":"Relationships lose warmth when care becomes habit without feeling.","zh":"當關心變成沒有感受的習慣，關係就會失去溫度。"},{"en":"This phrase describes emotional emptiness hidden beneath a good appearance.","zh":"這個短語描述隱藏在美好外表下的情感空洞。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"not so much...as...","meaning":"與其說是……不如說是……","examples":[{"en":"It is not so much a sad song as a careful one.","zh":"與其說它是一首悲傷的歌，不如說它是一首細膩謹慎的歌。"},{"en":"Not so much A as B means B is a better description than A.","zh":"not so much A as B 的意思是 B 比 A 更能準確描述某事。"},{"en":"The film is not so much frightening as thoughtful.","zh":"與其說這部電影可怕，不如說它發人深省。"},{"en":"This structure helps correct a simple label and replace it with a more accurate one.","zh":"這個結構幫助修正簡單標籤，並換成更準確的描述。"},{"en":"It is useful when something looks like one thing but should be understood as another.","zh":"當某事看似一樣東西，但應被理解為另一樣東西時，這個結構很有用。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"a careful song","meaning":"細膩謹慎的歌曲","examples":[{"en":"Zoe describes Plastic Roses as a careful song.","zh":"Zoe 形容《Plastic Roses》是一首細膩謹慎的歌曲。"},{"en":"A careful song is a song that handles its feelings gently and thoughtfully.","zh":"a careful song 是溫柔而深思熟慮地處理情感的歌曲。"},{"en":"A careful song may ask difficult questions without giving easy answers.","zh":"細膩謹慎的歌曲可能提出困難問題，而不給予簡單答案。"},{"en":"Careful songs often use small details instead of loud emotion.","zh":"細膩謹慎的歌曲常使用小細節，而不是強烈外露的情緒。"},{"en":"This phrase suggests emotional control and quiet depth.","zh":"這個短語暗示情感控制和安靜深度。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"beauty still matters","meaning":"美是否仍然重要","examples":[{"en":"She asks whether beauty still matters if it cannot breathe.","zh":"她問，如果美不能呼吸，美是否仍然重要。"},{"en":"Beauty still matters means beauty remains important even when its value is being questioned.","zh":"beauty still matters 的意思是即使美的價值受到質疑，美仍然重要。"},{"en":"A plastic flower may look beautiful, but people may ask whether that beauty still matters without life.","zh":"塑膠花可能看起來美麗，但人們可能會問，沒有生命的美是否仍然重要。"},{"en":"This question becomes deeper when beauty is separated from warmth, change, or feeling.","zh":"當美與溫度、變化或感受分開時，這個問題會變得更深。"},{"en":"The phrase invites listeners to think about what makes beauty meaningful.","zh":"這個短語邀請聽眾思考甚麼令美有意義。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"reveal a more personal side","meaning":"展現更個人的一面","examples":[{"en":"Borrowed Light reveals a more personal side of Zoe.","zh":"《Borrowed Light》展現 Zoe 更個人的一面。"},{"en":"To reveal a more personal side means to show private feelings, fears, or experiences more openly.","zh":"reveal a more personal side 的意思是更公開地展示私人感受、恐懼或經歷。"},{"en":"A singer may reveal a more personal side in a song about anxiety after fame.","zh":"歌手可能在一首關於成名後焦慮的歌曲中，展現更個人的一面。"},{"en":"Revealing a personal side can help listeners feel closer to the artist.","zh":"展現個人的一面可以幫助聽眾感覺更接近藝人。"},{"en":"This phrase suggests emotional honesty beyond public image.","zh":"這個短語暗示超越公眾形象的情感誠實。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"newest single","meaning":"最新單曲","examples":[{"en":"Borrowed Light is Zoe’s newest single.","zh":"《Borrowed Light》是 Zoe 的最新單曲。"},{"en":"A newest single is the most recently released song by an artist.","zh":"newest single 是藝人最近推出的一首歌曲。"},{"en":"Fans often listen to a singer’s newest single to understand her current style.","zh":"歌迷常聽歌手的最新單曲，以了解她目前的風格。"},{"en":"A newest single can introduce a new album, image, or emotional direction.","zh":"最新單曲可以介紹新專輯、新形象或新的情感方向。"},{"en":"This phrase is common in music news and reviews.","zh":"這個短語常見於音樂新聞和評論。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"during a period when","meaning":"在……的一段時期","examples":[{"en":"She wrote the song during a period when she felt overwhelmed.","zh":"她在感到被壓得喘不過氣的一段時期寫下這首歌。"},{"en":"During a period when means in a particular time in someone’s life when something was happening.","zh":"during a period when 的意思是在某人生活中某件事正在發生的一段特定時期。"},{"en":"A student may write a diary during a period when exams feel impossible.","zh":"學生可能在考試感覺難以應付的一段時期寫日記。"},{"en":"This phrase helps connect a piece of work to the life situation behind it.","zh":"這個短語幫助把作品與背後的生活處境連繫起來。"},{"en":"It is useful when explaining the timing and emotional background of an event.","zh":"當解釋事件的時間和情感背景時，它很有用。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"feel overwhelmed by","meaning":"被……壓得喘不過氣","examples":[{"en":"Zoe felt overwhelmed by sudden attention.","zh":"Zoe 被突如其來的關注壓得喘不過氣。"},{"en":"To feel overwhelmed by something means to feel unable to handle it because it is too much.","zh":"feel overwhelmed by something 的意思是因某事太多或太強而感到無法應付。"},{"en":"A student may feel overwhelmed by homework, exams, and family expectations.","zh":"學生可能被功課、考試和家庭期望壓得喘不過氣。"},{"en":"Sudden success can overwhelm a young artist if too many demands arrive at once.","zh":"如果太多要求同時出現，突然成功可以令年輕藝人不知所措。"},{"en":"This phrase describes pressure that feels bigger than one’s ability to cope.","zh":"這個短語描述一種比自己應付能力更大的壓力。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"sudden attention","meaning":"突如其來的關注","examples":[{"en":"Sudden attention made Zoe feel overwhelmed.","zh":"突如其來的關注令 Zoe 感到被壓得喘不過氣。"},{"en":"Sudden attention is unexpected public interest that arrives quickly.","zh":"sudden attention 是迅速出現的意外公眾興趣。"},{"en":"A quiet student may find sudden attention uncomfortable after winning a competition.","zh":"安靜學生贏得比賽後，可能覺得突如其來的關注令人不自在。"},{"en":"Sudden attention can be exciting, but it can also make ordinary actions feel watched.","zh":"突如其來的關注可以令人興奮，但也可以令普通行動感覺被注視。"},{"en":"This phrase shows how fame can arrive before a person feels ready.","zh":"這個短語展示名氣可能在一個人準備好之前就到來。"}],"source":"2020 Q7.pdf","sourcePage":9},{"front":"learn to stand under a spotlight","meaning":"學習站在聚光燈下","examples":[{"en":"The song describes an artist learning to stand under a spotlight.","zh":"這首歌描述一位藝人學習站在聚光燈下。"},{"en":"To learn to stand under a spotlight means to gradually become able to handle public attention.","zh":"learn to stand under a spotlight 的意思是逐漸學會應付公眾關注。"},{"en":"A young singer learns to stand under a spotlight by facing interviews, cameras, and criticism.","zh":"年輕歌手透過面對訪問、鏡頭和批評，學習站在聚光燈下。"},{"en":"This process takes time because being seen by many people can feel frightening.","zh":"這個過程需要時間，因為被許多人看見可能令人害怕。"},{"en":"The phrase describes emotional training for fame.","zh":"這個短語描述為名氣而進行的情感訓練。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"without being blinded by it","meaning":"而不被它蒙蔽","examples":[{"en":"She is learning to stand under a spotlight without being blinded by it.","zh":"她正在學習站在聚光燈下，而不被它蒙蔽。"},{"en":"Without being blinded by it means not letting fame, attention, or success stop you from seeing clearly.","zh":"without being blinded by it 的意思是不讓名氣、關注或成功阻止自己清楚看事物。"},{"en":"A popular student can enjoy praise without being blinded by it if she still accepts advice.","zh":"受歡迎的學生如果仍接受建議，就可以享受讚美而不被它蒙蔽。"},{"en":"Fame can blind people when they begin to believe every compliment too easily.","zh":"當人們太容易相信每一句讚美時，名氣就可能蒙蔽他們。"},{"en":"This phrase warns that attention is powerful but can be dangerous.","zh":"這個短語提醒人們，關注很有力量，但也可能危險。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"with success comes pressure","meaning":"成功伴隨壓力","examples":[{"en":"With success comes pressure.","zh":"成功伴隨壓力。"},{"en":"With success comes pressure means success often brings new expectations, duties, and stress.","zh":"with success comes pressure 的意思是成功常帶來新期望、責任和壓力。"},{"en":"After winning a prize, a student may feel that with success comes pressure to win again.","zh":"得獎後，學生可能感到成功伴隨再次勝出的壓力。"},{"en":"Public success can make people expect every future work to be better.","zh":"公開成功會令人期待未來每一件作品都更好。"},{"en":"This phrase balances the joy of achievement with its burden.","zh":"這個短語平衡成就的喜悅與其負擔。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"not entirely easy to handle","meaning":"並非完全容易應付","examples":[{"en":"Fame has not been entirely easy to handle.","zh":"名氣並非完全容易應付。"},{"en":"Not entirely easy to handle means something has some difficulties even if it may look positive.","zh":"not entirely easy to handle 的意思是某事即使看似正面，也有一些困難。"},{"en":"A new job may not be entirely easy to handle because the hours are long.","zh":"新工作可能並非完全容易應付，因為工時很長。"},{"en":"Fame is not entirely easy to handle when strangers comment on your private life.","zh":"當陌生人評論你的私人生活時，名氣並非完全容易應付。"},{"en":"This phrase gives a careful and balanced view of a challenge.","zh":"這個短語對挑戰作出謹慎而平衡的看法。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"get used to","meaning":"習慣於","examples":[{"en":"She has had to get used to interviews and rehearsals.","zh":"她不得不習慣訪問和綵排。"},{"en":"To get used to something means to become more comfortable with it after time and practice.","zh":"get used to something 的意思是經過時間和練習後，變得較能適應某事。"},{"en":"A new student needs time to get used to a different school routine.","zh":"新學生需要時間習慣不同的學校日程。"},{"en":"Artists get used to interviews by answering questions again and again.","zh":"藝人透過一次又一次回答問題來習慣訪問。"},{"en":"This phrase shows adjustment rather than instant comfort.","zh":"這個短語展示適應，而不是立即感到自在。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"interviews and rehearsals","meaning":"訪問和綵排","examples":[{"en":"Zoe has had to get used to interviews and rehearsals.","zh":"Zoe 不得不習慣訪問和綵排。"},{"en":"Interviews and rehearsals are media conversations and practice sessions before performances.","zh":"interviews and rehearsals 是媒體談話和演出前的練習。"},{"en":"A new singer may spend her afternoon doing interviews and rehearsals before a show.","zh":"新歌手可能在演出前整個下午都在做訪問和綵排。"},{"en":"Interviews and rehearsals can be tiring because they require both careful speech and repeated practice.","zh":"訪問和綵排可能令人疲累，因為它們需要謹慎說話和反覆練習。"},{"en":"This phrase shows the professional work behind public performance.","zh":"這個短語展示公開表演背後的專業工作。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"public comments","meaning":"公眾評論","examples":[{"en":"She has had to get used to public comments.","zh":"她不得不習慣公眾評論。"},{"en":"Public comments are opinions or reactions expressed openly by people, often online.","zh":"public comments 是人們公開表達的意見或反應，常見於網上。"},{"en":"A singer may receive public comments about her voice, clothes, and personality.","zh":"歌手可能收到關於聲線、衣着和性格的公眾評論。"},{"en":"Public comments can encourage artists, but cruel comments can hurt them deeply.","zh":"公眾評論可以鼓勵藝人，但殘酷評論也可以深深傷害他們。"},{"en":"This phrase shows the exposed side of fame.","zh":"這個短語展示名氣中暴露於人前的一面。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"the strange feeling of being recognised","meaning":"被人認出的奇怪感覺","examples":[{"en":"She experienced the strange feeling of being recognised in public.","zh":"她經歷了在公眾地方被人認出的奇怪感覺。"},{"en":"The strange feeling of being recognised means the unusual experience of strangers knowing who you are.","zh":"the strange feeling of being recognised 的意思是陌生人知道你是誰的異常經驗。"},{"en":"A young singer may feel the strange feeling of being recognised when someone asks for a photo on the street.","zh":"年輕歌手在街上被人要求合照時，可能感到被人認出的奇怪感覺。"},{"en":"Being recognised can feel exciting and uncomfortable at the same time.","zh":"被人認出可以同時令人興奮和不自在。"},{"en":"This phrase shows how fame changes ordinary public moments.","zh":"這個短語展示名氣如何改變普通公共時刻。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"buying egg waffles","meaning":"買雞蛋仔","examples":[{"en":"She was recognised while buying egg waffles.","zh":"她買雞蛋仔時被人認出。"},{"en":"Buying egg waffles means purchasing a popular Hong Kong street snack made in a bubble-like shape.","zh":"buying egg waffles 的意思是購買一種有泡泡形狀的香港街頭小食。"},{"en":"A singer buying egg waffles may simply want a normal snack after school.","zh":"歌手買雞蛋仔，可能只是想放學後吃一份普通小食。"},{"en":"Being recognised while buying egg waffles shows how fame enters daily life.","zh":"買雞蛋仔時被人認出，展示名氣如何進入日常生活。"},{"en":"This phrase makes the scene feel local, ordinary, and slightly funny.","zh":"這個短語令場景感覺本地、普通又有點有趣。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"miss being invisible","meaning":"懷念不被注意的感覺","examples":[{"en":"Sometimes Zoe misses being invisible.","zh":"有時 Zoe 懷念不被注意的感覺。"},{"en":"To miss being invisible means to wish people would stop noticing you so much.","zh":"miss being invisible 的意思是希望別人不要那麼注意自己。"},{"en":"A famous student may miss being invisible when classmates stare at her in the corridor.","zh":"成名學生在走廊被同學盯着看時，可能懷念不被注意的感覺。"},{"en":"People may miss being invisible because privacy allows them to relax.","zh":"人們可能懷念不被注意，因為私隱讓人放鬆。"},{"en":"This phrase shows that attention can feel like a loss as well as a gift.","zh":"這個短語展示關注既可以是禮物，也可以像一種失去。"}],"source":"2020 Q7.pdf","sourcePage":10},{"front":"feel less alone","meaning":"感到不那麼孤單","examples":[{"en":"A fan told Zoe that her song helped them feel less alone.","zh":"一位歌迷告訴 Zoe，她的歌幫助他感到不那麼孤單。"},{"en":"To feel less alone means to feel more understood or connected to others.","zh":"feel less alone 的意思是感到更被理解，或與別人更有連繫。"},{"en":"A song about exam stress may help students feel less alone.","zh":"一首關於考試壓力的歌，可能幫助學生感到不那麼孤單。"},{"en":"People feel less alone when they realise someone else has felt the same pain.","zh":"當人們意識到別人也感受過同樣痛苦時，就會感到不那麼孤單。"},{"en":"This phrase shows the comforting power of art.","zh":"這個短語展示藝術的安慰力量。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"make everything worth it","meaning":"令一切都值得","examples":[{"en":"Messages from listeners make everything worth it.","zh":"聽眾的訊息令一切都值得。"},{"en":"To make everything worth it means to make all the effort, stress, or sacrifice feel meaningful.","zh":"make everything worth it 的意思是令所有努力、壓力或犧牲都感覺有意義。"},{"en":"One thank-you note from a student can make months of teaching work worth it.","zh":"學生的一封感謝信，可以令數月的教學工作都值得。"},{"en":"For an artist, knowing a song helped someone can make criticism easier to bear.","zh":"對藝人來說，知道一首歌幫助了某人，可以令批評較容易承受。"},{"en":"This phrase explains why a difficult journey still feels valuable.","zh":"這個短語解釋為何困難旅程仍然有價值。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"someone’s appeal lies in","meaning":"某人的吸引力在於","examples":[{"en":"Zoe’s appeal lies in her balance between innocence and emotional intelligence.","zh":"Zoe 的吸引力在於她天真與情緒智慧之間的平衡。"},{"en":"Someone’s appeal lies in something means that quality is the main reason people like them.","zh":"someone’s appeal lies in something 的意思是某種特質是人們喜歡某人的主要原因。"},{"en":"A teacher’s appeal lies in her ability to make difficult ideas feel simple.","zh":"一位老師的吸引力在於她能令困難概念變得簡單。"},{"en":"An artist’s appeal may lie in honesty rather than glamour.","zh":"藝人的吸引力可能在於真誠，而不是華麗。"},{"en":"This phrase is useful when explaining the source of someone’s charm or popularity.","zh":"當解釋某人魅力或人氣來源時，這個短語很有用。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"balance between innocence and emotional intelligence","meaning":"天真與情緒智慧之間的平衡","examples":[{"en":"Her appeal lies in the balance between innocence and emotional intelligence.","zh":"她的吸引力在於天真與情緒智慧之間的平衡。"},{"en":"A balance between innocence and emotional intelligence means someone feels fresh and sincere while also understanding feelings deeply.","zh":"balance between innocence and emotional intelligence 的意思是某人感覺清新真誠，同時又深刻理解情感。"},{"en":"A young singer can show this balance by asking simple questions about complicated emotions.","zh":"年輕歌手可以透過提出關於複雜情感的簡單問題，展現這種平衡。"},{"en":"Too much innocence may seem naive, while emotional intelligence gives depth.","zh":"太多天真可能顯得幼稚，而情緒智慧則帶來深度。"},{"en":"This phrase explains why Zoe can sound young but not shallow.","zh":"這個短語解釋為何 Zoe 聽起來年輕但不膚淺。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"emotional intelligence","meaning":"情緒智慧","examples":[{"en":"Zoe shows emotional intelligence in her songwriting.","zh":"Zoe 在創作歌曲中展現情緒智慧。"},{"en":"Emotional intelligence is the ability to understand feelings, both your own and other people’s.","zh":"情緒智慧是理解自己和別人感受的能力。"},{"en":"A person with emotional intelligence can notice when a friend is hurt but pretending to be fine.","zh":"有情緒智慧的人，可以察覺朋友受了傷卻假裝沒事。"},{"en":"Emotional intelligence helps artists write songs that feel honest and sensitive.","zh":"情緒智慧幫助藝術家寫出真誠而細膩的歌曲。"},{"en":"This phrase is about understanding emotions, not simply being emotional.","zh":"這個短語關於理解情緒，而不只是情緒化。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"write about small things","meaning":"書寫小事情","examples":[{"en":"She writes about small things.","zh":"她書寫小事情。"},{"en":"To write about small things means to focus on ordinary details rather than dramatic events.","zh":"write about small things 的意思是聚焦普通細節，而不是戲劇性事件。"},{"en":"A songwriter may write about a bus seat, a lunch box, or a shop sign.","zh":"創作人可能書寫巴士座位、飯盒或店舖招牌。"},{"en":"Small things become meaningful when they reveal hidden feelings.","zh":"當小事情揭示隱藏感受時，它們就變得有意義。"},{"en":"This phrase shows attention to everyday life.","zh":"這個短語展示對日常生活的關注。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"make them feel large","meaning":"令它們顯得重大","examples":[{"en":"She writes about small things and makes them feel large.","zh":"她書寫小事情，並令它們顯得重大。"},{"en":"To make them feel large means to make small details seem emotionally important.","zh":"make them feel large 的意思是令細小細節感覺在情感上重要。"},{"en":"A song can make a simple train ride feel large by connecting it to loneliness and ambition.","zh":"一首歌可以把簡單火車旅程與孤獨和抱負連繫起來，令它顯得重大。"},{"en":"Artists make small things feel large when they show what those details mean to people.","zh":"當藝術家展示這些細節對人有何意義時，就能令小事情顯得重大。"},{"en":"This phrase describes the power of turning the ordinary into something meaningful.","zh":"這個短語描述把普通事物變成有意義事物的力量。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"her words linger","meaning":"她的文字令人回味","examples":[{"en":"She sings softly, yet her words linger.","zh":"她輕聲歌唱，但她的文字令人回味。"},{"en":"Her words linger means her lyrics remain in people’s minds after the song ends.","zh":"her words linger 的意思是歌曲結束後，她的歌詞仍留在人們心中。"},{"en":"A simple line may linger if it expresses a feeling listeners could not explain themselves.","zh":"如果一句簡單歌詞表達了聽眾自己無法解釋的感受，它可能令人回味。"},{"en":"Words linger when they are honest, memorable, and emotionally clear.","zh":"當文字真誠、難忘且情感清晰時，就會令人回味。"},{"en":"This phrase suggests quiet but lasting impact.","zh":"這個短語暗示安靜但持久的影響。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"entertain her audience","meaning":"娛樂觀眾","examples":[{"en":"She does not just entertain her audience.","zh":"她不只是娛樂觀眾。"},{"en":"To entertain her audience means to give listeners enjoyment, interest, or pleasure.","zh":"entertain her audience 的意思是給聽眾享受、興趣或樂趣。"},{"en":"A singer entertains her audience with melody, stage presence, and emotion.","zh":"歌手透過旋律、舞台魅力和情感娛樂觀眾。"},{"en":"Some artists entertain their audience but also make them think about their own lives.","zh":"有些藝人娛樂觀眾，同時也令他們思考自己的生活。"},{"en":"This phrase focuses on the relationship between performer and listeners.","zh":"這個短語着重表演者與聽眾之間的關係。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"give someone room to","meaning":"給某人空間去……","examples":[{"en":"She gives listeners room to understand themselves.","zh":"她給聽眾空間去理解自己。"},{"en":"To give someone room to do something means to allow them space, time, or freedom to do it.","zh":"give someone room to do something 的意思是給某人空間、時間或自由去做某事。"},{"en":"A teacher gives students room to think when she does not answer every question immediately.","zh":"老師不立刻回答每個問題時，就是給學生空間去思考。"},{"en":"Songs give listeners room to feel when the lyrics are open and gentle.","zh":"當歌詞開放而溫柔時，歌曲可以給聽眾空間去感受。"},{"en":"This phrase suggests support without pressure.","zh":"這個短語暗示沒有壓力的支持。"}],"source":"2020 Q7.pdf","sourcePage":11},{"front":"understand themselves","meaning":"理解自己","examples":[{"en":"Her songs give listeners room to understand themselves.","zh":"她的歌曲給聽眾空間去理解自己。"},{"en":"To understand themselves means to recognise their own feelings, thoughts, needs, or fears.","zh":"understand themselves 的意思是認出自己的感受、想法、需要或恐懼。"},{"en":"A teenager may understand herself better after hearing a song about loneliness.","zh":"青少年聽到一首關於孤獨的歌後，可能更理解自己。"},{"en":"People understand themselves through art when it gives words to feelings they already had.","zh":"當藝術為人們本已有的感受找到文字時，人們就能透過藝術理解自己。"},{"en":"This phrase shows personal reflection and emotional growth.","zh":"這個短語展示個人反思和情感成長。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"perhaps that is why","meaning":"也許這就是為何","examples":[{"en":"Perhaps that is why her rise does not feel accidental.","zh":"也許這就是為何她的冒起感覺不像偶然。"},{"en":"Perhaps that is why means this may be the reason for something.","zh":"perhaps that is why 的意思是這可能就是某事發生的原因。"},{"en":"She writes honestly; perhaps that is why listeners trust her.","zh":"她寫得真誠；也許這就是為何聽眾信任她。"},{"en":"This phrase is useful when giving a thoughtful but not absolute explanation.","zh":"當提出深思熟慮但不絕對的解釋時，這個短語很有用。"},{"en":"It helps connect an observation to a possible conclusion.","zh":"它幫助把觀察與可能結論連繫起來。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"feel accidental","meaning":"感覺像偶然","examples":[{"en":"Her rise does not feel accidental.","zh":"她的冒起感覺不像偶然。"},{"en":"To feel accidental means to seem like something happened by chance rather than for a clear reason.","zh":"feel accidental 的意思是看似偶然發生，而不是有清楚原因。"},{"en":"A student’s success does not feel accidental when we see her years of practice.","zh":"當我們看見學生多年的練習，她的成功就感覺不像偶然。"},{"en":"Fame may look accidental online, but there is often effort behind it.","zh":"名氣在網上可能看似偶然，但背後常有努力。"},{"en":"This phrase helps separate luck from earned growth.","zh":"這個短語幫助區分運氣與應得的成長。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"Great oaks grow from little acorns","meaning":"偉大成就始於微小起點","examples":[{"en":"Great oaks grow from little acorns, and Zoe’s first award may be only the beginning.","zh":"偉大成就始於微小起點，而 Zoe 的第一個獎可能只是開始。"},{"en":"Great oaks grow from little acorns means big achievements can begin from small starts.","zh":"Great oaks grow from little acorns 的意思是偉大成就可以始於細小起點。"},{"en":"A famous singer may begin with one small performance after school.","zh":"著名歌手可能由一次放學後的小表演開始。"},{"en":"This proverb reminds people not to dismiss early efforts just because they look small.","zh":"這句諺語提醒人們不要因早期努力看似微小而輕視它。"},{"en":"It is useful when describing future potential from humble beginnings.","zh":"當描述由謙卑起點而來的未來潛力時，它很有用。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"first visible branch","meaning":"第一根看得見的枝椏；初步成果","examples":[{"en":"Her first award may be the first visible branch of something deeper.","zh":"她的第一個獎可能是某種更深層東西的第一根看得見的枝椏。"},{"en":"First visible branch means the first clear sign of growth that others can see.","zh":"first visible branch 的意思是別人能看見的第一個清楚成長跡象。"},{"en":"A prize may be the first visible branch of years of private practice.","zh":"一個獎項可能是多年私下練習的初步成果。"},{"en":"People often notice the visible branch but not the roots beneath it.","zh":"人們常注意看得見的枝椏，卻看不到底下的根。"},{"en":"This phrase suggests that public success grows from hidden effort.","zh":"這個短語暗示公開成功源自隱藏努力。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"something much deeper","meaning":"更深層的東西","examples":[{"en":"The award may point to something much deeper.","zh":"這個獎項可能指向更深層的東西。"},{"en":"Something much deeper means a more meaningful reason, ability, or truth beneath the surface.","zh":"something much deeper 的意思是表面之下更有意義的原因、能力或真相。"},{"en":"A singer’s popularity may point to something much deeper than a catchy chorus.","zh":"歌手的人氣可能指向比易記副歌更深層的東西。"},{"en":"When listeners stay with an artist, something much deeper is usually at work.","zh":"當聽眾長久支持一位藝人時，通常有更深層的東西在發揮作用。"},{"en":"This phrase encourages readers to look beyond the obvious success.","zh":"這個短語鼓勵讀者看見明顯成功之外的東西。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"as our interview ended","meaning":"當訪問結束時","examples":[{"en":"As our interview ended, Zoe held her trophy carefully.","zh":"當訪問結束時，Zoe 小心地拿着獎座。"},{"en":"As our interview ended means at the moment when the conversation with the reporter was finishing.","zh":"as our interview ended 的意思是在與記者的對話即將結束時。"},{"en":"As our interview ended, the singer thanked the staff before leaving the studio.","zh":"當訪問結束時，那位歌手在離開錄音室前感謝工作人員。"},{"en":"This phrase is often used to close an article with one final image.","zh":"這個短語常用來以最後一個畫面結束文章。"},{"en":"It helps readers feel that they are watching the scene end.","zh":"它幫助讀者感覺自己正在看着場景結束。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"belong to someone else","meaning":"屬於別人","examples":[{"en":"She held her trophy as if it still belonged to someone else.","zh":"她拿着獎座，彷彿它仍然屬於別人。"},{"en":"To belong to someone else means to be owned by another person, not by you.","zh":"belong to someone else 的意思是屬於另一個人，而不是屬於你。"},{"en":"A shy winner may look at her medal as if it belonged to someone else.","zh":"害羞的勝出者可能看着自己的獎牌，彷彿它屬於別人。"},{"en":"This feeling can happen when success arrives faster than a person can accept it.","zh":"當成功來得比一個人能接受的速度更快時，可能會出現這種感覺。"},{"en":"The phrase shows disbelief, humility, and emotional distance from the achievement.","zh":"這個短語展示難以置信、謙遜，以及與成就之間的情感距離。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"surrounded by applause","meaning":"被掌聲包圍","examples":[{"en":"Zoe is a new artist surrounded by applause.","zh":"Zoe 是一位被掌聲包圍的新藝人。"},{"en":"Surrounded by applause means receiving praise, cheers, and approval from many people.","zh":"surrounded by applause 的意思是得到許多人的讚賞、歡呼和認同。"},{"en":"A performer surrounded by applause may still feel nervous inside.","zh":"被掌聲包圍的表演者，內心仍可能感到緊張。"},{"en":"Applause can encourage someone, but it can also make expectations feel heavier.","zh":"掌聲可以鼓勵一個人，但也可能令期望變得更沉重。"},{"en":"This phrase creates an image of public praise around a person.","zh":"這個短語塑造一個人被公眾讚賞包圍的畫面。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"sound famous","meaning":"聽起來有名氣","examples":[{"en":"Zoe does not want her next songs to sound famous.","zh":"Zoe 不希望她下一批歌曲聽起來有名氣。"},{"en":"To sound famous means to seem designed mainly to impress people or fit a celebrity image.","zh":"sound famous 的意思是聽起來主要為了令人印象深刻或配合名人形象而設計。"},{"en":"A song may sound famous if it is polished but lacks honest feeling.","zh":"如果一首歌很精緻但缺乏真實感受，它可能聽起來有名氣。"},{"en":"Some artists avoid sounding famous because they do not want to lose their original voice.","zh":"有些藝人避免聽起來有名氣，因為他們不想失去原本的聲音。"},{"en":"This phrase suggests that fame can change the tone of art.","zh":"這個短語暗示名氣可以改變藝術的語氣。"}],"source":"2020 Q7.pdf","sourcePage":12},{"front":"sound honest","meaning":"聽起來真誠","examples":[{"en":"She wants her next songs to sound honest.","zh":"她希望她下一批歌曲聽起來真誠。"},{"en":"To sound honest means to feel sincere, real, and not fake.","zh":"sound honest 的意思是感覺真摯、真實而不虛假。"},{"en":"A song can sound honest when the singer uses simple words that match true feelings.","zh":"當歌手使用符合真實感受的簡單文字時，歌曲可以聽起來真誠。"},{"en":"Honest songs often connect with listeners because they do not try too hard to impress.","zh":"真誠的歌曲常與聽眾產生連繫，因為它們沒有過分努力令人印象深刻。"},{"en":"This phrase shows Zoe’s wish to protect her sincerity.","zh":"這個短語展示 Zoe 想保護自己真誠的一面。"}],"source":"2020 Q7.pdf","sourcePage":13},{"front":"the most promising note of all","meaning":"最令人期待的一點","examples":[{"en":"Her wish to stay honest may be the most promising note of all.","zh":"她想保持真誠的願望，可能是最令人期待的一點。"},{"en":"The most promising note of all means the sign that gives the greatest hope for the future.","zh":"the most promising note of all 的意思是最能令人對未來抱有希望的跡象。"},{"en":"A young artist’s humility may be the most promising note of all after her first success.","zh":"年輕藝人在第一次成功後仍保持謙遜，可能是最令人期待的一點。"},{"en":"Talent matters, but a desire to stay honest can suggest long-term growth.","zh":"才華很重要，但想保持真誠的願望可以暗示長遠成長。"},{"en":"This phrase ends an evaluation with hope and confidence.","zh":"這個短語以希望和信心結束評價。"}],"source":"2020 Q7.pdf","sourcePage":13}],"dse/writing/part-b/2020/Q8":[{"front":"white noise","meaning":"白噪音","examples":[{"en":"The first chapter is called White Noise.","zh":"第一章叫做《白噪音》。"},{"en":"White noise is a steady background sound that can cover other noises.","zh":"白噪音是一種持續的背景聲音，可以蓋過其他聲音。"},{"en":"Some students play white noise while studying so sudden traffic sounds do not disturb them.","zh":"有些學生溫習時會播放白噪音，令突然的交通聲不會打擾他們。"},{"en":"In the Arctic story, white noise suggests both sound and silence, making the place feel strange.","zh":"在北極故事中，白噪音暗示聲音和寂靜，令這個地方感覺詭異。"},{"en":"White noise can feel calming in a bedroom, but frightening in an empty research station.","zh":"白噪音在睡房裏可能令人平靜，但在空蕩的研究站裏可能令人害怕。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"the first thing to know about","meaning":"首先要知道的是","examples":[{"en":"The first thing to know about silence in the Arctic is that it is not quiet.","zh":"首先要知道的是，北極的寂靜並不安靜。"},{"en":"The first thing to know about a topic is the most important basic idea before anything else.","zh":"「首先要知道的是」指在其他事情之前，最重要的基本概念。"},{"en":"The first thing to know about cooking rice is that the amount of water matters.","zh":"首先要知道的是，煮飯時水量很重要。"},{"en":"The first thing to know about online safety is that strangers may not be who they say they are.","zh":"首先要知道的是，網上安全中陌生人未必如他們所說的那樣。"},{"en":"This phrase helps introduce an important warning or explanation at the beginning.","zh":"這個短語有助在開頭引入重要警告或解釋。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"silence in the Arctic","meaning":"北極的寂靜","examples":[{"en":"Silence in the Arctic is not quiet.","zh":"北極的寂靜並不安靜。"},{"en":"Silence in the Arctic means the deep stillness of the far northern ice and snow.","zh":"北極的寂靜指遙遠北方冰雪中的深沉靜止。"},{"en":"Silence in the Arctic can feel heavy because there are no cars, crowds, or city voices nearby.","zh":"北極的寂靜可能令人感到沉重，因為附近沒有汽車、人群或城市聲音。"},{"en":"In a lonely station, silence in the Arctic may make every small sound seem dangerous.","zh":"在孤立的研究站裏，北極的寂靜可能令每一個細小聲音都像危險。"},{"en":"Silence in the Arctic is different from peace; it can feel like something waiting.","zh":"北極的寂靜不同於平靜；它可能像有東西正在等待。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"the Arctic","meaning":"北極","examples":[{"en":"The Arctic silence presses against the station windows.","zh":"北極的寂靜壓向研究站的窗戶。"},{"en":"The Arctic is the cold northern region around the North Pole.","zh":"北極是圍繞北極點的寒冷北方地區。"},{"en":"Scientists may travel to the Arctic to study ice, weather, animals, and climate change.","zh":"科學家可能前往北極研究冰、天氣、動物和氣候變化。"},{"en":"Because the Arctic is so cold and remote, small problems can quickly become serious.","zh":"因為北極極寒又偏遠，小問題可能很快變得嚴重。"},{"en":"In stories, the Arctic often feels dangerous because help is far away.","zh":"在故事中，北極常令人感到危險，因為救援非常遙遠。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"presses against","meaning":"壓向；貼着","examples":[{"en":"Silence presses its white mouth against windows.","zh":"寂靜把它白色的嘴壓向窗戶。"},{"en":"If something presses against a surface, it pushes or leans on it closely.","zh":"如果某物 presses against 一個表面，就是緊貼着它或向它施壓。"},{"en":"On a crowded train, a bag may press against your leg.","zh":"在擠迫的列車上，袋子可能會壓着你的腿。"},{"en":"Strong wind can press against a door until it becomes hard to open.","zh":"強風可以壓向門，令門變得難以打開。"},{"en":"In the story, silence presses against the windows as if it is trying to get inside.","zh":"在故事中，寂靜壓向窗戶，好像想鑽進來。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"slips through","meaning":"從……鑽進去","examples":[{"en":"Silence slips through screws in steel.","zh":"寂靜從鋼鐵上的螺絲縫裏鑽進去。"},{"en":"If something slips through a space, it passes through quietly or secretly.","zh":"如果某物 slips through 一個空隙，就是安靜或偷偷地穿過去。"},{"en":"Cold air can slip through a small gap under the door.","zh":"冷空氣可以從門底的小縫鑽進來。"},{"en":"A mistake may slip through if nobody checks the homework carefully.","zh":"如果沒有人仔細檢查功課，錯誤可能會漏過去。"},{"en":"This phrase often suggests something small, quiet, and hard to stop.","zh":"這個短語常暗示某物細小、安靜，而且難以阻止。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"screws in steel","meaning":"鋼鐵上的螺絲","examples":[{"en":"Silence slips through screws in steel.","zh":"寂靜從鋼鐵上的螺絲縫裏鑽進去。"},{"en":"Screws in steel are metal fasteners fixed into steel to hold parts together.","zh":"鋼鐵上的螺絲是固定在鋼材中、用來連接部件的金屬扣件。"},{"en":"A mechanic checks screws in steel panels to make sure a machine is safe.","zh":"機械師會檢查鋼板上的螺絲，確保機器安全。"},{"en":"If screws in steel become loose, doors, machines, or walls may shake.","zh":"如果鋼鐵上的螺絲鬆了，門、機器或牆可能會震動。"},{"en":"In the station, even screws in steel seem unable to keep the silence out.","zh":"在研究站裏，連鋼鐵上的螺絲似乎也擋不住寂靜。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"at the edge of","meaning":"在……邊緣","examples":[{"en":"Silence waits at the edge of every sentence.","zh":"寂靜等在每一句話的邊緣。"},{"en":"At the edge of something means near the border, side, or limit of it.","zh":"at the edge of 指在某物的邊界、旁邊或極限附近。"},{"en":"A child stood at the edge of the swimming pool before jumping in.","zh":"孩子跳進泳池前站在泳池邊緣。"},{"en":"A town at the edge of a desert may face water shortages.","zh":"位於沙漠邊緣的城鎮可能面對缺水。"},{"en":"In writing, “at the edge of every sentence” suggests silence is always close.","zh":"在寫作中，「在每一句話的邊緣」暗示寂靜總是很接近。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"before I went north","meaning":"在我北上之前","examples":[{"en":"Before I went north, I thought silence meant the absence of sound.","zh":"在我北上之前，我以為寂靜就是沒有聲音。"},{"en":"Before I went north means before I travelled to a colder or more northern place.","zh":"before I went north 指在我前往較北或較寒冷的地方之前。"},{"en":"Before I went north for university, I had never seen snow.","zh":"在我北上讀大學之前，我從未見過雪。"},{"en":"Before I went north, I packed warm clothes because the weather would be severe.","zh":"在我北上之前，我收拾了保暖衣物，因為天氣會很嚴寒。"},{"en":"This phrase often marks a change between what someone believed before and what they learned later.","zh":"這個短語常標示一個人以前的想法和後來學到的事之間的轉變。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"the absence of sound","meaning":"沒有聲音","examples":[{"en":"I thought silence meant the absence of sound.","zh":"我以為寂靜就是沒有聲音。"},{"en":"The absence of sound means there is no noise or voice present.","zh":"the absence of sound 指沒有噪音或聲音存在。"},{"en":"In a library, the absence of sound can help students focus.","zh":"在圖書館裏，沒有聲音可以幫助學生集中。"},{"en":"After the power cut, the absence of sound made the apartment feel empty.","zh":"停電後，沒有聲音令公寓感覺空蕩蕩。"},{"en":"The story suggests that silence can be more than the absence of sound.","zh":"故事暗示，寂靜可以不只是沒有聲音。"}],"source":"2020 Q8.pdf","sourcePage":1},{"front":"by the time","meaning":"到……的時候","examples":[{"en":"By the time I reached Borealis-7, I knew better.","zh":"到我抵達 Borealis-7 的時候，我已經明白事實並非如此。"},{"en":"By the time means when a later moment arrived, something had already happened or changed.","zh":"by the time 指到某個較後時間時，某事已經發生或改變。"},{"en":"By the time the bus arrived, the students were already late.","zh":"到巴士到達的時候，學生們已經遲到了。"},{"en":"By the time she finished the project, she understood the problem much better.","zh":"到她完成項目的時候，她已經更了解那個問題。"},{"en":"This phrase helps show how time changes a person’s situation or understanding.","zh":"這個短語有助顯示時間如何改變一個人的處境或理解。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"knew better","meaning":"已經明白事實並非如此","examples":[{"en":"By the time I reached Borealis-7, I knew better.","zh":"到我抵達 Borealis-7 的時候，我已經明白事實並非如此。"},{"en":"If you know better, you understand the truth because experience has taught you.","zh":"如果你 know better，就是因經驗而明白真相並非自己以前所想。"},{"en":"I once thought exams were easy, but after failing one, I knew better.","zh":"我曾以為考試很容易，但失敗一次後，我就明白不是那樣。"},{"en":"Children may touch a hot pan once, but after that they know better.","zh":"孩子可能摸過一次熱鍋，但之後就會明白不能再那樣做。"},{"en":"In the story, Chris knew better because the Arctic silence felt alive, not empty.","zh":"在故事中，Chris 明白事實並非如此，因為北極的寂靜感覺像活着，而不是空無。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"called the matter","meaning":"把事情稱為","examples":[{"en":"The Ministry called the matter a temporary staffing irregularity.","zh":"部門把事情稱為暫時性人手異常。"},{"en":"To call the matter something means to describe or label the situation in a certain way.","zh":"called the matter something 指用某種說法描述或標籤一件事。"},{"en":"The school called the matter a misunderstanding, although parents thought it was serious.","zh":"學校把事情稱為誤會，雖然家長認為很嚴重。"},{"en":"A company may call the matter a delay to make a failure sound less damaging.","zh":"公司可能把事情稱為延誤，令失敗聽起來沒那麼嚴重。"},{"en":"This phrase can show how official language hides fear, blame, or danger.","zh":"這個短語可以顯示官方語言如何掩蓋恐懼、責任或危險。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"a temporary staffing irregularity","meaning":"暫時性人手異常","examples":[{"en":"The Ministry called the matter a temporary staffing irregularity.","zh":"部門把事情稱為暫時性人手異常。"},{"en":"A temporary staffing irregularity is an official-sounding phrase for a short-term problem with workers.","zh":"temporary staffing irregularity 是一個官方味很重的說法，指短期的人手問題。"},{"en":"A hospital might report a temporary staffing irregularity if several nurses suddenly cannot work.","zh":"如果幾名護士突然不能上班，醫院可能會報告暫時性人手異常。"},{"en":"Calling disappearances a temporary staffing irregularity makes the danger sound smaller.","zh":"把失蹤稱為暫時性人手異常，令危險聽起來較小。"},{"en":"This phrase feels cold and bureaucratic because it hides human fear behind polite words.","zh":"這個短語感覺冷冰冰又官僚，因為它用客氣字眼遮住人的恐懼。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"less delicate","meaning":"沒那麼婉轉","examples":[{"en":"My editor was less delicate about the disappearances.","zh":"我的編輯談到那些失蹤事件時沒那麼婉轉。"},{"en":"If someone is less delicate, they speak more directly and with less polite softness.","zh":"如果某人 less delicate，就是說話更直接，少了禮貌上的柔和。"},{"en":"The teacher was less delicate when she told the class that their work was careless.","zh":"老師告訴全班他們的功課很粗心時，語氣沒那麼婉轉。"},{"en":"A doctor may be less delicate in an emergency because clear instructions matter most.","zh":"醫生在緊急情況下可能沒那麼婉轉，因為清楚指示最重要。"},{"en":"In this sentence, the editor does not hide the seriousness of the disappearances.","zh":"在這句中，編輯沒有掩飾失蹤事件的嚴重性。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"slid a folder across","meaning":"把文件夾推過去","examples":[{"en":"My editor slid a thin folder across his desk.","zh":"我的編輯把一個薄薄的文件夾從桌上推過來。"},{"en":"To slide a folder across a desk means to push it smoothly from one side to another.","zh":"slid a folder across a desk 指把文件夾平滑地從桌子一邊推到另一邊。"},{"en":"The manager slid a folder across the table before explaining the new contract.","zh":"經理在解釋新合約前，把文件夾從桌上推過去。"},{"en":"A detective may slide a folder across to show evidence without saying much.","zh":"偵探可能把文件夾推過去，不多說話，只讓人看證據。"},{"en":"This action often feels quiet, serious, and deliberate.","zh":"這個動作常感覺安靜、嚴肅，而且有意圖。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"a thin folder","meaning":"一個薄薄的文件夾","examples":[{"en":"My editor slid a thin folder across his desk.","zh":"我的編輯把一個薄薄的文件夾從桌上推過來。"},{"en":"A thin folder is a small folder with only a few papers inside.","zh":"a thin folder 是裏面只有幾張紙的小文件夾。"},{"en":"The student carried a thin folder containing her application form and certificates.","zh":"學生拿着一個薄薄的文件夾，裏面有申請表和證書。"},{"en":"A thin folder can still contain important information if every page matters.","zh":"如果每一頁都重要，一個薄薄的文件夾也可以包含重要資料。"},{"en":"In the story, the thin folder suggests the case looks simple but may be dangerous.","zh":"在故事中，薄薄的文件夾暗示案件看似簡單，卻可能很危險。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"have vanished from","meaning":"從……消失","examples":[{"en":"Four scientists have vanished from a locked research station.","zh":"四名科學家從一間上鎖的研究站消失了。"},{"en":"If people have vanished from a place, they have disappeared from there suddenly or mysteriously.","zh":"如果人們 have vanished from 某地，就是他們突然或神秘地從那裏消失。"},{"en":"Several bikes have vanished from the school entrance this month.","zh":"這個月有幾輛單車從學校入口消失了。"},{"en":"When money has vanished from an account, the bank must investigate quickly.","zh":"當金錢從帳戶消失，銀行必須迅速調查。"},{"en":"The phrase sounds more mysterious than simply saying someone left.","zh":"這個短語比單純說某人離開更有神秘感。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"a locked research station","meaning":"上鎖的研究站","examples":[{"en":"Four scientists have vanished from a locked research station.","zh":"四名科學家從一間上鎖的研究站消失了。"},{"en":"A locked research station is a scientific workplace that has been secured so people cannot easily enter or leave.","zh":"上鎖的研究站是已被鎖好、令人不能輕易進出的科學工作場所。"},{"en":"A locked research station in the Arctic may use airlocks, cameras, and sealed doors.","zh":"北極的上鎖研究站可能使用氣閘、攝影機和密封門。"},{"en":"If someone disappears from a locked research station, the mystery becomes harder to explain.","zh":"如果有人從上鎖的研究站消失，謎團就更難解釋。"},{"en":"This phrase creates tension because locked places should be safe and controlled.","zh":"這個短語製造緊張感，因為上鎖的地方本應安全且受控制。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"one by one","meaning":"一個接一個","examples":[{"en":"The scientists vanished one by one.","zh":"科學家們一個接一個地消失了。"},{"en":"One by one means separately, in sequence, not all at the same time.","zh":"one by one 指逐個、按次序地發生，而不是同時發生。"},{"en":"The students entered the classroom one by one after the bell rang.","zh":"鐘聲響起後，學生們一個接一個走進課室。"},{"en":"If lights go out one by one, the room slowly becomes darker.","zh":"如果燈一盞接一盞熄滅，房間會慢慢變暗。"},{"en":"In a mystery, people disappearing one by one makes the fear grow.","zh":"在懸疑故事中，人們一個接一個消失會令恐懼增加。"}],"source":"2020 Q8.pdf","sourcePage":2},{"front":"find out why","meaning":"查明原因","examples":[{"en":"Chris was sent north to find out why.","zh":"Chris 被派往北方去查明原因。"},{"en":"To find out why means to discover the reason something happened.","zh":"find out why 指找出某件事發生的原因。"},{"en":"The teacher checked the records to find out why many students were absent.","zh":"老師查看紀錄，以查明為何許多學生缺席。"},{"en":"A doctor asks questions to find out why a patient feels dizzy.","zh":"醫生會問問題，以查明病人為何頭暈。"},{"en":"This phrase shows that a person is looking for causes, not just facts.","zh":"這個短語表示一個人在尋找原因，而不只是尋找事實。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"become number five","meaning":"成為第五個失蹤者","examples":[{"en":"The editor told Chris not to become number five.","zh":"編輯叫 Chris 不要成為第五個失蹤者。"},{"en":"To become number five here means to become the fifth person who disappears.","zh":"become number five 在這裏指成為第五個消失的人。"},{"en":"If four workers have already fallen ill, the manager tells others not to become number five.","zh":"如果已有四名員工生病，經理會提醒其他人不要成為第五個。"},{"en":"The phrase sounds dark because a person is reduced to the next victim in a list.","zh":"這個短語聽起來陰暗，因為一個人被簡化成名單上的下一個受害者。"},{"en":"In the story, it is a warning that Chris may vanish like the scientists.","zh":"在故事中，這是警告 Chris 可能會像科學家一樣消失。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"so there I was","meaning":"於是我就這樣","examples":[{"en":"So there I was, two days later, arriving at the top of the world.","zh":"於是我就這樣，兩天後，抵達世界之巔。"},{"en":"So there I was is used when a speaker introduces a situation they suddenly found themselves in.","zh":"so there I was 用來引入說話者突然身處的情況。"},{"en":"So there I was, standing outside the exam room with no pen.","zh":"於是我就這樣，站在考場外，卻沒有筆。"},{"en":"So there I was can make a story feel personal and immediate.","zh":"so there I was 可以令故事感覺更個人、更即時。"},{"en":"In this sentence, it shows Chris has moved quickly from conversation to danger.","zh":"在這句中，它顯示 Chris 很快從談話走進危險。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"a supply helicopter","meaning":"補給直升機","examples":[{"en":"Chris arrived by supply helicopter.","zh":"Chris 乘補給直升機抵達。"},{"en":"A supply helicopter carries food, equipment, medicine, or people to remote places.","zh":"補給直升機把食物、設備、藥物或人員送到偏遠地方。"},{"en":"Mountain villages may depend on a supply helicopter after roads are blocked by snow.","zh":"當道路被雪封住，山村可能依靠補給直升機。"},{"en":"If a supply helicopter cannot land, people in isolated areas may run short of goods.","zh":"如果補給直升機不能降落，孤立地區的人可能會物資短缺。"},{"en":"In the Arctic, a supply helicopter shows how far the station is from normal transport.","zh":"在北極，補給直升機顯示研究站離正常交通非常遠。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"a rectangle of blue ice","meaning":"一塊長方形藍冰","examples":[{"en":"The helicopter dropped him onto a rectangle of blue ice.","zh":"直升機把他放到一塊長方形藍冰上。"},{"en":"A rectangle of blue ice is a flat, rectangular area of ice with a blue colour.","zh":"a rectangle of blue ice 指一片平坦、長方形、帶藍色的冰面。"},{"en":"The rescue team marked a rectangle of blue ice as the safest place to land.","zh":"救援隊把一塊長方形藍冰標記為最安全的降落地點。"},{"en":"Blue ice can look beautiful, but it may also be hard, slippery, and dangerous.","zh":"藍冰看起來可以很美，但也可能堅硬、濕滑和危險。"},{"en":"In the story, the phrase makes the landing place feel cold and unnatural.","zh":"在故事中，這個短語令降落地點感覺寒冷而不自然。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"at the top of the world","meaning":"在世界之巔","examples":[{"en":"Chris landed on blue ice at the top of the world.","zh":"Chris 降落在世界之巔的藍冰上。"},{"en":"At the top of the world means in the far north, near the Arctic region.","zh":"at the top of the world 指在極北之地，接近北極地區。"},{"en":"Explorers may describe the North Pole as the top of the world.","zh":"探險者可能把北極點形容為世界之巔。"},{"en":"At the top of the world, ordinary help, shops, and hospitals may be far away.","zh":"在世界之巔，普通救援、商店和醫院可能都很遙遠。"},{"en":"This phrase can sound adventurous, but in the story it also feels lonely.","zh":"這個短語可以聽起來像冒險，但在故事中也感覺孤獨。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"land properly","meaning":"正式着陸","examples":[{"en":"The pilot did not land properly.","zh":"飛行員沒有正式着陸。"},{"en":"To land properly means to bring an aircraft safely and correctly onto the ground.","zh":"land properly 指讓飛行器安全而正確地落到地面。"},{"en":"A plane cannot land properly if strong wind pushes it sideways.","zh":"如果強風把飛機推向一邊，它就不能正式着陸。"},{"en":"If a helicopter does not land properly, passengers may have to jump down carefully.","zh":"如果直升機沒有正式着陸，乘客可能要小心跳下去。"},{"en":"In the story, the failed landing suggests the place is dangerous even for machines.","zh":"在故事中，未能正式着陸暗示這個地方連機器也難以應付。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"lowered the craft","meaning":"降低飛行器","examples":[{"en":"The pilot lowered the craft long enough for him to jump.","zh":"飛行員把飛行器降低到足夠讓他跳下去。"},{"en":"To lower the craft means to move the aircraft closer to the ground.","zh":"lower the craft 指把飛行器移近地面。"},{"en":"The pilot lowered the craft slowly so the rescue worker could step onto the roof.","zh":"飛行員慢慢降低飛行器，讓救援人員踏上屋頂。"},{"en":"In bad weather, lowering the craft too much can be risky.","zh":"在惡劣天氣中，把飛行器降得太低可能有風險。"},{"en":"This phrase shows the helicopter did not fully land, but came down briefly.","zh":"這個短語顯示直升機沒有完全降落，只是短暫降低。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"long enough for","meaning":"足夠讓……","examples":[{"en":"The pilot lowered the craft long enough for Chris to jump.","zh":"飛行員把飛行器降低到足夠讓 Chris 跳下去。"},{"en":"Long enough for something means there is sufficient time for that action to happen.","zh":"long enough for something 指時間足夠讓某個動作發生。"},{"en":"The bus stopped long enough for the old man to get on safely.","zh":"巴士停得足夠久，讓老人安全上車。"},{"en":"The door stayed open long enough for the cat to run inside.","zh":"門開着的時間足夠讓貓跑進來。"},{"en":"In this sentence, Chris only had a short chance to jump from the helicopter.","zh":"在這句中，Chris 只有短暫機會從直升機跳下去。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"duffel","meaning":"帆布旅行袋","examples":[{"en":"His duffel thudded beside him like a body.","zh":"他的帆布旅行袋像一具屍體般砰一聲落在他旁邊。"},{"en":"A duffel is a soft travel bag often used for clothes and equipment.","zh":"duffel 是一種柔軟的旅行袋，常用來裝衣物和裝備。"},{"en":"The athlete packed shoes, towels, and a uniform into his duffel.","zh":"運動員把鞋、毛巾和制服放進帆布旅行袋。"},{"en":"A heavy duffel can be hard to carry across snow or ice.","zh":"沉重的帆布旅行袋很難在雪地或冰面上攜帶。"},{"en":"In the story, the duffel sounds unsettling because it lands like a body.","zh":"在故事中，帆布旅行袋令人不安，因為它像屍體一樣落地。"}],"source":"2020 Q8.pdf","sourcePage":3},{"front":"thudded beside","meaning":"砰一聲落在旁邊","examples":[{"en":"His duffel thudded beside him like a body.","zh":"他的帆布旅行袋像一具屍體般砰一聲落在他旁邊。"},{"en":"If something thudded beside you, it landed near you with a heavy dull sound.","zh":"如果某物 thudded beside you，就是它在你旁邊以沉重低響落下。"},{"en":"A pile of books thudded beside the desk when the student dropped them.","zh":"學生把一疊書掉下時，書砰一聲落在書桌旁邊。"},{"en":"Heavy footsteps thudded beside the bedroom door and woke the child.","zh":"沉重腳步聲在睡房門旁砰砰作響，吵醒了孩子。"},{"en":"The word thudded makes the landing feel heavy, sudden, and physical.","zh":"thudded 這個詞令落下的動作感覺沉重、突然和實在。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"like a body","meaning":"像一具屍體","examples":[{"en":"His duffel landed beside him like a body.","zh":"他的帆布旅行袋像一具屍體般落在他旁邊。"},{"en":"Like a body compares something to a human body, often to create fear or unease.","zh":"like a body 把某物比作人體，常用來製造恐懼或不安。"},{"en":"The wet coat lay on the floor like a body in the dark hallway.","zh":"濕外套在黑暗走廊的地上攤開，像一具屍體。"},{"en":"A bag falling like a body can make people turn around in alarm.","zh":"袋子像屍體一樣落下，可能令人驚慌回頭。"},{"en":"In the story, this comparison quietly introduces the idea of death.","zh":"在故事中，這個比喻悄悄引入死亡的感覺。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"No offence","meaning":"無意冒犯","examples":[{"en":"The pilot said, “No offence, Mr Wong.”","zh":"飛行員說：「無意冒犯，Wong 先生。」"},{"en":"No offence means the speaker does not want the listener to feel insulted.","zh":"No offence 指說話者不想令聽者感到被冒犯。"},{"en":"No offence, but your plan needs more details before we present it.","zh":"無意冒犯，但你的計劃在匯報前需要更多細節。"},{"en":"People often say “no offence” before a comment that may sound rude or uncomfortable.","zh":"人們常在可能聽起來粗魯或令人不舒服的評論前說 no offence。"},{"en":"In the story, the pilot uses it before warning Chris about the strange place.","zh":"在故事中，飛行員在警告 Chris 這個怪地方前使用這句話。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"makes the instruments lie","meaning":"令儀器顯示錯誤","examples":[{"en":"The pilot said the place makes the instruments lie.","zh":"飛行員說這個地方會令儀器顯示錯誤。"},{"en":"If a place makes the instruments lie, the machines give false readings there.","zh":"如果一個地方 makes the instruments lie，就是那裏令機器給出錯誤讀數。"},{"en":"A strong magnetic field can make instruments lie by confusing the compass.","zh":"強磁場可以擾亂指南針，令儀器顯示錯誤。"},{"en":"If instruments lie during a flight, the pilot may not know the true height or direction.","zh":"如果飛行中儀器顯示錯誤，飛行員可能不知道真正高度或方向。"},{"en":"This phrase makes the Arctic seem powerful enough to deceive technology.","zh":"這個短語令北極看似強大到足以欺騙科技。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"rose into","meaning":"升進","examples":[{"en":"The helicopter rose into the bruised sky.","zh":"直升機升進暗紫色的天空。"},{"en":"Rose into means moved upward and entered a place or area.","zh":"rose into 指向上移動並進入某個地方或範圍。"},{"en":"Smoke rose into the evening air after the fire started.","zh":"火起後，煙升進傍晚的空氣中。"},{"en":"The balloon rose into the clouds until the child could barely see it.","zh":"氣球升進雲裏，直到孩子幾乎看不見它。"},{"en":"In the story, the helicopter rising into the sky leaves Chris alone below.","zh":"在故事中，直升機升進天空，把 Chris 獨自留在下面。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"the bruised sky","meaning":"暗紫色的天空","examples":[{"en":"The helicopter rose into the bruised sky.","zh":"直升機升進暗紫色的天空。"},{"en":"The bruised sky means a dark purple or blue sky that looks like a bruise.","zh":"the bruised sky 指像瘀傷一樣呈深紫或深藍色的天空。"},{"en":"Before a storm, the evening sky may turn bruised and heavy.","zh":"暴風雨前，傍晚天空可能變得暗紫而沉重。"},{"en":"Describing the sky as bruised can make a scene feel injured or threatening.","zh":"把天空形容為 bruised 可以令場景感覺受傷或有威脅。"},{"en":"In this sentence, the bruised sky adds danger to the Arctic setting.","zh":"在這句中，暗紫色的天空為北極環境增添危險感。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"left me alone","meaning":"留下我獨自一人","examples":[{"en":"The pilot left Chris alone at the station.","zh":"飛行員把 Chris 留在研究站獨自一人。"},{"en":"Left me alone means went away and made me stay by myself.","zh":"left me alone 指別人離開，令我自己一個留下。"},{"en":"My friends left me alone at the bus stop when they got on the wrong bus.","zh":"我的朋友上錯巴士後，把我獨自留在巴士站。"},{"en":"Being left alone in a strange place can make a person nervous.","zh":"被獨自留在陌生地方可能令人緊張。"},{"en":"In the story, Chris being left alone increases the feeling of isolation.","zh":"在故事中，Chris 被獨自留下加強了孤立感。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, Borealis-7 looked exactly like the photograph.","zh":"乍看之下，Borealis-7 看起來完全像照片。"},{"en":"At first glance means when you first look at something, before checking carefully.","zh":"at first glance 指初看某物時，還未仔細檢查之前。"},{"en":"At first glance, the phone looked new, but its screen was cracked.","zh":"乍看之下，那部電話像新的，但螢幕裂了。"},{"en":"At first glance, a problem may seem simple until details appear.","zh":"乍看之下，問題可能很簡單，直到細節出現。"},{"en":"This phrase often prepares readers for a later discovery or correction.","zh":"這個短語常為之後的發現或修正作準備。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"looked exactly like","meaning":"看起來完全像","examples":[{"en":"Borealis-7 looked exactly like the Ministry’s photograph.","zh":"Borealis-7 看起來完全像部門的照片。"},{"en":"Looked exactly like means appeared the same as something else in every clear way.","zh":"looked exactly like 指外觀在明顯方面與另一物完全相同。"},{"en":"The cake looked exactly like the picture on the recipe website.","zh":"那個蛋糕看起來完全像食譜網站上的圖片。"},{"en":"A fake ID may look exactly like a real one until someone checks it closely.","zh":"假證件可能看起來完全像真證件，直到有人仔細檢查。"},{"en":"In the story, the station looks correct at first, but small details feel wrong.","zh":"在故事中，研究站起初看起來正確，但小細節令人覺得不對。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"linked by sealed corridors","meaning":"由密封走廊連接","examples":[{"en":"Three silver modules were linked by sealed corridors.","zh":"三個銀色艙體由密封走廊連接。"},{"en":"If buildings are linked by sealed corridors, closed passageways connect them safely.","zh":"如果建築物 linked by sealed corridors，就是由封閉通道安全連接。"},{"en":"In cold places, laboratories may be linked by sealed corridors so workers do not go outside.","zh":"在寒冷地方，實驗室可能由密封走廊連接，讓工作人員不用外出。"},{"en":"Sealed corridors can protect people from wind, snow, or dangerous air.","zh":"密封走廊可以保護人免受風雪或危險空氣影響。"},{"en":"This phrase makes the station sound controlled, closed, and difficult to escape.","zh":"這個短語令研究站聽起來受控制、封閉，而且難以逃離。"}],"source":"2020 Q8.pdf","sourcePage":4},{"front":"sealed corridors","meaning":"密封走廊","examples":[{"en":"The modules were connected by sealed corridors.","zh":"那些艙體由密封走廊連接。"},{"en":"Sealed corridors are closed passageways that stop air, cold, or contamination from entering.","zh":"sealed corridors 是封閉通道，可以阻止空氣、寒冷或污染物進入。"},{"en":"Hospitals may use sealed corridors to separate clean areas from infected areas.","zh":"醫院可能使用密封走廊，把潔淨區和感染區分開。"},{"en":"If sealed corridors fail, dangerous air may spread through a building.","zh":"如果密封走廊失效，危險空氣可能在建築物內擴散。"},{"en":"In the story, sealed corridors make the station feel safe but also trapped.","zh":"在故事中，密封走廊令研究站感覺安全，但也像被困住。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"a wind turbine","meaning":"風力渦輪機","examples":[{"en":"A wind turbine turned beside the station.","zh":"一座風力渦輪機在研究站旁轉動。"},{"en":"A wind turbine is a tall machine that uses wind to produce electricity.","zh":"風力渦輪機是利用風力發電的高大機器。"},{"en":"A farm may use a wind turbine to power lights and water pumps.","zh":"農場可能用風力渦輪機為燈和水泵供電。"},{"en":"If a wind turbine stops during a storm, a remote station may lose power.","zh":"如果風力渦輪機在暴風中停下，偏遠研究站可能會停電。"},{"en":"In the Arctic, a wind turbine shows how the station depends on harsh weather.","zh":"在北極，風力渦輪機顯示研究站依賴惡劣天氣。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"with slow, unwilling grace","meaning":"緩慢而勉強地優雅轉動","examples":[{"en":"The wind turbine turned with slow, unwilling grace.","zh":"風力渦輪機緩慢而勉強地優雅轉動。"},{"en":"With slow, unwilling grace means moving beautifully but reluctantly and heavily.","zh":"with slow, unwilling grace 指動作優雅，但緩慢、沉重，好像不情願。"},{"en":"The old dancer stood up with slow, unwilling grace after hurting his knee.","zh":"老舞者膝蓋受傷後，緩慢而勉強地優雅站起來。"},{"en":"A door may open with slow, unwilling grace when its hinges are frozen.","zh":"當鉸鏈結冰，門可能緩慢而勉強地優雅打開。"},{"en":"In this phrase, the turbine seems almost alive and unwilling to move.","zh":"在這個短語中，渦輪機幾乎像有生命，而且不願轉動。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"a radio mast","meaning":"無線電桅杆","examples":[{"en":"A radio mast pointed at the clouds.","zh":"一支無線電桅杆指向雲層。"},{"en":"A radio mast is a tall structure used to send or receive radio signals.","zh":"radio mast 是用來發送或接收無線電訊號的高大結構。"},{"en":"A ship may use a radio mast to contact the coast during bad weather.","zh":"船隻可能用無線電桅杆在惡劣天氣中聯絡岸邊。"},{"en":"If a radio mast breaks, people in remote places may lose communication.","zh":"如果無線電桅杆損壞，偏遠地方的人可能失去通訊。"},{"en":"In the story, the radio mast suggests the station depends on fragile contact with the outside world.","zh":"在故事中，無線電桅杆暗示研究站依靠脆弱的外界聯繫。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"pointing at","meaning":"指向","examples":[{"en":"The radio mast was pointing at the clouds like an accusation.","zh":"無線電桅杆像控訴一樣指向雲層。"},{"en":"Pointing at means facing or directing toward a person, object, or place.","zh":"pointing at 指面向或指向某人、某物或某地。"},{"en":"The sign was pointing at the emergency exit.","zh":"標誌指向緊急出口。"},{"en":"A child pointing at a broken window may show where the accident happened.","zh":"孩子指向破窗，可能是在指出意外發生的位置。"},{"en":"In the story, the mast pointing at the clouds feels like blame.","zh":"在故事中，桅杆指向雲層，感覺像在責怪。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"like an accusation","meaning":"像一種控訴","examples":[{"en":"The mast pointed at the clouds like an accusation.","zh":"桅杆像一種控訴般指向雲層。"},{"en":"Like an accusation means in a way that seems to blame someone or something.","zh":"like an accusation 指某種樣子像是在責怪某人或某事。"},{"en":"The dirty plates on the table sat there like an accusation after everyone left.","zh":"所有人離開後，桌上的髒碟像一種控訴般留在那裏。"},{"en":"A teacher’s silence can feel like an accusation when homework is missing.","zh":"當功課不見了，老師的沉默可能感覺像一種控訴。"},{"en":"This comparison gives an object an angry, blaming feeling.","zh":"這個比喻令物件帶有憤怒和責備的感覺。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"on closer inspection","meaning":"仔細看時","examples":[{"en":"On closer inspection, several details refused to fit.","zh":"仔細看時，有幾個細節顯得格格不入。"},{"en":"On closer inspection means after looking more carefully.","zh":"on closer inspection 指更仔細查看之後。"},{"en":"On closer inspection, the cheap watch had scratches around the glass.","zh":"仔細看時，那隻便宜手錶的玻璃邊有刮痕。"},{"en":"A plan may sound perfect at first, but on closer inspection, the costs are too high.","zh":"一個計劃起初可能聽起來完美，但仔細看時，成本太高。"},{"en":"This phrase often reveals problems hidden by a first look.","zh":"這個短語常揭示初看時隱藏的問題。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"refused to fit","meaning":"顯得格格不入；不對勁","examples":[{"en":"Several details refused to fit.","zh":"有幾個細節顯得格格不入。"},{"en":"If details refuse to fit, they do not match the expected explanation.","zh":"如果 details refuse to fit，就是它們與預期解釋不相符。"},{"en":"The witness’s story refused to fit with the security footage.","zh":"目擊者的說法與保安錄像格格不入。"},{"en":"A small receipt may refuse to fit the timeline and make investigators suspicious.","zh":"一張小收據可能與時間線不吻合，令調查員起疑。"},{"en":"This phrase suggests the problem is quietly resisting a simple answer.","zh":"這個短語暗示問題正悄悄抗拒一個簡單答案。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"eastern airlock","meaning":"東面氣閘","examples":[{"en":"The eastern airlock stood open.","zh":"東面氣閘開着。"},{"en":"The eastern airlock is the airlock on the east side of a building or station.","zh":"eastern airlock 指建築物或研究站東邊的氣閘。"},{"en":"Workers used the eastern airlock to enter the laboratory from the snowfield.","zh":"工作人員用東面氣閘從雪地進入實驗室。"},{"en":"If the eastern airlock is open, cold air or danger may enter the station.","zh":"如果東面氣閘開着，冷空氣或危險可能進入研究站。"},{"en":"In the story, an open eastern airlock is worrying because airlocks should be secure.","zh":"在故事中，開着的東面氣閘令人擔心，因為氣閘本應安全關閉。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"stood open","meaning":"開着","examples":[{"en":"The eastern airlock stood open.","zh":"東面氣閘開着。"},{"en":"Stood open means remained open, often in a way that seems noticeable or wrong.","zh":"stood open 指一直開着，常帶有明顯或不對勁的感覺。"},{"en":"The shop door stood open after closing time, so the owner checked inside.","zh":"店門在關門時間後仍開着，所以店主進去檢查。"},{"en":"If a medicine cabinet stands open, a parent may worry that a child touched it.","zh":"如果藥櫃開着，家長可能擔心孩子碰過它。"},{"en":"This phrase can make an open door feel like evidence of trouble.","zh":"這個短語可以令一扇開着的門感覺像麻煩的證據。"}],"source":"2020 Q8.pdf","sourcePage":5},{"front":"security light","meaning":"保安燈","examples":[{"en":"The security light blinked red, then green, then red again.","zh":"保安燈閃着紅色，然後綠色，又再紅色。"},{"en":"A security light is a warning or safety light that shows whether an area is safe, locked, or in danger.","zh":"security light 是顯示某區域是否安全、上鎖或有危險的警示燈。"},{"en":"The security light outside the office turns on when someone approaches at night.","zh":"辦公室外的保安燈在晚上有人接近時會亮起。"},{"en":"If a security light changes colour strangely, workers may check the alarm system.","zh":"如果保安燈奇怪地變色，員工可能會檢查警報系統。"},{"en":"In the story, the blinking security light suggests something is wrong with the station.","zh":"在故事中，閃爍的保安燈暗示研究站出了問題。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"blinked red and green","meaning":"閃着紅綠燈","examples":[{"en":"The security light blinked red, then green, then red again.","zh":"保安燈閃着紅色，然後綠色，又再紅色。"},{"en":"Blinked red and green means flashed between red and green lights.","zh":"blinked red and green 指紅燈和綠燈交替閃爍。"},{"en":"The traffic signal blinked red and green during the power fault.","zh":"交通燈在電力故障期間閃着紅綠燈。"},{"en":"If a machine blinks red and green, it may be showing mixed or unclear status.","zh":"如果機器閃着紅綠燈，可能表示狀態混亂或不清楚。"},{"en":"In this sentence, the changing colours make the airlock feel unreliable.","zh":"在這句中，變換的顏色令氣閘感覺不可靠。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"fresh footprints","meaning":"新近的腳印","examples":[{"en":"There were no fresh footprints leading out.","zh":"沒有新近的腳印往外延伸。"},{"en":"Fresh footprints are new marks made by feet or shoes on the ground.","zh":"fresh footprints 是腳或鞋在地面留下的新痕跡。"},{"en":"After the snow stopped, fresh footprints showed that someone had walked across the garden.","zh":"雪停後，新近的腳印顯示有人走過花園。"},{"en":"If there are no fresh footprints outside a door, it may mean nobody recently left that way.","zh":"如果門外沒有新近的腳印，可能表示最近沒有人從那裏離開。"},{"en":"In the story, the lack of fresh footprints makes the open airlock more mysterious.","zh":"在故事中，沒有新近的腳印令開着的氣閘更加神秘。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"leading out","meaning":"往外延伸","examples":[{"en":"There were no fresh footprints leading out.","zh":"沒有新近的腳印往外延伸。"},{"en":"Leading out means going away from the inside toward the outside.","zh":"leading out 指從裏面朝外面延伸或離開。"},{"en":"The path leading out of the park goes past the bus stop.","zh":"往公園外延伸的小路會經過巴士站。"},{"en":"Footprints leading out of a room may show where someone escaped.","zh":"往房間外延伸的腳印可能顯示某人逃走的方向。"},{"en":"In this sentence, the absence of tracks means no one seems to have left through the airlock.","zh":"在這句中，沒有痕跡表示似乎沒有人經氣閘離開。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"stepped inside","meaning":"走進去","examples":[{"en":"Chris stepped inside the research station.","zh":"Chris 走進研究站。"},{"en":"Stepped inside means walked into a place, usually from outside.","zh":"stepped inside 指從外面走進某個地方。"},{"en":"The customer stepped inside the shop to escape the rain.","zh":"顧客走進店裏避雨。"},{"en":"When someone steps inside a dark room, they may pause to let their eyes adjust.","zh":"當人走進黑暗房間，可能會停一停讓眼睛適應。"},{"en":"In the story, stepping inside moves Chris from the open ice into the mystery.","zh":"在故事中，走進去令 Chris 從開闊冰面進入謎團。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"heat struck me first","meaning":"熱氣首先迎面襲來","examples":[{"en":"Heat struck Chris first when he entered.","zh":"Chris 進去時，熱氣首先迎面襲來。"},{"en":"Heat struck me first means the warmth was the first strong thing I noticed.","zh":"heat struck me first 指熱力是我第一個強烈注意到的東西。"},{"en":"When I opened the oven, heat struck me first and made me step back.","zh":"我打開焗爐時，熱氣首先迎面襲來，令我退後一步。"},{"en":"After walking through snow, the heat inside a building can strike you suddenly.","zh":"在雪地行走後，建築物內的熱氣可以突然迎面襲來。"},{"en":"In the story, the heat contrasts sharply with the frozen world outside.","zh":"在故事中，熱氣與外面的冰冷世界形成強烈對比。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"the smell of","meaning":"……的氣味","examples":[{"en":"The station had the smell of coffee, disinfectant, metal and fear.","zh":"研究站有咖啡、消毒藥水、金屬和恐懼的氣味。"},{"en":"The smell of something means the scent or odour that comes from it.","zh":"the smell of something 指某物散發出的氣味。"},{"en":"The smell of fresh bread filled the kitchen in the morning.","zh":"清晨，鮮麵包的氣味充滿廚房。"},{"en":"The smell of smoke can warn people that something is burning.","zh":"煙的氣味可以警告人們有東西正在燃燒。"},{"en":"In the story, the smell of fear suggests danger even before anyone explains it.","zh":"在故事中，恐懼的氣味在任何人解釋前已暗示危險。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"disinfectant","meaning":"消毒藥水","examples":[{"en":"The corridor smelled of disinfectant.","zh":"走廊有消毒藥水的氣味。"},{"en":"Disinfectant is a chemical used to kill germs on surfaces.","zh":"disinfectant 是用來殺死表面細菌的化學清潔劑。"},{"en":"Hospitals use disinfectant to clean beds, floors, and medical equipment.","zh":"醫院使用消毒藥水清潔病床、地板和醫療設備。"},{"en":"Too much disinfectant can make a room smell sharp and uncomfortable.","zh":"太多消毒藥水會令房間氣味刺鼻而令人不舒服。"},{"en":"In the station, disinfectant suggests cleanliness but also illness or danger.","zh":"在研究站裏，消毒藥水暗示潔淨，也暗示疾病或危險。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"deep in the station","meaning":"在研究站深處","examples":[{"en":"Somewhere deep in the station, a machine clicked steadily.","zh":"在研究站深處某處，一部機器有規律地滴答作響。"},{"en":"Deep in the station means far inside the building, away from the entrance.","zh":"deep in the station 指在建築物裏面很深處，遠離入口。"},{"en":"Deep in the school basement, old pipes made noises at night.","zh":"在學校地庫深處，舊水管晚上會發出聲音。"},{"en":"A sound deep in the station can feel mysterious because its source is hidden.","zh":"研究站深處的聲音可能令人感到神秘，因為來源被藏住。"},{"en":"This phrase makes the station seem larger and more secretive.","zh":"這個短語令研究站顯得更大、更隱秘。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"clicked steadily","meaning":"有規律地滴答作響","examples":[{"en":"A machine clicked steadily in the station.","zh":"一部機器在研究站裏有規律地滴答作響。"},{"en":"Clicked steadily means made regular small clicking sounds again and again.","zh":"clicked steadily 指一次又一次發出規律的小滴答聲。"},{"en":"The clock clicked steadily while the students waited for the exam to end.","zh":"學生等待考試結束時，時鐘有規律地滴答作響。"},{"en":"A machine clicking steadily may sound normal, but in a quiet room it can feel tense.","zh":"機器有規律地滴答作響可能很正常，但在安靜房間裏會令人緊張。"},{"en":"In the story, the steady clicks sound like time running out.","zh":"在故事中，規律滴答聲像時間正在耗盡。"}],"source":"2020 Q8.pdf","sourcePage":6},{"front":"as if counting down","meaning":"好像在倒數","examples":[{"en":"The machine clicked steadily, as if counting down.","zh":"機器有規律地滴答作響，好像在倒數。"},{"en":"As if counting down means it seemed to be marking the time before something happens.","zh":"as if counting down 指它似乎在標記某事發生前的時間。"},{"en":"The timer beeped faster, as if counting down to a race.","zh":"計時器越響越快，好像在為比賽倒數。"},{"en":"Rain tapped the roof as if counting down the minutes before the storm arrived.","zh":"雨點敲打屋頂，好像在倒數暴風來臨前的分鐘。"},{"en":"This phrase creates suspense because counting down suggests an approaching event.","zh":"這個短語製造懸念，因為倒數暗示某件事即將發生。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"called out","meaning":"大聲呼叫","examples":[{"en":"Chris called out in the corridor.","zh":"Chris 在走廊裏大聲呼叫。"},{"en":"Called out means spoke loudly so someone could hear.","zh":"called out 指大聲說話，讓別人聽見。"},{"en":"The teacher called out the students’ names during attendance.","zh":"老師點名時大聲讀出學生名字。"},{"en":"A child lost in a supermarket may call out for their parent.","zh":"在超市走失的孩子可能會大聲呼叫父母。"},{"en":"In the story, Chris calls out because he expects someone to answer.","zh":"在故事中，Chris 大聲呼叫，因為他期待有人回答。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"swallowed my voice","meaning":"吞沒我的聲音","examples":[{"en":"The corridor swallowed his voice before it could travel far.","zh":"走廊在他的聲音傳遠之前就吞沒了它。"},{"en":"If a place swallowed my voice, it absorbed the sound so it did not carry.","zh":"如果一個地方 swallowed my voice，就是它吸收聲音，令聲音傳不遠。"},{"en":"The thick curtains swallowed my voice, so people outside could not hear me.","zh":"厚窗簾吞沒了我的聲音，所以外面的人聽不見。"},{"en":"A huge empty hall can swallow a quiet voice and make it disappear.","zh":"巨大的空禮堂可以吞沒細小聲音，令它消失。"},{"en":"This phrase makes the corridor feel powerful and unnatural.","zh":"這個短語令走廊感覺有力量而且不自然。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"before it could travel far","meaning":"在它能傳遠之前","examples":[{"en":"The corridor swallowed his voice before it could travel far.","zh":"走廊在他的聲音能傳遠之前就吞沒了它。"},{"en":"Before it could travel far means before the sound had time to move a long distance.","zh":"before it could travel far 指聲音還未能傳到較遠地方之前。"},{"en":"The wall stopped the music before it could travel far down the street.","zh":"牆壁在音樂能沿街傳遠之前就擋住了它。"},{"en":"Snow can absorb sound before it can travel far across an open field.","zh":"雪地可以在聲音傳遠之前吸收它。"},{"en":"In the story, the voice dies quickly, making Chris feel more alone.","zh":"在故事中，聲音很快消失，令 Chris 更感孤獨。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"speaker above my head","meaning":"頭頂上的喇叭","examples":[{"en":"A speaker above his head suddenly spoke.","zh":"他頭頂上的喇叭突然說話。"},{"en":"A speaker above my head is a sound device fixed overhead.","zh":"speaker above my head 指固定在頭頂上方的播音裝置。"},{"en":"The speaker above my head announced that the train would be delayed.","zh":"我頭頂上的喇叭宣布列車會延誤。"},{"en":"If a speaker above your head suddenly speaks in an empty room, it can startle you.","zh":"如果空房間裏頭頂上的喇叭突然說話，可能會嚇到你。"},{"en":"In the station, the overhead speaker makes the building seem to watch and control Chris.","zh":"在研究站裏，頭頂上的喇叭令建築物似乎在監視和控制 Chris。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"turned to face me","meaning":"轉過來面向我","examples":[{"en":"The camera beside the speaker turned to face him.","zh":"喇叭旁的攝影機轉過來面向他。"},{"en":"Turned to face me means moved so that its front was directed toward me.","zh":"turned to face me 指轉動到正面朝向我。"},{"en":"The teacher turned to face the class before explaining the answer.","zh":"老師轉過來面向全班，然後解釋答案。"},{"en":"When the camera turned to face me, I knew someone was watching.","zh":"當攝影機轉過來面向我時，我知道有人正在看着。"},{"en":"In the story, the camera’s movement makes Chris feel observed.","zh":"在故事中，攝影機的轉動令 Chris 感到被監視。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"proceed to decontamination","meaning":"前往除污程序","examples":[{"en":"The voice told Chris to proceed to decontamination.","zh":"那聲音叫 Chris 前往除污程序。"},{"en":"Proceed to decontamination means go to the place or process where harmful substances are removed.","zh":"proceed to decontamination 指前往清除有害物質的地方或程序。"},{"en":"After the chemical leak, workers were told to proceed to decontamination immediately.","zh":"化學品洩漏後，工作人員被要求立即前往除污程序。"},{"en":"Visitors to a clean laboratory may proceed to decontamination before entering.","zh":"進入潔淨實驗室前，訪客可能要前往除污程序。"},{"en":"This phrase sounds official and makes the station feel strict and dangerous.","zh":"這個短語聽起來官方，令研究站感覺嚴格又危險。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"decontamination","meaning":"除污；消毒程序","examples":[{"en":"Chris was ordered to enter decontamination.","zh":"Chris 被命令進入除污程序。"},{"en":"Decontamination is the process of removing germs, chemicals, or dangerous material.","zh":"decontamination 是清除細菌、化學物或危險物質的程序。"},{"en":"Doctors may use decontamination after contact with infectious disease.","zh":"醫生接觸傳染病後可能會使用除污程序。"},{"en":"Decontamination protects others by stopping harmful material from spreading.","zh":"除污程序透過阻止有害物質擴散來保護其他人。"},{"en":"In the story, decontamination suggests the station fears contamination from outside or inside.","zh":"在故事中，除污程序暗示研究站害怕來自外面或裏面的污染。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"is expecting you","meaning":"正在等你","examples":[{"en":"Dr Soren is expecting Chris.","zh":"Soren 博士正在等 Chris。"},{"en":"Is expecting you means someone knows you are coming and is waiting for you.","zh":"is expecting you 指某人知道你會來，並正在等你。"},{"en":"The receptionist said the manager is expecting you in Room 3.","zh":"接待員說經理正在三號房等你。"},{"en":"If a host is expecting you, you should arrive on time.","zh":"如果主人正在等你，你應該準時到達。"},{"en":"In the story, the phrase shows Chris’s arrival has already been prepared for.","zh":"在故事中，這個短語顯示 Chris 的到來早已被安排好。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"calm enough to be human","meaning":"平靜得像人聲","examples":[{"en":"The voice was calm enough to be human.","zh":"那聲音平靜得像人聲。"},{"en":"Calm enough to be human means the voice sounded natural and controlled enough to belong to a person.","zh":"calm enough to be human 指聲音自然而穩定得像屬於一個人。"},{"en":"The emergency operator sounded calm enough to be human, even during the fire.","zh":"即使在火災中，緊急接線員的聲音也平靜得像正常人聲。"},{"en":"A recorded message may be calm enough to be human but still feel artificial.","zh":"錄音訊息可能平靜得像人聲，但仍令人覺得不自然。"},{"en":"In the story, the phrase creates doubt about whether the voice is a person or a machine.","zh":"在故事中，這個短語令人懷疑那聲音到底是人還是機器。"}],"source":"2020 Q8.pdf","sourcePage":7},{"front":"flat enough not to be","meaning":"平板得不像人聲","examples":[{"en":"The voice was flat enough not to be human.","zh":"那聲音平板得不像人聲。"},{"en":"Flat enough not to be means too emotionless or even to seem real.","zh":"flat enough not to be 指太沒有情感或太平直，以致不像真的。"},{"en":"The online lesson voice was flat enough not to be a real teacher.","zh":"網上課堂的聲音平板得不像真正老師。"},{"en":"A reply that is flat enough not to be sincere may make people uncomfortable.","zh":"如果回覆平板得不像真心，可能令人不舒服。"},{"en":"In the story, the voice is both human-like and machine-like, which feels disturbing.","zh":"在故事中，那聲音既像人又像機器，因此令人不安。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"if only because","meaning":"只因為","examples":[{"en":"Chris obeyed, if only because the inner door had locked behind him.","zh":"Chris 服從了，只因為內門已在他身後鎖上。"},{"en":"If only because means for this reason alone, even if there are no other reasons.","zh":"if only because 指單憑這個原因，即使沒有其他理由。"},{"en":"I brought an umbrella, if only because the sky looked dark.","zh":"我帶了雨傘，只因為天空看起來很暗。"},{"en":"She apologised, if only because she wanted the argument to stop.","zh":"她道歉了，只因為她想爭吵停止。"},{"en":"In the story, Chris obeys mainly because he has no way back.","zh":"在故事中，Chris 服從主要是因為他已沒有退路。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"locked behind me","meaning":"在我身後鎖上","examples":[{"en":"The inner door had locked behind Chris.","zh":"內門已在 Chris 身後鎖上。"},{"en":"Locked behind me means a door closed and locked after I passed through it.","zh":"locked behind me 指我走過門後，門在我身後關上並上鎖。"},{"en":"The hotel door locked behind me before I realised my key was inside.","zh":"酒店房門在我身後鎖上，我才發現房匙在裏面。"},{"en":"If a door locks behind you in a strange building, you may feel trapped.","zh":"如果陌生建築物裏的門在你身後鎖上，你可能會覺得被困。"},{"en":"In the story, the locked door removes Chris’s freedom to leave.","zh":"在故事中，上鎖的門奪走了 Chris 離開的自由。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"chamber","meaning":"小室；艙","examples":[{"en":"The chamber hissed with antiseptic vapour.","zh":"小室裏充滿消毒蒸氣，發出嘶嘶聲。"},{"en":"A chamber is a small enclosed room or space used for a special purpose.","zh":"chamber 是用於特定目的的小型封閉房間或空間。"},{"en":"The patient entered a pressure chamber for medical treatment.","zh":"病人進入壓力艙接受醫療治療。"},{"en":"A chamber can feel uncomfortable if the door closes tightly behind you.","zh":"如果門在你身後緊緊關上，小室可能令人不舒服。"},{"en":"In the station, the chamber is used for decontamination and feels controlled.","zh":"在研究站裏，這個小室用於除污，感覺受到控制。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"hissed with","meaning":"發出嘶嘶聲並充滿","examples":[{"en":"The chamber hissed with antiseptic vapour.","zh":"小室發出嘶嘶聲並充滿消毒蒸氣。"},{"en":"Hissed with means filled with something that made a sharp “sss” sound.","zh":"hissed with 指充滿某物並發出尖細的「嘶嘶」聲。"},{"en":"The kettle hissed with steam when the water boiled.","zh":"水煮沸時，水壺發出嘶嘶聲並冒着蒸氣。"},{"en":"A pipe hissed with escaping gas, so everyone left the room.","zh":"管道發出嘶嘶聲並洩出氣體，所以所有人離開房間。"},{"en":"In the story, the hissing sound makes the decontamination chamber feel threatening.","zh":"在故事中，嘶嘶聲令除污小室感覺有威脅。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"antiseptic vapour","meaning":"消毒蒸氣","examples":[{"en":"The chamber filled with antiseptic vapour.","zh":"小室充滿消毒蒸氣。"},{"en":"Antiseptic vapour is a mist or gas used to kill germs.","zh":"antiseptic vapour 是用來殺菌的霧氣或氣體。"},{"en":"The clinic used antiseptic vapour to clean the room after a serious infection.","zh":"診所在嚴重感染後使用消毒蒸氣清潔房間。"},{"en":"Too much antiseptic vapour can sting the eyes or throat.","zh":"太多消毒蒸氣可能刺痛眼睛或喉嚨。"},{"en":"In the story, antiseptic vapour makes the station feel medical and unsafe at the same time.","zh":"在故事中，消毒蒸氣令研究站同時感覺醫療化和不安全。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"in case of","meaning":"如遇到","examples":[{"en":"In case of auditory hallucination, report immediately.","zh":"如遇到幻聽，請立即報告。"},{"en":"In case of means if a particular problem or situation happens.","zh":"in case of 指如果某種問題或情況發生。"},{"en":"In case of fire, leave the building by the nearest exit.","zh":"如遇火警，請由最近出口離開建築物。"},{"en":"In case of heavy rain, the school picnic will move indoors.","zh":"如遇大雨，學校旅行將移到室內。"},{"en":"This phrase is often used in warnings, notices, and safety instructions.","zh":"這個短語常用於警告、告示和安全指示。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"auditory hallucination","meaning":"幻聽","examples":[{"en":"The notice warned about auditory hallucination.","zh":"告示警告有關幻聽。"},{"en":"Auditory hallucination means hearing sounds or voices that are not really there.","zh":"auditory hallucination 指聽到實際上不存在的聲音或人聲。"},{"en":"A patient experiencing auditory hallucination may hear someone calling their name in an empty room.","zh":"經歷幻聽的病人可能在空房間裏聽到有人叫自己的名字。"},{"en":"Stress, illness, or lack of sleep can sometimes be linked to auditory hallucination.","zh":"壓力、疾病或睡眠不足有時可能與幻聽有關。"},{"en":"In the story, this warning makes the station feel psychologically dangerous.","zh":"在故事中，這個警告令研究站感覺有心理上的危險。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"report immediately","meaning":"立即報告","examples":[{"en":"Anyone experiencing auditory hallucination should report immediately.","zh":"任何經歷幻聽的人都應立即報告。"},{"en":"Report immediately means tell the person in charge at once.","zh":"report immediately 指立刻告訴負責人。"},{"en":"Students should report immediately if they smell gas in the science room.","zh":"如果學生在實驗室聞到煤氣味，應立即報告。"},{"en":"Workers must report immediately when safety equipment is broken.","zh":"當安全設備損壞，工人必須立即報告。"},{"en":"This phrase appears in rules because delay can make danger worse.","zh":"這個短語出現在規則中，因為拖延可能令危險惡化。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"unfamiliar voices","meaning":"陌生聲音","examples":[{"en":"The notice warned people not to answer unfamiliar voices.","zh":"告示警告人們不要回答陌生聲音。"},{"en":"Unfamiliar voices are voices you do not recognise.","zh":"unfamiliar voices 是你不認得的聲音。"},{"en":"A child should be careful if unfamiliar voices call from outside the house.","zh":"如果屋外有陌生聲音呼叫，孩子應小心。"},{"en":"Hearing unfamiliar voices in a locked building may make people feel unsafe.","zh":"在上鎖建築物裏聽到陌生聲音，可能令人感到不安全。"},{"en":"In the story, the warning suggests that answering a voice could be dangerous.","zh":"在故事中，這個警告暗示回答聲音可能有危險。"}],"source":"2020 Q8.pdf","sourcePage":8},{"front":"familiar voices after 00:00","meaning":"午夜後熟悉的聲音","examples":[{"en":"The notice warned people not to answer familiar voices after 00:00.","zh":"告示警告人們不要回答午夜後熟悉的聲音。"},{"en":"Familiar voices after 00:00 means voices you recognise, but heard after midnight.","zh":"familiar voices after 00:00 指午夜後聽到的、你認得的聲音。"},{"en":"A rule about familiar voices after 00:00 is frightening because familiar things should feel safe.","zh":"關於午夜後熟悉聲音的規則很可怕，因為熟悉的東西本應令人安心。"},{"en":"If someone hears familiar voices after 00:00 in an empty corridor, they may question what is real.","zh":"如果有人在空走廊裏聽到午夜後熟悉的聲音，他可能會懷疑甚麼是真的。"},{"en":"In the story, this warning makes midnight feel like a dangerous boundary.","zh":"在故事中，這個警告令午夜像一條危險界線。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"paid to be curious","meaning":"以好奇心為工作","examples":[{"en":"Journalists are paid to be curious.","zh":"記者是以好奇心為工作的人。"},{"en":"Paid to be curious means someone’s job requires them to ask questions and seek answers.","zh":"paid to be curious 指某人的工作要求他提問並尋找答案。"},{"en":"Reporters are paid to be curious about decisions that powerful people want to hide.","zh":"記者以好奇心為工作，追問有權勢者想隱藏的決定。"},{"en":"A scientist is also paid to be curious, because research begins with questions.","zh":"科學家也是以好奇心為工作的人，因為研究始於問題。"},{"en":"In the story, Chris’s curiosity pushes him forward even when he feels afraid.","zh":"在故事中，Chris 的好奇心即使在害怕時也推動他前進。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"made me wish","meaning":"令我希望","examples":[{"en":"The notice made Chris wish he had chosen advertising instead.","zh":"那告示令 Chris 希望自己改為選擇廣告業。"},{"en":"Made me wish means caused me to want something different from reality.","zh":"made me wish 指某事令我想要與現實不同的情況。"},{"en":"The difficult exam made me wish I had studied earlier.","zh":"困難的考試令我希望自己早點溫習。"},{"en":"A terrible bus ride can make you wish you had taken the train.","zh":"糟糕的巴士旅程可以令你希望自己坐了火車。"},{"en":"In the story, the warning makes Chris regret his dangerous career choice for a moment.","zh":"在故事中，那警告令 Chris 一時後悔選了危險的職業。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"briefly and shamefully","meaning":"短暫而羞愧地","examples":[{"en":"Chris briefly and shamefully wished he had chosen advertising.","zh":"Chris 短暫而羞愧地希望自己選了廣告業。"},{"en":"Briefly and shamefully means for a short time and with a feeling of embarrassment or guilt.","zh":"briefly and shamefully 指短時間地，並帶着尷尬或內疚。"},{"en":"I briefly and shamefully hoped the meeting would be cancelled.","zh":"我短暫而羞愧地希望會議取消。"},{"en":"She briefly and shamefully felt glad that someone else had to answer the hard question.","zh":"她短暫而羞愧地為別人要回答難題而感到高興。"},{"en":"This phrase shows a private thought the person quickly judges as weak.","zh":"這個短語顯示一個人很快便覺得軟弱的私下想法。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"chosen advertising instead","meaning":"改為選擇廣告業","examples":[{"en":"Chris wished he had chosen advertising instead.","zh":"Chris 希望自己改為選擇廣告業。"},{"en":"Chosen advertising instead means selected a job in advertising rather than the path actually taken.","zh":"chosen advertising instead 指選擇廣告工作，而不是實際走上的道路。"},{"en":"After one dangerous assignment, the reporter joked that he should have chosen advertising instead.","zh":"經歷一次危險任務後，記者開玩笑說自己本該改為選擇廣告業。"},{"en":"Someone may wish they had chosen advertising instead when creative office work seems safer.","zh":"當創意辦公室工作看來較安全時，有人可能希望自己改為選擇廣告業。"},{"en":"In the story, this phrase contrasts a safe career with Chris’s frightening investigation.","zh":"在故事中，這個短語把安全職業與 Chris 可怕的調查形成對比。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"common room","meaning":"公共休息室","examples":[{"en":"Dr Elias Soren met Chris in the common room.","zh":"Elias Soren 博士在公共休息室見 Chris。"},{"en":"A common room is a shared room where people in a building can sit, talk, or rest.","zh":"common room 是建築物裏供人坐下、交談或休息的共用房間。"},{"en":"Students gathered in the common room after dinner to play cards.","zh":"學生晚飯後聚在公共休息室打牌。"},{"en":"In a research station, a common room may be the only place where workers relax together.","zh":"在研究站裏，公共休息室可能是工作人員唯一一起放鬆的地方。"},{"en":"In the story, meeting in the common room should feel normal, but the mood is tense.","zh":"在故事中，在公共休息室見面本應平常，但氣氛緊張。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"hollow-eyed","meaning":"眼窩深陷的","examples":[{"en":"Dr Soren was tall and hollow-eyed.","zh":"Soren 博士身材高大，眼窩深陷。"},{"en":"Hollow-eyed means having sunken eyes, often because of tiredness, illness, or fear.","zh":"hollow-eyed 指眼睛凹陷，常因疲倦、疾病或恐懼造成。"},{"en":"After three nights without sleep, the nurse looked hollow-eyed.","zh":"三晚沒睡後，那名護士看起來眼窩深陷。"},{"en":"A hollow-eyed person may seem exhausted before they say anything.","zh":"眼窩深陷的人未說話前已可能顯得極度疲憊。"},{"en":"In the story, Soren’s hollow-eyed face suggests stress and sleeplessness.","zh":"在故事中，Soren 眼窩深陷的臉暗示壓力和失眠。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"wrapped in","meaning":"裹着","examples":[{"en":"Dr Soren was wrapped in two sweaters.","zh":"Soren 博士裹着兩件毛衣。"},{"en":"Wrapped in means covered or surrounded by clothing, cloth, or material.","zh":"wrapped in 指被衣物、布料或材料包住或圍住。"},{"en":"The baby was wrapped in a warm blanket before leaving the hospital.","zh":"嬰兒離開醫院前被裹在溫暖的毛氈裏。"},{"en":"Someone wrapped in two coats may still feel cold in severe weather.","zh":"在嚴寒天氣中，裹着兩件外套的人仍可能覺得冷。"},{"en":"In the story, Soren wearing two sweaters indoors suggests something is wrong.","zh":"在故事中，Soren 在室內穿兩件毛衣，暗示有事不對。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"systems engineer","meaning":"系統工程師","examples":[{"en":"Lena Cho was a young systems engineer.","zh":"Lena Cho 是一名年輕的系統工程師。"},{"en":"A systems engineer designs, manages, or fixes complex technical systems.","zh":"systems engineer 是設計、管理或維修複雜技術系統的人。"},{"en":"A systems engineer may check computers, power, alarms, and communication networks.","zh":"系統工程師可能檢查電腦、電力、警報和通訊網絡。"},{"en":"If a station loses power, a systems engineer may be the person who finds the fault.","zh":"如果研究站停電，系統工程師可能是找出故障的人。"},{"en":"In the story, Lena’s job connects her to the station’s technology and secrets.","zh":"在故事中，Lena 的工作把她與研究站的科技和秘密連在一起。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"kept rubbing","meaning":"不停揉","examples":[{"en":"Lena kept rubbing her left wrist.","zh":"Lena 不停揉她的左手腕。"},{"en":"Kept rubbing means continued to move a hand back and forth over something.","zh":"kept rubbing 指持續用手來回摩擦某處。"},{"en":"The child kept rubbing his eyes because he was tired.","zh":"孩子因為疲倦而不停揉眼睛。"},{"en":"A person may keep rubbing a sore wrist after carrying heavy bags.","zh":"一個人拿了重袋後，可能不停揉疼痛的手腕。"},{"en":"In the story, Lena’s repeated rubbing suggests anxiety or pain.","zh":"在故事中，Lena 重複揉手腕暗示焦慮或痛楚。"}],"source":"2020 Q8.pdf","sourcePage":9},{"front":"medic","meaning":"醫護人員","examples":[{"en":"Dr Malek was an older medic.","zh":"Malek 博士是一名年長的醫護人員。"},{"en":"A medic is a person trained to give medical help, especially in emergencies or remote places.","zh":"medic 是受過訓練、能提供醫療協助的人，特別是在緊急或偏遠地方。"},{"en":"The school medic cleaned the student’s cut and checked for swelling.","zh":"學校醫護人員清潔學生的傷口並檢查腫脹。"},{"en":"In a research station, a medic may treat injuries when hospitals are far away.","zh":"在研究站裏，當醫院很遠時，醫護人員可能要處理傷患。"},{"en":"In the story, the medic should bring safety, but his strange smile creates doubt.","zh":"在故事中，醫護人員本應帶來安全感，但他奇怪的微笑令人懷疑。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"arrived late and left early","meaning":"來得遲、消失得快","examples":[{"en":"Dr Malek’s smile arrived late and left early.","zh":"Malek 博士的微笑來得遲、消失得快。"},{"en":"Arrived late and left early describes a smile that appears slowly and disappears quickly.","zh":"arrived late and left early 形容微笑慢慢出現，又很快消失。"},{"en":"Her smile arrived late and left early when she heard the bad news.","zh":"她聽到壞消息時，微笑來得遲、消失得快。"},{"en":"A smile that arrives late and leaves early may not feel sincere.","zh":"來得遲、消失得快的微笑可能令人覺得不真誠。"},{"en":"In the story, Malek’s smile suggests he is hiding fear or distrust.","zh":"在故事中，Malek 的微笑暗示他正在隱藏恐懼或不信任。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"originally","meaning":"原本","examples":[{"en":"There were twelve scientists originally.","zh":"原本有十二名科學家。"},{"en":"Originally means at the beginning, before later changes happened.","zh":"originally 指在最初，在後來變化發生之前。"},{"en":"The club originally had twenty members, but only twelve stayed.","zh":"那個社團原本有二十名成員，但只有十二人留下。"},{"en":"A plan may change completely from what was originally agreed.","zh":"一個計劃可能與原本同意的內容完全不同。"},{"en":"In the story, originally shows how many people have already been lost.","zh":"在故事中，originally 顯示已有多少人失去。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"took out my recorder","meaning":"拿出錄音機","examples":[{"en":"Chris took out his recorder before asking questions.","zh":"Chris 在提問前拿出錄音機。"},{"en":"Took out my recorder means removed a recording device so a conversation could be recorded.","zh":"took out my recorder 指拿出錄音設備，以便記錄談話。"},{"en":"The journalist took out her recorder before interviewing the witness.","zh":"記者在訪問目擊者前拿出錄音機。"},{"en":"A student may take out a recorder during a lecture to review the lesson later.","zh":"學生可能在講座中拿出錄音機，方便之後重溫。"},{"en":"In the story, the recorder shows Chris is working as a journalist, not just a visitor.","zh":"在故事中，錄音機顯示 Chris 是以記者身份工作，而不只是訪客。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"the file is outdated","meaning":"文件已過時","examples":[{"en":"Soren said the file was outdated.","zh":"Soren 說文件已過時。"},{"en":"If a file is outdated, the information in it is no longer current or correct.","zh":"如果 a file is outdated，就是文件中的資料已不再最新或正確。"},{"en":"The school’s emergency file is outdated because several phone numbers have changed.","zh":"學校的緊急聯絡文件已過時，因為幾個電話號碼已改變。"},{"en":"Using an outdated file can lead to wrong decisions.","zh":"使用過時文件可能導致錯誤決定。"},{"en":"In the story, the outdated file means Chris knows less than he thinks.","zh":"在故事中，過時文件表示 Chris 知道的比他以為的少。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"no sooner had… than…","meaning":"剛一……就……","examples":[{"en":"No sooner had Soren said it than the overhead lights dimmed.","zh":"Soren 剛一說完，頭頂燈就變暗了。"},{"en":"No sooner had A happened than B happened means B happened immediately after A.","zh":"no sooner had A happened than B happened 指 A 剛發生，B 就立刻發生。"},{"en":"No sooner had the teacher left than the students began talking.","zh":"老師剛一離開，學生就開始說話。"},{"en":"No sooner had I opened the door than the alarm started ringing.","zh":"我剛一打開門，警報就開始響起。"},{"en":"This pattern is useful for showing a sudden event that follows another event at once.","zh":"這個句式適合表示一件事剛發生，另一件事立刻跟着發生。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"overhead lights","meaning":"頭頂燈","examples":[{"en":"The overhead lights dimmed.","zh":"頭頂燈變暗了。"},{"en":"Overhead lights are lights fixed above people, usually on the ceiling.","zh":"overhead lights 是固定在人們上方、通常在天花板上的燈。"},{"en":"The overhead lights in the classroom were too bright during the presentation.","zh":"課室的頭頂燈在匯報時太光。"},{"en":"If overhead lights flicker in a hospital, staff may check the power supply.","zh":"如果醫院的頭頂燈閃爍，員工可能會檢查供電。"},{"en":"In the story, the overhead lights changing makes everyone look up and worry.","zh":"在故事中，頭頂燈的變化令所有人抬頭並擔心。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"dimmed","meaning":"變暗","examples":[{"en":"The overhead lights dimmed suddenly.","zh":"頭頂燈突然變暗。"},{"en":"Dimmed means became less bright.","zh":"dimmed 指變得沒有那麼明亮。"},{"en":"The cinema lights dimmed before the film began.","zh":"電影開始前，戲院燈光變暗。"},{"en":"When the battery was low, the screen dimmed to save power.","zh":"電池電量低時，螢幕會變暗以節省電力。"},{"en":"In the story, the lights dimming suddenly suggests a problem or warning.","zh":"在故事中，燈突然變暗暗示問題或警告。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"beyond the wall","meaning":"在牆後某處","examples":[{"en":"Somewhere beyond the wall, the ice groaned.","zh":"在牆後某處，冰發出呻吟。"},{"en":"Beyond the wall means on the other side of the wall, outside what you can see.","zh":"beyond the wall 指在牆的另一邊，在你看不見的地方。"},{"en":"The children heard music beyond the wall but could not see the party.","zh":"孩子們聽到牆後有音樂，但看不見派對。"},{"en":"A noise beyond the wall can feel mysterious because its source is hidden.","zh":"牆後的聲音可能令人感到神秘，因為來源被遮住。"},{"en":"In the story, the ice beyond the wall feels close but unreachable.","zh":"在故事中，牆後的冰感覺很近，卻無法接觸。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"gave a long, animal groan","meaning":"發出長長的獸性呻吟","examples":[{"en":"The ice gave a long, animal groan.","zh":"冰發出長長的獸性呻吟。"},{"en":"Gave a long, animal groan means made a deep drawn-out sound like a living creature.","zh":"gave a long, animal groan 指發出像生物一樣低沉而拖長的聲音。"},{"en":"The old ship gave a long, animal groan as it moved in the storm.","zh":"舊船在暴風中移動時，發出長長的獸性呻吟。"},{"en":"A building may give a long groan when strong wind pushes against it.","zh":"強風壓向建築物時，它可能發出長長的呻吟。"},{"en":"In the story, the phrase makes the ice seem alive and suffering.","zh":"在故事中，這個短語令冰看似活着且正在受苦。"}],"source":"2020 Q8.pdf","sourcePage":10},{"front":"whispered something","meaning":"低聲說了些話","examples":[{"en":"Dr Malek whispered something Chris did not catch.","zh":"Malek 博士低聲說了些 Chris 沒聽清楚的話。"},{"en":"Whispered something means said something very quietly.","zh":"whispered something 指非常小聲地說了某些話。"},{"en":"The student whispered something to her friend during the exam and got warned.","zh":"學生在考試中低聲對朋友說話，結果被警告。"},{"en":"People may whisper something when they do not want others to hear.","zh":"當人們不想讓其他人聽見時，可能會低聲說話。"},{"en":"In the story, the whisper creates suspicion because Chris cannot hear it clearly.","zh":"在故事中，低語製造懷疑，因為 Chris 聽不清楚。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"I did not catch","meaning":"我沒有聽清楚","examples":[{"en":"Dr Malek whispered something Chris did not catch.","zh":"Malek 博士低聲說了些 Chris 沒有聽清楚的話。"},{"en":"I did not catch means I did not hear or understand what was said.","zh":"I did not catch 指我沒有聽到或理解剛才說的話。"},{"en":"Could you repeat that? I did not catch the last word.","zh":"你可以重複嗎？我沒有聽清楚最後一個字。"},{"en":"In a noisy restaurant, customers may not catch what the waiter says.","zh":"在嘈雜餐廳裏，顧客可能聽不清楚侍應說的話。"},{"en":"This phrase is useful when sound is unclear or information is missed.","zh":"當聲音不清楚或資料被錯過時，這個短語很有用。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"listen carefully","meaning":"仔細聽","examples":[{"en":"Soren told Chris to listen carefully.","zh":"Soren 叫 Chris 仔細聽。"},{"en":"Listen carefully means pay close attention to what is being said or heard.","zh":"listen carefully 指專心注意正在說或聽到的內容。"},{"en":"Students should listen carefully before answering instructions in an exam.","zh":"學生在考試中回答指示前應仔細聽。"},{"en":"If a patient describes pain, a doctor must listen carefully to avoid mistakes.","zh":"如果病人描述痛楚，醫生必須仔細聽以避免錯誤。"},{"en":"In the story, Soren asks Chris to listen carefully because the details matter.","zh":"在故事中，Soren 要 Chris 仔細聽，因為細節很重要。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"disappeared from","meaning":"從……消失","examples":[{"en":"Dr Iversen disappeared from the weather tower.","zh":"Iversen 博士從氣象塔消失了。"},{"en":"Disappeared from means was no longer present in a place, often suddenly or mysteriously.","zh":"disappeared from 指某人或某物不再在某地，常是突然或神秘地。"},{"en":"The keys disappeared from the kitchen table before anyone left the house.","zh":"在任何人離家前，鑰匙從廚房桌上消失了。"},{"en":"If a child disappears from school, teachers must contact the family immediately.","zh":"如果孩子從學校消失，老師必須立即聯絡家人。"},{"en":"In the story, each disappearance from a different place deepens the mystery.","zh":"在故事中，每次從不同地方消失都加深謎團。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"weather tower","meaning":"氣象塔","examples":[{"en":"Dr Iversen disappeared from the weather tower.","zh":"Iversen 博士從氣象塔消失了。"},{"en":"A weather tower is a structure used to measure wind, temperature, and other weather conditions.","zh":"weather tower 是用來測量風、溫度和其他天氣情況的結構。"},{"en":"Scientists climb the weather tower to repair sensors after storms.","zh":"暴風後，科學家爬上氣象塔維修感應器。"},{"en":"If someone disappears from a weather tower, investigators check ladders, cameras, and weather records.","zh":"如果有人從氣象塔消失，調查員會檢查梯子、攝影機和天氣紀錄。"},{"en":"In the Arctic, a weather tower is exposed to wind, ice, and danger.","zh":"在北極，氣象塔暴露於風、冰和危險之中。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"locked laboratory","meaning":"上鎖的實驗室","examples":[{"en":"Professor Hale disappeared from his locked laboratory.","zh":"Hale 教授從他上鎖的實驗室消失了。"},{"en":"A locked laboratory is a lab secured so others cannot enter without permission.","zh":"locked laboratory 是已上鎖、別人未經許可不能進入的實驗室。"},{"en":"A locked laboratory may contain chemicals, machines, or private research records.","zh":"上鎖的實驗室可能存放化學品、機器或私人研究紀錄。"},{"en":"If someone vanishes from a locked laboratory, the locked door makes the case harder to explain.","zh":"如果有人從上鎖的實驗室消失，上鎖的門令案件更難解釋。"},{"en":"In the story, the locked laboratory suggests the disappearance should have been impossible.","zh":"在故事中，上鎖的實驗室暗示失蹤本應不可能。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"hydroponic bay","meaning":"水耕栽培艙","examples":[{"en":"Chen disappeared from the hydroponic bay.","zh":"Chen 從水耕栽培艙消失了。"},{"en":"A hydroponic bay is an area where plants are grown in water instead of soil.","zh":"hydroponic bay 是用水而不是泥土種植植物的區域。"},{"en":"A space station may use a hydroponic bay to grow fresh vegetables.","zh":"太空站可能使用水耕栽培艙種植新鮮蔬菜。"},{"en":"If the hydroponic bay fails, people in a remote station may lose fresh food.","zh":"如果水耕栽培艙失效，偏遠研究站的人可能失去新鮮食物。"},{"en":"In the story, even a practical growing area becomes part of the mystery.","zh":"在故事中，連實用的種植區也成為謎團的一部分。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"stopped sleeping alone","meaning":"不再單獨睡覺","examples":[{"en":"After Chen vanished, they stopped sleeping alone.","zh":"Chen 消失後，他們不再單獨睡覺。"},{"en":"Stopped sleeping alone means they no longer slept by themselves.","zh":"stopped sleeping alone 指他們不再自己一個人睡覺。"},{"en":"After the burglary, the children stopped sleeping alone and shared one room.","zh":"入屋盜竊後，孩子們不再單獨睡覺，而是共用一個房間。"},{"en":"People may stop sleeping alone when fear makes them feel safer in groups.","zh":"當恐懼令人在群體中更有安全感，他們可能不再單獨睡覺。"},{"en":"In the story, this decision shows the scientists are terrified.","zh":"在故事中，這個決定顯示科學家們非常害怕。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"it did not help","meaning":"這也沒有用","examples":[{"en":"They stopped sleeping alone, but it did not help.","zh":"他們不再單獨睡覺，但這也沒有用。"},{"en":"It did not help means the action did not solve the problem or improve the situation.","zh":"it did not help 指某個做法沒有解決問題或改善情況。"},{"en":"I drank water for my headache, but it did not help.","zh":"我為了頭痛喝了水，但這也沒有用。"},{"en":"The company changed the poster, but it did not help sales.","zh":"公司換了海報，但這對銷售也沒有用。"},{"en":"In the story, even staying together cannot stop the disappearances.","zh":"在故事中，即使待在一起也阻止不了失蹤。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"went missing","meaning":"失蹤","examples":[{"en":"Anika went missing from the infirmary.","zh":"Anika 從醫務室失蹤了。"},{"en":"Went missing means disappeared and could not be found.","zh":"went missing 指消失並找不到。"},{"en":"A child went missing at the beach, so lifeguards began searching immediately.","zh":"一個孩子在海灘失蹤，救生員立即開始搜索。"},{"en":"If important files go missing, the office may check cameras and computer logs.","zh":"如果重要文件失蹤，辦公室可能會檢查攝影機和電腦紀錄。"},{"en":"In the story, Anika going missing proves the danger is still active.","zh":"在故事中，Anika 失蹤證明危險仍在發生。"}],"source":"2020 Q8.pdf","sourcePage":11},{"front":"infirmary","meaning":"醫務室","examples":[{"en":"Anika went missing from the infirmary.","zh":"Anika 從醫務室失蹤了。"},{"en":"An infirmary is a small medical room in a school, camp, ship, or station.","zh":"infirmary 是學校、營地、船或研究站中的小型醫療房間。"},{"en":"The injured student rested in the infirmary until her parents arrived.","zh":"受傷學生在醫務室休息，直到父母到達。"},{"en":"In a remote station, the infirmary may be the only place for medical care.","zh":"在偏遠研究站裏，醫務室可能是唯一提供醫療照顧的地方。"},{"en":"In the story, disappearing from the infirmary is shocking because it should be supervised.","zh":"在故事中，從醫務室消失令人震驚，因為那裏本應有人看守。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"stood outside","meaning":"站在外面","examples":[{"en":"Malek stood outside the infirmary.","zh":"Malek 站在醫務室外面。"},{"en":"Stood outside means remained standing outside a place rather than entering it.","zh":"stood outside 指站在某地外面，而不是進入裏面。"},{"en":"The parent stood outside the classroom while waiting for the teacher.","zh":"家長站在課室外面等老師。"},{"en":"A guard may stand outside a room to make sure nobody enters.","zh":"守衛可能站在房間外面，確保沒有人進入。"},{"en":"In the story, Malek standing outside makes Anika’s disappearance seem impossible.","zh":"在故事中，Malek 站在外面，令 Anika 的失蹤看似不可能。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"that is impossible","meaning":"那是不可能的","examples":[{"en":"Chris said that Anika’s disappearance was impossible.","zh":"Chris 說 Anika 的失蹤是不可能的。"},{"en":"That is impossible means something cannot happen according to normal facts or rules.","zh":"that is impossible 指某事按正常事實或規則不可能發生。"},{"en":"The teacher said it was impossible for the homework to be marked before anyone submitted it.","zh":"老師說，在任何人交功課前就批改完是不可能的。"},{"en":"A locked room mystery feels frightening because people keep saying, “That is impossible.”","zh":"密室謎案令人害怕，因為人們不斷說：「那是不可能的。」"},{"en":"In the story, the impossible event forces Chris to question reality.","zh":"在故事中，不可能的事件迫使 Chris 質疑現實。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"so was","meaning":"……也是","examples":[{"en":"Soren said the first disappearance was impossible too.","zh":"Soren 說第一次失蹤也是不可能的。"},{"en":"So was means the same description is true of another person or thing.","zh":"so was 指同一描述也適用於另一人或另一事物。"},{"en":"The second answer was wrong, and so was the first.","zh":"第二個答案是錯的，第一個也是。"},{"en":"Her room was cold, and so was the hallway outside.","zh":"她的房間很冷，外面的走廊也是。"},{"en":"In the story, Soren means the first disappearance was also impossible.","zh":"在故事中，Soren 的意思是第一次失蹤也是不可能的。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"the trouble with fear is that","meaning":"恐懼的問題在於","examples":[{"en":"The trouble with fear is that it can look like madness.","zh":"恐懼的問題在於，它起初可以看起來像瘋狂。"},{"en":"The trouble with fear is that introduces a problem caused by fear.","zh":"the trouble with fear is that 用來引出恐懼造成的問題。"},{"en":"The trouble with fear is that it can make people avoid useful help.","zh":"恐懼的問題在於，它可能令人避開有用的幫助。"},{"en":"The trouble with fear is that it may turn small doubts into big arguments.","zh":"恐懼的問題在於，它可能把小小疑慮變成大爭吵。"},{"en":"In the story, this phrase explains why real danger may first be mistaken for madness.","zh":"在故事中，這個短語解釋為何真正危險起初可能被誤認為瘋狂。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"look like madness","meaning":"看起來像瘋狂","examples":[{"en":"Fear can look like madness at first.","zh":"恐懼起初可以看起來像瘋狂。"},{"en":"Look like madness means seem irrational, extreme, or mentally unstable.","zh":"look like madness 指看似不理性、極端或精神不穩。"},{"en":"A person warning about a danger nobody else sees may look like madness.","zh":"一個人警告別人看不見的危險時，可能看起來像瘋狂。"},{"en":"Panic can look like madness when people shout and run without explaining why.","zh":"當人們不解釋原因就大叫奔跑，恐慌可能看起來像瘋狂。"},{"en":"In the story, fear looks like madness until evidence proves it is reasonable.","zh":"在故事中，恐懼看起來像瘋狂，直到證據證明它是合理的。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"until the evidence starts","meaning":"直到證據開始","examples":[{"en":"Fear looks like madness until the evidence starts breathing down your neck.","zh":"恐懼看起來像瘋狂，直到證據開始緊逼着你。"},{"en":"Until the evidence starts means up to the point when proof begins to appear or become impossible to ignore.","zh":"until the evidence starts 指直到證據開始出現或變得無法忽視。"},{"en":"A rumour seems silly until the evidence starts showing up in official records.","zh":"謠言看似荒謬，直到證據開始出現在官方紀錄中。"},{"en":"People may ignore a leak until the evidence starts dripping from the ceiling.","zh":"人們可能忽視漏水，直到證據開始從天花板滴下來。"},{"en":"This phrase shows the moment when doubt changes into proof.","zh":"這個短語顯示懷疑轉變成證據的時刻。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"breathing down your neck","meaning":"緊逼着你；迫在眉睫","examples":[{"en":"The evidence started breathing down Chris’s neck.","zh":"證據開始緊逼着 Chris。"},{"en":"Breathing down your neck means being very close and creating pressure or fear.","zh":"breathing down your neck 指某事非常接近，造成壓力或恐懼。"},{"en":"With the deadline breathing down her neck, she finally finished the report.","zh":"截止日期緊逼着她時，她終於完成報告。"},{"en":"A competitor breathing down your neck can force you to improve quickly.","zh":"競爭對手緊逼着你，可能迫使你快速改善。"},{"en":"In the story, the evidence feels so close that Chris cannot ignore it.","zh":"在故事中，證據近得令 Chris 無法忽視。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"security footage","meaning":"保安錄影片段","examples":[{"en":"Chris asked for the security footage.","zh":"Chris 要求查看保安錄影片段。"},{"en":"Security footage is video recorded by security cameras.","zh":"security footage 是保安攝影機拍下的影片。"},{"en":"The shop owner checked the security footage to see who broke the window.","zh":"店主查看保安錄影片段，看是誰打破窗戶。"},{"en":"Security footage can prove where someone was at a certain time.","zh":"保安錄影片段可以證明某人在某個時間的位置。"},{"en":"In the story, the footage should explain the disappearance but instead makes it stranger.","zh":"在故事中，錄影片段本應解釋失蹤，卻令事情更奇怪。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"face tightened","meaning":"臉色繃緊","examples":[{"en":"Soren’s face tightened when Chris asked for the footage.","zh":"Chris 要求查看錄像時，Soren 的臉色繃緊。"},{"en":"Face tightened means the muscles in someone’s face became tense, usually because of fear, anger, or worry.","zh":"face tightened 指臉部肌肉變得緊繃，通常因恐懼、憤怒或擔心。"},{"en":"The manager’s face tightened when she saw the missing money.","zh":"經理看到不見了的金錢時，臉色繃緊。"},{"en":"A person’s face may tighten before they give bad news.","zh":"一個人在說壞消息前，臉色可能會繃緊。"},{"en":"In the story, Soren’s reaction shows the footage is disturbing.","zh":"在故事中，Soren 的反應顯示那段錄像令人不安。"}],"source":"2020 Q8.pdf","sourcePage":12},{"front":"led me to","meaning":"帶我到","examples":[{"en":"Soren led Chris to the control room.","zh":"Soren 帶 Chris 到控制室。"},{"en":"Led me to means guided me or took me to a place.","zh":"led me to 指引導我或帶我到某個地方。"},{"en":"The nurse led me to the waiting area after checking my name.","zh":"護士核對我的名字後，帶我到等候區。"},{"en":"A guide led the tourists to the old temple through narrow streets.","zh":"導遊帶遊客穿過窄街到古廟。"},{"en":"In the story, Soren leads Chris toward the evidence.","zh":"在故事中，Soren 帶 Chris 走向證據。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"control room","meaning":"控制室","examples":[{"en":"Soren led Chris to the control room.","zh":"Soren 帶 Chris 到控制室。"},{"en":"A control room is a place where people monitor and manage machines, cameras, or systems.","zh":"control room 是人們監察和管理機器、攝影機或系統的地方。"},{"en":"Airport staff work in a control room to track planes and runway activity.","zh":"機場員工在控制室追蹤飛機和跑道活動。"},{"en":"If alarms appear in the control room, engineers must respond quickly.","zh":"如果控制室出現警報，工程師必須迅速應對。"},{"en":"In the story, the control room holds the station’s recorded secrets.","zh":"在故事中，控制室保存了研究站記錄下來的秘密。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"monitors flickered","meaning":"監視器閃爍","examples":[{"en":"Six monitors flickered in the control room.","zh":"六部監視器在控制室裏閃爍。"},{"en":"Monitors flickered means screens flashed unevenly or changed brightness quickly.","zh":"monitors flickered 指螢幕不均勻地閃光或快速改變亮度。"},{"en":"The old computer monitors flickered whenever the power was weak.","zh":"電力不足時，舊電腦監視器就會閃爍。"},{"en":"Flickering monitors can make a room feel unstable or haunted.","zh":"閃爍的監視器可以令房間感覺不穩定或像鬧鬼。"},{"en":"In the story, the flickering screens add to the uneasy atmosphere.","zh":"在故事中，閃爍的螢幕加深不安氣氛。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"blue half-light","meaning":"半明半暗的藍光","examples":[{"en":"The monitors flickered in the blue half-light.","zh":"監視器在半明半暗的藍光中閃爍。"},{"en":"Blue half-light is dim bluish light that does not fully brighten a room.","zh":"blue half-light 是微弱的藍色光線，不能完全照亮房間。"},{"en":"The hospital corridor looked cold in the blue half-light before dawn.","zh":"黎明前，醫院走廊在半明半暗的藍光中顯得冰冷。"},{"en":"Blue half-light can make faces look pale and tired.","zh":"半明半暗的藍光可以令臉看起來蒼白疲倦。"},{"en":"In the story, the blue half-light makes the control room feel unreal.","zh":"在故事中，半明半暗的藍光令控制室感覺不真實。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"infirmary corridor","meaning":"醫務室走廊","examples":[{"en":"The screen showed the infirmary corridor at 23:59.","zh":"螢幕顯示 23:59 的醫務室走廊。"},{"en":"An infirmary corridor is the hallway outside or near the medical room.","zh":"infirmary corridor 是醫務室外面或附近的走廊。"},{"en":"Nurses moved quietly through the infirmary corridor during the night shift.","zh":"夜班期間，護士安靜地穿過醫務室走廊。"},{"en":"If a camera shows an empty infirmary corridor, investigators can check who passed by.","zh":"如果攝影機顯示空蕩的醫務室走廊，調查員可以查看誰經過。"},{"en":"In the story, the corridor becomes important because Anika disappears nearby.","zh":"在故事中，這條走廊變得重要，因為 Anika 在附近消失。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"in a red parka","meaning":"穿着紅色防寒外套","examples":[{"en":"Anika stood behind the glass door in a red parka.","zh":"Anika 穿着紅色防寒外套，站在玻璃門後。"},{"en":"In a red parka means wearing a warm red hooded coat.","zh":"in a red parka 指穿着一件紅色連帽保暖外套。"},{"en":"The child in a red parka was easy to see against the snow.","zh":"穿着紅色防寒外套的孩子在雪地中特別容易看見。"},{"en":"People wear parkas in freezing weather because they protect against wind and cold.","zh":"人們在嚴寒天氣穿防寒外套，因為它能抵擋風和寒冷。"},{"en":"In the story, the red parka helps viewers identify Anika clearly on the footage.","zh":"在故事中，紅色防寒外套幫助觀眾在錄像中清楚認出 Anika。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"glass door","meaning":"玻璃門","examples":[{"en":"Anika stood behind a glass door.","zh":"Anika 站在一扇玻璃門後。"},{"en":"A glass door is a door made partly or fully of glass, so people can see through it.","zh":"glass door 是部分或全部由玻璃製成、可以看穿的門。"},{"en":"The doctor looked through the glass door before entering the patient’s room.","zh":"醫生進入病房前，先透過玻璃門看進去。"},{"en":"A glass door can make someone visible but still separated from others.","zh":"玻璃門可以令人看得見某人，但仍把人隔開。"},{"en":"In the story, the glass door makes Anika seem close, yet unreachable.","zh":"在故事中，玻璃門令 Anika 感覺很近，卻無法觸及。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"the clock changed to","meaning":"時鐘轉到","examples":[{"en":"The clock changed to 00:00.","zh":"時鐘轉到 00:00。"},{"en":"The clock changed to means the displayed time became a new time.","zh":"the clock changed to 指顯示的時間變成新的時間。"},{"en":"When the clock changed to 08:00, the school gates opened.","zh":"時鐘轉到 08:00 時，校門打開。"},{"en":"The clock changed to midnight just as the power failed.","zh":"時鐘剛轉到午夜，電力就中斷。"},{"en":"In the story, the clock changing to 00:00 marks the dangerous moment.","zh":"在故事中，時鐘轉到 00:00 標示危險時刻。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"went out","meaning":"熄滅","examples":[{"en":"The lights went out for exactly eleven seconds.","zh":"燈熄滅了整整十一秒。"},{"en":"Went out means stopped shining or stopped working.","zh":"went out 指停止發光或停止運作。"},{"en":"The lights went out during the storm, so we used candles.","zh":"暴風期間燈熄滅了，所以我們用了蠟燭。"},{"en":"If the screen goes out, the computer may have lost power.","zh":"如果螢幕熄滅，電腦可能失去電力。"},{"en":"In the story, the lights going out gives the disappearance a short hidden space.","zh":"在故事中，燈熄滅為失蹤提供了一段短暫的隱藏時間。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"for exactly eleven seconds","meaning":"整整十一秒","examples":[{"en":"The lights went out for exactly eleven seconds.","zh":"燈熄滅了整整十一秒。"},{"en":"For exactly eleven seconds means for a precise period of eleven seconds, not more or less.","zh":"for exactly eleven seconds 指精確持續十一秒，不多不少。"},{"en":"The alarm rang for exactly eleven seconds before stopping.","zh":"警報響了整整十一秒才停止。"},{"en":"If a camera fails for exactly eleven seconds, investigators may suspect a planned interruption.","zh":"如果攝影機失效整整十一秒，調查員可能懷疑那是有計劃的中斷。"},{"en":"In the story, the exact timing makes the event feel deliberate.","zh":"在故事中，精確時間令事件感覺像被刻意安排。"}],"source":"2020 Q8.pdf","sourcePage":13},{"front":"when they returned","meaning":"當它們恢復時","examples":[{"en":"When the lights returned, the room was empty.","zh":"當燈光恢復時，房間空無一人。"},{"en":"When they returned means when the lights came back on or became visible again.","zh":"when they returned 指燈光重新亮起或再次可見時。"},{"en":"When the lights returned after the blackout, everyone checked the fridge.","zh":"停電後燈光恢復時，大家檢查雪櫃。"},{"en":"When the streetlights returned, the driver could see the road clearly again.","zh":"街燈恢復時，司機又能清楚看見道路。"},{"en":"In the story, the lights returning reveals that Anika has vanished.","zh":"在故事中，燈光恢復揭示 Anika 已經消失。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"the room was empty","meaning":"房間空無一人","examples":[{"en":"When the lights returned, the room was empty.","zh":"當燈光恢復時，房間空無一人。"},{"en":"The room was empty means nobody was inside the room.","zh":"the room was empty 指房間裏沒有人。"},{"en":"The classroom was empty because all the students had gone to assembly.","zh":"課室空無一人，因為所有學生都去了集會。"},{"en":"If a locked room is empty after someone was seen inside, people will ask how they left.","zh":"如果有人被看見在上鎖房間裏，之後房間卻空無一人，人們會問他如何離開。"},{"en":"In the story, the empty room is the impossible result of the blackout.","zh":"在故事中，空房間是停電後不可能的結果。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"not a door opened","meaning":"沒有任何門打開","examples":[{"en":"Not a door opened during those eleven seconds.","zh":"在那十一秒裏，沒有任何門打開。"},{"en":"Not a door opened means no door opened at all.","zh":"not a door opened 指完全沒有門打開。"},{"en":"During the test, not a door opened, so the room stayed silent.","zh":"測驗期間沒有任何門打開，所以房間保持安靜。"},{"en":"If not a door opened, the person inside could not have left normally.","zh":"如果沒有任何門打開，裏面的人不可能正常離開。"},{"en":"In the story, this detail makes Anika’s disappearance harder to explain.","zh":"在故事中，這個細節令 Anika 的失蹤更難解釋。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"not a shadow moved","meaning":"沒有任何影子移動","examples":[{"en":"Not a shadow moved on the footage.","zh":"錄像中沒有任何影子移動。"},{"en":"Not a shadow moved means nothing visible moved, not even a faint shape.","zh":"not a shadow moved 指沒有可見的東西移動，連淡淡影子也沒有。"},{"en":"The room was so still that not a shadow moved.","zh":"房間靜得沒有任何影子移動。"},{"en":"If not a shadow moved on security footage, the camera shows no sign of escape.","zh":"如果保安錄像中沒有任何影子移動，攝影機就沒有顯示逃走跡象。"},{"en":"In the story, total stillness makes the disappearance feel supernatural.","zh":"在故事中，完全靜止令失蹤感覺超自然。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"simply gone","meaning":"就這樣消失了","examples":[{"en":"Anika was simply gone.","zh":"Anika 就這樣消失了。"},{"en":"Simply gone means completely gone, without any clear explanation.","zh":"simply gone 指完全消失，而且沒有清楚解釋。"},{"en":"I put my wallet on the table, and ten minutes later it was simply gone.","zh":"我把錢包放在桌上，十分鐘後它就這樣消失了。"},{"en":"When evidence is simply gone, people may suspect theft or something stranger.","zh":"當證據就這樣消失了，人們可能懷疑盜竊或更奇怪的事。"},{"en":"In the story, the phrase is frightening because it gives no cause, method, or answer.","zh":"在故事中，這個短語令人害怕，因為它沒有原因、方法或答案。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"speakers crackled","meaning":"喇叭發出雜音","examples":[{"en":"The speakers crackled after Anika disappeared.","zh":"Anika 消失後，喇叭發出雜音。"},{"en":"Speakers crackled means the speakers made rough, broken, static-like sounds.","zh":"speakers crackled 指喇叭發出粗糙、斷續、像靜電的聲音。"},{"en":"The classroom speakers crackled before the principal’s announcement.","zh":"校長廣播前，課室喇叭發出雜音。"},{"en":"Old speakers may crackle when the wire is loose.","zh":"電線鬆動時，舊喇叭可能發出雜音。"},{"en":"In the story, the crackling sound prepares readers for a disturbing voice.","zh":"在故事中，雜音為令人不安的聲音作準備。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"static","meaning":"靜電雜音","examples":[{"en":"At first, Chris thought the sound was static.","zh":"起初，Chris 以為那聲音是靜電雜音。"},{"en":"Static is a rough crackling noise caused by radio or electronic interference.","zh":"static 是由無線電或電子干擾造成的粗糙雜音。"},{"en":"The radio was full of static during the storm.","zh":"暴風期間，收音機充滿靜電雜音。"},{"en":"If a phone call has static, it may be hard to understand the speaker.","zh":"如果電話有靜電雜音，就可能難以聽清楚對方。"},{"en":"In the story, what seems like static soon becomes something more frightening.","zh":"在故事中，看似靜電雜音的東西很快變得更可怕。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"my own voice","meaning":"我自己的聲音","examples":[{"en":"Chris heard his own voice coming from under the floor.","zh":"Chris 聽到自己的聲音從地板下面傳來。"},{"en":"My own voice means the sound of me speaking, not someone else.","zh":"my own voice 指我自己說話的聲音，而不是別人的聲音。"},{"en":"Hearing my own voice in a recording can feel strange at first.","zh":"在錄音裏聽到我自己的聲音，起初可能感覺奇怪。"},{"en":"If you hear your own voice when you did not speak, the experience may feel impossible.","zh":"如果你在沒有說話時聽到自己的聲音，那經歷可能感覺不可能。"},{"en":"In the story, Chris hearing his own voice turns the mystery personal.","zh":"在故事中，Chris 聽到自己的聲音令謎團變得私人化。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"soft and close","meaning":"輕柔而貼近","examples":[{"en":"The voice sounded soft and close.","zh":"那聲音聽起來輕柔而貼近。"},{"en":"Soft and close means quiet, gentle, and seeming very near.","zh":"soft and close 指安靜、柔和，而且似乎非常接近。"},{"en":"Her voice was soft and close when she whispered beside the hospital bed.","zh":"她在病床旁低語時，聲音輕柔而貼近。"},{"en":"A sound that is soft and close can feel comforting in one situation and frightening in another.","zh":"輕柔而貼近的聲音在某些情況下令人安心，在另一些情況下令人害怕。"},{"en":"In the story, the voice feels frightening because it is too near and too intimate.","zh":"在故事中，那聲音令人害怕，因為它太近、太親密。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"coming from under the floor","meaning":"從地板下面傳來","examples":[{"en":"The voice was coming from under the floor.","zh":"那聲音從地板下面傳來。"},{"en":"Coming from under the floor means the sound seemed to rise from beneath the floor surface.","zh":"coming from under the floor 指聲音似乎從地板表面下方傳上來。"},{"en":"The family heard scratching coming from under the floor and called a repair worker.","zh":"一家人聽到地板下面傳來抓刮聲，便找維修工人。"},{"en":"Water sounds coming from under the floor may mean a pipe is leaking.","zh":"從地板下面傳來水聲，可能表示水管漏水。"},{"en":"In the story, a voice from under the floor feels impossible and deeply unsettling.","zh":"在故事中，從地板下面傳來的人聲感覺不可能，而且非常不安。"}],"source":"2020 Q8.pdf","sourcePage":14},{"front":"You’re late","meaning":"你遲到了","examples":[{"en":"The voice said, “Chris, you’re late.”","zh":"那聲音說：「Chris，你遲到了。」"},{"en":"You’re late means you arrived after the expected or correct time.","zh":"You’re late 指你在預期或正確時間之後才到達。"},{"en":"The teacher said, “You’re late,” when the student entered after the bell.","zh":"學生在鐘聲後進入課室時，老師說：「你遲到了。」"},{"en":"Saying “you’re late” can sound ordinary, but it becomes frightening if nobody should know you are there.","zh":"說「你遲到了」可以很普通，但如果沒有人應該知道你在那裏，就會變得可怕。"},{"en":"In the story, the voice knows Chris’s name and speaks as if it expected him.","zh":"在故事中，那聲音知道 Chris 的名字，並像早已等着他一樣說話。"}],"source":"2020 Q8.pdf","sourcePage":15}],"dse/writing/part-b/2020/Q9":[{"front":"from sceptic to spellbound","meaning":"由懷疑到着迷","examples":[{"en":"The writer goes from sceptic to spellbound after a night at Hong Kong’s Xiqu Centre.","zh":"作者在香港戲曲中心度過一晚後，由懷疑到着迷。"},{"en":"“From sceptic to spellbound” means changing from someone who doubts something into someone deeply impressed by it.","zh":"“From sceptic to spellbound” 指一個人由懷疑某事，轉變為被它深深打動。"},{"en":"A student may go from sceptic to spellbound after seeing how a difficult poem can connect with real life.","zh":"學生看見一首艱深詩歌如何連繫真實生活後，可能由懷疑到着迷。"},{"en":"A visitor can go from sceptic to spellbound when an unfamiliar performance slowly becomes moving and beautiful.","zh":"當陌生的表演慢慢變得動人而美麗，訪客可以由懷疑到着迷。"},{"en":"This phrase is useful when an experience changes a person’s attitude completely.","zh":"這個短語適合用來描述一段經歷完全改變一個人的態度。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"sceptic","meaning":"懷疑者","examples":[{"en":"The writer enters the theatre as a sceptic.","zh":"作者以懷疑者的身份走進劇院。"},{"en":"A sceptic is someone who doubts whether something is true, useful, or worth enjoying.","zh":"懷疑者是指懷疑某事是否真實、有用或值得欣賞的人。"},{"en":"A student may be a sceptic about online learning until a good teacher makes the lesson clear.","zh":"學生可能一開始懷疑網上學習，直到好老師把課堂講得清楚。"},{"en":"People often become sceptics when they have little experience of something unfamiliar.","zh":"當人們對陌生事物經驗很少時，常會成為懷疑者。"},{"en":"Being a sceptic is not always bad, because questions can lead to deeper understanding.","zh":"做懷疑者不一定是壞事，因為提問可以帶來更深入的理解。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"spellbound","meaning":"着迷的；入神的","examples":[{"en":"The performance leaves the writer spellbound.","zh":"這場表演令作者着迷入神。"},{"en":"Spellbound means so fascinated that you give something your full attention.","zh":"Spellbound 指着迷到把全部注意力放在某事上。"},{"en":"Children were spellbound when the storyteller changed voices for every character.","zh":"當說故事的人為每個角色改變聲線時，孩子們都聽得入神。"},{"en":"Beautiful music can leave an audience spellbound because no one wants to look away or speak.","zh":"美麗的音樂可以令觀眾着迷，因為沒有人想移開視線或說話。"},{"en":"Use spellbound when someone is not just interested, but completely absorbed.","zh":"當某人不只是感興趣，而是完全投入時，可以用 spellbound。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"a night at","meaning":"在……的一晚","examples":[{"en":"The essay describes a night at Hong Kong’s Xiqu Centre.","zh":"這篇文章描述作者在香港戲曲中心的一晚。"},{"en":"“A night at” means an evening spent in a particular place or event.","zh":"“A night at” 指在某個地方或活動中度過的一個晚上。"},{"en":"A night at the museum can help students learn history outside the classroom.","zh":"在博物館的一晚可以幫助學生在課室外學習歷史。"},{"en":"A night at a concert may become memorable if the music surprises you.","zh":"如果音樂帶來驚喜，在音樂會的一晚可能會令人難忘。"},{"en":"This phrase often introduces the place where an important evening experience happens.","zh":"這個短語常用來介紹一段重要夜晚經歷發生的地方。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"Xiqu Centre","meaning":"戲曲中心","examples":[{"en":"The writer visits the Xiqu Centre in the West Kowloon Cultural District.","zh":"作者到訪位於西九文化區的戲曲中心。"},{"en":"The Xiqu Centre is a cultural venue where audiences can watch Chinese opera and related performances.","zh":"戲曲中心是一個文化場地，觀眾可以在那裏欣賞中國戲曲及相關表演。"},{"en":"A tourist may visit the Xiqu Centre to learn about traditional stage costumes, music, and stories.","zh":"遊客可能會到戲曲中心了解傳統舞台服裝、音樂和故事。"},{"en":"The Xiqu Centre helps make an old art form easier for new audiences to approach.","zh":"戲曲中心幫助新觀眾更容易接觸古老藝術。"},{"en":"For learners, the name Xiqu Centre refers to both a building and a doorway into Chinese opera.","zh":"對學習者來說，Xiqu Centre 既是一座建築，也是一道進入中國戲曲的門。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"suggested that","meaning":"建議","examples":[{"en":"Chris suggested that we spend my third evening in Hong Kong watching Chinese opera.","zh":"Chris 建議我們在我到香港的第三個晚上欣賞中國戲曲。"},{"en":"“Suggested that” means proposed an idea for someone to consider.","zh":"“Suggested that” 指提出一個想法讓別人考慮。"},{"en":"My teacher suggested that I read the story summary before watching the play.","zh":"老師建議我在看戲前先閱讀故事簡介。"},{"en":"A friend may suggest that you try something unfamiliar because it could change your view.","zh":"朋友可能建議你嘗試陌生事物，因為它可能改變你的看法。"},{"en":"This phrase is softer than ordering someone, because it gives advice or a recommendation.","zh":"這個短語比命令柔和，因為它是在給建議或推薦。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"spend my third evening","meaning":"度過我第三個晚上","examples":[{"en":"We spent my third evening in Hong Kong watching Chinese opera.","zh":"我們在香港的第三個晚上欣賞中國戲曲。"},{"en":"“Spend my third evening” means use the third night of a trip or stay doing a particular activity.","zh":"“Spend my third evening” 指把旅程或停留期間的第三個晚上用來做某件事。"},{"en":"I spent my third evening in Taipei walking through a night market with my cousins.","zh":"我在台北的第三個晚上和表親逛夜市。"},{"en":"How you spend an evening can affect what you remember most about a place.","zh":"你如何度過一個晚上，會影響你對一個地方最深的記憶。"},{"en":"This phrase is useful when describing a travel schedule through personal experience.","zh":"這個短語適合用來從個人經歷描述旅行安排。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"watching Chinese opera","meaning":"欣賞中國戲曲","examples":[{"en":"Chris suggested watching Chinese opera at the Xiqu Centre.","zh":"Chris 建議在戲曲中心欣賞中國戲曲。"},{"en":"Watching Chinese opera means seeing a stage performance that combines singing, acting, music, movement, and costume.","zh":"欣賞中國戲曲指觀看結合唱、做、音樂、動作和服裝的舞台表演。"},{"en":"Students may enjoy watching Chinese opera more if someone explains the story first.","zh":"如果有人先解釋故事，學生可能會更享受欣賞中國戲曲。"},{"en":"Watching Chinese opera can feel difficult at first, but the gestures and music can slowly become meaningful.","zh":"欣賞中國戲曲起初可能覺得困難，但動作和音樂會慢慢變得有意義。"},{"en":"This phrase describes an activity, not just listening to songs.","zh":"這個短語描述的是一種觀看活動，不只是聽歌。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"Chinese opera","meaning":"中國戲曲","examples":[{"en":"Chinese opera seemed remote and difficult to enter at first.","zh":"中國戲曲起初看來遙遠而難以投入。"},{"en":"Chinese opera is a traditional performing art that uses music, singing, movement, costume, and symbolic gestures.","zh":"中國戲曲是一種傳統表演藝術，運用音樂、唱腔、動作、服裝和象徵手勢。"},{"en":"A beginner may understand Chinese opera better by reading the plot before the performance.","zh":"初學者在表演前閱讀劇情，可能會更理解中國戲曲。"},{"en":"Chinese opera can seem strange because its stage language is different from modern drama.","zh":"中國戲曲可能顯得陌生，因為它的舞台語言不同於現代戲劇。"},{"en":"Chinese opera becomes easier to appreciate when viewers watch patiently and notice details.","zh":"當觀眾有耐性地觀看並留意細節，中國戲曲會變得更容易欣賞。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"West Kowloon Cultural District","meaning":"西九文化區","examples":[{"en":"The Xiqu Centre is in the West Kowloon Cultural District.","zh":"戲曲中心位於西九文化區。"},{"en":"The West Kowloon Cultural District is a cultural area in Hong Kong with venues for arts and performances.","zh":"西九文化區是香港一個文化區，設有藝術和表演場地。"},{"en":"A visitor may spend an afternoon in the West Kowloon Cultural District before attending a show at night.","zh":"遊客可能下午先在西九文化區遊覽，晚上再去看表演。"},{"en":"The West Kowloon Cultural District gives tourists a place to experience Hong Kong beyond shopping and transport.","zh":"西九文化區讓遊客體驗購物和交通以外的香港。"},{"en":"The phrase names a location, so it is useful in travel and culture writing.","zh":"這個短語是一個地點名稱，適合用於旅遊和文化寫作。"}],"source":"2020 Q9.pdf","sourcePage":1},{"front":"my first reaction was","meaning":"我的第一反應是","examples":[{"en":"My first reaction was embarrassingly honest.","zh":"我的第一反應誠實得令人尷尬。"},{"en":"“My first reaction was” introduces what someone immediately thought or felt before deeper reflection.","zh":"“My first reaction was” 用來介紹某人在深入思考前立刻產生的想法或感受。"},{"en":"My first reaction was fear when I saw the long exam paper.","zh":"當我看到很長的試卷時，我的第一反應是害怕。"},{"en":"A first reaction can be wrong because it often comes before understanding.","zh":"第一反應可能是錯的，因為它常出現在真正理解之前。"},{"en":"This phrase helps writers show how their attitude changes later.","zh":"這個短語幫助作者展示自己之後的態度轉變。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"embarrassingly honest","meaning":"誠實得令人尷尬","examples":[{"en":"My first reaction was embarrassingly honest.","zh":"我的第一反應誠實得令人尷尬。"},{"en":"Embarrassingly honest means truthful in a way that makes you feel slightly ashamed or uncomfortable.","zh":"Embarrassingly honest 指說得很真實，但真實到令人有點羞愧或不自在。"},{"en":"I was embarrassingly honest when I admitted that I had never read the famous book.","zh":"我承認自己從未讀過那本名著時，誠實得令人尷尬。"},{"en":"Someone may sound embarrassingly honest when they reveal a prejudice they later question.","zh":"當某人說出後來會反思的偏見時，可能顯得誠實得令人尷尬。"},{"en":"The phrase often shows self-awareness, because the speaker knows the truth is not flattering.","zh":"這個短語常顯示自我覺察，因為說話者知道這個真相並不光彩。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"understand a single minute of","meaning":"聽懂其中一分一秒","examples":[{"en":"I wondered whether I would understand a single minute of the performance.","zh":"我 wondered 自己會否聽懂這場表演的任何一分一秒。"},{"en":"“Understand a single minute of” means understand even a very small part of something.","zh":"“Understand a single minute of” 指即使是一小部分也能理解。"},{"en":"I worried I would not understand a single minute of the science lecture.","zh":"我擔心自己連科學講座的一分一秒也聽不懂。"},{"en":"People may fear a foreign-language film because they think they will not understand a single minute of it.","zh":"人們可能害怕外語電影，因為他們以為自己連一分鐘也看不明白。"},{"en":"This phrase often shows anxiety before a difficult or unfamiliar experience.","zh":"這個短語常表達人在面對困難或陌生經歷前的焦慮。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"up until then","meaning":"在那之前","examples":[{"en":"Up until then, Chinese opera had been a museum piece in my imagination.","zh":"在那之前，中國戲曲在我的想像中一直像博物館藏品般的舊事物。"},{"en":"“Up until then” means before that moment or before that experience changed something.","zh":"“Up until then” 指在那一刻之前，或在某次經歷改變事情之前。"},{"en":"Up until then, I thought public speaking was only for confident people.","zh":"在那之前，我以為公開演說只屬於有自信的人。"},{"en":"A new experience can change what someone believed up until then.","zh":"新經歷可以改變某人在那之前一直相信的事。"},{"en":"This phrase is useful when showing a turning point in a story.","zh":"這個短語適合用來展示故事中的轉折點。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"in my imagination","meaning":"在我的想像中","examples":[{"en":"Chinese opera had been, in my imagination, a museum piece.","zh":"中國戲曲在我的想像中一直像博物館藏品般的舊事物。"},{"en":"“In my imagination” means in the way someone pictures something before seeing or knowing it clearly.","zh":"“In my imagination” 指某人在真正看見或了解之前，心中想像事物的方式。"},{"en":"In my imagination, boarding school was lonely until I met students who loved living there.","zh":"在我的想像中，寄宿學校很孤單，直到我遇見喜歡住在那裏的學生。"},{"en":"Things in my imagination may be different from reality because I have not experienced them yet.","zh":"想像中的事物可能與現實不同，因為我還未真正經歷。"},{"en":"This phrase helps writers separate an old assumption from a real experience.","zh":"這個短語幫助作者分清舊有假設和真實經驗。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"a museum piece","meaning":"像博物館藏品般的舊事物","examples":[{"en":"Chinese opera had seemed like a museum piece to me.","zh":"對我來說，中國戲曲曾像博物館藏品般的舊事物。"},{"en":"A museum piece is something that seems old, distant, and no longer part of everyday life.","zh":"A museum piece 指看起來古老、遙遠，而且不再屬於日常生活的事物。"},{"en":"Some teenagers think handwriting is a museum piece because they type almost everything.","zh":"有些青少年覺得手寫字像博物館藏品，因為他們幾乎所有東西都用打字。"},{"en":"A tradition may feel like a museum piece if people only display it but never practise it.","zh":"如果人們只展示傳統而不實踐它，傳統可能會像博物館藏品。"},{"en":"This phrase can be critical because it suggests something feels frozen in the past.","zh":"這個短語可以帶批評意味，因為它暗示某事物像被凍結在過去。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"remote, slow and difficult to enter","meaning":"遙遠、緩慢而難以投入","examples":[{"en":"I imagined Chinese opera as remote, slow, and difficult to enter.","zh":"我把中國戲曲想像成遙遠、緩慢而難以投入的藝術。"},{"en":"“Remote, slow and difficult to enter” describes something that feels distant, hard to understand, and not immediately enjoyable.","zh":"“Remote, slow and difficult to enter” 描述某事物感覺遙遠、難懂，而且不容易即時享受。"},{"en":"Classical music may seem remote, slow and difficult to enter for students who only know pop songs.","zh":"對只熟悉流行曲的學生來說，古典音樂可能顯得遙遠、緩慢而難以投入。"},{"en":"Without explanation, an old art form can feel remote, slow and difficult to enter.","zh":"如果沒有解釋，古老藝術形式可能令人覺得遙遠、緩慢而難以投入。"},{"en":"The phrase shows why beginners may resist something before giving it time.","zh":"這個短語顯示初學者為何可能在給予時間之前先抗拒某事。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"collecting skyline photographs","meaning":"拍攝城市天際線照片","examples":[{"en":"Travelling is not just about collecting skyline photographs.","zh":"旅遊不只是拍攝城市天際線照片。"},{"en":"“Collecting skyline photographs” means taking impressive city-view photos, often as a surface-level travel activity.","zh":"“Collecting skyline photographs” 指拍攝壯觀城市景觀照，常代表較表面的旅遊活動。"},{"en":"A tourist may collect skyline photographs but still miss the daily life of local people.","zh":"遊客可能拍了很多城市天際線照片，卻仍錯過本地人的日常生活。"},{"en":"If travel is only collecting skyline photographs, it may become shallow and forgettable.","zh":"如果旅遊只是不斷拍城市天際線照片，它可能變得膚淺而容易忘記。"},{"en":"This phrase contrasts sightseeing pictures with deeper cultural understanding.","zh":"這個短語把觀光照片與更深入的文化理解作對比。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"more importantly","meaning":"更重要的是","examples":[{"en":"More importantly, travelling is about letting a place challenge your assumptions.","zh":"更重要的是，旅遊是讓一個地方挑戰你的既有想法。"},{"en":"“More importantly” introduces the point that matters more than what was said before.","zh":"“More importantly” 用來引出比前面內容更重要的一點。"},{"en":"A school trip is fun, but more importantly, it teaches students how people live outside textbooks.","zh":"學校旅行很有趣，但更重要的是，它教學生了解課本以外的人如何生活。"},{"en":"Writers use more importantly when they want readers to focus on the deeper reason.","zh":"作者使用 more importantly，是想讀者集中在更深層的原因。"},{"en":"This phrase helps organise ideas by moving from a smaller point to a bigger one.","zh":"這個短語幫助組織想法，把較小的重點推進到更大的重點。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"challenge your assumptions","meaning":"挑戰你的既有想法","examples":[{"en":"Travelling can let a place challenge your assumptions.","zh":"旅遊可以讓一個地方挑戰你的既有想法。"},{"en":"To challenge your assumptions means to make you question ideas you accepted too quickly.","zh":"To challenge your assumptions 指令你質疑自己太快接受的想法。"},{"en":"Meeting hardworking elderly people may challenge your assumptions about age and ability.","zh":"遇見勤奮的長者可能會挑戰你對年齡和能力的既有想法。"},{"en":"A new culture can challenge your assumptions by showing that your way is not the only way.","zh":"新文化可以透過顯示你的方式不是唯一方式，挑戰你的既有想法。"},{"en":"This phrase is useful when an experience makes someone think again.","zh":"當一段經歷令人重新思考時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":2},{"front":"followed someone through","meaning":"跟隨某人穿過","examples":[{"en":"I followed Chris through the glowing entrance.","zh":"我跟隨 Chris 穿過亮着燈光的入口。"},{"en":"“Followed someone through” means walked behind or with someone while passing through a place.","zh":"“Followed someone through” 指跟在某人後面或與某人一起穿過某個地方。"},{"en":"I followed my teacher through the crowded museum so I would not get lost.","zh":"我跟着老師穿過擠迫的博物館，以免迷路。"},{"en":"A nervous visitor may follow a friend through an unfamiliar entrance for confidence.","zh":"緊張的訪客可能會跟隨朋友穿過陌生入口，讓自己有信心。"},{"en":"This phrase often describes movement into a new setting.","zh":"這個短語常描述進入新場景的動作。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"the glowing entrance","meaning":"亮着燈光的入口","examples":[{"en":"I followed Chris through the glowing entrance.","zh":"我跟隨 Chris 穿過亮着燈光的入口。"},{"en":"A glowing entrance is an entrance lit warmly or brightly, often making a place feel welcoming or dramatic.","zh":"A glowing entrance 指被溫暖或明亮燈光照亮的入口，常令人覺得親切或有戲劇感。"},{"en":"The glowing entrance of the theatre made the evening feel special before the show began.","zh":"劇院亮着燈光的入口讓表演開始前的晚上已顯得特別。"},{"en":"Lighting can turn an ordinary doorway into a glowing entrance that attracts people inside.","zh":"燈光可以把普通門口變成吸引人進入的亮着燈光的入口。"},{"en":"This phrase helps create atmosphere at the start of a scene.","zh":"這個短語有助在場景開頭營造氣氛。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"in order to","meaning":"為了","examples":[{"en":"I entered the Xiqu Centre in order to see another side of Hong Kong.","zh":"我走進戲曲中心，為了看見香港的另一面。"},{"en":"“In order to” means for the purpose of doing something.","zh":"“In order to” 指為了做某件事。"},{"en":"Students read the introduction in order to understand the play more easily.","zh":"學生閱讀簡介，為了更容易理解那齣戲。"},{"en":"People may travel slowly in order to notice details they usually miss.","zh":"人們可能慢慢旅行，為了注意平時錯過的細節。"},{"en":"This phrase clearly connects an action with its purpose.","zh":"這個短語清楚連接行動和目的。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"lay beyond","meaning":"存在於……之外","examples":[{"en":"I wanted to see a Hong Kong that lay beyond ferries, malls, and neon signs.","zh":"我想看見一個存在於渡輪、商場和霓虹招牌之外的香港。"},{"en":"“Lay beyond” means existed outside or past the familiar things people usually notice.","zh":"“Lay beyond” 指存在於人們通常注意的熟悉事物之外。"},{"en":"The village life that lay beyond the tourist street showed me a quieter side of the town.","zh":"存在於遊客街之外的村莊生活，讓我看見小鎮較安靜的一面。"},{"en":"A deeper culture may lie beyond famous buildings and shopping areas.","zh":"更深層的文化可能存在於著名建築和購物區之外。"},{"en":"This phrase helps describe hidden or less obvious parts of a place.","zh":"這個短語有助描述一個地方隱藏或不那麼明顯的部分。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"ferries, malls and neon signs","meaning":"渡輪、商場和霓虹招牌","examples":[{"en":"The writer wanted to see a Hong Kong beyond ferries, malls, and neon signs.","zh":"作者想看見一個超越渡輪、商場和霓虹招牌的香港。"},{"en":"“Ferries, malls and neon signs” represents the familiar, busy images people often associate with Hong Kong.","zh":"“Ferries, malls and neon signs” 代表人們常聯想到香港的熟悉繁忙形象。"},{"en":"A visitor may know a city through ferries, malls and neon signs before discovering its traditions.","zh":"遊客可能先透過渡輪、商場和霓虹招牌認識一個城市，然後才發現它的傳統。"},{"en":"If tourists focus only on ferries, malls and neon signs, they may miss quieter cultural experiences.","zh":"如果遊客只集中於渡輪、商場和霓虹招牌，就可能錯過較安靜的文化經驗。"},{"en":"This phrase is useful as a list of surface impressions of a modern city.","zh":"這個短語適合用作現代城市表面印象的清單。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"by the end of the night","meaning":"到那晚結束時","examples":[{"en":"By the end of the night, I had changed my mind about Xiqu.","zh":"到那晚結束時，我已改變了對戲曲的看法。"},{"en":"“By the end of the night” means when the evening had finished or reached its conclusion.","zh":"“By the end of the night” 指晚上結束或來到尾聲的時候。"},{"en":"By the end of the night, the shy student was singing with everyone else.","zh":"到那晚結束時，那個害羞的學生已和大家一起唱歌。"},{"en":"A person’s attitude can change by the end of the night if the experience is powerful.","zh":"如果經歷很有力量，一個人的態度可以到那晚結束時改變。"},{"en":"This phrase often marks the result of an evening event.","zh":"這個短語常標示一個夜晚活動帶來的結果。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"not merely","meaning":"不只是","examples":[{"en":"I had not merely changed my mind about Xiqu.","zh":"我不只是改變了對戲曲的看法。"},{"en":"“Not merely” means not only this simple thing, but something more important as well.","zh":"“Not merely” 指不只是這件簡單事情，還有更重要的意義。"},{"en":"Reading a novel is not merely learning a story; it can also teach empathy.","zh":"讀小說不只是認識故事，也可以學習同理心。"},{"en":"A museum visit is not merely looking at objects if it helps people understand history.","zh":"如果參觀博物館幫助人理解歷史，它就不只是看物件。"},{"en":"This phrase helps writers move from a surface meaning to a deeper meaning.","zh":"這個短語幫助作者由表面意思推進到更深層意思。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"change my mind about","meaning":"改變對……的看法","examples":[{"en":"I changed my mind about Xiqu by the end of the night.","zh":"到那晚結束時，我改變了對戲曲的看法。"},{"en":"To change my mind about something means to think differently about it after new experience or evidence.","zh":"To change my mind about something 指在有新經驗或證據後，對某事有不同想法。"},{"en":"I changed my mind about group work after my classmates helped me finish a difficult project.","zh":"同學幫我完成困難專題後，我改變了對小組合作的看法。"},{"en":"People may change their mind about an art form when they finally see it performed well.","zh":"當人們終於看見某種藝術被精彩演出時，可能會改變對它的看法。"},{"en":"This phrase describes a personal shift in opinion.","zh":"這個短語描述個人意見上的轉變。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"the way I listened to a culture","meaning":"我聆聽一種文化的方式","examples":[{"en":"I changed the way I listened to a culture.","zh":"我改變了自己聆聽一種文化的方式。"},{"en":"“The way I listened to a culture” means how I paid attention to, understood, and respected a culture.","zh":"“The way I listened to a culture” 指我如何留意、理解並尊重一種文化。"},{"en":"A traveller changes the way they listen to a culture when they stop judging too quickly.","zh":"當旅客不再太快判斷，他們就改變了聆聽一種文化的方式。"},{"en":"Patient explanation can change the way people listen to a culture because they notice meaning behind details.","zh":"耐心解釋可以改變人們聆聽一種文化的方式，因為他們會注意細節背後的意義。"},{"en":"This phrase is more reflective than simply saying “I learned about culture.”","zh":"這個短語比簡單說「我學習了文化」更有反思意味。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"the first note was played","meaning":"第一個音符奏起","examples":[{"en":"The experience began before the first note was played.","zh":"這段經歷在第一個音符奏起之前已經開始。"},{"en":"“Before the first note was played” means before the music or performance officially started.","zh":"“Before the first note was played” 指音樂或表演正式開始之前。"},{"en":"The audience felt excited before the first note was played because the hall was already full of energy.","zh":"第一個音符奏起之前，觀眾已感到興奮，因為大廳已充滿氣氛。"},{"en":"A performance can begin emotionally before the first note is played if the setting prepares the audience.","zh":"如果場地先讓觀眾投入，表演可以在第一個音符奏起前已在情感上開始。"},{"en":"This phrase shows that atmosphere can matter before the actual show begins.","zh":"這個短語顯示真正表演開始前，氣氛也很重要。"}],"source":"2020 Q9.pdf","sourcePage":3},{"front":"standing in the foyer","meaning":"站在大堂裏","examples":[{"en":"Standing in the foyer, I felt as if the building was easing me into another world.","zh":"站在大堂裏，我感覺這座建築正慢慢引導我進入另一個世界。"},{"en":"Standing in the foyer means being in the entrance hall of a theatre, hotel, or public building.","zh":"Standing in the foyer 指身處劇院、酒店或公共建築的入口大堂。"},{"en":"Standing in the foyer before the concert, students read posters about the performers.","zh":"音樂會前站在大堂裏，學生閱讀關於表演者的海報。"},{"en":"A foyer can prepare visitors for an event before they enter the main hall.","zh":"大堂可以在訪客進入主廳前，先為活動作準備。"},{"en":"This phrase places the writer at the beginning of the theatre experience.","zh":"這個短語把作者放在劇院經歷的開端。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"felt as if","meaning":"感覺好像","examples":[{"en":"I felt as if the building itself was easing me into another world.","zh":"我感覺好像這座建築本身正慢慢引導我進入另一個世界。"},{"en":"“Felt as if” means had the impression that something was true, even if it was not literally true.","zh":"“Felt as if” 指感覺某事像是真的，即使它不一定是字面上的事實。"},{"en":"I felt as if the old classroom remembered every student who had studied there.","zh":"我感覺好像那間舊課室記得每一位曾在那裏讀書的學生。"},{"en":"Writers use felt as if to describe emotion, atmosphere, or imagination.","zh":"作者用 felt as if 來描述情感、氣氛或想像。"},{"en":"This phrase helps turn a physical place into a personal feeling.","zh":"這個短語能把實際地方轉化成個人感受。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"ease someone into","meaning":"引導某人慢慢進入","examples":[{"en":"The building seemed to ease me into another world.","zh":"這座建築似乎慢慢引導我進入另一個世界。"},{"en":"To ease someone into something means to help them enter or accept it gradually and comfortably.","zh":"To ease someone into something 指幫助某人逐漸而舒服地進入或接受某事。"},{"en":"A teacher can ease students into a difficult topic by starting with simple examples.","zh":"老師可以先用簡單例子，引導學生慢慢進入困難課題。"},{"en":"Clear signs and friendly staff can ease visitors into an unfamiliar museum.","zh":"清楚指示和友善職員可以引導訪客慢慢進入陌生博物館。"},{"en":"This phrase is useful when a new experience does not feel sudden or frightening.","zh":"當新經歷不顯得突然或可怕時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"another world","meaning":"另一個世界","examples":[{"en":"The building seemed to ease me into another world.","zh":"這座建築似乎慢慢引導我進入另一個世界。"},{"en":"Another world means a place or experience that feels very different from everyday life.","zh":"Another world 指一個地方或經歷感覺與日常生活非常不同。"},{"en":"A quiet library can feel like another world after a noisy school day.","zh":"在嘈雜的上學日後，安靜的圖書館可以像另一個世界。"},{"en":"Music, lighting, and costume can make a theatre feel like another world.","zh":"音樂、燈光和服裝可以令劇院感覺像另一個世界。"},{"en":"This phrase suggests strong contrast between ordinary life and a special experience.","zh":"這個短語暗示日常生活與特別經歷之間有強烈對比。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"harbour breeze","meaning":"海港微風","examples":[{"en":"Outside, West Kowloon was full of harbour breeze and Saturday-night energy.","zh":"外面，西九充滿海港微風和星期六晚上的活力。"},{"en":"Harbour breeze means the fresh wind that comes from the sea or harbour.","zh":"Harbour breeze 指從海邊或海港吹來的清新微風。"},{"en":"People walking by the waterfront enjoyed the harbour breeze after a hot afternoon.","zh":"炎熱下午後，在海濱散步的人享受着海港微風。"},{"en":"A harbour breeze can make a city feel open, relaxed, and alive.","zh":"海港微風可以令城市感覺開闊、放鬆而有生氣。"},{"en":"This phrase adds sensory detail because readers can imagine the air moving.","zh":"這個短語加入感官細節，因為讀者可以想像空氣流動。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"Saturday-night energy","meaning":"星期六晚上的活力","examples":[{"en":"West Kowloon was full of harbour breeze and Saturday-night energy.","zh":"西九充滿海港微風和星期六晚上的活力。"},{"en":"Saturday-night energy means the lively, relaxed excitement people often feel at the weekend.","zh":"Saturday-night energy 指人們在週末常感到的熱鬧、放鬆和興奮氣氛。"},{"en":"The shopping street had Saturday-night energy, with families eating, laughing, and taking photos.","zh":"那條購物街充滿星期六晚上的活力，家人們吃飯、笑談和拍照。"},{"en":"Music and crowds can create Saturday-night energy in a public square.","zh":"音樂和人群可以在公共廣場營造星期六晚上的活力。"},{"en":"This phrase describes mood as much as time.","zh":"這個短語不只描述時間，也描述氣氛。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"the atmosphere slowed down","meaning":"氣氛慢了下來","examples":[{"en":"Inside, however, the atmosphere slowed down.","zh":"然而，一走進裏面，氣氛慢了下來。"},{"en":"“The atmosphere slowed down” means the mood became calmer, quieter, and less hurried.","zh":"“The atmosphere slowed down” 指氣氛變得更平靜、更安靜和不再匆忙。"},{"en":"When students entered the library, the atmosphere slowed down immediately.","zh":"學生一走進圖書館，氣氛立刻慢了下來。"},{"en":"Soft lighting and quiet voices can make the atmosphere slow down before a performance.","zh":"柔和燈光和安靜說話聲可以令表演前的氣氛慢下來。"},{"en":"This phrase is useful for showing contrast between a busy outside world and a calm inside space.","zh":"這個短語適合展示繁忙外界與平靜室內空間的對比。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"elderly opera lovers","meaning":"年長戲曲愛好者","examples":[{"en":"Elderly opera lovers chatted beside tourists with wide eyes.","zh":"年長戲曲愛好者在睜大眼睛的遊客旁邊聊天。"},{"en":"Elderly opera lovers are older people who know, enjoy, and often care deeply about opera.","zh":"Elderly opera lovers 指熟悉、喜愛並常深深重視戲曲的年長人士。"},{"en":"Elderly opera lovers may explain costumes and gestures to younger visitors.","zh":"年長戲曲愛好者可能會向年輕訪客解釋服裝和手勢。"},{"en":"Their presence can show that an art form has loyal audiences across many years.","zh":"他們的出現可以顯示一種藝術多年來有忠實觀眾。"},{"en":"This phrase helps readers imagine the mix of people in the foyer.","zh":"這個短語幫助讀者想像大堂裏不同人群的混合。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"tourists with wide eyes","meaning":"睜大眼睛的遊客","examples":[{"en":"Elderly opera lovers chatted beside tourists with wide eyes.","zh":"年長戲曲愛好者在睜大眼睛的遊客旁邊聊天。"},{"en":"Tourists with wide eyes are visitors who look curious, surprised, or excited by a new place.","zh":"Tourists with wide eyes 指因新地方而顯得好奇、驚訝或興奮的遊客。"},{"en":"Tourists with wide eyes stopped to photograph the colourful costumes in the lobby.","zh":"睜大眼睛的遊客停下來拍大堂裏色彩鮮豔的戲服。"},{"en":"People often have wide eyes when they see something unfamiliar but attractive.","zh":"當人們看見陌生但吸引的事物時，常會睜大眼睛。"},{"en":"This phrase shows wonder without needing to say directly that the tourists were amazed.","zh":"這個短語不用直接說遊客很驚奇，也能表現驚嘆。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"under the warm lights","meaning":"在溫暖的燈光下","examples":[{"en":"A young couple took photos under the warm lights.","zh":"一對年輕情侶在溫暖的燈光下拍照。"},{"en":"Under the warm lights means beneath soft lighting that makes a place feel gentle and welcoming.","zh":"Under the warm lights 指在柔和燈光之下，令地方感覺溫柔而親切。"},{"en":"Students displayed their artwork under the warm lights of the school hall.","zh":"學生在學校禮堂溫暖的燈光下展示自己的作品。"},{"en":"Warm lights can make photos feel softer and the space more comfortable.","zh":"溫暖的燈光可以令照片更柔和，也令空間更舒服。"},{"en":"This phrase gives a scene visual warmth and atmosphere.","zh":"這個短語為場景加入視覺上的溫暖和氣氛。"}],"source":"2020 Q9.pdf","sourcePage":4},{"front":"embroidered robes","meaning":"繡花戲服","examples":[{"en":"A poster showed embroidered robes and painted faces.","zh":"一張海報展示繡花戲服和臉譜。"},{"en":"Embroidered robes are long stage clothes decorated with patterns sewn into the fabric.","zh":"Embroidered robes 指用線在布料上繡上圖案的長舞台服裝。"},{"en":"Embroidered robes can show a character’s status, role, or personality in Chinese opera.","zh":"繡花戲服可以顯示中國戲曲角色的身份、角色類型或性格。"},{"en":"If a robe is richly embroidered, the audience may guess the character is important or noble.","zh":"如果戲服繡得華麗，觀眾可能猜到角色重要或高貴。"},{"en":"This phrase points to costume details that carry meaning on stage.","zh":"這個短語指向舞台上帶有意義的服裝細節。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"painted faces","meaning":"臉譜；彩繪面孔","examples":[{"en":"A poster showed embroidered robes and painted faces.","zh":"一張海報展示繡花戲服和臉譜。"},{"en":"Painted faces are stage make-up designs that show a character’s identity, mood, or moral nature.","zh":"Painted faces 指舞台化妝圖案，用來顯示角色身份、情緒或道德性格。"},{"en":"In Chinese opera, painted faces can help the audience recognise heroes, villains, or warriors.","zh":"在中國戲曲中，臉譜可以幫助觀眾辨認英雄、奸角或武士。"},{"en":"A fierce painted face may prepare viewers for a powerful or dangerous character.","zh":"兇猛的臉譜可能讓觀眾預期角色有力量或危險。"},{"en":"This phrase shows that make-up can be a storytelling tool.","zh":"這個短語顯示化妝也可以是說故事的工具。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"what surprised me most was that","meaning":"最令我驚訝的是","examples":[{"en":"What surprised me most was that the Xiqu Centre did not make the art feel locked away.","zh":"最令我驚訝的是，戲曲中心沒有令這門藝術感覺被封存。"},{"en":"“What surprised me most was that” introduces the thing that was most unexpected.","zh":"“What surprised me most was that” 用來引出最出乎意料的事情。"},{"en":"What surprised me most was that the quiet student gave the strongest speech.","zh":"最令我驚訝的是，那位安靜的學生發表了最有力的演講。"},{"en":"Writers use this phrase to highlight a discovery that changes their opinion.","zh":"作者用這個短語突出一個改變自己看法的發現。"},{"en":"This phrase prepares the reader for an important contrast between expectation and reality.","zh":"這個短語讓讀者準備看見期望與現實之間的重要對比。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"locked away","meaning":"被封存；被隔絕","examples":[{"en":"The Xiqu Centre did not make the art feel locked away.","zh":"戲曲中心沒有令這門藝術感覺被封存或隔絕。"},{"en":"Locked away means kept separate, hidden, or difficult for ordinary people to reach.","zh":"Locked away 指被分隔、收藏起來，或普通人難以接觸。"},{"en":"A tradition feels locked away if only experts can understand or practise it.","zh":"如果只有專家能理解或實踐某種傳統，它就會感覺被封存。"},{"en":"Museums can avoid making history feel locked away by using clear stories and examples.","zh":"博物館可以透過清楚故事和例子，避免令歷史感覺被隔絕。"},{"en":"This phrase is useful when something valuable seems closed off from newcomers.","zh":"當有價值的東西似乎不向初接觸者開放時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"make room for","meaning":"為……留出空間","examples":[{"en":"The Xiqu Centre made room for newcomers.","zh":"戲曲中心為初次接觸的人留出空間。"},{"en":"To make room for someone means to include them and give them space to join or understand.","zh":"To make room for someone 指包容某人，並給予他們加入或理解的空間。"},{"en":"A good teacher makes room for shy students by giving them time to answer.","zh":"好老師會給害羞學生時間回答，為他們留出空間。"},{"en":"Cultural venues make room for newcomers when they provide summaries, signs, and friendly explanations.","zh":"文化場地提供簡介、指示和友善解釋時，就是為新來者留出空間。"},{"en":"This phrase suggests welcome, not just physical space.","zh":"這個短語暗示歡迎，不只是實際空間。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"newcomers","meaning":"初次接觸的人","examples":[{"en":"The Xiqu Centre made room for newcomers.","zh":"戲曲中心為初次接觸的人留出空間。"},{"en":"Newcomers are people who are new to a place, activity, subject, or community.","zh":"Newcomers 指新來到某地方、活動、課題或社群的人。"},{"en":"Newcomers to Chinese opera may need a story summary before the show begins.","zh":"初次接觸中國戲曲的人可能需要在表演前閱讀故事簡介。"},{"en":"If a club ignores newcomers, they may feel embarrassed and leave quickly.","zh":"如果社團忽視新來者，他們可能會感到尷尬並很快離開。"},{"en":"This word is useful when talking about inclusion and first experiences.","zh":"這個詞適合用來談包容和初次經驗。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"a tiny movement of the hand","meaning":"手部一個細微動作","examples":[{"en":"A tiny movement of the hand could reveal rank, anger, or grief.","zh":"手部一個細微動作可以顯示身份、憤怒或悲傷。"},{"en":"A tiny movement of the hand means a very small gesture that can still carry meaning.","zh":"A tiny movement of the hand 指很細小但仍能帶有意義的手勢。"},{"en":"A teacher’s tiny movement of the hand can tell students to wait quietly.","zh":"老師手部一個細微動作可以叫學生安靜等待。"},{"en":"On stage, a tiny movement of the hand may show emotion more clearly than a long speech.","zh":"在舞台上，手部一個細微動作可能比長篇說話更清楚表現情感。"},{"en":"This phrase teaches students that small physical details can be important.","zh":"這個短語教學生明白細小身體細節也可以很重要。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"reveal rank, anger or grief","meaning":"顯示身份、憤怒或悲傷","examples":[{"en":"A tiny movement of the hand could reveal rank, anger, or grief.","zh":"手部一個細微動作可以顯示身份、憤怒或悲傷。"},{"en":"To reveal rank, anger or grief means to show a character’s status, emotion, or sadness without direct explanation.","zh":"To reveal rank, anger or grief 指不用直接說明，也能顯示角色地位、情緒或悲傷。"},{"en":"A soldier’s posture can reveal rank, anger or grief before he says anything.","zh":"士兵的姿勢可以在他說話前顯示身份、憤怒或悲傷。"},{"en":"In theatre, gestures reveal rank, anger or grief so the audience can understand the story visually.","zh":"在戲劇中，手勢能顯示身份、憤怒或悲傷，讓觀眾以視覺理解故事。"},{"en":"This phrase shows how body language can communicate hidden meaning.","zh":"這個短語顯示身體語言可以傳達隱藏意義。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"rank","meaning":"身份；地位","examples":[{"en":"A movement of the hand could reveal a character’s rank.","zh":"一個手勢可以顯示角色的身份或地位。"},{"en":"Rank means someone’s position or level in a group, society, army, or organisation.","zh":"Rank 指某人在群體、社會、軍隊或組織中的位置或級別。"},{"en":"A manager’s rank in a company may give them authority to make decisions.","zh":"經理在公司的地位可能給予他們作決定的權力。"},{"en":"In a play, costume can show rank before the character speaks.","zh":"在戲劇中，服裝可以在角色開口前顯示身份。"},{"en":"This word helps describe social position, not just personal quality.","zh":"這個詞幫助描述社會位置，而不只是個人特質。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"grief","meaning":"悲傷","examples":[{"en":"A tiny movement could reveal grief.","zh":"一個細微動作可以顯示悲傷。"},{"en":"Grief means deep sadness, especially after loss or painful separation.","zh":"Grief 指深切悲傷，特別是在失去或痛苦分離之後。"},{"en":"A child may feel grief after a pet dies.","zh":"寵物去世後，孩子可能會感到悲傷。"},{"en":"In a performance, grief can be shown through silence, slow movement, or a lowered head.","zh":"在表演中，悲傷可以透過沉默、緩慢動作或低頭表現。"},{"en":"This word is stronger than ordinary sadness because it suggests emotional pain.","zh":"這個詞比普通傷心更強烈，因為它暗示情感上的痛苦。"}],"source":"2020 Q9.pdf","sourcePage":5},{"front":"not to worry about","meaning":"不必擔心","examples":[{"en":"Chris told me not to worry about understanding everything.","zh":"Chris 告訴我不必擔心理解所有事情。"},{"en":"“Not to worry about” means not to feel anxious about something.","zh":"“Not to worry about” 指不要為某事感到焦慮。"},{"en":"The guide told visitors not to worry about knowing every historical detail.","zh":"導賞員告訴訪客不必擔心知道每個歷史細節。"},{"en":"Beginners learn better when they are told not to worry about making small mistakes.","zh":"初學者被告知不必擔心犯小錯時，會學得更好。"},{"en":"This phrase is often used to comfort someone before a difficult task.","zh":"這個短語常用來在困難任務前安慰別人。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"few, if any","meaning":"即使有，也很少","examples":[{"en":"Few, if any, first-time visitors could catch every reference.","zh":"首次到訪的人即使有，也很少能聽懂每個典故。"},{"en":"“Few, if any” means almost none, and possibly none at all.","zh":"“Few, if any” 指幾乎沒有，甚至可能完全沒有。"},{"en":"Few, if any, students understand a whole subject after only one lesson.","zh":"學生即使有，也很少能在一堂課後理解整個課題。"},{"en":"Few, if any, beginners can play a difficult song perfectly on the first try.","zh":"初學者即使有，也很少能第一次就完美彈奏困難歌曲。"},{"en":"This phrase makes a statement cautious but still strong.","zh":"這個短語令說法謹慎，但仍然有力。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"first-time visitors","meaning":"首次到訪的人","examples":[{"en":"Few first-time visitors could catch every reference.","zh":"首次到訪的人很少能聽懂每個典故。"},{"en":"First-time visitors are people who are visiting a place or experiencing something for the first time.","zh":"First-time visitors 指第一次到某地方或第一次經歷某事的人。"},{"en":"First-time visitors to a temple may need signs explaining the customs.","zh":"首次到寺廟的人可能需要解釋習俗的指示牌。"},{"en":"If first-time visitors feel welcomed, they are more likely to return.","zh":"如果首次到訪的人感到受歡迎，他們更可能再來。"},{"en":"This phrase is useful when discussing accessibility and clear guidance.","zh":"這個短語適合用來討論易接近程度和清楚指引。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"catch every reference","meaning":"聽懂每個典故","examples":[{"en":"Few first-time visitors could catch every reference.","zh":"首次到訪的人很少能聽懂每個典故。"},{"en":"To catch every reference means to understand every allusion, cultural hint, or hidden meaning.","zh":"To catch every reference 指理解每個典故、文化暗示或隱藏意思。"},{"en":"Viewers may not catch every reference in a historical film without background knowledge.","zh":"沒有背景知識，觀眾可能無法聽懂歷史電影中的每個典故。"},{"en":"Teachers explain difficult poems because students cannot catch every reference alone.","zh":"老師解釋困難詩歌，因為學生不能單靠自己聽懂每個典故。"},{"en":"This phrase is useful when meaning depends on culture, history, or shared knowledge.","zh":"當意思依賴文化、歷史或共同知識時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"patient explanations","meaning":"耐心的解釋","examples":[{"en":"Chris’s patient explanations gave me confidence to stay open.","zh":"Chris 耐心的解釋給了我保持開放態度的信心。"},{"en":"Patient explanations are calm, clear explanations given without rushing or making someone feel foolish.","zh":"Patient explanations 指不催促、不令人覺得愚蠢的平靜清楚解釋。"},{"en":"A tutor’s patient explanations can help a child understand maths step by step.","zh":"補習老師耐心的解釋可以幫助孩子一步一步理解數學。"},{"en":"Patient explanations reduce fear because learners feel allowed to ask questions.","zh":"耐心的解釋能減少恐懼，因為學習者覺得可以提問。"},{"en":"This phrase shows that kindness can make difficult knowledge easier to receive.","zh":"這個短語顯示善意可以令人更容易接受困難知識。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"give someone enough confidence to","meaning":"給予某人足夠信心去","examples":[{"en":"The setting gave me enough confidence to stay open.","zh":"那個環境給了我足夠信心去保持開放態度。"},{"en":"To give someone enough confidence to do something means to make them feel safe or able enough to try it.","zh":"To give someone enough confidence to do something 指令人覺得足夠安全或有能力去嘗試某事。"},{"en":"Clear instructions gave the new student enough confidence to join the activity.","zh":"清楚指示給了新同學足夠信心去參加活動。"},{"en":"Support from friends can give someone enough confidence to speak in public.","zh":"朋友支持可以給某人足夠信心去公開演說。"},{"en":"This phrase connects encouragement with the action that follows.","zh":"這個短語把鼓勵和之後的行動連接起來。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"stay open","meaning":"保持開放態度","examples":[{"en":"His explanations gave me enough confidence to stay open.","zh":"他的解釋給了我足夠信心去保持開放態度。"},{"en":"To stay open means to keep a willing and curious attitude instead of rejecting something too quickly.","zh":"To stay open 指保持願意了解和好奇的態度，而不是太快拒絕某事。"},{"en":"Students should stay open when they hear opinions different from their own.","zh":"學生聽到與自己不同的意見時，應保持開放態度。"},{"en":"If you stay open during a new experience, confusion may slowly become understanding.","zh":"如果你在新經歷中保持開放態度，困惑可能慢慢變成理解。"},{"en":"This phrase is often about attitude, not physical openness.","zh":"這個短語通常指態度，而不是實際打開。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"the curtain rose","meaning":"幕布升起","examples":[{"en":"Then the curtain rose, and my doubts began to fall away.","zh":"然後幕布升起，我的疑慮開始消散。"},{"en":"The curtain rose means the stage curtain went up and the performance began.","zh":"The curtain rose 指舞台幕布升起，表演開始。"},{"en":"When the curtain rose, the audience stopped talking and watched carefully.","zh":"幕布升起時，觀眾停止交談，專心觀看。"},{"en":"The moment the curtain rose can change the mood from waiting to full attention.","zh":"幕布升起的一刻可以把氣氛由等待轉為全神貫注。"},{"en":"This phrase often marks the official start of a stage performance.","zh":"這個短語常標示舞台表演正式開始。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"doubts began to fall away","meaning":"疑慮開始消散","examples":[{"en":"My doubts began to fall away after the curtain rose.","zh":"幕布升起後，我的疑慮開始消散。"},{"en":"“Doubts began to fall away” means worries or negative expectations slowly started to disappear.","zh":"“Doubts began to fall away” 指憂慮或負面預期慢慢開始消失。"},{"en":"My doubts began to fall away when the teacher explained the task clearly.","zh":"當老師清楚解釋任務時，我的疑慮開始消散。"},{"en":"A nervous audience member’s doubts may fall away when the performance becomes moving.","zh":"當表演變得動人，緊張觀眾的疑慮可能會消散。"},{"en":"This phrase is useful when confidence replaces uncertainty.","zh":"當信心取代不確定時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"at first","meaning":"起初","examples":[{"en":"At first, the singing startled me.","zh":"起初，那種唱腔令我吃驚。"},{"en":"At first means in the beginning, before later change or understanding.","zh":"At first 指一開始，在之後改變或理解之前。"},{"en":"At first, the new school felt confusing, but I soon found friendly classmates.","zh":"起初，新學校令人困惑，但我很快找到友善同學。"},{"en":"People often dislike unfamiliar sounds at first because they do not know how to listen yet.","zh":"人們起初常不喜歡陌生聲音，因為他們還不知道如何聆聽。"},{"en":"This phrase helps compare an early reaction with a later one.","zh":"這個短語幫助比較早期反應和後來反應。"}],"source":"2020 Q9.pdf","sourcePage":6},{"front":"startled me","meaning":"令我吃驚","examples":[{"en":"The singing startled me at first.","zh":"起初，那種唱腔令我吃驚。"},{"en":"Startled me means surprised me suddenly, often because something was unexpected.","zh":"Startled me 指突然令我驚訝，通常因為事情出乎意料。"},{"en":"The fire alarm startled me during the quiet exam.","zh":"安靜考試期間，火警鐘聲令我吃驚。"},{"en":"A loud drumbeat can startle an audience before they understand its purpose.","zh":"觀眾理解其作用前，響亮鼓聲可能會令他們吃驚。"},{"en":"This phrase is stronger than “surprised me” because it suggests a sudden physical reaction.","zh":"這個短語比 “surprised me” 更強，因為它暗示突然的身體反應。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"grow used to","meaning":"逐漸習慣","examples":[{"en":"I wondered whether I could grow used to the singing.","zh":"我 wondered 自己能否逐漸習慣那種唱腔。"},{"en":"To grow used to something means to become familiar with it gradually.","zh":"To grow used to something 指逐漸熟悉並習慣某事物。"},{"en":"A new student may grow used to the school timetable after a few weeks.","zh":"新學生可能在幾星期後逐漸習慣學校時間表。"},{"en":"People can grow used to unfamiliar music if they listen patiently and often.","zh":"如果人們有耐性而且經常聆聽，就可以逐漸習慣陌生音樂。"},{"en":"This phrase shows change through time, not instant comfort.","zh":"這個短語顯示經過時間才改變，而不是立即感到舒服。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"the longer…, the more…","meaning":"越……就越……","examples":[{"en":"The longer I watched, the more I realised what the voice was carrying.","zh":"我看得越久，就越明白那聲音承載着甚麼。"},{"en":"“The longer…, the more…” shows that one change increases as another situation continues.","zh":"“The longer…, the more…” 表示一種變化會隨着另一情況持續而增加。"},{"en":"The longer students practise speaking, the more confident they become.","zh":"學生練習說話越久，就越有信心。"},{"en":"The longer you listen to a culture patiently, the more meaning you notice.","zh":"你越有耐性地聆聽一種文化，就越注意到其中意義。"},{"en":"This structure clearly links time or effort with growing understanding.","zh":"這個結構清楚連接時間或努力與逐漸增加的理解。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"not merely singing","meaning":"不只是唱歌","examples":[{"en":"The voice was not merely singing.","zh":"那聲音不只是唱歌。"},{"en":"Not merely singing means the voice was doing more than producing music; it was carrying emotion and meaning.","zh":"Not merely singing 指那聲音不只是發出音樂，而是在承載情感和意思。"},{"en":"In the play, the mother was not merely singing but expressing years of pain.","zh":"在劇中，那位母親不只是唱歌，而是在表達多年的痛苦。"},{"en":"A performer is not merely singing when each note reveals a character’s hope or fear.","zh":"當每個音符都顯示角色的希望或恐懼，表演者就不只是唱歌。"},{"en":"This phrase helps show that an action has deeper artistic purpose.","zh":"這個短語幫助顯示一個動作有更深層的藝術目的。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"carrying pain, pride and longing","meaning":"承載痛苦、驕傲和渴望","examples":[{"en":"The voice was carrying pain, pride, and longing across the stage.","zh":"那聲音把痛苦、驕傲和渴望帶過整個舞台。"},{"en":"Carrying pain, pride and longing means expressing strong sadness, dignity, and desire through sound or performance.","zh":"Carrying pain, pride and longing 指透過聲音或表演表達強烈悲傷、尊嚴和渴望。"},{"en":"A farewell song may carry pain, pride and longing when a character leaves home.","zh":"當角色離開家鄉，告別歌曲可能承載痛苦、驕傲和渴望。"},{"en":"Music can carry pain, pride and longing so clearly that listeners understand before any words are translated.","zh":"音樂可以清楚承載痛苦、驕傲和渴望，讓聽眾在翻譯前已理解。"},{"en":"This phrase shows that emotion can travel through voice.","zh":"這個短語顯示情感可以透過聲音傳遞。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"longing","meaning":"渴望；思念","examples":[{"en":"The voice carried pain, pride, and longing across the stage.","zh":"那聲音把痛苦、驕傲和渴望帶過整個舞台。"},{"en":"Longing means a strong wish for someone or something that is absent or far away.","zh":"Longing 指對不在身邊或遙遠的人或事物有強烈渴望。"},{"en":"A student studying overseas may feel longing for family dinners at home.","zh":"在海外讀書的學生可能會思念家中的晚飯。"},{"en":"Longing can appear in music when the melody sounds like it is reaching for something lost.","zh":"當旋律像在追尋失去的東西，音樂中可能會出現 longing。"},{"en":"This word is deeper than “want” because it includes emotion and distance.","zh":"這個詞比 “want” 更深，因為它包含情感和距離。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"across the stage","meaning":"橫越舞台","examples":[{"en":"The voice carried emotion across the stage.","zh":"那聲音把情感帶過整個舞台。"},{"en":"Across the stage means from one side of the performance space to another, or throughout the stage area.","zh":"Across the stage 指從表演空間一邊到另一邊，或遍及整個舞台範圍。"},{"en":"The dancer moved slowly across the stage while the audience stayed silent.","zh":"舞者慢慢橫越舞台，而觀眾保持沉默。"},{"en":"A strong voice can travel across the stage and fill the hall.","zh":"有力的聲音可以橫越舞台並充滿大廳。"},{"en":"This phrase helps readers imagine movement or sound in a theatre.","zh":"這個短語幫助讀者想像劇院中的動作或聲音。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"flicked like a wave","meaning":"像浪一樣一甩","examples":[{"en":"A sleeve flicked like a wave.","zh":"袖子像浪一樣一甩。"},{"en":"Flicked like a wave means moved quickly and smoothly, like water rising and falling.","zh":"Flicked like a wave 指快速而流暢地移動，像水浪起伏。"},{"en":"The dancer’s scarf flicked like a wave when she turned.","zh":"舞者轉身時，圍巾像浪一樣一甩。"},{"en":"A small stage movement can look powerful if it flicks like a wave.","zh":"如果細小舞台動作像浪一樣一甩，也可以顯得有力量。"},{"en":"This phrase uses a simple image to show graceful motion.","zh":"這個短語用簡單意象展示優美動作。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"a fan opened","meaning":"扇子打開","examples":[{"en":"A fan opened, and suddenly a character seemed powerful.","zh":"扇子打開，角色突然顯得有力量。"},{"en":"A fan opened describes the action of spreading out a folded fan, often as a meaningful stage gesture.","zh":"A fan opened 描述摺扇展開的動作，常是有意義的舞台手勢。"},{"en":"When a fan opened in the actor’s hand, the audience understood the character’s confidence.","zh":"當演員手中的扇子打開，觀眾理解角色的自信。"},{"en":"In Chinese opera, a fan opening can change how a character appears.","zh":"在中國戲曲中，扇子打開可以改變角色呈現出來的感覺。"},{"en":"This phrase shows how a small object can affect meaning on stage.","zh":"這個短語顯示小道具如何影響舞台意義。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"a slow step across the stage","meaning":"橫過舞台的緩慢步伐","examples":[{"en":"A slow step across the stage stretched time.","zh":"橫過舞台的緩慢步伐像拉長了時間。"},{"en":"A slow step across the stage means a deliberate, unhurried movement from one part of the stage to another.","zh":"A slow step across the stage 指從舞台一處到另一處的刻意、從容動作。"},{"en":"A slow step across the stage can make the audience feel a character’s fear or dignity.","zh":"橫過舞台的緩慢步伐可以令觀眾感到角色的恐懼或尊嚴。"},{"en":"When movement is slow, viewers notice balance, costume, and emotion more carefully.","zh":"當動作緩慢，觀眾會更細心留意平衡、服裝和情感。"},{"en":"This phrase shows how pace can create dramatic meaning.","zh":"這個短語顯示節奏如何創造戲劇意義。"}],"source":"2020 Q9.pdf","sourcePage":7},{"front":"stretch time","meaning":"拉長時間","examples":[{"en":"A slow step across the stage seemed to stretch time.","zh":"橫過舞台的緩慢步伐似乎拉長了時間。"},{"en":"To stretch time means to make a moment feel longer, slower, or more intense.","zh":"To stretch time 指令某一刻感覺更長、更慢或更強烈。"},{"en":"Waiting for exam results can seem to stretch time because every minute feels heavy.","zh":"等待考試結果可能像拉長時間，因為每一分鐘都很沉重。"},{"en":"A silent pause in a film may stretch time before an important decision.","zh":"電影中的沉默停頓可以在重要決定前拉長時間。"},{"en":"This phrase describes how emotion changes our feeling of time.","zh":"這個短語描述情感如何改變我們對時間的感覺。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"even silence felt meaningful","meaning":"連沉默也變得有意義","examples":[{"en":"The performance stretched time until even silence felt meaningful.","zh":"表演把時間拉長，直到連沉默也變得有意義。"},{"en":"Even silence felt meaningful means quiet moments seemed full of emotion or purpose.","zh":"Even silence felt meaningful 指安靜時刻也像充滿情感或目的。"},{"en":"During the apology, even silence felt meaningful because everyone understood the pain.","zh":"在道歉期間，連沉默也變得有意義，因為大家都明白其中痛苦。"},{"en":"In good theatre, even silence can feel meaningful when it gives the audience time to think.","zh":"在好的戲劇中，當沉默給觀眾思考時間，連沉默也可以變得有意義。"},{"en":"This phrase shows that meaning can come from absence of sound.","zh":"這個短語顯示意義也可以來自沒有聲音。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, the percussion controlled the pulse of the story.","zh":"與此同時，敲擊樂控制着故事的節奏。"},{"en":"Meanwhile means at the same time or during that same period.","zh":"Meanwhile 指在同一時間或同一段期間。"},{"en":"The actors moved slowly; meanwhile, the drums created tension.","zh":"演員慢慢移動；與此同時，鼓聲製造緊張感。"},{"en":"Writers use meanwhile to show two connected things happening together.","zh":"作者用 meanwhile 來展示兩件相關事情同時發生。"},{"en":"This word helps organise events without making the timeline confusing.","zh":"這個詞幫助組織事件，而不令時間線混亂。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"percussion","meaning":"敲擊樂","examples":[{"en":"The percussion did not simply accompany the actors.","zh":"敲擊樂不只是為演員伴奏。"},{"en":"Percussion means musical instruments that are played by being hit, shaken, or struck.","zh":"Percussion 指透過敲打、搖動或擊打發聲的樂器。"},{"en":"Drums, gongs, and wooden clappers are common forms of percussion.","zh":"鼓、鑼和木拍板都是常見的敲擊樂。"},{"en":"Percussion can control rhythm, create tension, and signal sudden action on stage.","zh":"敲擊樂可以控制節奏、製造緊張感，並提示舞台上的突然動作。"},{"en":"This word is useful when describing music that strongly affects pace.","zh":"這個詞適合用來描述強烈影響節奏的音樂。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"accompany the actors","meaning":"為演員伴奏","examples":[{"en":"The percussion did not simply accompany the actors.","zh":"敲擊樂不只是為演員伴奏。"},{"en":"To accompany the actors means to play music alongside the performers as they move, sing, or speak.","zh":"To accompany the actors 指在表演者動作、唱歌或說話時，用音樂配合他們。"},{"en":"A pianist may accompany the actors during a school musical.","zh":"在學校音樂劇中，鋼琴師可能會為演員伴奏。"},{"en":"Music that accompanies the actors can support emotion without taking attention away from them.","zh":"為演員伴奏的音樂可以支持情感，而不搶走他們的焦點。"},{"en":"This phrase describes support, but the support may still be powerful.","zh":"這個短語描述支持作用，但這種支持仍可以很有力量。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"control the pulse of the story","meaning":"控制故事的節奏","examples":[{"en":"The percussion controlled the pulse of the story.","zh":"敲擊樂控制着故事的節奏。"},{"en":"To control the pulse of the story means to guide its rhythm, speed, and emotional heartbeat.","zh":"To control the pulse of the story 指引導故事的節奏、速度和情感脈搏。"},{"en":"In a film, background music can control the pulse of the story by making scenes feel urgent or calm.","zh":"在電影中，背景音樂可以透過令場面緊急或平靜，控制故事的節奏。"},{"en":"Drums can control the pulse of the story when they speed up during a fight scene.","zh":"打鬥場面中鼓聲加快時，可以控制故事的節奏。"},{"en":"This phrase connects music with storytelling structure.","zh":"這個短語把音樂和敘事結構連接起來。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"one moment…, the next…","meaning":"前一刻……下一刻……","examples":[{"en":"One moment, the wooden clappers made my heart jump; the next, the strings softened the scene.","zh":"前一刻，木拍板令我心頭一震；下一刻，弦樂又把場面柔和下來。"},{"en":"“One moment…, the next…” shows a quick change from one situation or feeling to another.","zh":"“One moment…, the next…” 表示一種情況或感覺很快轉到另一種。"},{"en":"One moment, the classroom was noisy; the next, everyone became silent for the announcement.","zh":"前一刻，課室很嘈吵；下一刻，大家因廣播而安靜下來。"},{"en":"Performances use sudden contrast when one moment feels tense and the next feels gentle.","zh":"表演會運用突然對比，前一刻緊張，下一刻溫柔。"},{"en":"This structure helps describe fast emotional shifts.","zh":"這個結構幫助描述快速的情感轉變。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"wooden clappers","meaning":"木拍板","examples":[{"en":"The wooden clappers made my heart jump.","zh":"木拍板令我心頭一震。"},{"en":"Wooden clappers are percussion instruments made of wood that create sharp rhythmic sounds.","zh":"Wooden clappers 是用木製成的敲擊樂器，會發出清脆有節奏的聲音。"},{"en":"Wooden clappers can signal sudden action in a stage performance.","zh":"木拍板可以在舞台表演中提示突然動作。"},{"en":"Their sharp sound may surprise the audience and make a quiet scene feel urgent.","zh":"它清脆的聲音可能令觀眾吃驚，並令安靜場面變得緊急。"},{"en":"This phrase names an instrument that controls rhythm and attention.","zh":"這個短語指出一種控制節奏和注意力的樂器。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"make my heart jump","meaning":"令我心頭一震","examples":[{"en":"The wooden clappers made my heart jump.","zh":"木拍板令我心頭一震。"},{"en":"To make my heart jump means to startle me so suddenly that I feel a physical shock.","zh":"To make my heart jump 指突然嚇到我，令我感到身體上的一震。"},{"en":"The sudden knock on the door made my heart jump.","zh":"突然的敲門聲令我心頭一震。"},{"en":"A loud sound can make my heart jump when I am already nervous.","zh":"當我本來已緊張，響亮聲音可以令我心頭一震。"},{"en":"This phrase describes surprise that is felt in the body.","zh":"這個短語描述身體感受到的驚嚇。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"the strings","meaning":"弦樂","examples":[{"en":"The strings softened the scene gently.","zh":"弦樂輕柔地令場面柔和下來。"},{"en":"The strings are string instruments, such as violins or traditional bowed instruments, used to create musical tone.","zh":"The strings 指弦樂器，例如小提琴或傳統拉弦樂器，用來製造音色。"},{"en":"The strings played softly while the actor stood alone on stage.","zh":"演員獨自站在舞台上時，弦樂輕柔響起。"},{"en":"Strings can make a sad scene feel warmer and more human.","zh":"弦樂可以令悲傷場面感覺更溫暖、更有人情味。"},{"en":"This phrase usually refers to a group of string instruments in music.","zh":"這個短語通常指音樂中的一組弦樂器。"}],"source":"2020 Q9.pdf","sourcePage":8},{"front":"soften the scene","meaning":"令場面柔和下來","examples":[{"en":"The strings softened the scene so gently that the hall seemed to hold its breath.","zh":"弦樂如此輕柔地令場面柔和下來，整個大廳彷彿屏息靜氣。"},{"en":"To soften the scene means to make a moment feel calmer, gentler, or less harsh.","zh":"To soften the scene 指令某一刻變得更平靜、更溫柔或不那麼強烈。"},{"en":"Soft lighting can soften the scene after an argument in a film.","zh":"在電影爭吵後，柔和燈光可以令場面柔和下來。"},{"en":"Music may soften the scene so the audience feels sympathy instead of fear.","zh":"音樂可能令場面柔和下來，讓觀眾感到同情而不是恐懼。"},{"en":"This phrase describes how artistic choices change mood.","zh":"這個短語描述藝術選擇如何改變氣氛。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"hold its breath","meaning":"屏息靜氣","examples":[{"en":"The hall seemed to hold its breath.","zh":"整個大廳彷彿屏息靜氣。"},{"en":"To hold its breath means to become extremely still and quiet, as if waiting for something important.","zh":"To hold its breath 指變得極安靜、靜止，好像在等待重要事情。"},{"en":"The classroom seemed to hold its breath while the teacher opened the exam results.","zh":"老師打開考試成績時，課室彷彿屏息靜氣。"},{"en":"An audience may hold its breath during a dangerous or emotional moment.","zh":"在危險或情感強烈的一刻，觀眾可能會屏息靜氣。"},{"en":"This phrase gives a place human-like feeling to show tension or wonder.","zh":"這個短語賦予地方人的感覺，以表現緊張或驚嘆。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"cannot begin to describe","meaning":"無法充分描述","examples":[{"en":"I cannot begin to describe every detail.","zh":"我無法充分描述每一個細節。"},{"en":"“Cannot begin to describe” means something is too rich, strong, or complex to explain fully.","zh":"“Cannot begin to describe” 指某事太豐富、強烈或複雜，無法完全說清楚。"},{"en":"I cannot begin to describe how relieved I felt after finding my lost wallet.","zh":"找回失去的錢包後，我無法充分描述自己的安心。"},{"en":"People use this phrase when ordinary words feel too small for an experience.","zh":"當普通文字不足以表達經歷時，人們會用這個短語。"},{"en":"This phrase admits the limits of description.","zh":"這個短語承認描述能力有限。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"one image remains","meaning":"有一個畫面仍然留在腦海","examples":[{"en":"One image remains in my mind.","zh":"有一個畫面仍然留在我的腦海。"},{"en":"“One image remains” means one scene or picture is still clearly remembered.","zh":"“One image remains” 指某個場景或畫面仍然被清楚記得。"},{"en":"One image remains from the school trip: an old man feeding birds beside the river.","zh":"學校旅行有一個畫面仍留在腦海：一位老人坐在河邊餵鳥。"},{"en":"A powerful performance can leave one image remaining in the audience’s memory for years.","zh":"有力的表演可以令一個畫面多年後仍留在觀眾記憶中。"},{"en":"This phrase helps writers focus on the most unforgettable detail.","zh":"這個短語幫助作者集中在最難忘的細節。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"a warrior","meaning":"武士；戰士","examples":[{"en":"A warrior stood still under bright light.","zh":"一位武士站在強光下不動。"},{"en":"A warrior is a fighter or soldier, especially one shown as brave, fierce, or skilled.","zh":"A warrior 指戰士或士兵，特別是勇敢、兇猛或有技巧的人。"},{"en":"In a historical drama, a warrior may protect the city during war.","zh":"在歷史劇中，武士可能在戰爭中保護城市。"},{"en":"A warrior’s costume can show strength before the character even moves.","zh":"武士的服裝可以在角色動作前先顯示力量。"},{"en":"This word often appears in stories, legends, and stage performances.","zh":"這個詞常出現在故事、傳說和舞台表演中。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"standing still","meaning":"站着不動","examples":[{"en":"A warrior was standing still under bright light.","zh":"一位武士在強光下站着不動。"},{"en":"Standing still means not moving while remaining upright.","zh":"Standing still 指直立但沒有移動。"},{"en":"The children had to stand still while the photographer took the class photo.","zh":"攝影師拍班相時，孩子們要站着不動。"},{"en":"On stage, standing still can create tension because the audience waits for the next movement.","zh":"在舞台上，站着不動可以製造緊張感，因為觀眾等待下一個動作。"},{"en":"This phrase can show control, fear, patience, or dramatic focus.","zh":"這個短語可以表現控制、恐懼、耐性或戲劇焦點。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"under bright light","meaning":"在強光下","examples":[{"en":"A warrior stood still under bright light.","zh":"一位武士在強光下站着不動。"},{"en":"Under bright light means in a strongly lit place where details can be clearly seen.","zh":"Under bright light 指在強烈燈光照射、細節能被清楚看見的地方。"},{"en":"The actor’s painted face looked dramatic under bright light.","zh":"演員的臉譜在強光下顯得很有戲劇感。"},{"en":"Bright light can make a stage figure look powerful, exposed, or lonely.","zh":"強光可以令舞台人物顯得有力量、暴露或孤獨。"},{"en":"This phrase helps describe visibility and stage atmosphere.","zh":"這個短語有助描述可見度和舞台氣氛。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"looked fierce and sorrowful at once","meaning":"同時顯得兇猛而哀傷","examples":[{"en":"The warrior’s painted face looked fierce and sorrowful at once.","zh":"那位武士的臉譜同時顯得兇猛而哀傷。"},{"en":"Looked fierce and sorrowful at once means appeared both frighteningly strong and deeply sad at the same time.","zh":"Looked fierce and sorrowful at once 指同時顯得可怕有力又深深悲傷。"},{"en":"A soldier in a war film may look fierce and sorrowful at once after losing a friend.","zh":"戰爭電影中的士兵失去朋友後，可能同時顯得兇猛而哀傷。"},{"en":"Make-up and expression can make a character look fierce and sorrowful at once.","zh":"化妝和表情可以令角色同時顯得兇猛而哀傷。"},{"en":"This phrase is useful for describing mixed emotions.","zh":"這個短語適合描述混合情緒。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"at once","meaning":"同時","examples":[{"en":"His painted face looked fierce and sorrowful at once.","zh":"他的臉譜同時顯得兇猛而哀傷。"},{"en":"At once can mean at the same time when describing two qualities together.","zh":"At once 在描述兩種特質時，可以指同時。"},{"en":"The old house felt beautiful and lonely at once.","zh":"那間老房子同時令人覺得美麗而孤單。"},{"en":"A good performance may make the audience feel excited and sad at once.","zh":"好表演可能令觀眾同時感到興奮和悲傷。"},{"en":"This phrase helps join two feelings that exist together.","zh":"這個短語幫助連接同時存在的兩種感受。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"the final bow","meaning":"謝幕","examples":[{"en":"The real impact of the evening dawned on me only after the final bow.","zh":"直到謝幕後，那晚真正的影響才使我恍然大悟。"},{"en":"The final bow is the performers’ last bow to the audience at the end of a show.","zh":"The final bow 指表演結束時，演員最後一次向觀眾鞠躬。"},{"en":"After the final bow, the audience stood up and clapped loudly.","zh":"謝幕後，觀眾站起來熱烈拍掌。"},{"en":"Sometimes the meaning of a performance becomes clear only after the final bow.","zh":"有時表演的意義要到謝幕後才變得清楚。"},{"en":"This phrase marks the formal ending of a stage experience.","zh":"這個短語標示舞台經歷的正式結束。"}],"source":"2020 Q9.pdf","sourcePage":9},{"front":"the real impact","meaning":"真正的影響","examples":[{"en":"The real impact of the evening dawned on me after the final bow.","zh":"謝幕後，那晚真正的影響才使我恍然大悟。"},{"en":"The real impact means the true effect or importance of an experience.","zh":"The real impact 指一段經歷真正的作用或重要性。"},{"en":"The real impact of the lesson appeared when students used the idea in daily life.","zh":"當學生在日常生活中使用那個概念時，課堂真正的影響才出現。"},{"en":"A journey’s real impact may not be clear until you return home and think about it.","zh":"旅程真正的影響可能要到回家後思考才清楚。"},{"en":"This phrase separates deep influence from immediate reaction.","zh":"這個短語把深層影響和即時反應分開。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"dawn on me","meaning":"使我恍然大悟","examples":[{"en":"The real impact of the evening dawned on me after the final bow.","zh":"謝幕後，那晚真正的影響才使我恍然大悟。"},{"en":"To dawn on me means to become clear to me gradually or suddenly.","zh":"To dawn on me 指某事逐漸或突然變得清楚，使我明白。"},{"en":"It dawned on me that I had judged the film before understanding it.","zh":"我恍然大悟，自己在理解電影前已經先作判斷。"},{"en":"A solution may dawn on a student after they look at the problem from another angle.","zh":"當學生從另一角度看問題時，解決方法可能會使他恍然大悟。"},{"en":"This phrase often describes a moment of realisation.","zh":"這個短語常描述突然明白的一刻。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"mistake unfamiliarity for boredom","meaning":"把陌生誤以為沉悶","examples":[{"en":"I had mistaken unfamiliarity for boredom.","zh":"我曾把陌生誤以為沉悶。"},{"en":"To mistake unfamiliarity for boredom means to think something is boring only because it is new or hard to understand.","zh":"To mistake unfamiliarity for boredom 指只因某事新奇或難懂，就以為它沉悶。"},{"en":"A student may mistake classical music for boredom before learning how to listen to it.","zh":"學生學會如何聆聽古典音樂前，可能把陌生誤以為沉悶。"},{"en":"People often mistake unfamiliarity for boredom when a culture uses signs they do not yet understand.","zh":"當一種文化使用人們還不理解的符號時，人們常把陌生誤以為沉悶。"},{"en":"This phrase warns against judging too quickly.","zh":"這個短語提醒人不要太快判斷。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"assume that","meaning":"以為；假設","examples":[{"en":"I had assumed that the art would have little to offer me.","zh":"我曾以為這門藝術沒有甚麼可給予我。"},{"en":"To assume that means to believe something is true without enough proof.","zh":"To assume that 指在沒有足夠證據下相信某事是真的。"},{"en":"I assumed that the lecture would be boring, but the speaker used many real examples.","zh":"我以為講座會很沉悶，但講者用了很多真實例子。"},{"en":"People may assume that old traditions are useless before they learn their meaning.","zh":"人們學習傳統意義前，可能會以為古老傳統沒有用。"},{"en":"This phrase often introduces an idea that later proves wrong.","zh":"這個短語常引出後來被證明錯誤的想法。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"know the codes","meaning":"懂得當中的符碼","examples":[{"en":"I did not know the codes of Chinese opera.","zh":"我不懂得中國戲曲當中的符碼。"},{"en":"To know the codes means to understand the signs, rules, or meanings used in a particular art form or culture.","zh":"To know the codes 指理解某種藝術或文化中使用的符號、規則或意思。"},{"en":"A new viewer may not know the codes of ballet, such as what certain movements suggest.","zh":"新觀眾可能不懂芭蕾舞的符碼，例如某些動作暗示甚麼。"},{"en":"If you know the codes of a performance, small gestures become easier to read.","zh":"如果你懂得表演中的符碼，細小手勢就更容易解讀。"},{"en":"This phrase shows that understanding often depends on shared symbols.","zh":"這個短語顯示理解常依賴共同符號。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"have little to offer","meaning":"沒有甚麼可給予","examples":[{"en":"I assumed that the art would have little to offer me.","zh":"我以為這門藝術沒有甚麼可給予我。"},{"en":"To have little to offer means to seem unable to give much value, interest, or help.","zh":"To have little to offer 指看似不能提供很多價值、興趣或幫助。"},{"en":"I thought the old book had little to offer until its story matched my own problem.","zh":"我以為那本舊書沒有甚麼可給予我，直到它的故事與我的問題相似。"},{"en":"A person may wrongly think a subject has little to offer because they have not explored it.","zh":"一個人可能錯誤地以為某科目沒有甚麼可給予，因為他還未探索它。"},{"en":"This phrase is useful when discussing unfair first impressions.","zh":"這個短語適合討論不公平的第一印象。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"the opposite was true","meaning":"事實剛好相反","examples":[{"en":"In fact, the opposite was true.","zh":"事實上，情況剛好相反。"},{"en":"The opposite was true means the real situation was completely different from what someone expected.","zh":"The opposite was true 指真實情況與某人預期完全相反。"},{"en":"I thought the quiet student disliked teamwork, but the opposite was true.","zh":"我以為那個安靜學生不喜歡小組合作，但事實剛好相反。"},{"en":"People may think tradition stops creativity, but sometimes the opposite is true.","zh":"人們可能以為傳統阻礙創意，但有時事實剛好相反。"},{"en":"This phrase is useful when correcting a wrong assumption.","zh":"這個短語適合用來糾正錯誤假設。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"be designed to","meaning":"被設計成用來","examples":[{"en":"Culture is not always designed to be consumed quickly.","zh":"文化不一定被設計成用來快速消費。"},{"en":"Be designed to means be made or intended for a particular purpose.","zh":"Be designed to 指被製作或安排來達到某個目的。"},{"en":"A children’s book is designed to help young readers understand ideas through simple stories.","zh":"兒童書被設計成用簡單故事幫助年輕讀者理解概念。"},{"en":"Some performances are designed to make audiences slow down and observe carefully.","zh":"有些表演被設計成讓觀眾慢下來並細心觀察。"},{"en":"This phrase connects an object, system, or activity with its intended function.","zh":"這個短語把物件、系統或活動與其預期功能連接起來。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"be consumed quickly","meaning":"被快速消費","examples":[{"en":"Culture is not always designed to be consumed quickly.","zh":"文化不一定被設計成用來快速消費。"},{"en":"To be consumed quickly means to be used, watched, or understood in a fast and surface-level way.","zh":"To be consumed quickly 指被快速而表面地使用、觀看或理解。"},{"en":"Short online videos are often designed to be consumed quickly during a break.","zh":"短網上影片常被設計成讓人在休息時快速消費。"},{"en":"Serious art may lose meaning if people expect it to be consumed quickly.","zh":"如果人們期望嚴肅藝術被快速消費，它可能會失去意義。"},{"en":"This phrase is useful for contrasting fast entertainment with slow understanding.","zh":"這個短語適合把快速娛樂與慢慢理解作對比。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"ask us to slow down","meaning":"要求我們慢下來","examples":[{"en":"Some things ask us to slow down and observe carefully.","zh":"有些事情要求我們慢下來並細心觀察。"},{"en":"“Ask us to slow down” means require us to become more patient and less hurried.","zh":"“Ask us to slow down” 指要求我們更有耐性，不那麼匆忙。"},{"en":"A quiet painting may ask us to slow down before we notice its small details.","zh":"一幅安靜的畫可能要求我們慢下來，才會注意到它的小細節。"},{"en":"Complex traditions ask us to slow down because their meanings cannot be understood immediately.","zh":"複雜傳統要求我們慢下來，因為其意義不能立刻理解。"},{"en":"This phrase gives an activity a gentle demand on our attention.","zh":"這個短語賦予活動一種對注意力的溫柔要求。"}],"source":"2020 Q9.pdf","sourcePage":10},{"front":"observe carefully","meaning":"細心觀察","examples":[{"en":"Some things ask us to slow down and observe carefully.","zh":"有些事情要求我們慢下來並細心觀察。"},{"en":"To observe carefully means to look, listen, or notice details with attention.","zh":"To observe carefully 指用心觀看、聆聽或注意細節。"},{"en":"Science students must observe carefully before writing down results.","zh":"科學學生在寫下結果前必須細心觀察。"},{"en":"In Chinese opera, viewers observe carefully to understand what a gesture or costume suggests.","zh":"在中國戲曲中，觀眾要細心觀察，才明白手勢或服裝暗示甚麼。"},{"en":"This phrase is useful when careful attention leads to better understanding.","zh":"當用心留意能帶來更好理解時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"little by little","meaning":"一點一點地","examples":[{"en":"We may understand culture little by little rather than all at once.","zh":"我們可能一點一點地理解文化，而不是一下子全部理解。"},{"en":"Little by little means gradually, in small steps over time.","zh":"Little by little 指逐漸地，經過時間一步一步發展。"},{"en":"A child learns a new language little by little through listening and practice.","zh":"孩子透過聆聽和練習，一點一點地學習新語言。"},{"en":"Difficult art becomes clearer little by little when viewers return to it patiently.","zh":"當觀眾有耐性地再次接觸，困難藝術會一點一點地變清楚。"},{"en":"This phrase shows slow progress instead of sudden success.","zh":"這個短語顯示緩慢進步，而不是突然成功。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"rather than all at once","meaning":"而不是一下子全部","examples":[{"en":"We may understand little by little rather than all at once.","zh":"我們可能一點一點地理解，而不是一下子全部理解。"},{"en":"Rather than all at once means instead of happening completely at one time.","zh":"Rather than all at once 指不是在同一時間完全發生。"},{"en":"Students often understand grammar through many examples rather than all at once.","zh":"學生通常透過很多例子理解文法，而不是一下子全部明白。"},{"en":"Cultural understanding usually grows through repeated contact rather than all at once.","zh":"文化理解通常透過反覆接觸而增長，而不是一下子全部獲得。"},{"en":"This phrase contrasts gradual learning with immediate complete understanding.","zh":"這個短語把逐步學習與即時完全理解作對比。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"described through speed","meaning":"透過速度來形容","examples":[{"en":"Hong Kong is often described through speed.","zh":"香港常被透過速度來形容。"},{"en":"Described through speed means explained by focusing on fast movement, fast work, and a hurried lifestyle.","zh":"Described through speed 指用快速移動、快速工作和匆忙生活方式來解釋某地。"},{"en":"A city may be described through speed if people talk mainly about its trains, offices, and busy streets.","zh":"如果人們主要談一個城市的火車、辦公室和繁忙街道，它可能會被透過速度來形容。"},{"en":"When Hong Kong is described through speed, slower cultural traditions may be overlooked.","zh":"當香港被透過速度來形容時，較慢的文化傳統可能被忽略。"},{"en":"This phrase shows how one image can shape the way we understand a place.","zh":"這個短語顯示一種形象如何影響我們理解一個地方。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"fast deals","meaning":"快速交易","examples":[{"en":"Hong Kong is often described through fast trains, fast service, fast deals, and fast lives.","zh":"香港常被透過快車、快速服務、快速交易和快速生活來形容。"},{"en":"Fast deals are business agreements or transactions made quickly.","zh":"Fast deals 指很快完成的商業協議或交易。"},{"en":"In a busy market, fast deals happen when sellers and buyers decide quickly.","zh":"在繁忙市場中，買賣雙方快速決定時，就會出現快速交易。"},{"en":"A city known for fast deals may seem efficient but also stressful.","zh":"以快速交易聞名的城市可能顯得有效率，但也有壓力。"},{"en":"This phrase helps describe a commercial world that moves at high speed.","zh":"這個短語幫助描述高速運作的商業世界。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"another Hong Kong","meaning":"另一個香港","examples":[{"en":"The performance revealed another Hong Kong.","zh":"這場表演揭示了另一個香港。"},{"en":"Another Hong Kong means a different side of Hong Kong that is less obvious than the usual image.","zh":"Another Hong Kong 指香港較不明顯、不同於常見形象的另一面。"},{"en":"A walk through old neighbourhoods can reveal another Hong Kong beyond skyscrapers.","zh":"走過舊社區可以揭示摩天大廈以外的另一個香港。"},{"en":"Cultural performances show another Hong Kong by highlighting patience, memory, and tradition.","zh":"文化表演透過突出耐性、記憶和傳統，展示另一個香港。"},{"en":"This phrase is useful when a place has more than one identity.","zh":"當一個地方有多重身份時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"patient, disciplined, symbolic and deeply rooted","meaning":"有耐性、有紀律、富象徵性而且根基深厚","examples":[{"en":"The performance revealed a Hong Kong that was patient, disciplined, symbolic, and deeply rooted.","zh":"這場表演揭示了一個有耐性、有紀律、富象徵性而且根基深厚的香港。"},{"en":"Patient, disciplined, symbolic and deeply rooted describes a culture that values time, control, meaning, and strong tradition.","zh":"Patient, disciplined, symbolic and deeply rooted 描述一種重視時間、控制、意義和深厚傳統的文化。"},{"en":"A ceremony can feel patient, disciplined, symbolic and deeply rooted when every action has meaning.","zh":"當每個動作都有意義，典禮可以顯得有耐性、有紀律、富象徵性而且根基深厚。"},{"en":"Such qualities contrast with a city image based only on speed and business.","zh":"這些特質與只建基於速度和商業的城市形象形成對比。"},{"en":"This phrase is useful for describing a mature cultural tradition.","zh":"這個短語適合描述成熟的文化傳統。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"deeply rooted","meaning":"根基深厚","examples":[{"en":"Chinese opera feels deeply rooted in culture.","zh":"中國戲曲感覺根基深厚，深植於文化之中。"},{"en":"Deeply rooted means strongly connected to history, tradition, or long-held values.","zh":"Deeply rooted 指與歷史、傳統或長久價值有強烈連繫。"},{"en":"A festival is deeply rooted when families have practised it for generations.","zh":"如果家庭幾代人都實踐某個節日，它就是根基深厚的。"},{"en":"Local food can be deeply rooted in climate, farming, and family memory.","zh":"本地食物可以深深扎根於氣候、農業和家庭記憶。"},{"en":"This phrase shows that something is not shallow or newly invented.","zh":"這個短語顯示某事物不是膚淺或新近才發明。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"far from being","meaning":"絕不是","examples":[{"en":"Far from being old-fashioned, Chinese opera felt alive.","zh":"中國戲曲絕不是老套，而是充滿生命力。"},{"en":"Far from being means not at all what people may wrongly think it is.","zh":"Far from being 指完全不是人們可能錯誤以為的那樣。"},{"en":"Far from being lazy, the quiet student worked carefully every night.","zh":"那位安靜學生絕不是懶惰，而是每晚都細心工作。"},{"en":"Far from being useless, old stories can teach modern people about courage and loss.","zh":"古老故事絕不是沒用，它們可以教現代人勇氣和失去。"},{"en":"This phrase strongly corrects a mistaken impression.","zh":"這個短語有力地糾正錯誤印象。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"an old-fashioned performance","meaning":"老套的表演","examples":[{"en":"Chinese opera is far from being an old-fashioned performance for specialists.","zh":"中國戲曲絕不是只給專家看的老套表演。"},{"en":"An old-fashioned performance is a show that seems outdated or only connected to the past.","zh":"An old-fashioned performance 指看似過時或只與過去有關的表演。"},{"en":"Some people wrongly see traditional theatre as an old-fashioned performance before watching it closely.","zh":"有些人在細看之前，會錯誤地把傳統劇場看成老套的表演。"},{"en":"A performance stops feeling old-fashioned when audiences understand its living emotions.","zh":"當觀眾理解其中活生生的情感，表演就不再顯得老套。"},{"en":"This phrase is often used when discussing whether tradition still matters today.","zh":"這個短語常用來討論傳統在今天是否仍有意義。"}],"source":"2020 Q9.pdf","sourcePage":11},{"front":"specialists","meaning":"專家；行家","examples":[{"en":"Chinese opera is not only for specialists.","zh":"中國戲曲不只是給專家欣賞。"},{"en":"Specialists are people with deep knowledge or skill in a particular subject.","zh":"Specialists 指在某個課題上有深厚知識或技能的人。"},{"en":"Medical specialists understand problems that general doctors may not treat every day.","zh":"醫學專家理解普通醫生不一定每天處理的問題。"},{"en":"If an art form is explained clearly, it does not have to belong only to specialists.","zh":"如果一種藝術形式被清楚解釋，它就不必只屬於專家。"},{"en":"This word helps contrast experts with ordinary beginners.","zh":"這個詞幫助對比專家和普通初學者。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"in my eyes","meaning":"在我眼中","examples":[{"en":"Chinese opera became, in my eyes, a living conversation between past and present.","zh":"在我眼中，中國戲曲變成過去與現在之間一場有生命力的對話。"},{"en":"In my eyes means in my opinion or from my personal point of view.","zh":"In my eyes 指在我看來，或從我的個人角度而言。"},{"en":"In my eyes, a good teacher is someone who makes students feel brave enough to ask questions.","zh":"在我眼中，好老師是令人有勇氣提問的人。"},{"en":"A tradition may become more valuable in my eyes after I understand its meaning.","zh":"當我理解傳統的意義後，它在我眼中可能變得更有價值。"},{"en":"This phrase clearly marks a personal judgement.","zh":"這個短語清楚標示個人判斷。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"a living conversation","meaning":"有生命力的對話","examples":[{"en":"Chinese opera became a living conversation between past and present.","zh":"中國戲曲變成過去與現在之間一場有生命力的對話。"},{"en":"A living conversation is an active exchange of meaning that still matters now.","zh":"A living conversation 指仍在當下有意義的活躍交流。"},{"en":"A festival becomes a living conversation when young people add new ideas while respecting old customs.","zh":"當年輕人加入新想法同時尊重舊習俗，節日就成為有生命力的對話。"},{"en":"Art can be a living conversation because each generation understands it differently.","zh":"藝術可以是有生命力的對話，因為每一代人都會有不同理解。"},{"en":"This phrase shows tradition as alive, not frozen.","zh":"這個短語把傳統呈現為活的，而不是凍結的。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"between past and present","meaning":"在過去與現在之間","examples":[{"en":"Chinese opera became a living conversation between past and present.","zh":"中國戲曲變成過去與現在之間一場有生命力的對話。"},{"en":"Between past and present means connecting old history or tradition with life today.","zh":"Between past and present 指把舊歷史或傳統與今天生活連接起來。"},{"en":"A restored market creates a link between past and present when old shops serve modern customers.","zh":"當修復後的街市讓舊店服務現代顧客，它就在過去與現在之間建立連繫。"},{"en":"Music can stand between past and present by using traditional instruments in new songs.","zh":"音樂可以透過在新歌中使用傳統樂器，站在過去與現在之間。"},{"en":"This phrase is useful when old and new meanings meet.","zh":"當新舊意義相遇時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"a resounding yes","meaning":"非常肯定的「是」","examples":[{"en":"My answer is a resounding yes.","zh":"我的答案是非常肯定的「是」。"},{"en":"A resounding yes means a very strong, clear, and confident agreement.","zh":"A resounding yes 指非常強烈、清楚和有信心的同意。"},{"en":"If someone asks whether students need real examples, my answer is a resounding yes.","zh":"如果有人問學生是否需要真實例子，我的答案是非常肯定的「是」。"},{"en":"After the successful school concert, the principal gave a resounding yes to holding it again.","zh":"學校音樂會成功後，校長非常肯定地同意再次舉辦。"},{"en":"This phrase is stronger than simply saying “yes.”","zh":"這個短語比簡單說 “yes” 更強烈。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"arrive early","meaning":"早點到達","examples":[{"en":"Visitors should arrive early and read the story summary.","zh":"訪客應該早點到達並閱讀故事簡介。"},{"en":"To arrive early means to reach a place before the required or expected time.","zh":"To arrive early 指在要求或預期時間之前到達某地。"},{"en":"Students should arrive early for an exam so they can settle down calmly.","zh":"學生考試時應早點到達，讓自己平靜下來。"},{"en":"Visitors who arrive early have time to find seats, read signs, and understand the setting.","zh":"早點到達的訪客有時間找座位、看指示和了解環境。"},{"en":"This phrase is practical advice for avoiding stress before an event.","zh":"這個短語是避免活動前壓力的實用建議。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"read the story summary","meaning":"閱讀故事簡介","examples":[{"en":"Visitors should read the story summary before the performance.","zh":"訪客應在表演前閱讀故事簡介。"},{"en":"To read the story summary means to look at a short explanation of the plot before watching the full work.","zh":"To read the story summary 指在觀看完整作品前，閱讀劇情的簡短說明。"},{"en":"Students read the story summary so they know who the main characters are.","zh":"學生閱讀故事簡介，以便知道主要角色是誰。"},{"en":"Reading the story summary can reduce confusion when the language or style is unfamiliar.","zh":"當語言或風格陌生時，閱讀故事簡介可以減少困惑。"},{"en":"This phrase is useful advice for enjoying plays, operas, and films.","zh":"這個短語是欣賞戲劇、歌劇和電影的實用建議。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"as well as","meaning":"以及","examples":[{"en":"Watch the audience as well as the stage.","zh":"觀看舞台，也要觀看觀眾。"},{"en":"As well as means in addition to, showing that two things should both receive attention.","zh":"As well as 指以及，表示兩件事都應受到注意。"},{"en":"Students should check grammar as well as ideas when they revise an essay.","zh":"學生修改文章時，應檢查文法以及內容。"},{"en":"In a theatre, watching the audience as well as the stage can show how people respond to culture.","zh":"在劇院中，觀看觀眾以及舞台，可以顯示人們如何回應文化。"},{"en":"This phrase adds another important item without replacing the first.","zh":"這個短語加入另一個重要項目，而不是取代第一個。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"let yourself be confused","meaning":"容許自己困惑","examples":[{"en":"Let yourself be confused for a while.","zh":"容許自己困惑一會兒。"},{"en":"To let yourself be confused means to accept not understanding everything immediately.","zh":"To let yourself be confused 指接受自己不能立刻理解所有事情。"},{"en":"When learning a new language, let yourself be confused before the pattern becomes clear.","zh":"學習新語言時，在規律變清楚之前，容許自己困惑。"},{"en":"People learn better when they let themselves be confused instead of giving up too soon.","zh":"人們容許自己困惑，而不是太快放棄時，會學得更好。"},{"en":"This phrase encourages patience with uncertainty.","zh":"這個短語鼓勵人對不確定保持耐性。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"for a while","meaning":"一會兒","examples":[{"en":"Let yourself be confused for a while.","zh":"容許自己困惑一會兒。"},{"en":"For a while means for a short or limited period of time.","zh":"For a while 指在一小段或有限的時間內。"},{"en":"After moving to a new school, I felt lost for a while.","zh":"搬到新學校後，我迷惘了一會兒。"},{"en":"Feeling confused for a while is normal when the subject is new.","zh":"當課題很新時，困惑一會兒是正常的。"},{"en":"This phrase suggests the situation will not necessarily last forever.","zh":"這個短語暗示情況不一定會永遠持續。"}],"source":"2020 Q9.pdf","sourcePage":12},{"front":"broaden the mind","meaning":"擴闊眼界","examples":[{"en":"Travel broadens the mind.","zh":"旅遊擴闊眼界。"},{"en":"To broaden the mind means to help someone think more openly and understand more kinds of people or ideas.","zh":"To broaden the mind 指幫助人更開放地思考，並理解更多不同的人或想法。"},{"en":"Reading books from different countries can broaden the mind without leaving home.","zh":"閱讀不同國家的書，即使不離家也可以擴闊眼界。"},{"en":"Travel broadens the mind when it challenges old assumptions instead of only providing photos.","zh":"當旅遊挑戰舊有想法，而不只是提供照片時，它會擴闊眼界。"},{"en":"This phrase connects experience with wider understanding.","zh":"這個短語把經驗和更廣闊的理解連接起來。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"not because…, but because…","meaning":"不是因為……而是因為……","examples":[{"en":"Travel broadens the mind not because every place feels familiar, but because some places challenge us.","zh":"旅遊擴闊眼界，不是因為每個地方都令人熟悉，而是因為有些地方會挑戰我們。"},{"en":"“Not because…, but because…” corrects one possible reason and gives the real reason.","zh":"“Not because…, but because…” 會修正一個可能原因，並給出真正原因。"},{"en":"Students improve not because exams are easy, but because practice makes their thinking clearer.","zh":"學生進步不是因為考試容易，而是因為練習令思考更清晰。"},{"en":"A tradition matters not because it is old, but because people still find meaning in it.","zh":"傳統重要不是因為它古老，而是因為人們仍在其中找到意義。"},{"en":"This structure is useful for explaining contrast in an argument.","zh":"這個結構適合在論證中解釋對比。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"immediately feels familiar","meaning":"立即令人感到熟悉","examples":[{"en":"Not every place immediately feels familiar.","zh":"不是每個地方都立即令人感到熟悉。"},{"en":"Immediately feels familiar means seems comfortable, easy to understand, or known right away.","zh":"Immediately feels familiar 指立刻感到舒服、容易理解或似曾相識。"},{"en":"A new neighbourhood may not immediately feel familiar, even if people there are friendly.","zh":"新社區即使人們友善，也未必立即令人感到熟悉。"},{"en":"Art from another culture may not immediately feel familiar because its signs are different.","zh":"另一種文化的藝術可能不會立即令人感到熟悉，因為其符號不同。"},{"en":"This phrase helps explain why patience is needed with new experiences.","zh":"這個短語幫助解釋為何新經歷需要耐性。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"question what we thought we knew","meaning":"質疑自己原本以為知道的事","examples":[{"en":"Some places make us question what we thought we knew.","zh":"有些地方會令我們質疑自己原本以為知道的事。"},{"en":"To question what we thought we knew means to rethink beliefs we once felt sure about.","zh":"To question what we thought we knew 指重新思考自己曾經很肯定的信念。"},{"en":"Meeting people from another background can make us question what we thought we knew about success.","zh":"遇見不同背景的人，可以令我們質疑自己原本以為知道的成功。"},{"en":"Travel can make people question what they thought they knew about comfort, family, or time.","zh":"旅遊可以令人質疑自己原本以為知道的舒適、家庭或時間。"},{"en":"This phrase describes deep learning through surprise.","zh":"這個短語描述透過驚訝得到的深層學習。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"expecting to endure","meaning":"預期要忍受","examples":[{"en":"I entered the theatre expecting to endure a cultural duty.","zh":"我走進劇院時，預期要忍受一項文化責任。"},{"en":"Expecting to endure means thinking you will have to suffer through something unpleasant or boring.","zh":"Expecting to endure 指以為自己要忍受某件不愉快或沉悶的事。"},{"en":"I went to the lecture expecting to endure two dull hours, but it was surprisingly useful.","zh":"我去聽講座時預期要忍受兩小時沉悶內容，但結果意外地有用。"},{"en":"People may expect to endure an unfamiliar tradition before they understand its beauty.","zh":"人們在理解陌生傳統的美之前，可能預期要忍受它。"},{"en":"This phrase shows negative expectation before an experience begins.","zh":"這個短語顯示經歷開始前的負面預期。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"a cultural duty","meaning":"一項文化責任","examples":[{"en":"I entered the theatre expecting to endure a cultural duty.","zh":"我走進劇院時，預期要忍受一項文化責任。"},{"en":"A cultural duty is something someone feels they should do to respect or experience culture, even if they do not expect to enjoy it.","zh":"A cultural duty 指某人覺得為了尊重或體驗文化而應該做的事，即使不期待享受。"},{"en":"A student may visit a historical site as a cultural duty before realising it is interesting.","zh":"學生可能把參觀歷史遺址當成一項文化責任，之後才發現它很有趣。"},{"en":"If art is treated only as a cultural duty, people may miss its emotional power.","zh":"如果藝術只被當成一項文化責任，人們可能錯過它的情感力量。"},{"en":"This phrase shows the difference between obligation and real enjoyment.","zh":"這個短語顯示義務和真正享受之間的分別。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"carrying a tune I could not sing","meaning":"帶着一段自己唱不出的旋律離開","examples":[{"en":"I left carrying a tune I could not sing.","zh":"我帶着一段自己唱不出的旋律離開。"},{"en":"Carrying a tune I could not sing means leaving with music remembered emotionally, even though I could not reproduce it.","zh":"Carrying a tune I could not sing 指帶着情感上記得的音樂離開，即使自己不能唱出來。"},{"en":"After the concert, I left carrying a tune I could not sing but could still feel.","zh":"音樂會後，我帶着一段自己唱不出的旋律離開，但仍能感受到它。"},{"en":"A song can stay with someone even if they do not know the words or melody exactly.","zh":"即使不知道歌詞或旋律，歌曲仍可以留在人心中。"},{"en":"This phrase shows the lasting emotional trace of music.","zh":"這個短語顯示音樂留下的持久情感痕跡。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"fully retell","meaning":"完整複述","examples":[{"en":"I left with a story I could not fully retell.","zh":"我帶着一個自己無法完整複述的故事離開。"},{"en":"To fully retell a story means to explain all its events, details, and meanings completely.","zh":"To fully retell a story 指完整解釋故事所有事件、細節和意義。"},{"en":"I enjoyed the film, but I could not fully retell the plot because it was complex.","zh":"我喜歡那部電影，但因劇情複雜，無法完整複述。"},{"en":"Some cultural experiences are powerful even when visitors cannot fully retell them afterwards.","zh":"有些文化經歷即使訪客之後不能完整複述，仍然很有力量。"},{"en":"This phrase shows partial understanding without denying emotional impact.","zh":"這個短語顯示部分理解，但不否認情感影響。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"a respect I could not shake off","meaning":"一份揮之不去的敬意","examples":[{"en":"I left with a respect I could not shake off.","zh":"我帶着一份揮之不去的敬意離開。"},{"en":"A respect I could not shake off means a strong admiration that stayed with me after the experience.","zh":"A respect I could not shake off 指經歷後仍留在心中的強烈敬意。"},{"en":"After seeing the nurses work all night, I felt a respect I could not shake off.","zh":"看見護士通宵工作後，我感到一份揮之不去的敬意。"},{"en":"A powerful performance can leave viewers with a respect they cannot easily forget.","zh":"有力的表演可以令觀眾留下難以忘記的敬意。"},{"en":"This phrase shows that admiration can remain even after confusion fades.","zh":"這個短語顯示敬意即使在困惑消散後仍能留下。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"shake off","meaning":"擺脫","examples":[{"en":"I could not shake off the respect I felt after the performance.","zh":"表演後，我無法擺脫心中的敬意。"},{"en":"To shake off something means to get rid of a feeling, thought, or influence.","zh":"To shake off something 指擺脫某種感覺、想法或影響。"},{"en":"I could not shake off the sadness after hearing my friend’s story.","zh":"聽完朋友的故事後，我無法擺脫那種悲傷。"},{"en":"A person may try to shake off nervousness before speaking on stage.","zh":"一個人在上台說話前，可能會嘗試擺脫緊張。"},{"en":"This phrase is useful when a feeling stays longer than expected.","zh":"當某種感覺停留得比預期更久時，這個短語很有用。"}],"source":"2020 Q9.pdf","sourcePage":13},{"front":"do the experience justice","meaning":"充分表達那段經歷","examples":[{"en":"No words can do the experience justice.","zh":"沒有文字能充分表達那段經歷。"},{"en":"To do the experience justice means to describe it well enough to show its true value or power.","zh":"To do the experience justice 指把一段經歷描述得足夠好，以顯示其真正價值或力量。"},{"en":"A photograph cannot always do a mountain sunrise justice.","zh":"一張照片不一定能充分表達山上日出的美。"},{"en":"A short summary may not do the performance justice because it misses sound, movement, and atmosphere.","zh":"簡短摘要可能無法充分表達那場表演，因為它錯過聲音、動作和氣氛。"},{"en":"This phrase admits that real experience can be richer than description.","zh":"這個短語承認真實經歷可以比描述更豐富。"}],"source":"2020 Q9.pdf","sourcePage":14},{"front":"see it in person","meaning":"親身觀看","examples":[{"en":"Perhaps that is why you should see it in person.","zh":"或許這正是你應該親身觀看它的原因。"},{"en":"To see it in person means to experience something directly with your own eyes, not through photos, videos, or descriptions.","zh":"To see it in person 指親眼直接經歷某事，而不是透過照片、影片或描述。"},{"en":"You should see the old theatre in person because pictures cannot show its atmosphere fully.","zh":"你應該親身觀看那座舊劇院，因為照片不能完全展示它的氣氛。"},{"en":"Some performances must be seen in person because the sound and audience reaction are part of the experience.","zh":"有些表演必須親身觀看，因為聲音和觀眾反應都是經歷的一部分。"},{"en":"This phrase is often used when direct experience matters more than second-hand information.","zh":"當直接經驗比二手資料更重要時，這個短語常被使用。"}],"source":"2020 Q9.pdf","sourcePage":14}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2020_SEED);
